#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NormalRecoveryAttemptResult {
    #[allow(dead_code)]
    Qualified,
    #[allow(dead_code)]
    Failed,
    #[allow(dead_code)]
    CompletionUnknown,
    Unavailable,
}

type NormalRecoveryAttemptRuntime = Box<
    dyn FnMut(
        DrmDeviceKey,
        crate::kms::owner::lifecycle::RecoveryId,
        crate::kms::owner::lifecycle::TransitionTag<IncarnationId>,
    ) -> NormalRecoveryAttemptResult,
>;

struct RecoveryOpenedDevice {
    device: crate::kms::backend::PlatformInitDevice,
}

type NormalRecoveryDeviceOpener = Box<
    dyn FnMut(
        DrmDeviceKey,
        &std::path::Path,
        IncarnationId,
        crate::kms::owner::lifecycle::LifecycleEpochId,
    ) -> io::Result<RecoveryOpenedDevice>,
>;

struct PendingNormalRecovery {
    recovery_id: crate::kms::owner::lifecycle::RecoveryId,
    transition: crate::kms::owner::lifecycle::TransitionTag<IncarnationId>,
    new_incarnation: IncarnationId,
    probe_epoch: u64,
    clock_probe: Option<crate::kms::owner::clock::ClockKey>,
    rediscovery_complete: bool,
    rediscovery_failed: bool,
}

struct PendingNormalRecoveryHandshake {
    recovery_id: crate::kms::owner::lifecycle::RecoveryId,
    transition: crate::kms::owner::lifecycle::TransitionTag<IncarnationId>,
    new_incarnation: IncarnationId,
    clock_probe_crtc: u32,
    deadline: std::time::Instant,
}

struct QuarantinedNormalRecovery {
    #[allow(dead_code)] // retained for transition-correlated teardown (Task 8)
    transition: crate::kms::owner::lifecycle::TransitionTag<IncarnationId>,
    device: crate::kms::render::platform::KmsDevice,
    #[allow(dead_code)] // retains the old incarnation's service until its barrier
    resource_service: Option<crate::kms::render::resources::ResourceService>,
    cleanup_registry: Option<crate::kms::render::resources::DrmCleanupRegistry>,
}

fn open_normal_recovery_device(
    key: DrmDeviceKey,
    path: &std::path::Path,
    incarnation: IncarnationId,
    lifecycle_epoch: crate::kms::owner::lifecycle::LifecycleEpochId,
) -> io::Result<RecoveryOpenedDevice> {
    let device = crate::kms::backend::open_platform_init_device_for_recovery(
        path,
        incarnation,
        lifecycle_epoch,
        Some(key),
        &[],
    )
    .map_err(|error| match error {
        crate::kms::backend::PlatformDeviceOpenError::DeviceOpen(error)
        | crate::kms::backend::PlatformDeviceOpenError::Initialization(error) => error,
    })?;
    Ok(RecoveryOpenedDevice { device })
}

#[cfg(test)]
struct RealDrmTestSerial {
    state: std::sync::Mutex<RealDrmTestSerialState>,
    wake: std::sync::Condvar,
}

#[cfg(test)]
struct RealDrmTestSerialState {
    owner: Option<std::thread::ThreadId>,
    depth: usize,
}

#[cfg(test)]
static REAL_DRM_TEST_SERIAL: RealDrmTestSerial = RealDrmTestSerial {
    state: std::sync::Mutex::new(RealDrmTestSerialState {
        owner: None,
        depth: 0,
    }),
    wake: std::sync::Condvar::new(),
};

/// A re-entrant process-wide guard for Vulkan test contexts. Re-entrancy is
/// needed because a few tests intentionally keep two live fixtures at once;
/// ownership remains exclusive between test threads.
#[cfg(test)]
struct RealDrmTestGuard;

#[cfg(test)]
impl RealDrmTestSerial {
    fn acquire() -> RealDrmTestGuard {
        let thread = std::thread::current().id();
        let mut state = REAL_DRM_TEST_SERIAL
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        loop {
            match state.owner {
                None => {
                    state.owner = Some(thread);
                    state.depth = 1;
                    return RealDrmTestGuard;
                }
                Some(owner) if owner == thread => {
                    state.depth = state.depth.saturating_add(1);
                    return RealDrmTestGuard;
                }
                Some(_) => {
                    state = REAL_DRM_TEST_SERIAL
                        .wake
                        .wait(state)
                        .unwrap_or_else(std::sync::PoisonError::into_inner);
                }
            }
        }
    }
}

#[cfg(test)]
impl Drop for RealDrmTestGuard {
    fn drop(&mut self) {
        let thread = std::thread::current().id();
        let mut state = REAL_DRM_TEST_SERIAL
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        assert_eq!(
            state.owner,
            Some(thread),
            "real-DRM Vulkan test guard dropped by a non-owner thread"
        );
        assert!(state.depth > 0, "real-DRM Vulkan test guard underflow");
        state.depth -= 1;
        if state.depth == 0 {
            state.owner = None;
            REAL_DRM_TEST_SERIAL.wake.notify_one();
        }
    }
}

/// Acquire the Vulkan test serialization guard for fixtures outside
/// `KmsBackend` that construct their own `VkContext`.
#[cfg(test)]
pub(crate) fn acquire_test_vk_guard() -> impl Drop {
    RealDrmTestSerial::acquire()
}

/// Per-window geometry tracked by v2's scene assembler. Stage 2 plan
/// Risk 3: a parallel `windows` map on `KmsBackend` (NOT on
/// `KmsCore` — v1 doesn't need it). Stage 4 may collapse into
/// `KmsCore.windows` when `WindowState` splits.
///
/// Stage 3f.6 grows `parent`: subwindows record their parent xid so
/// `build_scene` can recurse top-level → descendants with accumulated
/// offsets. `None` marks top-levels (parent is root, not tracked
/// in `windows`). The `bg_pixel` / `bg_pixmap` slots carry
/// per-window background attributes set via
/// `change_subwindow_attributes`; the bg-pixel is painted into
/// storage at allocate + configure resize so freshly-mapped windows
/// have a defined initial colour.
/// See `input_only_pointer_hosts`.
#[derive(Clone, Copy, Debug)]
pub(crate) struct InputOnlyPointerHost {
    window: ResourceId,
    /// Host of the nearest ancestor with a backend window, where the
    /// cursor walk carries on when no InputOnly window on the way up has
    /// a cursor.
    parent_host: u32,
    /// The first cursor set on the InputOnly windows from `window` up to
    /// that ancestor.
    cursor: Option<u32>,
    /// `window`'s parent-relative origin, which `event_relative_coords`
    /// subtracts as it does a backend window's (the core adds it back).
    origin: (i16, i16),
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct WindowGeometry {
    pub(crate) x: i16,
    pub(crate) y: i16,
    pub(crate) width: u16,
    pub(crate) height: u16,
    pub(crate) depth: u8,
    pub(crate) mapped: bool,
    /// Mirror of core viewability, kept by `realize_window_storage` / `release_window_storage`.
    pub(crate) viewable: bool,
    pub(crate) parent: Option<u32>,
    pub(crate) stack_rank: u64,
    pub(crate) bg_pixel: Option<u32>,
    pub(crate) bg_pixmap: Option<u32>,
    /// #133 step 2 (P3) — the window's border width, in pixels, as the
    /// core tree has it. Carried on the wire by `create_subwindow` and
    /// by `HostSubwindowConfig::border_width`; recorded here so the
    /// render side has the same value as `Window::border_width` without
    /// reaching back into resources. Nothing consumes it yet: storage
    /// sizing is step 3 and the ring fill is step 4.
    pub(crate) border_width: u16,
    /// #133 step 2 (P3) — the resolved border source, flattened to
    /// primitives exactly as `bg_pixel` / `bg_pixmap` are, so the
    /// `yserver` crate need not know `resources::BorderSource`. Xorg's
    /// `PixUnion border` + `borderIsPixel` (`include/windowstr.h:146`)
    /// is an either/or, so at most one of these is `Some`: a tile
    /// pixmap wins when it has host storage, otherwise the pixel.
    /// Set from `change_subwindow_attributes` (CWBorderPixmap 0x04 /
    /// CWBorderPixel 0x08), which core forwards both at create time and
    /// on every border-attribute change.
    pub(crate) border_pixel: Option<u32>,
    pub(crate) border_pixmap: Option<u32>,
    /// Stage 5 Phase A — per-window X11 cursor attribute. `None`
    /// means inherit from the parent chain; `Some(xid)` pins a
    /// specific cursor on hover-in. Mutated by `define_cursor` only —
    /// `change_subwindow_attributes` does not decode CWCursor (the
    /// cursor arrives through `Backend::define_cursor`, which core
    /// calls for a CWA cursor change as well).
    pub(crate) cursor: Option<u32>,
}

pub(crate) type WindowsMap = HashMap<u32, WindowGeometry>;

/// [`WindowsMap`] counting its mutable borrows, so a clip computed from
/// it can tell it is still current ([`KmsBackend::subwindow_mode_clip`]).
#[derive(Debug, Default)]
pub(crate) struct TrackedWindows {
    map: WindowsMap,
    generation: u64,
}

impl TrackedWindows {
    pub(crate) fn generation(&self) -> u64 {
        self.generation
    }
}

impl std::ops::Deref for TrackedWindows {
    type Target = WindowsMap;
    fn deref(&self) -> &WindowsMap {
        &self.map
    }
}

impl<'a> IntoIterator for &'a TrackedWindows {
    type Item = (&'a u32, &'a WindowGeometry);
    type IntoIter = std::collections::hash_map::Iter<'a, u32, WindowGeometry>;
    fn into_iter(self) -> Self::IntoIter {
        self.map.iter()
    }
}

impl std::ops::DerefMut for TrackedWindows {
    fn deref_mut(&mut self) -> &mut WindowsMap {
        self.generation = self.generation.wrapping_add(1);
        &mut self.map
    }
}

/// Test-only (#133): one scene participant's placement — its host xid and
/// its output-local rects as `(x, y, w, h)`. Named so
/// `KmsBackend::scene_participant_places_for_tests` has a simple signature.
pub type ScenePlacement = (u32, Vec<(i32, i32, u32, u32)>, Vec<(i32, i32, u32, u32)>);

/// #133 step 3 (P4) — the observable shape of a resolved paint target,
/// for `KmsBackend::paint_target_shape_for_tests`: the content
/// translation into storage coordinates, the content clip as
/// `(x, y, w, h)` in storage coordinates (`None` = the whole storage),
/// and whether the resolved chain carries a border clip at all (the
/// direct-scanout gate's input, 3.5).
pub type PaintTargetShape = ((i32, i32), Option<(i32, i32, u32, u32)>, bool);

/// #133 step 3 (3.3) — a window's storage extent: the bordered extent
/// `(w + 2bw) x (h + 2bw)`, mirroring Xorg's `compAllocPixmap`
/// (`composite/compalloc.c:610`, `w + (bw << 1)`), with the client
/// content living at `(bw, bw)` inside it. Collapses to exactly
/// `(w, h)` at `bw == 0`.
fn bordered_storage_extent(width: u16, height: u16, border_width: u16) -> (u32, u32) {
    let bw2 = u32::from(border_width).saturating_mul(2);
    (
        u32::from(width).saturating_add(bw2).max(1),
        u32::from(height).saturating_add(bw2).max(1),
    )
}

/// #133 step 6 (6.2) — the content copy a border-width change needs:
/// `(src_rect, dst_pos)` in STORAGE coordinates, or `None` when there
/// is nothing to move.
///
/// The source is the OLD content rect, derived entirely from the old
/// allocation (`extent − 2·offset` is the content extent it was
/// allocated for), intersected with the new content extent — Xorg
/// copies the same intersection, since `compCopyWindow` clips the
/// recovered region to `pWin->borderClip`
/// (`composite/compwindow.c:515`). The destination is the new content
/// origin `(bw, bw)`, so a pixel the client drew at content `(cx, cy)`
/// is still at content `(cx, cy)` afterwards — the whole point of the
/// migration.
///
/// `None` when either content rect is empty, which is the only case
/// with nothing to move. Whether a copy is WANTED at all is the
/// caller's decision (`LeafContent`), not this function's.
fn migrated_content_copy(
    old_extent: ash::vk::Extent2D,
    old_offset: i32,
    new_w: u16,
    new_h: u16,
    new_offset: i32,
) -> Option<(ash::vk::Rect2D, ash::vk::Offset2D)> {
    let old_bw2 = u32::try_from(old_offset).unwrap_or(0).saturating_mul(2);
    let old_content_w = old_extent.width.saturating_sub(old_bw2);
    let old_content_h = old_extent.height.saturating_sub(old_bw2);
    let copy_w = old_content_w.min(u32::from(new_w));
    let copy_h = old_content_h.min(u32::from(new_h));
    if copy_w == 0 || copy_h == 0 {
        return None;
    }
    Some((
        ash::vk::Rect2D {
            offset: ash::vk::Offset2D {
                x: old_offset,
                y: old_offset,
            },
            extent: ash::vk::Extent2D {
                width: copy_w,
                height: copy_h,
            },
        },
        ash::vk::Offset2D {
            x: new_offset,
            y: new_offset,
        },
    ))
}

/// A moving window's place in an ancestor's shared redirect backing,
/// taken before the configure: see
/// [`KmsBackend::shared_backing_move_source`].
struct SharedBackingMoveSource {
    /// Where the window drew before the move.
    target: PaintTarget,
    /// Higher siblings over the window at its OLD position, in its
    /// local content space: those pixels are theirs, not the window's.
    occluders: Vec<ash::vk::Rect2D>,
}

/// Cooking state owned by one temporarily floating keyboard slave. Its XKB
/// state and duplicate guard must not share the master keyboard's state.
struct FloatingKeyboardState {
    xkb_state: crate::kms::core::XkbState,
    down_keys: HashSet<u8>,
    lock_filter_priv_by_key: HashMap<u8, LockFilterPriv>,
    locked_group: u8,
}

/// The XkbFilterLockState data captured for a held LockMods key. Xorg stores
/// both the pre-press locked bits and the up action; `LockNoUnlock` suppresses
/// clearing those bits when the detached key is released.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct LockFilterPriv {
    pre_press_locked_mods: u32,
    no_unlock: bool,
}

/// XkbSA_LockNoUnlock (`LockMods(..., affect=lock)`).
const XKB_SA_LOCK_NO_UNLOCK: u8 = 0x02;

/// #133 step 6 (P8) — what [`KmsBackend::sync_window_leaf_storage`]
/// does with the pixels a window's leaf storage already holds when it
/// has to reallocate.
///
/// The two callers want opposite things and the difference is not an
/// optimisation:
///
/// - A **border-width** change must preserve the client's drawable:
///   nothing about the client's content changed, only where it sits
///   inside the storage. Reallocating and background-filling would
///   erase an otherwise untouched window — [`Self::Migrate`].
/// - A **width/height** resize preserves it too, but only for a window
///   with NO background: X11 discards the contents of a default-gravity
///   window and tiles it with its background, "if no background is
///   defined, the existing screen contents are not altered"
///   (ForgetGravity, ChangeWindowAttributes), which Xorg implements by
///   returning from the paint without touching a pixel
///   (`mi/miexpose.c:438-440`). A window WITH a background is tiled, so
///   it stays on [`Self::Discard`] — see `configure_subwindow` for the
///   #143 measurement and for why a non-Forget `bit_gravity` cannot be
///   honoured here yet (`project_resize_black_window_storage`).
/// - **Unredirect** discards, because the leaf has been stale since the
///   route was installed and `restore_leaves_from_backing` puts the
///   compositor's real pixels back on top of the fresh storage —
///   [`Self::Discard`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum LeafContent {
    /// Reallocate and initialise from the background; copy nothing
    /// forward.
    Discard,
    /// Retain the old storage across the reallocation and copy the
    /// intersection of the old and new CONTENT rects into the new one,
    /// from `old_bw` to `new_bw`. Xorg keeps the old pixmap for exactly
    /// this reason — "leaving the old pixmap in cw->pOldPixmap so bits
    /// can be recovered" (`composite/compalloc.c:676-678`) — and
    /// recovers them with a `CopyArea` in `compCopyWindow`
    /// (`composite/compwindow.c:501-540`).
    Migrate,
}

/// #133 step 4 (P5) — the border ring, as up to four disjoint rects:
/// `outer − inner`, i.e. exactly what Xorg paints for `PW_BORDER`
/// (`RegionSubtract(&exposed, &pWin->borderClip, &pWin->winSize)`,
/// `dix/window.c:1586` and `composite/compwindow.c:114`).
///
/// Both rects are in the SAME frame (the window's backing/storage
/// space) and `inner` must be contained in `outer`; the caller builds
/// `outer` by expanding `inner` by the border width. The split is
/// full-width top and bottom bands plus the two side bars between
/// them, which tiles the annulus exactly once — a tiled fill must not
/// paint a corner twice, since `PictOp Src` is idempotent but the
/// damage/submit accounting is not.
///
/// Empty bands are dropped, so `inner == outer` (`bw == 0`) yields an
/// empty vector and no caller ever submits anything.
fn border_ring_rects(outer: vk::Rect2D, inner: vk::Rect2D) -> Vec<vk::Rect2D> {
    let rect = |x: i32, y: i32, w: i32, h: i32| {
        (w > 0 && h > 0).then(|| vk::Rect2D {
            offset: vk::Offset2D { x, y },
            extent: vk::Extent2D {
                width: u32::try_from(w).unwrap_or(0),
                height: u32::try_from(h).unwrap_or(0),
            },
        })
    };
    let ox = outer.offset.x;
    let oy = outer.offset.y;
    let ox1 = ox.saturating_add_unsigned(outer.extent.width);
    let oy1 = oy.saturating_add_unsigned(outer.extent.height);
    let ix = inner.offset.x;
    let iy = inner.offset.y;
    let ix1 = ix.saturating_add_unsigned(inner.extent.width);
    let iy1 = iy.saturating_add_unsigned(inner.extent.height);
    [
        // Top band, full outer width.
        rect(ox, oy, ox1 - ox, iy - oy),
        // Bottom band, full outer width.
        rect(ox, iy1, ox1 - ox, oy1 - iy1),
        // Left bar, between the two bands.
        rect(ox, iy, ix - ox, iy1 - iy),
        // Right bar, between the two bands.
        rect(ix1, iy, ox1 - ix1, iy1 - iy),
    ]
    .into_iter()
    .flatten()
    .collect()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScanoutM0Target {
    Cow,
    CowDescendant,
    Unredirected,
    Other,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScanoutM0Coverage {
    Root,
    Output(usize),
    None,
}

fn scanout_m2_is_authoritative_root(target: ScanoutM0Target, root_coverage: bool) -> bool {
    matches!(
        target,
        ScanoutM0Target::Cow | ScanoutM0Target::CowDescendant | ScanoutM0Target::Unredirected
    ) && root_coverage
}

#[allow(clippy::too_many_arguments)]
fn scanout_direct_eligible(
    scanout_allowed: bool,
    kms_outputs_active: bool,
    cursor_hw: bool,
    root_overlay_empty: bool,
    authoritative_root: bool,
    unbordered: bool,
    x_off: i16,
    y_off: i16,
    valid_region_xid: u32,
) -> bool {
    scanout_allowed
        && kms_outputs_active
        && cursor_hw
        && root_overlay_empty
        && authoritative_root
        && unbordered
        && x_off == 0
        && y_off == 0
        && valid_region_xid == 0
    // explicit_sync and update_region/update_is_full are intentionally NOT
    // consulted: an authoritative-root (fullscreen) present replaces the
    // whole scanout buffer, and the acquire fence is already awaited
    // (source_ready) before try_present_direct runs.
    //
    // #133 step 3 (3.5) — `unbordered` is a HARD phase-1 rule: the flip
    // path assumes the presented content starts at storage `(0, 0)`, and
    // a bordered window's storage starts `bw` earlier (its OUTER origin,
    // per `compAllocPixmap`, `composite/compalloc.c:610`). It must land
    // with the storage-layout change rather than after it, or a bordered
    // window can be flipped with a `bw`-shifted source. It costs nothing
    // on real desktops (every WM in the current smoke set uses
    // `border_width = 0`). Lifting it later needs the bordered storage +
    // source crop proven valid.
}

/// Whether no Bounding or Clip shape on `leaf_xid` or any ancestor up to the
/// root (the COW included) removes part of the `root` rect.
///
/// Xorg flips a Present only when the window's `clipList` equals the root's
/// `winSize` (`present/present_scmd.c:102`), and every shape in the chain
/// narrows that clip list (`SetWinSize`, `dix/window.c:1713`, propagated to
/// descendants by `miComputeClips`). Muffin's lock screen is the load-bearing
/// case: it shapes the COW to an EMPTY region and unredirects the locker, so
/// its stage's Presents are clipped to nothing and the locker below shows.
/// Shape rects are relative to each window's content origin.
fn direct_shape_chain_covers_root(
    windows: &WindowsMap,
    root_window_id: u32,
    shape_bounding: &HashMap<u32, Vec<xfixes::RegionRect>>,
    shape_clip: &HashMap<u32, Vec<xfixes::RegionRect>>,
    leaf_xid: u32,
    root: (u32, u32),
) -> bool {
    use crate::kms::render::region::Region;

    let mut chain = Vec::new();
    let mut xid = leaf_xid;
    // Resource validation prevents cycles in production; stay bounded anyway.
    for _ in 0..=windows.len() {
        let Some(geometry) = windows.get(&xid) else {
            return false;
        };
        let bw = i32::from(geometry.border_width);
        chain.push((xid, i32::from(geometry.x) + bw, i32::from(geometry.y) + bw));
        match geometry.parent {
            None => break,
            Some(parent) if parent == root_window_id => break,
            Some(parent) => xid = parent,
        }
    }
    let root_rect = vk::Rect2D {
        offset: vk::Offset2D::default(),
        extent: vk::Extent2D {
            width: root.0,
            height: root.1,
        },
    };
    let (mut abs_x, mut abs_y) = (0, 0);
    for &(xid, x, y) in chain.iter().rev() {
        abs_x += x;
        abs_y += y;
        for shapes in [shape_bounding, shape_clip] {
            let Some(rects) = shapes.get(&xid) else {
                continue;
            };
            // Subtract rect by rect: a capped remainder only grows, so the
            // answer can err towards "not covered", never towards a flip.
            let mut uncovered = Region::from_rect(root_rect);
            for rect in rects {
                uncovered.subtract(&Region::from_rect(vk::Rect2D {
                    offset: vk::Offset2D {
                        x: abs_x + i32::from(rect.x),
                        y: abs_y + i32::from(rect.y),
                    },
                    extent: vk::Extent2D {
                        width: u32::from(rect.width),
                        height: u32::from(rect.height),
                    },
                }));
            }
            if !uncovered.is_empty() {
                return false;
            }
        }
    }
    true
}

/// Which retained direct frame a single CRTC is scanning out.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DirectFrameSlot {
    Pending,
    Current,
}

/// Decide, per output, whether a CRTC is displaying a directly-flipped client
/// buffer and which retained frame it is — or the compositor's own scanout BO.
///
/// A direct transaction is submitted to every CRTC at once
/// (`submit_direct_frame` builds one plane state per `platform.outputs`
/// entry), but retirement and the composed unflip are per-CRTC, so the two
/// transitions leave a window where outputs disagree:
///
/// * `pending_awaiting` holds the outputs whose flip has NOT retired yet.
///   Those still show the predecessor (`current`, or the composed pool if this
///   is the first direct frame); the rest already show `pending`.
/// * `unflip_awaiting` holds the outputs whose composed replacement has NOT
///   retired yet. Those are still direct; an output missing from a non-empty
///   set has already been handed back to its pool BO. The set is emptied when
///   the unflip fully retires, which also drops both frames.
fn direct_frame_slot_on_output(
    output_idx: usize,
    pending_awaiting: Option<&HashSet<usize>>,
    current_present: bool,
    unflip_awaiting: &HashSet<usize>,
) -> Option<DirectFrameSlot> {
    if !unflip_awaiting.is_empty() && !unflip_awaiting.contains(&output_idx) {
        return None;
    }
    if pending_awaiting.is_some_and(|awaiting| !awaiting.contains(&output_idx)) {
        return Some(DirectFrameSlot::Pending);
    }
    current_present.then_some(DirectFrameSlot::Current)
}

fn phase_b_flip_in_flight_for_scheduler(
    scene_flip_pending: bool,
    direct_flip_pending: bool,
    unflip_pending: bool,
) -> bool {
    scene_flip_pending || direct_flip_pending || unflip_pending
}

fn scanout_m1_probe_eligible(
    scanout_allowed: bool,
    kms_outputs_active: bool,
    cursor_hw: bool,
    root_overlay_empty: bool,
    target: ScanoutM0Target,
    coverage: ScanoutM0Coverage,
    x_off: i16,
    y_off: i16,
    valid_region_xid: u32,
) -> bool {
    scanout_allowed
        && kms_outputs_active
        && cursor_hw
        && root_overlay_empty
        && matches!(
            target,
            ScanoutM0Target::Cow | ScanoutM0Target::CowDescendant | ScanoutM0Target::Unredirected
        )
        && matches!(coverage, ScanoutM0Coverage::Root)
        && x_off == 0
        && y_off == 0
        && valid_region_xid == 0
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ScanoutM0Shape {
    target: ScanoutM0Target,
    coverage: ScanoutM0Coverage,
    rect: Option<(i32, i32, u32, u32)>,
    source_extent: (u32, u32),
    depth: u8,
    bpp: u8,
    imported: bool,
    fourcc: u32,
    vk_format: vk::Format,
    modifier: u64,
    plane_offset: u64,
    plane_pitch: u32,
    offsets: (i16, i16),
    /// Whether the Present carried a valid / update region, NOT which one.
    ///
    /// Issue #146: these were the region XIDs. A compositor creates a fresh
    /// update region every frame (`update=0x4144dd` → `0x4144eb` →
    /// `0x4144f9` in the reporter's log), so putting the XID in the dedup key
    /// made the key change on every Present by construction — and
    /// `scanout_m0 shape`, which is supposed to log only when the shape
    /// CHANGES, logged once per composited frame instead.
    ///
    /// Only the zero-ness is ever consumed: `regions_ok` tests
    /// `valid_region_xid == 0 && update_region_xid == 0 && update_is_full`.
    /// The identities are printed in the log line straight from the
    /// candidate, so nothing is lost by keeping them out of the key.
    valid_region_present: bool,
    update_region_present: bool,
    update_is_full: bool,
}

