#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct ScanoutM1IndexKey {
    source_id: DrawableId,
    backing_serial: u64,
    topology_generation: u64,
}

struct ScanoutM1ProbeEntry {
    /// Retained solely for its FB/GEM lifetime until Owner adoption;
    /// `Drop` performs teardown only for a Legacy entry.
    _framebuffer: Option<crate::drm::modeset::DirectScanoutProbeFramebuffer>,
    managed: bool,
    probe_serial: Option<u64>,
    index_key: Option<ScanoutM1IndexKey>,
    token: Option<crate::kms::render::resources::ManagedAllocationToken>,
}

impl ScanoutM1ProbeEntry {
    fn rejected() -> Self {
        Self {
            _framebuffer: None,
            managed: false,
            probe_serial: None,
            index_key: None,
            token: None,
        }
    }

    fn accepted(framebuffer: crate::drm::modeset::DirectScanoutProbeFramebuffer) -> Self {
        Self {
            _framebuffer: Some(framebuffer),
            managed: false,
            probe_serial: None,
            index_key: None,
            token: None,
        }
    }

    fn framebuffer(&self) -> Option<&crate::drm::modeset::DirectScanoutProbeFramebuffer> {
        (!self.managed)
            .then_some(self._framebuffer.as_ref())
            .flatten()
    }

    fn take_framebuffer(&mut self) -> Option<crate::drm::modeset::DirectScanoutProbeFramebuffer> {
        if self.managed {
            return None;
        }
        let framebuffer = self._framebuffer.take();
        if framebuffer.is_some() {
            self.managed = true;
        }
        framebuffer
    }
}

const MAX_M1_PROBE_CACHE_ENTRIES: usize = 32;

struct ScanoutM1ProbeCache {
    topology_signature: u64,
    order: std::collections::VecDeque<DrawableId>,
    entries: HashMap<DrawableId, ScanoutM1ProbeEntry>,
    index: HashMap<ScanoutM1IndexKey, crate::kms::render::resources::ManagedAllocationToken>,
}

impl ScanoutM1ProbeCache {
    fn new() -> Self {
        Self {
            topology_signature: 0,
            order: std::collections::VecDeque::new(),
            entries: HashMap::new(),
            index: HashMap::new(),
        }
    }

    #[cfg(test)]
    fn insert(&mut self, id: DrawableId, entry: ScanoutM1ProbeEntry) {
        self.insert_with_serial(id, None, entry);
    }

    fn insert_with_serial(
        &mut self,
        id: DrawableId,
        probe_serial: Option<u64>,
        mut entry: ScanoutM1ProbeEntry,
    ) {
        self.remove_index_for_source(id);
        entry.probe_serial = probe_serial;
        if !self.entries.contains_key(&id) {
            while self.entries.len() >= MAX_M1_PROBE_CACHE_ENTRIES {
                if let Some(oldest) = self.order.pop_front() {
                    self.remove(oldest);
                } else {
                    break;
                }
            }
            self.order.push_back(id);
        }
        self.entries.insert(id, entry);
    }

    fn mark_managed(
        &mut self,
        id: DrawableId,
        key: ScanoutM1IndexKey,
        token: crate::kms::render::resources::ManagedAllocationToken,
    ) -> bool {
        if !self.entries.contains_key(&id) {
            return false;
        }
        self.remove_index_for_source(id);
        let Some(entry) = self.entries.get_mut(&id) else {
            return false;
        };
        entry.managed = true;
        entry.probe_serial = Some(key.backing_serial);
        entry.index_key = Some(key);
        entry.token = Some(token.clone());
        self.index.insert(key, token);
        true
    }

    fn token(
        &self,
        key: ScanoutM1IndexKey,
    ) -> Option<crate::kms::render::resources::ManagedAllocationToken> {
        self.index.get(&key).cloned()
    }

    fn remove_index_for_source(&mut self, id: DrawableId) {
        let Some(entry) = self.entries.get_mut(&id) else {
            self.index.retain(|key, _| key.source_id != id);
            return;
        };
        if let Some(key) = entry.index_key.take() {
            self.index.remove(&key);
        }
        entry.token = None;
        self.index.retain(|key, _| key.source_id != id);
    }

    fn remove_index_for_allocation(
        &mut self,
        allocation: crate::kms::render::resources::AllocationKey,
    ) {
        let keys: Vec<_> = self
            .index
            .iter()
            .filter_map(|(key, token)| (token.key() == allocation).then_some(*key))
            .collect();
        for key in keys {
            self.index.remove(&key);
            if let Some(entry) = self.entries.get_mut(&key.source_id)
                && entry.index_key == Some(key)
            {
                entry.index_key = None;
                entry.token = None;
                entry.probe_serial = None;
            }
        }
    }

    fn remove(&mut self, id: DrawableId) {
        self.remove_index_for_source(id);
        self.entries.remove(&id);
    }

    pub(super) fn clear(&mut self, reason: &'static str) {
        if !self.entries.is_empty() || !self.index.is_empty() {
            log::debug!(
                "scanout_m1: dropping {} cached probe framebuffer(s): {reason}",
                self.entries.len()
            );
            self.entries.clear();
            self.order.clear();
            self.index.clear();
        }
    }
}

struct DirectPresentFrame {
    source_pin: u64,
    fallback_target_pin: u64,
    /// Owner-route adoption's role-proof framebuffer lease. Legacy direct
    /// frames leave this empty and continue to use the strong M1 cache.
    framebuffer_lease: Option<crate::kms::render::resources::AllocationLease>,
    source_id: DrawableId,
    candidate: PresentScanoutCandidate,
    fallback_target: PaintTarget,
    /// The exact KMS membership captured while the producer prepared this
    /// frame. It must not be reconstructed from the consumer's current state
    /// at dispatch time.
    members: Vec<crate::kms::render::resources::GroupMember>,
    event: yserver_core::backend::CompletedPresentEvent,
    /// Commit that accepted this frame. `Presented` may populate the clock
    /// only when its owner event names this exact id.
    commit_id: Option<crate::kms::render::resources::CommitKey>,
    /// Output whose CRTC domain owns CompleteNotify/MSC for this Present.
    completion_output_idx: usize,
    /// Exact pageflip sample from the selected/reference CRTC. Xorg waits for
    /// every grouped CRTC to retire before completing, but stamps the event
    /// from this reference sample rather than the last/max output.
    completion_clock: Option<yserver_core::backend::PresentClockSample>,
    awaiting_outputs: HashSet<usize>,
    admission_source_generation: Option<u64>,
}

/// The result of the one production direct-scanout eligibility evaluation.
///
/// The preparation values are carried along because `try_present_direct`
/// needs them after the decision to retain the existing prepare/submit split;
/// admission consumes only `eligible` and `layout_generation`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct DirectEligibility {
    pub(crate) eligible: bool,
    pub(crate) layout_generation: u64,
    source_id: Option<DrawableId>,
    paint_target: Option<PaintTarget>,
    authoritative_root: bool,
}

impl DirectEligibility {
    pub(crate) fn refused(layout_generation: u64) -> Self {
        Self {
            eligible: false,
            layout_generation,
            source_id: None,
            paint_target: None,
            authoritative_root: false,
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn direct_present_eligibility_decision(
    direct_crtc_eligible: bool,
    scanout_allowed: bool,
    kms_outputs_active: bool,
    cursor_hw: bool,
    root_overlay_empty: bool,
    authoritative_root: bool,
    unbordered: bool,
    x_off: i16,
    y_off: i16,
    valid_region_xid: u32,
    layout_generation: u64,
) -> DirectEligibility {
    DirectEligibility {
        eligible: direct_crtc_eligible
            && scanout_direct_eligible(
                scanout_allowed,
                kms_outputs_active,
                cursor_hw,
                root_overlay_empty,
                authoritative_root,
                unbordered,
                x_off,
                y_off,
                valid_region_xid,
            ),
        layout_generation,
        source_id: None,
        paint_target: None,
        authoritative_root,
    }
}

/// Require a short stable run before entering direct ownership. Compositors
/// such as E27 alternate full-root Presents with authoritative region-limited
/// Presents; entering on every eligible member of that stream otherwise
/// causes direct/composed atomic thrash.
const SCANOUT_M2_ELIGIBLE_ROOT_PROBATION: u8 = 8;

/// F5a-M1: the real `DirectOwnershipState` implementor for
/// `resources::transport::TransportGate`'s M-13 precondition. A clone of
/// `ScanoutM2State`'s own live cells, kept in sync by `sync_ownership`
/// (called at `ScanoutM2State`'s own `current`/`pending`/
/// `queued_successor`/`unflip_requested` mutation sites) -- unlike the
/// deleted `DirectOwnershipSignal`, nothing outside `ScanoutM2State` ever
/// needs to remember to publish into this: it is the shadow of fields this
/// same struct already owns and mutates. Installing a `TransportGate`
/// against a clone of this handle in production is later work (R8).
#[derive(Debug, Clone, Default)]
pub(crate) struct ScanoutM2OwnershipHandle {
    busy: Rc<Cell<bool>>,
    unflip_outstanding: Rc<Cell<bool>>,
}

impl crate::kms::render::resources::DirectOwnershipState for ScanoutM2OwnershipHandle {
    fn direct_ownership_busy(&self) -> bool {
        self.busy.get()
    }

    fn unflip_outstanding(&self) -> bool {
        self.unflip_outstanding.get()
    }
}

pub(super) struct ScanoutM2State {
    ownership: ScanoutM2OwnershipHandle,
    pending: Option<DirectPresentFrame>,
    /// One eligible direct successor, retained while `pending` owns the
    /// hardware transaction. Newer successors replace this slot (latest
    /// wins); there is never more than one not-yet-submitted direct frame.
    queued_successor: Option<DirectPresentFrame>,
    /// F7-B1: the `DirectRole::Successor` capacity charge for
    /// `queued_successor`, kept in lockstep with it. It travels as a bare
    /// `RoleReservation` (never `attach`ed into a `CommitResources`, so it
    /// is always `Reserved`, never `Occupied`) until the managed dispatch
    /// seam promotes it. Every site that mutates `queued_successor` must
    /// mutate this field in the same step: dropping a charged
    /// `RoleReservation` without an explicit `cancel_reservation`/
    /// `finish_role` closes admission via its own `Drop` impl (capacity.rs),
    /// so a bare `.take()`/`.replace()` on `queued_successor` alone would
    /// either leak a charge or spuriously close admission.
    queued_successor_role: Option<crate::kms::render::resources::RoleReservation>,
    current: Option<DirectPresentFrame>,
    completed: Vec<yserver_core::backend::CompletedPresentEvent>,
    /// Coalesced successors cannot overtake the in-flight predecessor's
    /// CompleteNotify. Release their storage immediately, but publish their
    /// Skip completions only when that predecessor retires.
    deferred_successor_skips: Vec<yserver_core::backend::CompletedPresentEvent>,
    idled: Vec<yserver_core::backend::CompletedPresentEvent>,
    hold_direct: bool,
    cursor_bound_all: bool,
    unflip_requested: bool,
    /// First request in the current direct-to-composed transition. This is
    /// the causal trigger; later composite ticks must not overwrite it.
    unflip_reason: Option<&'static str>,
    /// Most recent request before submission, useful for distinguishing the
    /// initiating event from the gate that finally drove the atomic unflip.
    unflip_last_reason: Option<&'static str>,
    unflip_awaiting_outputs: HashSet<usize>,
    reentry_blocked_until_composed: bool,
    eligible_root_streak: u8,
    unflip_fallback_source: Option<DrawableId>,
    unflip_shadow_ready: bool,
    /// The synchronized composed unflip failed and was degraded to the
    /// per-output scene compose path. Keep direct-frame pins held until those
    /// composed flips replace every direct plane.
    degraded_composed_unflip: bool,
    /// The owner-route unflip that was dispatched and the exact outputs whose
    /// composed return it owns. This is set only after the dispatch crosses
    /// the send/confirm boundary; an ordinary retiring commit cannot trigger
    /// the return path by merely observing that an unflip was requested.
    pub(super) owner_unflip_return: Option<OwnerUnflipReturn>,
    /// Outputs whose post-unflip repaint has been applied by the scene but
    /// whose scene-produced proof has not yet arrived at this backend seam.
    owner_unflip_awaiting_outputs: HashSet<usize>,
    /// Once the owner return retires, this keeps the direct-entry barrier
    /// cumulative across as many scene ticks as the affected outputs need.
    owner_unflip_barrier_active: bool,
    /// Client modesets that have requested an Owner unflip retain direct-entry
    /// exclusion until that unflip is terminal and the modeset itself ends.
    pub(super) client_modeset_unflip_holds: Vec<ClientModesetUnflipHold>,
    #[cfg(test)]
    test_force_active: bool,
    #[cfg(test)]
    test_submit_direct_without_drm: bool,
}

impl ScanoutM2State {
    fn new() -> Self {
        Self {
            ownership: ScanoutM2OwnershipHandle::default(),
            pending: None,
            queued_successor: None,
            queued_successor_role: None,
            current: None,
            completed: Vec::new(),
            deferred_successor_skips: Vec::new(),
            idled: Vec::new(),
            hold_direct: false,
            cursor_bound_all: false,
            unflip_requested: false,
            unflip_reason: None,
            unflip_last_reason: None,
            unflip_awaiting_outputs: HashSet::new(),
            reentry_blocked_until_composed: false,
            eligible_root_streak: 0,
            unflip_fallback_source: None,
            unflip_shadow_ready: false,
            degraded_composed_unflip: false,
            owner_unflip_return: None,
            owner_unflip_awaiting_outputs: HashSet::new(),
            owner_unflip_barrier_active: false,
            client_modeset_unflip_holds: Vec::new(),
            #[cfg(test)]
            test_force_active: false,
            #[cfg(test)]
            test_submit_direct_without_drm: false,
        }
    }

    pub(super) fn active(&self) -> bool {
        self.pending.is_some() || self.queued_successor.is_some() || self.current.is_some() || {
            #[cfg(test)]
            {
                self.test_force_active
            }
            #[cfg(not(test))]
            {
                false
            }
        }
    }

    fn admit_eligible_root(&mut self) -> bool {
        if self.active() {
            return true;
        }
        self.eligible_root_streak = self
            .eligible_root_streak
            .saturating_add(1)
            .min(SCANOUT_M2_ELIGIBLE_ROOT_PROBATION);
        self.eligible_root_streak >= SCANOUT_M2_ELIGIBLE_ROOT_PROBATION
    }

    pub(super) fn reset_eligible_root_probation(&mut self) {
        self.eligible_root_streak = 0;
    }

    /// F5a-M1: re-derive the `DirectOwnershipState` answer from this
    /// struct's own fields and publish it into `ownership`. Called at every
    /// site that mutates `current`/`pending`/`queued_successor`/
    /// `unflip_requested`, so a clone of `ownership` held elsewhere (e.g. a
    /// `TransportGate`) never reads a value this struct itself did not just
    /// derive from its own truth.
    fn sync_ownership(&self) {
        self.ownership.busy.set(
            self.current.is_some() || self.pending.is_some() || self.queued_successor.is_some(),
        );
        self.ownership.unflip_outstanding.set(self.unflip_requested);
    }
}

pub(super) struct OwnerUnflipReturn {
    pub(super) commit: crate::kms::render::resources::CommitKey,
    affected_outputs: Vec<OutputKey>,
}

pub(super) struct ClientModesetUnflipHold {
    pub(super) modeset_device: DrmDeviceKey,
    pub(super) tag:
        crate::kms::owner::lifecycle::ClientModesetTag<crate::kms::owner::identity::IncarnationId>,
    pub(super) unflip_device: DrmDeviceKey,
    pub(super) unflip_commit: Option<crate::kms::render::resources::CommitKey>,
    pub(super) unflip_terminal: bool,
    pub(super) request_ended: bool,
}

#[cfg(test)]
fn classify_scanout_m0_coverage(
    rect: Option<(i32, i32, u32, u32)>,
    source_extent: (u32, u32),
    root_extent: (u32, u32),
    outputs: &[(i32, i32, u32, u32)],
) -> ScanoutM0Coverage {
    let Some(rect) = rect else {
        return ScanoutM0Coverage::None;
    };
    if rect == (0, 0, root_extent.0, root_extent.1) && source_extent == root_extent {
        return ScanoutM0Coverage::Root;
    }
    outputs
        .iter()
        .position(|output| rect == *output && source_extent == (output.2, output.3))
        .map_or(ScanoutM0Coverage::None, ScanoutM0Coverage::Output)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ScanoutM1OutputGeometry {
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    mode_width: u32,
    mode_height: u32,
}

fn scanout_m1_outputs_cover_root(root: (u32, u32), outputs: &[ScanoutM1OutputGeometry]) -> bool {
    if outputs.is_empty() {
        return false;
    }
    let mut area = 0u64;
    for (index, output) in outputs.iter().enumerate() {
        if output.x < 0
            || output.y < 0
            || output.width == 0
            || output.height == 0
            || output.width != output.mode_width
            || output.height != output.mode_height
        {
            return false;
        }
        let x = u32::try_from(output.x).expect("non-negative checked above");
        let y = u32::try_from(output.y).expect("non-negative checked above");
        if x.saturating_add(output.width) > root.0 || y.saturating_add(output.height) > root.1 {
            return false;
        }
        for other in &outputs[..index] {
            let separated = output.x + i32::try_from(output.width).unwrap_or(i32::MAX) <= other.x
                || other.x + i32::try_from(other.width).unwrap_or(i32::MAX) <= output.x
                || output.y + i32::try_from(output.height).unwrap_or(i32::MAX) <= other.y
                || other.y + i32::try_from(other.height).unwrap_or(i32::MAX) <= output.y;
            if !separated {
                return false;
            }
        }
        area = area.saturating_add(u64::from(output.width) * u64::from(output.height));
    }
    area == u64::from(root.0) * u64::from(root.1)
}

/// One leaf→backing composite emitted by
/// `KmsBackend::plan_backing_inferiors`. Coordinates are
/// backing-local (B's `(0, 0)` == the redirected window's origin);
