    fn init_root_storage(&mut self) {
        let root_xid = self.core.window_id;
        if self.store.lookup(root_xid).is_some() {
            return;
        }
        let width = self.platform.fb_w.max(1);
        let height = self.platform.fb_h.max(1);
        let storage = match self.platform.allocate_drawable_storage_as(
            width,
            height,
            32,
            crate::kms::vk::mem_accounting::MemCategory::WindowStorage,
        ) {
            Ok(storage) => {
                self.telemetry.record_storage_allocation();
                self.telemetry.record_image_view_create();
                storage
            }
            Err(e) => {
                log::debug!("render init_root_storage: no Vk, using stub root storage: {e:?}");
                Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: u32::from(width),
                        height: u32::from(height),
                    },
                    PlatformBackend::format_for_depth(32),
                )
            }
        };
        let id = match self.store_alloc(root_xid, DrawableKind::Root, 32, true, storage) {
            Ok(id) => id,
            Err(e) => {
                log::warn!("render init_root_storage: store.allocate failed: {e:?}");
                return;
            }
        };
        let rect = ash::vk::Rect2D {
            offset: ash::vk::Offset2D::default(),
            extent: ash::vk::Extent2D {
                width: u32::from(width),
                height: u32::from(height),
            },
        };
        if let Err(e) = self.engine.fill_rect(
            &mut self.store,
            &mut self.platform,
            Dst::server_internal(id),
            rect,
            decode_x11_pixel_for_storage(
                self.core.bg_pixel.unwrap_or(0x0050_5050),
                24,
                PlatformBackend::format_for_depth(24),
            ),
        ) && self.platform.vk.is_some()
        {
            log::warn!("render init_root_storage: initial root fill failed: {e:?}");
        }
    }

    /// Stamp alpha = 0xFF over `rects` (storage coordinates) when `target`
    /// is a depth-24 drawable resolved into a depth-32 ancestor's redirect
    /// backing; a no-op for every other target.
    ///
    /// A depth-24 window has no alpha, so its pixels must read opaque in
    /// that backing — Xorg composites a mismatched-depth child into its
    /// parent with alpha forced to 1. The fills and RENDER paths already
    /// honour that; a raw image copy does not, and carries the source's
    /// undefined X byte across (a GL client's background is commonly 0,
    /// which picom then shows through). Called after each raw copy with
    /// the rects it wrote.
    fn stamp_opaque_alpha_if_shared(&mut self, target: PaintTarget, rects: &[ash::vk::Rect2D]) {
        if rects.is_empty() || target.x11_depth() != 24 {
            return;
        }
        if !self
            .store
            .get(target.backing_id())
            .is_some_and(|d| d.depth == 32)
        {
            return;
        }
        let rects16: Vec<Rectangle16> = rects
            .iter()
            .filter_map(|r| {
                Some(Rectangle16 {
                    x: i16::try_from(r.offset.x).ok()?,
                    y: i16::try_from(r.offset.y).ok()?,
                    width: u16::try_from(r.extent.width).ok()?,
                    height: u16::try_from(r.extent.height).ok()?,
                })
            })
            .collect();
        if let Err(e) = self.engine.stamp_opaque_alpha(
            &mut self.store,
            &mut self.platform,
            target.dst(),
            &rects16,
        ) {
            log::warn!(
                "render: stamping opaque alpha into depth-32 backing {:?} failed: {e:?}",
                target.backing_id()
            );
        }
    }

    /// Stage 4a — resolve a host xid into the actual paint target
    /// under COMPOSITE redirect routing. Walks up the
    /// `windows.parent` chain accumulating `(x, y)` offsets;
    /// the first ancestor (including `host_xid` itself) whose
    /// `Drawable.redirected_target` is `Some(B_id)` wins.
    ///
    /// Returns:
    /// - `None` if `host_xid` doesn't map to any drawable.
    /// - the LEAF drawable for Pixmap targets (not in `windows`) and for
    ///   unredirected windows whose ancestor chain reaches root without
    ///   finding a redirected ancestor.
    /// - the redirect BACKING for redirected windows + their descendants.
    ///
    /// #133 step 3 (P4): the walk also accumulates the CONTENT offset
    /// (`border_width` per level, since a window's storage starts at its
    /// OUTER origin — `compAllocPixmap`, `composite/compalloc.c:610`)
    /// and the content clip. Both collapse to the pre-#133 values —
    /// offset `(0, 0)` / clip `None` — when every window in the chain
    /// has `border_width == 0`. See [`PaintTarget`] for the four cases.
    ///
    /// Per Stage 4 plan §"Per-hierarchy redirect": this is the
    /// per-op walk; tree depth bounds cost (typically ≤ 4 for
    /// real apps). Cached-ancestry alternative deferred to
    /// Stage 5 if profiling shows it.
    pub(crate) fn resolve_paint_target(&self, host_xid: u32) -> Option<PaintTarget> {
        let leaf_id = self.store.lookup(host_xid);
        let leaf_depth = self
            .windows
            .get(&host_xid)
            .map(|w| w.depth)
            .or_else(|| leaf_id.and_then(|id| self.store.get(id).map(|d| d.depth)))?;
        if let Some(geom) = self.windows.get(&host_xid) {
            // An unviewable window is clipped away, even under a viewable redirected ancestor.
            if !geom.viewable && !self.storage_lifecycle_exempt(host_xid) {
                return None;
            }
            self.resolve_window_paint_target(host_xid, leaf_id, leaf_depth)
        } else {
            let leaf_id = leaf_id?;
            self.resolve_non_window_paint_target(leaf_id, leaf_depth)
        }
    }

    fn resolve_non_window_paint_target(
        &self,
        leaf_id: super::store::DrawableId,
        leaf_depth: u8,
    ) -> Option<PaintTarget> {
        // Pixmaps have no border (`content == None`: the whole storage
        // is content), so this arm is unchanged by #133.
        if let Some(b_id) = self.store.redirected_target(leaf_id) {
            return Some(PaintTarget::new(b_id, (0, 0), None, leaf_depth));
        }
        Some(PaintTarget::new(leaf_id, (0, 0), None, leaf_depth))
    }

    fn resolve_window_paint_target(
        &self,
        host_xid: u32,
        leaf_id: Option<super::store::DrawableId>,
        leaf_depth: u8,
    ) -> Option<PaintTarget> {
        use super::target::ContentClipAccum;

        let mut cur_xid = host_xid;
        // #133 step 3 (P4/3.3) — the walk carries TWO accumulators, both
        // expressed in the frame it has reached (initially: the drawn
        // window's own outer origin, which is where its storage starts,
        // per `compAllocPixmap` `composite/compalloc.c:610`).
        //
        //   offset : the drawn window's CONTENT origin
        //   clip   : the content rects of every BORDERED level, intersected
        //
        // Per level the recurrence is `+ cur.x` (into the parent's content
        // frame) then `+ parent.border_width` (into the parent's outer
        // frame), which is the spec's one-level translation
        // `W.border_width + C.x + C.border_width` for a child C painting
        // into redirected ancestor W.
        //
        // A level with `border_width == 0` contributes NO clip term. Its
        // content rect is not a border constraint, and adding it would
        // narrow the `bw == 0` path — where the storage extent is the only
        // clip today — on every desktop we support.
        let own_bw = self.window_border_width(host_xid);
        let mut offset = (own_bw, own_bw);
        // #133 step 3 round 6 — every term that comes from a window's
        // own STORAGE (the leaf case, and a redirect owner's) is taken
        // from what that storage was ALLOCATED with, never from the
        // current `border_width`: see `storage_content_offset` for why
        // (an allocation that has not followed a border-width change
        // would otherwise displace every pixel already drawn). The
        // intermediate terms below are pure geometry — they position a
        // descendant inside an ancestor's content and own no storage.
        let mut clip = ContentClipAccum::default();
        if let Some(g) = self.windows.get(&host_xid)
            && g.border_width > 0
        {
            clip.intersect(super::target::content_rect(offset, g.width, g.height));
        }
        // The window's own content intersected with every ancestor's,
        // bordered or not: its clip in an ANCESTOR's backing, which it
        // shares with its parent and siblings (see
        // `PaintTarget::within_window_bounds`). Same frames as `clip`.
        let mut bounds = ContentClipAccum::default();
        if let Some(g) = self.windows.get(&host_xid) {
            bounds.intersect(super::target::content_rect(offset, g.width, g.height));
        }
        loop {
            if let Some(cur_id) = self.store.lookup(cur_xid)
                && let Some(b_id) = self.store.redirected_target(cur_id)
            {
                // A redirected window owns backing sized to its OWN
                // bordered geometry and is clipped to its own content
                // only — never to its parent. Xorg keys this off
                // `redirectDraw != RedirectDrawNone`, with no
                // manual/automatic distinction (`SetWinSize`,
                // `dix/window.c:1720`; `SetBorderSize`, `:1747`).
                // #133 step 3 round 6: the OWNER's own border term must
                // come from what its BACKING was allocated with, not
                // from its current `border_width` — same rule as the
                // leaf case (see `storage_content_offset`). Re-base the
                // accumulation by the delta; everything inside the
                // owner's content (all descendant terms, and the clip)
                // moves with it.
                let geom_bw = self.window_border_width(cur_xid);
                let layout_bw = self.storage_content_offset(cur_xid, b_id);
                let delta = layout_bw - geom_bw;
                let mut clip = clip;
                clip.shift(delta, delta);
                let mut bounds = bounds;
                bounds.shift(delta, delta);
                if layout_bw > 0 && geom_bw == 0 {
                    // The owner's own content term was never folded in
                    // (its geometry says `bw == 0`), but its backing is
                    // laid out with a border: add it now, in backing
                    // coordinates.
                    if let Some(g) = self.windows.get(&cur_xid) {
                        clip.intersect(super::target::content_rect(
                            (layout_bw, layout_bw),
                            g.width,
                            g.height,
                        ));
                    }
                }
                let target = PaintTarget::new(
                    b_id,
                    (offset.0 + delta, offset.1 + delta),
                    self.finish_content_clip(clip, b_id),
                    leaf_depth,
                );
                if cur_xid == host_xid {
                    return Some(target);
                }
                return Some(target.within_window_bounds(self.finish_content_clip(bounds, b_id)));
            }
            // No `windows` entry means we've stepped onto root
            // (parent = `core.window_id`, not tracked) or onto an
            // unparented orphan. In both cases there's no parent
            // chain left to walk; return identity at the leaf.
            // if it still has live storage. If the leaf drawable
            // has already detached from the xid map (e.g. a
            // redirected descendant whose paints should route only
            // via an ancestor backing), keep the redirected-ancestor
            // miss as `None`.
            let Some(geom) = self.windows.get(&cur_xid) else {
                return leaf_id.map(|id| self.leaf_paint_target(host_xid, id, leaf_depth));
            };
            match geom.parent {
                None => {
                    // Top-level: parent is root, not tracked in
                    // `windows`. `create_subwindow` records
                    // `parent = None` when the host_parent is
                    // root_xid (the if-not-in-windows branch),
                    // so this is the production representation
                    // for every top-level. Step up to root
                    // explicitly so a `RedirectWindow(root, …)`
                    // compositor sees top-level descendants route
                    // through the root backing — codex round-7
                    // finding (`parent == None` previously
                    // returned identity without consulting root).
                    offset.0 += i32::from(geom.x);
                    offset.1 += i32::from(geom.y);
                    clip.shift(i32::from(geom.x), i32::from(geom.y));
                    bounds.shift(i32::from(geom.x), i32::from(geom.y));
                    // The root window has no border (spec §Invariants), so
                    // its content origin IS its backing origin: no further
                    // shift and no clip term.
                    if let Some(root_id) = self.store.lookup(self.core.window_id)
                        && let Some(b_id) = self.store.redirected_target(root_id)
                    {
                        // Root has no border, so nothing to re-base
                        // here: the accumulated offset already ends in
                        // the root's content frame, which IS its
                        // backing origin.
                        return Some(
                            PaintTarget::new(
                                b_id,
                                offset,
                                self.finish_content_clip(clip, b_id),
                                leaf_depth,
                            )
                            .within_window_bounds(self.finish_content_clip(bounds, b_id)),
                        );
                    }
                    // No root redirect: paint stays on the leaf
                    // at its own CONTENT origin if the leaf storage is
                    // still live. Explicit match (not `?`) so we
                    // don't poison the outer Option.
                    return leaf_id.map(|id| self.leaf_paint_target(host_xid, id, leaf_depth));
                }
                Some(parent_xid) => {
                    // Into the parent's CONTENT frame…
                    offset.0 += i32::from(geom.x);
                    offset.1 += i32::from(geom.y);
                    clip.shift(i32::from(geom.x), i32::from(geom.y));
                    bounds.shift(i32::from(geom.x), i32::from(geom.y));
                    // …intersect the parent's own content rect (a child
                    // may not reach its parent's border,
                    // `mi/mivaltree.c:386`), then step into the parent's
                    // OUTER frame, which is where the parent's storage or
                    // backing starts.
                    let parent_bw = self.window_border_width(parent_xid);
                    if parent_bw > 0
                        && let Some(pg) = self.windows.get(&parent_xid)
                    {
                        clip.intersect(super::target::content_rect((0, 0), pg.width, pg.height));
                    }
                    if let Some(pg) = self.windows.get(&parent_xid) {
                        bounds.intersect(super::target::content_rect((0, 0), pg.width, pg.height));
                    }
                    offset.0 += parent_bw;
                    offset.1 += parent_bw;
                    clip.shift(parent_bw, parent_bw);
                    bounds.shift(parent_bw, parent_bw);
                    cur_xid = parent_xid;
                }
            }
        }
    }

    /// `border_width` of a tracked window as an `i32`, or 0 for the root
    /// / an untracked xid (#133: the root window has no border).
    fn window_border_width(&self, host_xid: u32) -> i32 {
        self.windows
            .get(&host_xid)
            .map_or(0, |g| i32::from(g.border_width))
    }

    /// Resolve a RENDER source / mask picture into what the engine samples.
    ///
    /// Takes `&self` because a picture on a WINDOW must go through
    /// `resolve_paint_target`: see the `PictureRecord::Drawable` arm.
    fn resolve_picture_for_render(
        &self,
        host_pic: u32,
    ) -> Option<(
        crate::kms::render::engine::ResolvedSource,
        Repeat,
        Option<PictTransform>,
        bool, // component_alpha
    )> {
        use crate::kms::render::engine::{ResolvedSource, SourceDrawable};
        match self.core.pictures.get(&host_pic)? {
            PictureRecord::Drawable {
                host_xid,
                repeat,
                transform,
                component_alpha,
                ..
            } => {
                // #133 step 3 (P4) — a picture wrapping a WINDOW resolves
                // through `resolve_paint_target`, exactly like every other
                // route to a window's pixels (`copy_area`'s source,
                // `copy_plane`'s source, every destination). That hands back
                // all three things this needs:
                //
                // - the drawable that HOLDS the pixels. A redirected
                //   window's leaf storage is stale — its pixels live in the
                //   backing — so a raw `store.lookup` samples the wrong
                //   image. Same premise as `copy_plane`.
                // - the ACCUMULATED content origin. A window's content
                //   starts `bw` inside its own storage (`compAllocPixmap`,
                //   `composite/compalloc.c:610`), and a child below a
                //   redirected ancestor additionally carries the whole
                //   `W.bw + C.x + C.bw` chain the resolver walks — a single
                //   level's `border_width` is not enough.
                // - the read bounds, via the window's own extent as the
                //   source domain (below).
                //
                // Xorg arrives at the same offset from the other side:
                // `create_bits_picture` builds the pixman image over the
                // whole backing pixmap (`fb/fbpict.c:293-296`) and then adds
                // `pict->pDrawable->x/y` to the sampling offset
                // (`fb/fbpict.c:328-329`), which for a redirected bordered
                // window is exactly `bw` because `compAllocPixmap` places
                // the pixmap at `screen_x = drawable.x - bw`.
                //
                // A picture wrapping a COMPOSITE-NAMED WINDOW PIXMAP is the
                // other case and must NOT be treated this way: that pixmap
                // IS the bordered image, so its border is part of the
                // drawable on purpose. Named window pixmaps are registered
                // as Pixmaps under their own xid and are absent from
                // `windows`, so the discriminator stays "is this xid a
                // window in the geometry mirror" — and the non-window arm
                // keeps its pre-#133 raw-leaf lookup, which also leaves
                // root-drawable pictures (root is not in `windows`) on the
                // routing they had.
                let source = match self.windows.get(host_xid) {
                    Some(g) => {
                        let target = self.resolve_paint_target(*host_xid)?;
                        SourceDrawable::content(
                            target.backing_id(),
                            target.offset(),
                            ash::vk::Extent2D {
                                width: u32::from(g.width),
                                height: u32::from(g.height),
                            },
                        )
                    }
                    None => SourceDrawable::whole(self.store.lookup(*host_xid)?),
                };
                Some((
                    ResolvedSource::Drawable(source),
                    *repeat,
                    *transform,
                    *component_alpha,
                ))
            }
            PictureRecord::SolidFill {
                premul,
                repeat,
                component_alpha,
            } => Some((
                ResolvedSource::Solid(*premul),
                *repeat,
                None,
                *component_alpha,
            )),
            PictureRecord::LinearGradient {
                repeat, transform, ..
            }
            | PictureRecord::RadialGradient {
                repeat, transform, ..
            } => {
                // Stage 3f.13: full LUT sampling. The engine-side
                // `GradientPicture` was built at create time and lives
                // in `engine.picture_paint[host_pic]`; engine looks it
                // up by xid. If the engine-side build failed (test
                // fixture with no Vk, or allocation error), the engine
                // logs a gap and skips the paint — no first-stop
                // collapse fallback.
                Some((
                    ResolvedSource::Gradient(host_pic),
                    *repeat,
                    *transform,
                    false,
                ))
            }
        }
    }

    /// #137 visibility note — record a `CompositeGlyphs` this server
    /// cannot serve: bump the counter, and log the FIRST occurrence at
    /// `warn!` with every later one at `debug!`.
    ///
    /// A drop here draws nothing and returns no error, so the client
    /// cannot tell — and neither could we. #137 was an entire class of
    /// application (every Java/AWT one) rendering no text at all while
    /// the server's own telemetry knew, because the only evidence sat
    /// at `debug` in a module the usual `RUST_LOG` filters exclude.
    /// Warning once means a silently-unsupported paint path announces
    /// itself rather than never; reverting to `debug` after that means
    /// a pathological client cannot flood the log.
    ///
    /// **Once per process**, deliberately and literally — not once per
    /// server generation. A bare flag does not reset itself at a
    /// generation boundary, and wiring one into the reset lifecycle
    /// would depend on the #121 reset work, which is unmerged and
    /// parked. Revisit if and when reset lands.
    ///
    /// The counter is NOT rate-limited: it advances on every drop.
    fn record_composite_glyphs_drop(&mut self, reason: std::fmt::Arguments<'_>) {
        self.telemetry.record_composite_glyphs_dropped_unsupported();
        if take_first_occurrence(&COMPOSITE_GLYPHS_DROP_WARNED) {
            log::warn!(
                "render composite_glyphs UNSUPPORTED: {reason} — this request drew \
                 NOTHING and returned no error. Further occurrences log at debug; \
                 the composite_glyphs_dropped_unsupported counter keeps counting."
            );
        } else {
            log::debug!("render composite_glyphs gap: {reason}");
        }
    }

    /// #137 tier 1 — collapse a uniform drawable glyph source to the
    /// premultiplied colour it is, by reading its single pixel.
    ///
    /// `Err` carries the reason the caller must log: every way this can
    /// decline draws no text, and a client whose text silently vanishes
    /// cannot tell.
    ///
    /// Two things about the read are load-bearing:
    ///
    /// - It goes through [`RenderEngine::get_image`], the synchronous
    ///   readback, for its flush / close-frame / fence-wait ordering. A
    ///   direct image map offers no such guarantee and would race the
    ///   client's own recolouring — Java repaints this very pixmap to
    ///   change text colour and then reuses the picture, so an unordered
    ///   read renders the *previous* colour.
    /// - It goes through [`Src::server_internal`], the privileged
    ///   unclipped backing-space handle. `SourceDrawable::offset()` is
    ///   already resolved into backing space, so a client-bounded `Src`
    ///   would reapply a coordinate space on top of it and sample the
    ///   wrong pixel of a redirected window's backing — precisely the
    ///   case the domain-not-storage rule exists to get right.
    ///
    /// Step 5 puts [`Self::uniform_glyph_source_cache`] in front of the
    /// read. That is not a copy-cost optimisation: the copy-out measured
    /// at 1.5 ms/s. It is there because `get_image` must
    /// `close_open_frame(CloseReason::SyncWait)` before it can wait, and
    /// that close measured as ~75% of ALL frame closes on a text-heavy
    /// workload (`opens=237 closes=238`, `sync_wait=179`), collapsing
    /// `ops/frame_avg` to 1.6 and destroying the batching
    /// `composite_glyphs_via_frame_builder` exists to provide. A hit
    /// skips the read and therefore skips the close.
    ///
    /// The cache is populated only on the way OUT, after the pixel has
    /// been read, and a hit requires the source's `content_version` to
    /// be unchanged — so a client that repaints the 1x1 pixmap to
    /// recolour its text (Java, every string) misses and re-reads.
    fn uniform_glyph_source_premul(
        &mut self,
        host_src: u32,
        src: crate::kms::render::engine::SourceDrawable,
        repeat: Repeat,
        mask_fmt: u32,
    ) -> Result<[f32; 4], &'static str> {
        use crate::kms::render::{
            engine::{premul_from_wire_pixel, uniform_pixel_glyph_source},
            telemetry::GetImageSite,
        };
        let (depth, extent, content_version) = self
            .store
            .get(src.id())
            .map(|d| (d.depth, d.extent(), d.content_version))
            .ok_or("source drawable is not in the store")?;
        let rect = uniform_pixel_glyph_source(src, repeat, extent, mask_fmt)
            .ok_or("not a one-pixel sampled domain under a plane-covering repeat (tier 1 only)")?;
        // Step 5 — the cache lookup, and the ONLY thing that can skip
        // the readback below. `rect.offset` is the pixel actually read,
        // which is `src.offset()` resolved into backing space.
        let key_offset = (rect.offset.x, rect.offset.y);
        if let Some(premul) =
            self.uniform_glyph_source_cache
                .get(src.id(), content_version, key_offset)
        {
            self.telemetry.record_uniform_glyph_source_cache(true);
            return Ok(premul);
        }
        self.telemetry.record_uniform_glyph_source_cache(false);
        // The picture's DECLARED format, which overrides storage depth
        // when it says the alpha byte is padding — the same precedence
        // `resolve_force_opaque_pict_format` applies on the sampling
        // path. Absent (a synthesized source) falls back to depth.
        let pict_format = match self.core.pictures.get(&host_src) {
            Some(PictureRecord::Drawable { pict_format, .. }) => *pict_format,
            _ => 0,
        };
        self.telemetry
            .record_get_image_site(GetImageSite::GlyphSource);
        let wire = self
            .engine
            .get_image(
                &mut self.store,
                &mut self.platform,
                Src::server_internal(src.id()),
                rect,
                depth,
            )
            .map_err(|e| {
                log::warn!(
                    "render composite_glyphs: uniform source readback failed for \
                     0x{host_src:x} at {rect:?} d{depth}: {e:?}"
                );
                "uniform source readback failed"
            })?;
        let premul = premul_from_wire_pixel(&wire, depth, pict_format)
            .ok_or("source depth has no RENDER pixel decode, or the read came back short")?;
        // Populate AFTER the ordered read, never before — see spec
        // invariant 4 and [`UniformGlyphSourceCache`]. The version read
        // above is the one the bytes just returned belong to: nothing
        // between it and here can write the source, because this thread
        // IS the request loop and the read is fence-waited.
        self.uniform_glyph_source_cache
            .insert(src.id(), content_version, key_offset, premul);
        Ok(premul)
    }

    /// Resolve an accumulated content clip against the storage it will be
    /// applied in. `None` (no bordered level) keeps the target on the
    /// pre-#133 arithmetic.
    fn finish_content_clip(
        &self,
        clip: super::target::ContentClipAccum,
        id: DrawableId,
    ) -> Option<ash::vk::Rect2D> {
        let extent = self.store.get(id).map(|d| d.extent())?;
        clip.finish(extent)
    }

    /// #133 step 3 round 6 — the content offset the STORAGE was
    /// ALLOCATED with (`compAllocPixmap`,
    /// `composite/compalloc.c:610`): the client-visible content starts
    /// this many pixels inside it.
    ///
    /// **The content layout is a property of the allocation, not of the
    /// current `border_width`.** A `border_width` change mirrors into
    /// the geometry immediately, but reallocating and MIGRATING the
    /// content is step 6 (P8) — `configure_subwindow` re-syncs storage
    /// only on a width/height change. Re-basing the content origin off
    /// the new `border_width` alone moves the coordinate system without
    /// moving a single pixel, so everything already drawn is displaced
    /// by the delta.
    ///
    /// That was the xts5 Xlib9 `IncludeInferiors` regression, all 14 of
    /// them: `makewin` creates the test window with `border_width = 1`
    /// (xts5/src/lib/makewin2.c:232) and the purpose draws into it, then
    /// its root section does `XSetWindowBorderWidth(A_DRAW, 0)` before
    /// re-drawing through the root and comparing against the earlier
    /// saved image. Everything drawn before the change sat at storage
    /// `+(1, 1)`; after it the same content coordinates addressed
    /// storage `+(0, 0)`. The intervening `dclear` is clipped by the
    /// strip children — `dset` builds a FRESH GC, so ClipByChildren
    /// (xts5/src/lib/dset.c:126-149) — so the 1-px-displaced residue
    /// under the last strip survived and surfaced one column right of
    /// the rect: `Pixel mismatch at (90, 31)`.
    ///
    /// Anchoring on the allocation keeps every pixel where it is until
    /// something reallocates, and leaves step 6's realloc-and-migrate
    /// ([`Self::relayout_window_leaf_storage_for_border_change`]) as
    /// the single place that ever re-bases content — and it moves the
    /// pixels in the same breath. Identity at `bw == 0`, and equal to
    /// `border_width` whenever the two agree, which is always for a
    /// window that owns its own leaf storage. A window whose allocation
    /// could not follow (a core-owned redirect backing, a failed
    /// allocation) is where the two can still differ, and this is the
    /// value that keeps such a window readable rather than displaced.
    ///
    /// The value is RECORDED at allocation
    /// ([`Drawable::content_offset`]), not inferred from the extent: a
    /// redirect backing may legitimately be larger than its window, so
    /// an extent difference does not imply a border.
    fn storage_content_offset(&self, _host_xid: u32, id: DrawableId) -> i32 {
        self.store.get(id).map_or(0, |d| d.content_offset)
    }

    /// The paint target for a window drawing into its OWN leaf storage.
    /// The content origin comes from the ALLOCATION
    /// ([`Self::storage_content_offset`]), not from `border_width`.
    fn leaf_paint_target(&self, host_xid: u32, id: DrawableId, leaf_depth: u8) -> PaintTarget {
        let b = self.storage_content_offset(host_xid, id);
        PaintTarget::new(
            id,
            (b, b),
            self.leaf_content_clip(host_xid, id, b),
            leaf_depth,
        )
    }

    /// The content clip for a window painting into its OWN leaf storage:
    /// `(b, b, w, h)` inside `(w + 2b) x (h + 2b)` storage, where `b` is
    /// the ALLOCATION's content offset. `None` at `b == 0`, where
    /// content and storage coincide.
    fn leaf_content_clip(&self, host_xid: u32, id: DrawableId, b: i32) -> Option<ash::vk::Rect2D> {
        if b == 0 {
            return None;
        }
        let geom = self.windows.get(&host_xid)?;
        let mut clip = super::target::ContentClipAccum::default();
        clip.intersect(super::target::content_rect((b, b), geom.width, geom.height));
        self.finish_content_clip(clip, id)
    }

    /// What a pure move of `host_xid` has to carry along, captured
    /// BEFORE the configure mutates its geometry: `None` unless the
    /// window draws into an ANCESTOR's redirect backing.
    ///
    /// A window under a redirected ancestor has no pixels of its own on
    /// screen: it (and every non-redirected inferior) paints straight
    /// into the shared backing at its offset, so moving it leaves those
    /// pixels behind. Xorg moves them inside that one pixmap:
    /// `miMoveWindow` calls `CopyWindow` (`mi/miwindow.c:293`), and
    /// `compCopyWindow` falls through for a window that is not itself
    /// redirected (`composite/compwindow.c:548-552`) to `fbCopyWindow`,
    /// which copies the old `borderClip` to the new origin. The client
    /// is not asked to repaint the part that copy covers, so a client
    /// that drew once — the MATE notification area composites each
    /// tray icon into its window and then waits for Damage — shows
    /// whatever the backing held at the new position. A window that
    /// paints into its own leaf (no redirected ancestor), or owns its
    /// own backing, moves with its storage and needs nothing.
    ///
    /// Only a pure move qualifies: a resize or border-width change
    /// reallocates or re-tiles the window and goes through the paths
    /// below it instead.
    fn shared_backing_move_source(
        &self,
        host_xid: u32,
        config: &HostSubwindowConfig,
    ) -> Option<SharedBackingMoveSource> {
        let geom = self.windows.get(&host_xid)?;
        let moved = config.x.is_some_and(|x| x != geom.x) || config.y.is_some_and(|y| y != geom.y);
        let resized = config.width.is_some_and(|w| w != geom.width)
            || config.height.is_some_and(|h| h != geom.height)
            || config
                .border_width
                .is_some_and(|bw| bw != geom.border_width);
        if !moved || resized {
            return None;
        }
        let leaf = self.store.lookup(host_xid);
        if leaf
            .and_then(|id| self.store.redirected_target(id))
            .is_some()
        {
            return None;
        }
        let target = self.resolve_paint_target(host_xid)?;
        if Some(target.backing_id()) == leaf {
            return None;
        }
        Some(SharedBackingMoveSource {
            occluders: self.copy_area_shared_backing_occluders(host_xid, &target),
            target,
        })
    }

    /// Copy what [`Self::shared_backing_move_source`] captured to the
    /// window's new position in the same backing: the window's whole
    /// outer extent, inferiors included, minus higher siblings at the
    /// old position (not the window's pixels) and at the new one (not
    /// the window's to overwrite) — `fbCopyWindow`'s old `borderClip`
    /// intersected with the new one. Whatever the copy cannot cover is
    /// exposed by the core configure path, as in Xorg.
    fn carry_shared_backing_pixels_on_move(
        &mut self,
        host_xid: u32,
        source: SharedBackingMoveSource,
    ) {
        let Some(geom) = self.windows.get(&host_xid).copied() else {
            return;
        };
        let Some(target) = self.resolve_paint_target(host_xid) else {
            return;
        };
        let backing = target.backing_id();
        if backing != source.target.backing_id() {
            return;
        }
        let old_origin = source.target.offset();
        let new_origin = target.offset();
        if old_origin == new_origin {
            return;
        }
        // Window-local CONTENT space, the occluders' frame: the outer
        // extent starts a border width up and left of the content.
        let bw = i32::from(geom.border_width);
        let outer = ash::vk::Rect2D {
            offset: ash::vk::Offset2D { x: -bw, y: -bw },
            extent: ash::vk::Extent2D {
                width: u32::from(geom.width) + 2 * u32::from(geom.border_width),
                height: u32::from(geom.height) + 2 * u32::from(geom.border_width),
            },
        };
        let new_occluders = self.copy_area_shared_backing_occluders(host_xid, &target);
        // The parent's paint target carries its clip, its own and every
        // ancestor's, in backing coordinates.
        let parent_bounds = geom
            .parent
            .and_then(|p| self.resolve_paint_target(p))
            .filter(|t| t.backing_id() == backing)
            .and_then(PaintTarget::content_bounds);
        let shape = self.bounding_shape_local(host_xid);
        let pieces = shared_backing_move_pieces(
            outer,
            shape.as_deref(),
            &source.occluders,
            &new_occluders,
            parent_bounds,
            old_origin,
            new_origin,
        );
        let delta = (new_origin.0 - old_origin.0, new_origin.1 - old_origin.1);
        for piece in order_pieces_for_in_place_move(pieces, delta) {
            let src_rect = ash::vk::Rect2D {
                offset: ash::vk::Offset2D {
                    x: old_origin.0 + piece.offset.x,
                    y: old_origin.1 + piece.offset.y,
                },
                extent: piece.extent,
            };
            let dst_pos = ash::vk::Offset2D {
                x: new_origin.0 + piece.offset.x,
                y: new_origin.1 + piece.offset.y,
            };
            if let Err(e) = self.engine.copy_area(
                &mut self.store,
                &mut self.platform,
                Src::server_internal(backing),
                Dst::server_internal(backing),
                src_rect,
                dst_pos,
            ) {
                log::warn!(
                    "render configure_subwindow: carrying moved window 0x{host_xid:x} \
                     inside its shared backing failed: {e:?}"
                );
                return;
            }
        }
    }

    /// When window branches share one redirected backing, painting a lower
    /// branch must not overwrite higher siblings' visible pixels in that
    /// backing. Walk from the destination through every ancestor: a higher
    /// sibling at any level is an occluder for the whole descendant branch.
    ///
    /// Return those mapped higher-sibling rects in `dst_host_xid` local
    /// coordinates so `copy_area` can subtract them before dispatch. Using
    /// each sibling's resolved backing offset, rather than just its immediate
    /// `(x, y)`, also handles cousins reached through wrapper windows.
    fn copy_area_shared_backing_occluders(
        &self,
        dst_host_xid: u32,
        dst_target: &PaintTarget,
    ) -> Vec<ash::vk::Rect2D> {
        let mut branch_xid = dst_host_xid;
        let mut occluders = Vec::new();
        while let Some(branch_geom) = self.windows.get(&branch_xid) {
            occluders.extend(
                self.windows
                    .iter()
                    .filter_map(|(sibling_host_xid, sibling_geom)| {
                        if *sibling_host_xid == branch_xid
                            || !sibling_geom.mapped
                            || sibling_geom.parent != branch_geom.parent
                            || sibling_geom.stack_rank <= branch_geom.stack_rank
                            || sibling_geom.width == 0
                            || sibling_geom.height == 0
                        {
                            return None;
                        }
                        let sibling_target = self.resolve_paint_target(*sibling_host_xid)?;
                        (sibling_target.backing_id() == dst_target.backing_id()).then_some((
                            sibling_geom.stack_rank,
                            ash::vk::Rect2D {
                                offset: ash::vk::Offset2D {
                                    x: sibling_target.offset().0 - dst_target.offset().0,
                                    y: sibling_target.offset().1 - dst_target.offset().1,
                                },
                                extent: ash::vk::Extent2D {
                                    width: u32::from(sibling_geom.width),
                                    height: u32::from(sibling_geom.height),
                                },
                            },
                        ))
                    }),
            );
            let Some(parent_xid) = branch_geom.parent else {
                break;
            };
            branch_xid = parent_xid;
        }
        occluders.sort_by_key(|(rank, _)| *rank);
        occluders.into_iter().map(|(_, rect)| rect).collect()
    }

    /// `host_xid`'s bounding shape in its own content space, or `None`
    /// when it has none (the shape is then its outer rect).
    fn bounding_shape_local(&self, host_xid: u32) -> Option<Vec<ash::vk::Rect2D>> {
        self.core.shape_bounding.get(&host_xid).map(|rects| {
            rects
                .iter()
                .filter(|r| r.width > 0 && r.height > 0)
                .map(|r| ash::vk::Rect2D {
                    offset: ash::vk::Offset2D {
                        x: i32::from(r.x),
                        y: i32::from(r.y),
                    },
                    extent: ash::vk::Extent2D {
                        width: u32::from(r.width),
                        height: u32::from(r.height),
                    },
                })
                .collect()
        })
    }

    /// What a mapped child takes out of its parent under ClipByChildren,
    /// in the parent's content space: `content_box` for an unshaped child,
    /// else its bounding shape within its outer rect — Xorg subtracts the
    /// child's `borderSize`, which `SetBorderSize` intersects with
    /// `wBoundingShape` (`dix/window.c:1747-1770`). GDK clips a native
    /// window inside a client-side one with exactly such a shape, so the
    /// parent's widgets outside it (a dialog's button bar) stay drawable.
    fn child_clip_region(
        &self,
        child_host_xid: u32,
        geom: &WindowGeometry,
        content_box: ash::vk::Rect2D,
    ) -> Vec<ash::vk::Rect2D> {
        let Some(shape) = self.bounding_shape_local(child_host_xid) else {
            return vec![content_box];
        };
        let bw = i32::from(geom.border_width);
        let (cx, cy) = (i32::from(geom.x) + bw, i32::from(geom.y) + bw);
        let outer = ash::vk::Rect2D {
            offset: ash::vk::Offset2D {
                x: i32::from(geom.x),
                y: i32::from(geom.y),
            },
            extent: ash::vk::Extent2D {
                width: u32::from(geom.width) + 2 * u32::from(geom.border_width),
                height: u32::from(geom.height) + 2 * u32::from(geom.border_width),
            },
        };
        let in_parent: Vec<ash::vk::Rect2D> = shape
            .into_iter()
            .map(|r| ash::vk::Rect2D {
                offset: ash::vk::Offset2D {
                    x: r.offset.x + cx,
                    y: r.offset.y + cy,
                },
                extent: r.extent,
            })
            .collect();
        intersect_rect_with_clip(outer, &in_parent)
    }

    /// Where `host_xid` may draw in a backing it shares with its
    /// ancestors, beyond the bounds its paint target already carries, in
    /// its own content space: inside its own bounding shape and each
    /// ancestor's up to the backing's owner, and outside every higher
    /// sibling at each of those levels (their pixels share the backing;
    /// [`Self::copy_area_shared_backing_occluders`]). Xorg's clipList
    /// gets the same from `miComputeClips` (`mi/mivaltree.c:390-437`).
    /// `None` when nothing narrows the bounds — always for a window
    /// drawing into storage of its own.
    fn shared_backing_draw_clip(
        &self,
        host_xid: u32,
        target: &PaintTarget,
    ) -> Option<Vec<ash::vk::Rect2D>> {
        let leaf = self.store.lookup(host_xid);
        if Some(target.backing_id()) == leaf
            || leaf
                .and_then(|id| self.store.redirected_target(id))
                .is_some()
            || !self.windows.contains_key(&host_xid)
        {
            return None;
        }
        let mut region: Option<Vec<ash::vk::Rect2D>> = None;
        // The current level's content origin, in `host_xid`'s content space.
        let (mut ox, mut oy) = (0i32, 0i32);
        let mut cur = host_xid;
        loop {
            if let Some(shape) = self.bounding_shape_local(cur) {
                let shape: Vec<ash::vk::Rect2D> = shape
                    .into_iter()
                    .map(|r| ash::vk::Rect2D {
                        offset: ash::vk::Offset2D {
                            x: r.offset.x + ox,
                            y: r.offset.y + oy,
                        },
                        extent: r.extent,
                    })
                    .collect();
                region = Some(match region {
                    None => shape,
                    Some(cur_region) => cur_region
                        .into_iter()
                        .flat_map(|r| intersect_rect_with_clip(r, &shape))
                        .collect(),
                });
            }
            let owner = self
                .store
                .lookup(cur)
                .and_then(|id| self.store.redirected_target(id))
                .is_some();
            let Some(geom) = self.windows.get(&cur) else {
                break;
            };
            let Some(parent) = geom.parent.filter(|_| !owner) else {
                break;
            };
            // `cur`'s content origin sits at `(x + bw, y + bw)` in its
            // parent's content space.
            ox -= i32::from(geom.x) + i32::from(geom.border_width);
            oy -= i32::from(geom.y) + i32::from(geom.border_width);
            cur = parent;
        }
        let occluders = self.copy_area_shared_backing_occluders(host_xid, target);
        if region.is_none() && occluders.is_empty() {
            return None;
        }
        let bounds = target.content_bounds().map_or(
            ash::vk::Rect2D {
                offset: ash::vk::Offset2D {
                    x: i32::MIN / 2,
                    y: i32::MIN / 2,
                },
                extent: ash::vk::Extent2D {
                    width: u32::MAX / 2,
                    height: u32::MAX / 2,
                },
            },
            |b| ash::vk::Rect2D {
                offset: ash::vk::Offset2D {
                    x: b.offset.x - target.offset().0,
                    y: b.offset.y - target.offset().1,
                },
                extent: b.extent,
            },
        );
        let region = region.map_or_else(|| vec![bounds], |r| intersect_rect_with_clip(bounds, &r));
        Some(
            region
                .into_iter()
                .flat_map(|r| compute_copy_area_dst_rects(r, &occluders))
                .collect(),
        )
    }

    /// Screenshot fast-path for `CopyArea(src=root, …)` with the GC's
    /// subwindow-mode set to `IncludeInferiors` (Qt5 `QScreen::grabWindow`,
    /// e.g. flameshot). The root window's own storage holds only the
    /// background, so the ordinary copy would capture just the wallpaper. Read
    /// the COMPOSITED scanout instead — the same source `get_image` uses for
    /// the root — and upload it into the destination. This keeps composition in
    /// one place (the scene compositor) rather than re-walking the window tree.
    ///
    /// Returns `Ok(true)` when it handled the copy, `Ok(false)` to fall through
    /// to the normal path: for non-root sources, `ClipByChildren` (root storage
    /// is the correct background-only source there), non-plain GC state
    /// (non-`GXcopy`, partial plane-mask, or a bitmap clip-mask — whose
    /// semantics a raw upload can't preserve), or when there are no live
    /// outputs to read.
    fn try_copy_area_root_scanout(
        &mut self,
        src_host_xid: u32,
        dst_host_xid: u32,
        dst_target: &PaintTarget,
        src_x: i16,
        src_y: i16,
        dst_x: i16,
        dst_y: i16,
        width: u16,
        height: u16,
    ) -> io::Result<bool> {
        use yserver_core::backend::{ClipState, GcFunction, SubwindowMode};
        if src_host_xid != self.core.window_id
            || !matches!(
                self.core.current_subwindow_mode,
                SubwindowMode::IncludeInferiors
            )
        {
            return Ok(false);
        }
        // Only the plain GXcopy / full-plane-mask / no-bitmap-clip case reads
        // the scanout; exotic ROP/plane/clip-mask combos fall through so their
        // semantics aren't silently reduced to a raw upload. (GC rectangle
        // clips ARE honoured — via `compute_copy_area_scissors` below.)
        let dst_depth = dst_target.x11_depth();
        let full_mask = depth_plane_mask(dst_depth);
        let plane_mask = self.core.current_plane_mask & full_mask;
        let plain = matches!(self.core.current_function, GcFunction::Copy)
            && plane_mask == full_mask
            && !matches!(self.core.current_clip, ClipState::Pixmap { .. });
        if !plain {
            return Ok(false);
        }
        self.prime_transformed_root_reads();
        // Root space: a transformed output covers its footprint (spec D6).
        let outputs = self.crtc_root_rects();
        if outputs.is_empty() {
            return Ok(false);
        }
        // Destination sub-rects honour the GC rectangle clip (and, for window
        // destinations, child/occluder subtraction). Pixmap destinations get
        // the whole rect. Empty = fully clipped away (spec-correct no-op).
        let sub_rects =
            self.compute_copy_area_scissors(dst_host_xid, dst_target, dst_x, dst_y, width, height);
        if sub_rects.is_empty() {
            return Ok(true);
        }
        let dst_id = dst_target.dst();
        let (off_x, off_y) = dst_target.offset();
        let mut any = false;
        for sub in &sub_rects {
            for piece in split_root_scanout_reads(*sub, src_x, src_y, dst_x, dst_y, &outputs) {
                let bytes =
                    match read_scanout_region(self, piece.read, ScanoutReadSelection::OnScreenOnly)
                    {
                        Ok(b) => b,
                        Err(e) => {
                            log::warn!(
                                "render copy_area root-scanout: readback failed \
                             (dst=0x{dst_host_xid:x} read={:?}): {e:?}",
                                piece.read,
                            );
                            continue;
                        }
                    };
                let dst_pos = ash::vk::Offset2D {
                    x: piece.dst_local.x + off_x,
                    y: piece.dst_local.y + off_y,
                };
                match self.engine.put_image(
                    &mut self.store,
                    &mut self.platform,
                    dst_id,
                    dst_pos,
                    piece.read.extent,
                    &bytes,
                    dst_depth,
                ) {
                    Ok(()) => any = true,
                    Err(e) => log::warn!(
                        "render copy_area root-scanout: upload failed \
                         (dst=0x{dst_host_xid:x} pos={dst_pos:?}): {e:?}"
                    ),
                }
            }
        }
        if any {
            self.telemetry.record_paint_submit();
            self.trace_simple(SubmitKind::CopyArea, dst_target.backing_id(), 1);
            self.scene.wake_for_damage();
        }
        Ok(true)
    }

    /// Read a root-window region from the composited scanout, assembling across
    /// outputs. Returns the ZPixmap bytes (row-major, 4 bytes/pixel) for
    /// `region`, or `None` when there is no scanout (no KMS outputs) so the
    /// caller can fall through to the empty-reply path. Uncovered / failed
    /// pieces are zero-filled. See [`assemble_root_scanout`] for why the plain
    /// GetImage path must split like `CopyArea` does.
    #[allow(clippy::too_many_arguments)]
    fn render_composite_inner(
        &mut self,
        inferiors_snapshot: Option<u32>,
        op: u8,
        host_src: u32,
        host_mask: u32,
        host_dst: u32,
        src_x: i16,
        src_y: i16,
        mask_x: i16,
        mask_y: i16,
        dst_x: i16,
        dst_y: i16,
        width: u16,
        height: u16,
    ) -> io::Result<Vec<xfixes::RegionRect>> {
        use crate::kms::render::engine::ResolvedSource;
        if width == 0 || height == 0 {
            return Ok(Vec::new());
        }
        let Some((mut src_resolved, src_repeat, src_transform, _src_ca)) =
            self.resolve_picture_for_render(host_src)
        else {
            log::debug!("render render_composite gap: host_src 0x{host_src:x} not resolvable");
            return Ok(Vec::new());
        };
        if let Some(xid) = inferiors_snapshot
            && let Some(id) = self.store.lookup(xid)
        {
            src_resolved =
                ResolvedSource::Drawable(crate::kms::render::engine::SourceDrawable::whole(id));
        }
        let (mask_resolved, mask_repeat, mask_transform, mask_component_alpha) = if host_mask == 0 {
            (ResolvedSource::None, Repeat::None, None, false)
        } else {
            let Some(t) = self.resolve_picture_for_render(host_mask) else {
                log::debug!(
                    "render render_composite gap: host_mask 0x{host_mask:x} not resolvable"
                );
                return Ok(Vec::new());
            };
            t
        };
        let Some((dst_host_xid, dst_clip)) = resolve_dst_picture_for_render(&self.core, host_dst)
        else {
            log::debug!(
                "render render_composite gap: host_dst 0x{host_dst:x} not a Drawable picture"
            );
            return Ok(Vec::new());
        };
        // Stage 4a — resolve through redirect routing. The picture
        // wraps a window xid; the actual paint may land in that
        // window's COMPOSITE backing with an accumulated offset.
        let Some(dst_target) = self.resolve_paint_target(dst_host_xid) else {
            log::debug!(
                "render render_composite gap: dst drawable 0x{dst_host_xid:x} \
                 not in store (post-resolve)"
            );
            return Ok(Vec::new());
        };
        let clip_by_children = dst_picture_clip_by_children(&self.core, host_dst);
        let dst_local_extent = self.dst_local_extent(dst_host_xid, dst_target.backing_id());
        let op_bbox_local = Rectangle16 {
            x: dst_x,
            y: dst_y,
            width,
            height,
        };
        let cliplist_local = self.render_dst_cliplist_local(
            dst_host_xid,
            clip_by_children,
            dst_clip.as_deref(),
            dst_local_extent,
            op_bbox_local,
        );
        if cliplist_local.is_empty() {
            return Ok(Vec::new());
        }
        let dst_clip =
            Self::shift_dst_picture_clip(Some(cliplist_local.clone()), dst_target.offset());

        // Audit #2 (2026-05-19) — fold src/mask client clips into
        // the composite-region clip per Xorg's
        // `miComputeCompositeRegion` (`render/mipict.c:316-389`).
        // Pre-fix, `resolve_picture_for_render` discarded src/mask
        // clips entirely, so `SetPictureClipRectangles` on a source
        // picture (xfwm4/muffin shadow blits) painted over the
        // whole dst. The translation offset matches Xorg's
        // `miClipPictureSrc(..., xDst - xSrc, yDst - ySrc)` call
        // site at `mipict.c:356,370` — the dst already has
        // `dst_target.offset()` applied to `(xDst, yDst)`, so the
        // translation picks up that offset automatically.
        // #133 step 3 (P4): the source/mask DOMAIN joins the client
        // clip. For a bordered window source that is what keeps a
        // `RepeatNone` sample outside the window from returning a ring
        // texel — see `picture_source_domain_clip`. `None` unless the
        // picture wraps a bordered window, so `bw == 0` folds exactly
        // what it folded before.
        let fold_domain = |client: Option<Vec<Rectangle16>>,
                           domain: Option<Vec<Rectangle16>>|
         -> Option<Vec<Rectangle16>> {
            match (client, domain) {
                (Some(c), Some(d)) => Some(intersect_clip_lists(&c, &d)),
                (Some(c), None) => Some(c),
                (None, d) => d,
            }
        };
        let src_clip = fold_domain(
            picture_client_clip(&self.core, host_src),
            picture_source_domain_clip(
                &self.store,
                &src_resolved,
                src_repeat,
                src_transform.as_ref(),
            ),
        );
        let mask_clip = if host_mask == 0 {
            None
        } else {
            fold_domain(
                picture_client_clip(&self.core, host_mask),
                picture_source_domain_clip(
                    &self.store,
                    &mask_resolved,
                    mask_repeat,
                    mask_transform.as_ref(),
                ),
            )
        };
        let dst_origin_x = i32::from(dst_x) + dst_target.offset().0;
        let dst_origin_y = i32::from(dst_y) + dst_target.offset().1;
        let src_translation = (
            dst_origin_x - i32::from(src_x),
            dst_origin_y - i32::from(src_y),
        );
        let mask_translation = (
            dst_origin_x - i32::from(mask_x),
            dst_origin_y - i32::from(mask_y),
        );
        let dst_clip = compute_render_composite_clip(
            dst_clip.as_deref(),
            src_clip.as_deref(),
            src_translation,
            mask_clip.as_deref(),
            mask_translation,
        );

        let rect = crate::kms::vk::ops::render::CompositeRect {
            src_x: i32::from(src_x),
            src_y: i32::from(src_y),
            mask_x: i32::from(mask_x),
            mask_y: i32::from(mask_y),
            dst_x: i32::from(dst_x) + dst_target.offset().0,
            dst_y: i32::from(dst_y) + dst_target.offset().1,
            width: u32::from(width),
            height: u32::from(height),
        };
        // Audit #4 (2026-05-19) — thread src/mask/dst PictFormat IDs
        // through to the engine so an xRGB32 picture wrapping a
        // depth-32 storage picks a no-alpha sample swizzle +
        // force-opaque for sources, AND the right "no alpha target"
        // pipeline + readback selection for destinations.
        // `picture_pict_format` returns 0 for non-Drawable picture
        // variants and unknown xids — engine falls back to the depth
        // heuristic in those cases.
        let src_pict_format = picture_pict_format(&self.core, host_src);
        let mask_pict_format = picture_pict_format(&self.core, host_mask);
        let dst_pict_format = picture_pict_format(&self.core, host_dst);
        let stats = self.engine.render_composite(
            &mut self.store,
            &mut self.platform,
            op,
            src_resolved,
            mask_resolved,
            dst_target.dst(),
            std::slice::from_ref(&rect),
            dst_clip.as_deref(),
            src_repeat,
            mask_repeat,
            src_transform,
            mask_transform,
            mask_component_alpha,
            src_pict_format,
            mask_pict_format,
            dst_pict_format,
        );
        self.sync_descriptor_pool_telemetry();
        let src_class = self.picture_src_class_by_xid(host_src);
        let mask_class = if host_mask == 0 {
            None
        } else {
            Some(self.picture_src_class_by_xid(host_mask))
        };
        match &stats {
            Ok(s) => {
                if s.recorded_draws > 0 && !s.deferred_to_batch {
                    self.telemetry.record_paint_submit();
                    self.trace_render(
                        SubmitKind::RenderComposite,
                        dst_target.backing_id(),
                        s.recorded_draws,
                        op,
                        src_class,
                        mask_class,
                        SubmitFlags {
                            readback: s.used_dst_readback,
                            alias: s.used_src_alias_scratch,
                            zero_draws: false,
                            upload: false,
                        },
                    );
                }
                if s.used_dst_readback {
                    self.telemetry.record_disjoint_readback();
                }
                log::trace!(
                    target: "yserver::kms::render::render",
                    "render_composite stats dst=0x{host_dst:x} \
                     recorded_draws={} used_src_alias_scratch={} used_dst_readback={}",
                    s.recorded_draws,
                    s.used_src_alias_scratch,
                    s.used_dst_readback,
                );
            }
            Err(e) => {
                log::warn!("render render_composite: engine returned {e:?} on dst 0x{host_dst:x}");
            }
        }
        // Phase B.2 Task 15: render_composite may open a frame; drain
        // any resulting close events into telemetry so the per-second
        // emit picks them up without stale lag. Mirrors the B.1 drain
        // at the composite_glyphs wrapper.
        self.drain_frame_builder_telemetry();
        Ok(local_rects_to_region(cliplist_local))
    }

    /// What a RENDER source Picture on a window reads, as a sampleable
    /// drawable, when the window's own storage does not hold it: Xorg
    /// samples the pixmap the window draws into, its inferiors and all,
    /// whatever the picture's subwindow mode — only a client clip limits
    /// a source (`miClipPictureSrc`, `render/mipict.c:265-284`; fb builds
    /// it without a composite clip, `fb/fbpict.c:57`). Measured by
    /// tools/vng-scenarios/draw-clip-probe.c in both modes.
    ///
    /// The root: its own storage holds only the backdrop (#135; maim's
    /// whole capture is one such Composite), so this borrows the read
    /// `GetImage` of the root does (`read_root_scanout_assembled`) and
    /// uploads it into a short-lived pixmap. Any other window: its storage
    /// with [`Self::inferior_pieces`] copied over it, when there are any.
    /// `None` leaves the normal source routing untouched.
    ///
    /// The scratch pixmap is freed by the caller through the ordinary
    /// `free_pixmap` path, so its storage retires behind the fence like any
    /// other drawable rather than being destroyed under in-flight GPU work.
    fn source_inferiors_snapshot(&mut self, host_pic: u32) -> Option<u32> {
        let Some(PictureRecord::Drawable { host_xid, .. }) = self.core.pictures.get(&host_pic)
        else {
            return None;
        };
        let host_xid = *host_xid;
        if host_xid != self.core.window_id {
            return self.window_inferiors_snapshot(host_xid, None);
        }
        let root_xid = self.core.window_id;
        let root_id = self.store.lookup(root_xid)?;
        let (extent, depth) = {
            let d = self.store.get(root_id)?;
            (d.extent(), d.depth)
        };
        if extent.width == 0 || extent.height == 0 {
            return None;
        }
        let region = vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 },
            extent,
        };
        let bytes = self.read_root_scanout_assembled(region)?;
        let width = u16::try_from(extent.width).ok()?;
        let height = u16::try_from(extent.height).ok()?;
        let scratch = self.create_pixmap(None, depth, width, height).ok()?;
        let scratch_xid = scratch.as_raw();
        let Some(target) = self.resolve_paint_target(scratch_xid) else {
            let _ = self.free_pixmap(None, scratch_xid);
            return None;
        };
        // PRIVILEGED whole-backing write: this is a server-internal upload of
        // the composited screen, not a client paint, and the scratch drawable
        // has no border so the two targets coincide anyway.
        self.put_image_rop_cpu(
            target.server_backing_dst(),
            vk::Offset2D { x: 0, y: 0 },
            width,
            (0, 0),
            width,
            height,
            &bytes,
            depth,
            yserver_core::backend::GcFunction::Copy,
            depth_plane_mask(depth),
        );
        Some(scratch_xid)
    }

    /// [`Self::source_inferiors_snapshot`] for a window other than the
    /// root: `area` of it (its content space; `None` for all of it) as a
    /// scratch pixmap whose `(0, 0)` is `area`'s origin. `None` when its
    /// storage holds all it shows there already.
    fn window_inferiors_snapshot(
        &mut self,
        host_xid: u32,
        area: Option<vk::Rect2D>,
    ) -> Option<u32> {
        let geom = *self.windows.get(&host_xid)?;
        let target = self.resolve_paint_target(host_xid)?;
        let whole = vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 },
            extent: vk::Extent2D {
                width: u32::from(geom.width),
                height: u32::from(geom.height),
            },
        };
        let area = area.unwrap_or(whole);
        let content = intersect_rect_with_clip(area, &[whole])
            .into_iter()
            .next()?;
        let mut pieces = Vec::new();
        self.inferior_pieces(
            host_xid,
            (0, 0),
            &[content],
            target.backing_id(),
            &mut pieces,
        );
        if pieces.is_empty() {
            return None;
        }
        let scratch = self
            .create_pixmap(
                None,
                geom.depth,
                u16::try_from(area.extent.width).ok()?,
                u16::try_from(area.extent.height).ok()?,
            )
            .ok()?
            .as_raw();
        let Some(dst) = self.resolve_paint_target(scratch) else {
            let _ = self.free_pixmap(None, scratch);
            return None;
        };
        let copy = |b: &mut Self, src: PaintTarget, origin: (i32, i32), r: vk::Rect2D| {
            let src_rect = vk::Rect2D {
                offset: vk::Offset2D {
                    x: r.offset.x - origin.0 + src.offset().0,
                    y: r.offset.y - origin.1 + src.offset().1,
                },
                extent: r.extent,
            };
            let at = vk::Offset2D {
                x: r.offset.x - area.offset.x,
                y: r.offset.y - area.offset.y,
            };
            if let Err(e) = b.engine.copy_area(
                &mut b.store,
                &mut b.platform,
                src.src_including_border(),
                dst.server_backing_dst(),
                src_rect,
                at,
            ) {
                log::debug!("render source snapshot of {host_xid:#x}: copy {r:?}: {e:?}");
            }
        };
        copy(self, target, (0, 0), content);
        for piece in pieces {
            for r in &piece.rects {
                copy(self, piece.target, piece.origin, *r);
            }
        }
        Some(scratch)
    }

    /// The image a root read of `local` on output `output_idx` copies from,
    /// composed from the scene as every earlier request left it
    /// ([`SceneCompositor::root_readback`]); `None` without a live scene,
    /// leaving the read on the scanout.
    fn fresh_root_readback(&mut self, output_idx: usize, local: vk::Rect2D) -> Option<vk::Image> {
        if !self.scene.is_live() {
            return None;
        }
        if !self
            .scene
            .root_readback_is_current(&self.store, &self.platform, output_idx, local)
        {
            if let Err(e) = self.engine.close_open_frame(
                &mut self.store,
                &mut self.platform,
                crate::kms::render::frame_builder::CloseReason::LegacyScCompose,
            ) {
                log::warn!("render root read: close_open_frame failed: {e:?}");
            }
            if let Err(e) = self.engine.flush_submit_group(
                &mut self.store,
                &mut self.platform,
                crate::kms::render::submit_group::FlushReason::SceneCompose,
            ) {
                log::warn!("render root read: flush_submit_group failed: {e:?}");
            }
        }
        let cow_host_xid = self.cow_host_xid();
        match self.scene.root_readback(
            &self.core,
            &mut self.store,
            &self.windows,
            &self.platform,
            cow_host_xid,
            output_idx,
            local,
        ) {
            Ok(image) => image,
            Err(e) => {
                log::warn!("render root read: output {output_idx} readback compose failed: {e}");
                None
            }
        }
    }

    /// Before a root read: compose any transformed output that has not
    /// composed since its transform became current, so the read returns root
    /// content rather than a zero-filled piece.
    fn prime_transformed_root_reads(&mut self) {
        if !self
            .scene
            .has_unprimed_transform_intermediate(&self.platform)
        {
            return;
        }
        if let Err(e) = self.engine.close_open_frame(
            &mut self.store,
            &mut self.platform,
            crate::kms::render::frame_builder::CloseReason::LegacyScCompose,
        ) {
            log::warn!("render root read: close_open_frame failed: {e:?}");
        }
        if let Err(e) = self.engine.flush_submit_group(
            &mut self.store,
            &mut self.platform,
            crate::kms::render::submit_group::FlushReason::SceneCompose,
        ) {
            log::warn!("render root read: flush_submit_group failed: {e:?}");
        }
        let cow_host_xid = self.cow_host_xid();
        if let Err(e) = self.scene.prime_transform_intermediates(
            &self.core,
            &mut self.store,
            &self.windows,
            &self.platform,
            cow_host_xid,
        ) {
            log::warn!("render root read: transform intermediate compose failed: {e}");
        }
    }

    /// Tile `host_pixmap_xid` across the whole root extent from (0, 0): the
    /// root's background pixmap, painted by `set_container_background_pixmap`
    /// and again whenever the root storage is reallocated for a new screen
    /// size (Xorg `SetRootClip` exposes the whole resized root and
    /// `miPaintWindow` tiles its background there).
    fn tile_root_background_pixmap(&mut self, host_pixmap_xid: u32) {
        use crate::kms::{
            render::engine::{ResolvedSource, SourceDrawable},
            vk::ops::render::CompositeRect,
        };
        // Stage 4a — root paint resolves through redirect routing.
        let Some(dst_target) = self.resolve_paint_target(self.core.window_id) else {
            return;
        };
        let dst = dst_target.backing_id();
        let Some(src) = self.store.lookup(host_pixmap_xid) else {
            log::debug!(
                "render set_container_background_pixmap: pixmap 0x{host_pixmap_xid:x} not in store"
            );
            return;
        };
        // Stage 3f.14: X11 bg_pixmap tiles across the drawable
        // extent. Pre-3f.14 v2 did a single copy_area at (0, 0)
        // and left the rest of root unchanged — fvwm3 wallpaper
        // covered only the top-left of the screen on bee. Route
        // through `engine.render_composite` with OP_SRC + Repeat::
        // Normal so the source pixmap tiles across the whole root
        // extent in a single submit. Same shape as `try_tiled_fill`
        // (3f.3) but unconditioned by GC clip.
        if src == dst {
            // Defensive: a pixmap aliased as bg of its own drawable
            // is not a meaningful X11 op. v1's path treats it the
            // same (copy_area with src == dst is logged + skipped).
            log::debug!("render set_container_background_pixmap: src == root, skipping");
            return;
        }
        let src_format = self.store.get(src).map(|d| d.storage.format);
        if src_format != Some(ash::vk::Format::B8G8R8A8_UNORM) {
            // Tile path requires BGRA8 src (matches `try_tiled_fill`
            // gate). Other formats fall through with no paint —
            // v1-parity-ish; rare in practice for root bg.
            log::debug!(
                "render set_container_background_pixmap: pixmap 0x{host_pixmap_xid:x} format \
                 {src_format:?} not BGRA8, skipping tile"
            );
            return;
        }
        let dst_extent = ash::vk::Extent2D {
            width: u32::from(self.platform.fb_w.max(1)),
            height: u32::from(self.platform.fb_h.max(1)),
        };
        let rects = [CompositeRect {
            src_x: 0,
            src_y: 0,
            mask_x: 0,
            mask_y: 0,
            dst_x: dst_target.offset().0,
            dst_y: dst_target.offset().1,
            width: dst_extent.width,
            height: dst_extent.height,
        }];
        const OP_SRC: u8 = 1;
        let composite_result = self.engine.render_composite(
            &mut self.store,
            &mut self.platform,
            OP_SRC,
            ResolvedSource::Drawable(SourceDrawable::whole(src)),
            ResolvedSource::None,
            dst_target.dst(),
            &rects,
            None,
            Repeat::Normal,
            Repeat::None,
            None,
            None,
            false,
            // Audit #4: synthesized backing-seed copy, no Picture
            // context. Engine falls back to depth heuristic.
            0,
            0,
            0,
        );
        self.sync_descriptor_pool_telemetry();
        match composite_result {
            Ok(s) if s.recorded_draws > 0 && !s.deferred_to_batch => {
                self.telemetry.record_paint_submit();
                self.trace_render(
                    SubmitKind::RenderComposite,
                    dst,
                    s.recorded_draws,
                    1, // OP_SRC
                    SrcClass::Direct,
                    None,
                    SubmitFlags {
                        readback: s.used_dst_readback,
                        alias: s.used_src_alias_scratch,
                        zero_draws: false,
                        upload: false,
                    },
                );
            }
            Ok(_) => {}
            Err(e) => {
                log::warn!(
                    "render set_container_background_pixmap: render_composite tile failed: {e:?}"
                );
            }
        }
    }

    fn read_root_scanout_assembled(&mut self, region: vk::Rect2D) -> Option<Vec<u8>> {
        self.prime_transformed_root_reads();
        // Root space: a transformed output covers its footprint (spec D6).
        let outputs = self.crtc_root_rects();
        let root_target = self.resolve_paint_target(self.core.window_id)?;
        let root_id = root_target.backing_id();
        Some(assemble_root_scanout(region, &outputs, |rect, source| {
            if source == RootReadSource::Background {
                // No CRTC shows this area, so no scanout holds it. The root
                // storage does: its background, which is what Xorg's screen
                // pixmap holds there too (windows over it are not composed
                // outside the CRTCs, so they are missing from this piece).
                let (offset_x, offset_y) = root_target.offset();
                let root_local_rect = vk::Rect2D {
                    offset: vk::Offset2D {
                        x: rect.offset.x.saturating_add(offset_x),
                        y: rect.offset.y.saturating_add(offset_y),
                    },
                    extent: rect.extent,
                };
                return self
                    .engine
                    .get_image(
                        &mut self.store,
                        &mut self.platform,
                        crate::kms::render::target::Src::server_internal(root_id),
                        root_local_rect,
                        32,
                    )
                    .map_err(|e| log::debug!("render root background readback {rect:?}: {e:?}"))
                    .ok()
                    .filter(|bytes| {
                        bytes.len() == rect.extent.width as usize * rect.extent.height as usize * 4
                    });
            }
            // `assemble_root_scanout` zero-fills a piece it cannot read. That
            // degradation is unchanged, but a failure here now also covers an
            // unresolvable direct-scanout source, which previously answered
            // with a stale composed BO instead — so say which rect went black.
            match read_scanout_region(self, rect, ScanoutReadSelection::OnScreenOnly) {
                Ok(bytes) => Some(bytes),
                Err(error) => {
                    if let Some(held) = self.root_readback_warn.check(std::time::Instant::now()) {
                        log::warn!(
                            "render root scanout readback: {rect:?} unreadable, \
                             zero-filling that piece: {error} ({held} more since the last report)"
                        );
                    }
                    None
                }
            }
        }))
    }

    /// Compute the surviving destination scissor rects for a CopyArea, in
    /// drawable-LOCAL space (before `dst_target.offset()` is added). This is the
    /// EXACT non-mask clip machinery the run-based path uses, in order: GC
    /// clip-rect intersect (`ClipState::Rectangles`; `Pixmap`/`None` keep the
    /// whole copy rect), then ClipByChildren child-window subtraction (window
    /// dsts only), then higher-sibling occluder subtraction (shared redirect
    /// backing). Extracted from `copy_area`'s `post_gc_clip` →
    /// `child_clipped_rects` → `sub_rects` block so both the run-based path and
    /// the GPU masked path (Task 14) share identical non-mask clipping. The
    /// masked path further gates by the GPU clip-mask snapshot and shifts these
    /// rects into image space by `dst_target.offset()`. An empty result means
    /// "fully clipped away" (empty GC clip, or fully occluded): a no-op.
    fn compute_copy_area_scissors(
        &self,
        dst_host_xid: u32,
        dst_target: &PaintTarget,
        dst_x: i16,
        dst_y: i16,
        width: u16,
        height: u16,
    ) -> Vec<ash::vk::Rect2D> {
        let dst_rect_local = ash::vk::Rect2D {
            offset: ash::vk::Offset2D {
                x: i32::from(dst_x),
                y: i32::from(dst_y),
            },
            extent: ash::vk::Extent2D {
                width: u32::from(width),
                height: u32::from(height),
            },
        };
        // #133 step 3 (P4): confine the copy to the destination's content
        // BEFORE the clip machinery, so "fully clipped away" (the
        // `is_empty()` early-out both callers rely on) also covers a copy
        // that lands entirely in the border ring. The engine clamps again
        // on dispatch; this is the local-space mirror. Identity when the
        // destination has no border clip.
        let Some(dst_rect_local) = dst_target.clip_local_vk_rect(dst_rect_local) else {
            return Vec::new();
        };
        let post_gc_clip: Vec<ash::vk::Rect2D> =
            if let yserver_core::backend::ClipState::Rectangles { origin, rects } =
                &self.core.current_clip
            {
                let clip_rects: Vec<ash::vk::Rect2D> = rects
                    .rectangles
                    .chunks_exact(8)
                    .filter_map(|chunk| {
                        let cx = i32::from(i16::from_le_bytes([chunk[0], chunk[1]]))
                            + i32::from(origin.0);
                        let cy = i32::from(i16::from_le_bytes([chunk[2], chunk[3]]))
                            + i32::from(origin.1);
                        let cw = i32::from(u16::from_le_bytes([chunk[4], chunk[5]]));
                        let ch = i32::from(u16::from_le_bytes([chunk[6], chunk[7]]));
                        if cw <= 0 || ch <= 0 {
                            return None;
                        }
                        Some(ash::vk::Rect2D {
                            offset: ash::vk::Offset2D { x: cx, y: cy },
                            extent: ash::vk::Extent2D {
                                width: u32::try_from(cw).unwrap_or(0),
                                height: u32::try_from(ch).unwrap_or(0),
                            },
                        })
                    })
                    .collect();
                intersect_rect_with_clip(dst_rect_local, &clip_rects)
            } else {
                vec![dst_rect_local]
            };
        if post_gc_clip.is_empty() {
            return Vec::new();
        }
        // Step 2: ClipByChildren — subtract every mapped child window
        // rect from each post-GC-clip rect. IncludeInferiors (mode=1)
        // keeps each post-GC-clip rect as-is. Pixmap destinations
        // (not in `windows`) also bypass child subtraction.
        let child_clipped_rects: Vec<ash::vk::Rect2D> =
            if matches!(
                self.core.current_subwindow_mode,
                yserver_core::backend::SubwindowMode::ClipByChildren,
            ) && self.windows.contains_key(&dst_host_xid)
            {
                let child_rects: Vec<ash::vk::Rect2D> = self
                    .windows
                    .iter()
                    .filter_map(|(child_host_xid, geom)| {
                        if !(geom.parent == Some(dst_host_xid) && geom.mapped) {
                            return None;
                        }
                        // Manually-redirected children don't claim the
                        // parent's pixmap real estate (see run-path note).
                        let is_manually_redirected = self
                            .store
                            .lookup(*child_host_xid)
                            .and_then(|id| self.store.get(id))
                            .is_some_and(|d| !d.scene_participating);
                        if is_manually_redirected {
                            return None;
                        }
                        // #133 step 3 round 5 — child rects live in the
                        // parent's CONTENT space: `(x + bw, y + bw)`.
                        // Same rule as the `IncludeInferiors` fan-out and
                        // `clip_fill_rects_by_subwindow_mode`; identity
                        // at `bw == 0`.
                        let child_bw = i32::from(geom.border_width);
                        let content_box = ash::vk::Rect2D {
                            offset: ash::vk::Offset2D {
                                x: i32::from(geom.x) + child_bw,
                                y: i32::from(geom.y) + child_bw,
                            },
                            extent: ash::vk::Extent2D {
                                width: u32::from(geom.width.max(1)),
                                height: u32::from(geom.height.max(1)),
                            },
                        };
                        Some(self.child_clip_region(*child_host_xid, geom, content_box))
                    })
                    .flatten()
                    .collect();
                if child_rects.is_empty() {
                    post_gc_clip
                } else {
                    post_gc_clip
                        .into_iter()
                        .flat_map(|r| compute_copy_area_dst_rects(r, &child_rects))
                        .collect()
                }
            } else {
                post_gc_clip
            };
        // Higher siblings at every level, and the bounding shapes, of a
        // window sharing its ancestors' backing.
        match self.shared_backing_draw_clip(dst_host_xid, dst_target) {
            Some(keep) => child_clipped_rects
                .into_iter()
                .flat_map(|r| intersect_rect_with_clip(r, &keep))
                .collect(),
            None => child_clipped_rects,
        }
    }

    /// Stage 4c.2 — compute the screen-absolute rect for a window's
    /// `DrawableId`. Walks the `windows.parent` chain upward
    /// from `w_id`, accumulating each step's `(x, y)` offset; the
    /// resulting rect's `offset` is the window's root-relative
    /// origin and the `extent` is its own `width × height`.
    ///
    /// Returns `None` when:
    /// - `w_id` doesn't resolve in the store, OR
    /// - the leaf xid has no `windows` entry (Pixmap / Root /
    ///   detached), OR
    /// - the parent chain hits a dangling `Some(xid)` that is
    ///   neither root (`core.window_id`) nor a tracked
    ///   `windows` entry. Bailing keeps callers from acting on
    ///   a half-accumulated rect; Stage 5 cache work can revisit
    ///   if the conservative choice ever bites.
    ///
    /// Consumed by Stage 4c.4's `set_window_scene_participation`:
    /// it captures the previous on-screen rect BEFORE flipping
    /// `scene_participating` so it can fire
    /// `mark_scene_structure_damage_rects(&[prev_rect])` for the
    /// redirect transition.
    pub(crate) fn window_absolute_rect(
        &self,
        w_id: crate::kms::render::store::DrawableId,
    ) -> Option<ash::vk::Rect2D> {
        let leaf_xid = self.store.get(w_id)?.xid;
        let leaf_geom = self.windows.get(&leaf_xid)?;
        let mut abs_x = i32::from(leaf_geom.x);
        let mut abs_y = i32::from(leaf_geom.y);
        let mut cur_parent = leaf_geom.parent;
        while let Some(parent_xid) = cur_parent {
            if parent_xid == self.core.window_id {
                // Reached root explicitly — root is the (0, 0)
                // origin of the screen-absolute coordinate space.
                break;
            }
            let Some(parent_geom) = self.windows.get(&parent_xid) else {
                // Dangling parent: not root, not tracked. Bail.
                return None;
            };
            abs_x += i32::from(parent_geom.x);
            abs_y += i32::from(parent_geom.y);
            cur_parent = parent_geom.parent;
        }
        Some(ash::vk::Rect2D {
            offset: ash::vk::Offset2D { x: abs_x, y: abs_y },
            extent: ash::vk::Extent2D {
                width: u32::from(leaf_geom.width),
                height: u32::from(leaf_geom.height),
            },
        })
    }

    /// Audit #6 (2026-05-19) — Xorg parity rewrite. The old
    /// "copy W's own storage + DFS-walk descendants" model
    /// (Stage 4b.5) preserved any pre-redirect paint on W, but
    /// freshly-mapped windows that hit redirect activation
    /// before their first paint seeded B with W's default-init
    /// colour (opaque black on depth-24, transparent on
    /// depth-32) — visible as the recurring "black band on map"
    /// symptom and called out by the 2026-05-19 protocol audit.
    ///
    /// Replaced with Xorg's `compNewPixmap`
    /// (composite/compalloc.c:541-606) semantics: copy from
    /// W's PARENT at the source offset
    /// `(W.x - parent.x, W.y - parent.y)` to B at `(0, 0)`.
    /// This gives the compositor / direct-emit scene-walk
    /// continuity with what was on-screen before W appeared.
    /// The W's own (default-init) content is not preserved;
    /// W's first client paint fills B via `resolve_paint_target`
    /// routing afterwards.
    ///
    /// Skipped when:
    /// - W has no parent in `windows` (root or untracked).
    /// - Parent's storage isn't in the store (pixmap-as-W
    ///   activation path used by tests; falls back to leaving
    ///   B at its default-init zero-fill).
    /// - Parent's storage extent is zero.
    ///
    /// `IncludeInferiors`-equivalent semantics (parent's siblings
    /// of W contributing where they overlap W's screen position)
    /// are deferred: yserver's parent storage already includes
    /// most of that content via the normal paint flow for
    /// non-compositor cases, and the Stage 4d compositor-floor
    /// scene-walk presents siblings directly.
    fn seed_backing_from_parent(
        &mut self,
        w_xid: u32,
        b_id: crate::kms::render::store::DrawableId,
    ) {
        let Some(w_geom) = self.windows.get(&w_xid).copied() else {
            log::debug!("render seed_backing_from_parent W=0x{w_xid:x}: not in windows; skip seed");
            return;
        };
        let Some(parent_xid) = w_geom.parent else {
            log::debug!(
                "render seed_backing_from_parent W=0x{w_xid:x}: no parent (root or untracked); skip seed"
            );
            return;
        };
        // Resolve parent's effective storage. If parent is itself
        // redirected, its `redirected_target` (B') holds the
        // currently-visible pixels; if not, parent's own storage
        // does. `resolve_paint_target` does the chain walk.
        let Some(parent_target) = self.resolve_paint_target(parent_xid) else {
            log::debug!(
                "render seed_backing_from_parent W=0x{w_xid:x}: parent 0x{parent_xid:x} has no paint target; skip seed"
            );
            return;
        };
        let parent_extent = self
            .store
            .get(parent_target.backing_id())
            .map(|d| d.extent())
            .unwrap_or_default();
        if parent_extent.width == 0 || parent_extent.height == 0 {
            log::debug!(
                "render seed_backing_from_parent W=0x{w_xid:x}: parent storage zero-extent; skip seed"
            );
            return;
        }
        // Source rect on parent: W's OUTER origin in the parent's
        // drawable space. `parent_target.offset()` is the parent's
        // content origin inside the storage the copy reads (its own, or
        // an ancestor backing when the parent is itself redirected);
        // W's wire `(x, y)` is its OUTER origin relative to that
        // content origin (`dix/window.c` sets
        // `drawable.x = parent->drawable.x + x + bw`).
        //
        // #133 step 3 (3.3): B is now the BORDERED extent placed at W's
        // outer origin, so the seed must cover `w + 2bw` x `h + 2bw`
        // and land at B's `(0, 0)` — exactly Xorg
        // `compNewPixmap(pWin, x, y, w, h)` with
        // `x = drawable.x - bw` / `w = width + (bw << 1)`
        // (`composite/compalloc.c:608-618`) copying
        // `CopyArea(parent → pixmap, x - pParent->drawable.x,
        // y - pParent->drawable.y, w, h, 0, 0)`
        // (`composite/compalloc.c:566-571`). Seeding only `w x h` here
        // would put the parent's pixels in the ring and shift the whole
        // inherited image by `bw`. Collapses to the pre-#133 rect at
        // `bw == 0`.
        let src_x = parent_target.offset().0 + i32::from(w_geom.x);
        let src_y = parent_target.offset().1 + i32::from(w_geom.y);
        let (outer_w, outer_h) =
            bordered_storage_extent(w_geom.width, w_geom.height, w_geom.border_width);
        let src_rect = ash::vk::Rect2D {
            offset: ash::vk::Offset2D {
                x: src_x.max(0),
                y: src_y.max(0),
            },
            extent: ash::vk::Extent2D {
                width: outer_w,
                height: outer_h,
            },
        };
        let dst_pos = ash::vk::Offset2D { x: 0, y: 0 };
        log::debug!(
            "render seed_backing_from_parent W=0x{w_xid:x} parent=0x{parent_xid:x} \
             src=({src_x},{src_y} {outer_w}x{outer_h} outer, bw={bw}) → B@(0,0)",
            bw = w_geom.border_width,
        );
        // Server-internal redirect seeding: B is initialised from the
        // parent's backing in BACKING space (both handles privileged).
        if let Err(e) = self.engine.copy_area(
            &mut self.store,
            &mut self.platform,
            parent_target.server_backing_src(),
            Dst::server_internal(b_id),
            src_rect,
            dst_pos,
        ) {
            log::warn!(
                "render seed_backing_from_parent(0x{w_xid:x}): parent copy_area failed: {e:?}",
            );
        } else {
            self.telemetry.record_paint_submit();
            self.trace_simple(SubmitKind::CopyArea, b_id, 1);
        }
    }

    /// 2026-06-11 — synthesize Xorg `compNewPixmap`'s
    /// `IncludeInferiors` over a freshly-allocated redirect backing.
    ///
    /// `seed_backing_from_parent` lays down the parent layer — Xorg's
    /// `CopyArea(parent, …, IncludeInferiors)` base
    /// (../xserver/composite/compalloc.c:562). But Xorg has NO separate
    /// per-window storage, so that copy captures the redirected
    /// window's OWN pixels (it is an inferior of the parent). yserver
    /// keeps a separate per-window leaf, so the parent storage holds
    /// only the parent's pixels (wallpaper for a root child) and W's
    /// own content is lost — the "half-drawn MATE panel under compiz
    /// --replace" bug (static regions never repaint after a
    /// compositor handoff, so they keep the wallpaper seed).
    ///
    /// This reconstructs the inferiors: DFS over W and its mapped
    /// descendants in `stack_rank` (bottom-to-top) order, compositing
    /// each window's own leaf into B at its accumulated offset from W.
    /// A descendant that owns its OWN `redirected_target` (an
    /// independently-redirected child — XEmbed systray icons, etc.) is
    /// PRUNED with its whole subtree: the client compositor reads and
    /// composites that child's backing separately via
    /// `NameWindowPixmap`, so its pixels must not be baked into W's
    /// backing.
    ///
    /// Must run BEFORE `set_redirected_target(W)` so the walk reads
    /// each window's leaf, not the about-to-be-installed route. Keep
    /// the per-window/stacking rules in sync with
    /// `scene::emit_window_subtree` (scene.rs:2406).
    fn overlay_backing_inferiors(
        &mut self,
        w_xid: u32,
        b_id: crate::kms::render::store::DrawableId,
    ) {
        use crate::kms::{
            cpu_types::Repeat,
            render::engine::{ResolvedSource, SourceDrawable},
            vk::ops::render::CompositeRect,
        };
        let plan = self.plan_backing_inferiors(w_xid, b_id);
        if plan.is_empty() {
            return;
        }
        // RAW COPY, not a composite. Xorg's `compNewPixmap` seeds the
        // new backing with `CopyArea(parent, …, IncludeInferiors)`
        // (`composite/compalloc.c:562`), and CopyArea replaces the
        // destination — it has no notion of alpha at all. This walk
        // exists only because yserver keeps a separate per-window leaf,
        // so it must reproduce the same REPLACEMENT that a single
        // shared-storage CopyArea would have performed, one leaf at a
        // time in bottom-to-top stack order.
        //
        // This was `PictOpOver` until 2026-09-11, on the reasoning that
        // "alpha children blend over the parent base". They must not: a
        // depth-32 child with α = 0 then blends as a NO-OP and the
        // parent's seed shows through its background. Measured — a
        // window asking for `background-pixel = 0x00000000` kept the
        // root's red and read back `00ff0000` where Xorg 21.1.24 gives
        // `00000000` (`tools/depth32-bg-probe.c`, transparent-zero
        // A-root, vng 2026-09-11).
        //
        // The same probe shows the replacement model is what Xorg
        // actually stores: on 21.1.24 a depth-24 frame's redirected
        // pixmap reads `00ffffff` under an ARGB child whose background
        // is transparent white — the child's own bits, alpha and all,
        // stamped into the parent's pixmap rather than blended with it.
        //
        // Shape and stacking are unaffected: `push_inferior_rects`
        // already intersects each leaf with its `shape_bounding` and
        // `collect_backing_inferiors` walks in `stack_rank` order, so
        // only the blend equation changes here. Depth-24 leaves still
        // land opaque — `sample_view` gives them α = 1 — so the one
        // behaviour that changes is the one that was wrong.
        const OP_SRC: u8 = 1;
        for d in plan {
            // Skip leaves whose storage has no realized view (no GPU
            // backing yet) — the planner left the liveness check here.
            if self
                .store
                .get(d.leaf_id)
                .is_none_or(|s| !s.has_image_view())
            {
                continue;
            }
            let rects = [CompositeRect {
                src_x: d.src_x,
                src_y: d.src_y,
                mask_x: 0,
                mask_y: 0,
                dst_x: d.dst_x,
                dst_y: d.dst_y,
                width: d.width,
                height: d.height,
            }];
            match self.engine.render_composite(
                &mut self.store,
                &mut self.platform,
                OP_SRC,
                // The planner already put this leaf's CONTENT origin
                // into `src_x`/`src_y` (`push_inferior_rects`), so the
                // source is addressed in raw leaf-storage coordinates
                // here — `whole` is correct and `content` would
                // double-count the border.
                ResolvedSource::Drawable(SourceDrawable::whole(d.leaf_id)),
                ResolvedSource::None,
                Dst::server_internal(b_id),
                &rects,
                None,
                Repeat::None,
                Repeat::None,
                None,
                None,
                false,
                // Synthesized seed; no Picture context — engine falls
                // back to the depth heuristic (→ `sample_view`).
                0,
                0,
                0,
            ) {
                Ok(s) if s.recorded_draws > 0 => {
                    self.telemetry.record_paint_submit();
                    self.trace_simple(SubmitKind::RenderComposite, b_id, s.recorded_draws);
                }
                Ok(_) => {}
                Err(e) => log::warn!(
                    "render overlay_backing_inferiors(0x{w_xid:x}): leaf {leaf:?} composite failed: {e:?}",
                    leaf = d.leaf_id,
                ),
            }
        }
    }

    /// Pure planner for [`Self::overlay_backing_inferiors`] — returns
    /// the ordered leaf→backing composites (backing-local coords,
    /// B's (0,0) == W's origin). Split out so the
    /// traversal/prune/clip logic is unit-testable without a live
    /// `RenderEngine`/Vulkan context.
    fn plan_backing_inferiors(
        &self,
        w_xid: u32,
        b_id: crate::kms::render::store::DrawableId,
    ) -> Vec<SeedInferiorDraw> {
        let mut out = Vec::new();
        let b_extent = self
            .store
            .get(b_id)
            .map_or(ash::vk::Extent2D::default(), |d| d.extent());
        if b_extent.width == 0 || b_extent.height == 0 {
            return out;
        }
        // #133 step 3 (3.3): B's `(0, 0)` is W's OUTER origin now, so
        // the walk starts at W's CONTENT origin inside B — `(bw, bw)`,
        // Xorg's `compSetPixmap(pWin, pPixmap, bw)`
        // (`composite/compalloc.c:620`). `(0, 0)` at `bw == 0`.
        let seed_bw = self.window_border_width(w_xid);
        self.collect_backing_inferiors(w_xid, seed_bw, seed_bw, true, &mut out);
        out
    }

    /// Recursive worker for [`Self::plan_backing_inferiors`].
    /// `(off_x, off_y)` is the current window's CONTENT origin in
    /// backing-local coords (#133 step 3: B's `(0, 0)` is W's OUTER
    /// origin, and each level adds `child.x + child.border_width` —
    /// the same recurrence `resolve_window_paint_target` walks);
    /// `is_seed_root` is true only for W itself (W is becoming
    /// redirected now, so its own `redirected_target` must not prune
    /// it).
    fn collect_backing_inferiors(
        &self,
        xid: u32,
        off_x: i32,
        off_y: i32,
        is_seed_root: bool,
        out: &mut Vec<SeedInferiorDraw>,
    ) {
        let Some(geom) = self.windows.get(&xid).copied() else {
            return;
        };
        if !geom.mapped {
            // X11: an unmapped window (and its whole subtree) is invisible.
            return;
        }
        let Some(leaf_id) = self.store.lookup(xid) else {
            return;
        };

        // Prune at an independently-redirected descendant: its backing
        // is composited separately by the client compositor, so its
        // pixels (and its subtree) must not be baked into W's backing.
        if !is_seed_root && self.store.redirected_target(leaf_id).is_some() {
            return;
        }

        // Plan this window's own leaf if it's a Window with sized
        // storage. The GPU-liveness check (`image_view != null`) is
        // deferred to the consumer so this planner stays pure/testable.
        if let Some(d) = self.store.get(leaf_id)
            && matches!(d.kind, crate::kms::render::store::DrawableKind::Window)
        {
            // #133 step 3: the leaf's CONTENT is what composites into
            // B, and it lives `bw` inside the leaf's own storage
            // (`compAllocPixmap`, `composite/compalloc.c:610`), so the
            // clamp is against the storage minus the ring and the
            // source origin is `(bw, bw)`. Identity at `bw == 0`.
            let bw = u32::from(geom.border_width);
            let content_cap_w = d.extent().width.saturating_sub(bw.saturating_mul(2));
            let content_cap_h = d.extent().height.saturating_sub(bw.saturating_mul(2));
            let w = u32::from(geom.width).min(content_cap_w);
            let h = u32::from(geom.height).min(content_cap_h);
            self.push_inferior_rects(xid, leaf_id, off_x, off_y, w, h, out);
        }

        // Recurse mapped children bottom-to-top, same `stack_rank`
        // order as `scene::emit_window_subtree` (scene.rs:2406).
        let mut children: Vec<(u32, u64)> = self
            .windows
            .iter()
            .filter_map(|(c, g)| (g.parent == Some(xid)).then_some((*c, g.stack_rank)))
            .collect();
        children.sort_by_key(|(_, rank)| *rank);
        for (child, _) in children {
            // `off` is the PARENT's content origin; a child's outer
            // origin is `+ (x, y)` from there and its own content
            // origin `+ bw` inside that (#133 step 3 — the same
            // one-level translation `resolve_window_paint_target` uses,
            // `W.border_width + C.x + C.border_width`).
            let (cx, cy, cbw) = self.windows.get(&child).map_or((0, 0, 0), |g| {
                (i32::from(g.x), i32::from(g.y), i32::from(g.border_width))
            });
            self.collect_backing_inferiors(child, off_x + cx + cbw, off_y + cy + cbw, false, out);
        }
    }

    /// Emit the leaf→backing rects for one window, honoring SHAPE
    /// bounding (one rect per bound, mirroring scene.rs:2302) and
    /// clamping negative destination offsets by shifting the source
    /// (the off-parent/offscreen case the parent-seed copy mishandled).
    ///
    /// #133 step 3: `(off_x, off_y)` is the window's CONTENT origin in
    /// backing-local coords, and the SOURCE origin is the window's
    /// content origin inside its own leaf storage — `(bw, bw)`, not
    /// `(0, 0)`. SHAPE bounds are window-relative (content space), so
    /// they are offset by `bw` on the source side only.
    fn push_inferior_rects(
        &self,
        xid: u32,
        leaf_id: crate::kms::render::store::DrawableId,
        off_x: i32,
        off_y: i32,
        w: u32,
        h: u32,
        out: &mut Vec<SeedInferiorDraw>,
    ) {
        if w == 0 || h == 0 {
            return;
        }
        let src_bw = self.window_border_width(xid);
        let mut emit = |sx: i32, sy: i32, dx: i32, dy: i32, rw: i32, rh: i32| {
            let (mut sx, mut sy, mut dx, mut dy) = (sx, sy, dx, dy);
            let (mut rw, mut rh) = (i64::from(rw), i64::from(rh));
            // Low-side clamp: a negative dst shifts the source and
            // shrinks the rect. High-side clipping is left to
            // `render_composite`'s dst-extent clamp.
            if dx < 0 {
                sx -= dx;
                rw += i64::from(dx);
                dx = 0;
            }
            if dy < 0 {
                sy -= dy;
                rh += i64::from(dy);
                dy = 0;
            }
            if rw <= 0 || rh <= 0 {
                return;
            }
            #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
            out.push(SeedInferiorDraw {
                leaf_id,
                src_x: sx,
                src_y: sy,
                dst_x: dx,
                dst_y: dy,
                width: rw as u32,
                height: rh as u32,
            });
        };
        if let Some(rects) = self.core.shape_bounding.get(&xid) {
            for r in rects {
                let (rx, ry) = (i32::from(r.x), i32::from(r.y));
                let (rw, rh) = (i32::from(r.width), i32::from(r.height));
                // Intersect the bound with the window box [0,w)×[0,h).
                let cx = rx.max(0);
                let cy = ry.max(0);
                #[allow(clippy::cast_possible_wrap)]
                let cw = (rx + rw).min(w as i32) - cx;
                #[allow(clippy::cast_possible_wrap)]
                let ch = (ry + rh).min(h as i32) - cy;
                if cw <= 0 || ch <= 0 {
                    continue;
                }
                emit(cx + src_bw, cy + src_bw, off_x + cx, off_y + cy, cw, ch);
            }
        } else {
            #[allow(clippy::cast_possible_wrap)]
            emit(src_bw, src_bw, off_x, off_y, w as i32, h as i32);
        }
    }

    /// Virtual-screen extent — mirrors `KmsBackend::fb_dimensions`.
    /// Called by `lib.rs` during the pre-`Box<dyn Backend>` setup
    /// (capability advertisement, `ServerState::with_randr_outputs`).
    #[must_use]
    pub fn fb_dimensions(&self) -> (u16, u16) {
        self.platform.fb_dimensions()
    }

    /// Startup pointer position — centre of the primary output (output 0),
    /// matching Xorg. Used by `lib.rs` to seed the libinput thread's cursor so
    /// it agrees with the core (which is seeded the same way at construction).
    #[must_use]
    pub fn initial_pointer_position(&self) -> (i32, i32) {
        let (fw, fh) = self.fb_dimensions();
        crate::kms::backend::primary_output_center(&self.platform.outputs, fw, fh)
    }

    /// Seed the stable RANDR connector registry from every opened DRM card.
    /// Startup scanout remains limited to the outputs activated during
    /// platform bring-up; connected secondary-card connectors are registered
    /// as available but off until a RANDR client enables them.
    fn seed_initial_connector_topology(&mut self) -> io::Result<()> {
        self.reserve_randr_provider_ids();

        // Preserve historical XID allocation order: active startup outputs
        // receive output/CRTC IDs before inactive secondary connectors.
        let live_keys: Vec<_> = self
            .platform
            .outputs
            .iter()
            .map(|layout| layout.key.clone())
            .collect();
        for key in &live_keys {
            let _ = self.randr_id_alloc.ids_for(key);
        }

        // Keep a lightweight all-connector pass for disconnected connector
        // XIDs/provider inventory, then enrich every connected entry from a
        // forced metadata snapshot. Gather both before mutating the registry,
        // so a failure on card N cannot leave a partially reconciled startup
        // view.
        let probes = self.platform.probe_all_connectors()?;
        let snapshots = self.platform.probe_connector_snapshot()?;
        self.seed_connector_topology_from_probes(&probes, &snapshots);
        Ok(())
    }

    /// Apply already-gathered startup probes. The cached pass reserves stable
    /// XIDs only; the forced connected-only snapshot is authoritative for
    /// connection, modes, and monitor metadata.
    fn seed_connector_topology_from_probes(
        &mut self,
        probes: &[(
            crate::platform::drm::DrmDeviceKey,
            Vec<crate::platform::drm::ConnectorProbe>,
        )],
        snapshots: &[ConnectorSnapshot],
    ) {
        for (device_key, connectors) in probes {
            for connector in connectors {
                let key = OutputKey::new(*device_key, connector.connector_name.clone());
                let _ = self.randr_id_alloc.ids_for(&key);
            }
        }
        // Entries seen only by cached inventory remain default-disconnected.
        let _ = self.reconcile_connector_registry(snapshots, &[], &[]);

        let live_configs: Vec<_> = self
            .platform
            .outputs
            .iter()
            .map(|layout| {
                (
                    layout.key.clone(),
                    ConnectorConfig::Enabled {
                        mode_w: layout.width,
                        mode_h: layout.height,
                        vrefresh: layout.output.picked.vrefresh,
                        x: layout.x,
                        y: layout.y,
                    },
                )
            })
            .collect();
        for (key, config) in live_configs {
            let entry = self.randr_id_alloc.entry_mut(&key);
            if entry.connected && !entry.modes.is_empty() {
                entry.config = config;
                entry.crtc_associated = true;
            }
        }
    }

    /// Reconcile a complete connected-output metadata snapshot from a heavy
    /// physical-topology boundary. Returns connector keys whose advertised
    /// connection, modes, or identity changed, so callers can avoid spurious
    /// RANDR config-timestamp bumps. Retiring an already-light-disconnected
    /// CRTC still clears its internal config below, but is deliberately not a
    /// second advertised-config delta.
    ///
    /// `dropped_layouts` carries the live rectangle of every route the
    /// connector snapshot removed. The registry's own `config` can be stale
    /// after an auto-layout repack (nothing writes `(x, y)` back to it), so
    /// the remembered route is taken from the layout that actually departed.
    fn reconcile_connector_registry(
        &mut self,
        connected: &[ConnectorSnapshot],
        dropped: &[OutputKey],
        dropped_layouts: &[crate::kms::render::platform::DroppedRoute],
    ) -> ConnectorRegistryDelta {
        let mut delta = ConnectorRegistryDelta::default();
        let connected_keys: HashSet<_> = connected.iter().map(|snapshot| &snapshot.key).collect();
        for key in dropped {
            let departed = dropped_layouts
                .iter()
                .find(|route| &route.key == key)
                .cloned();
            let entry = self.randr_id_alloc.entry_mut(key);
            if connected_keys.contains(key) {
                // Physically connected but no longer usable by the live CRTC
                // (for example, its current mode vanished). The connected
                // snapshot below owns advertised state; this arm retires only
                // the route policy, so do not fabricate a disconnect/reconnect
                // pair or a second config timestamp.
                entry.crtc_associated |= matches!(entry.config, ConnectorConfig::Enabled { .. });
                entry.config = ConnectorConfig::Off;
                entry.client_configured = false;
                // Not a physical departure — the connector is still here, it
                // just lost its route. There is nothing to relight on a
                // reconnect edge that will not come, and nothing to reserve.
                entry.last_enabled = None;
                continue;
            }
            // The connector physically departed. Remember the route it was
            // scanning out so the reconnect relights it without a client
            // request, and so its slot stays reserved meanwhile.
            if matches!(entry.config, ConnectorConfig::Enabled { .. })
                && let Some(route) = departed
            {
                entry.last_enabled = Some(ConnectorConfig::Enabled {
                    mode_w: route.width,
                    mode_h: route.height,
                    vrefresh: route.vrefresh,
                    x: route.x,
                    y: route.y,
                });
            }
            let config_changed = entry.connected;
            let output_changed = config_changed
                || !entry.edid.is_empty()
                || entry.mm_width != 0
                || entry.mm_height != 0;
            if output_changed {
                delta.changed_keys.push(key.clone());
            }
            delta.config_changed |= config_changed;
            entry.crtc_associated |= matches!(entry.config, ConnectorConfig::Enabled { .. });
            entry.connected = false;
            entry.config = ConnectorConfig::Off;
            entry.client_configured = false;
            // Retain stable mode resources and connector-owned type, but do
            // not project the departed monitor's identity while disconnected.
            entry.edid.clear();
            entry.mm_width = 0;
            entry.mm_height = 0;
        }
        for snapshot in connected {
            let entry = self.randr_id_alloc.entry_mut(&snapshot.key);
            let config_changed = !entry.connected || entry.modes != snapshot.modes;
            let output_changed = config_changed
                || entry.edid != snapshot.edid
                || entry.mm_width != snapshot.mm_width
                || entry.mm_height != snapshot.mm_height
                || entry.connector_type != snapshot.connector_type;
            if output_changed {
                delta.changed_keys.push(snapshot.key.clone());
            }
            delta.config_changed |= config_changed;
            entry.connected = true;
            entry.modes.clone_from(&snapshot.modes);
            entry.edid.clone_from(&snapshot.edid);
            entry.mm_width = snapshot.mm_width;
            entry.mm_height = snapshot.mm_height;
            entry.connector_type.clone_from(&snapshot.connector_type);
        }
        if !delta.is_empty() {
            self.bump_crtc_config_topology_epoch("connector registry changed");
        }
        delta
    }

    /// Merge cached connector-only results for an explicit RANDR query.
    /// This never mutates live KMS routing, but a changed client-visible
    /// registry is rebuilt and published immediately so a later debounced
    /// heavy snapshot cannot lose the corresponding disconnect notification.
    fn publish_connector_probes(
        &mut self,
        state: &mut ServerState,
        probes: &[(
            crate::platform::drm::DrmDeviceKey,
            Vec<crate::platform::drm::ConnectorProbe>,
        )],
    ) -> bool {
        let mut changed_keys = HashSet::new();
        let mut config_changed = false;
        for (device_key, connectors) in probes {
            let delta =
                reconcile_connector_probe(&mut self.randr_id_alloc, *device_key, connectors);
            changed_keys.extend(delta.changed_keys);
            config_changed |= delta.config_changed;
        }
        let changed = !changed_keys.is_empty();
        if changed {
            self.bump_crtc_config_topology_epoch("connector probe changed");
        }
        // A force query never advances lastSetTime. It advances lastConfigTime
        // for connection/mode-list changes and notifies dirty outputs for
        // those or monitor-identity invalidation.
        self.rebuild_randr_state(state, None, config_changed);
        if changed {
            let changed_ids: HashSet<_> = changed_keys
                .iter()
                .filter_map(|key| {
                    self.randr_id_alloc
                        .entry(key)
                        .map(|entry| entry.ids.output_id)
                })
                .collect();
            let mut changed_outputs: Vec<_> = state
                .randr
                .outputs
                .iter()
                .filter(|output| changed_ids.contains(&output.output_id))
                .map(|output| (output.output_id, output.crtc_id, output.mode_id))
                .collect();
            changed_outputs.sort_unstable_by_key(|&(output, _, _)| output);
            yserver_core::core_loop::run::emit_randr_connector_change_notifications(
                state,
                &[],
                &changed_outputs,
            );
        }
        changed
    }

    fn connector_registry_fingerprint(&self, device: DrmDeviceKey) -> ConnectorRegistryFingerprint {
        let mut connectors = self
            .randr_id_alloc
            .entries()
            .filter(|(key, _)| key.device_key == device)
            .map(|(key, entry)| {
                (
                    key.connector_name.clone(),
                    entry.connected,
                    entry
                        .modes
                        .iter()
                        .map(|mode| (mode.width, mode.height, mode.vrefresh, mode.preferred))
                        .collect(),
                )
            })
            .collect::<Vec<_>>();
        connectors.sort_unstable_by(|left, right| left.0.cmp(&right.0));
        connectors
    }

    /// RandR output list — mirrors `KmsBackend::randr_outputs`.
    #[must_use]
    pub fn randr_outputs(&mut self) -> Vec<yserver_core::randr::RandrOutput> {
        self.randr_outputs_and_modes().0
    }

    /// Provider endpoint used by the selected operational renderer.
    ///
    /// Vulkan primary-node metadata is diagnostic, not a KMS ownership
    /// claim. It coalesces the renderer with an existing KMS provider only
    /// when it exactly names an opened KMS device; every other selected
    /// renderer remains its own endpoint.
    fn selected_render_provider_endpoint(&self) -> Option<RandrProviderEndpoint> {
        let renderer = self.platform.selected_render_device()?;
        if let Some(primary) = renderer.advertised_primary_node
            && self
                .platform
                .devices
                .iter()
                .any(|device| device.key == primary)
        {
            return Some(RandrProviderEndpoint::Kms(primary));
        }
        Some(RandrProviderEndpoint::Render(renderer.id))
    }

    /// Resolve a provider XID only when its endpoint is still projected now.
    /// `RandrIdAllocator` deliberately retains historical IDs, so using its
    /// reverse lookup alone at a request boundary could revive a stale source
    /// or sink after a future renderer/provider topology change.
    fn current_provider_endpoint_for_id(&self, provider_id: u32) -> Option<RandrProviderEndpoint> {
        let endpoint = self.randr_id_alloc.provider_endpoint_for_id(provider_id)?;
        self.randr_provider_endpoints()
            .contains(&endpoint)
            .then_some(endpoint)
    }

    /// Whether the selected renderer is authorized to feed one KMS device.
    ///
    /// A coalesced renderer/KMS provider needs no self-association. Every
    /// distinct KMS sink must retain an explicit endpoint-level policy entry;
    /// the route's tri-state transport probe remains authoritative later when
    /// the scanout pool is allocated.
    fn provider_output_source_allows(
        &self,
        kms_device_key: crate::platform::drm::DrmDeviceKey,
    ) -> bool {
        let Some(source) = self.selected_render_provider_endpoint() else {
            return false;
        };
        let sink = RandrProviderEndpoint::Kms(kms_device_key);
        source == sink || self.provider_output_sources.get(&kms_device_key) == Some(&source)
    }

    /// Validate the routes committed during platform bring-up and initialize
    /// the one-shot automatic PRIME Output Source policy.
    ///
    /// Every opened KMS endpoint distinct from the selected renderer is
    /// recorded, even when it currently has no connector inventory. Provider
    /// projection remains capability-aware and hides such an association until
    /// a connector is discovered. This initializer is constructor-only: a
    /// later explicit detach removes the map entry permanently and ordinary
    /// RANDR rebuilds or connector disconnect/reconnect cycles never recreate
    /// it.
    fn initialize_provider_output_sources(&mut self) -> io::Result<()> {
        let Some(selected_renderer) = self.platform.selected_render_device() else {
            if self.platform.outputs.is_empty() {
                return Ok(());
            }
            return Err(io::Error::other(
                "active startup outputs exist without a selected renderer endpoint",
            ));
        };
        let selected_render_device_id = selected_renderer.id;
        let source = self
            .selected_render_provider_endpoint()
            .expect("selected renderer has a provider endpoint");

        for output in &self.platform.outputs {
            if output.scanout_route.render_device_id != selected_render_device_id {
                return Err(io::Error::other(format!(
                    "active startup output {} on {} records renderer {:?}, but the selected renderer is {:?}",
                    output.key.connector_name,
                    output.key.device_key,
                    output.scanout_route.render_device_id,
                    selected_render_device_id,
                )));
            }
            if output.scanout_route.kms_device_key != output.key.device_key {
                return Err(io::Error::other(format!(
                    "active startup output {} records KMS endpoint {}, but its owner is {}",
                    output.key.connector_name,
                    output.scanout_route.kms_device_key,
                    output.key.device_key,
                )));
            }
        }

        for device in &self.platform.devices {
            let sink = RandrProviderEndpoint::Kms(device.key);
            if sink == source {
                continue;
            }
            if let Some(&previous) = self.provider_output_sources.get(&device.key) {
                if previous != source {
                    return Err(io::Error::other(format!(
                        "automatic KMS sink {} has conflicting sources {previous:?} and {source:?}",
                        device.key,
                    )));
                }
                continue;
            }
            self.provider_output_sources.insert(device.key, source);
            log::info!(
                "PRIME Output Source: automatically associated sink {sink:?} -> source {source:?}",
            );
        }
        Ok(())
    }

    fn randr_provider_endpoints(&self) -> Vec<RandrProviderEndpoint> {
        let mut endpoints = Vec::with_capacity(self.platform.devices.len().saturating_add(1));
        if let Some(renderer) = self.selected_render_provider_endpoint() {
            endpoints.push(renderer);
        }
        for device in &self.platform.devices {
            let kms = RandrProviderEndpoint::Kms(device.key);
            if !endpoints.contains(&kms) {
                endpoints.push(kms);
            }
        }
        endpoints
    }

    fn reserve_randr_provider_ids(&mut self) {
        for endpoint in self.randr_provider_endpoints() {
            let _ = self.randr_id_alloc.provider_id_for(endpoint);
        }
    }

    fn kms_provider_name(device: &crate::kms::render::platform::KmsDevice) -> String {
        let Some(attached) = device.device.attached() else {
            return format!("DRM device {} (detached)", device.key);
        };
        std::path::Path::new(attached.path())
            .file_name()
            .and_then(std::ffi::OsStr::to_str)
            .unwrap_or_else(|| attached.path())
            .to_string()
    }

    fn render_provider_name(device: &crate::kms::render::platform::RenderDevice) -> String {
        if let Some(node) = &device.render_node {
            return node
                .path()
                .file_name()
                .and_then(std::ffi::OsStr::to_str)
                .map_or_else(|| node.path().display().to_string(), str::to_string);
        }
        match device.id {
            crate::kms::render::platform::RenderDeviceId::DrmRender(key) => {
                format!("drm-render-{key}")
            }
            crate::kms::render::platform::RenderDeviceId::UnverifiedFallback => {
                "vulkan-unverified".to_string()
            }
        }
    }

    /// Project opened KMS devices, the selected renderer, and persistent PRIME
    /// Output Source relationships into stable RANDR providers.
    ///
    /// The selected renderer coalesces with a KMS provider only when its
    /// advertised primary node exactly matches that KMS device. It advertises
    /// `SourceOutput`; distinct KMS endpoints with known connector inventory
    /// advertise only `SinkOutput`. Unselected metadata-only renderer inventory
    /// is not operational and is therefore omitted. KMS providers own every
    /// connector/CRTC XID allocated for their device, including connectors
    /// that are currently disconnected; a distinct render provider owns no
    /// display resources. Associations are the endpoint policy projected in
    /// both directions and never assert that a concrete DMA-BUF allocation is
    /// compatible.
    #[must_use]
    pub fn randr_providers(&mut self) -> Vec<yserver_core::randr::RandrProvider> {
        use yserver_core::randr::{RandrProvider, RandrProviderAssociation};
        use yserver_protocol::x11::randr::{
            PROVIDER_CAPABILITY_SINK_OUTPUT, PROVIDER_CAPABILITY_SOURCE_OUTPUT,
        };

        self.reserve_randr_provider_ids();
        let selected_endpoint = self.selected_render_provider_endpoint();
        let distinct_renderer = match selected_endpoint {
            Some(endpoint @ RandrProviderEndpoint::Render(_)) => self
                .platform
                .selected_render_device()
                .map(|device| (endpoint, Self::render_provider_name(device))),
            _ => None,
        };
        let endpoints = self.randr_provider_endpoints();
        let provider_ids: HashMap<_, _> = endpoints
            .iter()
            .copied()
            .map(|endpoint| {
                let id = self.randr_id_alloc.provider_id_for(endpoint);
                (endpoint, id)
            })
            .collect();
        let kms_with_connector_inventory: HashSet<_> = self
            .randr_id_alloc
            .entries()
            .map(|(key, _)| key.device_key)
            .collect();
        let mut associations_by_endpoint: HashMap<
            RandrProviderEndpoint,
            Vec<RandrProviderAssociation>,
        > = HashMap::new();
        if let Some(source) = selected_endpoint {
            for (&sink_key, &configured_source) in &self.provider_output_sources {
                let sink = RandrProviderEndpoint::Kms(sink_key);
                if configured_source != source
                    || sink == source
                    || !provider_ids.contains_key(&sink)
                    || !kms_with_connector_inventory.contains(&sink_key)
                {
                    continue;
                }
                let Some(&source_id) = provider_ids.get(&source) else {
                    continue;
                };
                let sink_id = provider_ids[&sink];
                associations_by_endpoint
                    .entry(sink)
                    .or_default()
                    .push(RandrProviderAssociation {
                        provider_id: source_id,
                        capability: PROVIDER_CAPABILITY_SOURCE_OUTPUT,
                    });
                associations_by_endpoint.entry(source).or_default().push(
                    RandrProviderAssociation {
                        provider_id: sink_id,
                        capability: PROVIDER_CAPABILITY_SINK_OUTPUT,
                    },
                );
            }
        }
        for associations in associations_by_endpoint.values_mut() {
            associations.sort_by_key(|association| association.provider_id);
        }

        let mut providers = Vec::with_capacity(endpoints.len());
        for device in &self.platform.devices {
            let endpoint = RandrProviderEndpoint::Kms(device.key);
            let provider_id = provider_ids[&endpoint];
            let mut crtcs = Vec::new();
            let mut outputs = Vec::new();
            for (key, entry) in self.randr_id_alloc.entries() {
                if key.device_key != device.key
                    || self.randr_id_alloc.device_is_withdrawn(key.device_key)
                {
                    continue;
                }
                crtcs.push(entry.ids.crtc_id);
                outputs.push(entry.ids.output_id);
            }
            crtcs.sort_unstable();
            outputs.sort_unstable();
            let capabilities = match selected_endpoint {
                Some(source) if source == endpoint => PROVIDER_CAPABILITY_SOURCE_OUTPUT,
                Some(_) if kms_with_connector_inventory.contains(&device.key) => {
                    PROVIDER_CAPABILITY_SINK_OUTPUT
                }
                _ => 0,
            };
            providers.push(RandrProvider {
                provider_id,
                name: Self::kms_provider_name(device),
                capabilities,
                is_gpu: selected_endpoint.is_some_and(|source| source != endpoint),
                crtcs,
                outputs,
                associations: associations_by_endpoint
                    .remove(&endpoint)
                    .unwrap_or_default(),
            });
        }
        if let Some((endpoint, name)) = distinct_renderer {
            providers.push(RandrProvider {
                provider_id: provider_ids[&endpoint],
                name,
                capabilities: PROVIDER_CAPABILITY_SOURCE_OUTPUT,
                is_gpu: false,
                crtcs: Vec::new(),
                outputs: Vec::new(),
                associations: associations_by_endpoint
                    .remove(&endpoint)
                    .unwrap_or_default(),
            });
        }
        providers.sort_by_key(|provider| provider.provider_id);
        providers
    }

    /// RandR outputs plus the full deduped mode table.
    #[must_use]
    pub fn randr_outputs_and_modes(
        &mut self,
    ) -> (
        Vec<yserver_core::randr::RandrOutput>,
        Vec<yserver_core::randr::RandrMode>,
    ) {
        use yserver_core::randr::{RandrMode, RandrOutput};

        // Provider ids share the same XID source as outputs, CRTCs, and modes
        // even before providers are exposed on the wire. Reserve every
        // projected endpoint now (selected renderer first, then deduplicated
        // KMS devices) so identities stay stable and collision-free.
        self.reserve_randr_provider_ids();

        // A lightweight disconnect leaves the registry config Enabled, so
        // the live CRTC remains projected while `connected` flips false. A
        // heavy drop (and a startup force-probe miss) sets config Off; do not
        // let a stale `platform.outputs` row revive that route.
        let live_keys: HashSet<OutputKey> =
            self.platform
                .outputs
                .iter()
                .filter(|layout| {
                    !self
                        .randr_id_alloc
                        .device_is_withdrawn(layout.key.device_key)
                        && self.randr_id_alloc.entry(&layout.key).is_none_or(|entry| {
                            matches!(entry.config, ConnectorConfig::Enabled { .. })
                        })
                })
                .map(|layout| layout.key.clone())
                .collect();
        let mut outs: Vec<RandrOutput> = Vec::with_capacity(
            self.platform.outputs.len() + self.randr_id_alloc.known_connectors().len(),
        );
        // Rebuild the per-output identity map (EDID + ConnectorType) each
        // projection so the output-property handlers serve current data.
        self.output_identity_by_id.clear();
        self.output_key_by_id.clear();
        self.crtc_key_by_id.clear();
        for layout in self
            .platform
            .outputs
            .iter()
            .filter(|layout| live_keys.contains(&layout.key))
        {
            let vrefresh = layout.output.picked.vrefresh;
            let output_key = layout.key.clone();
            let registry_entry_exists = self.randr_id_alloc.entry(&output_key).is_some();
            let ids = self.randr_id_alloc.ids_for(&output_key);
            let (connected, connector_modes, edid, mm_width, mm_height, connector_type) = {
                let entry = self.randr_id_alloc.entry_mut(&output_key);
                // Production seeds every connected connector from a heavy
                // snapshot before projection. Keep a defensive fallback for
                // synthetic fixtures which construct ActiveOutput directly.
                if !registry_entry_exists {
                    entry.modes.clone_from(&layout.output.modes);
                    entry.edid.clone_from(&layout.output.edid);
                    entry.mm_width = layout.output.mm_width;
                    entry.mm_height = layout.output.mm_height;
                    entry
                        .connector_type
                        .clone_from(&layout.output.connector_type);
                    entry.connected = true;
                    entry.config = ConnectorConfig::Enabled {
                        mode_w: layout.width,
                        mode_h: layout.height,
                        vrefresh,
                        x: layout.x,
                        y: layout.y,
                    };
                    entry.crtc_associated = true;
                }
                // A live KMS route is necessarily attached. This also seeds
                // fixtures whose registry entry predates the active-output
                // projection, before a later physical disconnect preserves
                // the association while retiring the route.
                entry.crtc_associated = true;
                (
                    entry.connected,
                    entry.modes.clone(),
                    entry.edid.clone(),
                    entry.mm_width,
                    entry.mm_height,
                    entry.connector_type.clone(),
                )
            };
            self.output_key_by_id
                .insert(ids.output_id, output_key.clone());
            self.crtc_key_by_id.insert(ids.crtc_id, output_key);
            let mode_id = self.randr_id_alloc.mode_id(&layout.output.picked);
            if connected {
                self.output_identity_by_id
                    .insert(ids.output_id, (edid, connector_type));
            }
            let mut mode_ids = Vec::with_capacity(connector_modes.len());
            let mut num_preferred: u16 = 0;
            for mode in &connector_modes {
                let mode_id = self.randr_id_alloc.mode_id(mode);
                // A connector can advertise the same exact resource more
                // than once. List each XID only once (issue #48).
                if mode_ids.contains(&mode_id) {
                    continue;
                }
                mode_ids.push(mode_id);
                if mode.preferred {
                    num_preferred = num_preferred.saturating_add(1);
                }
            }
            outs.push(RandrOutput {
                name: layout.output.connector_name.clone(),
                output_id: ids.output_id,
                crtc_id: ids.crtc_id,
                mode_id,
                connected,
                x: i16::try_from(layout.x).unwrap_or(i16::MAX),
                y: i16::try_from(layout.y).unwrap_or(i16::MAX),
                width: layout.width,
                height: layout.height,
                vrefresh,
                timing: mode_timing(&layout.output.picked),
                mm_width: if connected { mm_width } else { 0 },
                mm_height: if connected { mm_height } else { 0 },
                mode_ids,
                num_preferred,
                pending_transform: Default::default(),
                current_transform: Default::default(),
                rotation: 1,
            });
        }

        let advertised_modes: Vec<crate::platform::drm::Mode> = self
            .randr_id_alloc
            .entries()
            .filter(|(key, _)| !self.randr_id_alloc.device_is_withdrawn(key.device_key))
            .flat_map(|(_, entry)| entry.modes.clone())
            .collect();
        // A replacement monitor can omit the timing still programmed on a
        // live CRTC. Retain that current mode resource until a client selects
        // a replacement-advertised mode, avoiding a dangling mode XID.
        let current_modes: Vec<crate::platform::drm::Mode> = self
            .platform
            .outputs
            .iter()
            .filter(|layout| live_keys.contains(&layout.key))
            .map(|layout| layout.output.picked.clone())
            .collect();
        let mut modes: Vec<RandrMode> = Vec::new();
        let mut mode_identities = HashSet::new();
        for mode in current_modes.into_iter().chain(advertised_modes) {
            let identity = ModeIdentity::from(&mode);
            let mode_id = self.randr_id_alloc.mode_id(&mode);
            if mode_identities.insert(identity) {
                modes.push(RandrMode {
                    mode_id,
                    width: mode.width,
                    height: mode.height,
                    vrefresh: mode.vrefresh,
                    timing: mode_timing(&mode),
                });
            }
        }

        // Not-live (registered but not in `platform.outputs`) connectors.
        // Two sub-states, distinguished by the registry `connected` flag:
        //   - connected=true  → hotplugged but not yet enabled (Task 5.2):
        //     report RR_Connected with mode=0/crtc-unassigned so a client
        //     can enable it (GetOutputInfo offers the advertised modes).
        //   - connected=false → physically disconnected: RR_Disconnected.
        // Either way the last-known advertised mode list is retained so
        // GetOutputInfo stays consistent with the GetScreenResources union.
        // Collect owned first to release the &self borrow before the
        // &mut self mode_id() allocations below.
        let not_live: Vec<NotLiveConnector> = self
            .randr_id_alloc
            .entries()
            .filter(|(key, _)| {
                !live_keys.contains(*key)
                    && !self.randr_id_alloc.device_is_withdrawn(key.device_key)
            })
            .map(|(key, entry)| NotLiveConnector {
                key: key.clone(),
                ids: entry.ids,
                connected: entry.connected,
                modes: entry.modes.clone(),
                edid: entry.edid.clone(),
                mm_width: entry.mm_width,
                mm_height: entry.mm_height,
                connector_type: entry.connector_type.clone(),
            })
            .collect();
        for connector in not_live {
            let mut mode_ids = Vec::with_capacity(connector.modes.len());
            let mut num_preferred: u16 = 0;
            for mode in connector.modes {
                let mode_id = self.randr_id_alloc.mode_id(&mode);
                // See the live-output loop: list each exact XID once.
                if mode_ids.contains(&mode_id) {
                    continue;
                }
                mode_ids.push(mode_id);
                if mode.preferred {
                    num_preferred = num_preferred.saturating_add(1);
                }
            }
            self.output_key_by_id
                .insert(connector.ids.output_id, connector.key.clone());
            self.crtc_key_by_id
                .insert(connector.ids.crtc_id, connector.key.clone());
            if connector.connected {
                self.output_identity_by_id.insert(
                    connector.ids.output_id,
                    (connector.edid, connector.connector_type),
                );
            }
            outs.push(RandrOutput {
                name: connector.key.connector_name,
                output_id: connector.ids.output_id,
                crtc_id: connector.ids.crtc_id,
                mode_id: 0,
                connected: connector.connected,
                x: 0,
                y: 0,
                width: 0,
                height: 0,
                vrefresh: 0,
                timing: None,
                mm_width: if connector.connected {
                    connector.mm_width
                } else {
                    0
                },
                mm_height: if connector.connected {
                    connector.mm_height
                } else {
                    0
                },
                mode_ids,
                num_preferred,
                pending_transform: Default::default(),
                current_transform: Default::default(),
                rotation: yserver_core::randr::RR_ROTATE_0,
            });
        }
        outs.sort_by_key(|o| o.output_id);
        modes.sort_by_key(|m| m.mode_id);
        self.refresh_present_crtc_clock_epochs();
        (outs, modes)
    }

    /// The one place `state.randr` is rebuilt from the backend's
    /// registry/outputs.
    /// - `set_time`: `Some(t)` sets `timestamp` (lastSetTime) to `t`
    ///   (SetCrtcConfig uses the client-provided request timestamp);
    ///   `None` preserves the prior value (connector discovery and no-op
    ///   reprobes must not advance lastSetTime).
    /// - `config_changed`: advances `config_timestamp` (lastConfigTime)
    ///   only when the available config (outputs/modes/connection)
    ///   changed — i.e. hotplug/reprobe-with-change, NOT a CRTC set.
    ///
    /// The current logical screen size (`screen_width`/`screen_height`
    /// and `*_mm`) is OWNED by `RRSetScreenSize` once set and is carried
    /// forward across every rebuild — a re-probe or CRTC set never
    /// collapses a client-resized screen back to the bounding box
    /// (Xorg keeps `pScreen->width/height` until the client resizes).
    /// The extent the projection *derives* underneath that carry-forward
    /// covers the live outputs unioned with the slots still reserved by
    /// departed-but-restorable routes, so it never describes a screen that
    /// shrank around a monitor we are about to re-light.
    fn rebuild_randr_state(
        &mut self,
        state: &mut ServerState,
        set_time: Option<u32>,
        config_changed: bool,
    ) {
        let prev_ts = state.randr.timestamp;
        let prev_ct = state.randr.config_timestamp;
        let prev_primary = state.randr.primary_output;
        let prev_primary_explicit = state.randr_primary_output_explicit;
        // Snapshot the client-owned logical screen size to carry forward.
        let prev_screen = (
            state.randr.screen_width,
            state.randr.screen_height,
            state.randr.width_mm,
            state.randr.height_mm,
        );
        let prev_transforms = state.randr.crtc_transforms();
        let (outputs, mode_table) = self.randr_outputs_and_modes();
        let providers = self.randr_providers();
        let reserved = self.reserved_layout_slots();
        let new_ts = set_time.unwrap_or(prev_ts);
        let ts_now = state.timestamp_now();
        state.randr = yserver_core::randr::RandrState::from_outputs_with_modes_and_reservations(
            new_ts, outputs, mode_table, &reserved,
        );
        // CRTC transforms are client-owned, like the logical size below.
        state.randr.restore_crtc_transforms(prev_transforms);
        let associations = self
            .randr_id_alloc
            .entries()
            .filter(|(_, entry)| entry.crtc_associated)
            .map(|(_, entry)| (entry.ids.output_id, entry.ids.crtc_id));
        state.randr.set_output_crtc_associations(associations);
        state.randr.set_providers(providers);
        // Carry forward the client-set logical size (from_outputs reseeds
        // it to the bbox; that is only correct at boot, where prev_screen
        // already equals the bbox).
        state.randr.screen_width = prev_screen.0;
        state.randr.screen_height = prev_screen.1;
        state.randr.width_mm = prev_screen.2;
        state.randr.height_mm = prev_screen.3;
        // SetOutputPrimary is client-owned metadata. Keep it across a
        // topology rebuild while the output resource still exists, including
        // a temporarily disconnected output. If it vanished entirely, retain
        // from_outputs' best available fallback instead.
        state.randr_primary_output_explicit = restore_primary_output_after_rebuild(
            prev_primary,
            prev_primary_explicit,
            &mut state.randr,
        );
        state.randr.config_timestamp = if config_changed { ts_now } else { prev_ct };
    }

    pub(super) fn withdraw_outputs_for_device(&mut self, device: DrmDeviceKey) {
        if self
            .lifecycle_coordinator
            .device(&device)
            .is_some_and(|arbiter| {
                arbiter.state() == crate::kms::owner::lifecycle::DeviceLifecycleState::Removed
                    || arbiter.desired().device_presence() == Some(false)
            })
        {
            self.scene.withdraw_device_outputs(device);
        }
        let Some((output_ids, crtc_ids)) = self.randr_id_alloc.withdraw_device(device) else {
            return;
        };
        self.urgent_requesterless_publications.push_back(
            RequesterlessPublication::urgent_withdrawal(output_ids, crtc_ids),
        );
        self.wake_crtc_config_ready();
    }

    /// Telemetry accessor — used by the acceptance harness to
    /// read lifetime counters after driving a test sequence.
    #[must_use]
    pub fn telemetry(&self) -> &Telemetry {
        &self.telemetry
    }

    // ── Stage 5 Task 3 diagnostic instrumentation helpers ───────
    //
    // These exist purely to wire `YSERVER_SUBMIT_TRACE` event
    // recording at every `vkQueueSubmit2` site with minimal
    // per-site boilerplate. Zero hot-path cost when the env var
    // is unset (`Telemetry::record_submit_event` early-returns on
    // `submit_trace.is_none()`).

    /// Classify a v2 drawable by kind for the trace TSV's
    /// `target_kind` column. COW is held separately on
    /// `KmsBackend`; other kinds come from `DrawableKind`.
    fn submit_target_kind(&self, id: DrawableId) -> TargetKind {
        if self.cow_id == Some(id) {
            return TargetKind::Cow;
        }
        match self.store.get(id).map(|d| d.kind) {
            Some(DrawableKind::Root) => TargetKind::Root,
            Some(DrawableKind::Window) => TargetKind::Window,
            Some(DrawableKind::Pixmap) => TargetKind::Pixmap,
            Some(DrawableKind::Cursor) => TargetKind::Cursor,
            Some(DrawableKind::RedirectedBacking) => TargetKind::Backing,
            None => TargetKind::Unknown,
        }
    }

    /// Emit one trace event for a plain paint submit (no
    /// render-key info). One-liner helper for the ~12 sites
    /// that don't need op/src/mask plumbing.
    fn trace_simple(&mut self, kind: SubmitKind, target: DrawableId, batch_size: u32) {
        let target_kind = self.submit_target_kind(target);
        self.telemetry.record_submit_event(SubmitEvent {
            frame_id: 0,
            kind,
            target_kind,
            target_id: target.as_u64(),
            batch_size,
            op: SubmitOp::None,
            src_class: SrcClass::None,
            mask_class: SrcClass::None,
            pipeline_id: None,
            flags: SubmitFlags::NONE,
        });
    }

    /// Emit one trace event for a RENDER paint submit with full
    /// op + src/mask class info. `mask` of `None` writes
    /// `no_mask`; `Some(class)` writes the class.
    fn trace_render(
        &mut self,
        kind: SubmitKind,
        target: DrawableId,
        batch_size: u32,
        op_byte: u8,
        src: SrcClass,
        mask: Option<SrcClass>,
        flags: SubmitFlags,
    ) {
        let target_kind = self.submit_target_kind(target);
        self.telemetry.record_submit_event(SubmitEvent {
            frame_id: 0,
            kind,
            target_kind,
            target_id: target.as_u64(),
            batch_size,
            op: SubmitOp::from_pict_op_byte(op_byte),
            src_class: src,
            mask_class: mask.unwrap_or(SrcClass::NoMask),
            pipeline_id: None,
            flags,
        });
    }

    /// Classify a `PictureRecord` for the `src_class` /
    /// `mask_class` columns. Used by render-path call sites.
    fn picture_src_class(record: &PictureRecord) -> SrcClass {
        match record {
            PictureRecord::Drawable { .. } => SrcClass::Direct,
            PictureRecord::SolidFill { .. } => SrcClass::Solid,
            PictureRecord::LinearGradient { .. } => SrcClass::GradientLinear,
            PictureRecord::RadialGradient { .. } => SrcClass::GradientRadial,
        }
    }

    /// Lookup a picture xid in `core.pictures` and return its
    /// class, or `SrcClass::Direct` if the xid doesn't resolve
    /// (rare — render sites already guard on `resolve_*`; this
    /// is a defensive default for the diagnostic).
    fn picture_src_class_by_xid(&self, xid: u32) -> SrcClass {
        self.core
            .pictures
            .get(&xid)
            .map_or(SrcClass::Direct, Self::picture_src_class)
    }

    /// Stage 5 Task 3 POC: drain the engine's cow-batch flush
    /// records (since the last drain), bump telemetry counters,
    /// Drain the engine's queued submit/flush/frame-close records into
    /// telemetry. Runs at the end of every `maybe_composite` tick, including
    /// the dark (VT-away / DPMS-off) early returns: paint frames keep
    /// closing while dark, and `pending_flush_outcomes` has no cap, so an
    /// undrained dark period would grow it for as long as the display is off.
    fn drain_paint_submit_telemetry(&mut self) {
        self.drain_render_telemetry();
        // Phase A Task 3.5: drain SubmitGroup flush outcomes and
        // route each to the matching telemetry counter.
        for outcome in self.engine.drain_flush_outcomes() {
            if outcome.aborted {
                self.telemetry.record_submit_group_abort();
            } else {
                self.telemetry
                    .record_submit_group_flush(outcome.flushed_entries, outcome.reason);
            }
        }
        // Phase A telemetry retention gauges. Sample on every tick —
        // the high-water aggregator handles bursts.
        let pool_count =
            u64::try_from(self.engine.descriptor_pool_ring_pool_count()).unwrap_or(u64::MAX);
        self.telemetry
            .record_active_descriptor_pool_high_water(pool_count);
        let (staging_bytes, scratch_bytes) = self.engine.active_resource_bytes();
        self.telemetry
            .record_active_staging_high_water(staging_bytes);
        self.telemetry
            .record_active_scratch_high_water(scratch_bytes);
        // Phase B.1 Task 21: drain frame-builder close events into telemetry.
        self.drain_frame_builder_telemetry();
        // Per-second telemetry summary emission.
        self.telemetry.maybe_emit(self.engine.pending_count());
    }

    /// Stage 5 Task 3 (render-composite generalization): drain
    /// the engine's render-batch flush records, bump telemetry
    /// counters, emit one submit-trace event per flush.
    fn drain_render_telemetry(&mut self) {
        // Ahead of the early return below, and NOT at the GetImage call sites:
        // `engine.get_image` has a dozen callers and only two of them were
        // ever going to drain, so per-site draining both misattributed and
        // dropped readbacks (a session whose only reads are cursor-image ones
        // would report zero). Draining here — `maybe_composite`, ~60/s —
        // captures every site.
        if let Some(p) = self.engine.drain_get_image_phases() {
            self.telemetry
                .record_get_image_engine_phases(p.drain_ns, p.wait_ns, p.copyout_ns);
        }
        let records = self.engine.drain_render_flush_records();
        if records.is_empty() {
            return;
        }
        for rec in records {
            self.telemetry
                .record_render_batch_flushed(rec.coalesced_count);
            let target_kind = self.submit_target_kind(rec.dst);
            self.telemetry.record_submit_event(SubmitEvent {
                frame_id: 0,
                kind: SubmitKind::RenderComposite,
                target_kind,
                target_id: rec.dst.as_u64(),
                batch_size: rec.coalesced_count,
                op: SubmitOp::from_pict_op_byte(rec.op),
                src_class: SrcClass::Direct,
                mask_class: if rec.has_mask {
                    SrcClass::Direct
                } else {
                    SrcClass::NoMask
                },
                pipeline_id: None,
                flags: SubmitFlags::NONE,
            });
        }
    }

    /// Phase B.1 Task 21: drain queued `FrameCloseEvent`s into the
    /// per-second telemetry. Called from every site that drives a
    /// frame close (`maybe_composite`, `enqueue_present_completion`,
    /// `get_image`, `shutdown`/`disable_output`, `render_composite_glyphs`).
    ///
    /// Opens are delta-tracked via `last_drained_fb_opens` — the
    /// drain emits one `record_frame_builder_open` for each new open
    /// since the previous call without requiring a separate event queue.
    ///
    /// The drain is idempotent: calling it multiple times in a row is
    /// harmless (the event queue and delta are both empty after the
    /// first call).
    fn drain_frame_builder_telemetry(&mut self) {
        // Delta-track opens (FrameBuilder doesn't queue open events;
        // we infer them from the monotonic lifetime counter).
        let current_opens = self.engine.frame_builder_lifetime_opens();
        let delta_opens = current_opens.saturating_sub(self.last_drained_fb_opens);
        for _ in 0..delta_opens {
            self.telemetry.record_frame_builder_open();
        }
        self.last_drained_fb_opens = current_opens;

        // Drain the close-event queue.
        for event in self.engine.drain_frame_close_events() {
            if event.aborted {
                self.telemetry.record_frame_builder_abort();
            } else {
                self.telemetry.record_frame_builder_close(
                    event.reason,
                    event.ops_in_frame,
                    event.glyph_uploads_in_frame,
                    event.renders_in_frame,
                );
            }
            // Aborts also record pin_count high water — those pins existed
            // before the failure dropped them.
            self.telemetry.record_frame_builder_active_pins_high_water(
                u64::try_from(event.pin_count).unwrap_or(u64::MAX),
            );
        }
    }

    /// Phase B.2 Task 14 test helper: drive
    /// `drain_frame_builder_telemetry` from a test so the queued
    /// `FrameCloseEvent`s feed into lifetime counters without
    /// requiring a full main-loop tick. Mirrors the role of
    /// `telemetry_submit_group_flushes_for_tests` for the
    /// frame-close-event side of the telemetry pipeline.
    #[doc(hidden)]
    pub fn drain_frame_builder_telemetry_for_tests(&mut self) {
        self.drain_frame_builder_telemetry();
    }

    /// Stage 5 Task 4 layer 1: test-side accessor to the ring's
    /// pool residency. Used by the acceptance harness to assert
    /// steady-state pool count stays small after warm-up.
    #[doc(hidden)]
    #[must_use]
    pub fn descriptor_pool_ring_pool_count(&self) -> usize {
        self.engine.descriptor_pool_ring_pool_count()
    }

    /// Test-only accessor for the engine's per-drawable view cache
    /// size. Used by the live-Vk integration test that gates the
    /// `notify_drawable_retired` runtime-wiring fix: pre-fix a
    /// destroyed drawable's cached views accumulated until engine
    /// `Drop`; post-fix they're invalidated synchronously via
    /// `store_decref_with_invalidate` / `poll_pending_retire_with_invalidate`.
    #[doc(hidden)]
    #[must_use]
    pub fn drawable_view_cache_len(&self) -> usize {
        self.engine.drawable_view_cache_len()
    }

    /// Stage 5 Task 4 layer 1: test-side retirement driver. In
    /// production, retirement runs from `on_page_flip_ready` and
    /// invokes `engine.poll_retired` + `store.poll_pending_retire`.
    /// Pixmap-only test fixtures never drive a page flip, so the
    /// ring's recycle path can't run without this hook. The body
    /// mirrors the production sequence 1:1 so the acceptance harness
    /// exercises the same code paths any future store-retirement
    /// work would touch — and adds the telemetry sync call so ring
    /// delta counters land in `self.telemetry`.
    #[doc(hidden)]
    pub fn for_tests_poll_retired(&mut self) {
        self.engine.poll_retired(&self.platform);
        self.poll_pending_retire_with_invalidate();
        self.sync_descriptor_pool_telemetry();
    }

    /// Bridge `store.decref` to `engine.notify_drawable_retired`.
    /// When `decref` decides the drawable is destroyable, the
    /// closure fires BEFORE `Storage::destroy`, so any
    /// `VkImageView` cached in `RenderEngine::drawable_view_cache`
    /// for that `DrawableId` is destroyed while its underlying
    /// `VkImage` is still alive. Without this hook the cache
    /// accumulates entries pointing at freed images for the
    /// lifetime of the session (only swept at engine `Drop`).
    /// `DrawableId`s are monotonically allocated so stale entries
    /// can never alias a fresh drawable — the leak is memory-only,
    /// not use-after-free — but unbounded growth still matters.
    pub(crate) fn store_decref_with_invalidate(
        &mut self,
        id: crate::kms::render::store::DrawableId,
    ) -> crate::kms::render::store::RetireDecision {
        let engine = &mut self.engine;
        let scanout_m1 = &mut self.scanout_m1;
        self.store.decref(&mut self.platform, id, |dropped| {
            engine.notify_drawable_retired(dropped);
            scanout_m1.remove(dropped);
        })
    }

    /// Allocate a fresh store entry and apply any deferred picture
    /// refs that were waiting for this xid's backing to materialize.
    /// Every production backing-materialization path goes through
    /// this so pictures created before the backing existed still pin
    /// it (see [`Self::apply_pending_picture_refs`]).
    fn store_alloc(
        &mut self,
        xid: u32,
        kind: DrawableKind,
        depth: u8,
        scene_participating: bool,
        storage: Storage,
    ) -> Result<DrawableId, AllocError> {
        let id = self
            .store
            .allocate(xid, kind, depth, scene_participating, storage)?;
        self.apply_pending_picture_refs(xid);
        Ok(id)
    }

    /// Apply the deferred store refs for pictures that wrapped
    /// `host_xid` before its backing existed. Called after every
    /// successful materialization (`store_alloc`). A picture created
    /// early (window map + redirect before backing alloc, GLX-TFP /
    /// Present / DRI3 import) must still pin the backing once it
    /// appears, or a later `free_pixmap` reaches refcount 0 and
    /// destroys the drawable out from under the live Picture —
    /// the game-start transparency bug.
    pub(crate) fn apply_pending_picture_refs(&mut self, host_xid: u32) {
        let pending: Vec<u32> = self
            .pending_picture_drawable_refs
            .iter()
            .filter(|(_, x)| **x == host_xid)
            .map(|(pic, _)| *pic)
            .collect();
        if pending.is_empty() {
            return;
        }
        let Some(id) = self.store.lookup(host_xid) else {
            return;
        };
        for pic in pending {
            self.pending_picture_drawable_refs.remove(&pic);
            self.store.incref(id);
            self.picture_drawable_ids.insert(pic, id);
        }
    }

    // ── GLX-TFP (Tasks 2.3 + 2.4): exported-backing lifetime ─────────

    /// Ensure an `ExportedBacking` entry exists for `id`, taking the
    /// single backing lifetime ref on first creation. Idempotent.
    ///
    /// Spelled as an explicit `contains_key` → take-ref → `insert` →
    /// `get_mut` rather than `entry().or_insert_with(..)` because taking
    /// the lifetime ref needs `&mut self` (alias_registry / store), which
    /// would conflict with an `entry` borrow of `self.exported_dmabufs`.
    fn ensure_exported_entry(
        &mut self,
        id: crate::kms::render::store::DrawableId,
        backing: PixmapHandle,
    ) -> &mut ExportedBacking {
        if !self.exported_dmabufs.contains_key(&id) {
            // ONE lifetime ref per backing, released exactly once in teardown.
            let via_alias = self.take_backing_lifetime_ref(id, backing);
            self.exported_dmabufs.insert(
                id,
                ExportedBacking {
                    fd: None,
                    glx_refs: 0,
                    lifetime_ref_held: true,
                    backing_id: id,
                    backing,
                    lifetime_via_alias: via_alias,
                },
            );
        }
        self.exported_dmabufs
            .get_mut(&id)
            .expect("entry just ensured")
    }

    /// Take ONE lifetime ref on the backing's owning counter so the
    /// storage survives an early `FreePixmap` while a GL consumer still
    /// references it. Returns `true` if the ref was taken on
    /// `alias_registry` (NameWindowPixmap'd redirect backing), `false`
    /// if on the `DrawableStore` refcount (plain pixmap).
    fn take_backing_lifetime_ref(
        &mut self,
        id: crate::kms::render::store::DrawableId,
        backing: PixmapHandle,
    ) -> bool {
        if self.core.alias_registry.get(backing).is_some() {
            self.core.alias_registry.incref(backing);
            true
        } else {
            self.store.incref(id);
            false
        }
    }

    /// Release the single lifetime ref taken in `take_backing_lifetime_ref`.
    /// Routes to the counter recorded at take time. For the alias path a
    /// final decref frees the backing via the same release path
    /// `free_pixmap` uses; for the plain path the store decref frees the
    /// storage when its own refcount also hits zero.
    fn release_backing_lifetime_ref(&mut self, entry: &ExportedBacking) {
        if entry.lifetime_via_alias {
            // Alias path: decref the registry (keyed by xid); on final ref
            // free the backing via the same store decref `free_pixmap` uses.
            if self.core.alias_registry.decref(entry.backing) {
                self.store_decref_with_invalidate(entry.backing_id);
            }
        } else {
            // Plain path: drop the extra store ref taken at acquire time.
            // Use the captured DrawableId — the `by_xid` mapping may have
            // been detached by an intervening FreePixmap (PendingFence).
            self.store_decref_with_invalidate(entry.backing_id);
        }
    }

    /// `export holders` rows: drawables in exportable memory or with an export entry, plus orphaned entries.
    pub(crate) fn export_holder_rows(&self) -> Vec<crate::kms::render::export_holders::HolderRow> {
        use crate::kms::{
            render::export_holders::{ExportRow, HolderRow, StoreRow},
            vk::mem_accounting::{self, MemCategory},
        };
        let export_row = |e: &ExportedBacking| ExportRow {
            glx_refs: e.glx_refs,
            dri3_fd: e.fd.is_some(),
            lifetime_held: e.lifetime_ref_held,
            lifetime_via_alias: e.lifetime_via_alias,
        };
        let mut pictures: HashMap<crate::kms::render::store::DrawableId, u32> = HashMap::new();
        for id in self.picture_drawable_ids.values() {
            *pictures.entry(*id).or_default() += 1;
        }
        let redirect_of: HashMap<u32, u32> = self
            .core
            .host_window_to_backing
            .iter()
            .map(|(&w, b)| (b.as_raw(), w))
            .collect();
        let mut rows = Vec::new();
        for d in self.store.drawables() {
            let entry = mem_accounting::entry_of(d.storage.memory);
            let export = self.exported_dmabufs.get(&d.id);
            let export_mem = matches!(
                entry,
                Some((_, MemCategory::RedirectExport | MemCategory::TfpExport))
            );
            if !export_mem && export.is_none() {
                continue;
            }
            let attached = self.store.lookup(d.xid) == Some(d.id);
            let handle = PixmapHandle::from_raw(d.xid);
            rows.push(HolderRow {
                host_xid: d.xid,
                store: Some(StoreRow {
                    drawable_id: d.id.as_u64(),
                    category: entry.map(|(_, c)| c),
                    width: d.storage.extent.width,
                    height: d.storage.extent.height,
                    bytes: entry.map_or(0, |(b, _)| b),
                    refcount: d.refcount,
                    pending_retire: self.store.is_pending_retire(d.id),
                    xid_attached: attached,
                    pictures: pictures.get(&d.id).copied().unwrap_or(0),
                }),
                alias_refcount: handle
                    .filter(|_| attached)
                    .and_then(|h| self.core.alias_registry.get(h))
                    .map(|a| a.refcount),
                export: export.map(export_row),
                sync_dup: self.store.is_exported(d.id),
                redirect_of: redirect_of.get(&d.xid).copied().filter(|_| attached),
            });
        }
        for (id, e) in &self.exported_dmabufs {
            if self.store.get(*id).is_none() {
                rows.push(HolderRow {
                    host_xid: e.backing.as_raw(),
                    store: None,
                    alias_refcount: None,
                    export: Some(export_row(e)),
                    sync_dup: self.store.is_exported(*id),
                    redirect_of: None,
                });
            }
        }
        rows
    }

    /// GLX-TFP (Task 3.4 callers): record that a GLXPixmap now references
    /// the export of `host_xid`. Creates the entry (+ lifetime ref) if
    /// this is the first arrival. Public so the GLX protocol surface can
    /// call it. No-op on an unknown xid.
    pub fn acquire_glx_pixmap_export(&mut self, host_xid: u32) {
        let Some(id) = self.store.lookup(host_xid) else {
            return;
        };
        let Some(backing) = PixmapHandle::from_raw(host_xid) else {
            return;
        };
        let entry = self.ensure_exported_entry(id, backing);
        entry.glx_refs += 1;
    }

    /// GLX-TFP (Task 3.4 callers): a GLXPixmap referencing the export of
    /// `host_xid` is gone. Drops one `glx_refs` and tears the export down
    /// when it reaches zero.
    pub fn release_glx_pixmap_export(&mut self, host_xid: u32) {
        let Some(id) = self.store.lookup(host_xid) else {
            return;
        };
        if let Some(e) = self.exported_dmabufs.get_mut(&id) {
            e.glx_refs = e.glx_refs.saturating_sub(1);
        }
        self.maybe_teardown_export(id);
    }

    /// GLX-TFP: tear the export down iff no GLX consumer references it
    /// (`glx_refs == 0`). Drops the dup'd fd, clears the store's sync-fd
    /// dup, and releases the single lifetime ref. While `glx_refs > 0`
    /// this is a no-op (defer-destroy-while-referenced). There is NO
    /// `x_pixmap_freed` flag — an early `FreePixmap` is bridged by the
    /// lifetime ref and resolved here once `glx_refs` hits 0.
    fn maybe_teardown_export(&mut self, id: crate::kms::render::store::DrawableId) {
        let ready = matches!(self.exported_dmabufs.get(&id), Some(e) if e.glx_refs == 0);
        if !ready {
            return;
        }
        if let Some(e) = self.exported_dmabufs.remove(&id) {
            // Drop the store's parallel sync-fd dup so no write can be
            // routed through a torn-down export.
            self.store.clear_exported_sync_fd(id);
            // `e.fd` (our dup) closes on drop; the kernel buffer survives
            // while any GL consumer still holds its own fd.
            if e.lifetime_ref_held {
                self.release_backing_lifetime_ref(&e);
            }
        }
    }

    /// GLX-TFP (Task 3.5 `glXBindTexImageEXT`): promote the backing for
    /// `host_xid` to dma-buf-exportable storage, idempotently, WITHOUT
    /// touching `glx_refs` or `exported_dmabufs` (no fd alloc/export).
    /// Returns whether the backing is exportable after the call.
    ///
    /// This is the lightweight bind hook — distinct from
    /// `acquire_glx_pixmap_export` (which manages the GLXPixmap LIFETIME
    /// ref). Binds happen repeatedly (per-frame); coupling them to the
    /// lifetime refcount would leak the backing. The engine's
    /// `promote_drawable_exportable` short-circuits via `is_exportable()`
    /// so repeated binds cost nothing after the first.
    pub fn promote_pixmap_exportable(&mut self, host_xid: u32) -> bool {
        let Some(id) = self.store.lookup(host_xid) else {
            return false;
        };
        // Already exportable → idempotent no-op (the common rebind case).
        if self
            .store
            .get(id)
            .map(|d| d.is_exportable(self.resource_service.as_mut()))
            .unwrap_or(false)
        {
            return true;
        }
        // First bind: promote. Requires Vulkan; if unavailable, report
        // not-exportable rather than erroring (bind still succeeds at the
        // protocol layer — see process_request's BindTexImageEXT TODO).
        if self.platform.vk.is_none() {
            return false;
        }
        // Real promotion (past the is_exportable no-op above) → 1 SyncBoundary
        // flush inside engine.promote_drawable_exportable. Counted for the
        // gkrellm submit-storm attribution (project_client_scheduling_fairness).
        self.telemetry.record_promote_exportable_run();
        match self.engine.promote_drawable_exportable(
            &mut self.platform,
            &mut self.store,
            self.resource_service.as_mut(),
            id,
        ) {
            Ok(()) => self
                .store
                .get(id)
                .map(|d| d.is_exportable(self.resource_service.as_mut()))
                .unwrap_or(false),
            Err(e) => {
                log::warn!("GLX BindTexImageEXT promote 0x{host_xid:x} failed: {e:?}");
                false
            }
        }
    }

    /// GLX-TFP test introspection: true iff `host_xid` currently has an
    /// `ExportedBacking` entry.
    #[doc(hidden)]
    pub fn has_export_entry(&self, host_xid: u32) -> bool {
        self.store
            .lookup(host_xid)
            .is_some_and(|id| self.exported_dmabufs.contains_key(&id))
    }

    /// Bridge `store.poll_pending_retire` to
    /// `engine.notify_drawable_retired`. Per the rationale on
    /// `store_decref_with_invalidate`, drawables that were
    /// parked in `pending_retire` (waiting for their fence to
    /// signal) get their engine-side view caches dropped before
    /// `Storage::destroy` runs.
    pub(crate) fn poll_pending_retire_with_invalidate(&mut self) {
        let engine = &mut self.engine;
        let scanout_m1 = &mut self.scanout_m1;
        self.store
            .poll_pending_retire(&mut self.platform, |dropped| {
                engine.notify_drawable_retired(dropped);
                scanout_m1.remove(dropped);
            });
    }

