    #[test]
    fn xi_dynamic_pointer_mapping_cleanup_releases_the_held_logical_button() {
        use yserver_core::{
            backend::Backend,
            core_loop::{HostInputEvent, InputOrigin},
            server::ServerState,
            xinput::{InputSourceId, XiFacetKind},
        };
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        const SOURCE: InputSourceId = InputSourceId(0xA203);
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let _peer = kbd_map_client_id(&mut state, 73);
        // PickPointer is the ten-button CorePointer (`dix/devices.c:662-690`),
        // so SetPointerMapping must supply all ten entries.
        let mapping = [3u8, 2, 1, 4, 5, 6, 7, 8, 9, 10];
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend as &mut dyn Backend,
            ClientId(73),
            SequenceNumber(1),
            RequestHeader {
                opcode: 116,
                data: u8::try_from(mapping.len()).unwrap(),
                length_units: 4,
            },
            &mapping,
            None,
        )
        .expect("SetPointerMapping through process_request");
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(dynamic_test_device(SOURCE, false, true)),
        );
        let device_id = state
            .xi_devices
            .facet(SOURCE, XiFacetKind::PointerTouch)
            .expect("DeviceAdded publishes the pointer facet");

        backend.on_host_input(
            &mut state,
            HostInputEvent::PointerButton {
                origin: InputOrigin::Physical(SOURCE),
                button: 0x110, // physical Button1 maps to logical Button3
                pressed: true,
                time: 0,
            },
        );
        assert_eq!(
            state.xi_devices.device(device_id).unwrap().buttons_down,
            1 << 2
        );
        assert_eq!(state.buttons_down, 1 << 2);

        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceRemoved { source_id: SOURCE },
        );

        assert!(state.xi_devices.source(SOURCE).is_none());
        assert!(state.xi_devices.device(device_id).is_none());
        assert_eq!(
            state.buttons_down, 0,
            "the logical master Button3 hold is released"
        );
        assert!(state.sync_pending.is_empty());
        assert!(!state.xi2_pointer_grabs.contains_key(&device_id));
        assert!(!state.xi2_detached_masters.contains_key(&device_id));
    }

    #[test]
    fn xtest_key_input_to_a_floating_keyboard_does_not_change_master_state() {
        use yserver_core::{
            backend::Backend,
            core_loop::{HostInputEvent, InputOrigin},
            host_x11::HostKeyEvent,
            server::ServerState,
            xinput::{InputSourceId, XiFacetKind},
        };

        const FLOATING: InputSourceId = InputSourceId(0xA204);
        const ATTACHED: InputSourceId = InputSourceId(0xA205);
        const CLIENT: u32 = 74;
        const KEYCODE: u8 = 38;
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut peer = kbd_map_client_id(&mut state, CLIENT);
        for source in [FLOATING, ATTACHED] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(dynamic_test_device(source, true, false)),
            );
        }
        let floating_id = state
            .xi_devices
            .facet(FLOATING, XiFacetKind::Keyboard)
            .unwrap();
        let attached_id = state
            .xi_devices
            .facet(ATTACHED, XiFacetKind::Keyboard)
            .unwrap();
        backend.on_host_input(
            &mut state,
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(FLOATING),
                pressed: true,
                keycode: 50,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            }),
        );
        process_dynamic_test_keyboard_grab(&mut backend, &mut state, CLIENT, floating_id, 1);
        let _ = kbd_map_drain(&mut peer);

        let key = |origin, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin,
                pressed,
                keycode: KEYCODE,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        backend.on_host_input(&mut state, key(InputOrigin::XTest(floating_id), true));
        let master_key_bit = 1u8 << (KEYCODE % 8);
        assert_eq!(
            state.keys_down[usize::from(KEYCODE / 8)] & master_key_bit,
            0,
            "XTEST's floating slave key is absent from QueryKeymap's master bitmap",
        );
        assert!(
            backend.floating_keyboard_states[&floating_id]
                .down_keys
                .contains(&KEYCODE)
        );
        assert!(state.key_down_by_device[&floating_id].contains_key(&KEYCODE));

        backend.on_host_input(&mut state, key(InputOrigin::Physical(ATTACHED), true));
        assert!(
            backend.core.down_keys.contains(&KEYCODE),
            "the next attached keyboard press is accepted by the master XKB state",
        );
        assert!(state.key_down_by_device[&attached_id].contains_key(&KEYCODE));
        assert!(state.xi2_keyboard_grabs.contains_key(&floating_id));
        assert_eq!(
            state
                .xi_devices
                .device(floating_id)
                .unwrap()
                .attached_master,
            None
        );
        assert!(state.sync_pending.is_empty());

        backend.on_host_input(&mut state, key(InputOrigin::Physical(ATTACHED), false));
        backend.on_host_input(&mut state, key(InputOrigin::XTest(floating_id), false));
        assert!(!state.key_down_by_device.contains_key(&attached_id));
        assert!(
            !state
                .key_down_by_device
                .get(&floating_id)
                .is_some_and(|held| held.contains_key(&KEYCODE))
        );
    }

    #[test]
    fn record_contains_only_accepted_master_key_and_button_transitions() {
        use yserver_core::{
            backend::Backend,
            core_loop::{HostInputEvent, InputOrigin},
            host_x11::HostKeyEvent,
            server::ServerState,
            xinput::InputSourceId,
        };

        const A_KBD: InputSourceId = InputSourceId(0xA206);
        const B_KBD: InputSourceId = InputSourceId(0xA207);
        const A_PTR: InputSourceId = InputSourceId(0xA208);
        const B_PTR: InputSourceId = InputSourceId(0xA209);
        const FLOATING_KBD: InputSourceId = InputSourceId(0xA20B);
        const GRAB_CLIENT: u32 = 76;
        const KEYCODE: u8 = 38;
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut peer = kbd_map_client_id(&mut state, 5);
        let mut grab_peer = kbd_map_client_id(&mut state, GRAB_CLIENT);

        // RECORD CreateContext(ctx=1, FutureClients, core KeyPress..ButtonRelease)
        // followed by EnableContext, through the normal request dispatcher.
        let mut create = Vec::new();
        for word in [1u32, 0, 1, 1, 2] {
            create.extend_from_slice(&word.to_le_bytes());
        }
        create.extend_from_slice(&[0; 18]);
        create.extend_from_slice(&[2, 5, 0, 0, 0, 0]);
        kbd_map_request(&mut state, &mut backend, 154, 1, &create);
        kbd_map_request(&mut state, &mut backend, 154, 5, &1u32.to_le_bytes());
        let _ = kbd_map_drain(&mut peer);

        for (source, keyboard, pointer) in [
            (A_KBD, true, false),
            (B_KBD, true, false),
            (A_PTR, false, true),
            (B_PTR, false, true),
            (FLOATING_KBD, true, false),
        ] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(dynamic_test_device(source, keyboard, pointer)),
            );
        }
        let key = |source, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(source),
                pressed,
                keycode: KEYCODE,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        backend.on_host_input(&mut state, key(A_KBD, true));
        backend.on_host_input(&mut state, key(B_KBD, true));
        backend.on_host_input(&mut state, key(A_KBD, false));
        backend.on_host_input(&mut state, key(B_KBD, false));
        let bytes = kbd_map_drain(&mut peer);
        let mut key_records = Vec::new();
        let mut at = 0usize;
        while at + 32 <= bytes.len() {
            let words = u32::from_le_bytes(bytes[at + 4..at + 8].try_into().unwrap()) as usize;
            let len = 32 + words * 4;
            assert!(at + len <= bytes.len(), "complete RECORD stream element");
            if bytes[at] == 1 && bytes[at + 1] == 0 {
                let event = &bytes[at + 32..at + len];
                if matches!(event[0], 2 | 3) {
                    key_records.push((event[0], event[1]));
                }
            }
            at += len;
        }
        assert_eq!(key_records, [(2, KEYCODE), (3, KEYCODE)]);

        let floating_id = state
            .xi_devices
            .facet(FLOATING_KBD, yserver_core::xinput::XiFacetKind::Keyboard)
            .unwrap();
        process_dynamic_test_keyboard_grab(&mut backend, &mut state, GRAB_CLIENT, floating_id, 1);
        let _ = kbd_map_drain(&mut grab_peer);
        for pressed in [true, false] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::Key(HostKeyEvent {
                    origin: InputOrigin::XTest(floating_id),
                    pressed,
                    keycode: KEYCODE,
                    time: 0,
                    root_x: 0,
                    root_y: 0,
                    event_x: 0,
                    event_y: 0,
                    state: 0,
                }),
            );
        }
        let bytes = kbd_map_drain(&mut peer);
        let mut floating_key_records = Vec::new();
        let mut at = 0usize;
        while at + 32 <= bytes.len() {
            let words = u32::from_le_bytes(bytes[at + 4..at + 8].try_into().unwrap()) as usize;
            let len = 32 + words * 4;
            assert!(at + len <= bytes.len(), "complete RECORD stream element");
            if bytes[at] == 1 && bytes[at + 1] == 0 {
                let event = &bytes[at + 32..at + len];
                if matches!(event[0], 2 | 3) {
                    floating_key_records.push((event[0], event[1]));
                }
            }
            at += len;
        }
        assert!(
            floating_key_records.is_empty(),
            "floating slave key edges have no core RECORD forms",
        );

        let button = |source, pressed| HostInputEvent::PointerButton {
            origin: InputOrigin::Physical(source),
            button: 0x110,
            pressed,
            time: 0,
        };
        backend.on_host_input(&mut state, button(A_PTR, true));
        backend.on_host_input(&mut state, button(B_PTR, true));
        backend.on_host_input(&mut state, button(A_PTR, false));
        backend.on_host_input(&mut state, button(B_PTR, false));
        let bytes = kbd_map_drain(&mut peer);
        let mut button_records = Vec::new();
        let mut at = 0usize;
        while at + 32 <= bytes.len() {
            let words = u32::from_le_bytes(bytes[at + 4..at + 8].try_into().unwrap()) as usize;
            let len = 32 + words * 4;
            assert!(at + len <= bytes.len(), "complete RECORD stream element");
            if bytes[at] == 1 && bytes[at + 1] == 0 {
                let event = &bytes[at + 32..at + len];
                if matches!(event[0], 4 | 5) {
                    button_records.push((event[0], event[1]));
                }
            }
            at += len;
        }
        assert_eq!(button_records, [(4, 1), (5, 1)]);
        assert_eq!(state.buttons_down, 0);
        assert!(state.key_down_by_device.is_empty());
        assert!(state.sync_pending.is_empty());
    }

    /// Nested host keys produce master-only XI2 raw/device events. Their
    /// sourceid is the master keyboard itself (3), never the virtual XTEST
    /// keyboard (5). Raw remains before the device event with the same
    /// timestamp, matching Xorg's GetKeyboardEvents ordering.
    #[test]
    fn device_key_emits_raw_key_events_before_the_device_event() {
        use yserver_core::{
            core_loop::HostInputEvent, host_x11::HostKeyEvent, resources::ROOT_WINDOW,
            server::ServerState,
        };
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut peer = kbd_map_client_id(&mut state, 9);
        let client = state.clients.get_mut(&9).unwrap();
        client
            .xi2_masks
            .insert((ROOT_WINDOW, 1), (1 << 13) | (1 << 14));
        client
            .xi2_masks
            .insert((ROOT_WINDOW, 3), (1 << 2) | (1 << 3));
        let key = |pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: yserver_core::core_loop::InputOrigin::NestedHost,
                keycode: 71, // F5, as in the report
                pressed,
                state: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                time: 0,
            })
        };

        b.on_host_input(&mut state, key(true));
        b.on_host_input(&mut state, key(false));

        let events = xi2_events(&kbd_map_drain(&mut peer));
        let kinds: Vec<_> = events.iter().map(|e| (e.0, e.1, e.2, e.3)).collect();
        assert_eq!(
            kinds,
            vec![(13, 3, 3, 71), (2, 3, 3, 71), (14, 3, 3, 71), (3, 3, 3, 71)],
            "nested RawKeyPress, KeyPress, RawKeyRelease, KeyRelease"
        );
        assert_eq!(
            events[0].4, events[1].4,
            "raw press and KeyPress share one time"
        );
        assert_eq!(
            events[2].4, events[3].4,
            "raw release and KeyRelease share one time"
        );
    }

    #[test]
    fn key_source_routing_kms_preserves_facets_and_drops_unknown_before_xkb() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const RAZER: InputSourceId = InputSourceId(0xA11);
        const HYPERX: InputSourceId = InputSourceId(0xA12);
        const RETIRED: InputSourceId = InputSourceId(0xA13);

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.core_focus.raw = ROOT_WINDOW.0;

        let key = |origin, keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin,
                keycode,
                pressed,
                time: 0,
                root_x: 10,
                root_y: 20,
                event_x: 10,
                event_y: 20,
                state: 0,
            })
        };
        let device_info = |source_id, name: &str| DeviceInfo {
            source_id,
            enabled: true,
            resume_key: None,
            capabilities: InputCapabilities {
                keyboard: true,
                pointer: false,
                touch: false,
            },
            name: name.to_owned(),
            device_node: format!("/dev/input/{name}"),
            sysname: name.to_owned(),
            vendor_id: 0,
            product_id: 0,
            is_touchpad: false,
            config: LibinputConfigSnapshot::default(),
        };

        Backend::on_host_input(
            &mut backend,
            &mut state,
            HostInputEvent::DeviceAdded(device_info(RETIRED, "Retired keyboard")),
        );
        Backend::on_host_input(
            &mut backend,
            &mut state,
            HostInputEvent::DeviceRemoved { source_id: RETIRED },
        );

        // An unknown source must not reach raw fanout or advance KMS/XKB.
        let initial_modifiers = backend.serialize_modifiers();
        Backend::on_host_input(
            &mut backend,
            &mut state,
            key(InputOrigin::Physical(RETIRED), 50, true),
        );
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert_eq!(backend.serialize_modifiers(), initial_modifiers);

        for (source_id, name) in [(RAZER, "Razer"), (HYPERX, "HyperX")] {
            Backend::on_host_input(
                &mut backend,
                &mut state,
                HostInputEvent::DeviceAdded(device_info(source_id, name)),
            );
        }
        let razer_id = state
            .xi_devices
            .facet(RAZER, XiFacetKind::Keyboard)
            .expect("Razer keyboard facet");
        let hyperx_id = state
            .xi_devices
            .facet(HYPERX, XiFacetKind::Keyboard)
            .expect("HyperX keyboard facet");
        assert_ne!(razer_id, hyperx_id);

        let suspended_info = device_info(HYPERX, "HyperX");
        Backend::on_host_input(
            &mut backend,
            &mut state,
            HostInputEvent::DeviceSuspended { source_id: HYPERX },
        );
        let suspended_modifiers = backend.serialize_modifiers();
        Backend::on_host_input(
            &mut backend,
            &mut state,
            key(InputOrigin::Physical(HYPERX), 50, true),
        );
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert_eq!(backend.serialize_modifiers(), suspended_modifiers);
        Backend::on_host_input(
            &mut backend,
            &mut state,
            HostInputEvent::DeviceResumed(suspended_info),
        );
        assert!(state.xi_devices.source(HYPERX).unwrap().enabled);
        assert_eq!(
            state.xi_devices.facet(HYPERX, XiFacetKind::Keyboard),
            Some(hyperx_id),
            "resume preserves the same facet ID"
        );

        for source_id in [RAZER, HYPERX] {
            Backend::on_host_input(
                &mut backend,
                &mut state,
                key(InputOrigin::Physical(source_id), 38, true),
            );
            Backend::on_host_input(
                &mut backend,
                &mut state,
                key(InputOrigin::Physical(source_id), 38, false),
            );
        }

        for origin in [InputOrigin::XTest(5), InputOrigin::NestedHost] {
            Backend::on_host_input(&mut backend, &mut state, key(origin, 38, true));
            Backend::on_host_input(&mut backend, &mut state, key(origin, 38, false));
        }
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert!(state.key_repeats.is_empty());
        assert!(state.sync_pending.is_empty());
        assert!(state.xi_devices.source(RETIRED).is_none());
        assert!(state.xi_devices.source(RAZER).is_some());
        assert!(state.xi_devices.source(HYPERX).is_some());
    }

    #[test]
    fn key_source_selection_keeps_slave_holds_independent_from_master_transitions() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const A: InputSourceId = InputSourceId(0xB11);
        const B: InputSourceId = InputSourceId(0xB12);
        const SHIFT_L: u8 = 50;
        const A_KEY: u8 = 38;
        const KEY_MASK: u64 = (1 << 2) | (1 << 3);
        const SHIFT_MASK: u16 = 1;

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.core_focus.raw = ROOT_WINDOW.0;
        let mut peer_a = kbd_map_client_id(&mut state, 31);
        let mut peer_b = kbd_map_client_id(&mut state, 32);
        let mut master_peer = kbd_map_client_id(&mut state, 33);
        let mut core_peer = kbd_map_client_id(&mut state, 34);
        for (source, name) in [(A, "keyboard A"), (B, "keyboard B")] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(DeviceInfo {
                    source_id: source,
                    enabled: true,
                    resume_key: None,
                    capabilities: InputCapabilities {
                        keyboard: true,
                        pointer: false,
                        touch: false,
                    },
                    name: name.to_owned(),
                    device_node: format!("/dev/input/{name}"),
                    sysname: name.to_owned(),
                    vendor_id: 0,
                    product_id: 0,
                    is_touchpad: false,
                    config: LibinputConfigSnapshot::default(),
                }),
            );
        }
        let a_id = state
            .xi_devices
            .facet(A, XiFacetKind::Keyboard)
            .expect("keyboard A facet");
        let b_id = state
            .xi_devices
            .facet(B, XiFacetKind::Keyboard)
            .expect("keyboard B facet");
        for (client, device) in [(31, a_id), (32, b_id)] {
            state
                .clients
                .get_mut(&client)
                .unwrap()
                .xi2_masks
                .insert((ROOT_WINDOW, device), KEY_MASK);
        }
        state
            .clients
            .get_mut(&33)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, 3), KEY_MASK);
        state
            .clients
            .get_mut(&34)
            .unwrap()
            .event_masks
            .insert(ROOT_WINDOW, 0x0000_0001 | 0x0000_0002);

        let key = |origin, keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin,
                pressed,
                keycode,
                time: 0,
                root_x: 10,
                root_y: 20,
                event_x: 10,
                event_y: 20,
                state: 0,
            })
        };
        let send = |backend: &mut KmsBackend, state: &mut ServerState, origin, keycode, pressed| {
            Backend::on_host_input(backend, state, key(origin, keycode, pressed));
        };

        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(A),
            SHIFT_L,
            true,
        );
        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(A),
            SHIFT_L,
            true,
        );
        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(B),
            SHIFT_L,
            true,
        );
        assert_ne!(backend.serialize_modifiers() & SHIFT_MASK, 0);
        let a_press = xi2_events(&kbd_map_drain(&mut peer_a));
        let b_press = xi2_events(&kbd_map_drain(&mut peer_b));
        let master_press = xi2_events(&kbd_map_drain(&mut master_peer));
        assert_eq!(
            a_press
                .iter()
                .filter(|event| event.0 == 2)
                .map(|event| event.1)
                .collect::<Vec<_>>(),
            vec![a_id],
            "keyboard A gets its slave KeyPress",
        );
        assert_eq!(
            b_press
                .iter()
                .filter(|event| event.0 == 2)
                .map(|event| event.1)
                .collect::<Vec<_>>(),
            vec![b_id],
            "keyboard B's slave KeyPress remains deliverable while the master is already down",
        );
        assert_eq!(
            master_press
                .iter()
                .filter(|event| event.0 == 2)
                .map(|event| (event.1, event.2))
                .collect::<Vec<_>>(),
            vec![(3, a_id)],
            "the master's own down guard suppresses keyboard B's duplicate press",
        );

        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(A),
            SHIFT_L,
            false,
        );
        assert_eq!(
            backend.serialize_modifiers() & SHIFT_MASK,
            0,
            "the first valid slave release clears master Shift while B still holds Shift",
        );
        let _ = kbd_map_drain(&mut peer_a);
        let a_release_master = xi2_events(&kbd_map_drain(&mut master_peer));
        assert_eq!(
            a_release_master
                .iter()
                .filter(|event| event.0 == 3)
                .map(|event| (event.1, event.2))
                .collect::<Vec<_>>(),
            vec![(3, a_id)],
        );

        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(A),
            A_KEY,
            true,
        );
        let core_key = kbd_map_drain(&mut core_peer);
        let core_press = core_key
            .chunks_exact(32)
            .find(|event| event[0] & 0x7f == 2 && event[1] == A_KEY)
            .expect("core A KeyPress");
        assert_eq!(
            u16::from_le_bytes([core_press[28], core_press[29]]) & SHIFT_MASK,
            0,
            "core key after A's release is unshifted although B still physically holds Shift",
        );
        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(A),
            A_KEY,
            false,
        );
        let _ = kbd_map_drain(&mut core_peer);

        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(B),
            SHIFT_L,
            false,
        );
        send(
            &mut backend,
            &mut state,
            InputOrigin::Physical(B),
            SHIFT_L,
            false,
        );
        let b_release = xi2_events(&kbd_map_drain(&mut peer_b));
        assert_eq!(
            b_release
                .iter()
                .filter(|event| event.0 == 3)
                .map(|event| event.1)
                .collect::<Vec<_>>(),
            vec![b_id],
            "keyboard B receives its own release after A already released the master key",
        );
        let b_master_tail = xi2_events(&kbd_map_drain(&mut master_peer));
        assert!(
            b_master_tail.iter().all(|event| {
                !(event.0 == 3 && event.2 == b_id && event.3 == u32::from(SHIFT_L))
            }),
            "B's release cannot release the already-up master Shift a second time: {b_master_tail:?}",
        );
        assert_eq!(backend.serialize_modifiers() & SHIFT_MASK, 0);
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert!(state.key_down_by_device.is_empty());
        assert!(state.unpublished_keyboard_keys_down.is_empty());
        assert!(state.sync_pending.is_empty());
        assert_eq!(state.xi_devices.facet(A, XiFacetKind::Keyboard), Some(a_id));
        assert_eq!(state.xi_devices.facet(B, XiFacetKind::Keyboard), Some(b_id));
    }

    #[test]
    fn key_source_selection_tracks_xtest_targeted_keyboard_facets() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const PHYSICAL: InputSourceId = InputSourceId(0xB13);
        const KEY_MASK: u64 = (1 << 2) | (1 << 3);
        const KEYCODE: u8 = 38;
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.core_focus.raw = ROOT_WINDOW.0;
        let mut xtest_peer = kbd_map_client_id(&mut state, 41);
        let mut physical_peer = kbd_map_client_id(&mut state, 42);
        let mut master_peer = kbd_map_client_id(&mut state, 43);
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(DeviceInfo {
                source_id: PHYSICAL,
                enabled: true,
                resume_key: None,
                capabilities: InputCapabilities {
                    keyboard: true,
                    pointer: false,
                    touch: false,
                },
                name: "targeted keyboard".to_owned(),
                device_node: "/dev/input/targeted".to_owned(),
                sysname: "targeted".to_owned(),
                vendor_id: 0,
                product_id: 0,
                is_touchpad: false,
                config: LibinputConfigSnapshot::default(),
            }),
        );
        let physical_id = state
            .xi_devices
            .facet(PHYSICAL, XiFacetKind::Keyboard)
            .unwrap();
        state
            .clients
            .get_mut(&41)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, 5), KEY_MASK);
        state
            .clients
            .get_mut(&42)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, physical_id), KEY_MASK);
        state
            .clients
            .get_mut(&43)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, 3), KEY_MASK);
        let key = |device_id, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::XTest(device_id),
                pressed,
                keycode: KEYCODE,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        backend.on_host_input(&mut state, key(5, true));
        backend.on_host_input(&mut state, key(physical_id, true));
        let xtest_events = xi2_events(&kbd_map_drain(&mut xtest_peer));
        let physical_events = xi2_events(&kbd_map_drain(&mut physical_peer));
        let master_events = xi2_events(&kbd_map_drain(&mut master_peer));
        assert!(
            xtest_events
                .iter()
                .any(|event| event.0 == 2 && event.1 == 5 && event.2 == 5)
        );
        assert!(
            physical_events
                .iter()
                .any(|event| event.0 == 2 && event.1 == physical_id && event.2 == physical_id),
            "XTEST explicitly targeting a physical keyboard preserves the targeted slave form",
        );
        assert_eq!(
            master_events
                .iter()
                .filter(|event| event.0 == 2)
                .map(|event| (event.1, event.2))
                .collect::<Vec<_>>(),
            vec![(3, 5)],
            "the XTEST target's slave state is independent while master still has one down transition",
        );
        backend.on_host_input(&mut state, key(physical_id, false));
        backend.on_host_input(&mut state, key(5, false));
        let physical_release = xi2_events(&kbd_map_drain(&mut physical_peer));
        let xtest_release = xi2_events(&kbd_map_drain(&mut xtest_peer));
        assert!(
            physical_release
                .iter()
                .any(|event| event.0 == 3 && event.1 == physical_id)
        );
        assert!(
            xtest_release
                .iter()
                .any(|event| event.0 == 3 && event.1 == 5)
        );
        let master_tail = xi2_events(&kbd_map_drain(&mut master_peer));
        assert_eq!(
            master_tail
                .iter()
                .filter(|event| event.0 == 3 && event.3 == u32::from(KEYCODE))
                .map(|event| event.2)
                .collect::<Vec<_>>(),
            vec![physical_id],
            "the first valid targeted-device release releases the master once; XTEST 5's later release is suppressed",
        );
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert!(state.key_down_by_device.is_empty());
        assert!(state.unpublished_keyboard_keys_down.is_empty());
        assert_eq!(
            state.xi_devices.facet(PHYSICAL, XiFacetKind::Keyboard),
            Some(physical_id)
        );
        assert_eq!(state.xi_devices.devices().len(), 5);
    }

    #[test]
    fn key_source_selection_delivers_physical_key_under_exact_device_grab() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        const SOURCE: InputSourceId = InputSourceId(0xB14);
        const CLIENT: u32 = 51;
        const KEYCODE: u8 = 38;
        const KEY_MASK: u64 = (1 << 2) | (1 << 3);
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut peer = kbd_map_client_id(&mut state, CLIENT);
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(DeviceInfo {
                source_id: SOURCE,
                enabled: true,
                resume_key: None,
                capabilities: InputCapabilities {
                    keyboard: true,
                    pointer: false,
                    touch: false,
                },
                name: "grabbed keyboard".to_owned(),
                device_node: "/dev/input/grabbed".to_owned(),
                sysname: "grabbed".to_owned(),
                vendor_id: 0,
                product_id: 0,
                is_touchpad: false,
                config: LibinputConfigSnapshot::default(),
            }),
        );
        let device_id = state
            .xi_devices
            .facet(SOURCE, XiFacetKind::Keyboard)
            .unwrap();
        let mut body = Vec::with_capacity(24);
        body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        body.extend_from_slice(&0u32.to_le_bytes());
        body.extend_from_slice(&0u32.to_le_bytes());
        body.extend_from_slice(&device_id.to_le_bytes());
        body.extend_from_slice(&[1, 1, 0, 0]);
        body.extend_from_slice(&1u16.to_le_bytes());
        body.extend_from_slice(&(KEY_MASK as u32).to_le_bytes());
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            ClientId(CLIENT),
            SequenceNumber(1),
            RequestHeader {
                opcode: 137,
                data: 51,
                length_units: 7,
            },
            &body,
            None,
        )
        .expect("XIGrabDevice on the physical keyboard facet");
        assert!(state.xi2_keyboard_grabs.contains_key(&device_id));
        assert_eq!(
            state.xi_devices.device(device_id).unwrap().attached_master,
            None
        );
        backend.on_host_input(
            &mut state,
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(SOURCE),
                pressed: true,
                keycode: KEYCODE,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            }),
        );
        let events = xi2_events(&kbd_map_drain(&mut peer));
        assert!(events.iter().any(|event| {
            event.0 == 2
                && event.1 == device_id
                && event.2 == device_id
                && event.3 == u32::from(KEYCODE)
        }));
        assert!(!events.iter().any(|event| event.1 == 3));
        assert!(state.sync_pending.is_empty());
        assert!(state.xi2_keyboard_grabs.contains_key(&device_id));
        assert_eq!(
            state.xi_devices.device(device_id).unwrap().source_id,
            Some(SOURCE)
        );
        backend.on_host_input(
            &mut state,
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(SOURCE),
                pressed: false,
                keycode: KEYCODE,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            }),
        );
        let _ = kbd_map_drain(&mut peer);
        assert!(
            !backend.floating_keyboard_states[&device_id]
                .down_keys
                .contains(&KEYCODE)
        );
        assert!(state.key_down_by_device.is_empty());
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
    }

    #[test]
    fn key_source_selection_xi1_uses_the_physical_keyboard_facet() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{
                InputCapabilities, InputSourceId, XI_DEVICE_KEY_PRESS_OFFSET,
                XI_DEVICE_KEY_RELEASE_OFFSET, XiFacetKind,
            },
        };

        const SOURCE: InputSourceId = InputSourceId(0xB17);
        const CLIENT: u32 = 71;
        const KEYCODE: u8 = 38;
        const XI_FIRST_EVENT: u8 = 66;
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.core_focus.raw = ROOT_WINDOW.0;
        let mut peer = kbd_map_client_id(&mut state, CLIENT);
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(DeviceInfo {
                source_id: SOURCE,
                enabled: true,
                resume_key: None,
                capabilities: InputCapabilities {
                    keyboard: true,
                    pointer: false,
                    touch: false,
                },
                name: "XI1 keyboard".to_owned(),
                device_node: "/dev/input/xi1-keyboard".to_owned(),
                sysname: "xi1-keyboard".to_owned(),
                vendor_id: 0,
                product_id: 0,
                is_touchpad: false,
                config: LibinputConfigSnapshot::default(),
            }),
        );
        let device_id = state
            .xi_devices
            .facet(SOURCE, XiFacetKind::Keyboard)
            .unwrap();
        let press_class =
            (u32::from(device_id) << 8) | u32::from(XI_FIRST_EVENT + XI_DEVICE_KEY_PRESS_OFFSET);
        let release_class =
            (u32::from(device_id) << 8) | u32::from(XI_FIRST_EVENT + XI_DEVICE_KEY_RELEASE_OFFSET);
        state
            .clients
            .get_mut(&CLIENT)
            .unwrap()
            .xi1_window_event_classes
            .insert(
                ROOT_WINDOW,
                [press_class, release_class].into_iter().collect(),
            );
        let key = |origin, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin,
                pressed,
                keycode: KEYCODE,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        backend.on_host_input(&mut state, key(InputOrigin::Physical(SOURCE), true));
        backend.on_host_input(&mut state, key(InputOrigin::Physical(SOURCE), false));
        let events = kbd_map_drain(&mut peer);
        assert_eq!(events.len(), 64);
        assert_eq!(events[0], XI_FIRST_EVENT + XI_DEVICE_KEY_PRESS_OFFSET);
        let wire_device_id = u8::try_from(device_id).expect("XI1 device ids fit in one byte");
        assert_eq!(events[31], wire_device_id);
        assert_eq!(events[32], XI_FIRST_EVENT + XI_DEVICE_KEY_RELEASE_OFFSET);
        assert_eq!(events[63], wire_device_id);
        assert_eq!(events[1], KEYCODE);
        assert_eq!(events[33], KEYCODE);

        backend.on_host_input(&mut state, key(InputOrigin::NestedHost, true));
        backend.on_host_input(&mut state, key(InputOrigin::NestedHost, false));
        assert!(
            kbd_map_drain(&mut peer).is_empty(),
            "nested input has no XI1 slave form"
        );
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert!(state.key_down_by_device.is_empty());
        assert!(state.unpublished_keyboard_keys_down.is_empty());
        assert!(state.sync_pending.is_empty());
        assert_eq!(
            state.xi_devices.facet(SOURCE, XiFacetKind::Keyboard),
            Some(device_id)
        );
        assert_eq!(state.xi_devices.devices().len(), 5);
    }

    #[test]
    fn key_source_selection_drains_one_keyboard_and_keeps_other_holds() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const A: InputSourceId = InputSourceId(0xB15);
        const B: InputSourceId = InputSourceId(0xB16);
        const A_KEY: u8 = 38;
        const SHIFT_L: u8 = 50;
        const KEY_MASK: u64 = (1 << 2) | (1 << 3);
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.core_focus.raw = ROOT_WINDOW.0;
        let mut a_peer = kbd_map_client_id(&mut state, 61);
        let mut b_peer = kbd_map_client_id(&mut state, 62);
        let mut master_peer = kbd_map_client_id(&mut state, 63);
        for (source, name) in [(A, "drain A"), (B, "drain B")] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(DeviceInfo {
                    source_id: source,
                    enabled: true,
                    resume_key: None,
                    capabilities: InputCapabilities {
                        keyboard: true,
                        pointer: false,
                        touch: false,
                    },
                    name: name.to_owned(),
                    device_node: format!("/dev/input/{name}"),
                    sysname: name.to_owned(),
                    vendor_id: 0,
                    product_id: 0,
                    is_touchpad: false,
                    config: LibinputConfigSnapshot::default(),
                }),
            );
        }
        let a_id = state.xi_devices.facet(A, XiFacetKind::Keyboard).unwrap();
        let b_id = state.xi_devices.facet(B, XiFacetKind::Keyboard).unwrap();
        for (client, device) in [(61, a_id), (62, b_id)] {
            state
                .clients
                .get_mut(&client)
                .unwrap()
                .xi2_masks
                .insert((ROOT_WINDOW, device), KEY_MASK);
        }
        state
            .clients
            .get_mut(&63)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, 3), KEY_MASK);
        let key = |origin, keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin,
                pressed,
                keycode,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        backend.on_host_input(&mut state, key(InputOrigin::Physical(A), A_KEY, true));
        backend.on_host_input(&mut state, key(InputOrigin::Physical(A), A_KEY, false));
        backend.on_host_input(&mut state, key(InputOrigin::XTest(a_id), SHIFT_L, true));
        backend.on_host_input(&mut state, key(InputOrigin::Physical(B), A_KEY, true));
        let a_before_drain = xi2_events(&kbd_map_drain(&mut a_peer));
        let b_before_drain = xi2_events(&kbd_map_drain(&mut b_peer));
        assert_eq!(
            a_before_drain
                .iter()
                .filter(|event| event.0 == 3 && event.3 == u32::from(A_KEY))
                .count(),
            1,
            "the earlier A release has already cleared that key",
        );
        assert!(
            b_before_drain
                .iter()
                .any(|event| event.0 == 2 && event.3 == u32::from(A_KEY))
        );
        let master_before_drain = xi2_events(&kbd_map_drain(&mut master_peer));

        backend.release_keyboard_source_keys(&mut state, A);

        let a_after_drain = xi2_events(&kbd_map_drain(&mut a_peer));
        let b_after_drain = xi2_events(&kbd_map_drain(&mut b_peer));
        let master_after_drain = xi2_events(&kbd_map_drain(&mut master_peer));
        assert_eq!(
            a_after_drain
                .iter()
                .filter(|event| event.0 == 3 && event.3 == u32::from(SHIFT_L))
                .count(),
            1,
            "the targeted XTEST Shift hold on A drains once",
        );
        assert!(
            b_after_drain.is_empty(),
            "unrelated keyboard B is untouched"
        );
        assert_eq!(
            master_after_drain
                .iter()
                .filter(|event| event.0 == 3 && event.3 == u32::from(SHIFT_L))
                .map(|event| (event.1, event.2))
                .collect::<Vec<_>>(),
            vec![(3, a_id)],
            "only A's held Shift transition releases the master",
        );
        assert_eq!(
            master_before_drain
                .iter()
                .chain(master_after_drain.iter())
                .filter(|event| event.0 == 3 && event.3 == u32::from(A_KEY))
                .count(),
            1,
            "A's earlier key release is not generated again during cleanup",
        );
        assert_eq!(backend.serialize_modifiers() & 1, 0);
        assert!(backend.core.down_keys.contains(&A_KEY));
        assert_eq!(
            state.keys_down[usize::from(A_KEY / 8)] & (1 << (A_KEY % 8)),
            1 << (A_KEY % 8)
        );
        assert!(state.sync_pending.is_empty());
        assert!(state.xi_devices.source(A).is_some());
        assert_eq!(state.xi_devices.facet(A, XiFacetKind::Keyboard), Some(a_id));
        assert_eq!(state.xi_devices.facet(B, XiFacetKind::Keyboard), Some(b_id));
        assert!(!state.key_down_by_device.contains_key(&a_id));
        assert_eq!(
            state.key_down_by_device.get(&b_id),
            Some(&std::collections::HashMap::from([(
                A_KEY,
                InputOrigin::Physical(B),
            )])),
            "B's unrelated key remains held after A cleanup",
        );
        assert!(state.unpublished_keyboard_keys_down.is_empty());
        assert_eq!(state.xi_devices.devices().len(), 6);
    }

    #[test]
    fn xi_source_removal_releases_source_holds_before_unregister_and_drops_stale_reuse_input() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const REMOVED: InputSourceId = InputSourceId(0xD140);
        const HYPERX: InputSourceId = InputSourceId(0xD141);
        const REPLACEMENT: InputSourceId = InputSourceId(0xD142);
        const CLIENT: u32 = 0xD14;
        const CTRL_L: u8 = 37;
        const ALT_L: u8 = 64;
        const SHIFT_L: u8 = 50;
        const SUPER_L: u8 = 133;
        const HYPERX_KEY: u8 = 30;
        const KEY_MASK: u64 = (1 << 2) | (1 << 3);
        const BUTTON_MASK: u64 = (1 << 4) | (1 << 5);

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        backend
            .core
            .xid_map
            .insert(backend.core.window_id, ROOT_WINDOW);
        state.core_focus.raw = ROOT_WINDOW.0;
        let mut peer = kbd_map_client_id(&mut state, CLIENT);
        let make_info = |source_id: InputSourceId, name: &str| DeviceInfo {
            source_id,
            enabled: true,
            resume_key: None,
            capabilities: InputCapabilities {
                keyboard: true,
                pointer: true,
                touch: false,
            },
            name: name.to_owned(),
            device_node: format!("/dev/input/{}", source_id.0),
            sysname: format!("event{}", source_id.0),
            vendor_id: 0,
            product_id: source_id.0 as u32,
            is_touchpad: false,
            config: LibinputConfigSnapshot::default(),
        };
        for (source, name) in [(REMOVED, "Razer"), (HYPERX, "HyperX")] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(make_info(source, name)),
            );
        }
        let removed_keyboard = state
            .xi_devices
            .facet(REMOVED, XiFacetKind::Keyboard)
            .unwrap();
        let removed_pointer = state
            .xi_devices
            .facet(REMOVED, XiFacetKind::PointerTouch)
            .unwrap();
        let hyperx_keyboard = state
            .xi_devices
            .facet(HYPERX, XiFacetKind::Keyboard)
            .unwrap();
        let hyperx_pointer = state
            .xi_devices
            .facet(HYPERX, XiFacetKind::PointerTouch)
            .unwrap();
        let removed_keyboard_properties = state
            .xi_devices
            .device(removed_keyboard)
            .unwrap()
            .properties
            .clone();
        let removed_pointer_properties = state
            .xi_devices
            .device(removed_pointer)
            .unwrap()
            .properties
            .clone();
        let hyperx_pointer_properties = state
            .xi_devices
            .device(hyperx_pointer)
            .unwrap()
            .properties
            .clone();
        for (device_id, mask) in [
            (removed_keyboard, KEY_MASK),
            (hyperx_keyboard, KEY_MASK),
            (removed_pointer, BUTTON_MASK),
            (hyperx_pointer, BUTTON_MASK),
            (2, BUTTON_MASK),
            (3, KEY_MASK),
            (4, BUTTON_MASK),
            (5, KEY_MASK),
        ] {
            state
                .clients
                .get_mut(&CLIENT)
                .unwrap()
                .xi2_masks
                .insert((ROOT_WINDOW, device_id), mask);
        }
        state
            .clients
            .get_mut(&CLIENT)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, 0), KEY_MASK | BUTTON_MASK);

        let key = |origin, keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin,
                pressed,
                keycode,
                time: 1,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        let button = |origin, button, pressed| HostInputEvent::PointerButton {
            origin,
            button,
            pressed,
            time: 2,
        };
        let drain_peer = |state: &mut ServerState, peer: &mut std::os::unix::net::UnixStream| {
            let mut bytes = Vec::new();
            for _ in 0..64 {
                bytes.extend(kbd_map_drain(peer));
                let Some(client) = state.clients.get_mut(&CLIENT) else {
                    break;
                };
                if client.outbound.is_empty() {
                    break;
                }
                let outcome = yserver_core::core_loop::client_io::drain_outbound(client)
                    .expect("flush buffered test events");
                assert_ne!(
                    outcome,
                    yserver_core::core_loop::client_io::WriteOutcome::Disconnect,
                    "the event-capture peer remains connected",
                );
            }
            bytes.extend(kbd_map_drain(peer));
            bytes
        };

        // The source is a mixed keyboard/pointer facet. Explicit XTEST holds
        // aimed at its physical XI facets belong to those facets and drain
        // with them; virtual XTEST 4/5 holds remain independent.
        backend.on_host_input(
            &mut state,
            key(InputOrigin::Physical(REMOVED), CTRL_L, true),
        );
        backend.on_host_input(&mut state, key(InputOrigin::Physical(REMOVED), ALT_L, true));
        backend.on_host_input(
            &mut state,
            key(InputOrigin::XTest(removed_keyboard), SUPER_L, true),
        );
        backend.on_host_input(
            &mut state,
            key(InputOrigin::Physical(HYPERX), HYPERX_KEY, true),
        );
        backend.on_host_input(&mut state, key(InputOrigin::XTest(5), SHIFT_L, true));
        backend.on_host_input(
            &mut state,
            button(InputOrigin::Physical(REMOVED), 0x110, true),
        );
        backend.on_host_input(
            &mut state,
            button(InputOrigin::XTest(removed_pointer), 0x112, true),
        );
        backend.on_host_input(
            &mut state,
            button(InputOrigin::Physical(HYPERX), 0x110, true),
        );
        backend.on_host_input(&mut state, button(InputOrigin::XTest(4), 0x112, true));
        let press_bytes = drain_peer(&mut state, &mut peer);
        let press_events = xi2_events(&press_bytes);
        assert!(
            press_events.iter().any(|event| {
                event.0 == 4 && event.1 == removed_pointer && event.2 == removed_pointer
            }),
            "production pointer press reaches the selected source facet: events={press_events:?}; bytes={}; buffered={}; held={}",
            press_bytes.len(),
            state.clients[&CLIENT].outbound.len(),
            state
                .xi_devices
                .device(removed_pointer)
                .unwrap()
                .buttons_down,
        );
        assert_eq!(
            state
                .xi_devices
                .device(removed_pointer)
                .unwrap()
                .buttons_down,
            3,
            "the removed facet holds its physical and explicit-XTEST buttons",
        );

        assert_eq!(
            state
                .xi_devices
                .device(removed_keyboard)
                .unwrap()
                .properties,
            removed_keyboard_properties,
            "keyboard facet properties are intact immediately before removal",
        );
        assert_eq!(
            state.xi_devices.device(removed_pointer).unwrap().properties,
            removed_pointer_properties,
            "pointer facet properties are intact immediately before removal",
        );
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceRemoved { source_id: REMOVED },
        );
        assert!(
            state.pending_xi_device_removals.is_empty(),
            "the production removal dispatch consumes descriptor snapshots for XI2 Removed",
        );
        let removal_bytes = drain_peer(&mut state, &mut peer);
        let removal_events = xi2_events(&removal_bytes);
        let releases: Vec<_> = removal_events
            .iter()
            .enumerate()
            .filter(|(_, event)| matches!(event.0, 3 | 5))
            .collect();

        // Xorg dix/devices.c::ReleaseButtonsAndKeys runs its
        // `/* Release all buttons */` loop before `/* Release all keys */`.
        let last_button_release = releases
            .iter()
            .filter(|(_, event)| event.0 == 5)
            .map(|(index, _)| *index)
            .max()
            .unwrap_or_else(|| {
                panic!(
                    "removed source emits button releases; decoded={removal_events:?}; bytes={}; buffered={}",
                    removal_bytes.len(),
                    state.clients[&CLIENT].outbound.len(),
                )
            });
        let first_key_release = releases
            .iter()
            .filter(|(_, event)| event.0 == 3)
            .map(|(index, _)| *index)
            .min()
            .expect("removed source emits key releases");
        assert!(last_button_release < first_key_release);

        for detail in [1, 2] {
            assert_eq!(
                removal_events
                    .iter()
                    .filter(|event| {
                        event.0 == 5
                            && event.1 == removed_pointer
                            && event.2 == removed_pointer
                            && event.3 == detail
                    })
                    .count(),
                1,
                "each removed-facet ButtonRelease must be delivered once",
            );
        }
        assert_eq!(
            removal_events
                .iter()
                .filter(|event| event.0 == 5 && event.1 == 2 && event.3 == 1)
                .count(),
            0,
            "HyperX still holds button 1, so its master release is suppressed",
        );
        assert_eq!(
            removal_events
                .iter()
                .filter(|event| event.0 == 5 && event.1 == 2 && event.3 == 2)
                .count(),
            0,
            "virtual XTEST still holds button 2, so its master release is suppressed",
        );
        assert!(
            removal_events
                .iter()
                .all(|event| { !(matches!(event.0, 3 | 5) && matches!(event.1, 4 | 5)) }),
            "virtual XTEST facets do not receive removal releases"
        );
        for (keycode, expected_slave_events) in [(CTRL_L, 1), (ALT_L, 1), (SUPER_L, 1)] {
            let slave_release = removal_events
                .iter()
                .position(|event| {
                    event.0 == 3
                        && event.1 == removed_keyboard
                        && event.2 == removed_keyboard
                        && event.3 == u32::from(keycode)
                })
                .expect("removed keyboard facet gets its release");
            assert_eq!(
                removal_events
                    .iter()
                    .filter(|event| {
                        event.0 == 3
                            && event.1 == removed_keyboard
                            && event.2 == removed_keyboard
                            && event.3 == u32::from(keycode)
                    })
                    .count(),
                expected_slave_events,
            );
            let master_release = removal_events
                .iter()
                .position(|event| {
                    event.0 == 3
                        && event.1 == 3
                        && event.2 == removed_keyboard
                        && event.3 == u32::from(keycode)
                })
                .expect("accepted slave release reaches the keyboard master");
            assert!(
                slave_release < master_release,
                "slave form precedes master form"
            );
            assert_eq!(
                removal_events
                    .iter()
                    .filter(|event| {
                        event.0 == 3
                            && event.1 == 3
                            && event.2 == removed_keyboard
                            && event.3 == u32::from(keycode)
                    })
                    .count(),
                1,
                "each removed-source master KeyRelease is emitted once",
            );
        }

        assert!(state.xi_devices.source(REMOVED).is_none());
        assert!(
            state
                .xi_devices
                .devices()
                .iter()
                .all(|device| device.source_id != Some(REMOVED))
        );
        assert!(state.xi_devices.device(removed_keyboard).is_none());
        assert!(state.xi_devices.device(removed_pointer).is_none());
        assert!(!state.key_down_by_device.contains_key(&removed_keyboard));
        assert!(
            !state
                .key_repeats
                .contains_key(&InputOrigin::Physical(REMOVED))
        );
        assert!(!state.unpublished_keyboard_keys_down.contains_key(&REMOVED));
        assert!(
            !state
                .unpublished_pointer_buttons_down
                .contains_key(&REMOVED)
        );
        assert!(state.sync_pending.is_empty());
        assert!(backend.core.pending_pointer_events.is_empty());
        assert!(!state.xi1_frozen.contains_key(&removed_keyboard));
        assert!(!state.xi1_frozen.contains_key(&removed_pointer));
        assert!(!state.xi2_keyboard_grabs.contains_key(&removed_keyboard));
        assert!(!state.xi2_pointer_grabs.contains_key(&removed_pointer));
        assert!(!state.xi2_detached_masters.contains_key(&removed_keyboard));
        assert!(!state.xi2_detached_masters.contains_key(&removed_pointer));
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceRemoved { source_id: REMOVED },
        );
        assert!(drain_peer(&mut state, &mut peer).is_empty());
        assert!(state.pending_xi_device_removals.is_empty());
        assert!(state.take_xi_removed_device_descriptors().is_empty());
        assert!(backend.core.down_keys.contains(&HYPERX_KEY));
        assert!(backend.core.down_keys.contains(&SHIFT_L));
        assert!(!backend.core.down_keys.contains(&CTRL_L));
        assert!(!backend.core.down_keys.contains(&ALT_L));
        assert!(!backend.core.down_keys.contains(&SUPER_L));
        assert_eq!(
            state.key_down_by_device.get(&hyperx_keyboard),
            Some(&std::collections::HashMap::from([(
                HYPERX_KEY,
                InputOrigin::Physical(HYPERX),
            )])),
        );
        assert_eq!(
            state.key_down_by_device.get(&5),
            Some(&std::collections::HashMap::from([(
                SHIFT_L,
                InputOrigin::XTest(5),
            )])),
            "virtual XTEST keyboard 5 keeps its independent Shift hold",
        );
        assert_eq!(
            state
                .xi_devices
                .device(hyperx_pointer)
                .unwrap()
                .buttons_down,
            1,
            "HyperX keeps its button held",
        );
        assert_eq!(
            state.xi_devices.device(hyperx_pointer).unwrap().properties,
            hyperx_pointer_properties,
            "HyperX's independent property state remains intact",
        );
        assert_eq!(state.xi_devices.device(4).unwrap().buttons_down, 2);
        assert_eq!(
            state.xi_devices.device(5).unwrap().source_id,
            None,
            "virtual XTEST keyboard identity remains present",
        );
        assert_eq!(state.buttons_down, 3);
        assert_eq!(backend.core.button_mask, 0x0300);
        let mut expected_keys = [0u8; 32];
        for keycode in [HYPERX_KEY, SHIFT_L] {
            expected_keys[usize::from(keycode / 8)] |= 1 << (keycode % 8);
        }
        assert_eq!(state.keys_down, expected_keys);
        assert_eq!(
            state
                .xi_devices
                .device(hyperx_pointer)
                .unwrap()
                .scroll_axis_values,
            [0, 0],
            "unrelated pointer valuators remain unchanged",
        );

        // A newly added source can reuse the XI IDs, but events remain bound
        // to their old runtime SourceId and cannot mutate/fan out into it.
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(make_info(REPLACEMENT, "replacement")),
        );
        assert_eq!(
            state.xi_devices.facet(REPLACEMENT, XiFacetKind::Keyboard),
            Some(removed_keyboard),
        );
        assert_eq!(
            state
                .xi_devices
                .facet(REPLACEMENT, XiFacetKind::PointerTouch),
            Some(removed_pointer),
        );
        let before = (
            backend.core.cursor_x,
            backend.core.cursor_y,
            backend.core.button_mask,
            backend.serialize_modifiers(),
            state.pointer_root,
            state.buttons_down,
            state.keys_down,
            state
                .xi_devices
                .device(removed_pointer)
                .unwrap()
                .buttons_down,
        );
        backend.on_host_input(
            &mut state,
            key(InputOrigin::Physical(REMOVED), CTRL_L, true),
        );
        backend.on_host_input(
            &mut state,
            HostInputEvent::PointerMotion {
                origin: InputOrigin::Physical(REMOVED),
                x: 500,
                y: 400,
                time: 3,
                relative: false,
                dx: 0,
                dy: 0,
                motion_delta: None,
            },
        );
        backend.on_host_input(
            &mut state,
            button(InputOrigin::Physical(REMOVED), 0x111, true),
        );
        assert_eq!(
            (
                backend.core.cursor_x,
                backend.core.cursor_y,
                backend.core.button_mask,
                backend.serialize_modifiers(),
                state.pointer_root,
                state.buttons_down,
                state.keys_down,
                state
                    .xi_devices
                    .device(removed_pointer)
                    .unwrap()
                    .buttons_down,
            ),
            before,
            "old-source input cannot change KMS, master, or reused-facet state",
        );
        assert!(drain_peer(&mut state, &mut peer).is_empty());
        assert!(state.xi_devices.source(HYPERX).unwrap().enabled);
        assert!(state.xi_devices.source(REPLACEMENT).unwrap().enabled);
    }

    #[test]
    fn key_source_selection_guards_unpublished_physical_keyboard_holds() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };
        const A: InputSourceId = InputSourceId(0xB18);
        const B: InputSourceId = InputSourceId(0xB19);
        const SHIFT_L: u8 = 50;
        const KEY_MASK: u64 = (1 << 2) | (1 << 3);

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.core_focus.raw = ROOT_WINDOW.0;
        let mut master_peer = kbd_map_client_id(&mut state, 81);
        let mut core_peer = kbd_map_client_id(&mut state, 82);
        state
            .clients
            .get_mut(&81)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, 3), KEY_MASK);
        state
            .clients
            .get_mut(&82)
            .unwrap()
            .event_masks
            .insert(ROOT_WINDOW, 0x0000_0001 | 0x0000_0002);

        let info = |source_id: InputSourceId| DeviceInfo {
            source_id,
            enabled: true,
            resume_key: None,
            capabilities: InputCapabilities {
                keyboard: true,
                pointer: false,
                touch: false,
            },
            name: format!("unpublished keyboard {}", source_id.0),
            device_node: format!("/dev/input/unpublished{}", source_id.0),
            sysname: format!("unpublished{}", source_id.0),
            vendor_id: 0,
            product_id: 0,
            is_touchpad: false,
            config: LibinputConfigSnapshot::default(),
        };
        // Fill every physical XI slot through the same KMS DeviceAdded entry
        // used by production input discovery.
        for id in 1..=122 {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(info(InputSourceId(id))),
            );
        }
        for source in [A, B] {
            backend.on_host_input(&mut state, HostInputEvent::DeviceAdded(info(source)));
        }
        assert!(state.xi_devices.facet(A, XiFacetKind::Keyboard).is_none());
        assert!(state.xi_devices.facet(B, XiFacetKind::Keyboard).is_none());

        let key = |source, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(source),
                pressed,
                keycode: SHIFT_L,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        backend.on_host_input(&mut state, key(A, true));
        backend.on_host_input(&mut state, key(B, true));
        assert_eq!(
            state.unpublished_keyboard_keys_down.get(&A),
            Some(&std::collections::HashMap::from([(
                SHIFT_L,
                InputOrigin::Physical(A),
            )])),
        );
        assert_eq!(
            state.unpublished_keyboard_keys_down.get(&B),
            Some(&std::collections::HashMap::from([(
                SHIFT_L,
                InputOrigin::Physical(B),
            )])),
        );
        assert_ne!(backend.serialize_modifiers() & 1, 0);
        let master_press = xi2_events(&kbd_map_drain(&mut master_peer));
        assert_eq!(
            master_press
                .iter()
                .filter(|event| event.0 == 2)
                .map(|event| (event.1, event.2, event.3))
                .collect::<Vec<_>>(),
            vec![(3, 3, u32::from(SHIFT_L))],
            "an unpublished physical source still obeys the master's independent guard",
        );

        backend.release_keyboard_source_keys(&mut state, A);
        assert_eq!(backend.serialize_modifiers() & 1, 0);
        assert!(backend.core.down_keys.is_empty());
        assert!(!state.unpublished_keyboard_keys_down.contains_key(&A));
        assert_eq!(
            state.unpublished_keyboard_keys_down.get(&B),
            Some(&std::collections::HashMap::from([(
                SHIFT_L,
                InputOrigin::Physical(B),
            )])),
            "draining A leaves B's unpublished physical key hold intact",
        );
        let master_release = xi2_events(&kbd_map_drain(&mut master_peer));
        assert_eq!(
            master_release
                .iter()
                .filter(|event| event.0 == 3)
                .map(|event| (event.1, event.2, event.3))
                .collect::<Vec<_>>(),
            vec![(3, 3, u32::from(SHIFT_L))],
        );

        backend.on_host_input(&mut state, key(B, false));
        assert!(xi2_events(&kbd_map_drain(&mut master_peer)).is_empty());
        let core_bytes = kbd_map_drain(&mut core_peer);
        assert_eq!(
            core_bytes
                .chunks_exact(32)
                .filter(|event| matches!(event[0] & 0x7f, 2 | 3) && event[1] == SHIFT_L)
                .map(|event| event[0] & 0x7f)
                .collect::<Vec<_>>(),
            vec![2, 3],
            "core sees only the master's accepted press and first release",
        );
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert!(state.key_down_by_device.is_empty());
        assert!(state.unpublished_keyboard_keys_down.is_empty());
        assert!(state.sync_pending.is_empty());
        assert!(state.xi_devices.source(A).is_some());
        assert!(state.xi_devices.source(B).is_some());
        assert_eq!(state.xi_devices.devices().len(), 126);
    }

    /// The duplicate guard (#168) drops a press of a key already down and
    /// a release of a key that is not down before any delivery — but the
    /// raw event is generated ahead of it, as on Xorg (Xvfb capture, XTEST):
    /// `p38 p38` → two RawKeyPress; `p50 p50` (Shift_L, a modifier) → one;
    /// a lone `r38` → one RawKeyRelease. No device event for the dropped ones.
    #[test]
    fn duplicate_guard_keeps_xorg_raw_key_events() {
        use yserver_core::{
            core_loop::HostInputEvent, host_x11::HostKeyEvent, resources::ROOT_WINDOW,
            server::ServerState,
        };
        const A: u8 = 38;
        const SHIFT_L: u8 = 50;
        let mut b = KmsBackend::for_tests();
        assert_ne!(
            b.core.xkb_desc.modmap[usize::from(SHIFT_L)],
            0,
            "precondition: Shift_L is a modifier"
        );
        let mut state = ServerState::new();
        let mut peer = kbd_map_client_id(&mut state, 9);
        let client = state.clients.get_mut(&9).unwrap();
        client
            .xi2_masks
            .insert((ROOT_WINDOW, 1), (1 << 13) | (1 << 14));
        client
            .xi2_masks
            .insert((ROOT_WINDOW, 3), (1 << 2) | (1 << 3));
        let key = |keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: yserver_core::core_loop::InputOrigin::NestedHost,
                keycode,
                pressed,
                state: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                time: 0,
            })
        };

        for (keycode, pressed) in [
            (A, true),
            (A, true),
            (A, false),
            (SHIFT_L, true),
            (SHIFT_L, true),
            (SHIFT_L, false),
            (A, false),
        ] {
            b.on_host_input(&mut state, key(keycode, pressed));
        }

        let kinds: Vec<_> = xi2_events(&kbd_map_drain(&mut peer))
            .iter()
            .map(|e| (e.0, e.3))
            .collect();
        assert_eq!(
            kinds,
            vec![
                (13, 38),
                (2, 38),
                (13, 38), // duplicate press: raw only
                (14, 38),
                (3, 38),
                (13, 50),
                (2, 50),
                // duplicate modifier press: nothing
                (14, 50),
                (3, 50),
                (14, 38), // release of a key that is not down: raw only
            ]
        );
    }

    /// Software auto-repeat is not device input: Xorg's XKB repeat builds
    /// the device event directly (AccessXKeyboardEvent) and never passes
    /// GetKeyboardEvents, so a repeat pair produces no raw key events.
    #[test]
    fn key_repeat_emits_no_raw_key_events() {
        use yserver_core::{
            core_loop::HostInputEvent, host_x11::HostKeyEvent, resources::ROOT_WINDOW,
            server::ServerState,
        };
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut peer = kbd_map_client_id(&mut state, 9);
        let client = state.clients.get_mut(&9).unwrap();
        client
            .xi2_masks
            .insert((ROOT_WINDOW, 1), (1 << 13) | (1 << 14));
        client
            .xi2_masks
            .insert((ROOT_WINDOW, 3), (1 << 2) | (1 << 3));
        let ev = |pressed| HostKeyEvent {
            origin: yserver_core::core_loop::InputOrigin::NestedHost,
            keycode: 38,
            pressed,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        };

        b.on_host_input(&mut state, HostInputEvent::Key(ev(true)));
        b.on_host_input(&mut state, HostInputEvent::KeyRepeat(ev(false)));
        b.on_host_input(&mut state, HostInputEvent::KeyRepeat(ev(true)));
        b.on_host_input(&mut state, HostInputEvent::Key(ev(false)));

        let kinds: Vec<_> = xi2_events(&kbd_map_drain(&mut peer))
            .iter()
            .map(|e| e.0)
            .collect();
        assert_eq!(kinds, vec![13, 2, 3, 2, 14, 3]);
    }

    /// RECORD records an autorepeat as Xorg generates it: a press flagged
    /// in the sequence field and no release (`record-probe repeat l` on
    /// Xvfb: `02260000`, then presses with seqfield 1, then `03260000`).
    #[test]
    fn record_sees_autorepeat_as_flagged_presses() {
        use yserver_core::{
            core_loop::HostInputEvent, host_x11::HostKeyEvent, server::ServerState,
        };
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut peer = kbd_map_client_id(&mut state, 5);
        // CreateContext(ctx 1, FutureClients, device events 2..3), then
        // EnableContext on the same connection.
        let mut create = Vec::new();
        for word in [1u32, 0, 1, 1, 2] {
            create.extend_from_slice(&word.to_le_bytes());
        }
        create.extend_from_slice(&[0; 18]);
        create.extend_from_slice(&[2, 3, 0, 0, 0, 0]);
        kbd_map_request(&mut state, &mut b, 154, 1, &create);
        kbd_map_request(&mut state, &mut b, 154, 5, &1u32.to_le_bytes());
        let ev = |pressed| HostKeyEvent {
            origin: yserver_core::core_loop::InputOrigin::NestedHost,
            keycode: 38,
            pressed,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        };
        b.on_host_input(&mut state, HostInputEvent::Key(ev(true)));
        b.on_host_input(&mut state, HostInputEvent::KeyRepeat(ev(false)));
        b.on_host_input(&mut state, HostInputEvent::KeyRepeat(ev(true)));
        b.on_host_input(&mut state, HostInputEvent::Key(ev(false)));

        let bytes = kbd_map_drain(&mut peer);
        let mut recorded = Vec::new();
        let mut at = 0;
        while at < bytes.len() {
            let len =
                32 + 4 * u32::from_le_bytes(bytes[at + 4..at + 8].try_into().unwrap()) as usize;
            if bytes[at] == 1 && bytes[at + 1] == 0 {
                let event = &bytes[at + 32..at + len];
                recorded.push((event[0], event[1], u16::from_le_bytes([event[2], event[3]])));
            }
            at += len;
        }
        assert_eq!(recorded, [(2, 38, 0), (2, 38, 1), (3, 38, 0)]);
    }

    /// Test A: a compiled `grp:alt_shift_toggle` option makes the
    /// xkb_state effective layout advance 0 -> 1 when Alt_L then
    /// Shift_L are pressed. This locks in the xkbcommon behaviour the
    /// Driver-2 detection in `cook_host_key` relies on. (Confirmed
    /// locally before writing the feature.)
    #[test]
    fn grp_alt_shift_toggle_advances_xkb_layout() {
        let mut b = KmsBackend::for_tests();
        let changed = b.core.recompile_keymap(&crate::kms::core::XkbRmlvo {
            rules: "evdev".into(),
            model: "pc105".into(),
            layout: "us,be".into(),
            variant: String::new(),
            options: Some("grp:alt_shift_toggle".into()),
        });
        assert!(
            changed.is_some(),
            "us,be + grp:alt_shift_toggle must compile"
        );

        // Fresh keymap starts on group 0.
        assert_eq!(
            b.core
                .xkb_state
                .0
                .serialize_layout(xkbcommon::xkb::STATE_LAYOUT_EFFECTIVE),
            0,
            "fresh keymap is on group 0"
        );

        // Alt_L = evdev KEY_LEFTALT 56 + 8 = keycode 64.
        // Shift_L = evdev KEY_LEFTSHIFT 42 + 8 = keycode 50.
        b.core.xkb_state.0.update_key(
            xkbcommon::xkb::Keycode::new(64),
            xkbcommon::xkb::KeyDirection::Down,
        );
        b.core.xkb_state.0.update_key(
            xkbcommon::xkb::Keycode::new(50),
            xkbcommon::xkb::KeyDirection::Down,
        );

        assert_eq!(
            b.core
                .xkb_state
                .0
                .serialize_layout(xkbcommon::xkb::STATE_LAYOUT_EFFECTIVE),
            1,
            "Alt+Shift must advance the effective layout to group 1 (be)"
        );
    }

    /// Test B (make-or-break): feeding the Alt+Shift sequence through
    /// `cook_host_key` (Driver 2) must (a) sync the authoritative
    /// `core.locked_group` to 1, and (b) stamp group 1 into the cooked
    /// event's `state` group bits (13-14) on the very key that
    /// triggered the switch, so clients see the new group immediately.
    #[test]
    fn cook_host_key_grp_shortcut_syncs_locked_group_and_stamps_group_bits() {
        use yserver_core::host_x11::HostKeyEvent;
        let mut b = KmsBackend::for_tests();
        let changed = b.core.recompile_keymap(&crate::kms::core::XkbRmlvo {
            rules: "evdev".into(),
            model: "pc105".into(),
            layout: "us,be".into(),
            variant: String::new(),
            options: Some("grp:alt_shift_toggle".into()),
        });
        assert!(
            changed.is_some(),
            "us,be + grp:alt_shift_toggle must compile"
        );
        assert_eq!(b.core.locked_group, 0, "fresh state is on group 0");

        let key = |keycode, pressed| HostKeyEvent {
            origin: yserver_core::core_loop::InputOrigin::NestedHost,
            keycode,
            pressed,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        };

        // Alt_L down (keycode 64): no group change yet.
        let _ = b.cook_host_key(key(64, true));
        assert_eq!(
            b.core.locked_group, 0,
            "Alt alone must not advance the group"
        );

        // Shift_L down (keycode 50): the toggle fires — group 0 -> 1.
        let cooked = b.cook_host_key(key(50, true));
        assert_eq!(
            b.core.locked_group, 1,
            "Alt+Shift must sync the authoritative locked_group to 1"
        );
        // Group bits 13-14 (XkbGroupForCoreState): group 1 == 0x2000.
        assert_eq!(
            cooked.state & 0x6000,
            0x2000,
            "the trigger key must carry the NEW group in its state bits"
        );
    }

    /// Lock-LED mask tracks the XKB lock state: a Caps Lock toggle
    /// (press + release through `cook_host_key`) raises the CAPSLOCK
    /// LED bit; a second toggle clears it. This mask is what
    /// `sync_keyboard_leds` pushes to the keyboards via libinput —
    /// the caps-LED-never-lights bug (typed the lock-screen password
    /// wrong repeatedly because the LED gave no feedback).
    #[test]
    fn caps_lock_toggle_drives_led_bits() {
        use yserver_core::host_x11::HostKeyEvent;
        let mut b = KmsBackend::for_tests();
        assert_eq!(b.current_led_bits(), 0, "fresh state: all lock LEDs off");
        // 66 == X keycode for Caps Lock (evdev KEY_CAPSLOCK 58 + 8).
        let key = |pressed| HostKeyEvent {
            origin: yserver_core::core_loop::InputOrigin::NestedHost,
            keycode: 66,
            pressed,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        };
        let _ = b.cook_host_key(key(true));
        let _ = b.cook_host_key(key(false));
        assert_eq!(
            b.current_led_bits(),
            input::Led::CAPSLOCK.bits(),
            "caps toggle must raise the CAPSLOCK LED bit",
        );
        let _ = b.cook_host_key(key(true));
        let _ = b.cook_host_key(key(false));
        assert_eq!(b.current_led_bits(), 0, "second toggle clears the LED bit");
    }

    fn caps_key(pressed: bool) -> yserver_core::host_x11::HostKeyEvent {
        // 66 == X keycode for Caps Lock (evdev KEY_CAPSLOCK 58 + 8).
        yserver_core::host_x11::HostKeyEvent {
            origin: yserver_core::core_loop::InputOrigin::NestedHost,
            keycode: 66,
            pressed,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        }
    }

    /// xdotool through the core loop, after the xmodmap caps-as-control
    /// script (the vng scenario `xmodmap-caps-control.sh`): libxdo's
    /// GetMap(XkbAllClientInfoMask) + GetNames(KeyTypeNames|KTLevelNames|
    /// VirtualModNames) decode as libX11 does, and every name its type
    /// entries need resolves with GetAtomName (Xorg: `xorg-xkb-pristine.txt`
    /// names every type, level and vmod).
    #[test]
    fn xdotool_names_resolve_after_xmodmap() {
        let cases = parse_xkb_smm_golden(include_str!(
            "../testdata/xorg-xkb-set-modifier-mapping.txt"
        ));
        for case in cases.iter().filter(|c| c.name == "xmodmap-replay") {
            let mut backend = KmsBackend::for_tests();
            let mut state = yserver_core::server::ServerState::new();
            let mut peer = kbd_map_client(&mut state);
            for step in &case.steps {
                match &step.request {
                    SmmRequest::Ckm {
                        first,
                        kpk,
                        count,
                        syms,
                    } => kbd_map_request(
                        &mut state,
                        &mut backend,
                        100,
                        *count,
                        &change_kbd_map_body(*first, *kpk, syms),
                    ),
                    SmmRequest::Smm { kpm, keys } => {
                        kbd_map_request(&mut state, &mut backend, 118, *kpm, keys);
                    }
                    other => panic!("xmodmap-replay step {other:?}"),
                }
            }
            // libX11's XkbUseExtension first (every other XKB request
            // draws BadAccess without it).
            kbd_map_request(&mut state, &mut backend, 136, 0, &[1, 0, 0, 0]);
            let _ = kbd_map_drain(&mut peer);
            let mut map_req = [0u8; 20];
            map_req[0..2].copy_from_slice(&0x0100u16.to_le_bytes());
            map_req[2] = 0x07;
            kbd_map_request(&mut state, &mut backend, 136, 8, &map_req);
            let map = kbd_map_drain(&mut peer);
            assert_eq!(map[0], 1, "GetMap reply: {:02x?}", &map[..8.min(map.len())]);
            // libX11 sends the device id GetMap reported.
            let mut names_req = [0u8; 8];
            names_req[0..2].copy_from_slice(&u16::from(map[1]).to_le_bytes());
            // XkbKeyTypeNamesMask | XkbKTLevelNamesMask | XkbVirtualModNamesMask.
            names_req[4..8].copy_from_slice(&0x08c0u32.to_le_bytes());
            kbd_map_request(&mut state, &mut backend, 136, 17, &names_req);
            let names = kbd_map_drain(&mut peer);
            assert_eq!(
                names[0],
                1,
                "GetNames reply: {:02x?}",
                &names[..8.min(names.len())]
            );
            let (types, levels, vmods) =
                crate::kms::xkb_desc::tests::libx11_names(&map, &names).expect("libX11 decode");
            let desc = &backend.core.xkb_desc;
            let mut needed: Vec<u32> = types.clone();
            for (i, t) in desc.types.iter().enumerate() {
                needed.extend(&levels[i]);
                let used = t.mods.vmods | t.map.iter().fold(0, |m, e| m | e.mods.vmods);
                needed.extend((0..16).filter(|v| used & (1 << v) != 0).map(|v| vmods[v]));
            }
            for atom in needed {
                kbd_map_request(&mut state, &mut backend, 17, 0, &atom.to_le_bytes());
                let r = kbd_map_drain(&mut peer);
                assert_eq!(
                    r[0],
                    1,
                    "{}: GetAtomName({atom:#x}) → {:02x?}",
                    case.layout,
                    &r[..8]
                );
            }
        }
    }

    /// The xmodmap caps-as-control script on the keyboard description:
    /// `<CAPS>` rebound to `Control_L` (ChangeKeyboardMapping) and moved from
    /// Lock to Control (SetModifierMapping): nothing can hold Lock any more.
    /// (Rebinding alone isn't enough: a key left in Lock matches
    /// `Any+Exactly(Lock)`, which locks Lock, on Xorg as here.)
    fn caps_as_control(b: &mut KmsBackend) {
        let _ = b.apply_keyboard_mapping(66, 1, &[xkbcommon::xkb::keysyms::KEY_Control_L]);
        let mut modmap = [0u8; 256];
        modmap.copy_from_slice(&b.core.xkb_desc.modmap);
        modmap[66] = 0x04;
        let _ = b.apply_modifier_mapping(&modmap);
    }

    /// A full RMLVO reload starts from a fresh state (Caps Lock off), so
    /// the keyboard LEDs must follow right away, not on the next key.
    #[test]
    fn rmlvo_reload_resyncs_the_lock_leds() {
        use yserver_core::backend::Backend;
        let mut b = KmsBackend::for_tests();
        let _ = b.cook_host_key(caps_key(true));
        let _ = b.cook_host_key(caps_key(false));
        assert_eq!(b.leds_sent, input::Led::CAPSLOCK.bits(), "precondition");
        assert!(
            b.set_keymap_rmlvo("evdev", "pc105", "de", "", None)
                .is_some()
        );
        assert_eq!(b.current_led_bits(), 0, "fresh state");
        assert_eq!(b.leds_sent, 0, "LEDs resynced by the reload");
    }

    /// An edit carries Caps Lock across, but when the edit takes away the
    /// only key that locks it, the lock is released and the LED must go off.
    #[test]
    fn keymap_edit_resyncs_the_lock_leds() {
        let mut b = KmsBackend::for_tests();
        let _ = b.cook_host_key(caps_key(true));
        let _ = b.cook_host_key(caps_key(false));
        assert_eq!(b.leds_sent, input::Led::CAPSLOCK.bits(), "precondition");

        // Same description: Caps Lock and its LED stay on.
        let same = b.core.xkb_desc.clone();
        b.install_desc(same).expect("compiles");
        assert_eq!(b.leds_sent, input::Led::CAPSLOCK.bits(), "lock carried");

        caps_as_control(&mut b);
        assert_eq!(b.current_led_bits(), 0, "no key locks Lock any more");
        assert_eq!(b.leds_sent, 0, "LEDs resynced by the edit");
    }

    /// GetKbdByName for the base layout after an edit reloads it (Xorg
    /// reloads on every load), where a pristine keymap reports no change.
    #[test]
    fn get_kbd_by_name_reloads_an_edited_keymap() {
        use yserver_core::backend::{Backend, KeymapLoad};
        let mut b = KmsBackend::for_tests();
        let symbols = "pc+us+de:2+us:3+inet(evdev)";
        assert!(matches!(
            b.load_keymap_by_components(symbols),
            KeymapLoad::Loaded { changed: true, .. }
        ));
        assert!(matches!(
            b.load_keymap_by_components(symbols),
            KeymapLoad::Loaded { changed: false, .. }
        ));
        caps_as_control(&mut b);
        assert!(matches!(
            b.load_keymap_by_components(symbols),
            KeymapLoad::Loaded { changed: true, .. }
        ));
        assert_eq!(
            b.core
                .xkb_keymap
                .0
                .key_get_syms_by_level(xkbcommon::xkb::Keycode::new(66), 0, 0)[0]
                .raw(),
            xkbcommon::xkb::keysyms::KEY_Caps_Lock,
            "the reload dropped the edit"
        );
    }

    /// `_XKB_RULES_NAMES` keeps naming the base RMLVO through an edit, and
    /// `setxkbmap` with that same RMLVO then reloads.
    #[test]
    fn set_keymap_rmlvo_reloads_an_edited_keymap() {
        use yserver_core::backend::Backend;
        let mut b = KmsBackend::for_tests();
        let names = b.current_xkb_rules_names();
        caps_as_control(&mut b);
        assert_eq!(b.current_xkb_rules_names(), names, "base RMLVO reported");
        let [r, m, l, v, o] = names.expect("names");
        let opts = (!o.is_empty()).then_some(o.as_str());
        assert!(
            b.set_keymap_rmlvo(&r, &m, &l, &v, opts).is_some(),
            "reloads"
        );
        assert_eq!(b.set_keymap_rmlvo(&r, &m, &l, &v, opts), None, "pristine");
    }

    /// Cinnamon alt-tab regression (2026-06-10): `query_pointer`'s
    /// KeyButMask must include the LIVE keyboard modifier state, not
    /// only the held buttons. `XIQueryPointer`'s ModifierInfo is
    /// filled from this mask (Xorg fills the reply from the paired
    /// MASTER_KEYBOARD's XKB state — Xi/xiquerypointer.c:120,139);
    /// with the modifiers missing, cinnamon's switcher polled
    /// `global.get_pointer()` right after pushModal, read "Alt not
    /// held", and instantly cancelled the popup (instant window
    /// switch, no switcher UI).
    #[test]
    fn query_pointer_mask_includes_live_keyboard_modifiers() {
        use yserver_core::{backend::Backend, host_x11::HostKeyEvent};
        let mut b = KmsBackend::for_tests();
        // 50 == evdev KEY_LEFTSHIFT — proven to flip a modifier bit in
        // the test keymap by `cook_host_key_fills_coords_and_modifier_state`.
        let raw = HostKeyEvent {
            origin: yserver_core::core_loop::InputOrigin::NestedHost,
            keycode: 50,
            pressed: true,
            state: 0,
            root_x: 0,
            root_y: 0,
            event_x: 0,
            event_y: 0,
            time: 0,
        };
        let _ = b.cook_host_key(raw);
        let p = Backend::query_pointer(&mut b, None).expect("query_pointer");
        assert_ne!(
            p.mask & 0x00ff,
            0,
            "KeyButMask from query_pointer must include the held modifier \
             — XIQueryPointer's ModifierInfo (cinnamon alt-tab) reads it",
        );
    }

    /// `process_pointer_button` honours the X11 spec's pre-press
    /// `state` field: on ButtonPress the button bit is NOT yet
    /// set in `state`, on ButtonRelease it IS still set.
    /// `button_mask` is updated AFTER the event so the next
    /// motion sees the new mask.
    #[test]
    fn process_pointer_button_state_field_is_pre_press() {
        use yserver_core::{host_x11::PointerEventKind, server::ServerState};
        let mut b = KmsBackend::for_tests();
        let state = ServerState::new();
        // BTN_LEFT press → detail=1, button bit = 0x0100.
        b.process_pointer_button(
            0x110,
            true,
            &state,
            yserver_core::core_loop::InputOrigin::XTest(4),
        );
        let press = b
            .core
            .pending_pointer_events
            .iter()
            .find(|e| matches!(e.kind, PointerEventKind::ButtonPress))
            .expect("ButtonPress emitted");
        assert_eq!(press.detail, 1);
        assert_eq!(
            press.state & 0x0100,
            0,
            "Button1 bit must NOT be set in ButtonPress.state (pre-press)"
        );
        assert_eq!(
            b.core.button_mask & 0x0100,
            0x0100,
            "button_mask updated post-event"
        );

        b.core.pending_pointer_events.clear();
        b.process_pointer_button(
            0x110,
            false,
            &state,
            yserver_core::core_loop::InputOrigin::XTest(4),
        );
        let release = b
            .core
            .pending_pointer_events
            .iter()
            .find(|e| matches!(e.kind, PointerEventKind::ButtonRelease))
            .expect("ButtonRelease emitted");
        assert_eq!(
            release.state & 0x0100,
            0x0100,
            "Button1 bit MUST be set in ButtonRelease.state (still held)"
        );
        assert_eq!(
            b.core.button_mask & 0x0100,
            0,
            "button_mask cleared post-release"
        );
    }

    #[test]
    fn pointer_source_routing_kms_preserves_origin_and_drops_unknown_before_cursor_motion() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId},
        };

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        backend
            .core
            .xid_map
            .insert(backend.core.window_id, yserver_core::resources::ROOT_WINDOW);
        let initial_cursor = (backend.core.cursor_x, backend.core.cursor_y);
        Backend::on_host_input(
            &mut backend,
            &mut state,
            HostInputEvent::PointerMotion {
                origin: InputOrigin::Physical(InputSourceId(999)),
                x: 123,
                y: 45,
                time: 1,
                relative: false,
                dx: 0,
                dy: 0,
                motion_delta: None,
            },
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            initial_cursor
        );
        assert_eq!(state.pointer_root, (0, 0));
        assert_eq!(backend.core.pending_pointer_events.len(), 0);
        assert_eq!(state.xi_devices.devices().len(), 4);

        let source = InputSourceId(201);
        state.xi_register_source(&DeviceInfo {
            source_id: source,
            enabled: true,
            resume_key: None,
            capabilities: InputCapabilities {
                keyboard: false,
                pointer: true,
                touch: false,
            },
            name: "test mouse".into(),
            device_node: "/dev/input/event201".into(),
            sysname: "event201".into(),
            vendor_id: 1,
            product_id: 2,
            is_touchpad: false,
            config: LibinputConfigSnapshot::default(),
        });
        Backend::on_host_input(
            &mut backend,
            &mut state,
            HostInputEvent::PointerMotion {
                origin: InputOrigin::Physical(source),
                x: 20,
                y: 30,
                time: 2,
                relative: false,
                dx: 0,
                dy: 0,
                motion_delta: None,
            },
        );
        assert_eq!((backend.core.cursor_x, backend.core.cursor_y), (20.0, 30.0));
        assert_eq!(state.pointer_root, (20, 30));
        assert_eq!(backend.core.pending_pointer_events.len(), 0);
        assert_eq!(state.xi_devices.devices().len(), 5);
        assert_eq!(
            state
                .xi_devices
                .facet(source, yserver_core::xinput::XiFacetKind::PointerTouch),
            Some(6)
        );
        assert_eq!(state.buttons_down, 0);

        // Exercise the KMS event builder directly as well: on_host_input
        // drains this production queue immediately into core fanout, while
        // process_pointer_absolute exposes the HostPointerEvents it builds.
        backend.process_pointer_absolute(
            &mut state,
            21.0,
            31.0,
            false,
            0,
            0,
            InputOrigin::Physical(source),
        );
        assert_eq!((backend.core.cursor_x, backend.core.cursor_y), (21.0, 31.0));
        let emitted = std::mem::take(&mut backend.core.pending_pointer_events);
        assert_eq!(
            emitted.iter().map(|event| event.kind).collect::<Vec<_>>(),
            vec![yserver_core::host_x11::PointerEventKind::MotionNotify],
        );
        assert!(
            emitted
                .iter()
                .all(|event| event.origin == InputOrigin::Physical(source))
        );
        assert!(backend.core.pending_pointer_events.is_empty());

        let mut disabled = state.xi_devices.source(source).unwrap().clone();
        disabled.enabled = false;
        state.xi_register_source(&disabled);
        Backend::on_host_input(
            &mut backend,
            &mut state,
            HostInputEvent::PointerMotion {
                origin: InputOrigin::Physical(source),
                x: 500,
                y: 400,
                time: 3,
                relative: false,
                dx: 0,
                dy: 0,
                motion_delta: None,
            },
        );
        assert_eq!((backend.core.cursor_x, backend.core.cursor_y), (21.0, 31.0));
        assert_eq!(state.pointer_root, (20, 30));
        assert!(backend.core.pending_pointer_events.is_empty());
        assert!(!state.xi_devices.device(6).unwrap().enabled);
        assert_eq!(state.xi_devices.devices().len(), 5);
    }

    #[test]
    fn pointer_source_selection_kms_rejects_unknown_removed_and_suspended_button_sources() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            server::{ActivePointerGrab, ServerState},
            xinput::{InputCapabilities, InputSourceId},
        };

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        backend
            .core
            .xid_map
            .insert(backend.core.window_id, yserver_core::resources::ROOT_WINDOW);
        let active_grab = ActivePointerGrab {
            owner: yserver_protocol::x11::ClientId(1),
            grab_window: yserver_core::resources::ROOT_WINDOW,
            event_mask: 0,
            cursor: yserver_protocol::x11::ResourceId(0),
            time: 7,
            owner_events: false,
            via_xi2: false,
            implicit: false,
            passive: false,
            xi2_mask: 0,
        };
        state.set_pointer_grab(active_grab);

        let make_info = |source_id: InputSourceId| DeviceInfo {
            source_id,
            enabled: true,
            resume_key: None,
            capabilities: InputCapabilities {
                keyboard: false,
                pointer: true,
                touch: false,
            },
            name: format!("button source {}", source_id.0),
            device_node: format!("/dev/input/event{}", source_id.0),
            sysname: format!("event{}", source_id.0),
            vendor_id: 1,
            product_id: source_id.0 as u32,
            is_touchpad: false,
            config: LibinputConfigSnapshot::default(),
        };
        let removed = InputSourceId(401);
        let suspended = InputSourceId(402);
        state.xi_register_source(&make_info(removed));
        state.xi_register_source(&make_info(suspended));
        assert_eq!(state.xi_unregister_source(removed), vec![6]);
        let mut suspended_info = state.xi_devices.source(suspended).unwrap().clone();
        suspended_info.enabled = false;
        state.xi_register_source(&suspended_info);

        let initial_cursor = (backend.core.cursor_x, backend.core.cursor_y);
        let initial_devices = state.xi_devices.devices().to_vec();
        let initial_device_input_state = initial_devices
            .iter()
            .map(|device| {
                (
                    device.id,
                    device.enabled,
                    device.source_id,
                    device.facet,
                    device.attached_master,
                    device.buttons_down,
                    device.scroll_axis_values,
                )
            })
            .collect::<Vec<_>>();
        let grab_state = |grab: ActivePointerGrab| {
            (
                grab.owner,
                grab.grab_window,
                grab.event_mask,
                grab.cursor,
                grab.time,
                grab.owner_events,
                grab.via_xi2,
                grab.implicit,
                grab.passive,
                grab.xi2_mask,
            )
        };
        let initial_grab = state.active_pointer_grab.map(grab_state);
        for origin in [
            InputOrigin::Physical(InputSourceId(999)),
            InputOrigin::Physical(removed),
            InputOrigin::Physical(suspended),
        ] {
            Backend::on_host_input(
                &mut backend,
                &mut state,
                HostInputEvent::PointerButton {
                    origin,
                    button: 0x110,
                    pressed: true,
                    time: 10,
                },
            );
            assert_eq!(
                backend.core.button_mask, 0,
                "rejected input changes no KMS hold"
            );
            assert_eq!(
                (backend.core.cursor_x, backend.core.cursor_y),
                initial_cursor
            );
            assert!(backend.core.pending_pointer_events.is_empty());
            assert_eq!(
                state.buttons_down, 0,
                "rejected input changes no master hold"
            );
            assert_eq!(state.pointer_root, (0, 0));
            assert!(state.pointer_motion_history.is_empty());
            assert!(state.sync_pending.is_empty());
            assert!(state.xi1_device_input_state.is_empty());
            assert_eq!(state.active_pointer_grab.map(grab_state), initial_grab);
            assert_eq!(state.xi_devices.devices().len(), initial_devices.len());
            assert_eq!(
                state
                    .xi_devices
                    .devices()
                    .iter()
                    .map(|device| {
                        (
                            device.id,
                            device.enabled,
                            device.source_id,
                            device.facet,
                            device.attached_master,
                            device.buttons_down,
                            device.scroll_axis_values,
                        )
                    })
                    .collect::<Vec<_>>(),
                initial_device_input_state,
            );
            assert!(!state.xi_devices.source(suspended).unwrap().enabled);
        }
        assert!(state.xi_devices.source(removed).is_none());
        assert!(state.xi_devices.device(6).is_none());
        assert_eq!(state.xi_devices.device(7).unwrap().buttons_down, 0);
        assert_eq!(
            state.xi_devices.device(7).unwrap().scroll_axis_values,
            [0, 0]
        );
    }

    /// `warp_pointer_root` (the WarpPointer path on KMS) must move
    /// the tracked cursor and fan the resulting motion out — the
    /// fanout caches the position in `state.pointer_root`. Pre-fix
    /// `warp_pointer` was a `log_render_gap` stub, so XWarpPointer never
    /// moved the pointer and every xts5 Xlib11 event-delivery test
    /// pressed buttons at the stale center position, missing its
    /// test window ("Expected event not received" en masse).
    #[test]
    fn warp_pointer_root_moves_cursor_and_fans_out_motion() {
        use yserver_core::server::ServerState;
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        Backend::warp_pointer_root(&mut b, &mut state, 123, 45);
        assert_eq!(b.core.cursor_x, 123.0);
        assert_eq!(b.core.cursor_y, 45.0);
        assert_eq!(
            state.pointer_root,
            (123, 45),
            "the warp motion must reach the pointer fanout",
        );
    }

    /// `process_pointer_absolute` clamps to the output extent and
    /// updates `cursor_x` / `cursor_y`. Single-output test fixture
    /// reports 800×600 from PlatformBackend::for_tests.
    #[test]
    fn process_pointer_absolute_clamps_to_output() {
        use yserver_core::server::ServerState;
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        // Inside extent.
        b.process_pointer_absolute(
            &mut state,
            100.0,
            200.0,
            true,
            0,
            0,
            yserver_core::core_loop::InputOrigin::XTest(4),
        );
        assert_eq!(b.core.cursor_x, 100.0);
        assert_eq!(b.core.cursor_y, 200.0);
        // Past extent → clamped to (extent - 1).
        b.process_pointer_absolute(
            &mut state,
            5000.0,
            5000.0,
            true,
            0,
            0,
            yserver_core::core_loop::InputOrigin::XTest(4),
        );
        assert_eq!(b.core.cursor_x, 799.0);
        assert_eq!(b.core.cursor_y, 599.0);
    }

    /// Confinement must happen before KMS chooses the pointer window.
    /// Otherwise motion beyond the right edge queues EnterNotify for an
    /// overlapping window below before the core fanout clamps MotionNotify.
    /// dwm focuses that entered window, making SDL release/reacquire its grab
    /// and flicker the visible cursor continuously (#99).
    #[test]
    fn confined_motion_does_not_cross_into_window_below() {
        use yserver_core::{
            backend::WindowHandle,
            resources::{ROOT_VISUAL, ROOT_WINDOW},
            server::ServerState,
        };
        use yserver_protocol::x11::{ClientId, CreateWindowRequest, ResourceId};

        const BELOW: ResourceId = ResourceId(0x0020_0001);
        const GAME: ResourceId = ResourceId(0x0030_0001);
        const BELOW_HOST: u32 = 0x8000_0001;
        const GAME_HOST: u32 = 0x8000_0002;

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        for (xid, x, y, width, height, host) in [
            (BELOW, 0, 0, 800, 600, BELOW_HOST),
            (GAME, 100, 100, 100, 100, GAME_HOST),
        ] {
            state.resources.create_window(
                ClientId(1),
                CreateWindowRequest {
                    depth: 24,
                    window: xid,
                    parent: ROOT_WINDOW,
                    x,
                    y,
                    width,
                    height,
                    border_width: 0,
                    class: 1,
                    visual: ROOT_VISUAL,
                    ..Default::default()
                },
            );
            state.resources.window_mut(xid).unwrap().host_xid = WindowHandle::from_raw(host);
            assert!(state.resources.map_window(xid).mapping_changed);
            b.windows.insert(
                host,
                super::WindowGeometry {
                    border_width: 0,
                    border_pixel: None,
                    border_pixmap: None,
                    x,
                    y,
                    width,
                    height,
                    depth: 24,
                    mapped: true,
                    viewable: true,
                    parent: None,
                    stack_rank: 0,
                    bg_pixel: None,
                    bg_pixmap: None,
                    cursor: None,
                },
            );
            b.core.xid_map.insert(host, xid);
            b.core.top_level_order.push(host);
        }

        state.pointer_confine_to = GAME;
        state.pointer_root = (199, 150);
        b.core.cursor_x = 199.0;
        b.core.cursor_y = 150.0;
        b.core.prev_pointer_window = Some(GAME_HOST);

        b.process_pointer_absolute(
            &mut state,
            220.0,
            150.0,
            true,
            21,
            0,
            yserver_core::core_loop::InputOrigin::XTest(4),
        );

        assert_eq!((b.core.cursor_x, b.core.cursor_y), (199.0, 150.0));
        assert_eq!(state.pointer_root, (199, 150));
        assert_eq!(b.core.prev_pointer_window, Some(GAME_HOST));
    }

    /// Multi-output regression: the pointer clamp must use the
    /// union framebuffer extent (`PlatformBackend.fb_w/fb_h`),
    /// NOT `outputs.first().width/height`. Pre-fix the clamp
    /// consulted only the first output, so the cursor could never
    /// cross from monitor 0 onto monitor 1 in a side-by-side
    /// layout.
    ///
    /// Two side-by-side 2560×1440 monitors and the `fb_w` of 5120 that
    /// `core_platform_init` computes as `max(x + width)` across them
    /// (`kms/backend.rs:1063-1072`). The input thread already targets that
    /// union extent at thread spawn, so v2 receives `PointerMotion { x, y }`
    /// already in virtual-screen coords; the only divergence was v2's
    /// re-clamp.
    #[test]
    fn process_pointer_absolute_uses_union_fb_extent_for_multi_output() {
        use yserver_core::server::ServerState;
        let mut b = KmsBackend::for_tests();
        push_test_output(&mut b, 2);
        for (i, output) in b.platform.outputs.iter_mut().enumerate() {
            output.x = 2560 * i32::try_from(i).unwrap();
            output.width = 2560;
            output.height = 1440;
        }
        b.platform.fb_w = 5120;
        b.platform.fb_h = 1440;
        let mut state = ServerState::new();
        // Point on monitor 1 (x=4000 is past output[0]'s 800-wide
        // fixture extent but well within the 5120 union extent).
        b.process_pointer_absolute(
            &mut state,
            4000.0,
            1000.0,
            true,
            0,
            0,
            yserver_core::core_loop::InputOrigin::XTest(4),
        );
        assert_eq!(
            b.core.cursor_x, 4000.0,
            "pointer must be able to cross past the first output's \
             extent; pre-fix this clamps to 799 and the cursor is \
             stuck on monitor 0",
        );
        assert_eq!(b.core.cursor_y, 1000.0);
        // Past the union extent → clamped to (union - 1).
        b.process_pointer_absolute(
            &mut state,
            9999.0,
            9999.0,
            true,
            0,
            0,
            yserver_core::core_loop::InputOrigin::XTest(4),
        );
        assert_eq!(b.core.cursor_x, 5119.0);
        assert_eq!(b.core.cursor_y, 1439.0);
    }

    /// Absolute motion must bypass pointer barriers. This mirrors the
    /// touch/tablet path: the backend delivers the motion with
    /// `relative=false`, so the core motion fanout keeps the absolute
    /// coordinates untouched even when a solid barrier sits in the path.
    #[test]
    fn process_pointer_absolute_skips_pointer_barriers_when_absolute() {
        use yserver_core::{
            core_loop::HostInputEvent,
            server::{PointerBarrier, ServerState},
        };
        use yserver_protocol::x11::ClientId;

        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.pointer_root = (90, 50);
        state.pointer_barriers.insert(
            0x0050_0001,
            PointerBarrier {
                owner: ClientId(1),
                window: yserver_core::resources::ROOT_WINDOW,
                x1: 100,
                y1: 0,
                x2: 100,
                y2: 200,
                directions: 0,
                devices: Vec::new(),
                hit: false,
                seen: false,
                event_id: 1,
                release_event_id: 0,
                last_timestamp: 0,
            },
        );

        b.on_host_input(
            &mut state,
            HostInputEvent::PointerMotion {
                origin: yserver_core::core_loop::InputOrigin::NestedHost,
                x: 110,
                y: 50,
                time: 0,
                relative: false,
                dx: 0,
                dy: 0,
                motion_delta: None,
            },
        );

        assert_eq!(b.core.cursor_x, 110.0);
        assert_eq!(b.core.cursor_y, 50.0);
        assert_eq!(state.pointer_root, (110, 50));
    }

    #[test]
    fn kms_pointer_authority_integrates_relative_motion_against_pointer_barriers() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            server::{PointerBarrier, ServerState},
            xinput::{InputCapabilities, InputSourceId},
        };
        use yserver_protocol::x11::{ClientId, ResourceId};

        const SOURCE: InputSourceId = InputSourceId(0xB11);
        const BARRIER: ResourceId = ResourceId(0x0050_0001);

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(DeviceInfo {
                source_id: SOURCE,
                enabled: true,
                resume_key: None,
                capabilities: InputCapabilities {
                    keyboard: false,
                    pointer: true,
                    touch: false,
                },
                name: "barrier test pointer".to_owned(),
                device_node: "/dev/input/barrier-test".to_owned(),
                sysname: "barrier-test".to_owned(),
                vendor_id: 0,
                product_id: 0,
                is_touchpad: false,
                config: LibinputConfigSnapshot::default(),
            }),
        );
        state.pointer_barriers.insert(
            BARRIER.0,
            PointerBarrier {
                owner: ClientId(1),
                window: yserver_core::resources::ROOT_WINDOW,
                x1: 100,
                y1: 0,
                x2: 100,
                y2: 200,
                directions: 0,
                devices: Vec::new(),
                hit: false,
                seen: false,
                event_id: 1,
                release_event_id: 0,
                last_timestamp: 0,
            },
        );

        // Use the same solid barrier setup as the existing absolute-motion
        // test: release_event_id != event_id keeps it solid.
        Backend::warp_pointer_root(&mut backend, &mut state, 90, 50);
        let physical_motion = |time, x, dx, relative, motion_delta| HostInputEvent::PointerMotion {
            origin: InputOrigin::Physical(SOURCE),
            x,
            y: 50,
            time,
            relative,
            dx,
            dy: 0,
            motion_delta,
        };

        // Physical absolute input represents touch/tablet motion and bypasses
        // this barrier, as in the existing absolute-motion regression.
        backend.on_host_input(&mut state, physical_motion(1, 110, 11, false, None));
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (110.0, 50.0)
        );
        assert_eq!(state.pointer_root, (110, 50));
        Backend::warp_pointer_root(&mut backend, &mut state, 90, 50);

        // Consecutive physical relative events approach and cross x=100.
        // KMS must integrate each from its current (barrier-clamped) cursor.
        backend.on_host_input(
            &mut state,
            physical_motion(2, 700, 8, true, Some([8.0, 0.0])),
        );
        assert_eq!((backend.core.cursor_x, backend.core.cursor_y), (98.0, 50.0));
        assert_eq!(state.pointer_root, (98, 50));

        backend.on_host_input(
            &mut state,
            physical_motion(3, 700, 10, true, Some([10.0, 0.0])),
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (99.0, 50.0),
            "relative motion must stop immediately before the solid barrier",
        );
        assert_eq!(state.pointer_root, (99, 50));

        backend.on_host_input(
            &mut state,
            physical_motion(4, 700, -5, true, Some([-5.0, 0.0])),
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (94.0, 50.0),
            "the next relative delta away from the wall starts at the clamped cursor",
        );
        assert_eq!(state.pointer_root, (94, 50));

        assert_eq!(backend.core.cursor_x, state.pointer_root.0 as f32);
        assert_eq!(backend.core.cursor_y, state.pointer_root.1 as f32);
        assert!(backend.core.pending_pointer_events.is_empty());
        assert!(state.sync_pending.is_empty());
    }

    /// `window_under_cursor` returns the topmost mapped top-level
    /// containing the cursor. Walks `core.top_level_order` back-to-
    /// front so the most-recently-stacked window wins. Unmapped
    /// windows skipped.
    #[test]
    fn window_under_cursor_finds_topmost_mapped() {
        let mut b = KmsBackend::for_tests();
        b.windows.insert(
            0x1000,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.windows.insert(
            0x2000,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 50,
                y: 50,
                width: 100,
                height: 100,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 1,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.core.top_level_order.push(0x1000);
        b.core.top_level_order.push(0x2000);

        // Cursor in overlap (50..100, 50..100): 0x2000 wins (topmost).
        b.core.cursor_x = 75.0;
        b.core.cursor_y = 75.0;
        assert_eq!(b.window_under_cursor(), Some(0x2000));

        // Cursor outside overlap, only in 0x1000.
        b.core.cursor_x = 25.0;
        b.core.cursor_y = 25.0;
        assert_eq!(b.window_under_cursor(), Some(0x1000));

        // Cursor outside both — root-fallback handled at caller.
        b.core.cursor_x = 300.0;
        b.core.cursor_y = 300.0;
        assert_eq!(b.window_under_cursor(), None);

        // Unmapping the topmost — next match wins.
        b.windows.get_mut(&0x2000).unwrap().mapped = false;
        b.core.cursor_x = 75.0;
        b.core.cursor_y = 75.0;
        assert_eq!(b.window_under_cursor(), Some(0x1000));
    }

    /// `window_under_cursor` descends into mapped sub-windows so the
    /// returned xid is the deepest match. xfwm4 attaches resize-edge
    /// cursors to frame sub-windows; without descent the cursor walk
    /// stops at the (cursor=None) frame top-level and the resize
    /// sprites never become effective on hover. Pinned: top-edge
    /// child wins when pointer is in the edge band; the frame
    /// top-level wins in the interior; topmost sibling wins on
    /// overlap; unmapped sub-windows are skipped (parent wins).
    #[test]
    fn window_under_cursor_descends_into_subwindow_tree() {
        let mut b = KmsBackend::for_tests();
        // Frame top-level at (100,100, 800x600), no cursor.
        b.windows.insert(
            0x1000,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 100,
                y: 100,
                width: 800,
                height: 600,
                depth: 24,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.core.top_level_order.push(0x1000);
        // Top-edge resize sub-window at parent-local (0,0, 800x10),
        // i.e. screen (100,100, 800x10). Has its own resize cursor.
        b.windows.insert(
            0x1001,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 800,
                height: 10,
                depth: 24,
                mapped: true,
                viewable: true,
                parent: Some(0x1000),
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: Some(0xdead_0001),
            },
        );
        // Bottom-edge resize sub-window at parent-local (0,590, 800x10),
        // screen (100,690, 800x10). Different cursor.
        b.windows.insert(
            0x1002,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 590,
                width: 800,
                height: 10,
                depth: 24,
                mapped: true,
                viewable: true,
                parent: Some(0x1000),
                stack_rank: 1,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: Some(0xdead_0002),
            },
        );

        // Cursor in the top-edge band: deepest hit is the top sub-window.
        b.core.cursor_x = 150.0;
        b.core.cursor_y = 105.0;
        assert_eq!(b.window_under_cursor(), Some(0x1001));

        // Cursor in the bottom-edge band: bottom sub-window.
        b.core.cursor_x = 150.0;
        b.core.cursor_y = 695.0;
        assert_eq!(b.window_under_cursor(), Some(0x1002));

        // Cursor in the frame interior (not in any edge band): the
        // frame top-level itself.
        b.core.cursor_x = 400.0;
        b.core.cursor_y = 300.0;
        assert_eq!(b.window_under_cursor(), Some(0x1000));

        // Overlap test — add a second top-edge child at the same
        // location with higher stack_rank; topmost wins.
        b.windows.insert(
            0x1003,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 800,
                height: 10,
                depth: 24,
                mapped: true,
                viewable: true,
                parent: Some(0x1000),
                stack_rank: 99,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: Some(0xdead_0003),
            },
        );
        b.core.cursor_x = 150.0;
        b.core.cursor_y = 105.0;
        assert_eq!(b.window_under_cursor(), Some(0x1003));

        // Unmap the topmost overlap entry — sibling beneath wins.
        b.windows.get_mut(&0x1003).unwrap().mapped = false;
        assert_eq!(b.window_under_cursor(), Some(0x1001));
    }

    /// `on_host_input` no longer logs the `v2: on_host_input not
    /// yet implemented` gap that fired before 3f.7. Key events
    /// drain through xkb cooking; pointer events drain to the
    /// pointer fanout.
    #[test]
    fn on_host_input_does_not_log_gap() {
        use yserver_core::{core_loop::HostInputEvent, server::ServerState};
        let mut b = KmsBackend::for_tests();
        let mut state = ServerState::new();
        // PointerMotion → process_pointer_absolute → no panic, no gap.
        b.on_host_input(
            &mut state,
            HostInputEvent::PointerMotion {
                origin: yserver_core::core_loop::InputOrigin::NestedHost,
                x: 10,
                y: 20,
                time: 0,
                relative: false,
                dx: 0,
                dy: 0,
                motion_delta: None,
            },
        );
        assert!(
            !b.logged_gaps.borrow().contains("on_host_input"),
            "on_host_input must not log a gap post-3f.7"
        );
        assert_eq!(b.core.cursor_x, 10.0);
        assert_eq!(b.core.cursor_y, 20.0);
    }

    #[test]
    fn xi_dynamic_grabs_kms_slave_cleanup_does_not_freeze_paired_master() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const CLIENT: u32 = 7;
        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let _peer = kbd_map_client_id(&mut state, CLIENT);
        let source_id = InputSourceId(0xA11);
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(DeviceInfo {
                source_id,
                enabled: true,
                resume_key: None,
                capabilities: InputCapabilities {
                    keyboard: false,
                    pointer: true,
                    touch: false,
                },
                name: "floating pointer".to_owned(),
                device_node: "/dev/input/test-floating-pointer".to_owned(),
                sysname: "test-floating-pointer".to_owned(),
                vendor_id: 0,
                product_id: 0,
                is_touchpad: false,
                config: LibinputConfigSnapshot::default(),
            }),
        );
        let device_id = state
            .xi_devices
            .facet(source_id, XiFacetKind::PointerTouch)
            .expect("DeviceAdded publishes the pointer facet");

        let mut grab_body = Vec::with_capacity(20);
        grab_body.extend_from_slice(&yserver_core::resources::ROOT_WINDOW.0.to_le_bytes());
        grab_body.extend_from_slice(&0u32.to_le_bytes());
        grab_body.extend_from_slice(&0u32.to_le_bytes());
        grab_body.extend_from_slice(&device_id.to_le_bytes());
        grab_body.extend_from_slice(&[1, 0, 0, 0]); // async, requested paired sync, owner_events=false
        grab_body.extend_from_slice(&0u16.to_le_bytes());
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            yserver_protocol::x11::ClientId(CLIENT),
            yserver_protocol::x11::SequenceNumber(1),
            yserver_protocol::x11::RequestHeader {
                opcode: 137,
                data: 51,
                length_units: 6,
            },
            &grab_body,
            None,
        )
        .expect("XIGrabDevice on the source's pointer facet");
        assert!(state.xi2_pointer_grabs.contains_key(&device_id));
        assert_eq!(
            state.xi_devices.device(device_id).unwrap().attached_master,
            None
        );

        assert!(state.floating_pointer_positions.contains_key(&device_id));
        assert_eq!(
            state
                .xi1_frozen
                .get(&yserver_core::xinput::DEVICEID_MASTER_KEYBOARD)
                .and_then(|freeze| freeze.other),
            None,
            "Xorg forces a slave grab's paired mode to Async",
        );
        backend.on_host_input(
            &mut state,
            HostInputEvent::Key(HostKeyEvent {
                origin: yserver_core::core_loop::InputOrigin::NestedHost,
                pressed: true,
                keycode: 30,
                time: 0x1234,
                root_x: 10,
                root_y: 20,
                event_x: 10,
                event_y: 20,
                state: 0,
            }),
        );
        assert!(
            state.sync_pending.is_empty(),
            "the paired master keyboard is not frozen"
        );

        backend.on_host_input(&mut state, HostInputEvent::DeviceRemoved { source_id });
        assert!(state.xi_devices.source(source_id).is_none());
        assert!(state.xi_devices.device(device_id).is_none());
        assert!(!state.xi2_pointer_grabs.contains_key(&device_id));
        assert!(!state.xi2_detached_masters.contains_key(&device_id));
        assert!(!state.floating_pointer_positions.contains_key(&device_id));
        assert!(!state.xi1_frozen.contains_key(&device_id));
        assert!(state.sync_pending.is_empty());
        assert!(
            !state
                .xi1_frozen
                .get(&yserver_core::xinput::DEVICEID_MASTER_KEYBOARD)
                .is_some_and(yserver_core::server::Xi1Freeze::frozen),
            "source removal leaves the paired master keyboard unfrozen",
        );
    }

    #[test]
    fn key_source_selection_repeat_after_another_keyboard_becomes_active() {
        use yserver_core::{
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const A: InputSourceId = InputSourceId(0xA31);
        const B: InputSourceId = InputSourceId(0xA32);

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        for (source_id, name) in [(A, "Keyboard A"), (B, "Keyboard B")] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(DeviceInfo {
                    source_id,
                    enabled: true,
                    resume_key: None,
                    capabilities: InputCapabilities {
                        keyboard: true,
                        pointer: false,
                        touch: false,
                    },
                    name: name.to_owned(),
                    device_node: format!("/dev/input/{name}"),
                    sysname: name.to_owned(),
                    vendor_id: 0,
                    product_id: 0,
                    is_touchpad: false,
                    config: LibinputConfigSnapshot::default(),
                }),
            );
        }
        let a_id = state
            .xi_devices
            .facet(A, XiFacetKind::Keyboard)
            .expect("Keyboard A facet");
        let b_id = state
            .xi_devices
            .facet(B, XiFacetKind::Keyboard)
            .expect("Keyboard B facet");
        let key = |source_id, keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(source_id),
                pressed,
                keycode,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };

        yserver_core::core_loop::run::handle_host_input(&mut state, &mut backend, key(A, 38, true));
        yserver_core::core_loop::run::handle_host_input(&mut state, &mut backend, key(B, 39, true));

        assert_eq!(
            state
                .key_repeats
                .get(&InputOrigin::Physical(A))
                .map(|repeat| repeat.event.origin),
            Some(InputOrigin::Physical(A)),
            "Keyboard B's activity must not steal Keyboard A's repeat attribution",
        );
        assert!(state.key_down_by_device[&a_id].contains_key(&38));
        assert!(state.key_down_by_device[&b_id].contains_key(&39));
        let forced_deadline = std::time::Instant::now() - std::time::Duration::from_millis(1);
        state
            .key_repeats
            .get_mut(&InputOrigin::Physical(A))
            .expect("Keyboard A repeat remains armed")
            .next_fire = forced_deadline;
        assert!(yserver_core::core_loop::run::fire_pending_repeats(
            &mut state,
            &mut backend,
        ));
        assert_eq!(
            state.key_repeats[&InputOrigin::Physical(A)].event.origin,
            InputOrigin::Physical(A),
            "the repeat remains attributed to A after B becomes active",
        );
        assert!(state.key_repeats[&InputOrigin::Physical(A)].next_fire > forced_deadline);
        assert_eq!(
            state.key_repeats[&InputOrigin::Physical(B)].event.origin,
            InputOrigin::Physical(B),
            "B's independent repeat remains attributed to B",
        );
        assert!(
            state.key_repeats.contains_key(&InputOrigin::Physical(B)),
            "B's held key retains its own timer after A repeats",
        );
        assert_eq!(state.key_repeats.len(), 2);
        assert_eq!(state.key_down_by_device.len(), 2);
        assert_eq!(
            state.key_down_by_device[&a_id]
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            [38],
        );
        assert_eq!(
            state.key_down_by_device[&b_id]
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            [39],
        );
        assert_eq!(
            backend.core.down_keys,
            std::collections::HashSet::from([38, 39])
        );
        assert!(state.unpublished_keyboard_keys_down.is_empty());
    }

    #[test]
    fn key_source_selection_repeat_stops_after_source_key_is_drained() {
        use yserver_core::{
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };

        const A: InputSourceId = InputSourceId(0xA34);
        const B: InputSourceId = InputSourceId(0xA35);

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        for (source_id, name) in [(A, "Drain A"), (B, "Drain B")] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(DeviceInfo {
                    source_id,
                    enabled: true,
                    resume_key: None,
                    capabilities: InputCapabilities {
                        keyboard: true,
                        pointer: false,
                        touch: false,
                    },
                    name: name.to_owned(),
                    device_node: format!("/dev/input/{name}"),
                    sysname: name.to_owned(),
                    vendor_id: 0,
                    product_id: 0,
                    is_touchpad: false,
                    config: LibinputConfigSnapshot::default(),
                }),
            );
        }
        let a_id = state
            .xi_devices
            .facet(A, XiFacetKind::Keyboard)
            .expect("A keyboard facet");
        let b_id = state
            .xi_devices
            .facet(B, XiFacetKind::Keyboard)
            .expect("B keyboard facet");
        let key = |source_id, keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(source_id),
                pressed,
                keycode,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        yserver_core::core_loop::run::handle_host_input(&mut state, &mut backend, key(A, 38, true));
        yserver_core::core_loop::run::handle_host_input(&mut state, &mut backend, key(B, 39, true));
        backend.release_keyboard_source_keys(&mut state, A);
        state
            .key_repeats
            .get_mut(&InputOrigin::Physical(A))
            .expect("A repeat remains pending until the next timer check")
            .next_fire = std::time::Instant::now() - std::time::Duration::from_millis(1);

        assert!(!yserver_core::core_loop::run::fire_pending_repeats(
            &mut state,
            &mut backend,
        ));
        assert!(
            !state.key_repeats.contains_key(&InputOrigin::Physical(A)),
            "draining A's held key retires A's repeat",
        );
        assert!(state.key_repeats.contains_key(&InputOrigin::Physical(B)));
        assert_eq!(state.key_repeats.len(), 1);
        assert!(!state.key_down_by_device.contains_key(&a_id));
        assert_eq!(state.key_down_by_device.len(), 1);
        assert_eq!(
            state
                .key_down_by_device
                .get(&b_id)
                .map(|keys| keys.keys().copied().collect::<Vec<_>>()),
            Some(vec![39]),
            "B's held key remains untouched",
        );
        assert!(state.unpublished_keyboard_keys_down.is_empty());
        assert!(!backend.core.down_keys.contains(&38));
        assert!(backend.core.down_keys.contains(&39));
    }

    #[test]
    fn key_source_selection_repeat_floating_keyboard_arms_slave_repeat() {
        use yserver_core::{
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        const SOURCE: InputSourceId = InputSourceId(0xA33);
        const CLIENT: u32 = 8;

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        state.core_focus.raw = ROOT_WINDOW.0;
        let mut peer = kbd_map_client_id(&mut state, CLIENT);
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceAdded(DeviceInfo {
                source_id: SOURCE,
                enabled: true,
                resume_key: None,
                capabilities: InputCapabilities {
                    keyboard: true,
                    pointer: false,
                    touch: false,
                },
                name: "Floating keyboard".into(),
                device_node: "/dev/input/floating".into(),
                sysname: "floating".into(),
                vendor_id: 0,
                product_id: 0,
                is_touchpad: false,
                config: LibinputConfigSnapshot::default(),
            }),
        );
        let device_id = state
            .xi_devices
            .facet(SOURCE, XiFacetKind::Keyboard)
            .expect("keyboard facet");
        state
            .clients
            .get_mut(&CLIENT)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, device_id), (1 << 2) | (1 << 3));
        state
            .clients
            .get_mut(&CLIENT)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, 0), (1 << 2) | (1 << 3));
        let mut grab = Vec::with_capacity(24);
        grab.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        grab.extend_from_slice(&0u32.to_le_bytes());
        grab.extend_from_slice(&0u32.to_le_bytes());
        grab.extend_from_slice(&device_id.to_le_bytes());
        grab.extend_from_slice(&[1, 1, 0, 0]);
        grab.extend_from_slice(&1u16.to_le_bytes());
        grab.extend_from_slice(&((1u32 << 2) | (1u32 << 3)).to_le_bytes());
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            ClientId(CLIENT),
            SequenceNumber(1),
            RequestHeader {
                opcode: 137,
                data: 51,
                length_units: 7,
            },
            &grab,
            None,
        )
        .expect("exact keyboard grab floats this slave");
        let _ = kbd_map_drain(&mut peer);
        assert_eq!(
            state.xi_devices.device(device_id).unwrap().attached_master,
            None
        );

        yserver_core::core_loop::run::handle_host_input(
            &mut state,
            &mut backend,
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(SOURCE),
                pressed: true,
                keycode: 38,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            }),
        );

        assert_eq!(
            state
                .key_repeats
                .get(&InputOrigin::Physical(SOURCE))
                .map(|repeat| repeat.event.origin),
            Some(InputOrigin::Physical(SOURCE)),
            "a floating held key repeats in its slave view",
        );
        assert!(
            backend.floating_keyboard_states[&device_id]
                .down_keys
                .contains(&38)
        );
        assert!(!backend.core.down_keys.contains(&38));
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        let master_modifiers = backend.serialize_modifiers();
        let forced_deadline = std::time::Instant::now() - std::time::Duration::from_millis(1);
        state
            .key_repeats
            .get_mut(&InputOrigin::Physical(SOURCE))
            .expect("floating key has a source-local timer")
            .next_fire = forced_deadline;
        assert!(yserver_core::core_loop::run::fire_pending_repeats(
            &mut state,
            &mut backend,
        ));
        assert_eq!(
            state.key_repeats[&InputOrigin::Physical(SOURCE)]
                .event
                .origin,
            InputOrigin::Physical(SOURCE),
            "a floating repeat stays attributed to its slave source",
        );
        assert!(state.key_repeats[&InputOrigin::Physical(SOURCE)].next_fire > forced_deadline);
        assert!(
            backend.floating_keyboard_states[&device_id]
                .down_keys
                .contains(&38)
        );
        assert!(!backend.core.down_keys.contains(&38));
        assert!(state.keys_down.iter().all(|byte| *byte == 0));
        assert_eq!(state.key_down_by_device.len(), 1);
        assert_eq!(
            state.key_down_by_device[&device_id]
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            [38]
        );
        assert_eq!(state.key_repeats.len(), 1);
        assert!(state.unpublished_keyboard_keys_down.is_empty());
        assert_eq!(backend.serialize_modifiers(), master_modifiers);
        assert!(
            state
                .key_repeats
                .contains_key(&InputOrigin::Physical(SOURCE))
        );
    }

    #[test]
    fn xi_dynamic_grabs_floating_keyboard() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            resources::ROOT_WINDOW,
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        const GRAB_CLIENT: u32 = 7;
        const XI_MASTER_CLIENT: u32 = 8;
        const CORE_CLIENT: u32 = 9;
        const RAZER: InputSourceId = InputSourceId(0xA11);
        const HYPERX: InputSourceId = InputSourceId(0xA12);
        const SHIFT_L: u8 = 50;
        const A_KEY: u8 = 38;
        const CAPS_LOCK: u8 = 66;
        const SHIFT_MASK: u16 = 0x01;
        const LOCK_MASK: u16 = 0x02;

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut grab_peer = kbd_map_client_id(&mut state, GRAB_CLIENT);
        let mut xi_master_peer = kbd_map_client_id(&mut state, XI_MASTER_CLIENT);
        let mut core_peer = kbd_map_client_id(&mut state, CORE_CLIENT);
        state.core_focus.raw = ROOT_WINDOW.0;

        for (source_id, name) in [(RAZER, "Razer"), (HYPERX, "HyperX")] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(DeviceInfo {
                    source_id,
                    enabled: true,
                    resume_key: None,
                    capabilities: InputCapabilities {
                        keyboard: true,
                        pointer: false,
                        touch: false,
                    },
                    name: name.to_owned(),
                    device_node: format!("/dev/input/{name}"),
                    sysname: name.to_owned(),
                    vendor_id: 0,
                    product_id: 0,
                    is_touchpad: false,
                    config: LibinputConfigSnapshot::default(),
                }),
            );
        }
        let razer_id = state
            .xi_devices
            .facet(RAZER, XiFacetKind::Keyboard)
            .expect("Razer keyboard facet");
        let hyperx_id = state
            .xi_devices
            .facet(HYPERX, XiFacetKind::Keyboard)
            .expect("HyperX keyboard facet");

        // Select the attached master forms independently: XI2 on one
        // connection, core key events on another.
        state
            .clients
            .get_mut(&XI_MASTER_CLIENT)
            .unwrap()
            .xi2_masks
            .insert(
                (ROOT_WINDOW, yserver_core::xinput::DEVICEID_MASTER_KEYBOARD),
                (1 << 2) | (1 << 3),
            );
        state
            .clients
            .get_mut(&CORE_CLIENT)
            .unwrap()
            .event_masks
            .insert(ROOT_WINDOW, 0x0000_0001 | 0x0000_0002);

        let key = |source_id, keycode, pressed| {
            HostInputEvent::Key(HostKeyEvent {
                origin: yserver_core::core_loop::InputOrigin::Physical(source_id),
                pressed,
                keycode,
                time: 0x1234,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            })
        };
        let send_key =
            |backend: &mut KmsBackend, state: &mut ServerState, source_id, keycode, pressed| {
                yserver_core::core_loop::run::handle_host_input(
                    state,
                    backend,
                    key(source_id, keycode, pressed),
                );
            };

        // A slave attached before it floats already has the master's locked
        // state, as Xorg's XkbPushLockedStateToSlaves keeps it synchronized.
        for pressed in [true, false] {
            send_key(&mut backend, &mut state, HYPERX, CAPS_LOCK, pressed);
        }
        let _ = kbd_map_drain(&mut xi_master_peer);
        let _ = kbd_map_drain(&mut core_peer);
        assert_ne!(backend.current_led_bits(), 0);

        let xi_grab = |device_id: u16| {
            let mut body = Vec::with_capacity(24);
            body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
            body.extend_from_slice(&0u32.to_le_bytes());
            body.extend_from_slice(&0u32.to_le_bytes());
            body.extend_from_slice(&device_id.to_le_bytes());
            body.extend_from_slice(&[1, 1, 0, 0]); // async grab and paired device, no owner events
            body.extend_from_slice(&1u16.to_le_bytes());
            body.extend_from_slice(&((1u32 << 2) | (1u32 << 3)).to_le_bytes());
            body
        };
        let request = |minor_opcode, length_units| RequestHeader {
            opcode: 137,
            data: minor_opcode,
            length_units,
        };
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            ClientId(GRAB_CLIENT),
            SequenceNumber(1),
            request(51, 7),
            &xi_grab(razer_id),
            None,
        )
        .expect("XIGrabDevice on Razer's keyboard facet");
        let _ = kbd_map_drain(&mut grab_peer);
        assert_eq!(
            state.xi_devices.device(razer_id).unwrap().attached_master,
            None,
            "the explicit slave grab floats only Razer",
        );
        assert!(
            backend.floating_keyboard_states.contains_key(&razer_id),
            "detaching Razer allocates its independent XKB state",
        );
        assert_ne!(
            backend.serialize_modifiers() & LOCK_MASK,
            0,
            "HyperX's Caps Lock establishes a master locked modifier before Razer floats",
        );
        assert_eq!(
            KmsBackend::serialize_xkb_modifiers(
                &backend.floating_keyboard_states[&razer_id].xkb_state.0,
                backend.floating_keyboard_states[&razer_id].locked_group,
                backend.keymap_group_count(),
            ) & LOCK_MASK,
            backend.serialize_modifiers() & LOCK_MASK,
            "Razer inherits the master's locked modifier when its floating state is created",
        );
        assert_eq!(
            state.xi_devices.device(hyperx_id).unwrap().attached_master,
            Some(yserver_core::xinput::DEVICEID_MASTER_KEYBOARD),
            "HyperX remains attached to the master keyboard",
        );

        let master_mods_before = backend.serialize_modifiers();
        let master_leds_before = backend.current_led_bits();
        let mut razer_bytes = Vec::new();
        send_key(&mut backend, &mut state, RAZER, SHIFT_L, true);
        razer_bytes.extend(kbd_map_drain(&mut grab_peer));
        assert!(
            backend.floating_keyboard_states[&razer_id]
                .down_keys
                .contains(&SHIFT_L),
            "the first floating Shift press reaches the local XKB state; facet={:?}, attached={:?}, active={:?}, master_active={:?}, bytes={}, outbound={}",
            state
                .xi_devices
                .facet(RAZER, yserver_core::xinput::XiFacetKind::Keyboard),
            state.xi_devices.device(razer_id).unwrap().attached_master,
            state.xi2_keyboard_grabs.get(&razer_id),
            state.active_keyboard_grab,
            razer_bytes.len(),
            state.clients[&GRAB_CLIENT].outbound.len(),
        );
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        assert_eq!(backend.current_led_bits(), master_leds_before);
        send_key(&mut backend, &mut state, RAZER, SHIFT_L, true);
        razer_bytes.extend(kbd_map_drain(&mut grab_peer));
        send_key(&mut backend, &mut state, RAZER, A_KEY, true);
        razer_bytes.extend(kbd_map_drain(&mut grab_peer));
        assert!(
            state
                .key_repeats
                .contains_key(&yserver_core::core_loop::InputOrigin::Physical(RAZER)),
            "a floating held key arms repeat for its slave view",
        );
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        assert_eq!(backend.current_led_bits(), master_leds_before);
        send_key(&mut backend, &mut state, RAZER, A_KEY, false);
        razer_bytes.extend(kbd_map_drain(&mut grab_peer));
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        assert_eq!(backend.current_led_bits(), master_leds_before);
        send_key(&mut backend, &mut state, RAZER, SHIFT_L, false);
        razer_bytes.extend(kbd_map_drain(&mut grab_peer));
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        assert_eq!(backend.current_led_bits(), master_leds_before);
        assert!(
            backend.floating_keyboard_states[&razer_id]
                .down_keys
                .is_empty()
        );
        let razer_events = xi2_events(&razer_bytes);
        assert_eq!(
            razer_events
                .iter()
                .filter(|(kind, device, _, detail, _)| {
                    *kind == 2 && *device == razer_id && *detail == u32::from(SHIFT_L)
                })
                .count(),
            1,
            "the floating keyboard's duplicate guard emits one Shift press: events={razer_events:?}, pending={}, xi1_frozen={:?}, active={:?}, outbound={}",
            state.sync_pending.len(),
            state.xi1_frozen.get(&razer_id),
            state.xi2_keyboard_grabs.get(&razer_id),
            state.clients[&GRAB_CLIENT].outbound.len(),
        );
        assert!(
            razer_events.iter().any(|(kind, device, _, detail, _)| {
                *kind == 2 && *device == razer_id && *detail == u32::from(A_KEY)
            }),
            "floating key events are delivered through Razer's XI2 slave grab: {razer_events:?}",
        );
        let razer_shifted_a = {
            let bytes = &razer_bytes;
            let mut offset = 0usize;
            let mut shifted = false;
            while offset + 32 <= bytes.len() {
                if bytes[offset] == 35 {
                    let length =
                        u32::from_le_bytes(bytes[offset + 4..offset + 8].try_into().unwrap())
                            as usize;
                    let event_len = 32 + length * 4;
                    if offset + event_len > bytes.len() {
                        break;
                    }
                    let kind = u16::from_le_bytes([bytes[offset + 8], bytes[offset + 9]]);
                    let device = u16::from_le_bytes([bytes[offset + 10], bytes[offset + 11]]);
                    let detail =
                        u32::from_le_bytes(bytes[offset + 16..offset + 20].try_into().unwrap());
                    let effective_mods =
                        u32::from_le_bytes(bytes[offset + 72..offset + 76].try_into().unwrap())
                            as u16;
                    shifted |= kind == 2
                        && device == razer_id
                        && detail == u32::from(A_KEY)
                        && effective_mods & SHIFT_MASK != 0;
                    offset += event_len;
                } else {
                    offset += 32;
                }
            }
            shifted
        };
        assert!(
            razer_shifted_a,
            "Razer's own XI2 key event must report its floating Shift modifier",
        );

        // Caps Lock on floating Razer updates only its slave view; it does
        // not change the attached master's modifier state or LED snapshot.
        let mut razer_caps_bytes = Vec::new();
        for _ in 0..2 {
            for pressed in [true, false] {
                send_key(&mut backend, &mut state, RAZER, CAPS_LOCK, pressed);
            }
            send_key(&mut backend, &mut state, RAZER, A_KEY, true);
            assert!(
                state
                    .key_repeats
                    .contains_key(&yserver_core::core_loop::InputOrigin::Physical(RAZER)),
                "a floating held key arms repeat for its slave view",
            );
            send_key(&mut backend, &mut state, RAZER, A_KEY, false);
            assert_eq!(backend.serialize_modifiers(), master_mods_before);
            assert_eq!(backend.current_led_bits(), master_leds_before);
            razer_caps_bytes.extend(kbd_map_drain(&mut grab_peer));
        }
        let razer_caps_events = xi2_events(&razer_caps_bytes);
        let caps_lock_states = {
            let mut offset = 0usize;
            let mut states = Vec::new();
            while offset + 32 <= razer_caps_bytes.len() {
                if razer_caps_bytes[offset] == 35 {
                    let length = u32::from_le_bytes(
                        razer_caps_bytes[offset + 4..offset + 8].try_into().unwrap(),
                    ) as usize;
                    let event_len = 32 + length * 4;
                    if offset + event_len > razer_caps_bytes.len() {
                        break;
                    }
                    let kind = u16::from_le_bytes([
                        razer_caps_bytes[offset + 8],
                        razer_caps_bytes[offset + 9],
                    ]);
                    let device = u16::from_le_bytes([
                        razer_caps_bytes[offset + 10],
                        razer_caps_bytes[offset + 11],
                    ]);
                    let detail = u32::from_le_bytes(
                        razer_caps_bytes[offset + 16..offset + 20]
                            .try_into()
                            .unwrap(),
                    );
                    let effective_mods = u32::from_le_bytes(
                        razer_caps_bytes[offset + 72..offset + 76]
                            .try_into()
                            .unwrap(),
                    ) as u16;
                    if kind == 2 && device == razer_id && detail == u32::from(A_KEY) {
                        states.push(effective_mods & LOCK_MASK);
                    }
                    offset += event_len;
                } else {
                    offset += 32;
                }
            }
            states
        };
        assert!(
            razer_caps_events
                .iter()
                .any(|(kind, device, _, detail, _)| {
                    *kind == 2 && *device == razer_id && *detail == u32::from(A_KEY)
                }),
            "floating Razer key events continue to target its own slave grab",
        );
        assert_eq!(
            caps_lock_states,
            vec![0, LOCK_MASK],
            "Razer's own XI2 events report its independent Caps transitions",
        );
        assert!(
            kbd_map_drain(&mut xi_master_peer).is_empty(),
            "floating Razer key events have no master XI2 delivery",
        );
        assert!(
            kbd_map_drain(&mut core_peer).is_empty(),
            "floating Razer key events have no core delivery",
        );

        // The independently attached HyperX keyboard still delivers plain,
        // unshifted input to both the master XI2 and core views.
        send_key(&mut backend, &mut state, HYPERX, A_KEY, true);
        send_key(&mut backend, &mut state, HYPERX, A_KEY, false);
        let xi_master_bytes = kbd_map_drain(&mut xi_master_peer);
        let xi_master_events = xi2_events(&xi_master_bytes);
        assert!(
            xi_master_events.iter().any(|(kind, device, _, detail, _)| {
                *kind == 2
                    && *device == yserver_core::xinput::DEVICEID_MASTER_KEYBOARD
                    && *detail == u32::from(A_KEY)
            }),
            "attached HyperX input reaches the master XI2 selector: {xi_master_events:?}",
        );
        let master_a = xi_master_events.iter().any(|(kind, device, _, detail, _)| {
            *kind == 2
                && *device == yserver_core::xinput::DEVICEID_MASTER_KEYBOARD
                && *detail == u32::from(A_KEY)
        });
        assert!(master_a, "master XI2 includes HyperX's A key");
        let master_xi2_a_state = {
            let mut offset = 0usize;
            let mut key_state = None;
            while offset + 32 <= xi_master_bytes.len() {
                if xi_master_bytes[offset] == 35 {
                    let length = u32::from_le_bytes(
                        xi_master_bytes[offset + 4..offset + 8].try_into().unwrap(),
                    ) as usize;
                    let event_len = 32 + length * 4;
                    if offset + event_len > xi_master_bytes.len() {
                        break;
                    }
                    let kind = u16::from_le_bytes([
                        xi_master_bytes[offset + 8],
                        xi_master_bytes[offset + 9],
                    ]);
                    let device = u16::from_le_bytes([
                        xi_master_bytes[offset + 10],
                        xi_master_bytes[offset + 11],
                    ]);
                    let detail = u32::from_le_bytes(
                        xi_master_bytes[offset + 16..offset + 20]
                            .try_into()
                            .unwrap(),
                    );
                    if kind == 2
                        && device == yserver_core::xinput::DEVICEID_MASTER_KEYBOARD
                        && detail == u32::from(A_KEY)
                    {
                        key_state = Some(u32::from_le_bytes(
                            xi_master_bytes[offset + 72..offset + 76]
                                .try_into()
                                .unwrap(),
                        ) as u16);
                    }
                    offset += event_len;
                } else {
                    offset += 32;
                }
            }
            key_state
        };
        assert_eq!(
            master_xi2_a_state.map(|mask| mask & (SHIFT_MASK | LOCK_MASK)),
            Some(master_mods_before & (SHIFT_MASK | LOCK_MASK)),
            "master XI2 A event from HyperX is unshifted and keeps the master Caps lock",
        );
        assert_eq!(
            backend.serialize_modifiers() & (SHIFT_MASK | LOCK_MASK),
            master_mods_before & (SHIFT_MASK | LOCK_MASK),
            "floating Razer modifiers must not change the master modifier state",
        );
        let core_events = kbd_map_drain(&mut core_peer);
        assert!(
            core_events
                .chunks_exact(32)
                .any(|event| event[0] == 2 && event[1] == A_KEY),
            "attached HyperX input reaches the core key selector",
        );
        let core_a_state = core_events
            .chunks_exact(32)
            .find(|event| event[0] == 2 && event[1] == A_KEY)
            .map(|event| u16::from_le_bytes([event[28], event[29]]));
        assert_eq!(
            core_a_state.map(|mask| mask & (SHIFT_MASK | LOCK_MASK)),
            Some(master_mods_before & (SHIFT_MASK | LOCK_MASK)),
            "core A event from HyperX is unshifted and keeps the master Caps lock",
        );

        // Explicit grab reattachment follows Xorg's ReattachToOldMaster →
        // AttachDevice path: it does not call ReleaseButtonsAndKeys. A key
        // still physically held at ungrab is not synthesized as a release.
        send_key(&mut backend, &mut state, RAZER, SHIFT_L, true);
        let _ = kbd_map_drain(&mut grab_peer);
        // XIUngrabDevice restores Razer's original master; its floating
        // XKB state is retired and does not become master state.
        let mut ungrab_body = Vec::with_capacity(8);
        ungrab_body.extend_from_slice(&0u32.to_le_bytes());
        ungrab_body.extend_from_slice(&razer_id.to_le_bytes());
        ungrab_body.extend_from_slice(&[0u8; 2]);
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            ClientId(GRAB_CLIENT),
            SequenceNumber(2),
            request(52, 3),
            &ungrab_body,
            None,
        )
        .expect("XIUngrabDevice reattaches Razer");
        let _ = kbd_map_drain(&mut grab_peer);
        assert_eq!(
            state.xi_devices.device(razer_id).unwrap().attached_master,
            Some(yserver_core::xinput::DEVICEID_MASTER_KEYBOARD),
        );
        assert!(
            !backend.floating_keyboard_states.contains_key(&razer_id),
            "reattachment retires Razer's floating XKB state",
        );
        assert!(!state.xi2_keyboard_grabs.contains_key(&razer_id));
        assert!(!state.xi2_detached_masters.contains_key(&razer_id));
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        assert_eq!(backend.current_led_bits(), master_leds_before);
        send_key(&mut backend, &mut state, RAZER, SHIFT_L, false);
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        assert!(
            kbd_map_drain(&mut core_peer).is_empty(),
            "Xorg's explicit-grab reattachment does not synthesize a core key release",
        );
        assert!(
            kbd_map_drain(&mut xi_master_peer).is_empty(),
            "Xorg's explicit-grab reattachment does not synthesize a master XI2 release",
        );
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|&byte| byte == 0));
        assert!(state.sync_pending.is_empty());
        assert!(
            !state
                .xi1_frozen
                .get(&razer_id)
                .is_some_and(yserver_core::server::Xi1Freeze::frozen)
        );

        // Float it again and remove it while a local key is held. The state
        // is retired with the source and the unrelated HyperX facet survives.
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            ClientId(GRAB_CLIENT),
            SequenceNumber(3),
            request(51, 7),
            &xi_grab(razer_id),
            None,
        )
        .expect("second XIGrabDevice on Razer");
        let _ = kbd_map_drain(&mut grab_peer);
        assert_eq!(
            KmsBackend::serialize_xkb_modifiers(
                &backend.floating_keyboard_states[&razer_id].xkb_state.0,
                backend.floating_keyboard_states[&razer_id].locked_group,
                backend.keymap_group_count(),
            ) & LOCK_MASK,
            master_mods_before & LOCK_MASK,
            "a new floating interval starts from the master's locked Caps state",
        );
        send_key(&mut backend, &mut state, RAZER, CAPS_LOCK, true);
        send_key(&mut backend, &mut state, RAZER, CAPS_LOCK, false);
        send_key(&mut backend, &mut state, RAZER, SHIFT_L, true);
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        backend.on_host_input(
            &mut state,
            HostInputEvent::DeviceRemoved { source_id: RAZER },
        );
        assert!(state.xi_devices.source(RAZER).is_none());
        assert!(state.xi_devices.device(razer_id).is_none());
        assert!(state.xi_devices.source(HYPERX).is_some());
        assert_eq!(
            state.xi_devices.device(hyperx_id).unwrap().attached_master,
            Some(yserver_core::xinput::DEVICEID_MASTER_KEYBOARD),
        );
        assert!(!state.xi2_keyboard_grabs.contains_key(&razer_id));
        assert!(!state.xi2_detached_masters.contains_key(&razer_id));
        assert!(!state.xi1_frozen.contains_key(&razer_id));
        assert!(backend.core.down_keys.is_empty());
        assert!(state.keys_down.iter().all(|&byte| byte == 0));
        assert!(state.sync_pending.is_empty());
        assert!(state.key_repeats.is_empty());
        assert!(backend.floating_keyboard_states.is_empty());
        assert_eq!(backend.serialize_modifiers(), master_mods_before);
        assert_eq!(backend.current_led_bits(), master_leds_before);
        assert!(backend.floating_keyboard_states.is_empty());
    }

    #[test]
    fn kms_pointer_authority_integrates_physical_relative_motion_in_kms() {
        use yserver_core::{
            backend::Backend,
            core_loop::{DeviceInfo, HostInputEvent, message::LibinputConfigSnapshot},
            resources::{ROOT_VISUAL, ROOT_WINDOW},
            server::ServerState,
            xinput::{InputCapabilities, InputSourceId, XiFacetKind},
        };
        use yserver_protocol::x11::{ClientId, CreateWindowRequest, ResourceId};

        const CLIENT: u32 = 7;
        const RAZER: InputSourceId = InputSourceId(0xA11);
        const HYPERX: InputSourceId = InputSourceId(0xA12);

        let mut backend = KmsBackend::for_tests();
        let mut state = ServerState::new();
        let mut grab_peer = kbd_map_client_id(&mut state, CLIENT);
        for (source_id, name) in [(RAZER, "Razer"), (HYPERX, "HyperX")] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::DeviceAdded(DeviceInfo {
                    source_id,
                    enabled: true,
                    resume_key: None,
                    capabilities: InputCapabilities {
                        keyboard: source_id == RAZER,
                        pointer: true,
                        touch: false,
                    },
                    name: name.to_owned(),
                    device_node: format!("/dev/input/{name}"),
                    sysname: name.to_owned(),
                    vendor_id: 0,
                    product_id: 0,
                    is_touchpad: false,
                    config: LibinputConfigSnapshot::default(),
                }),
            );
        }
        let razer_id = state
            .xi_devices
            .facet(RAZER, XiFacetKind::PointerTouch)
            .expect("Razer pointer facet");
        let razer_keyboard_id = state
            .xi_devices
            .facet(RAZER, XiFacetKind::Keyboard)
            .expect("Razer keyboard facet");
        state
            .clients
            .get_mut(&CLIENT)
            .unwrap()
            .xi2_masks
            .insert((ROOT_WINDOW, razer_keyboard_id), (1 << 13) | (1 << 14));
        state.xi2_client_versions.insert(ClientId(CLIENT), (2, 2));
        assert!(
            state
                .xi_devices
                .facet(HYPERX, XiFacetKind::PointerTouch)
                .is_some()
        );

        // Establish the master cursor through the regular warp path.
        Backend::warp_pointer_root(&mut backend, &mut state, 100, 300);
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (100.0, 300.0)
        );

        // An explicit slave grab floats Razer while HyperX remains attached.
        let mut grab_body = Vec::with_capacity(24);
        grab_body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        grab_body.extend_from_slice(&0u32.to_le_bytes());
        grab_body.extend_from_slice(&0u32.to_le_bytes());
        grab_body.extend_from_slice(&razer_id.to_le_bytes());
        grab_body.extend_from_slice(&[1, 1, 0, 0]);
        grab_body.extend_from_slice(&0u16.to_le_bytes());
        grab_body.extend_from_slice(&[0u8; 2]);
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            ClientId(CLIENT),
            yserver_protocol::x11::SequenceNumber(1),
            yserver_protocol::x11::RequestHeader {
                opcode: 137,
                data: 51,
                length_units: 7,
            },
            &grab_body,
            None,
        )
        .expect("XIGrabDevice on Razer pointer");
        assert_eq!(
            state.xi_devices.device(razer_id).unwrap().attached_master,
            None
        );

        let physical_motion =
            |source_id, x, y, dx, dy, motion_delta, relative| HostInputEvent::PointerMotion {
                origin: yserver_core::core_loop::InputOrigin::Physical(source_id),
                x,
                y,
                time: 1,
                relative,
                dx,
                dy,
                motion_delta,
            };

        // The input thread's x=650 is stale for the master and differs from
        // the floating slave's authoritative 100 + 500 position.
        backend.on_host_input(
            &mut state,
            physical_motion(RAZER, 650, 300, 500, 0, Some([500.0, 0.0]), true),
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (100.0, 300.0)
        );
        let floating_position = state.floating_pointer_positions[&razer_id];
        assert_eq!(floating_position.0, 600.0);
        assert_eq!(floating_position.1, 300.0);
        assert_eq!(state.pointer_root, (100, 300));
        for _ in 0..3 {
            backend.on_host_input(
                &mut state,
                physical_motion(RAZER, 650, 300, 0, 0, Some([0.4, 0.0]), true),
            );
        }
        let floating_position = state.floating_pointer_positions[&razer_id];
        assert!((floating_position.0 - 601.2).abs() < 0.001);
        assert_eq!(state.pointer_root, (100, 300));

        // HyperX is still attached: its +1 delta advances the master by
        // exactly one pixel, regardless of the stale input-thread x value.
        backend.on_host_input(
            &mut state,
            physical_motion(HYPERX, 650, 300, 1, 0, Some([1.0, 0.0]), true),
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (101.0, 300.0)
        );
        assert_eq!(state.pointer_root, (101, 300));

        // Fractional motion is retained across separate events; it is not
        // rounded to zero per event or treated as three integer pixels.
        backend.on_host_input(
            &mut state,
            physical_motion(HYPERX, 650, 300, 0, 0, Some([1.2, 0.0]), true),
        );
        assert!((backend.core.cursor_x - 102.2).abs() < 0.001);

        // Warps reset the KMS position directly. Relative motion starts at
        // that warped point even though the host absolute coordinate lags.
        Backend::warp_pointer_root(&mut backend, &mut state, 250, 80);
        backend.on_host_input(
            &mut state,
            physical_motion(HYPERX, 102, 300, 2, 0, Some([2.0, 0.0]), true),
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (252.0, 80.0)
        );

        // Absolute tablet/touch-style input remains authoritative. A later
        // relative event continues from that point, not the input thread's
        // last relative accumulator.
        backend.on_host_input(
            &mut state,
            physical_motion(HYPERX, 305, 100, 205, 20, None, false),
        );
        backend.on_host_input(
            &mut state,
            physical_motion(HYPERX, 252, 80, 5, 0, Some([5.0, 0.0]), true),
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (310.0, 100.0)
        );

        // Motion confinement clamps the KMS-integrated result. The stale
        // host coordinate remains inside the window, while the relative
        // delta attempts to move beyond its right and bottom edges.
        const CONFINED: ResourceId = ResourceId(0x0050_0001);
        const CONFINED_HOST: u32 = 0x8000_0001;
        state.resources.create_window(
            ClientId(CLIENT),
            CreateWindowRequest {
                depth: 24,
                window: CONFINED,
                parent: ROOT_WINDOW,
                x: 300,
                y: 90,
                width: 10,
                height: 20,
                border_width: 0,
                class: 1,
                visual: ROOT_VISUAL,
                ..Default::default()
            },
        );
        state.resources.window_mut(CONFINED).unwrap().host_xid =
            yserver_core::backend::WindowHandle::from_raw(CONFINED_HOST);
        assert!(state.resources.map_window(CONFINED).mapping_changed);
        backend.windows.insert(
            CONFINED_HOST,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 300,
                y: 90,
                width: 10,
                height: 20,
                depth: 24,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        backend.core.xid_map.insert(CONFINED_HOST, CONFINED);
        backend.core.top_level_order.push(CONFINED_HOST);
        state.pointer_confine_to = CONFINED;
        let history_len = state.pointer_motion_history.len();
        backend.on_host_input(
            &mut state,
            physical_motion(HYPERX, 310, 100, 100, 100, Some([100.0, 100.0]), true),
        );
        assert_eq!(
            (backend.core.cursor_x, backend.core.cursor_y),
            (309.0, 109.0)
        );
        assert_eq!(state.pointer_root, (309, 109));
        assert_eq!(
            state
                .pointer_motion_history
                .iter()
                .skip(history_len)
                .map(|motion| (motion.root_x, motion.root_y))
                .collect::<Vec<_>>(),
            vec![(309, 109)],
            "KMS confines the integrated cursor before emitting motion"
        );

        // Float and synchronously grab Razer's keyboard facet, then send its
        // press/release through KMS. Raw slave records arrive immediately;
        // the device events remain queued with their generating source.
        let mut key_grab_body = Vec::with_capacity(24);
        key_grab_body.extend_from_slice(&ROOT_WINDOW.0.to_le_bytes());
        key_grab_body.extend_from_slice(&0u32.to_le_bytes());
        key_grab_body.extend_from_slice(&0u32.to_le_bytes());
        key_grab_body.extend_from_slice(&razer_keyboard_id.to_le_bytes());
        key_grab_body.extend_from_slice(&[0, 1, 0, 0]); // sync this, async paired
        key_grab_body.extend_from_slice(&0u16.to_le_bytes());
        key_grab_body.extend_from_slice(&[0u8; 2]);
        yserver_core::core_loop::process_request::process_request(
            &mut state,
            &mut backend,
            ClientId(CLIENT),
            yserver_protocol::x11::SequenceNumber(2),
            yserver_protocol::x11::RequestHeader {
                opcode: 137,
                data: 51,
                length_units: 7,
            },
            &key_grab_body,
            None,
        )
        .expect("XIGrabDevice on Razer keyboard");
        assert!(
            state
                .xi1_frozen
                .get(&razer_keyboard_id)
                .is_some_and(yserver_core::server::Xi1Freeze::frozen)
        );
        for (pressed, time) in [(true, 3), (false, 4)] {
            backend.on_host_input(
                &mut state,
                HostInputEvent::Key(yserver_core::host_x11::HostKeyEvent {
                    origin: yserver_core::core_loop::InputOrigin::Physical(RAZER),
                    pressed,
                    keycode: 38,
                    time,
                    root_x: -1,
                    root_y: -1,
                    event_x: -1,
                    event_y: -1,
                    state: 0,
                }),
            );
        }
        assert!(backend.core.down_keys.is_empty());
        let (deferred_raw, deferred_keys): (Vec<_>, Vec<_>) = state.sync_pending.iter().fold(
            (Vec::new(), Vec::new()),
            |(mut raw, mut keys), pending| {
                match &pending.event {
                    yserver_core::server::QueuedInputEvent::RawKey(event) => raw.push(*event),
                    yserver_core::server::QueuedInputEvent::HostKey(event) => keys.push(*event),
                    yserver_core::server::QueuedInputEvent::HostKeyTransition(event, _) => {
                        keys.push(*event);
                    }
                    yserver_core::server::QueuedInputEvent::Xi1Routed(_) => {}
                    other => panic!("unexpected deferred input, got {other:?}"),
                }
                (raw, keys)
            },
        );
        assert_eq!(state.sync_pending.len(), 2);
        assert_eq!(
            state
                .sync_pending
                .iter()
                .filter(|pending| matches!(
                    pending.event,
                    yserver_core::server::QueuedInputEvent::HostKey(_)
                        | yserver_core::server::QueuedInputEvent::HostKeyTransition(_, _)
                ))
                .count(),
            2
        );
        assert!(deferred_raw.is_empty());
        assert_eq!(deferred_keys.len(), 2);
        assert_eq!(
            deferred_keys
                .iter()
                .map(|event| (event.origin, event.keycode, event.pressed))
                .collect::<Vec<_>>(),
            vec![
                (
                    yserver_core::core_loop::InputOrigin::Physical(RAZER),
                    38,
                    true
                ),
                (
                    yserver_core::core_loop::InputOrigin::Physical(RAZER),
                    38,
                    false
                ),
            ]
        );
        assert_eq!(
            xi2_events(&kbd_map_drain(&mut grab_peer))
                .into_iter()
                .filter(|event| matches!(event.0, 13 | 14))
                .map(|event| (event.0, event.1, event.2, event.3))
                .collect::<Vec<_>>(),
            vec![
                (13, razer_keyboard_id, razer_keyboard_id, 38),
                (14, razer_keyboard_id, razer_keyboard_id, 38),
            ],
            "a floating keyboard emits only its source slave raw form"
        );
        assert_eq!(state.xi_devices.source(RAZER).unwrap().name, "Razer");
        assert_eq!(state.xi_devices.source(HYPERX).unwrap().name, "HyperX");
        assert_eq!(
            state.xi_devices.device(razer_id).unwrap().attached_master,
            None
        );
        assert_eq!(
            state
                .xi_devices
                .facet(HYPERX, XiFacetKind::PointerTouch)
                .and_then(|id| state.xi_devices.device(id))
                .unwrap()
                .attached_master,
            Some(yserver_core::xinput::DEVICEID_MASTER_POINTER)
        );
        assert_eq!(
            state
                .xi_devices
                .devices()
                .iter()
                .map(|device| device.id)
                .collect::<Vec<_>>(),
            vec![
                2,
                3,
                4,
                5,
                razer_keyboard_id,
                razer_id,
                state
                    .xi_devices
                    .facet(HYPERX, XiFacetKind::PointerTouch)
                    .unwrap()
            ]
        );
        assert_eq!(
            state.xi2_pointer_grabs.keys().copied().collect::<Vec<_>>(),
            vec![razer_id]
        );
        assert_eq!(
            state.xi2_keyboard_grabs.keys().copied().collect::<Vec<_>>(),
            vec![razer_keyboard_id]
        );
        assert_eq!(
            state
                .xi_devices
                .device(razer_keyboard_id)
                .unwrap()
                .attached_master,
            None
        );
        assert_eq!(
            state
                .floating_pointer_positions
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            vec![razer_id]
        );
        let floating_position = state.floating_pointer_positions[&razer_id];
        assert!((floating_position.0 - 601.2).abs() < 0.001);
        assert_eq!(floating_position.1, 300.0);
        assert!(backend.core.pending_pointer_events.is_empty());
        assert_eq!(state.sync_pending.len(), 2);
    }

    /// Stage 3f.6 — `create_subwindow` records the parent xid + the
    /// background-pixel hint so subsequent `build_scene` traversals
    /// can reach the new window and an initial bg_pixel fill can
    /// run. Engine fill itself returns `NoVk` on the test fixture;
    /// the load-bearing observable is the geometry record.
    #[test]
    fn create_subwindow_records_parent_and_bg_pixel() {
        use yserver_core::{backend::WindowHandle, host_x11::HostSubwindowVisual};
        let mut b = KmsBackend::for_tests();
        let parent = WindowHandle::from_raw(0x1234_5678).unwrap();
        let child = b
            .create_subwindow(
                None,
                parent,
                10,
                20,
                100,
                50,
                0,
                HostSubwindowVisual::CopyFromParent,
                Some(0xFF11_2233),
                None,
            )
            .expect("create_subwindow");
        let geom = b.windows[&child.as_raw()];
        assert_eq!(geom.parent, Some(0x1234_5678));
        assert_eq!(geom.bg_pixel, Some(0xFF11_2233));
        assert_eq!(geom.x, 10);
        assert_eq!(geom.y, 20);
        assert_eq!(geom.width, 100);
        assert_eq!(geom.height, 50);
        assert_eq!(
            geom.depth, 24,
            "root/untracked CopyFromParent inherits root depth"
        );
        assert!(!geom.mapped, "mapped is set later via map_subwindow");
    }

    /// #133 step 2 (P3): `create_subwindow` records the `border_width`
    /// it has always been handed (and discarded as `_border_width`),
    /// and `configure_subwindow` updates it. Recording only — storage
    /// stays content-sized until step 3, so this asserts the mirror,
    /// not a layout.
    #[test]
    fn create_and_configure_subwindow_record_border_width() {
        use yserver_core::{
            backend::WindowHandle,
            host_x11::{HostSubwindowConfig, HostSubwindowVisual},
        };
        let mut b = KmsBackend::for_tests();
        let parent = WindowHandle::from_raw(0x1234_5678).unwrap();
        let child = b
            .create_subwindow(
                None,
                parent,
                10,
                20,
                100,
                50,
                16,
                HostSubwindowVisual::CopyFromParent,
                None,
                None,
            )
            .expect("create_subwindow");
        let xid = child.as_raw();
        assert_eq!(b.windows[&xid].border_width, 16, "create records bw");

        // A configure that carries only the border width updates it and
        // touches nothing else.
        b.configure_subwindow(
            None,
            xid,
            HostSubwindowConfig {
                border_width: Some(3),
                ..Default::default()
            },
        )
        .expect("configure_subwindow");
        let geom = b.windows[&xid];
        assert_eq!(geom.border_width, 3);
        assert_eq!(geom.width, 100, "border-only configure keeps the size");
        assert_eq!(geom.height, 50);

        // A configure with no border-width field leaves the recorded
        // value in place (X11 ConfigureWindow is a sparse value list).
        b.configure_subwindow(
            None,
            xid,
            HostSubwindowConfig {
                width: Some(120),
                ..Default::default()
            },
        )
        .expect("configure_subwindow");
        let geom = b.windows[&xid];
        assert_eq!(geom.border_width, 3, "absent field is not a reset to 0");
        assert_eq!(geom.width, 120);
    }

    #[test]
    fn copy_from_parent_child_inherits_argb_parent_depth() {
        use yserver_core::{backend::WindowHandle, host_x11::HostSubwindowVisual};

        let mut b = KmsBackend::for_tests();
        b.windows.insert(
            0x2000,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 80,
                height: 40,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        let child = b
            .create_subwindow(
                None,
                WindowHandle::from_raw(0x2000).unwrap(),
                1,
                2,
                30,
                20,
                0,
                HostSubwindowVisual::CopyFromParent,
                None,
                None,
            )
            .expect("create_subwindow");
        assert_eq!(b.windows[&child.as_raw()].depth, 32);
    }

    #[test]
    fn depth_only_visual_preserves_argb_top_level_depth() {
        use yserver_core::{backend::WindowHandle, host_x11::HostSubwindowVisual};

        let mut b = KmsBackend::for_tests();
        let child = b
            .create_subwindow(
                None,
                WindowHandle::from_raw(b.window_id()).unwrap(),
                0,
                0,
                2944,
                1840,
                0,
                HostSubwindowVisual::DepthOnly { depth: 32 },
                Some(0),
                None,
            )
            .expect("create_subwindow");
        assert_eq!(b.windows[&child.as_raw()].depth, 32);
    }

    /// Stage 3f.11: reparenting a top-level window INTO another
    /// window removes it from `core.top_level_order` so
    /// `build_scene` only emits it once (via the recurse from the
    /// new parent). Reproducer for the MATE clock-applet duplicate-
    /// render: clock was first registered as a top-level under
    /// root, then reparented INTO mate-panel's container. Pre-fix,
    /// build_scene emitted it twice — once at child-relative coords
    /// (treated as absolute) and once at real screen position.
    #[test]
    fn reparent_into_container_removes_from_top_level_order() {
        let mut b = KmsBackend::for_tests();
        // Two stub windows: the parent container, and the would-be
        // child (initially registered as a top-level).
        b.windows.insert(
            0xC0FFEE,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 200,
                height: 100,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.windows.insert(
            0xCAFED00D,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 50,
                height: 20,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 1,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        // Reparent 0xCAFED00D under 0xC0FFEE at (30, 10).
        b.reparent_subwindow(None, 0xCAFED00D, 0xC0FFEE, 30, 10)
            .expect("reparent");

        // Step 2 (DRIFT 2): the double-emit fix is now the windows.parent
        // update — build_scene recurses by parent, so a child with a tracked
        // parent is reached only via the recurse, never the top-level walk.
        // (top_level_order membership itself is projected from core children
        // by the reparent core handler's sync_top_level_order, not here.)
        let geom = b.windows[&0xCAFED00D];
        assert_eq!(geom.parent, Some(0xC0FFEE));
        assert_eq!(geom.x, 30);
        assert_eq!(geom.y, 10);
    }

    /// Phase 4.1 (COW structural redesign): protocol-validation
    /// guarantees the host_parent exists in `windows` by the time
    /// `reparent_subwindow` is invoked. A missing entry means projection
    /// drift between resources and backend — a fatal internal-
    /// consistency failure, not a recoverable "treat as top-level".
    /// The old silent fallback masked the cinnamon COW bug for weeks;
    /// surfacing the drift via panic is the spec'd behaviour.
    #[test]
    #[should_panic(expected = "reparent_subwindow")]
    fn reparent_subwindow_panics_when_host_parent_missing() {
        let mut b = KmsBackend::for_tests();
        // Pre-seed the child so reparent_subwindow has something to
        // operate on; the panic must come from the missing host_parent
        // lookup, not from a missing child.
        let child_xid: u32 = 0x0040_0050;
        b.windows.insert(
            child_xid,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                depth: 24,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        // Reparent to a host_parent that doesn't exist in windows.
        // 0 is the legitimate "reparent to root" convention; 0xDEADBEEF
        // is genuinely absent and must trip the drift panic.
        let _ = b.reparent_subwindow(None, child_xid, 0xDEAD_BEEF, 0, 0);
    }

    /// Task 4.1 regression: the production reparent-to-root path
    /// (`process_request.rs` `handle_reparent_window`) computes
    /// `host_parent` as `backend.window_id()` (== `core.window_id` == 1)
    /// for `ReparentWindow(child -> ROOT_WINDOW)`, NOT 0. Root is never
    /// tracked in `windows`, so the missing-parent panic guard must
    /// treat `core.window_id` as a root sentinel (-> top-level) instead
    /// of crashing. Without the fix this panics on every WM window-
    /// withdraw / frame-teardown.
    #[test]
    fn reparent_subwindow_to_root_via_window_id_does_not_panic() {
        let mut b = KmsBackend::for_tests();
        let root_xid = b.window_id();
        assert_eq!(root_xid, 1, "core.window_id sentinel changed");
        let child_xid: u32 = 0x0040_0050;
        b.windows.insert(
            child_xid,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 5,
                y: 7,
                width: 100,
                height: 100,
                depth: 24,
                mapped: true,
                viewable: true,
                // Originally a sub-window under some frame; the WM now
                // reparents it back to root (withdraw / frame teardown).
                parent: Some(0x0040_0060),
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        // host_parent == root's real host xid (core.window_id), exactly
        // what the production call site passes for reparent-to-ROOT.
        let res = b.reparent_subwindow(None, child_xid, root_xid, 0, 0);
        assert!(res.is_ok(), "reparent-to-root must succeed, got {res:?}");
        // Child is now a top-level under root (parent cleared to None). Its
        // top_level_order membership is projected from core by the reparent
        // core handler's sync_top_level_order, not by this backend method.
        assert_eq!(b.windows.get(&child_xid).unwrap().parent, None);
    }

    // (Removed `restack_below_no_sibling_moves_to_bottom` /
    // `restack_above_no_sibling_moves_to_top`: `restack_top_level` is
    // deleted in Step 2 — top-level order is a projection of core children
    // via `sync_top_level_order`. The Below/Above-to-bottom/top semantics
    // are now exercised by core's restack tests in resources.rs plus the
    // `drift2_*` projection gates.)

    /// Stage 3f.11 follow-up: subwindow restack updates sibling order
    /// within a shared parent instead of relying on HashMap iteration.
    #[test]
    fn restack_subwindow_updates_sibling_order() {
        let mut b = KmsBackend::for_tests();
        b.windows.insert(
            0xCAFE,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 10,
                height: 10,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: Some(0xBEEF),
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.windows.insert(
            0xD00D,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 10,
                height: 10,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: Some(0xBEEF),
                stack_rank: 1,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.restack_subwindow(0xD00D, 1, Some(0xCAFE));
        assert!(b.windows[&0xD00D].stack_rank < b.windows[&0xCAFE].stack_rank);
    }

    /// Stage 3f.11 / Step 2: reparenting back to root clears the window's
    /// `windows.parent` to `None` so it resumes top-level rendering (its
    /// `top_level_order` membership is projected from core children by the
    /// reparent core handler). The Backend trait's reparent call carries
    /// the new parent xid; `host_parent==0` or an untracked xid (root is
    /// `core.window_id`, not in `windows`) maps to `parent=None`.
    #[test]
    fn reparent_to_root_clears_parent() {
        let mut b = KmsBackend::for_tests();
        b.windows.insert(
            0xC0FFEE,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 0,
                y: 0,
                width: 200,
                height: 100,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: None,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.windows.insert(
            0xCAFED00D,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x: 30,
                y: 10,
                width: 50,
                height: 20,
                depth: 32,
                mapped: true,
                viewable: true,
                parent: Some(0xC0FFEE),
                stack_rank: 1,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        // Start: child is a sub-window of 0xC0FFEE.
        assert_eq!(b.windows[&0xCAFED00D].parent, Some(0xC0FFEE));

        // Reparent to root (host_parent=0 maps to parent=None).
        b.reparent_subwindow(None, 0xCAFED00D, 0, 100, 200)
            .expect("reparent");

        // Now a top-level (parent cleared); position updated.
        let geom = b.windows[&0xCAFED00D];
        assert_eq!(geom.parent, None);
        assert_eq!(geom.x, 100);
        assert_eq!(geom.y, 200);
    }

    // ───── Stage 4a — resolve_paint_target ─────────────────────────

    /// Seed a window in `windows` and a matching no-Vk store
    /// entry, returning the new DrawableId. Used by the 4a
    /// resolver tests so the ancestor walk has something to chew
    /// on without touching Vk.
    /// The target of a window painting into an ancestor's backing:
    /// clipped to `(x, y, w, h)`, the window inside its ancestors, with no
    /// border term.
    fn in_ancestor_backing(
        id: crate::kms::render::store::DrawableId,
        offset: (i32, i32),
        (x, y, width, height): (i32, i32, u32, u32),
        depth: u8,
    ) -> PaintTarget {
        PaintTarget::new(id, offset, None, depth).within_window_bounds(Some(ash::vk::Rect2D {
            offset: ash::vk::Offset2D { x, y },
            extent: ash::vk::Extent2D { width, height },
        }))
    }

    pub(super) fn seed_window(
        b: &mut KmsBackend,
        xid: u32,
        parent: Option<u32>,
        x: i16,
        y: i16,
    ) -> crate::kms::render::store::DrawableId {
        use crate::kms::render::store::{DrawableKind, Storage};
        b.windows.insert(
            xid,
            super::WindowGeometry {
                border_width: 0,
                border_pixel: None,
                border_pixmap: None,
                x,
                y,
                width: 100,
                height: 100,
                // Normal (non-ARGB) X windows are depth 24; the redirect-routing
                // tests rely on resolve_paint_target reporting this logical depth
                // even when routed into a depth-32 backing (the picom/xterm shape).
                depth: 24,
                mapped: true,
                viewable: true,
                parent,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        b.store
            .allocate(
                xid,
                DrawableKind::Window,
                24,
                true,
                Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: 100,
                        height: 100,
                    },
                    ash::vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("seed_window allocate")
    }

    /// #133 step 3 — `seed_window` with a border and an explicit size,
    /// sized like `allocate_window_storage` would: storage is the
    /// BORDERED extent `(w + 2bw) x (h + 2bw)` (Xorg `compAllocPixmap`,
    /// `composite/compalloc.c:610`).
    fn seed_bordered_window(
        b: &mut KmsBackend,
        xid: u32,
        parent: Option<u32>,
        x: i16,
        y: i16,
        w: u16,
        h: u16,
        bw: u16,
    ) -> crate::kms::render::store::DrawableId {
        use crate::kms::render::store::{DrawableKind, Storage};
        b.windows.insert(
            xid,
            super::WindowGeometry {
                border_width: bw,
                border_pixel: None,
                border_pixmap: None,
                x,
                y,
                width: w,
                height: h,
                depth: 24,
                mapped: true,
                viewable: true,
                parent,
                stack_rank: 0,
                bg_pixel: None,
                bg_pixmap: None,
                cursor: None,
            },
        );
        let (sw, sh) = super::bordered_storage_extent(w.max(1), h.max(1), bw);
        let id = b
            .store
            .allocate(
                xid,
                DrawableKind::Window,
                24,
                true,
                Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: sw,
                        height: sh,
                    },
                    ash::vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("seed_bordered_window allocate");
        // Mirror production: the layout a storage was allocated with is
        // recorded on the drawable, never re-derived from the live
        // geometry (`Drawable::content_offset`).
        b.store.set_content_offset(id, i32::from(bw));
        id
    }

    /// #133 step 3 (3.3) — the bordered storage extent, `w + (bw << 1)`
    /// per `compAllocPixmap` (`composite/compalloc.c:610`). Collapses to
    /// exactly `(w, h)` at `bw == 0`: that identity is what keeps every
    /// `bw == 0` desktop on the pre-#133 allocation.
    #[test]
    fn bordered_storage_extent_collapses_at_bw_zero() {
        assert_eq!(super::bordered_storage_extent(100, 50, 0), (100, 50));
        assert_eq!(super::bordered_storage_extent(100, 50, 16), (132, 82));
        assert_eq!(super::bordered_storage_extent(1, 1, 1), (3, 3));
    }

    // ───── #133 step 4 (P5) — the ring fill ─────

    fn vkrect(x: i32, y: i32, w: u32, h: u32) -> ash::vk::Rect2D {
        ash::vk::Rect2D {
            offset: ash::vk::Offset2D { x, y },
            extent: ash::vk::Extent2D {
                width: w,
                height: h,
            },
        }
    }

    /// #133 step 4 (4.1) — the ring is `outer − content`, which is what
    /// Xorg passes to `miPaintWindow(..., PW_BORDER)`
    /// (`RegionSubtract(&exposed, &pWin->borderClip, &pWin->winSize)`,
    /// `dix/window.c:1586`). Four disjoint rects, covering the annulus
    /// exactly once, and NOTHING inside the content.
    #[test]
    fn border_ring_rects_tile_the_annulus_exactly_once() {
        // 100x50 content at (16, 16) inside 132x82 storage: bw = 16.
        let ring = super::border_ring_rects(vkrect(0, 0, 132, 82), vkrect(16, 16, 100, 50));
        assert_eq!(
            ring,
            vec![
                vkrect(0, 0, 132, 16),   // top band, full width
                vkrect(0, 66, 132, 16),  // bottom band, full width
                vkrect(0, 16, 16, 50),   // left bar
                vkrect(116, 16, 16, 50), // right bar
            ]
        );
        // Area check: outer − inner, and no double-covered pixel.
        let area: u32 = ring.iter().map(|r| r.extent.width * r.extent.height).sum();
        assert_eq!(area, 132 * 82 - 100 * 50);
        let mut covered = vec![0u8; (132 * 82) as usize];
        for r in &ring {
            for y in r.offset.y..r.offset.y + r.extent.height as i32 {
                for x in r.offset.x..r.offset.x + r.extent.width as i32 {
                    covered[(y * 132 + x) as usize] += 1;
                }
            }
        }
        for y in 0..82i32 {
            for x in 0..132i32 {
                let inside_content = (16..116).contains(&x) && (16..66).contains(&y);
                assert_eq!(
                    covered[(y * 132 + x) as usize],
                    u8::from(!inside_content),
                    "pixel ({x}, {y}) covered {} times",
                    covered[(y * 132 + x) as usize],
                );
            }
        }
    }

    /// #133 step 4 — `bw == 0` IDENTITY at the geometry level: with the
    /// content equal to the storage there is no ring, so no rect, so no
    /// submit. Every WM in the smoke set is this path.
    #[test]
    fn border_ring_rects_is_empty_at_bw_zero() {
        assert!(super::border_ring_rects(vkrect(0, 0, 100, 50), vkrect(0, 0, 100, 50)).is_empty());
    }

    /// A 1-px border still produces all four sides (the xts `makewin`
    /// default, `xts5/src/lib/makewin2.c:232`), and a ring around a
    /// content rect that is not at the storage origin — the redirected
    /// ancestor's backing case — is placed relative to the content, not
    /// to the storage.
    #[test]
    fn border_ring_rects_offset_content_and_one_pixel_border() {
        assert_eq!(
            super::border_ring_rects(vkrect(0, 0, 3, 3), vkrect(1, 1, 1, 1)),
            vec![
                vkrect(0, 0, 3, 1),
                vkrect(0, 2, 3, 1),
                vkrect(0, 1, 1, 1),
                vkrect(2, 1, 1, 1),
            ]
        );
        // Content (40, 30, 10, 10) with bw = 5 inside a larger backing.
        let ring = super::border_ring_rects(vkrect(35, 25, 20, 20), vkrect(40, 30, 10, 10));
        assert_eq!(
            ring,
            vec![
                vkrect(35, 25, 20, 5),
                vkrect(35, 40, 20, 5),
                vkrect(35, 30, 5, 10),
                vkrect(50, 30, 5, 10),
            ]
        );
    }

    /// #133 step 4 — the ring thickness comes from the ALLOCATION, not
    /// from the live `border_width` (step 3's invariant,
    /// `storage_content_offset`). A `border_width` change that has not
    /// reallocated must not move the ring, because it has not moved the
    /// content either — re-basing here would paint border colour over
    /// client pixels.
    #[test]
    fn border_ring_thickness_follows_the_allocation_not_the_geometry() {
        let mut b = KmsBackend::for_tests();
        let id = seed_bordered_window(&mut b, 0x4901, None, 10, 10, 100, 50, 16);
        let target = b.resolve_paint_target(0x4901).expect("resolve");
        assert_eq!(b.border_ring_thickness(0x4901, &target), 16);
        // XSetWindowBorderWidth(w, 3) with no reallocation: the
        // allocation still says 16, and so must the ring.
        b.windows.get_mut(&0x4901).expect("geom").border_width = 3;
        let target = b.resolve_paint_target(0x4901).expect("resolve");
        assert_eq!(b.border_ring_thickness(0x4901, &target), 16);
        // …and once the allocation is re-recorded, the ring follows it.
        b.store.set_content_offset(id, 3);
        let target = b.resolve_paint_target(0x4901).expect("resolve");
        assert_eq!(b.border_ring_thickness(0x4901, &target), 3);
    }

    /// #133 step 4 (4.3) — Xorg's depth-32 alpha rule
    /// (`mi/miexpose.c:491-511`): a depth-32 window whose parent chain
    /// reaches a depth-24 ancestor gets `fill.pixel |= 0xff000000`,
    /// "Make sure alpha will sample as 1.0 for opaque windows". A
    /// depth-32 chain keeps the client's alpha, and a non-32 window is
    /// untouched here (`decode_x11_pixel_for_storage` forces α = 1.0
    /// for it anyway).
    #[test]
    fn border_solid_pixel_applies_the_depth32_alpha_rule() {
        use crate::kms::render::store::{DrawableKind, Storage};
        let mut b = KmsBackend::for_tests();
        let mut seed = |xid: u32, parent: Option<u32>, depth: u8| {
            b.windows.insert(
                xid,
                super::WindowGeometry {
                    border_width: 4,
                    border_pixel: Some(0x0012_3456),
                    border_pixmap: None,
                    x: 0,
                    y: 0,
                    width: 10,
                    height: 10,
                    depth,
                    mapped: true,
                    viewable: true,
                    parent,
                    stack_rank: 0,
                    bg_pixel: None,
                    bg_pixmap: None,
                    cursor: None,
                },
            );
            b.store
                .allocate(
                    xid,
                    DrawableKind::Window,
                    depth,
                    true,
                    Storage::for_tests_null(
                        ash::vk::Extent2D {
                            width: 18,
                            height: 18,
                        },
                        ash::vk::Format::B8G8R8A8_UNORM,
                    ),
                )
                .expect("allocate")
        };
        // depth-24 top-level P24; depth-32 child C32 under it.
        let p24 = seed(0x4910, None, 24);
        let c32 = seed(0x4911, Some(0x4910), 32);
        // depth-32 top-level (parent is the root, which Xorg's
        // `while (orig_pWin && orig_pWin->parent)` never examines).
        let t32 = seed(0x4912, None, 32);

        let geom = |b: &KmsBackend, xid: u32| *b.windows.get(&xid).expect("geom");
        // Depth 24: no rule, the pixel passes through untouched.
        assert_eq!(b.border_solid_pixel(geom(&b, 0x4910), p24), 0x0012_3456);
        // Depth 32 under a depth-24 ancestor: alpha forced opaque.
        assert_eq!(b.border_solid_pixel(geom(&b, 0x4911), c32), 0xff12_3456);
        // Depth 32 all the way to the root: the client's alpha stands.
        assert_eq!(b.border_solid_pixel(geom(&b, 0x4912), t32), 0x0012_3456);
        // A depth-24 window painting into a depth-32 BACKING (a child
        // of a redirected depth-32 frame): Xorg gates on the PIXMAP's
        // depth and starts `effective_depth` from the WINDOW's, so this
        // takes the alpha with no parent walk at all. Getting it wrong
        // here is a transparent ring, because the depth-32 storage
        // reads alpha straight out of the pixel.
        assert_eq!(b.border_solid_pixel(geom(&b, 0x4910), c32), 0xff12_3456);
    }

    /// #133 step 3 (P4) case 1 — LEAF STORAGE. An unredirected window
    /// paints into its own storage: the content offset is its own
    /// `(bw, bw)` and the content clip is `(bw, bw, w, h)`.
    #[test]
    fn resolve_paint_target_leaf_storage_offsets_by_own_border() {
        let mut b = KmsBackend::for_tests();
        seed_bordered_window(&mut b, 0x4001, None, 30, 40, 100, 50, 16);
        let (offset, clip, bordered) = b
            .paint_target_shape_for_tests(0x4001)
            .expect("resolve leaf");
        assert_eq!(offset, (16, 16), "content starts at (bw, bw)");
        assert_eq!(clip, Some((16, 16, 100, 50)), "content clip");
        assert!(bordered);
        // The bw == 0 control: identity, on the pre-#133 arithmetic.
        seed_bordered_window(&mut b, 0x4002, None, 30, 40, 100, 50, 0);
        assert_eq!(
            b.paint_target_shape_for_tests(0x4002),
            Some(((0, 0), None, false)),
        );
    }

    /// #133 step 3 (P4) case 2 — ANCESTOR BACKING. Child C under
    /// redirected ancestor W: the one-level translation is
    /// `W.border_width + C.x + C.border_width` (spec P4), and the clip
    /// is W's content ∩ C's content, both in backing coordinates.
    #[test]
    fn resolve_paint_target_ancestor_backing_adds_both_borders() {
        use crate::kms::render::store::{DrawableKind, Storage};
        let mut b = KmsBackend::for_tests();
        // W: 100x50, bw 8 → backing 116x66, W content at (8, 8).
        seed_bordered_window(&mut b, 0x4010, None, 0, 0, 100, 50, 8);
        // C: 20x10, bw 4, at (10, 20) inside W's content.
        seed_bordered_window(&mut b, 0x4011, Some(0x4010), 10, 20, 20, 10, 4);
        let w_id = b.store.lookup(0x4010).expect("W id");
        let b_id = b
            .store
            .allocate(
                0x4012,
                DrawableKind::Pixmap,
                24,
                true,
                Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: 116,
                        height: 66,
                    },
                    ash::vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("backing allocate");
        b.store.set_redirected_target(w_id, Some(b_id));
        // Production records the backing's layout in
        // `allocate_redirected_backing`; mirror that here.
        b.store.set_content_offset(b_id, 8);

        let (offset, clip, bordered) = b.paint_target_shape_for_tests(0x4011).expect("resolve C");
        // 8 + 10 + 4 = 22 horizontally; 8 + 20 + 4 = 32 vertically.
        assert_eq!(offset, (22, 32), "W.bw + C.x + C.bw");
        assert!(bordered);
        // W's content (8, 8, 100, 50) ∩ C's content (22, 32, 20, 10).
        assert_eq!(clip, Some((22, 32, 20, 10)));

        // W itself, painting into its own backing: content clip derives
        // from W ALONE — no ancestor term — per spec §The redirection
        // exception rule 1 (`SetWinSize`, `dix/window.c:1720`).
        assert_eq!(
            b.paint_target_shape_for_tests(0x4010),
            Some(((8, 8), Some((8, 8, 100, 50)), true)),
        );
    }

    /// #133 step 3 (P4) case 3 — ROOT REDIRECTION. A top-level under a
    /// redirected root: `T.x + T.border_width`, and the root itself
    /// contributes no border term (the root window has no border).
    #[test]
    fn resolve_paint_target_root_redirection_adds_own_border_only() {
        use crate::kms::render::store::{DrawableKind, Storage};
        let mut b = KmsBackend::for_tests();
        // root storage is already seeded by `KmsCore::for_tests()`
        // (`init_root_storage`); it is deliberately NOT in `windows`.
        let root_id = b.store.lookup(b.core.window_id).expect("root id");
        let b_id = b
            .store
            .allocate(
                0x4021,
                DrawableKind::Pixmap,
                24,
                true,
                Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: 800,
                        height: 600,
                    },
                    ash::vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("root backing allocate");
        b.store.set_redirected_target(root_id, Some(b_id));
        // Top-level T at (30, 40), 100x50, bw 6 (parent = None is the
        // production representation for a top-level).
        seed_bordered_window(&mut b, 0x4020, None, 30, 40, 100, 50, 6);

        let (offset, clip, bordered) = b.paint_target_shape_for_tests(0x4020).expect("resolve T");
        assert_eq!(offset, (36, 46), "T.x + T.bw, no root border term");
        assert_eq!(clip, Some((36, 46, 100, 50)));
        assert!(bordered);
    }

    /// #133 step 3 (P4) case 4 — NESTED DESCENDANTS. C under P under
    /// redirected W accumulates `+ child.x` then `+ parent.bw` at every
    /// level: `W.bw + P.x + P.bw + C.x + C.bw`.
    #[test]
    fn resolve_paint_target_nested_descendants_accumulate_every_level() {
        use crate::kms::render::store::{DrawableKind, Storage};
        let mut b = KmsBackend::for_tests();
        seed_bordered_window(&mut b, 0x4030, None, 0, 0, 200, 100, 8); // W, bw 8
        seed_bordered_window(&mut b, 0x4031, Some(0x4030), 10, 10, 100, 60, 4); // P, bw 4
        seed_bordered_window(&mut b, 0x4032, Some(0x4031), 5, 7, 20, 10, 2); // C, bw 2
        let w_id = b.store.lookup(0x4030).expect("W id");
        let b_id = b
            .store
            .allocate(
                0x4033,
                DrawableKind::Pixmap,
                24,
                true,
                Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: 216,
                        height: 116,
                    },
                    ash::vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("backing allocate");
        b.store.set_redirected_target(w_id, Some(b_id));
        b.store.set_content_offset(b_id, 8);

        let (offset, clip, bordered) = b.paint_target_shape_for_tests(0x4032).expect("resolve C");
        // 8 + 10 + 4 + 5 + 2 = 29; 8 + 10 + 4 + 7 + 2 = 31.
        assert_eq!(offset, (29, 31));
        assert!(bordered);
        // Every bordered level contributes: W (8,8,200,100),
        // P (22,22,100,60) and C (29,31,20,10) intersected.
        assert_eq!(clip, Some((29, 31, 20, 10)));

        // The `bw == 0` control on the SAME shape: no border term, so the
        // walk lands on the pre-#133 offset, clipped only to C inside its
        // ancestors (C (15,17,20,10) ∩ P (10,10,100,60) ∩ W).
        let mut b0 = KmsBackend::for_tests();
        seed_bordered_window(&mut b0, 0x4040, None, 0, 0, 200, 100, 0);
        seed_bordered_window(&mut b0, 0x4041, Some(0x4040), 10, 10, 100, 60, 0);
        seed_bordered_window(&mut b0, 0x4042, Some(0x4041), 5, 7, 20, 10, 0);
        let w0 = b0.store.lookup(0x4040).expect("W id");
        let b0_id = b0
            .store
            .allocate(
                0x4043,
                DrawableKind::Pixmap,
                24,
                true,
                Storage::for_tests_null(
                    ash::vk::Extent2D {
                        width: 200,
                        height: 100,
                    },
                    ash::vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("backing allocate");
        b0.store.set_redirected_target(w0, Some(b0_id));
        assert_eq!(
            b0.paint_target_shape_for_tests(0x4042),
            Some(((15, 17), Some((15, 17, 20, 10)), false)),
            "bw == 0 keeps the pre-#133 (x, y) accumulation and no border clip",
        );
    }

    /// #133 step 3 (P4) — a MANUALLY redirected window (its backing not
    /// scene-participating) gets the same treatment as an automatic
    /// one: Xorg keys the clip off `redirectDraw != RedirectDrawNone`
    /// with no manual/automatic distinction (`SetWinSize`,
    /// `dix/window.c:1720`; `SetBorderSize`, `:1747`).
    #[test]
    fn resolve_paint_target_redirect_clip_ignores_the_redirect_mode() {
        use crate::kms::render::store::{DrawableKind, Storage};
        for participating in [true, false] {
            let mut b = KmsBackend::for_tests();
            seed_bordered_window(&mut b, 0x4050, None, 0, 0, 100, 50, 8);
            let w_id = b.store.lookup(0x4050).expect("W id");
            let b_id = b
                .store
                .allocate(
                    0x4051,
                    DrawableKind::Pixmap,
                    24,
                    true,
                    Storage::for_tests_null(
                        ash::vk::Extent2D {
                            width: 116,
                            height: 66,
                        },
                        ash::vk::Format::B8G8R8A8_UNORM,
                    ),
                )
                .expect("backing allocate");
            b.store.set_redirected_target(w_id, Some(b_id));
            b.store.set_content_offset(b_id, 8);
            b.store.set_scene_participating(w_id, participating);
            assert_eq!(
                b.paint_target_shape_for_tests(0x4050),
                Some(((8, 8), Some((8, 8, 100, 50)), true)),
                "redirect mode (participating={participating}) must not change \
                 the content clip",
            );
        }
    }

    /// #133 step 3 (3.3) — a width/height resize reallocates storage at
    /// the BORDERED extent. It goes through the same `Migrate` door as
    /// a `border_width` change (#143); this pins the extent, the
    /// content is pinned by the acceptance suite.
    #[test]
    fn resize_reallocates_storage_at_the_bordered_extent() {
        let mut b = KmsBackend::for_tests();
        seed_bordered_window(&mut b, 0x4060, None, 0, 0, 100, 50, 16);
        assert_eq!(b.storage_extent_for_tests(0x4060), Some((132, 82)));
        // Grow the content: storage follows as (w + 2bw) x (h + 2bw).
        if let Some(g) = b.windows.get_mut(&0x4060) {
            g.width = 200;
            g.height = 120;
        }
        b.sync_window_leaf_storage(0x4060, super::LeafContent::Migrate);
        assert_eq!(b.storage_extent_for_tests(0x4060), Some((232, 152)));
        // A re-sync with nothing changed must NOT reallocate (the
        // compare-and-skip is against the bordered extent).
        let id_before = b.store.lookup(0x4060);
        b.sync_window_leaf_storage(0x4060, super::LeafContent::Migrate);
        assert_eq!(b.store.lookup(0x4060), id_before, "no needless realloc");
    }

    /// #133 step 3 round 2 (P4) — the `RepeatNone` source-domain clip
    /// is IDENTITY for every pre-#133 source: a pixmap (no domain at
    /// all) and a `bw == 0` window (whose content IS its storage) both
    /// yield `None`, so the composite clip list is byte-identical
    /// there. A bordered window yields its own extent.
    #[test]
    fn picture_source_domain_clip_is_identity_without_a_border() {
        use crate::kms::render::engine::{ResolvedSource, SourceDrawable};
        let mut b = KmsBackend::for_tests();
        // bw == 0: storage IS the content.
        let plain = seed_bordered_window(&mut b, 0x4080, None, 0, 0, 100, 50, 0);
        let plain_src = ResolvedSource::Drawable(SourceDrawable::content(
            plain,
            (0, 0),
            ash::vk::Extent2D {
                width: 100,
                height: 50,
            },
        ));
        assert_eq!(
            super::picture_source_domain_clip(&b.store, &plain_src, Repeat::None, None),
            None,
            "bw == 0 must not add a clip term",
        );
        // A pixmap source carries no domain at all.
        let pix_src = ResolvedSource::Drawable(SourceDrawable::whole(plain));
        assert_eq!(
            super::picture_source_domain_clip(&b.store, &pix_src, Repeat::None, None),
            None,
        );
        // bw > 0: the window's own extent restricts the storage.
        let bordered = seed_bordered_window(&mut b, 0x4081, None, 0, 0, 100, 50, 16);
        let bordered_src = ResolvedSource::Drawable(SourceDrawable::content(
            bordered,
            (16, 16),
            ash::vk::Extent2D {
                width: 100,
                height: 50,
            },
        ));
        assert_eq!(
            super::picture_source_domain_clip(&b.store, &bordered_src, Repeat::None, None),
            Some(vec![Rectangle16 {
                x: 0,
                y: 0,
                width: 100,
                height: 50,
            }]),
        );
        // …but only for RepeatNone with no transform: the other repeat
        // modes wrap/clamp against the sampled image and a transformed
        // domain does not project to a rect in dst space.
        assert_eq!(
            super::picture_source_domain_clip(&b.store, &bordered_src, Repeat::Normal, None),
            None,
        );
        assert_eq!(
            super::picture_source_domain_clip(
                &b.store,
                &bordered_src,
                Repeat::None,
                Some(&crate::kms::cpu_types::PictTransform::IDENTITY),
            ),
            None,
        );
    }

    /// #133 step 3 round 4 — the xts `Xlib4/XSetWindowBackgroundPixmap`
    /// purpose-2 crash, root cause.
    ///
    /// That purpose is the only Xlib4 purpose that sets a border width
    /// on the window it then clears and reads
    /// (`XSetWindowBorderWidth(display, w, 2)`), and `checktile`
    /// (`xts5/src/lib/checktile.c:160-183`) reads it back with
    /// `getsize()` → `XGetImage(d, 0, 0, width, height, …)` →
    /// `XGetPixel` over the full `width x height`.
    ///
    /// #133 step 6 (6.1) — `XSetWindowBorderWidth` on a window created
    /// with `border_width = 0`: the awesome reproduction's shape and
    /// the shape six xts5 `Xlib4` purposes use (`crechild` creates with
    /// `bw = 0`, `xts5/src/lib/crechild.c:189`, and the purpose then
    /// calls `XSetWindowBorderWidth`).
    ///
    /// Before step 6 this changed the geometry mirror and nothing else,
    /// so the allocation kept its unbordered layout and the ring stayed
    /// 0 px wide however wide the client asked for. Now the bordered
    /// extent moved, so the storage is reallocated and the new content
    /// offset recorded — and, since the layout is a property of the
    /// allocation, the resolver's content origin and clip follow in the
    /// same step rather than describing a rectangle the storage cannot
    /// accommodate.
    #[test]
    fn border_width_change_reallocates_and_records_the_new_layout() {
        use yserver_core::host_x11::HostSubwindowConfig;

        let mut b = KmsBackend::for_tests();
        seed_bordered_window(&mut b, 0x4090, None, 0, 0, 16, 8, 0);
        assert_eq!(
            b.paint_target_shape_for_tests(0x4090),
            Some(((0, 0), None, false)),
            "baseline: unbordered layout",
        );

        b.configure_subwindow(
            None,
            0x4090,
            HostSubwindowConfig {
                border_width: Some(2),
                ..HostSubwindowConfig::default()
            },
        )
        .expect("configure border width");
        assert_eq!(
            b.windows[&0x4090].border_width, 2,
            "the geometry mirror carries the new border width",
        );
        assert_eq!(
            b.storage_extent_for_tests(0x4090),
            Some((20, 12)),
            "the bordered extent moved, so the storage is reallocated at \
             (w + 2bw) x (h + 2bw)",
        );
        assert_eq!(
            b.paint_target_shape_for_tests(0x4090),
            Some(((2, 2), Some((2, 2, 16, 8)), true)),
            "…and the content origin is (bw, bw) in the new allocation",
        );
    }

    /// #133 step 6 (6.2) — the case prose alone would let an
    /// implementer skip: `w=100,bw=2 → w=98,bw=3` in ONE configure.
    /// The outer extent is 104 either way, so nothing is reallocated
    /// (Xorg's `compReallocPixmap` takes its `else` branch,
    /// `composite/compalloc.c:706`) — and the content offset still has
    /// to move from 2 to 3, with the pixels.
    ///
    /// Asserted here on the LAYOUT (no Vk in a unit test, so the copy
    /// itself is a no-op); the pixels are asserted in
    /// `render_acceptance.rs`'s
    /// `border_change_with_unchanged_outer_extent_migrates_the_content`.
    #[test]
    fn border_change_with_unchanged_outer_extent_relocates_without_realloc() {
        use yserver_core::host_x11::HostSubwindowConfig;

        let mut b = KmsBackend::for_tests();
        seed_bordered_window(&mut b, 0x4091, None, 0, 0, 100, 60, 2);
        assert_eq!(b.storage_extent_for_tests(0x4091), Some((104, 64)));
        let id_before = b.store.lookup(0x4091);

        b.configure_subwindow(
            None,
            0x4091,
            HostSubwindowConfig {
                width: Some(98),
                height: Some(58),
                border_width: Some(3),
                ..HostSubwindowConfig::default()
            },
        )
        .expect("configure w + border width");

        assert_eq!(
            b.storage_extent_for_tests(0x4091),
            Some((104, 64)),
            "outer extent unchanged: 98 + 6 == 100 + 4",
        );
        assert_eq!(
            b.store.lookup(0x4091),
            id_before,
            "and therefore NOT reallocated (6.1)",
        );
        assert_eq!(
            b.paint_target_shape_for_tests(0x4091),
            Some(((3, 3), Some((3, 3, 98, 58)), true)),
            "the content offset moved with the border width (6.2)",
        );
    }

    /// #133 step 6 (6.4) — a pure `x`/`y` move changes the window's
    /// screen origin, which the scene walk applies from the geometry,
    /// and must relocate NOTHING storage-local.
    ///
    /// Seeded with an allocation whose content offset deliberately
    /// disagrees with the live `border_width` — the state step 3's
    /// invariant exists for — because that is what makes the assertion
    /// bite: an implementation that reacted to any geometry change by
    /// re-basing the content off `border_width` would move pixels here.
    #[test]
    fn pure_move_relocates_nothing_storage_local() {
        use yserver_core::host_x11::HostSubwindowConfig;

        let mut b = KmsBackend::for_tests();
        let id = seed_bordered_window(&mut b, 0x4092, None, 10, 10, 100, 60, 4);
        // The allocation says 4; the live geometry says 9. Only step 6's
        // border-width path may reconcile that, and only by moving the
        // pixels — a move must leave it exactly as it is.
        b.windows.get_mut(&0x4092).expect("geom").border_width = 9;

        b.configure_subwindow(
            None,
            0x4092,
            HostSubwindowConfig {
                x: Some(200),
                y: Some(120),
                ..HostSubwindowConfig::default()
            },
        )
        .expect("configure move");

        assert_eq!(b.store.lookup(0x4092), Some(id), "no reallocation");
        assert_eq!(
            b.storage_extent_for_tests(0x4092),
            Some((108, 68)),
            "storage extent untouched by a move",
        );
        assert_eq!(
            b.store.get(id).map(|d| d.content_offset),
            Some(4),
            "the content offset is a property of the ALLOCATION; a move \
             changes the screen origin only",
        );
        assert_eq!(
            b.windows[&0x4092].x, 200,
            "…while the geometry mirror does move",
        );
    }

    /// #133 step 6 — the `bw == 0` identity, on the two configures a
    /// `bw == 0` desktop actually sends.
    ///
    /// A `CWBorderWidth` value equal to the current one is not a
    /// change, so it must not reach the step-6 path at all (Xorg
    /// short-circuits the same comparison: `if ((mask & CWBorderWidth)
    /// && (bw != wBorderWidth(pWin)))`, `dix/window.c:2347`). And a
    /// pure resize keeps the pre-#133 path: reallocate at `(w, h)`,
    /// content offset 0, content DISCARDED (see `LeafContent`).
    #[test]
    fn bw_zero_configures_keep_the_pre_133_paths() {
        use yserver_core::host_x11::HostSubwindowConfig;

        let mut b = KmsBackend::for_tests();
        let id = seed_bordered_window(&mut b, 0x4093, None, 0, 0, 100, 60, 0);

        // CWBorderWidth = 0 on a bw == 0 window: not a change.
        b.configure_subwindow(
            None,
            0x4093,
            HostSubwindowConfig {
                border_width: Some(0),
                ..HostSubwindowConfig::default()
            },
        )
        .expect("configure bw 0 -> 0");
        assert_eq!(b.store.lookup(0x4093), Some(id), "no reallocation");
        assert_eq!(b.storage_extent_for_tests(0x4093), Some((100, 60)));
        assert_eq!(
            b.paint_target_shape_for_tests(0x4093),
            Some(((0, 0), None, false)),
            "no border clip term at bw == 0",
        );

        // A pure resize: the pre-#133 reallocate-and-discard path.
        b.configure_subwindow(
            None,
            0x4093,
            HostSubwindowConfig {
                width: Some(200),
                height: Some(120),
                ..HostSubwindowConfig::default()
            },
        )
        .expect("configure resize");
        assert_eq!(b.storage_extent_for_tests(0x4093), Some((200, 120)));
        assert_eq!(
            b.paint_target_shape_for_tests(0x4093),
            Some(((0, 0), None, false)),
            "still no border clip term",
        );
    }

    /// #133 step 6 (6.2) — the copy geometry itself: the source is the
    /// OLD content rect (derived from the old allocation alone) clipped
    /// to the new content extent, and the destination is the new
    /// content origin, so a pixel at content `(cx, cy)` stays at
    /// content `(cx, cy)`.
    #[test]
    fn migrated_content_copy_maps_content_origin_to_content_origin() {
        let ext = |w: u32, h: u32| ash::vk::Extent2D {
            width: w,
            height: h,
        };
        // The spec's case: 104x64 storage at offset 2 (content 100x60)
        // → content 98x58 at offset 3.
        assert_eq!(
            super::migrated_content_copy(ext(104, 64), 2, 98, 58, 3),
            Some((vkrect(2, 2, 98, 58), ash::vk::Offset2D { x: 3, y: 3 })),
        );
        // Growing the border with the content unchanged (the awesome
        // reproduction): the whole old content moves outward.
        assert_eq!(
            super::migrated_content_copy(ext(100, 60), 0, 100, 60, 16),
            Some((vkrect(0, 0, 100, 60), ash::vk::Offset2D { x: 16, y: 16 })),
        );
        // Shrinking the border to nothing (xts's bw -> 0).
        assert_eq!(
            super::migrated_content_copy(ext(102, 62), 1, 100, 60, 0),
            Some((vkrect(1, 1, 100, 60), ash::vk::Offset2D { x: 0, y: 0 })),
        );
        // The intersection, when the content shrinks by more than the
        // border grows: only the surviving part is copied.
        assert_eq!(
            super::migrated_content_copy(ext(104, 64), 2, 40, 20, 3),
            Some((vkrect(2, 2, 40, 20), ash::vk::Offset2D { x: 3, y: 3 })),
        );
        // Degenerate: an offset that swallows the whole allocation has
        // no content to move.
        assert_eq!(super::migrated_content_copy(ext(4, 4), 2, 10, 10, 1), None);
    }

    /// #133 step 3 (3.5) — the direct-scanout gate's INPUT: a bordered
    /// window's resolved paint target reports a border clip, which is
    /// what `scanout_direct_eligible` rejects on. A fullscreen bordered
    /// window therefore cannot take the flip path.
    #[test]
    fn bordered_fullscreen_window_reports_a_border_clip_to_the_scanout_gate() {
        let mut b = KmsBackend::for_tests();
        // Fullscreen-shaped candidate at the origin, but bordered.
        seed_bordered_window(&mut b, 0x4070, None, 0, 0, 800, 600, 2);
        let (_, _, bordered) = b
            .paint_target_shape_for_tests(0x4070)
            .expect("resolve bordered fullscreen");
        assert!(bordered, "bordered chain must report a border clip");
        assert!(
            !super::scanout_direct_eligible(true, true, true, true, true, !bordered, 0, 0, 0),
            "a bordered candidate must never be admitted to direct scanout",
        );
        // The same window unbordered is admitted (so the rejection is
        // attributable to the border, not to the rest of the gate).
        seed_bordered_window(&mut b, 0x4071, None, 0, 0, 800, 600, 0);
        let (_, _, plain) = b
            .paint_target_shape_for_tests(0x4071)
            .expect("resolve plain fullscreen");
        assert!(!plain);
        assert!(super::scanout_direct_eligible(
            true, true, true, true, true, !plain, 0, 0, 0
        ));
    }

    #[test]
    fn clip_fill_rects_by_subwindow_mode_subtracts_mapped_child() {
        let mut b = KmsBackend::for_tests();
        let _parent = seed_window(&mut b, 0x100, None, 0, 0);
        let _child = seed_window(&mut b, 0x200, Some(0x100), 10, 20);
        let child = b.windows.get_mut(&0x200).expect("child geom");
        child.width = 15;
        child.height = 10;
        b.core.current_subwindow_mode = yserver_core::backend::SubwindowMode::ClipByChildren;

        let out = b.clip_fill_rects_by_subwindow_mode(
            0x100,
            &[Rectangle16 {
                x: 0,
                y: 0,
                width: 40,
                height: 40,
            }],
        );
        let got: std::collections::BTreeSet<(i16, i16, u16, u16)> = out
            .into_iter()
            .map(|r| (r.x, r.y, r.width, r.height))
            .collect();
        let want = std::collections::BTreeSet::from([
            (0, 0, 40, 20),
            (0, 30, 40, 10),
            (0, 20, 10, 10),
            (25, 20, 15, 10),
        ]);
        assert_eq!(got, want);
    }

    /// The per-request clip is cached; any change to the window tree
    /// (a child moved, here) computes it again.
    #[test]
    fn clip_fill_rects_by_subwindow_mode_follows_a_moved_child() {
        let mut b = KmsBackend::for_tests();
        let _parent = seed_window(&mut b, 0x100, None, 0, 0);
        let _child = seed_window(&mut b, 0x200, Some(0x100), 10, 20);
        b.core.current_subwindow_mode = yserver_core::backend::SubwindowMode::ClipByChildren;
        let span = [Rectangle16 {
            x: 0,
            y: 25,
            width: 40,
            height: 1,
        }];
        let child = b.windows.get_mut(&0x200).expect("child geom");
        (child.width, child.height) = (15, 10);
        let before = b.clip_fill_rects_by_subwindow_mode(0x100, &span);
        assert_eq!(before.len(), 2, "split around the child: {before:?}");
        b.windows.get_mut(&0x200).expect("child geom").y = 100;
        assert_eq!(
            b.clip_fill_rects_by_subwindow_mode(0x100, &span),
            span.to_vec()
        );
    }

