    #[test]
    fn a_stale_arm_token_does_not_advance_the_reference() {
        let mut ids = IdentityAllocator::new(IncarnationId::first());
        let mut arms = SequenceArmTable::default();
        let live = ids.next_sequence_arm();
        arms.insert(SequenceArm {
            token: live,
            crtc_id: 0x42,
            epoch: ClockEpochId::first(),
            purpose: SequenceArmPurpose::AbsolutePerTarget,
            target: 1_000,
        });
        let stale = ids.next_sequence_arm(); // never armed
        assert!(arms.take_matching_arm(stale).is_none());
        assert!(arms.take_matching_arm(live).is_some());
    }

    #[test]
    fn an_arm_token_is_consumed_exactly_once() {
        let mut ids = IdentityAllocator::new(IncarnationId::first());
        let mut arms = SequenceArmTable::default();
        let token = ids.next_sequence_arm();
        arms.insert(SequenceArm {
            token,
            crtc_id: 1,
            epoch: ClockEpochId::first(),
            purpose: SequenceArmPurpose::Relative,
            target: 0,
        });
        assert!(arms.take_matching_arm(token).is_some());
        assert!(
            arms.take_matching_arm(token).is_none(),
            "a consumed arm must not fire twice"
        );
    }

    #[test]
    fn an_event_token_echoed_into_the_sequence_path_is_rejected() {
        let mut ids = IdentityAllocator::new(IncarnationId::first());
        let mut arms = SequenceArmTable::default();
        let event = ids.next_event_token();
        // A page-flip token must never decode as a sequence arm, even if the
        // counter happens to match: the purpose tag differs.
        assert!(
            SequenceArmToken::from_user_data(event.as_user_data())
                .is_none_or(|token| arms.take_matching_arm(token).is_none())
        );
    }

    #[test]
    fn a_zero_user_data_never_decodes_as_an_arm() {
        assert!(SequenceArmToken::from_user_data(0).is_none());
    }

    #[test]
    fn arm_present_absolute_vblank_with_dedups_same_target_one_kernel_call() {
        let mut b = super::KmsBackend::for_tests();
        let crtc_key = output_crtc_key(&b, 0);
        let mut calls = 0u32;

        let covered = b
            .arm_present_absolute_vblank_with(crtc_key, &[500], |_, _| {
                calls += 1;
                Ok(true)
            })
            .unwrap();
        assert_eq!(covered, 1);
        assert_eq!(calls, 1);

        // Re-arming the same target on the same CRTC must not re-issue the
        // ioctl (real invariant: `calls` stays 1) — but it IS still
        // covered by the earlier in-flight arm, so the return value must
        // stay 1, not fall to 0. `Ok(0)`/`Err` mean "arm failed, caller
        // must execute immediately" (spec §msc-due) — a still-parked,
        // already-armed target must never read as that.
        let covered2 = b
            .arm_present_absolute_vblank_with(crtc_key, &[500], |_, _| {
                calls += 1;
                Ok(true)
            })
            .unwrap();
        assert_eq!(covered2, 1, "duplicate target stays covered, not 0");
        assert_eq!(calls, 1, "duplicate target must not re-arm");

        // A distinct target on the same CRTC still arms (own per-target
        // set, unlike the relative arm's single in-flight slot).
        let covered3 = b
            .arm_present_absolute_vblank_with(crtc_key, &[600], |_, _| {
                calls += 1;
                Ok(true)
            })
            .unwrap();
        assert_eq!(covered3, 1);
        assert_eq!(calls, 2);
    }

    #[test]
    fn arm_present_absolute_vblank_false_result_is_not_tracked_as_covered() {
        let mut b = super::KmsBackend::for_tests();
        let crtc_key = output_crtc_key(&b, 0);
        let mut calls = 0;

        let covered = b
            .arm_present_absolute_vblank_with(crtc_key, &[500], |_, _| {
                calls += 1;
                Ok(false)
            })
            .unwrap();

        assert_eq!(calls, 1);
        assert_eq!(covered, 0);
        assert!(b.absolute_vblank_targets.is_empty());
    }

    /// Push a second live output onto the fixture, with its own selected raw
    /// CRTC handle. Mirrors `PlatformBackend::for_tests()`'s single-output
    /// literal.
    pub(super) fn push_test_output(b: &mut super::KmsBackend, crtc_id: u32) {
        use crate::kms::backend::ActiveOutput;
        let device_key = b
            .platform
            .primary_device()
            .expect("test fixture has a DRM device")
            .key;
        let scanout_route = b
            .platform
            .scanout_route_for_kms(device_key)
            .expect("test fixture has a scanout route");
        b.platform.outputs.push(ActiveOutput::new(
            scanout_route,
            crate::platform::drm::Output {
                connector: ::drm::control::from_u32(crtc_id).unwrap(),
                connector_name: "test2".to_string(),
                encoder: ::drm::control::from_u32(crtc_id).unwrap(),
                crtc: ::drm::control::from_u32(crtc_id).unwrap(),
                plane: ::drm::control::from_u32(crtc_id).unwrap(),
                // SAFETY: tests never pass this mode to DRM.
                mode: unsafe { std::mem::zeroed() },
                picked: crate::platform::drm::Mode {
                    name: "test2".to_string(),
                    width: 800,
                    height: 600,
                    vrefresh: 60,
                    preferred: true,
                    ..Default::default()
                },
                plane_fb_id_prop: ::drm::control::from_u32(1).unwrap(),
                plane_crtc_id_prop: ::drm::control::from_u32(1).unwrap(),
                plane_src_x_prop: ::drm::control::from_u32(1).unwrap(),
                plane_src_y_prop: ::drm::control::from_u32(1).unwrap(),
                plane_src_w_prop: ::drm::control::from_u32(1).unwrap(),
                plane_src_h_prop: ::drm::control::from_u32(1).unwrap(),
                plane_crtc_x_prop: ::drm::control::from_u32(1).unwrap(),
                plane_crtc_y_prop: ::drm::control::from_u32(1).unwrap(),
                plane_crtc_w_prop: ::drm::control::from_u32(1).unwrap(),
                plane_crtc_h_prop: ::drm::control::from_u32(1).unwrap(),
                plane_in_fence_fd_prop: None,
                crtc_out_fence_ptr_prop: None,
                scanout_modifiers: Vec::new(),
                mm_width: 0,
                mm_height: 0,
                edid: Vec::new(),
                connector_type: "unknown".to_string(),
                modes: vec![crate::platform::drm::Mode {
                    name: "test2".to_string(),
                    width: 800,
                    height: 600,
                    vrefresh: 60,
                    preferred: true,
                    ..Default::default()
                }],
            },
            crate::drm::Swapchain::empty_for_tests(),
            800,
            0,
        ));
        let output_key = b.platform.outputs.last().expect("new output").key.clone();
        let instance_id = b
            .platform
            .allocate_output_instance_id(&output_key)
            .expect("new test output instance");
        b.platform.output_instance_ids.push(instance_id);
    }

    pub(super) fn install_direct_frame_for_target_test(
        b: &mut super::KmsBackend,
        target_xid: u32,
        fallback_id: crate::kms::render::store::DrawableId,
        current: bool,
    ) -> (
        crate::kms::render::store::DrawableId,
        crate::kms::render::store::DrawableId,
        u64,
        u64,
    ) {
        use ash::vk;
        use yserver_core::backend::{
            CompletedPresentEvent, PresentClockSample, PresentClockSource, PresentScanoutCandidate,
            PresentWake,
        };

        use crate::kms::render::store::{DrawableKind, Storage};

        let source_xid = target_xid + 1;
        let source_id = b
            .store
            .allocate(
                source_xid,
                DrawableKind::Pixmap,
                24,
                false,
                Storage::for_tests_null(
                    vk::Extent2D {
                        width: 100,
                        height: 100,
                    },
                    vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("direct source");
        let source_pin = b.pin_direct_source(source_id);
        let fallback_target_pin = b.pin_direct_source(fallback_id);
        let completion_clock = current.then_some(PresentClockSample {
            msc: 17,
            ust: 1_700,
            source: PresentClockSource::PageFlip,
        });
        let candidate = PresentScanoutCandidate {
            client_id: 1,
            present_id: 77,
            crtc_id: 0,
            crtc_epoch: 0,
            src_pixmap_xid: source_xid,
            dst_window_xid: target_xid,
            src_host_xid: source_xid,
            paint_dst_host_xid: target_xid,
            completion_dst_host_xid: target_xid,
            src_width: 100,
            src_height: 100,
            x_off: 0,
            y_off: 0,
            valid_region_xid: 0,
            update_region_xid: 0,
            update_is_full: true,
            explicit_sync: false,
            options: 0,
        };
        let frame = super::DirectPresentFrame {
            source_pin,
            fallback_target_pin,
            framebuffer_lease: None,
            source_id,
            candidate,
            fallback_target: PaintTarget::new(fallback_id, (0, 0), None, 24),
            members: Vec::new(),
            event: CompletedPresentEvent {
                client_id: yserver_protocol::x11::ClientId(1),
                serial: 9,
                host_xid: source_xid,
                dst_host_xid: target_xid,
                options: 0,
                present_id: 77,
                window_generation: 5,
                crtc_id: 0,
                crtc_epoch: 0,
                msc_offset: 0,
                completion_clock,
                wake: PresentWake::Pixmap { idle_fence_xid: 0 },
                completion_mode: if current {
                    yserver_protocol::x11::present::COMPLETE_MODE_FLIP
                } else {
                    yserver_protocol::x11::present::COMPLETE_MODE_COPY
                },
                emit_idle: !current,
            },
            commit_id: None,
            completion_output_idx: 0,
            completion_clock,
            awaiting_outputs: if current {
                std::collections::HashSet::new()
            } else {
                std::collections::HashSet::from([0])
            },
            admission_source_generation: None,
        };
        if current {
            b.scanout_m2.current = Some(frame);
        } else {
            b.scanout_m2.pending = Some(frame);
        }
        b.scanout_m2.hold_direct = true;
        b.scanout_m2.sync_ownership();
        (source_id, fallback_id, source_pin, fallback_target_pin)
    }

    /// F5a-M1 decisive test: `direct_ownership_handle()` is a live view of
    /// this backend's own `ScanoutM2State`, not a value nobody publishes
    /// (the deleted `DirectOwnershipSignal`). Driving `current` occupied and
    /// an unflip requested through the real production functions
    /// (`install_direct_frame_for_target_test` mirrors the real "direct
    /// frame retired" assignment, `request_direct_unflip`,
    /// `stop_direct_after_scanout_replaced`) must be visible to a
    /// `TransportGate` built from a clone of the handle, with no setter
    /// call on the gate or the handle itself. Mutation check: reverting any
    /// of the `sync_ownership()` call sites this session added would leave
    /// `direct_ownership_busy()`/`unflip_outstanding()` stuck at their
    /// `Default` (`false`) values, and `begin_quiescing()` below would
    /// wrongly succeed while `current` is still occupied.
    #[test]
    fn c0_2ci_scanout_m2_ownership_handle_reflects_real_backend_state() {
        use crate::kms::render::resources::{ResourceError, TransportGate, TransportState};

        let mut b = super::KmsBackend::for_tests();
        b.get_overlay_window(None).expect("materialize COW");
        let cow_id = b.cow_id.expect("COW id");
        let target_xid = 0x7100;
        seed_window(&mut b, target_xid, None, 0, 0);
        install_direct_frame_for_target_test(&mut b, target_xid, cow_id, true);

        let device = test_device_key(0);
        let incarnation = IncarnationId::first();
        let mut gate =
            TransportGate::new_legacy(device, incarnation, Box::new(b.direct_ownership_handle()));

        // The real unit is `Current`: begin_quiescing refuses without
        // changing state (R7).
        assert_eq!(gate.begin_quiescing(), Err(ResourceError::Busy));
        assert_eq!(gate.state(), TransportState::Legacy);

        // Also request an unflip while still occupied -- a second,
        // independent real reason to stay Busy.
        b.request_direct_unflip("c0_2ci_ownership_handle_test");
        assert!(b.scanout_m2.unflip_requested);
        assert_eq!(gate.begin_quiescing(), Err(ResourceError::Busy));
        assert_eq!(gate.state(), TransportState::Legacy);

        // Retire through the real stop path: current vacates and the
        // unflip retires in the same call.
        b.stop_direct_after_scanout_replaced("c0_2ci_ownership_handle_test retirement");
        assert!(!b.scanout_m2.active());
        assert!(!b.scanout_m2.unflip_requested);
        assert!(gate.begin_quiescing().is_ok());
        assert_eq!(gate.state(), TransportState::Quiescing);
    }

