    #[test]
    fn c0_2ci_backend_managed_unflip_moves_current_into_exit_retirement_even_if_ordinary_occupied()
    {
        use crate::kms::render::resources::{CommitResources, DirectRole};

        let mut b = super::KmsBackend::for_tests();

        // OrdinaryRetirement is already occupied by an unrelated, still
        // in-flight retirement (F7-B2: unflip must not need it vacant).
        let ordinary_slot = b
            .commit_consumer
            .capacity
            .reserve(DirectRole::OrdinaryRetirement)
            .unwrap();
        let ordinary_res =
            CommitResources::new(Vec::new(), None, None, None, Vec::new(), Vec::new());
        let ordinary_res = b
            .commit_consumer
            .capacity
            .attach(ordinary_slot, ordinary_res)
            .unwrap();
        b.commit_consumer.releasing_resources.push(ordinary_res);

        // Current is occupied by the backend's own in-flight direct frame.
        let current_slot = b
            .commit_consumer
            .capacity
            .reserve(DirectRole::Current)
            .unwrap();
        let current_res =
            CommitResources::new(Vec::new(), None, None, None, Vec::new(), Vec::new());
        let current_res = b
            .commit_consumer
            .capacity
            .attach(current_slot, current_res)
            .unwrap();
        b.commit_consumer.current_resources.push(current_res);

        // A queued successor with its own charge -- unflip's "cancels
        // unsent direct work" must discharge it, never bare-drop it.
        let (id, candidate, event) = managed_prepare_ready_candidate(&mut b, 0x7201, 0x7202, 30, 1);
        assert!(
            b.managed_prepare_direct_candidate(id, candidate, event)
                .unwrap()
        );
        // OrdinaryRetirement + Current + Successor.
        assert_eq!(b.commit_consumer.capacity.occupied(), 3);

        let can_reenter = b
            .managed_handle_direct_unflip("test_ordinary_occupied")
            .unwrap();
        // This fixture never retains a composed framebuffer per output, so
        // re-entry is refused regardless of role state (unchanged contract).
        assert!(!can_reenter);
        assert_eq!(can_reenter, b.managed_can_enter_direct());

        // The queued successor's charge was discharged, not bare-dropped
        // (a bare drop would have closed admission instead).
        assert!(b.scanout_m2.queued_successor.is_none());
        assert!(b.scanout_m2.queued_successor_role.is_none());
        assert!(!b.commit_consumer.capacity.is_admission_closed());

        // Current moved into a freshly reserved ExitRetirement even though
        // OrdinaryRetirement stayed occupied the whole time (8.5).
        assert!(b.commit_consumer.current_resources.is_empty());
        assert_eq!(b.commit_consumer.releasing_resources.len(), 2);
        assert!(
            b.commit_consumer.releasing_resources.iter().any(|res| res
                .direct_role
                .as_ref()
                .unwrap()
                .role()
                == DirectRole::ExitRetirement)
        );
        assert!(
            b.commit_consumer.releasing_resources.iter().any(|res| res
                .direct_role
                .as_ref()
                .unwrap()
                .role()
                == DirectRole::OrdinaryRetirement)
        );
        assert_eq!(b.commit_consumer.capacity.occupied(), 2);

        // Re-entry is refused at the capacity level while both retirement
        // roles are occupied; discharging both (without dropping a token)
        // frees the capacity table completely and permits re-entry.
        assert!(!b.commit_consumer.capacity.can_enter_direct());
        for mut res in b.commit_consumer.releasing_resources.drain(..) {
            let slot = res.direct_role.take().unwrap();
            b.commit_consumer.capacity.finish_role(slot).unwrap();
        }
        assert!(b.commit_consumer.capacity.can_enter_direct());
        assert_eq!(b.commit_consumer.capacity.occupied(), 0);
    }
    /// Issue #146 — the dedup key must not move when only the region XIDs do.
    ///
    /// `scanout_m0 shape` logs when the shape CHANGES, and the key used to
    /// carry the Present valid/update region XIDs. A compositor creates a
    /// fresh update region every frame (`0x4144dd` → `0x4144eb` → `0x4144f9`
    /// across three consecutive Presents in the #146 report), so the key
    /// changed on every Present by construction and the guard suppressed
    /// nothing — one ~700-byte line per composited frame.
    ///
    /// The sibling test above cannot catch this: it sends
    /// `update_region_xid: 0` on both Presents, so the key is identical
    /// either way and it passes before and after the fix.
    ///
    /// Both directions are asserted. Identity must NOT move the key, or the
    /// flood returns; presence must STILL move it, or the fix has simply
    /// thrown the information away.
    #[test]
    fn scanout_m0_shape_ignores_region_xid_identity_but_not_presence() {
        use crate::kms::render::store::{DrawableKind, Storage};
        use ash::vk;
        use yserver_core::backend::PresentScanoutCandidate;

        let mut b = super::KmsBackend::for_tests();
        seed_window(&mut b, 0xD57, None, 0, 0);
        b.store
            .allocate(
                0x5AC,
                DrawableKind::Pixmap,
                24,
                false,
                Storage::for_tests_null(
                    vk::Extent2D {
                        width: 100,
                        height: 100,
                    },
                    vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("source");
        let base = PresentScanoutCandidate {
            client_id: 1,
            present_id: 1,
            crtc_id: 0,
            crtc_epoch: 0,
            src_pixmap_xid: 0x100,
            dst_window_xid: 0x200,
            src_host_xid: 0x5AC,
            paint_dst_host_xid: 0xD57,
            completion_dst_host_xid: 0xD57,
            src_width: 100,
            src_height: 100,
            x_off: 0,
            y_off: 0,
            // A real compositor's regions: present, and a different XID every
            // frame. These are the exact values from the #146 report.
            valid_region_xid: 0,
            update_region_xid: 0x0041_44dd,
            update_is_full: false,
            explicit_sync: false,
            options: 0,
        };

        b.observe_scanout_m0(base);
        let after_first = b.scanout_m0.last_shape_by_dst[&0xD57].clone();

        for (present_id, update) in [(2u64, 0x0041_44ebu32), (3, 0x0041_44f9)] {
            b.observe_scanout_m0(PresentScanoutCandidate {
                present_id,
                update_region_xid: update,
                ..base
            });
            assert_eq!(
                b.scanout_m0.last_shape_by_dst[&0xD57], after_first,
                "a fresh update-region XID must not count as a shape change \
                 (present {present_id}, update {update:#x}) — that is the \
                 per-frame log flood in #146",
            );
        }

        // ...but losing the region entirely IS a real change, so the key has
        // to notice. Otherwise the fix would just have dropped the signal.
        b.observe_scanout_m0(PresentScanoutCandidate {
            present_id: 4,
            update_region_xid: 0,
            update_is_full: true,
            ..base
        });
        assert_ne!(
            b.scanout_m0.last_shape_by_dst[&0xD57], after_first,
            "a Present that carries no update region at all is a different \
             shape and must still be logged",
        );
    }

