    impl crate::kms::render::admission::AdmissionSource for AdmissionSourceFixture {
        fn producer_readiness(
            &self,
            key: crate::kms::owner::admission::IntentKey,
        ) -> crate::kms::owner::admission::Readiness {
            if self.composed_waiting
                && matches!(
                    key,
                    crate::kms::owner::admission::IntentKey::Composed { .. }
                )
            {
                return crate::kms::owner::admission::Readiness::Waiting(
                    crate::kms::owner::admission::WaitReason::SourceWaits,
                );
            }
            self.readiness
                .borrow()
                .get(&key)
                .copied()
                .unwrap_or(crate::kms::owner::admission::Readiness::Ready)
        }

        fn describe(
            &mut self,
            decision: &crate::kms::owner::admission::AdmissionDecision,
        ) -> crate::kms::owner::build::CommitDescription {
            self.describe_calls.set(self.describe_calls.get() + 1);
            self.described_carried.set(decision.carried.len());
            if self.describe_page_flip.get() {
                crate::kms::owner::test_fixtures::single_active_crtc_with_present(1)
            } else {
                crate::kms::owner::test_fixtures::single_active_crtc()
            }
        }

        fn maintenance_readiness(
            &self,
            key: crate::kms::owner::admission::MaintenanceKey,
            generation: u64,
        ) -> crate::kms::owner::admission::Readiness {
            self.producer_readiness(crate::kms::owner::admission::IntentKey::Maintenance {
                key,
                generation,
            })
        }

        fn compatible(
            &self,
            key: crate::kms::owner::admission::MaintenanceKey,
            generation: u64,
            primary: crate::kms::owner::admission::IntentKey,
        ) -> bool {
            self.maintenance_compatibility
                .borrow()
                .get(&(key, generation, primary))
                .copied()
                .unwrap_or(true)
        }

        fn homogeneous_group(&self) -> std::collections::BTreeSet<u32> {
            self.homogeneous_group.borrow().clone()
        }

        fn cursor_recovery_ready(&self, crtc: u32) -> bool {
            self.cursor_recovery_ready.borrow().contains(&crtc)
        }

        fn composed_resources(
            &mut self,
            crtc: crate::kms::owner::admission::CrtcId,
            _generation: u64,
        ) -> Vec<crate::kms::render::resources::CommitResources> {
            self.composed_resource_calls
                .set(self.composed_resource_calls.get() + 1);
            if self.composed_resources_empty {
                return Vec::new();
            }
            let member = crate::kms::render::resources::GroupMember::new(
                CrtcKey::new(
                    DrmDeviceKey { major: 0, minor: 0 },
                    ::drm::control::from_u32(crtc).expect("fixture CRTC"),
                ),
                1,
                1,
            );
            vec![
                crate::kms::render::resources::CommitResources::new(
                    Vec::new(),
                    None,
                    None,
                    None,
                    vec![member],
                    Vec::new(),
                )
                .with_direct_role(
                    crate::kms::render::resources::RoleReservation::new_for_test(
                        crate::kms::render::resources::DirectRole::Successor,
                        1,
                        std::rc::Rc::clone(&self.composed_resource_dropped),
                    ),
                ),
            ]
        }

        fn restore_composed_resources(
            &mut self,
            resources: Vec<crate::kms::render::resources::CommitResources>,
        ) {
            self.restored_composed_resources
                .borrow_mut()
                .extend(resources);
        }

        fn direct_eligible(
            &self,
            _source_generation: u64,
            _eligibility: crate::kms::render::backend::DirectEligibility,
        ) -> bool {
            self.direct_eligible.get()
        }
    }

