    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_conv_cp_four_composed_owner_frames_do_not_exhaust_descriptor_ring_vulkan() {
        let OwnerLiveFixture { mut backend, .. } =
            owner_live_fixture().expect("environmental skip: no live Vulkan ICD available");
        let device = backend.platform.primary_device().expect("device").key;
        let mut previous_generation = 0;
        backend.scene.reset_tick_diagnostics_for_tests(0);

        for frame in 0..4 {
            if frame != 0 {
                reinstall_owner_executor_for_cir_test(&mut backend, device);
            }

            backend.scene.mark_scene_structure_dirty();
            backend.test_skip_render_completion_drain = true;
            let tick_result = backend.maybe_composite();
            backend.test_skip_render_completion_drain = false;
            tick_result.expect("the production compositor tick must succeed");
            let diagnostics = backend
                .scene
                .tick_diagnostics_for_tests(0)
                .expect("live Owner output has tick diagnostics");
            let Some((bo_idx, generation, waiting_for_render)) =
                backend.scene.owner_prepared_for_tests(0)
            else {
                panic!(
                    "composed Owner frame {frame} did not acquire a descriptor slot: \
                     skip_counts={:?}, pool_occupancy={:?}",
                    diagnostics.skip_counts, diagnostics.pool_occupancy
                );
            };
            assert!(
                generation > previous_generation,
                "composed Owner frame {frame} did not produce a new generation: \
                 previous={previous_generation}, current={generation}, \
                 skip_counts={:?}, pool_occupancy={:?}",
                diagnostics.skip_counts,
                diagnostics.pool_occupancy
            );
            previous_generation = generation;
            assert!(
                waiting_for_render,
                "frame {frame} remains Rendering until its GPU completion is drained"
            );
            assert!(
                diagnostics.pool_occupancy.0 > 0,
                "frame {frame} must retain its descriptor pool while compose work may use it"
            );

            backend.platform.wait_idle_bounded();
            backend.drain_scanout_render_completions_for_tests();
            assert_eq!(
                owner_state_for_tests(&backend, bo_idx),
                Some(crate::kms::render::owner_buffer::OwnerBufferState::Submitted),
                "frame {frame} generation {generation} must reach admission"
            );

            let commit = backend
                .device_owner_for_tests(0)
                .live_record()
                .expect("composed Owner generation is dispatched")
                .commit_id();
            assert!(backend.route_owner_event_batch(
                device,
                vec![crate::kms::owner::device::OwnerEvent::Accepted { commit }],
                std::time::Instant::now(),
            ));
            assert!(backend.route_owner_event_batch(
                device,
                vec![crate::kms::owner::device::OwnerEvent::HardwareComplete { commit }],
                std::time::Instant::now(),
            ));
            let completion = backend.complete_owner_for_tests(0);
            assert!(
                backend.route_owner_event_batch(device, completion, std::time::Instant::now(),)
            );
            assert_eq!(
                owner_state_for_tests(&backend, bo_idx),
                Some(crate::kms::render::owner_buffer::OwnerBufferState::Current),
                "frame {frame} completes the composed Owner lifecycle"
            );
        }
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_conv_cp_no_legacy_write_at_the_copied_site_vulkan() {
        // The recorder is entered by submit_flip_with_fences before its
        // transport-gate permit check. This observes entry into the legacy
        // primary sink, not the gate's refusal.
        crate::drm::clear_legacy_sink_entries_for_tests();
        let (mut fixture, bo_idx, _, _) = copied_owner_frame_after_a();

        // A's production completion prepares and submits B. No legacy sink
        // is involved in either Owner stage.
        fixture.backend.platform.wait_idle_bounded();
        fixture.backend.drain_scanout_render_completions_for_tests();
        assert!(
            crate::drm::legacy_sink_entries_for_tests().is_empty(),
            "stage A and the copied Owner B preparation must not enter the legacy sink"
        );
        assert!(
            fixture
                .backend
                .scene
                .copied_receipt_for_tests(0, bo_idx)
                .is_some(),
            "the copied Owner producer must reach its production B preparation"
        );

        // B's real sink fence retires through the service, then its existing
        // wake promotes the generation through the Owner conductor. The sink
        // observation is checked before inspecting the resulting commit so a
        // forced legacy branch fails specifically on the write-site evidence.
        wait_copied_sink_idle(&fixture.backend);
        fixture
            .backend
            .resource_service_mut()
            .expect("resource service")
            .service_completions(std::time::Instant::now())
            .expect("the copied destination obligation must retire");
        fixture.backend.platform.wait_idle_bounded();
        fixture.backend.drain_scanout_render_completions_for_tests();
        assert!(
            crate::drm::legacy_sink_entries_for_tests().is_empty(),
            "an Owner copied submit must not enter submit_copied_scanout's legacy primary sink"
        );
        assert!(
            fixture
                .backend
                .device_owner_for_tests(0)
                .live_record()
                .is_some(),
            "the copied Owner offer must reach the Owner commit path"
        );
    }

    fn copied_source_vk_for_sink(
        sink_vk: &crate::kms::vk::device::VkContext,
    ) -> Result<std::sync::Arc<crate::kms::vk::device::VkContext>, std::io::Error> {
        static SHARED_COPIED_SOURCE_VK: std::sync::OnceLock<
            Result<std::sync::Arc<crate::kms::vk::device::VkContext>, String>,
        > = std::sync::OnceLock::new();
        let result = SHARED_COPIED_SOURCE_VK.get_or_init(|| {
            let sink_selector = sink_vk.device_selector();
            let sink_primary = sink_vk
                .selected_drm_identity
                .and_then(|identity| identity.primary)
                .ok_or_else(|| "sink Vulkan context has no primary DRM identity".to_owned())?;
            let source = sink_vk
                .drm_physical_devices
                .iter()
                .find(|device| device.selector != sink_selector)
                .ok_or_else(|| {
                    "no distinct Vulkan renderer is available for copied fixture".to_owned()
                })?;
            let render = source
                .identity
                .render
                .ok_or_else(|| "copied fixture source has no render-node identity".to_owned())?;
            crate::kms::vk::device::VkContext::new_for_render_device(Some(render), sink_primary)
                .map_err(|error| format!("copied fixture source Vulkan context: {error}"))
        });
        result
            .as_ref()
            .map(std::sync::Arc::clone)
            .map_err(|error| std::io::Error::other(error.clone()))
    }

    fn copied_owner_live_fixture() -> Result<OwnerLiveFixture, std::io::Error> {
        copied_owner_live_fixture_inner(false).map(|(fixture, _)| fixture)
    }

    fn copied_owner_live_fixture_inner(use_real_connector: bool) -> CopiedOwnerLiveModeset {
        use std::sync::Arc;

        let mut backend = super::KmsBackend::for_tests_with_vk_live_scene_real_drm()?;
        let sink_vk =
            backend.platform.vk.as_ref().cloned().ok_or_else(|| {
                std::io::Error::other("copied fixture has no sink Vulkan context")
            })?;
        let sink_primary = sink_vk
            .selected_drm_identity
            .and_then(|identity| identity.primary)
            .ok_or_else(|| {
                std::io::Error::other(
                    "copied fixture requires sink_vk.selected_drm_identity.primary",
                )
            })?;
        let source_vk = copied_source_vk_for_sink(&sink_vk)?;

        // `init_root_storage` records its initial fill in the engine's open
        // frame and leaves the platform SubmitGroup holding a fence from the
        // sink VkDevice. Close and drain that frame while the sink context is
        // still installed; otherwise replacing `engine` would leave the
        // sink-owned fence to be submitted on the source queue below.
        backend
            .engine
            .shutdown(&mut backend.store, &mut backend.platform);

        // Release the sink-backed scene graph while the platform still names
        // the sink context. The copied fixture then installs a source-backed
        // renderer below, so later copied-route tasks can actually render A's
        // source rather than merely inspect an adopted pool.
        backend.engine = crate::kms::render::engine::RenderEngine::stub();
        backend.scene = crate::kms::render::scene::SceneCompositor::stub();
        backend.store = crate::kms::render::store::DrawableStore::new();

        // The shared live fixture deliberately uses the placeholder 0:0 key.
        // A copied fixture has a real sink endpoint, so replace that key before
        // constructing the copied route. This is identity bookkeeping only; no
        // modeset or DRM master operation is performed here.
        backend.platform.devices[0].key = sink_primary;
        backend.platform.outputs[0].key.device_key = sink_primary;
        let sink_id = backend
            .platform
            .render_devices
            .iter()
            .find(|device| device.selector == sink_vk.device_selector())
            .map(|device| device.id)
            .ok_or_else(|| {
                std::io::Error::other("copied fixture sink is not in renderer inventory")
            })?;
        backend
            .platform
            .attach_test_vk_context(Arc::clone(&source_vk));
        backend.platform.ops_command_pool = Some(
            crate::kms::vk::ops::OpsCommandPool::new(Arc::clone(&source_vk)).map_err(|error| {
                std::io::Error::other(format!("copied fixture ops pool: {error:?}"))
            })?,
        );
        backend.platform.fence_pool = Some(crate::kms::render::platform::FencePool::new(
            Arc::clone(&source_vk),
        ));
        let source_render_id = source_vk
            .selected_drm_identity
            .and_then(|identity| identity.render)
            .map(crate::kms::scanout_route::RenderDeviceId::DrmRender)
            .unwrap_or(crate::kms::scanout_route::RenderDeviceId::UnverifiedFallback);
        let route = crate::kms::scanout_route::ScanoutRoute::new(
            source_render_id,
            sink_primary,
            crate::kms::scanout_route::RenderKmsRelationship::Different,
        );
        let mut modeset_output = None;
        let mut modeset_target = None;
        if use_real_connector {
            use ::drm::{ClientCapability, Device as _};

            let drm_device = backend
                .platform
                .device_for_key(sink_primary)
                .and_then(|device| device.device.clone_rc())
                .ok_or_else(|| {
                    std::io::Error::new(
                        std::io::ErrorKind::NotConnected,
                        "copied fixture KMS device disappeared or detached",
                    )
                })?;
            for capability in [ClientCapability::UniversalPlanes, ClientCapability::Atomic] {
                let _ = drm_device.set_client_capability(capability, true);
            }
            let candidates = crate::drm::modeset::discover_outputs(&drm_device)?;
            let (connector, picked_target) = candidates
                .iter()
                .find_map(|candidate| {
                    candidate
                        .modes
                        .iter()
                        .find(|mode| {
                            mode.width == candidate.picked.width
                                && mode.height == candidate.picked.height
                                && mode.vrefresh != candidate.picked.vrefresh
                        })
                        .map(|mode| (candidate.connector_name.clone(), mode.clone()))
                })
                .or_else(|| {
                    candidates.iter().find_map(|candidate| {
                        candidate
                            .modes
                            .iter()
                            .find(|mode| {
                                mode.width != candidate.picked.width
                                    || mode.height != candidate.picked.height
                                    || mode.vrefresh != candidate.picked.vrefresh
                            })
                            .map(|mode| (candidate.connector_name.clone(), mode.clone()))
                    })
                })
                .ok_or_else(|| {
                    std::io::Error::other(
                        "copied fixture needs a connected connector with two advertised modes",
                    )
                })?;
            let output =
                crate::drm::modeset::discover_output_for_connector(&drm_device, &connector, &[])?;
            let target = output
                .modes
                .iter()
                .find(|mode| {
                    mode.width == output.picked.width
                        && mode.height == output.picked.height
                        && mode.vrefresh != output.picked.vrefresh
                })
                .cloned()
                .unwrap_or(picked_target);
            modeset_target = Some(yserver_core::backend::ModeSpec {
                width: target.width,
                height: target.height,
                vrefresh: target.vrefresh,
            });
            modeset_output = Some(output);
        }
        if let Some(output) = modeset_output {
            backend.platform.outputs[0] = crate::kms::backend::ActiveOutput::new(
                route,
                output,
                crate::drm::Swapchain::empty_for_tests(),
                0,
                0,
            );
            backend
                .platform
                .rebuild_output_instance_ids_for_tests()
                .map_err(|error| {
                    std::io::Error::other(format!("copied fixture output instance: {error:?}"))
                })?;
            backend.apply_virtual_screen_extent(
                backend.platform.outputs[0].width.max(1),
                backend.platform.outputs[0].height.max(1),
            )?;
        }
        backend.platform.outputs[0].scanout_route = route;
        let destination_route = crate::kms::scanout_route::ScanoutRoute::new(
            sink_id,
            sink_primary,
            crate::kms::scanout_route::RenderKmsRelationship::Same,
        );
        let output = &backend.platform.outputs[0];
        let kms_device = backend
            .platform
            .device_for_key(sink_primary)
            .ok_or_else(|| std::io::Error::other("copied fixture sink KMS device disappeared"))?;
        let drm_device = kms_device.device.clone_rc().ok_or_else(|| {
            std::io::Error::new(
                std::io::ErrorKind::NotConnected,
                "copied fixture sink KMS device detached",
            )
        })?;
        let plans = crate::kms::vk::scanout::CopiedScanoutPool::exact_allocation_plans(
            &source_vk,
            &sink_vk,
            &drm_device,
            u32::from(output.width),
            &output.output.scanout_modifiers,
        );
        if plans.is_empty() {
            return Err(std::io::Error::other(
                "copied fixture has no exact cross-device allocation plan",
            ));
        }
        let mut failures = Vec::new();
        let mut copied_pool = None;
        for plan in plans {
            match crate::kms::vk::scanout::CopiedScanoutPool::allocate_exact(
                Arc::clone(&source_vk),
                Arc::clone(&sink_vk),
                Rc::clone(&drm_device),
                route,
                destination_route,
                u32::from(output.width),
                u32::from(output.height),
                3,
                &output.output.scanout_modifiers,
                plan,
            ) {
                Ok(pool) => {
                    copied_pool = Some(pool);
                    break;
                }
                Err(error) => failures.push(format!("{}: {error}", plan.describe())),
            }
        }
        let copied_pool = copied_pool.ok_or_else(|| {
            std::io::Error::other(format!(
                "every copied fixture allocation plan failed: {}",
                failures.join("; ")
            ))
        })?;
        let bo_count = copied_pool.destinations.bos.len();
        backend.platform.scanout_pools[0] =
            Some(crate::kms::vk::scanout::OutputScanout::Copied(copied_pool));
        backend.platform.bo_generations[0] = vec![Default::default(); bo_count];
        backend.engine = crate::kms::render::engine::RenderEngine::new(&backend.platform)
            .map_err(|error| std::io::Error::other(format!("copied fixture engine: {error:?}")))?;
        backend.scene = crate::kms::render::scene::SceneCompositor::new(&backend.platform)
            .map_err(|error| std::io::Error::other(format!("copied fixture scene: {error:?}")))?;
        backend.store = crate::kms::render::store::DrawableStore::new();
        backend.init_root_storage();
        // The source-backed root fill also opens a frame. Close it here so
        // the fixture reaches tests with no open frame and Drop exercises the
        // normal engine.shutdown/drain path without needing a bypass flag.
        backend
            .engine
            .close_open_frame(
                &mut backend.store,
                &mut backend.platform,
                crate::kms::render::frame_builder::CloseReason::Timeout,
            )
            .map_err(|error| {
                std::io::Error::other(format!("close copied fixture init frame: {error:?}"))
            })?;
        backend.platform.reap_executors_on_drop_for_tests();
        backend.resource_cleanup_on_drop_for_tests = true;
        let fixture =
            finish_owner_live_fixture_with_properties(backend, false, !use_real_connector)?;
        let modeset = modeset_target.map(|mode| {
            (
                sink_primary,
                fixture.backend.platform.outputs[0]
                    .key
                    .connector_name
                    .clone(),
                mode,
            )
        });
        Ok((fixture, modeset))
    }

    fn owner_live_fixture_with_three_outputs() -> Result<OwnerLiveFixture, std::io::Error> {
        owner_live_fixture_with_output_count(3, false)
    }

    fn owner_live_fixture_with_extra_missing_output(
        extra_missing_output: bool,
    ) -> Result<OwnerLiveFixture, std::io::Error> {
        owner_live_fixture_with_output_count(1, extra_missing_output)
    }

    fn owner_live_fixture_with_output_count(
        output_count: usize,
        extra_missing_output: bool,
    ) -> Result<OwnerLiveFixture, std::io::Error> {
        owner_live_fixture_with_selected_identity(output_count, extra_missing_output)
    }

    fn owner_live_fixture_with_selected_identity(
        output_count: usize,
        extra_missing_output: bool,
    ) -> Result<OwnerLiveFixture, std::io::Error> {
        let mut backend = super::KmsBackend::for_tests_with_vk_live_scene_real_drm()?;
        let device = backend
            .platform
            .vk
            .as_ref()
            .and_then(|vk| vk.selected_drm_identity)
            .and_then(|identity| identity.primary)
            .ok_or_else(|| {
                std::io::Error::other(
                    "live Owner fixture requires vk.selected_drm_identity.primary",
                )
            })?;
        backend.platform.devices[0].key = device;
        backend.platform.outputs[0].key.device_key = device;
        let first_output_key = backend.platform.outputs[0].key.clone();
        backend.platform.output_instance_ids[0] = backend
            .platform
            .allocate_output_instance_id(&first_output_key)
            .expect("rekey live fixture output instance");
        backend.platform.reap_executors_on_drop_for_tests();
        backend.resource_cleanup_on_drop_for_tests = true;
        if output_count > 1 {
            let vk =
                backend.platform.vk.as_ref().cloned().ok_or_else(|| {
                    std::io::Error::other("live-scene fixture has no Vulkan context")
                })?;
            for output_idx in 1..output_count {
                backend.platform.append_test_output_with_scanout_pool(
                    std::sync::Arc::clone(&vk),
                    &format!("test-output-{output_idx}"),
                )?;
            }
            let output_width = backend.platform.outputs[0].width;
            for (output_idx, output) in backend.platform.outputs.iter_mut().enumerate() {
                output.x = i32::from(output_width)
                    .saturating_mul(i32::try_from(output_idx).unwrap_or(i32::MAX));
            }
            let fb_w = output_width.saturating_mul(u16::try_from(output_count).unwrap_or(u16::MAX));
            backend.apply_virtual_screen_extent(fb_w, backend.platform.outputs[0].height)?;
            backend
                .scene
                .rebuild_outputs(&backend.platform)
                .map_err(|error| {
                    std::io::Error::other(format!("rebuild multi-output scene: {error:?}"))
                })?;
        } else {
            backend
                .scene
                .rebuild_outputs(&backend.platform)
                .map_err(|error| {
                    std::io::Error::other(format!("rebuild single-output scene: {error:?}"))
                })?;
        }
        finish_owner_live_fixture(backend, extra_missing_output)
    }

    fn finish_owner_live_fixture(
        backend: super::KmsBackend,
        extra_missing_output: bool,
    ) -> Result<OwnerLiveFixture, std::io::Error> {
        finish_owner_live_fixture_with_properties(backend, extra_missing_output, true)
    }

    fn finish_owner_live_fixture_with_properties(
        mut backend: super::KmsBackend,
        extra_missing_output: bool,
        seed_test_properties: bool,
    ) -> Result<OwnerLiveFixture, std::io::Error> {
        use crate::kms::render::resources::{
            DrmCleanupRegistry, ResourceService, tests::MockCleanupIo,
        };
        use std::{cell::RefCell, rc::Rc};

        // This fixture uses the synthetic KMS object ids from the existing
        // scene fixture while its scanout allocations use a real DRM fd.
        // The owner executor is a stub and never issues this description to
        // that fd, so seed the persistent property ids that the production
        // discovery cache would have obtained for a real output.
        if seed_test_properties {
            backend.hotplug_seeded_route_discovery = true;
            for (output_idx, output) in backend.platform.outputs.iter_mut().enumerate() {
                backend
                    .hotplug_route_catalog
                    .insert(output.key.clone(), output.output.clone());
                let crtc = u32::from(output.output.crtc);
                output.output.plane =
                    ::drm::control::from_u32(10 + u32::try_from(output_idx).unwrap_or(u32::MAX))
                        .expect("fixture primary plane");
                output.output.plane_fb_id_prop =
                    ::drm::control::from_u32(19).expect("fixture FB_ID property");
                output.output.plane_crtc_id_prop =
                    ::drm::control::from_u32(20).expect("fixture CRTC_ID property");
                output.output.crtc_out_fence_ptr_prop =
                    Some(::drm::control::from_u32(22).expect("fixture OUT_FENCE_PTR property"));
                backend.platform.devices[0]
                    .active_property_cache
                    .insert_for_tests(crtc, 21);
            }
        }
        let executor = crate::kms::executor::test_support::spawn_stub_helper(
            crate::kms::executor::test_support::StubBehaviour::AcceptProbesThenNeverReply(1000),
        )
        .map_err(|error| std::io::Error::other(format!("stub executor: {error}")))?;
        let (incarnation, lifecycle) = executor.owner_identity();
        let device_key = backend
            .platform
            .primary_device()
            .ok_or_else(|| std::io::Error::other("live-scene fixture has no live KMS device"))?
            .key;
        backend.platform.devices[0].executor = Some(executor);
        backend.platform.devices[0].owner = Some(
            crate::kms::owner::device::DeviceCommitOwner::new(incarnation, lifecycle, 1),
        );
        let helper_lease = backend.platform.devices[0]
            .incarnation_fd_set
            .borrow_mut()
            .register_alias_from(
                backend.platform.devices[0]
                    .device
                    .attached()
                    .expect("live-scene fixture DRM device attached")
                    .as_fd(),
            )?;
        backend.platform.devices[0].helper_lease = Some(helper_lease);
        let device = backend
            .platform
            .device_for_key(device_key)
            .ok_or_else(|| std::io::Error::other("live-scene fixture device disappeared"))?
            .device
            .clone_rc()
            .ok_or_else(|| {
                std::io::Error::new(std::io::ErrorKind::NotConnected, "fixture device detached")
            })?;
        let cleanup_calls = Rc::new(RefCell::new(Vec::new()));
        let cleanup_io = MockCleanupIo::new(Rc::clone(&cleanup_calls));
        let mut registry = DrmCleanupRegistry::new_with_device_and_io(
            Rc::clone(&device),
            device_key,
            incarnation,
            Box::new(cleanup_io.clone()),
        );
        let mut service = ResourceService::new(device_key, incarnation);
        for output_idx in 0..backend.platform.scanout_pools.len() {
            let bo_count = backend.platform.scanout_pools[output_idx]
                .as_ref()
                .map_or(0, |scanout| scanout.display_pool().bos.len());
            for bo_idx in 0..bo_count {
                backend
                    .platform
                    .register_managed_scanout_bo(&mut service, &mut registry, output_idx, bo_idx)
                    .map_err(|error| {
                        std::io::Error::other(format!(
                            "adopt live-scene scanout output {output_idx} bo {bo_idx}: {error:?}"
                        ))
                    })?;
            }
        }
        backend.install_resource_service_with_registry(service, registry);
        if extra_missing_output {
            backend
                .platform
                .append_test_output_without_scanout_pool("test-bad-output");
            return Ok(OwnerLiveFixture {
                backend,
                cleanup_calls,
                cleanup_io,
            });
        }
        let gate =
            crate::kms::render::resources::tests::owner_gate_for_tests(device_key, incarnation);
        backend
            .platform
            .try_install_transport_gate(gate)
            .map_err(|error| std::io::Error::other(error.to_string()))?;
        let source = AdmissionSourceFixture::new_source().0;
        backend.install_admission_conductor_with_backend_composed_for_tests(device_key, source);
        c0_3aii_route_production_clock_probes(&mut backend, device_key);
        Ok(OwnerLiveFixture {
            backend,
            cleanup_calls,
            cleanup_io,
        })
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_conv_cfb_owner_live_fixture_reaps_stub_helper_vulkan() {
        let fixture = owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let helper_pid = fixture.backend.platform.devices[0]
            .executor
            .as_ref()
            .expect("owner executor")
            .child_pid();
        drop(fixture);

        let mut status = 0;
        // A reaped child is no longer waitable by this process.  Before the
        // fixture-owned teardown, KmsIoExecutor::Drop left its killed helper
        // as a zombie, and waitpid returned the child pid here.
        let result = unsafe { libc::waitpid(helper_pid, &mut status, libc::WNOHANG) };
        assert_eq!(
            result, -1,
            "owner fixture left helper {helper_pid} waitable"
        );
        assert_eq!(
            std::io::Error::last_os_error().raw_os_error(),
            Some(libc::ECHILD),
            "waitpid for helper {helper_pid} failed for an unexpected reason"
        );
    }

    fn reinstall_owner_executor_for_direct_test(backend: &mut super::KmsBackend) {
        crate::kms::executor::test_support::kill_and_reap(
            backend.platform.devices[0]
                .executor
                .as_mut()
                .expect("owner executor"),
        );
        backend.platform.devices[0].executor = Some(
            crate::kms::executor::test_support::spawn_stub_helper(
                crate::kms::executor::test_support::StubBehaviour::NeverReply,
            )
            .expect("replacement owner executor"),
        );
    }

    #[test]
    #[ignore = "takes DRM master on the Vulkan primary card and page-flips it; coordinator hardware run only"]
    fn c0_conv_ci_legacy_tick_flips_as_before_drm() {
        let mut fixture = super::KmsBackend::for_tests_with_live_kms()
            .expect("environmental skip: no live Vulkan ICD/DRM master available");
        let backend = &mut fixture.backend;
        backend.scene.mark_scene_structure_dirty();
        backend.tick_maybe_composite_for_tests();
        assert!(
            backend.scene.pending_ack_count_for_tests(0) > 0,
            "the live legacy tick must retain its page-flip acknowledgement"
        );
        assert!(
            backend
                .scene
                .damage_state_for_tests(0)
                .is_some_and(|(_, staged)| staged),
            "the legacy observable is a staged ScanoutDamage frame"
        );
    }

    fn c0_direct_eligibility_candidate(
        backend: &mut super::KmsBackend,
        crtc_id: u32,
        target_xid: u32,
        source_xid: u32,
        border_width: u16,
    ) -> yserver_core::backend::PresentScanoutCandidate {
        use crate::kms::render::store::{DrawableKind, Storage};
        use ash::vk;

        let width = backend.platform.fb_w;
        let height = backend.platform.fb_h;
        // A test that presents several candidates from one window (successive
        // Presents of the same app) reuses the target; seed it once.
        if !backend.windows.contains_key(&target_xid) {
            seed_bordered_window(backend, target_xid, None, 0, 0, width, height, border_width);
        }
        // Upstream #163: an unredirected candidate is direct-eligible only
        // while its top-level is the frontmost mapped window on the root.
        // Project the seeded window the way `sync_top_level_order` would.
        if !backend.core.top_level_order.contains(&target_xid) {
            backend.core.top_level_order.push(target_xid);
        }
        backend
            .store
            .allocate(
                source_xid,
                DrawableKind::Pixmap,
                24,
                false,
                Storage::for_tests_null(
                    vk::Extent2D {
                        width: u32::from(width),
                        height: u32::from(height),
                    },
                    vk::Format::B8G8R8A8_UNORM,
                ),
            )
            .expect("eligibility source");

        bind_test_randr_crtc(backend, 0, crtc_id);
        let crtc_epoch = backend.present_crtc_clock_epoch(crtc_id);
        yserver_core::backend::PresentScanoutCandidate {
            client_id: 1,
            present_id: u64::from(source_xid),
            crtc_id,
            crtc_epoch,
            src_pixmap_xid: source_xid,
            dst_window_xid: target_xid,
            src_host_xid: source_xid,
            paint_dst_host_xid: target_xid,
            completion_dst_host_xid: target_xid,
            src_width: width,
            src_height: height,
            x_off: 0,
            y_off: 0,
            valid_region_xid: 0,
            update_region_xid: 0,
            update_is_full: true,
            explicit_sync: false,
            options: 0,
        }
    }

    fn c0_direct_pure_eligibility(
        backend: &super::KmsBackend,
        candidate: &yserver_core::backend::PresentScanoutCandidate,
    ) -> bool {
        let leaf_id = backend.store.lookup(candidate.paint_dst_host_xid);
        let paint_target = backend.resolve_paint_target(candidate.paint_dst_host_xid);
        let paint_id = paint_target.map(|target| target.backing_id());
        let target = backend.scanout_m0_target(candidate.paint_dst_host_xid, leaf_id, paint_id);
        let root = (
            u32::from(backend.platform.fb_w),
            u32::from(backend.platform.fb_h),
        );
        let root_coverage = leaf_id
            .and_then(|id| backend.window_absolute_rect(id))
            .is_some_and(|rect| {
                rect.offset.x == 0
                    && rect.offset.y == 0
                    && (rect.extent.width, rect.extent.height) == root
                    && (
                        u32::from(candidate.src_width),
                        u32::from(candidate.src_height),
                    ) == root
            });
        super::scanout_direct_eligible(
            backend.scanout_allowed(),
            backend
                .present_crtc_output(candidate.crtc_id)
                .map(|(_, crtc)| backend.device_outputs_powered_on(crtc.device_key))
                .unwrap_or_else(|| backend.kms_outputs_active),
            matches!(
                backend.scene.cursor_mode(),
                crate::kms::render::scene::CursorPlaneMode::Hw
            ),
            backend.scene.root_overlay.is_empty(),
            super::scanout_m2_is_authoritative_root(target, root_coverage),
            paint_target.is_none_or(|target| !target.has_border_clip()),
            candidate.x_off,
            candidate.y_off,
            candidate.valid_region_xid,
        )
    }

    #[test]
    fn c0_conv_cii_eligibility_combination_rule() {
        let mut backend = super::KmsBackend::for_tests();
        let device = backend.platform.primary_device().expect("device").key;
        install_admission_owner_gate(&mut backend, device);
        let (source, _, _) = AdmissionSourceFixture::new();
        backend.install_admission_conductor_for_tests(device, source);
        assert_eq!(
            backend.admission_note_layout_change(device),
            crate::kms::render::admission::AdmissionOutcome::NothingAdmissible
        );

        let current_generation = backend.admission_conductors[&device].layout_generation;
        let gate_cases = [
            (
                "all-gates",
                true,
                true,
                true,
                true,
                true,
                true,
                true,
                0,
                0,
                0,
            ),
            ("vt", true, false, true, true, true, true, true, 0, 0, 0),
            (
                "outputs", true, true, false, true, true, true, true, 0, 0, 0,
            ),
            ("cursor", true, true, true, false, true, true, true, 0, 0, 0),
            (
                "overlay", true, true, true, true, false, true, true, 0, 0, 0,
            ),
            ("root", true, true, true, true, true, false, true, 0, 0, 0),
            ("border", true, true, true, true, true, true, true, 1, 0, 0),
            // The pure scanout core accepts this row; only the CRTC-domain
            // predicate refuses it.
            (
                "crtc-domain",
                false,
                true,
                true,
                true,
                true,
                true,
                true,
                0,
                0,
                0,
            ),
        ];
        for (
            name,
            direct_crtc_eligible,
            scanout_allowed,
            kms_outputs_active,
            cursor_hw,
            root_overlay_empty,
            authoritative_root,
            unbordered,
            x_off,
            y_off,
            valid_region_xid,
        ) in gate_cases
        {
            let pure = super::scanout_direct_eligible(
                scanout_allowed,
                kms_outputs_active,
                cursor_hw,
                root_overlay_empty,
                authoritative_root,
                unbordered,
                x_off,
                y_off,
                valid_region_xid,
            );
            let result = super::direct_present_eligibility_decision(
                direct_crtc_eligible,
                scanout_allowed,
                kms_outputs_active,
                cursor_hw,
                root_overlay_empty,
                authoritative_root,
                unbordered,
                x_off,
                y_off,
                valid_region_xid,
                current_generation,
            );
            assert_eq!(result.eligible, direct_crtc_eligible && pure, "{name}");
            assert_eq!(result.layout_generation, current_generation, "{name}");
        }

        assert_eq!(
            super::direct_present_eligibility_decision(
                true,
                true,
                true,
                true,
                true,
                true,
                true,
                0,
                0,
                0,
                current_generation,
            )
            .layout_generation,
            current_generation
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_conv_cii_eligibility_is_one_predicate() {
        let mut fixture = owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let backend = &mut fixture.backend;
        backend
            .scene
            .test_set_cursor_mode(crate::kms::render::scene::CursorPlaneMode::Hw);
        let device = backend.platform.primary_device().expect("device").key;
        c0_conv_ciii_establish_composed_return(backend, device);

        // Seed the bordered window first: upstream #163 keeps only the
        // frontmost mapped top-level direct-eligible, and the unbordered
        // candidate is the one that must stay eligible here.
        let bordered = c0_direct_eligibility_candidate(backend, 0xC311, 0xC314, 0xC315, 1);
        let unbordered = c0_direct_eligibility_candidate(backend, 0xC311, 0xC312, 0xC313, 0);

        assert!(
            c0_direct_pure_eligibility(backend, &unbordered),
            "the baseline candidate must pass the pure scanout gates"
        );
        assert!(
            backend.direct_present_crtc_eligible(unbordered.crtc_id, unbordered.crtc_epoch),
            "the baseline candidate must pass the gathered CRTC gate"
        );
        assert!(
            backend.direct_present_eligibility(unbordered).eligible,
            "the baseline candidate must be eligible through the production predicate"
        );

        let bordered_result = backend.direct_present_eligibility(bordered);
        assert!(
            bordered_result
                .paint_target
                .is_some_and(|target| target.has_border_clip()),
            "the border case must reach the production border input"
        );
        assert!(
            backend.direct_present_crtc_eligible(bordered.crtc_id, bordered.crtc_epoch),
            "the border case must be ineligible only through its border clip"
        );
        assert!(
            !bordered_result.eligible,
            "the production predicate must reject the bordered candidate"
        );

        let stale = yserver_core::backend::PresentScanoutCandidate {
            crtc_epoch: unbordered.crtc_epoch.saturating_sub(1),
            ..unbordered
        };
        assert!(
            c0_direct_pure_eligibility(backend, &stale),
            "the stale candidate must pass every pure scanout gate"
        );
        assert!(
            !backend.direct_present_crtc_eligible(stale.crtc_id, stale.crtc_epoch),
            "the stale candidate must fail the gathered CRTC gate"
        );
        assert!(
            !backend.direct_present_eligibility(stale).eligible,
            "the production predicate must reject the stale CRTC candidate"
        );

        let unknown = yserver_core::backend::PresentScanoutCandidate {
            crtc_id: 0xC3FF,
            ..unbordered
        };
        assert!(c0_direct_pure_eligibility(backend, &unknown));
        assert!(!backend.direct_present_crtc_eligible(unknown.crtc_id, unknown.crtc_epoch));
        assert!(!backend.direct_present_eligibility(unknown).eligible);
    }

    #[test]
    fn c0_conv_ciii_add_entry_refused_without_a_composed_return() {
        let mut backend = super::KmsBackend::for_tests();
        backend
            .scene
            .test_set_cursor_mode(crate::kms::render::scene::CursorPlaneMode::Hw);
        let device = backend.platform.primary_device().expect("device").key;
        install_admission_owner_gate(&mut backend, device);
        backend
            .install_admission_conductor_for_tests(device, AdmissionSourceFixture::new_source().0);
        let candidate = c0_direct_eligibility_candidate(&mut backend, 0xCA11, 0xCA12, 0xCA13, 0);

        assert!(c0_direct_pure_eligibility(&backend, &candidate));
        assert!(backend.direct_present_crtc_eligible(candidate.crtc_id, candidate.crtc_epoch));
        assert!(!backend.composed_return_established(device));
        let eligibility = backend.direct_present_eligibility(candidate);
        assert!(
            !eligibility.eligible,
            "an Owner entry candidate without a composed return must be refused"
        );
        assert!(backend.scanout_m2.pending.is_none());
        assert!(backend.scanout_m2.queued_successor.is_none());
        assert!(backend.scanout_m2.queued_successor_role.is_none());
    }

    #[test]
    fn c0_conv_ciii_add_legacy_eligibility_unchanged() {
        let mut backend = super::KmsBackend::for_tests();
        backend
            .scene
            .test_set_cursor_mode(crate::kms::render::scene::CursorPlaneMode::Hw);
        let candidate = c0_direct_eligibility_candidate(&mut backend, 0xCA21, 0xCA22, 0xCA23, 0);
        assert!(backend.admission_conductors.is_empty());

        backend.composed_return_test_override = Some(true);
        let with_return = backend.direct_present_eligibility(candidate).eligible;
        backend.composed_return_test_override = Some(false);
        let without_return = backend.direct_present_eligibility(candidate).eligible;
        backend.composed_return_test_override = None;

        assert!(with_return);
        assert_eq!(
            without_return, with_return,
            "Legacy direct eligibility must not consult Owner composed-return state"
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_conv_cii_eligibility_matches_legacy_vulkan() {
        let OwnerLiveFixture { mut backend, .. } =
            owner_live_fixture().expect("environmental skip: no live Vulkan ICD available");
        backend
            .scene
            .test_set_cursor_mode(crate::kms::render::scene::CursorPlaneMode::Hw);
        let device = backend.platform.primary_device().expect("device").key;
        c0_conv_ciii_establish_composed_return(&mut backend, device);
        // Bordered first: only the frontmost top-level stays eligible (#163).
        let owner_bordered =
            c0_direct_eligibility_candidate(&mut backend, 0xC401, 0xC404, 0xC405, 1);
        let owner_candidate =
            c0_direct_eligibility_candidate(&mut backend, 0xC401, 0xC402, 0xC403, 0);
        let owner_stale = yserver_core::backend::PresentScanoutCandidate {
            crtc_epoch: owner_candidate.crtc_epoch.saturating_sub(1),
            ..owner_candidate
        };
        assert!(c0_direct_pure_eligibility(&backend, &owner_candidate));
        assert!(c0_direct_pure_eligibility(&backend, &owner_stale));
        assert!(
            backend
                .direct_present_crtc_eligible(owner_candidate.crtc_id, owner_candidate.crtc_epoch)
        );
        assert!(
            backend.direct_present_crtc_eligible(owner_bordered.crtc_id, owner_bordered.crtc_epoch)
        );
        let owner_answers = [
            backend.direct_present_eligibility(owner_candidate).eligible,
            backend.direct_present_eligibility(owner_bordered).eligible,
            backend.direct_present_eligibility(owner_stale).eligible,
        ];
        assert_eq!(owner_answers, [true, false, false]);

        install_admission_legacy_gate(&mut backend, device);
        let legacy_candidate = owner_candidate;
        let legacy_answers = [
            backend
                .direct_present_eligibility(legacy_candidate)
                .eligible,
            backend.direct_present_eligibility(owner_bordered).eligible,
            backend
                .direct_present_eligibility(yserver_core::backend::PresentScanoutCandidate {
                    crtc_epoch: legacy_candidate.crtc_epoch.saturating_sub(1),
                    ..legacy_candidate
                })
                .eligible,
        ];
        assert_eq!(owner_answers, legacy_answers);
        assert_eq!(legacy_answers, [true, false, false]);
        assert!(super::scanout_direct_eligible(
            true, true, true, true, true, true, 0, 0, 0
        ));
        assert!(
            !super::direct_present_eligibility_decision(
                false, true, true, true, true, true, true, 0, 0, 0, 0
            )
            .eligible
        );
        assert!(!legacy_answers[2], "the stale CRTC must stay ineligible");
    }

    fn c0_conv_cii_generation(backend: &super::KmsBackend, device: DrmDeviceKey) -> u64 {
        backend.admission_conductors[&device].layout_generation
    }

    fn c0_conv_cii_assert_generation_bumped(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        site: &str,
        mutation: impl FnOnce(&mut super::KmsBackend),
    ) {
        let before = c0_conv_cii_generation(backend, device);
        mutation(backend);
        let after = c0_conv_cii_generation(backend, device);
        assert_eq!(
            after,
            before + 1,
            "{site} must advance the admission layout generation exactly once"
        );
    }

