    fn complete_owner_commit_and_reinstall(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        commit: crate::kms::owner::identity::CommitId,
    ) {
        backend.route_owner_event_batch(
            device,
            vec![
                crate::kms::owner::device::OwnerEvent::Accepted { commit },
                crate::kms::owner::device::OwnerEvent::HardwareComplete { commit },
            ],
            std::time::Instant::now(),
        );
        let completion = backend.complete_owner_for_tests(0);
        backend.route_owner_event_batch(device, completion, std::time::Instant::now());
        crate::kms::executor::test_support::kill_and_reap(
            backend.platform.devices[0]
                .executor
                .as_mut()
                .expect("owner executor"),
        );
        backend.platform.devices[0].executor = Some(
            crate::kms::executor::test_support::spawn_stub_helper(
                crate::kms::executor::test_support::StubBehaviour::NeverReply,
            )
            .expect("replacement owner executor"),
        );
        backend.install_admission_conductor_with_backend_composed_for_tests(
            device,
            AdmissionSourceFixture::new_source().0,
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_conv_ci_two_outputs_permuted_completions_vulkan() {
        let run_separate_order = |first_output: usize, second_output: usize| {
            let (
                OwnerLiveFixture { mut backend, .. },
                _state,
                output_zero_window,
                output_one_window,
            ) = owner_live_two_output_windows();
            let windows = [output_zero_window, output_one_window];
            let device = backend.platform.primary_device().expect("device").key;

            // First prove the same two outputs arrive bundled with the third
            // ready CRTC; all milestones are then routed through the owner
            // entry before the separate-order phase begins.
            backend.scene.mark_scene_structure_dirty();
            backend.tick_maybe_composite_for_tests_without_render_completion_drain();
            backend.platform.wait_idle_bounded();
            backend.drain_scanout_render_completions_for_tests();
            let initial = backend
                .device_owner_for_tests(0)
                .live_record()
                .expect("initial owner bundle")
                .commit_id();
            assert_eq!(
                backend
                    .device_owner_for_tests(0)
                    .live_record()
                    .expect("initial owner bundle")
                    .closure()
                    .expected_completion()
                    .len(),
                3,
                "the initial ready outputs share one transaction"
            );
            complete_owner_commit_and_reinstall(&mut backend, device, initial);

            for (position, output_idx) in [first_output, second_output].into_iter().enumerate() {
                backend
                    .fill_rectangle(
                        None,
                        windows[output_idx].as_raw(),
                        0x0000_70ff + u32::try_from(position).expect("position") * 0x100,
                        1,
                        1,
                        30,
                        30,
                    )
                    .expect("paint separately scheduled output");
                backend.tick_maybe_composite_for_tests_without_render_completion_drain();
                backend.platform.wait_idle_bounded();
                backend.drain_scanout_render_completions_for_tests();
                let record = backend
                    .device_owner_for_tests(0)
                    .live_record()
                    .expect("separately scheduled owner commit");
                let commit = record.commit_id();
                assert_eq!(
                    record.closure().expected_completion(),
                    &[u32::from(backend.platform.outputs[output_idx].output.crtc)],
                    "separate admission contains only output {output_idx}"
                );
                complete_owner_commit_and_reinstall(&mut backend, device, commit);
                assert_eq!(
                    backend.scene.owner_damage_transaction_count_for_tests(),
                    0,
                    "output {output_idx} completion applies and closes its transaction"
                );
            }
        };

        // Run both permutations on fresh real-GPU fixtures so no completion
        // order is accidentally made valid by the prior output's state.
        run_separate_order(1, 0);
        run_separate_order(0, 1);
    }

    fn install_admission_resource_service(backend: &mut super::KmsBackend) {
        let device = backend.platform.primary_device().unwrap().key;
        let incarnation = backend
            .platform
            .owner_ref(device)
            .expect("fixture owner")
            .incarnation();
        backend.install_resource_service(crate::kms::render::resources::ResourceService::new(
            device,
            incarnation,
        ));
    }

    fn install_admission_legacy_gate(backend: &mut super::KmsBackend, device: DrmDeviceKey) {
        let incarnation = backend
            .platform
            .owner_ref(device)
            .expect("fixture owner")
            .incarnation();
        let gate = crate::kms::render::resources::TransportGate::new_legacy(
            device,
            incarnation,
            Box::new(backend.direct_ownership_handle()),
        );
        backend.platform.install_transport_gate(gate);
    }

    fn admission_backend_with_stub_executor() -> super::KmsBackend {
        let mut backend = super::KmsBackend::for_tests();
        seed_direct_owner_description_properties_for_tests(&mut backend);
        let executor = crate::kms::executor::test_support::spawn_stub_helper(
            crate::kms::executor::test_support::StubBehaviour::NeverReply,
        )
        .expect("spawn stub executor");
        let (incarnation, lifecycle) = executor.owner_identity();
        backend.platform.devices[0].executor = Some(executor);
        backend.platform.devices[0].owner = Some(
            crate::kms::owner::device::DeviceCommitOwner::new(incarnation, lifecycle, 1),
        );
        let device = backend.platform.primary_device().unwrap().key;
        backend.install_resource_service(crate::kms::render::resources::ResourceService::new(
            device,
            incarnation,
        ));
        c0_conv_cii_prepare_owner_clock(
            &mut backend,
            device,
            0,
            yserver_core::backend::PresentClockSample {
                msc: 900,
                ust: 90_000,
                source: yserver_core::backend::PresentClockSource::IdleSequence,
            },
        );
        backend
    }

    fn c0_3aii_route_production_clock_probes(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
    ) {
        use crate::kms::owner::clock::{ClockSource, ProbeState};

        let served_crtcs = backend
            .platform
            .outputs
            .iter()
            .filter(|output| output.key.device_key == device)
            .map(|output| u32::from(CrtcKey::for_output(output).crtc))
            .collect::<std::collections::BTreeSet<_>>();
        for _ in &served_crtcs {
            wait_lifecycle_executor_readable(backend, device);
            let events = backend.platform.drain_executor_events();
            assert_eq!(events.len(), 1, "one production clock-probe reply");
            backend.record_host_call_events(events);
        }
        let owner = backend.platform.owner_ref(device).expect("Owner");
        for crtc in served_crtcs {
            let key = owner
                .clock_key_for_hardware_crtc(crtc)
                .expect("production activation installed the served CRTC clock");
            let clock = owner.clock(key).expect("production clock record");
            assert_eq!(clock.source, ClockSource::KernelSequence);
            assert_eq!(clock.probe, ProbeState::Succeeded);
            assert_eq!(clock.reference, Some(1000));
        }
    }

    fn lifecycle_dpms_backend(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
    ) -> (super::KmsBackend, DrmDeviceKey) {
        lifecycle_dpms_backend_with_output_count(behaviour, 1)
    }

    fn lifecycle_dpms_backend_with_output_count(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
        output_count: usize,
    ) -> (super::KmsBackend, DrmDeviceKey) {
        let mut backend = super::KmsBackend::for_tests();
        for index in 1..output_count {
            push_test_output(
                &mut backend,
                u32::try_from(index + 1).expect("test CRTC id"),
            );
        }
        seed_direct_owner_description_properties_for_tests(&mut backend);
        let probe_executor = crate::kms::executor::test_support::spawn_stub_helper(
            crate::kms::executor::test_support::StubBehaviour::AcceptProbesThenNeverReply(1000),
        )
        .expect("spawn lifecycle probe executor");
        let (incarnation, lifecycle) = probe_executor.owner_identity();
        let device = backend
            .platform
            .primary_device()
            .expect("fixture device")
            .key;
        let render_id = RenderDeviceId::DrmRender(test_device_key(128));
        backend.platform.render_devices = vec![test_render_device(render_id, Some(device))];
        backend.platform.selected_render_device = Some(render_id);
        backend.platform.devices[0].executor = Some(probe_executor);
        backend.platform.devices[0].owner = Some(
            crate::kms::owner::device::DeviceCommitOwner::new(incarnation, lifecycle, 1),
        );
        backend.install_resource_service(crate::kms::render::resources::ResourceService::new(
            device,
            incarnation,
        ));
        install_admission_owner_gate(&mut backend, device);
        backend.install_admission_conductor_with_backend_composed_for_tests(
            device,
            AdmissionSourceFixture::new_source().0,
        );
        c0_3aii_route_production_clock_probes(&mut backend, device);
        crate::kms::executor::test_support::kill_and_reap(
            backend.platform.devices[0].executor.as_mut().unwrap(),
        );
        backend.platform.devices[0].executor = Some(
            crate::kms::executor::test_support::spawn_stub_helper(behaviour)
                .expect("spawn lifecycle stub executor"),
        );
        (backend, device)
    }

    fn lifecycle_mixed_dpms_backend(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
    ) -> (super::KmsBackend, DrmDeviceKey, DrmDeviceKey) {
        let mut backend = super::KmsBackend::for_tests();
        let legacy_device = backend
            .platform
            .primary_device()
            .expect("fixture Legacy device")
            .key;
        let owner_device = test_device_key(91);
        push_test_device(&mut backend, owner_device);
        c0_conv_ciii_id_push_output_for_device(&mut backend, owner_device, 91, "owner-test");
        seed_direct_owner_description_properties_for_tests(&mut backend);

        let probe_executor = crate::kms::executor::test_support::spawn_stub_helper(
            crate::kms::executor::test_support::StubBehaviour::AcceptProbesThenNeverReply(1000),
        )
        .expect("spawn mixed-server Owner probe executor");
        let (incarnation, lifecycle) = probe_executor.owner_identity();
        let owner = backend
            .platform
            .devices
            .iter_mut()
            .find(|entry| entry.key == owner_device)
            .expect("mixed Owner device");
        owner.executor = Some(probe_executor);
        owner.owner = Some(crate::kms::owner::device::DeviceCommitOwner::new(
            incarnation,
            lifecycle,
            1,
        ));
        install_admission_owner_gate(&mut backend, owner_device);
        backend.install_resource_service(crate::kms::render::resources::ResourceService::new(
            owner_device,
            incarnation,
        ));
        backend.install_admission_conductor_with_backend_composed_for_tests(
            owner_device,
            AdmissionSourceFixture::new_source().0,
        );
        c0_3aii_route_production_clock_probes(&mut backend, owner_device);
        crate::kms::executor::test_support::kill_and_reap(
            backend
                .platform
                .devices
                .iter_mut()
                .find(|entry| entry.key == owner_device)
                .and_then(|entry| entry.executor.as_mut())
                .unwrap(),
        );
        let executor = crate::kms::executor::test_support::spawn_stub_helper(behaviour)
            .expect("spawn mixed-server Owner executor");
        backend
            .platform
            .devices
            .iter_mut()
            .find(|entry| entry.key == owner_device)
            .expect("mixed Owner device")
            .executor = Some(executor);
        (backend, legacy_device, owner_device)
    }

    fn wait_lifecycle_executor_readable(backend: &super::KmsBackend, device: DrmDeviceKey) {
        use std::os::fd::AsFd;

        let fd = backend
            .platform
            .devices
            .iter()
            .find(|entry| entry.key == device)
            .and_then(|entry| entry.executor.as_ref())
            .and_then(|executor| executor.control_fd())
            .expect("Owner executor control fd");
        crate::kms::executor::test_support::wait_readable(
            fd.as_fd(),
            std::time::Duration::from_secs(5),
        );
    }

    fn c0_2b_owner_fixture(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
        output_count: usize,
        legacy: bool,
        install_conductor: bool,
    ) -> (super::KmsBackend, DrmDeviceKey) {
        let mut backend = super::KmsBackend::for_tests();
        for index in 1..output_count {
            push_test_output(
                &mut backend,
                100 + u32::try_from(index).expect("fixture output index"),
            );
        }
        let executor = crate::kms::executor::test_support::spawn_stub_helper(behaviour)
            .expect("spawn 2b stub executor");
        let (incarnation, lifecycle) = executor.owner_identity();
        let device = backend
            .platform
            .primary_device()
            .expect("fixture device")
            .key;
        backend.platform.devices[0].executor = Some(executor);
        backend.platform.devices[0].owner = Some(if legacy {
            crate::kms::owner::device::DeviceCommitOwner::new_legacy(incarnation, lifecycle, 1)
        } else {
            crate::kms::owner::device::DeviceCommitOwner::new(incarnation, lifecycle, 1)
        });
        backend.install_resource_service(crate::kms::render::resources::ResourceService::new(
            device,
            incarnation,
        ));
        if !legacy {
            install_admission_owner_gate(&mut backend, device);
        }
        if install_conductor {
            backend.install_admission_conductor_for_tests(
                device,
                AdmissionSourceFixture::new_source().0,
            );
        }
        (backend, device)
    }

