    #[test]
    fn c0_3aii_dpms_off_on_a_mixed_server_does_not_exit() {
        use crate::kms::executor::test_support::StubBehaviour;

        let (mut backend, legacy_device, owner_device) =
            lifecycle_mixed_dpms_backend(StubBehaviour::NeverReply);
        let legacy_output = backend.platform.outputs[0].key.clone();
        let owner_output = backend.platform.outputs[1].key.clone();
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());

        Backend::set_dpms_power(&mut backend, 3).expect("mixed-server DPMS off");
        let off = backend
            .lifecycle_drivers
            .get(&owner_device)
            .expect("Owner lifecycle driver")
            .pending_topology_descriptions_for_tests();
        assert!(
            off.iter().any(|description| {
                description.objects.len() == 1
                    && description.objects[0].object
                        == u32::from(backend.platform.outputs[1].output.crtc)
                    && description.objects[0].props == vec![(description.property_ids.active, 0)]
            }),
            "the Owner off transition is one atomic ACTIVE-only topology"
        );
        Backend::set_dpms_power(&mut backend, 0).expect("mixed-server DPMS on");

        assert_eq!(legacy_output.device_key, legacy_device);
        assert_eq!(owner_output.device_key, owner_device);
        assert_eq!(
            backend.platform.dpms_output_calls_for_tests,
            Some(vec![
                (false, vec![legacy_output.clone()]),
                (true, vec![legacy_output.clone()])
            ]),
            "the Legacy transport sees its output on both transitions only"
        );
        let coordinator = &backend.lifecycle_coordinator;
        assert_eq!(coordinator.protocol_dpms_level(), 0);
        assert_eq!(coordinator.dpms_epoch(), 2);
        let projection = coordinator
            .device(&owner_device)
            .and_then(|device| device.desired().dpms_targets().get(&owner_output))
            .expect("Owner output remains in the protocol domain");
        assert_eq!(projection.level, 0);
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_dpms_off_on_a_mixed_server_does_not_exit",
            &c0_3bi_expected_end_state([legacy_output.clone(), owner_output.clone()]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3aii_legacy_off_leaves_owner_scanout_state_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;

        let mut backend = super::KmsBackend::for_tests_with_vk()
            .expect("environmental skip: no live Vulkan ICD available");
        let legacy_device = backend.platform.primary_device().unwrap().key;
        let owner_device = test_device_key(91);
        push_test_device(&mut backend, owner_device);
        c0_conv_ciii_id_push_output_for_device(&mut backend, owner_device, 91, "owner-test");
        let owner_output_idx = 1;
        let vk = backend.platform.vk().expect("live test Vulkan").clone();
        let drm = backend
            .platform
            .device_for_key(owner_device)
            .expect("Owner KMS device")
            .device
            .clone_rc()
            .expect("Owner test DRM device attached");
        let mut owner_bo = crate::kms::vk::scanout::ScanoutBo::for_tests(drm, vk);
        owner_bo.state.transition_to_recording();
        owner_bo.state.transition_to_submitted(-1);
        let _ = owner_bo.state.transition_to_pending(-1);
        let mut owner_pool = crate::kms::vk::scanout::ScanoutBoPool::for_tests();
        owner_pool.bos.push(owner_bo);
        backend.platform.scanout_pools[owner_output_idx] =
            Some(crate::kms::vk::scanout::OutputScanout::Shared(owner_pool));
        backend.platform.bo_generations[owner_output_idx] = vec![
            crate::kms::render::platform::BoGenerationEntry {
                last_present_generation: Some(73),
                content_invalidated: false,
            };
            1
        ];
        backend.scene = crate::kms::render::scene::SceneCompositor::new(&backend.platform)
            .expect("build two-output test scene");
        assert!(
            backend
                .scene
                .hold_pending_ack_for_tests(owner_output_idx, 0)
        );
        let owner_pool_before = backend.platform.bo_generations[owner_output_idx]
            .iter()
            .map(|entry| (entry.last_present_generation, entry.content_invalidated))
            .collect::<Vec<_>>();
        let owner_bo_phase_before = backend.platform.scanout_pools[owner_output_idx]
            .as_ref()
            .expect("Owner scanout pool")
            .display_pool()
            .bos[0]
            .state
            .phase;
        assert_eq!(
            owner_bo_phase_before,
            crate::kms::vk::scanout::BoPhase::Pending
        );
        let owner_scene_before = (
            backend
                .scene
                .scanout_damage_signature_for_tests(owner_output_idx),
            backend
                .scene
                .scene_structure_damage_for_tests(owner_output_idx),
        );

        let executor =
            crate::kms::executor::test_support::spawn_stub_helper(StubBehaviour::NeverReply)
                .expect("spawn Owner executor");
        let (incarnation, lifecycle) = executor.owner_identity();
        let owner = backend
            .platform
            .devices
            .iter_mut()
            .find(|entry| entry.key == owner_device)
            .expect("Owner device");
        owner.executor = Some(executor);
        owner.owner = Some(crate::kms::owner::device::DeviceCommitOwner::new(
            incarnation,
            lifecycle,
            1,
        ));
        install_admission_owner_gate(&mut backend, owner_device);
        backend.install_resource_service(crate::kms::render::resources::ResourceService::new(
            owner_device,
            incarnation,
        ));
        c0_conv_cii_install_owner_clock(&mut backend, owner_device, owner_output_idx, 1000);
        seed_direct_owner_description_properties_for_tests(&mut backend);
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());

        Backend::set_dpms_power(&mut backend, 3).expect("Legacy-only DPMS off path");

        assert_eq!(backend.platform.bo_generations[owner_output_idx].len(), 1);
        assert_eq!(
            backend.platform.bo_generations[owner_output_idx]
                .iter()
                .map(|entry| (entry.last_present_generation, entry.content_invalidated))
                .collect::<Vec<_>>(),
            owner_pool_before,
            "Legacy suspend reset must leave Owner scanout BO generations unchanged"
        );
        assert_eq!(
            backend.platform.scanout_pools[owner_output_idx]
                .as_ref()
                .expect("Owner scanout pool remains installed")
                .display_pool()
                .bos[0]
                .state
                .phase,
            owner_bo_phase_before,
            "Legacy suspend reset must leave the Owner scanout BO in Pending"
        );
        assert_eq!(
            (
                backend
                    .scene
                    .scanout_damage_signature_for_tests(owner_output_idx),
                backend
                    .scene
                    .scene_structure_damage_for_tests(owner_output_idx),
            ),
            owner_scene_before,
            "Legacy scene drain must leave Owner per-output damage state unchanged"
        );
        assert_eq!(backend.platform.outputs[0].key.device_key, legacy_device);
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_legacy_off_leaves_owner_scanout_state_vulkan",
            &c0_3bi_expected_end_state([
                OutputKey::new(legacy_device, "test"),
                OutputKey::new(owner_device, "owner-test"),
            ]),
        );
    }

    #[test]
    fn c0_3aii_new_output_inherits_the_global_off() {
        use crate::kms::executor::test_support::StubBehaviour;

        let (mut backend, device) = lifecycle_dpms_backend(StubBehaviour::NeverReply);
        Backend::set_dpms_power(&mut backend, 3).expect("global DPMS off");
        let epoch = backend.lifecycle_coordinator.dpms_epoch();

        push_test_output(&mut backend, 93);
        let new_output = backend.platform.outputs[1].key.clone();
        backend.lifecycle_begin_owner_event_batch(device);
        let projection = backend
            .lifecycle_coordinator
            .device(&device)
            .and_then(|arbiter| arbiter.desired().dpms_targets().get(&new_output))
            .copied()
            .expect("production registration projected the new output");
        backend.lifecycle_end_owner_event_batch(device);

        assert_eq!(projection.level, 3);
        assert_eq!(projection.epoch, Some(epoch));
        let pending = backend
            .lifecycle_drivers
            .get(&device)
            .expect("Owner lifecycle driver")
            .pending_topology_descriptions_for_tests();
        assert!(
            pending.iter().all(|description| {
                !description.objects.iter().any(|object| {
                    object.object == u32::from(backend.platform.outputs[1].output.crtc)
                        && object.props.iter().any(|(property, value)| {
                            *property == description.property_ids.active && *value == 1
                        })
                })
            }),
            "no pending topology may install the newly joined output active"
        );
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_new_output_inherits_the_global_off",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test"), new_output.clone()]),
        );
    }

    #[test]
    fn c0_3aii_legacy_off_keeps_owner_vblank_arms() {
        use crate::kms::executor::test_support::StubBehaviour;

        let (mut backend, _, owner_device) =
            lifecycle_mixed_dpms_backend(StubBehaviour::NeverReply);
        let legacy_crtc = output_crtc_key(&backend, 0);
        let owner_crtc = output_crtc_key(&backend, 1);
        let owner_token = backend.ids.next_sequence_arm();
        let legacy_token = backend.ids.next_sequence_arm();
        backend.armed_vblank_targets.insert(legacy_crtc, 0);
        backend.armed_vblank_targets.insert(owner_crtc, 0);
        backend
            .absolute_vblank_targets
            .insert(legacy_crtc, [10].into_iter().collect());
        backend
            .absolute_vblank_targets
            .insert(owner_crtc, [11].into_iter().collect());
        for (device, token, key) in [
            (legacy_crtc.device_key, legacy_token, legacy_crtc),
            (owner_device, owner_token, owner_crtc),
        ] {
            backend.sequence_arms.insert_for_device(
                device,
                SequenceArm {
                    token,
                    crtc_id: u32::from(key.crtc),
                    epoch: ClockEpochId::first(),
                    purpose: SequenceArmPurpose::Relative,
                    target: 0,
                },
            );
        }
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());

        Backend::set_dpms_power(&mut backend, 3).expect("mixed-server DPMS off");

        assert!(!backend.armed_vblank_targets.contains_key(&legacy_crtc));
        assert!(backend.armed_vblank_targets.contains_key(&owner_crtc));
        assert!(!backend.absolute_vblank_targets.contains_key(&legacy_crtc));
        assert!(backend.absolute_vblank_targets.contains_key(&owner_crtc));
        assert!(!backend.sequence_arms.live.contains_key(&legacy_token));
        assert!(backend.sequence_arms.live.contains_key(&owner_token));
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_legacy_off_keeps_owner_vblank_arms",
            &c0_3bi_expected_end_state([
                OutputKey::new(backend.platform.devices[0].key, "test"),
                OutputKey::new(owner_device, "owner-test"),
            ]),
        );
    }

    #[test]
    fn c0_3aii_resource_clock_runs_while_any_output_lit() {
        use crate::kms::{
            executor::test_support::{ScriptedReply, StubBehaviour},
            render::resources::CoreRetirementBatch,
        };

        let (mut rejected, _, owner_device) =
            lifecycle_mixed_dpms_backend(StubBehaviour::RejectWith(libc::EINVAL));
        rejected.platform.dpms_output_calls_for_tests = Some(Vec::new());
        rejected
            .resource_service
            .as_mut()
            .expect("resource service")
            .register_batch(CoreRetirementBatch::new(Vec::new(), Vec::new(), false));
        Backend::set_dpms_power(&mut rejected, 3).expect("Legacy off and Owner request");
        wait_lifecycle_executor_readable(&rejected, owner_device);
        Backend::on_executor_readable(&mut rejected, &mut ServerState::new());
        let service = rejected.resource_service().expect("resource service");
        assert_eq!(service.pending_batches().len(), 1);
        assert!(
            service.seat_active_for_tests(),
            "rejected Owner off stays lit"
        );

        let (mut applied, _, applied_owner) =
            lifecycle_mixed_dpms_backend(StubBehaviour::Scripted(ScriptedReply::Accepted {
                mask: 0,
                fds: 0,
            }));
        applied.platform.dpms_output_calls_for_tests = Some(Vec::new());
        applied
            .resource_service
            .as_mut()
            .expect("resource service")
            .register_batch(CoreRetirementBatch::new(Vec::new(), Vec::new(), false));
        Backend::set_dpms_power(&mut applied, 3).expect("mixed-server DPMS off");
        wait_lifecycle_executor_readable(&applied, applied_owner);
        Backend::on_executor_readable(&mut applied, &mut ServerState::new());
        let commit = applied
            .device_owner_for_tests(1)
            .live_record()
            .expect("Owner off commit was accepted")
            .commit_id();
        applied.route_owner_event_batch(
            applied_owner,
            vec![
                crate::kms::owner::device::OwnerEvent::Accepted { commit },
                crate::kms::owner::device::OwnerEvent::HardwareComplete { commit },
            ],
            std::time::Instant::now(),
        );
        let completion = applied.complete_owner_for_tests(1);
        applied.route_owner_event_batch(applied_owner, completion, std::time::Instant::now());
        assert!(
            !applied
                .resource_service()
                .expect("resource service")
                .seat_active_for_tests(),
            "once every served output is off, serviced-time pauses"
        );
        assert_eq!(
            applied.resource_service().unwrap().pending_batches().len(),
            1,
            "the test keeps a resource batch pending while observing the clock"
        );
        c0_3bi_assert_end_state(
            &rejected,
            "c0_3aii_resource_clock_runs_while_any_output_lit rejected",
            &c0_3bi_expected_end_state([
                OutputKey::new(rejected.platform.devices[0].key, "test"),
                OutputKey::new(owner_device, "owner-test"),
            ]),
        );
        c0_3bi_assert_end_state(
            &applied,
            "c0_3aii_resource_clock_runs_while_any_output_lit applied",
            &c0_3bi_expected_end_state([
                OutputKey::new(
                    applied
                        .platform
                        .primary_device()
                        .expect("Legacy test device")
                        .key,
                    "test",
                ),
                OutputKey::new(applied_owner, "owner-test"),
            ]),
        );
    }

    #[test]
    fn c0_3aii_rejected_off_is_deferred_and_not_retried() {
        use crate::kms::{
            executor::test_support::StubBehaviour,
            owner::lifecycle::{DesiredField, Disposition, Prerequisite},
        };

        let (mut attributable, device) =
            lifecycle_dpms_backend(StubBehaviour::RejectWithRepeatedly(libc::EINVAL));
        let previous_power = attributable
            .owner_dpms_installed_active
            .get(&device)
            .copied()
            .unwrap_or(true);
        Backend::set_dpms_power(&mut attributable, 3).expect("DPMS off request");
        wait_executor_readable_for_tests(&attributable, std::time::Duration::from_secs(5));
        Backend::on_executor_readable(&mut attributable, &mut ServerState::new());

        let arbiter = attributable
            .lifecycle_coordinator
            .device(&device)
            .expect("Owner lifecycle state");
        let rejected = arbiter
            .desired()
            .representative(DesiredField::Dpms)
            .expect("DPMS representative remains desired");
        let generation = attributable
            .platform
            .owner_ref(device)
            .expect("Owner")
            .topology_generation();
        assert_eq!(
            rejected.disposition,
            Some(Disposition::Deferred(Prerequisite::TopologyLatched(
                generation
            )))
        );
        assert_eq!(
            arbiter.state(),
            crate::kms::owner::lifecycle::DeviceLifecycleState::Ready
        );
        assert_eq!(
            attributable.owner_dpms_installed_active.get(&device),
            Some(&previous_power),
            "a rejected off leaves the previously installed power authoritative"
        );
        assert!(
            attributable
                .device_owner_for_tests(0)
                .tombstones()
                .is_empty(),
            "FailedBeforeSubmit creates no quarantine tombstone"
        );
        assert!(
            attributable
                .device_owner_for_tests(0)
                .live_record()
                .is_none(),
            "the rejection did not create an accepted commit"
        );
        assert!(
            attributable.lifecycle_drivers[&device]
                .pending_topology_tags()
                .is_empty(),
            "the latched generation is not retried after its rejection"
        );

        let first_event = rejected.event_id;
        Backend::set_dpms_power(&mut attributable, 0).expect("newer DPMS request");
        let newer = attributable
            .lifecycle_coordinator
            .device(&device)
            .unwrap()
            .desired()
            .representative(DesiredField::Dpms)
            .expect("new request supersedes the rejected representative");
        assert_ne!(newer.event_id, first_event);
        assert_eq!(
            newer.disposition,
            Some(Disposition::Deferred(Prerequisite::TopologyLatched(
                generation
            )))
        );
        assert!(
            attributable.lifecycle_drivers[&device]
                .pending_topology_tags()
                .is_empty(),
            "the newer request also waits for a generation change"
        );

        let (mut non_attributable, non_attributable_device) =
            lifecycle_dpms_backend(StubBehaviour::RejectWith(libc::EACCES));
        let old_power = non_attributable
            .owner_dpms_installed_active
            .get(&non_attributable_device)
            .copied()
            .unwrap_or(true);
        Backend::set_dpms_power(&mut non_attributable, 3).expect("DPMS off request");
        wait_executor_readable_for_tests(&non_attributable, std::time::Duration::from_secs(5));
        Backend::on_executor_readable(&mut non_attributable, &mut ServerState::new());
        let rejected = non_attributable
            .lifecycle_coordinator
            .device(&non_attributable_device)
            .unwrap()
            .desired()
            .representative(DesiredField::Dpms)
            .expect("non-attributable rejection remains desired");
        assert_eq!(
            rejected.disposition,
            Some(Disposition::Deferred(Prerequisite::ReadinessClosed))
        );
        assert_eq!(
            non_attributable
                .owner_dpms_installed_active
                .get(&non_attributable_device),
            Some(&old_power)
        );
        assert!(
            non_attributable
                .device_owner_for_tests(0)
                .tombstones()
                .is_empty()
        );
        assert!(
            non_attributable.lifecycle_drivers[&non_attributable_device]
                .pending_topology_tags()
                .is_empty()
        );
        c0_3bi_assert_end_state(
            &attributable,
            "c0_3aii_rejected_off_is_deferred_and_not_retried attributable",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
        c0_3bi_assert_end_state(
            &non_attributable,
            "c0_3aii_rejected_off_is_deferred_and_not_retried non-attributable",
            &c0_3bi_expected_end_state([OutputKey::new(non_attributable_device, "test")]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3aii_lost_off_fence_poisons_vulkan() {
        use crate::kms::{
            executor::test_support::StubBehaviour,
            owner::{
                fences::{FencePollSet, FenceQuery},
                lifecycle::{DesiredField, DeviceLifecycleState, Disposition, Prerequisite},
            },
        };
        use std::{
            io,
            os::fd::BorrowedFd,
            time::{Duration, Instant},
        };

        struct PendingFence;
        impl FenceQuery for PendingFence {
            fn status(
                &mut self,
                _fd: BorrowedFd<'_>,
            ) -> io::Result<crate::platform::sync_file::FenceStatus> {
                Ok(crate::platform::sync_file::FenceStatus::Pending)
            }
        }
        struct LateFence;
        impl FenceQuery for LateFence {
            fn status(
                &mut self,
                _fd: BorrowedFd<'_>,
            ) -> io::Result<crate::platform::sync_file::FenceStatus> {
                Ok(crate::platform::sync_file::FenceStatus::Success)
            }
        }
        struct NoopPollSet;
        impl FencePollSet for NoopPollSet {
            fn register(&mut self, _fd: BorrowedFd<'_>, _token: u64) -> io::Result<()> {
                Ok(())
            }

            fn unregister(&mut self, _fd: BorrowedFd<'_>) -> io::Result<()> {
                Ok(())
            }
        }

        let OwnerLiveFixture { mut backend, .. } =
            owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let device = backend.platform.primary_device().expect("Owner device").key;
        c0_3aii_prepare_lifecycle_clock(&mut backend, device);
        c0_3aii_replace_owner_executor(
            &mut backend,
            StubBehaviour::AcceptLifecycleWithPendingFence,
        );
        Backend::set_dpms_power(&mut backend, 3).expect("DPMS off request");

        let mut state = ServerState::new();
        for _ in 0..2 {
            wait_executor_readable_for_tests(&backend, Duration::from_secs(5));
            Backend::on_executor_readable(&mut backend, &mut state);
            if backend
                .device_owner_for_tests(0)
                .live_record()
                .is_some_and(|record| record.milestones().accepted)
            {
                break;
            }
        }
        let record = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("real lifecycle commit after final TEST_ONLY");
        assert!(record.milestones().accepted);
        let commit = record.commit_id();
        let accepted_at = record
            .completion_state()
            .accepted_at
            .expect("accepted timestamp");
        let deadline = backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.completion_deadline())
            .expect("required off-fence lifecycle deadline");
        assert_eq!(
            deadline.duration_since(accepted_at),
            Duration::from_secs(30),
            "without a measured lifecycle maximum, the off fence gets C.0's 30-second ceiling"
        );

        let pending_events = backend
            .platform
            .owner_for(device)
            .expect("Owner")
            .observe_fences(
                &mut PendingFence,
                &mut NoopPollSet,
                accepted_at + Duration::from_millis(1),
            );
        assert!(
            pending_events.is_empty(),
            "the injected off fence is pending"
        );
        let timeout_events = backend
            .platform
            .owner_for(device)
            .expect("Owner")
            .tick_completion(deadline + Duration::from_nanos(1));
        assert!(timeout_events.iter().any(|event| matches!(
            event,
            crate::kms::owner::device::OwnerEvent::MechanismFailed {
                reason: crate::kms::owner::completion::MechanismFailure::HardwareTimeout
            }
        )));
        assert!(backend.route_owner_event_batch(device, timeout_events, Instant::now()));
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .expect("lifecycle state")
                .state(),
            DeviceLifecycleState::Poisoned
        );
        assert_eq!(
            backend.owner_dpms_installed_active.get(&device),
            Some(&true)
        );
        let representative = backend
            .lifecycle_coordinator
            .device(&device)
            .unwrap()
            .desired()
            .representative(DesiredField::Dpms)
            .expect("unknown transition remains unresolved");
        assert_eq!(
            representative.disposition,
            Some(Disposition::Deferred(Prerequisite::ReadinessClosed))
        );
        assert_eq!(
            backend
                .device_owner_for_tests(0)
                .live_record()
                .expect("unknown record remains quarantined")
                .commit_id(),
            commit
        );

        let late_events = backend
            .platform
            .owner_for(device)
            .expect("Owner")
            .observe_fences(
                &mut LateFence,
                &mut NoopPollSet,
                deadline + Duration::from_secs(1),
            );
        assert!(late_events.is_empty(), "a late fence cannot promote poison");
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .unwrap()
                .state(),
            DeviceLifecycleState::Poisoned
        );
        assert_eq!(
            backend.owner_dpms_installed_active.get(&device),
            Some(&true)
        );
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_lost_off_fence_poisons_vulkan",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
    fn c0_3aii_poisoned_dpms_issues_no_commit() {
        use crate::kms::{
            executor::test_support::StubBehaviour, owner::lifecycle::DeviceLifecycleState,
        };

        let (mut backend, device) = lifecycle_dpms_backend(StubBehaviour::NeverReply);
        let incarnation = backend
            .platform
            .owner_ref(device)
            .expect("Owner")
            .incarnation();
        let unknown = backend
            .platform
            .owner_for(device)
            .expect("Owner")
            .report_stream_failure(incarnation, std::time::Instant::now());
        assert!(backend.route_owner_event_batch(device, unknown, std::time::Instant::now()));
        assert!(
            backend
                .platform
                .owner_ref(device)
                .expect("Owner")
                .is_poisoned()
        );
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .unwrap()
                .state(),
            DeviceLifecycleState::Poisoned
        );

        let validations_before =
            backend.lifecycle_drivers[&device].pending_topology_validation_commits_for_tests();
        let topology_tags_before = backend.lifecycle_drivers[&device].pending_topology_tags();
        let trace_before = backend.admission_trace_for_tests(device);
        let transition_kind_before = backend
            .lifecycle_coordinator
            .device(&device)
            .and_then(|arbiter| arbiter.transition())
            .map(|transition| transition.kind);
        Backend::set_dpms_power(&mut backend, 3).expect("logical off while poisoned");
        Backend::set_dpms_power(&mut backend, 0).expect("logical on while poisoned");

        assert_eq!(
            backend.lifecycle_drivers[&device].pending_topology_validation_commits_for_tests(),
            validations_before,
            "Poisoned DPMS does not enqueue another conductor validation"
        );
        assert_eq!(
            backend.lifecycle_drivers[&device].pending_topology_tags(),
            topology_tags_before,
            "Poisoned DPMS does not add a topology request"
        );
        assert_eq!(backend.admission_trace_for_tests(device), trace_before);
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .and_then(|arbiter| arbiter.transition())
                .map(|transition| transition.kind),
            transition_kind_before,
            "Poisoned DPMS does not replace the existing recovery transition with DPMS"
        );
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .unwrap()
                .state(),
            DeviceLifecycleState::Poisoned
        );
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_poisoned_dpms_issues_no_commit",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
    fn c0_3aii_dpms_while_seat_released_is_deferred() {
        use crate::{
            kms::owner::lifecycle::{DesiredField, Disposition, Prerequisite, SeatTarget},
            vt::state::VtState,
        };

        let (mut backend, device) =
            lifecycle_dpms_backend(crate::kms::executor::test_support::StubBehaviour::NeverReply);
        backend.vt_resume_succeeds_for_tests = true;
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let mut state = ServerState::new();
        backend.inject_seat_event_for_test(&mut state, false);
        assert_eq!(backend.vt_state, VtState::Suspended);
        assert_eq!(
            backend.lifecycle_coordinator.seat_target(),
            Some(SeatTarget::Released),
            "the production suspend path feeds seat release to the coordinator"
        );
        Backend::set_dpms_power(&mut backend, 3).expect("DPMS off while seat is released");
        let representative = backend
            .lifecycle_coordinator
            .device(&device)
            .expect("Owner lifecycle state")
            .desired()
            .representative(DesiredField::Dpms)
            .expect("deferred DPMS representative");
        assert_eq!(
            representative.disposition,
            Some(Disposition::Deferred(Prerequisite::SeatReleased))
        );
        assert!(backend.device_owner_for_tests(0).live_record().is_none());
        assert!(
            backend.lifecycle_drivers[&device]
                .pending_topology_tags()
                .is_empty()
        );

        backend.inject_seat_event_for_test(&mut state, true);
        assert!(
            !backend
                .vt_resume_lifecycle_observations_for_tests
                .is_empty(),
            "the VT action loop records Owner lifecycle state while Resuming"
        );
        assert_eq!(
            backend.vt_resume_lifecycle_observations_for_tests,
            vec![(
                device,
                Some(Disposition::Deferred(Prerequisite::SeatReleased)),
                true,
            )],
            "DPMS remains deferred and topology work stays queued until Active"
        );
        assert_eq!(backend.vt_state, VtState::Active);
        assert!(backend.scanout_allowed());
        assert_eq!(
            backend.lifecycle_coordinator.seat_target(),
            Some(SeatTarget::Owned),
            "the production VT state-machine path feeds reacquisition after Active"
        );
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .unwrap()
                .desired()
                .seat_target(),
            Some(SeatTarget::Owned),
            "the per-device prerequisite is updated with the global observation"
        );
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .pending_topology_validation_commits_for_tests()
                .len(),
            1,
            "the deferred DPMS target starts exactly one topology validation after Active"
        );
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .pending_topology_tags()
                .len(),
            1
        );
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .pending_topology_descriptions_for_tests()
                .len(),
            1
        );
        assert_eq!(
            backend.platform.dpms_output_calls_for_tests,
            Some(vec![(
                false,
                backend
                    .platform
                    .outputs
                    .iter()
                    .map(|output| output.key.clone())
                    .collect()
            )]),
            "the VT fixture records the suspend operation without issuing a KMS ioctl"
        );

        let mut legacy = super::KmsBackend::for_tests();
        make_vt_fixture_headless(&mut legacy);
        let mut legacy_state = ServerState::new();
        legacy.inject_seat_event_for_test(&mut legacy_state, false);
        legacy.inject_seat_event_for_test(&mut legacy_state, true);
        assert_eq!(legacy_state.dpms.power_level, 0);
        assert_eq!(
            legacy.lifecycle_coordinator.seat_target(),
            Some(SeatTarget::Owned)
        );
        assert_eq!(legacy.lifecycle_coordinator.protocol_dpms_level(), 0);
        assert!(legacy.lifecycle_drivers.is_empty());
        assert!(!legacy.kms_outputs_active);
        assert_eq!(legacy_state.dpms.power_level, 0);
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_dpms_while_seat_released_is_deferred Owner",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
        c0_3bi_assert_end_state(
            &legacy,
            "c0_3aii_dpms_while_seat_released_is_deferred headless Legacy",
            &c0_3bi_expected_end_state([]),
        );
    }

    #[derive(Debug, Eq, PartialEq)]
    enum DpmsScriptStatus {
        SetReturned,
        Info(u8),
    }

    #[derive(Debug, Eq, PartialEq)]
    struct DpmsScriptObservation {
        step: &'static str,
        status: DpmsScriptStatus,
        installed_active: bool,
        projected_active: bool,
    }

    fn c0_3aii_dpms_script_observation(
        backend: &super::KmsBackend,
        step: &'static str,
        status: DpmsScriptStatus,
        owner_device: Option<DrmDeviceKey>,
        protocol_level: u8,
    ) -> DpmsScriptObservation {
        let projected_active = owner_device
            .and_then(|device| {
                let output = backend
                    .platform
                    .outputs
                    .iter()
                    .find(|output| output.key.device_key == device)?;
                let projection = backend
                    .lifecycle_coordinator
                    .device(&device)?
                    .desired()
                    .dpms_targets()
                    .get(&output.key)?;
                Some(projection.level == 0)
            })
            .unwrap_or(protocol_level == 0);
        let installed_active = owner_device.map_or(backend.kms_outputs_active, |device| {
            backend
                .owner_dpms_installed_active
                .get(&device)
                .copied()
                .unwrap_or(true)
        });
        DpmsScriptObservation {
            step,
            status,
            installed_active,
            projected_active,
        }
    }

    fn c0_3aii_apply_dpms_script_level(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        level: u8,
    ) {
        c0_3aii_apply_dpms_transition(backend, device, level);
        let representative = backend
            .lifecycle_coordinator
            .device(&device)
            .expect("Owner lifecycle arbiter")
            .desired()
            .representative(crate::kms::owner::lifecycle::DesiredField::Dpms)
            .expect("DPMS representative");
        assert!(
            matches!(
                representative.disposition,
                Some(crate::kms::owner::lifecycle::Disposition::Applied(_))
            ),
            "Owner DPMS level {level} must complete as Applied: {:?}",
            representative.disposition
        );
    }

    #[test]
    fn c0_3aii_dpms_differential_backend_state() {
        use crate::kms::executor::test_support::StubBehaviour;

        let mut legacy = super::KmsBackend::for_tests();
        legacy.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let (mut owner, owner_device) = lifecycle_dpms_backend(StubBehaviour::NeverReply);
        owner.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let mut legacy_steps = Vec::new();
        let mut owner_steps = Vec::new();
        let mut protocol_level: u8;

        for (label, level) in [("off", 3), ("on", 0), ("standby", 1), ("suspend", 2)] {
            let legacy_result = Backend::set_dpms_power(&mut legacy, level);
            assert!(legacy_result.is_ok(), "Legacy {label}: {legacy_result:?}");
            c0_3aii_apply_dpms_script_level(&mut owner, owner_device, level);
            protocol_level = level;
            legacy_steps.push(c0_3aii_dpms_script_observation(
                &legacy,
                label,
                DpmsScriptStatus::SetReturned,
                None,
                protocol_level,
            ));
            owner_steps.push(c0_3aii_dpms_script_observation(
                &owner,
                label,
                DpmsScriptStatus::SetReturned,
                Some(owner_device),
                protocol_level,
            ));

            if label == "off" || label == "on" {
                let info_label = if label == "off" {
                    "info-after-off"
                } else {
                    "info-after-on"
                };
                legacy_steps.push(c0_3aii_dpms_script_observation(
                    &legacy,
                    info_label,
                    DpmsScriptStatus::Info(protocol_level),
                    None,
                    protocol_level,
                ));
                owner_steps.push(c0_3aii_dpms_script_observation(
                    &owner,
                    info_label,
                    DpmsScriptStatus::Info(protocol_level),
                    Some(owner_device),
                    protocol_level,
                ));
                if label == "on" {
                    for index in 1..4 {
                        let info_label = match index {
                            1 => "info-on-2",
                            2 => "info-on-3",
                            _ => "info-on-4",
                        };
                        legacy_steps.push(c0_3aii_dpms_script_observation(
                            &legacy,
                            info_label,
                            DpmsScriptStatus::Info(protocol_level),
                            None,
                            protocol_level,
                        ));
                        owner_steps.push(c0_3aii_dpms_script_observation(
                            &owner,
                            info_label,
                            DpmsScriptStatus::Info(protocol_level),
                            Some(owner_device),
                            protocol_level,
                        ));
                    }
                }
            }
        }

        let legacy_off_while_off = Backend::set_dpms_power(&mut legacy, 3);
        assert!(legacy_off_while_off.is_ok());
        c0_3aii_apply_dpms_script_level(&mut owner, owner_device, 3);
        protocol_level = 3;
        legacy_steps.push(c0_3aii_dpms_script_observation(
            &legacy,
            "off-while-off",
            DpmsScriptStatus::SetReturned,
            None,
            protocol_level,
        ));
        owner_steps.push(c0_3aii_dpms_script_observation(
            &owner,
            "off-while-off",
            DpmsScriptStatus::SetReturned,
            Some(owner_device),
            protocol_level,
        ));

        let mut legacy_seat = ServerState::new();
        let mut owner_seat = ServerState::new();
        legacy.vt_resume_succeeds_for_tests = true;
        owner.vt_resume_succeeds_for_tests = true;
        legacy.inject_seat_event_for_test(&mut legacy_seat, false);
        owner.inject_seat_event_for_test(&mut owner_seat, false);
        assert_eq!(legacy_seat.dpms.power_level, owner_seat.dpms.power_level);
        let seat_reset_level = legacy_seat.dpms.power_level;
        assert_eq!(
            seat_reset_level, 0,
            "Legacy's production suspend feed resets DPMS to On"
        );
        assert_eq!(owner_seat.dpms.power_level, seat_reset_level);
        let legacy_released = Backend::set_dpms_power(&mut legacy, 3);
        let owner_released = Backend::set_dpms_power(&mut owner, 3);
        assert!(
            legacy_released.is_ok(),
            "Legacy released-seat request: {legacy_released:?}"
        );
        assert!(
            owner_released.is_ok(),
            "Owner released-seat request: {owner_released:?}"
        );
        protocol_level = 3;
        let owner_disposition = owner
            .lifecycle_coordinator
            .device(&owner_device)
            .expect("Owner lifecycle arbiter")
            .desired()
            .representative(crate::kms::owner::lifecycle::DesiredField::Dpms)
            .expect("released-seat DPMS representative")
            .disposition;
        assert_eq!(
            owner_disposition,
            Some(crate::kms::owner::lifecycle::Disposition::Deferred(
                crate::kms::owner::lifecycle::Prerequisite::SeatReleased
            )),
            "Task 8's production seat feed leaves the released-seat request deferred"
        );
        legacy_steps.push(c0_3aii_dpms_script_observation(
            &legacy,
            "request-while-seat-released",
            DpmsScriptStatus::SetReturned,
            None,
            protocol_level,
        ));
        owner_steps.push(c0_3aii_dpms_script_observation(
            &owner,
            "request-while-seat-released",
            DpmsScriptStatus::SetReturned,
            Some(owner_device),
            protocol_level,
        ));

        assert_eq!(
            legacy_steps.len(),
            11,
            "the documented script has 11 observations"
        );
        assert_eq!(owner_steps.len(), legacy_steps.len());
        for (legacy, owner) in legacy_steps.iter().zip(&owner_steps) {
            assert_eq!(legacy.step, owner.step);
            assert_eq!(legacy.status, owner.status, "status at {}", legacy.step);
            assert_eq!(
                legacy.installed_active, owner.installed_active,
                "installed power at {} (Legacy kms_outputs_active vs Owner installed state)",
                legacy.step
            );
            assert_eq!(
                legacy.projected_active, owner.projected_active,
                "projected power at {}",
                legacy.step
            );
        }
        assert!(
            owner_steps
                .iter()
                .any(|step| step.step == "off" && !step.installed_active),
            "an applied Owner off leaves the output dark"
        );
        c0_3bi_assert_end_state(
            &legacy,
            "c0_3aii_dpms_differential_backend_state Legacy",
            &c0_3bi_expected_end_state([OutputKey::new(
                legacy
                    .platform
                    .primary_device()
                    .expect("Legacy test device")
                    .key,
                "test",
            )]),
        );
        c0_3bi_assert_end_state(
            &owner,
            "c0_3aii_dpms_differential_backend_state Owner",
            &c0_3bi_expected_end_state([OutputKey::new(owner_device, "test")]),
        );
    }

    fn c0_3aii_install_dpms_core_client(
        state: &mut ServerState,
        id: u32,
    ) -> std::os::unix::net::UnixStream {
        use std::{
            collections::{HashMap, HashSet, VecDeque},
            os::unix::net::UnixStream,
            sync::{Arc, Mutex, atomic::AtomicU16},
        };

        let (writer, peer) = UnixStream::pair().expect("DPMS fixture client socket pair");
        writer
            .set_nonblocking(true)
            .expect("nonblocking DPMS fixture writer");
        peer.set_nonblocking(true)
            .expect("nonblocking DPMS fixture peer");
        state.clients.insert(
            id,
            yserver_core::server::ClientState {
                writer: Arc::new(Mutex::new(yserver_core::transport::Transport::Unix(writer))),
                byte_order: yserver_protocol::x11::ClientByteOrder::LittleEndian,
                last_sequence: Arc::new(AtomicU16::new(0)),
                resource_id_base: 0,
                resource_id_mask: u32::MAX,
                event_masks: HashMap::new(),
                save_set: HashSet::new(),
                big_requests_enabled: false,
                xi2_masks: HashMap::new(),
                xi1_event_classes: HashSet::new(),
                xi1_window_event_classes: HashMap::new(),
                outbound: VecDeque::new(),
                watching_writable: false,
                focused_window: yserver_core::resources::ROOT_WINDOW,
                reader_control: None,
                is_local: true,
                fd_passing: true,
            },
        );
        peer
    }

    fn c0_3aii_dpms_core_run(
        mut backend: super::KmsBackend,
        subscribed_listener: bool,
        listener_id: u32,
        expected_outputs: Vec<OutputKey>,
    ) -> (Vec<u8>, Vec<u8>) {
        use std::{io::Read, time::Duration};
        use yserver_core::{
            core_loop::process_request::{RequestOutcome, process_request},
            server::ServerState,
        };
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber, dpms};

        fn issue(
            state: &mut ServerState,
            backend: &mut super::KmsBackend,
            sequence: &mut u16,
            client: u32,
            minor: u8,
            body: &[u8],
        ) {
            *sequence = sequence.checked_add(1).expect("DPMS sequence exhausted");
            let length_units = if body.is_empty() { 1 } else { 2 };
            let outcome = process_request(
                state,
                backend,
                ClientId(client),
                SequenceNumber(*sequence),
                RequestHeader {
                    opcode: 134,
                    data: minor,
                    length_units,
                },
                body,
                None,
            )
            .expect("core DPMS request dispatch");
            assert!(
                matches!(outcome, RequestOutcome::Handled),
                "DPMS request must complete synchronously at the protocol boundary: {outcome:?}"
            );
        }

        let mut state = ServerState::new();
        state.dpms.kms_capable = true;
        state.dpms.enabled = true;
        // A future server start instant makes the protocol timestamp zero,
        // keeping the byte comparison independent of fixture startup timing.
        state.start_instant = std::time::Instant::now()
            .checked_add(Duration::from_secs(60))
            .expect("future protocol clock");
        let mut requester_peer = c0_3aii_install_dpms_core_client(&mut state, 1);
        let mut listener_peer = c0_3aii_install_dpms_core_client(&mut state, listener_id);
        let mut sequence = 0u16;

        if subscribed_listener {
            issue(
                &mut state,
                &mut backend,
                &mut sequence,
                listener_id,
                dpms::SELECT_INPUT,
                &dpms::DPMS_INFO_NOTIFY_MASK.to_le_bytes(),
            );
        }
        issue(
            &mut state,
            &mut backend,
            &mut sequence,
            1,
            dpms::FORCE_LEVEL,
            &[dpms::DPMS_MODE_OFF as u8, 0, 0, 0],
        );
        issue(&mut state, &mut backend, &mut sequence, 1, dpms::INFO, &[]);
        issue(
            &mut state,
            &mut backend,
            &mut sequence,
            1,
            dpms::FORCE_LEVEL,
            &[dpms::DPMS_MODE_ON as u8, 0, 0, 0],
        );
        for _ in 0..4 {
            issue(&mut state, &mut backend, &mut sequence, 1, dpms::INFO, &[]);
        }
        issue(
            &mut state,
            &mut backend,
            &mut sequence,
            1,
            dpms::FORCE_LEVEL,
            &[dpms::DPMS_MODE_STANDBY as u8, 0, 0, 0],
        );
        issue(
            &mut state,
            &mut backend,
            &mut sequence,
            1,
            dpms::FORCE_LEVEL,
            &[dpms::DPMS_MODE_SUSPEND as u8, 0, 0, 0],
        );
        issue(
            &mut state,
            &mut backend,
            &mut sequence,
            1,
            dpms::FORCE_LEVEL,
            &[dpms::DPMS_MODE_OFF as u8, 0, 0, 0],
        );
        backend.vt_resume_succeeds_for_tests = true;
        backend.inject_seat_event_for_test(&mut state, false);
        issue(
            &mut state,
            &mut backend,
            &mut sequence,
            1,
            dpms::FORCE_LEVEL,
            &[dpms::DPMS_MODE_OFF as u8, 0, 0, 0],
        );

        let mut requester = Vec::new();
        let mut listener = Vec::new();
        let read_available = |peer: &mut std::os::unix::net::UnixStream, bytes: &mut Vec<u8>| {
            let mut chunk = [0u8; 256];
            loop {
                match peer.read(&mut chunk) {
                    Ok(0) => break,
                    Ok(count) => bytes.extend_from_slice(&chunk[..count]),
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => break,
                    Err(error) => panic!("read DPMS fixture bytes: {error}"),
                }
            }
        };
        read_available(&mut requester_peer, &mut requester);
        read_available(&mut listener_peer, &mut listener);
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_dpms_core_run protocol scenario",
            &c0_3bi_expected_end_state(expected_outputs),
        );
        (requester, listener)
    }

    #[test]
    fn c0_3aii_dpms_differential_protocol_bytes() {
        use crate::kms::executor::test_support::StubBehaviour;

        let mut legacy_subscribed = super::KmsBackend::for_tests();
        legacy_subscribed.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let legacy_device = legacy_subscribed
            .platform
            .primary_device()
            .expect("Legacy test device")
            .key;
        let subscribed_legacy = c0_3aii_dpms_core_run(
            legacy_subscribed,
            true,
            2,
            vec![OutputKey::new(legacy_device, "test")],
        );
        let (owner_subscribed, owner_subscribed_device) =
            lifecycle_dpms_backend(StubBehaviour::NeverReply);
        let subscribed_owner = c0_3aii_dpms_core_run(
            owner_subscribed,
            true,
            3,
            vec![OutputKey::new(owner_subscribed_device, "test")],
        );
        assert_eq!(subscribed_owner, subscribed_legacy);
        assert_eq!(subscribed_legacy.0.len(), 5 * 32, "five DPMSInfo replies");
        assert_eq!(
            subscribed_legacy.1.len(),
            6 * 32,
            "five changed levels plus the released-seat request's notification"
        );
        for (index, level) in [3u16, 0, 0, 0, 0].into_iter().enumerate() {
            let start = index * 32;
            let reply = &subscribed_legacy.0[start..start + 32];
            assert_eq!(reply[0], 1, "DPMSInfo reply {index}");
            assert_eq!(
                u16::from_le_bytes([reply[8], reply[9]]),
                level,
                "DPMSInfo level {index}"
            );
            assert_eq!(reply[10], 1, "DPMS remains enabled in info reply {index}");
        }
        for (event, level) in subscribed_legacy
            .1
            .chunks_exact(32)
            .zip([3u16, 0, 1, 2, 3, 3])
        {
            assert_eq!(event[0], 35, "DPMSInfoNotify is a GenericEvent");
            assert_eq!(u16::from_le_bytes([event[16], event[17]]), level);
            assert_eq!(event[18], 1, "DPMS remains enabled in notify");
            assert_eq!(&event[12..16], &[0, 0, 0, 0], "fixture timestamp is stable");
        }

        let mut legacy_unsubscribed = super::KmsBackend::for_tests();
        legacy_unsubscribed.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let legacy_device = legacy_unsubscribed
            .platform
            .primary_device()
            .expect("Legacy test device")
            .key;
        let unsubscribed_legacy = c0_3aii_dpms_core_run(
            legacy_unsubscribed,
            false,
            2,
            vec![OutputKey::new(legacy_device, "test")],
        );
        let (owner_unsubscribed, owner_unsubscribed_device) =
            lifecycle_dpms_backend(StubBehaviour::NeverReply);
        let unsubscribed_owner = c0_3aii_dpms_core_run(
            owner_unsubscribed,
            false,
            3,
            vec![OutputKey::new(owner_unsubscribed_device, "test")],
        );
        assert_eq!(unsubscribed_owner, unsubscribed_legacy);
        assert_eq!(unsubscribed_legacy.0.len(), 5 * 32, "five DPMSInfo replies");
        assert!(
            unsubscribed_legacy.1.is_empty(),
            "a listener that did not select DPMSInfoNotify receives nothing"
        );
    }

    #[test]
    fn c0_3aii_seat_reacquire_waits_for_active() {
        use crate::{
            kms::owner::lifecycle::{DesiredField, Disposition, Prerequisite, SeatTarget},
            vt::state::{VtPending, VtState},
        };

        let (mut backend, device) =
            lifecycle_dpms_backend(crate::kms::executor::test_support::StubBehaviour::NeverReply);
        backend.vt_resume_succeeds_for_tests = true;
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let mut state = ServerState::new();
        backend.inject_seat_event_for_test(&mut state, false);
        assert_eq!(backend.vt_state, VtState::Suspended);

        Backend::set_dpms_power(&mut backend, 3).expect("DPMS off while seat is released");
        let representative = backend
            .lifecycle_coordinator
            .device(&device)
            .expect("Owner lifecycle state")
            .desired()
            .representative(DesiredField::Dpms)
            .expect("deferred DPMS representative");
        assert_eq!(
            representative.disposition,
            Some(Disposition::Deferred(Prerequisite::SeatReleased))
        );
        assert!(backend.device_owner_for_tests(0).live_record().is_none());
        assert!(
            backend.lifecycle_drivers[&device]
                .pending_topology_tags()
                .is_empty()
        );

        backend.vt_pending = VtPending {
            pending_disable: true,
            pending_enable: false,
        };
        backend.inject_seat_event_for_test(&mut state, true);

        assert!(
            !backend
                .vt_resume_lifecycle_observations_for_tests
                .is_empty(),
            "the VT action loop records Owner lifecycle state while Resuming"
        );
        assert_eq!(
            backend.vt_resume_lifecycle_observations_for_tests,
            vec![(
                device,
                Some(Disposition::Deferred(Prerequisite::SeatReleased)),
                true,
            )],
            "the immediate re-suspend does not dispatch topology work while Resuming"
        );
        assert_eq!(backend.vt_state, VtState::Suspended);
        assert!(!backend.scanout_allowed());
        assert_eq!(
            backend.lifecycle_coordinator.seat_target(),
            Some(SeatTarget::Released),
            "the immediate re-suspend leaves the seat prerequisite released"
        );
        let representative = backend
            .lifecycle_coordinator
            .device(&device)
            .expect("Owner lifecycle state")
            .desired()
            .representative(DesiredField::Dpms)
            .expect("DPMS remains represented");
        assert_eq!(
            representative.disposition,
            Some(Disposition::Deferred(Prerequisite::SeatReleased)),
            "a resume that returns BeginSuspend does not advance DPMS convergence"
        );
        assert!(backend.device_owner_for_tests(0).live_record().is_none());
        assert!(
            backend.lifecycle_drivers[&device]
                .pending_topology_tags()
                .is_empty()
        );
        assert!(
            backend.lifecycle_drivers[&device]
                .pending_topology_validation_commits_for_tests()
                .is_empty()
        );
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_seat_reacquire_waits_for_active",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3aii_capability_stable_across_dpms_and_poison_vulkan() {
        use crate::kms::{owner::lifecycle::DeviceLifecycleState, render::scene::CursorPlaneMode};

        let OwnerLiveFixture { mut backend, .. } =
            owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let device = backend.platform.primary_device().expect("Owner device").key;
        let discovered = backend
            .platform
            .discover_completion_caps(device)
            .expect("read structural completion capability");
        backend
            .platform
            .install_completion_caps(discovered)
            .expect("install discovered structural capability for this incarnation");
        backend.scene.test_set_cursor_mode(CursorPlaneMode::Hw);
        let capability_before = backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.completion_caps())
            .expect("structural capability surface")
            .clone();
        let structural_before = capability_before.is_structurally_capable();
        let cursor_mode_before = backend.scene.cursor_mode();
        assert_eq!(cursor_mode_before, CursorPlaneMode::Hw);

        for _ in 0..4 {
            c0_3aii_apply_dpms_transition(&mut backend, device, 3);
            c0_3aii_apply_dpms_transition(&mut backend, device, 0);
            let capability_after = backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.completion_caps())
                .expect("DPMS preserves structural capability");
            assert_eq!(capability_after, &capability_before);
            assert_eq!(
                capability_after.is_structurally_capable(),
                structural_before
            );
            assert_eq!(backend.scene.cursor_mode(), cursor_mode_before);
        }

        let incarnation = backend
            .platform
            .owner_ref(device)
            .expect("Owner")
            .incarnation();
        let unknown = backend
            .platform
            .owner_for(device)
            .expect("Owner")
            .report_stream_failure(incarnation, std::time::Instant::now());
        assert!(backend.route_owner_event_batch(device, unknown, std::time::Instant::now()));
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .unwrap()
                .state(),
            DeviceLifecycleState::Poisoned
        );
        assert_eq!(
            backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.completion_caps()),
            Some(&capability_before),
            "incarnation poison closes readiness but preserves structural capability"
        );
        assert_eq!(backend.scene.cursor_mode(), cursor_mode_before);
        c0_3bi_assert_end_state(
            &backend,
            "c0_3aii_capability_stable_across_dpms_and_poison_vulkan",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    fn c0_3aii_replace_owner_executor(
        backend: &mut super::KmsBackend,
        behaviour: crate::kms::executor::test_support::StubBehaviour,
    ) {
        let device = &mut backend.platform.devices[0];
        if let Some(executor) = device.executor.as_mut() {
            crate::kms::executor::test_support::kill_and_reap(executor);
            if let Some(proof) = executor.take_reap_proof()
                && let Some(lease) = device.helper_lease.take()
            {
                device
                    .incarnation_fd_set
                    .borrow_mut()
                    .release_with_proof(lease, proof)
                    .expect("release reaped Owner fixture helper lease");
            }
        }
        let executor = crate::kms::executor::test_support::spawn_stub_helper(behaviour)
            .expect("replace Owner test executor");
        let device = &mut backend.platform.devices[0];
        device.helper_lease = Some(
            device
                .incarnation_fd_set
                .borrow_mut()
                .register_alias_from(
                    device
                        .device
                        .attached()
                        .expect("attached test DRM device")
                        .as_fd(),
                )
                .expect("track replacement Owner helper lease"),
        );
        device.executor = Some(executor);
    }

    fn c0_3aii_apply_dpms_transition(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        level: u8,
    ) -> crate::kms::owner::identity::CommitId {
        use crate::kms::executor::test_support::{ScriptedReply, StubBehaviour};

        c0_3aii_prepare_lifecycle_clock(backend, device);
        c0_3aii_replace_owner_executor(
            backend,
            StubBehaviour::Scripted(ScriptedReply::Accepted { mask: 0, fds: 0 }),
        );
        Backend::set_dpms_power(backend, level).expect("Owner DPMS request");
        c0_3bi_core_driver_until(
            backend,
            "dispatch Owner DPMS transition",
            std::time::Duration::from_secs(5),
            &|backend| backend.device_owner_for_tests(0).live_record().is_some(),
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));

        let record = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("validated DPMS topology must dispatch");
        let commit = record.commit_id();
        c0_conv_cii_accept_direct_owner_commit(backend, device, commit);
        let completion = backend.complete_owner_for_tests(0);
        if level == 0
            && backend
                .admission_conductors
                .get(&device)
                .is_some_and(|conductor| conductor.admission.unflip().is_some())
        {
            // The full core-loop tail may dispatch the retained unflip as
            // soon as DPMS-on reopens admission. Give that next request a
            // live, non-replying executor instead of exhausting the one-shot
            // scripted DPMS reply and spuriously refusing the unflip.
            c0_3aii_replace_owner_executor(backend, StubBehaviour::NeverReply);
        }
        assert!(c0_3bi_drive_owner_batch(
            backend,
            device,
            completion,
            "complete Owner DPMS transition"
        ));

        let expected_active = level == 0;
        c0_3bi_core_driver_until(
            backend,
            "route Owner DPMS completion through the core iteration tail",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend.owner_dpms_installed_active.get(&device).copied() == Some(expected_active)
                    && backend
                        .lifecycle_coordinator
                        .device(&device)
                        .is_some_and(|arbiter| {
                            arbiter.state()
                                == crate::kms::owner::lifecycle::DeviceLifecycleState::Ready
                        })
                    && (backend.device_owner_for_tests(0).live_record().is_none()
                        || backend.scanout_m2.owner_unflip_return.is_some())
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));
        if backend.scanout_m2.owner_unflip_return.is_none() {
            // Keep the helper executor available for an explicit compose
            // requested by a test after the lifecycle transition returns.
            c0_3aii_replace_owner_executor(backend, StubBehaviour::NeverReply);
        }

        assert_eq!(
            backend.owner_dpms_installed_active.get(&device).copied(),
            Some(level == 0),
            "Owner power state changes only after routed completion"
        );
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .expect("Owner lifecycle arbiter")
                .state(),
            crate::kms::owner::lifecycle::DeviceLifecycleState::Ready,
            "applied DPMS returns the Owner device to Ready"
        );
        commit
    }

    fn c0_3aii_prepare_lifecycle_clock(backend: &mut super::KmsBackend, device: DrmDeviceKey) {
        use crate::kms::owner::clock::{ClockSource, ProbeState};

        let output_idx = backend
            .platform
            .outputs
            .iter()
            .position(|output| output.key.device_key == device)
            .expect("Owner lifecycle output");
        let crtc_key = CrtcKey::for_output(&backend.platform.outputs[output_idx]);
        let hardware_crtc = u32::from(crtc_key.crtc);
        let owner = backend.platform.owner_ref(device).expect("Owner device");
        let key = owner
            .clock_key_for_hardware_crtc(hardware_crtc)
            .expect("lifecycle fixture uses the production-installed clock");
        let clock = owner.clock(key).expect("production lifecycle clock");
        assert_eq!(clock.source, ClockSource::KernelSequence);
        assert_eq!(clock.probe, ProbeState::Succeeded);
        backend.platform.record_completion_clock(
            crtc_key,
            yserver_core::backend::PresentClockSample {
                msc: 1_000,
                ust: 1_000_000,
                source: yserver_core::backend::PresentClockSource::IdleSequence,
            },
        );
    }

    fn c0_3bi_install_fresh_clock_epoch(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
    ) -> crate::kms::owner::clock::ClockKey {
        let output_idx = backend
            .platform
            .outputs
            .iter()
            .position(|output| output.key.device_key == device)
            .expect("Owner output");
        let hardware_crtc =
            u32::from(CrtcKey::for_output(&backend.platform.outputs[output_idx]).crtc);
        bind_test_randr_crtc(backend, output_idx, 0x3b01);
        let previous = backend
            .platform
            .owner_ref(device)
            .expect("Owner")
            .clock_key_for_hardware_crtc(hardware_crtc)
            .expect("fixture clock");
        assert!(
            backend
                .platform
                .owner_for(device)
                .expect("Owner")
                .invalidate_clock(previous)
                .is_empty(),
            "no probe is in flight while replacing the fixture epoch"
        );
        backend.refresh_present_crtc_clock_epochs();
        let current = backend
            .platform
            .owner_ref(device)
            .expect("Owner")
            .clock_key_for_hardware_crtc(hardware_crtc)
            .expect("fresh production clock epoch");
        assert!(current.epoch > previous.epoch);
        current
    }

    fn c0_3bi_install_unprobed_clock_epoch(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
    ) -> crate::kms::owner::clock::ClockKey {
        let hardware_crtc = u32::from(CrtcKey::for_output(&backend.platform.outputs[0]).crtc);
        let owner = backend.platform.owner_for(device).expect("Owner");
        let previous = owner
            .clock_key_for_hardware_crtc(hardware_crtc)
            .expect("fixture clock");
        assert!(owner.invalidate_clock(previous).is_empty());
        let (lifecycle, generation) = owner.clock_context();
        let epoch = owner.next_clock_epoch_after(hardware_crtc, 1);
        let current = crate::kms::owner::clock::ClockKey {
            hardware_crtc,
            epoch,
        };
        backend
            .platform
            .owner_for(device)
            .expect("Owner")
            .install_clock(current, lifecycle, generation)
            .expect("fresh unresolved clock epoch");
        current
    }

    fn c0_3bi_begin_dpms_transition(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        level: u8,
    ) -> crate::kms::owner::identity::CommitId {
        use crate::kms::executor::test_support::{ScriptedReply, StubBehaviour};

        let (validation_before, live_before, ..) =
            backend.lifecycle_drivers[&device].topology_test_stats();
        c0_3aii_replace_owner_executor(
            backend,
            StubBehaviour::Scripted(ScriptedReply::Accepted { mask: 0, fds: 0 }),
        );
        Backend::set_dpms_power(backend, level).expect("Owner DPMS request");
        let (validation_after, ..) = backend.lifecycle_drivers[&device].topology_test_stats();
        assert_eq!(
            validation_after.len(),
            validation_before.len() + 1,
            "lifecycle validation proceeds without waiting for a dark CRTC clock"
        );
        c0_3bi_core_driver_until(
            backend,
            "dispatch Owner DPMS transition",
            std::time::Duration::from_secs(5),
            &|backend| backend.device_owner_for_tests(0).live_record().is_some(),
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));

        let (_, live_after, ..) = backend.lifecycle_drivers[&device].topology_test_stats();
        assert_eq!(
            live_after.len(),
            live_before.len() + 1,
            "validated lifecycle commit is dispatched exactly once"
        );
        let commit = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("validated DPMS topology must dispatch")
            .commit_id();
        c0_conv_cii_accept_direct_owner_commit(backend, device, commit);
        commit
    }

    fn c0_3bi_complete_dpms_transition(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        post_completion_executor: crate::kms::executor::test_support::StubBehaviour,
    ) {
        let completion = backend.complete_owner_for_tests(0);
        c0_3aii_replace_owner_executor(backend, post_completion_executor);
        assert!(c0_3bi_drive_owner_batch(
            backend,
            device,
            completion,
            "complete Owner DPMS transition"
        ));
    }

