    fn c0_3bi_live_modeset_backend_inner(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
        with_other_output: bool,
        complete_composed_front: bool,
    ) -> Result<
        (
            OwnerLiveFixture,
            DrmDeviceKey,
            u32,
            String,
            yserver_core::backend::ModeSpec,
        ),
        std::io::Error,
    > {
        use crate::kms::backend::ActiveOutput;
        use ::drm::{ClientCapability, Device as _};
        use std::sync::Arc;

        let mut backend = super::KmsBackend::for_tests_with_vk_live_scene_real_drm()?;
        let device_key = backend
            .platform
            .vk
            .as_ref()
            .and_then(|vk| vk.selected_drm_identity)
            .and_then(|identity| identity.primary)
            .ok_or_else(|| std::io::Error::other("live modeset fixture has no DRM identity"))?;
        backend.platform.devices[0].key = device_key;
        backend.platform.outputs[0].key.device_key = device_key;
        backend.platform.outputs[0].scanout_route.kms_device_key = device_key;
        let scanout_route = backend.platform.outputs[0].scanout_route;
        match backend.platform.scanout_pools[0]
            .as_mut()
            .expect("live-scene fixture retains its scanout pool")
        {
            crate::kms::vk::scanout::OutputScanout::Shared(pool) => {
                pool.route = scanout_route;
            }
            crate::kms::vk::scanout::OutputScanout::Copied(pool) => {
                pool.route = scanout_route;
                pool.destinations.route = scanout_route;
            }
        }
        let drm_device = backend.platform.devices[0]
            .device
            .clone_rc()
            .expect("attached test DRM device");
        for capability in [ClientCapability::UniversalPlanes, ClientCapability::Atomic] {
            let _ = drm_device.set_client_capability(capability, true);
        }

        if with_other_output {
            let vk = backend
                .platform
                .vk
                .as_ref()
                .cloned()
                .ok_or_else(|| std::io::Error::other("live modeset fixture has no Vulkan"))?;
            backend
                .platform
                .append_test_output_with_scanout_pool(Arc::clone(&vk), "test-output-1")?;
            // This unrelated fixture output reserves an object tuple which
            // cannot collide with a real device assignment discovered below.
            let other = &mut backend.platform.outputs[1].output;
            other.encoder = ::drm::control::from_u32(0xefff_ff01).unwrap();
            other.crtc = ::drm::control::from_u32(0xefff_ff02).unwrap();
            other.plane = ::drm::control::from_u32(0xefff_ff03).unwrap();
        }

        let candidates = crate::drm::modeset::discover_outputs(&drm_device)?;
        let selected = candidates
            .iter()
            .find_map(|candidate| {
                candidate
                    .modes
                    .iter()
                    .find(|mode| {
                        mode.width == candidate.picked.width
                            && mode.height == candidate.picked.height
                            && mode.vrefresh != candidate.picked.vrefresh
                    })
                    .map(|mode| (candidate.connector_name.clone(), mode.clone()))
            })
            .or_else(|| {
                candidates.iter().find_map(|candidate| {
                    candidate
                        .modes
                        .iter()
                        .find(|mode| {
                            mode.width != candidate.picked.width
                                || mode.height != candidate.picked.height
                                || mode.vrefresh != candidate.picked.vrefresh
                        })
                        .map(|mode| (candidate.connector_name.clone(), mode.clone()))
                })
            });
        let (connector, target_mode) = selected.ok_or_else(|| {
            std::io::Error::other(
                "live modeset fixture needs a connected connector with two advertised modes",
            )
        })?;
        let output_key = OutputKey::new(device_key, connector.clone());
        backend.platform.outputs[0].key = output_key.clone();
        backend.platform.outputs[0].output.connector_name = connector.clone();
        let reserved_routes = backend
            .platform
            .outputs
            .iter()
            .skip(1)
            .map(|layout| {
                (
                    layout.output.encoder,
                    layout.output.crtc,
                    layout.output.plane,
                )
            })
            .collect::<Vec<_>>();
        let output = crate::drm::modeset::discover_output_for_connector(
            &drm_device,
            &connector,
            &reserved_routes,
        )?;
        let target_mode = output
            .modes
            .iter()
            .find(|mode| {
                mode.width == output.picked.width
                    && mode.height == output.picked.height
                    && mode.vrefresh != output.picked.vrefresh
            })
            .cloned()
            .unwrap_or(target_mode);
        let target_mode = yserver_core::backend::ModeSpec {
            width: target_mode.width,
            height: target_mode.height,
            vrefresh: target_mode.vrefresh,
        };
        let route = backend.platform.scanout_route_for_kms(device_key)?;
        let vk = backend
            .platform
            .vk
            .as_ref()
            .cloned()
            .ok_or_else(|| std::io::Error::other("live modeset fixture has no Vulkan"))?;
        let pool = crate::kms::vk::scanout::ScanoutBoPool::allocate(
            Arc::clone(&vk),
            Rc::clone(&drm_device),
            route,
            u32::from(output.picked.width),
            u32::from(output.picked.height),
            crate::kms::render::platform::SCANOUT_POOL_DEPTH,
            &output.scanout_modifiers,
        )
        .map_err(|error| std::io::Error::other(format!("fixture scanout pool: {error}")))?;
        backend.platform.outputs[0] = ActiveOutput::new(
            route,
            output,
            crate::drm::Swapchain::empty_for_tests(),
            0,
            0,
        );
        backend.acquire_uses_live_kms_discovery_for_tests = true;
        backend.platform.scanout_pools[0] =
            Some(crate::kms::vk::scanout::OutputScanout::Shared(pool));
        let pool_depth = backend.platform.scanout_pools[0]
            .as_ref()
            .expect("new live modeset pool")
            .display_pool()
            .bos
            .len();
        backend.platform.bo_generations[0] = vec![Default::default(); pool_depth];
        backend
            .platform
            .rebuild_output_instance_ids_for_tests()
            .map_err(|error| std::io::Error::other(format!("fixture output instance: {error}")))?;

        if with_other_output {
            backend.platform.outputs[1].x = i32::from(backend.platform.outputs[0].width);
        }
        let framebuffer_width = backend
            .platform
            .outputs
            .iter()
            .map(|layout| layout.x.saturating_add(i32::from(layout.width)))
            .max()
            .unwrap_or(backend.platform.outputs[0].width.into())
            .clamp(1, i32::from(u16::MAX));
        let framebuffer_width =
            u16::try_from(framebuffer_width).expect("clamped live fixture width fits in u16");
        let framebuffer_height = backend
            .platform
            .outputs
            .iter()
            .map(|layout| layout.y.saturating_add(i32::from(layout.height)))
            .max()
            .unwrap_or(backend.platform.outputs[0].height.into())
            .clamp(1, i32::from(u16::MAX));
        let framebuffer_height =
            u16::try_from(framebuffer_height).expect("clamped live fixture height fits in u16");
        backend.apply_virtual_screen_extent(framebuffer_width, framebuffer_height)?;
        backend
            .scene
            .rebuild_outputs(&backend.platform)
            .map_err(|error| std::io::Error::other(format!("fixture scene rebuild: {error:?}")))?;

        let ids = backend.randr_id_alloc.ids_for(&output_key);
        {
            let entry = backend.randr_id_alloc.entry_mut(&output_key);
            entry.connected = true;
            entry.config = super::ConnectorConfig::Enabled {
                mode_w: backend.platform.outputs[0].width,
                mode_h: backend.platform.outputs[0].height,
                vrefresh: backend.platform.outputs[0].output.picked.vrefresh,
                x: 0,
                y: 0,
            };
            entry.modes = backend.platform.outputs[0].output.modes.clone();
            entry.edid = backend.platform.outputs[0].output.edid.clone();
            entry.mm_width = backend.platform.outputs[0].output.mm_width;
            entry.mm_height = backend.platform.outputs[0].output.mm_height;
            entry.connector_type = backend.platform.outputs[0].output.connector_type.clone();
        }
        backend
            .output_key_by_id
            .insert(ids.output_id, output_key.clone());
        if complete_composed_front {
            assert!(
                !backend.platform.output_uses_owner_route(0),
                "the setup frame must travel through the production Legacy compose path"
            );
            {
                let _accept_flip = crate::drm::page_flip::accept_page_flips_for_tests();
                backend.scene.mark_scene_structure_dirty();
                backend.tick_maybe_composite_for_tests_without_render_completion_drain();
                backend.platform.wait_idle_bounded();
                backend.drain_scanout_render_completions_for_tests();
            }
            assert!(
                backend.scene.pending_ack_count_for_tests(0) > 0,
                "the production compose path installed a page-flip acknowledgement"
            );
            let pending_bos = backend.platform.scanout_pools[0]
                .as_ref()
                .expect("live modeset fixture pool")
                .display_pool()
                .bos
                .iter()
                .filter(|bo| bo.state.phase == crate::kms::vk::scanout::BoPhase::Pending)
                .count();
            assert_eq!(pending_bos, 1, "the composed frame reached KMS Pending");
            assert_eq!(
                backend
                    .simulate_scene_page_flip_complete_for_tests()
                    .map_err(|error| {
                        std::io::Error::other(format!("complete fixture compose: {error:?}"))
                    })?,
                1,
                "the composed frame retired through the production scene path"
            );
            let on_screen_bos = backend.platform.scanout_pools[0]
                .as_ref()
                .expect("live modeset fixture pool")
                .display_pool()
                .bos
                .iter()
                .filter(|bo| bo.state.phase == crate::kms::vk::scanout::BoPhase::OnScreen)
                .count();
            assert_eq!(
                on_screen_bos, 1,
                "the completed compose marks its BO OnScreen"
            );
        }
        let mut fixture = finish_owner_live_fixture_with_properties(backend, false, false)?;
        c0_3aii_replace_owner_executor(&mut fixture.backend, behaviour);
        Ok((fixture, device_key, ids.output_id, connector, target_mode))
    }

    fn c0_3bi_live_two_owner_position_backend(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
    ) -> Result<(OwnerLiveFixture, DrmDeviceKey, DrmDeviceKey, u32, String), std::io::Error> {
        let (mut fixture, device_a, output_id, connector, _) =
            c0_3bi_live_modeset_backend(behaviour, true)?;
        let backend = &mut fixture.backend;
        let device_b = DrmDeviceKey {
            major: 0x7fff_ff00,
            minor: 41,
        };
        push_test_device(backend, device_b);
        // The fixture's second pool was initially registered under A. Drop
        // those unused fixture leases before changing its output identity,
        // then adopt the same BOs again after the new B instance is installed.
        {
            let (service, registry) = (
                backend
                    .resource_service
                    .as_mut()
                    .expect("fixture resource service"),
                backend
                    .drm_cleanup_registry
                    .as_mut()
                    .expect("fixture cleanup registry"),
            );
            backend.platform.scanout_pools[1]
                .as_mut()
                .expect("second output pool")
                .detach_managed_entries(Some(registry));
            service.service_ready_with_registry(registry);
        }
        let executor = crate::kms::executor::test_support::spawn_stub_helper(behaviour)
            .map_err(|error| std::io::Error::other(format!("second Owner executor: {error}")))?;
        let (incarnation, lifecycle) = executor.owner_identity();
        let drm_device_a = backend
            .platform
            .device_for_key(device_a)
            .expect("first fixture device")
            .device
            .clone_rc()
            .expect("first fixture DRM device attached");
        let second_device = backend
            .platform
            .devices
            .iter_mut()
            .find(|entry| entry.key == device_b)
            .expect("second fixture device");
        second_device.device = drm_device_a.into();
        second_device.executor = Some(executor);
        second_device.owner = Some(crate::kms::owner::device::DeviceCommitOwner::new(
            incarnation,
            lifecycle,
            1,
        ));

        let output_key = OutputKey::new(device_b, "position-test-output-b");
        {
            let output = &mut backend.platform.outputs[1];
            output.key = output_key.clone();
            output.scanout_route.kms_device_key = device_b;
            // The fixture starts this synthetic output without discovered
            // KMS property handles. Seed the same persistent ids used by the
            // other live Owner fixture so B can become composed-ready.
            output.output.plane = ::drm::control::from_u32(11).expect("B fixture plane");
            output.output.plane_fb_id_prop =
                ::drm::control::from_u32(19).expect("B fixture FB_ID property");
            output.output.plane_crtc_id_prop =
                ::drm::control::from_u32(20).expect("B fixture CRTC_ID property");
            // The second Owner shares the test DRM fd, but its synthetic
            // output must still serialize unique property IDs per object.
            // AcceptKernelCalls never submits this request to the kernel.
            output.output.plane_src_x_prop =
                ::drm::control::from_u32(30).expect("B fixture SRC_X property");
            output.output.plane_src_y_prop =
                ::drm::control::from_u32(31).expect("B fixture SRC_Y property");
            output.output.plane_src_w_prop =
                ::drm::control::from_u32(32).expect("B fixture SRC_W property");
            output.output.plane_src_h_prop =
                ::drm::control::from_u32(33).expect("B fixture SRC_H property");
            output.output.plane_crtc_x_prop =
                ::drm::control::from_u32(34).expect("B fixture CRTC_X property");
            output.output.plane_crtc_y_prop =
                ::drm::control::from_u32(35).expect("B fixture CRTC_Y property");
            output.output.plane_crtc_w_prop =
                ::drm::control::from_u32(36).expect("B fixture CRTC_W property");
            output.output.plane_crtc_h_prop =
                ::drm::control::from_u32(37).expect("B fixture CRTC_H property");
            output.output.crtc_out_fence_ptr_prop =
                Some(::drm::control::from_u32(22).expect("B fixture OUT_FENCE_PTR property"));
        }
        backend
            .platform
            .rebuild_output_instance_ids_for_tests()
            .map_err(|error| std::io::Error::other(format!("second output identity: {error}")))?;
        let vk = backend
            .platform
            .vk
            .as_ref()
            .cloned()
            .ok_or_else(|| std::io::Error::other("second output Vulkan context"))?;
        let replacement_pool = backend
            .platform
            .allocate_test_output_scanout(vk, 1)
            .map_err(|error| {
                std::io::Error::other(format!("second output pool recreation: {error}"))
            })?;
        let replacement_bo_count = replacement_pool.display_pool().bos.len();
        backend.platform.scanout_pools[1] = Some(replacement_pool);
        backend.platform.bo_generations[1] = vec![Default::default(); replacement_bo_count];
        backend
            .scene
            .rebuild_outputs(&backend.platform)
            .map_err(|error| std::io::Error::other(format!("second output scene: {error:?}")))?;

        let bo_count = backend.platform.scanout_pools[1]
            .as_ref()
            .expect("second output pool")
            .display_pool()
            .bos
            .len();
        {
            let platform = &mut backend.platform;
            let service = backend
                .resource_service
                .as_mut()
                .expect("fixture resource service");
            let registry = backend
                .drm_cleanup_registry
                .as_mut()
                .expect("fixture cleanup registry");
            for bo_idx in 0..bo_count {
                platform
                    .register_managed_scanout_bo(service, registry, 1, bo_idx)
                    .map_err(|error| {
                        std::io::Error::other(format!("second output BO adoption: {error:?}"))
                    })?;
            }
        }

        let crtc = u32::from(backend.platform.outputs[1].output.crtc);
        backend
            .platform
            .devices
            .iter_mut()
            .find(|entry| entry.key == device_b)
            .expect("second fixture device")
            .active_property_cache
            .insert_for_tests(crtc, 21);
        let output = &backend.platform.outputs[1];
        let ids = backend.randr_id_alloc.ids_for(&output_key);
        {
            let entry = backend.randr_id_alloc.entry_mut(&output_key);
            entry.connected = true;
            entry.config = crate::kms::render::backend::ConnectorConfig::Enabled {
                mode_w: output.width,
                mode_h: output.height,
                vrefresh: output.output.picked.vrefresh,
                x: output.x,
                y: output.y,
            };
            entry.modes = output.output.modes.clone();
            entry.edid = output.output.edid.clone();
            entry.mm_width = output.output.mm_width;
            entry.mm_height = output.output.mm_height;
            entry.connector_type = output.output.connector_type.clone();
        }
        backend.output_key_by_id.insert(ids.output_id, output_key);

        install_admission_owner_gate(backend, device_b);
        backend.install_admission_conductor_with_backend_composed_for_tests(
            device_b,
            AdmissionSourceFixture::new_source().0,
        );
        backend
            .lifecycle_register_owner_device(device_b)
            .map_err(|error| std::io::Error::other(format!("second Owner lifecycle: {error:?}")))?;
        backend.activate_admission_clock_probes(device_b);
        Ok((fixture, device_a, device_b, output_id, connector))
    }

    fn c0_3bi_copied_live_modeset_backend(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
    ) -> Result<
        (
            OwnerLiveFixture,
            DrmDeviceKey,
            u32,
            String,
            yserver_core::backend::ModeSpec,
        ),
        std::io::Error,
    > {
        use ::drm::{ClientCapability, Device as _};

        let (mut fixture, modeset) = copied_owner_live_fixture_inner(true)?;
        let backend = &mut fixture.backend;
        let (device_key, connector, target_mode) = modeset.ok_or_else(|| {
            std::io::Error::other("copied live modeset fixture has no real connector")
        })?;
        let output_key = OutputKey::new(device_key, connector.clone());
        let drm_device = backend
            .platform
            .device_for_key(device_key)
            .and_then(|device| device.device.clone_rc())
            .ok_or_else(|| {
                std::io::Error::new(
                    std::io::ErrorKind::NotConnected,
                    "copied modeset KMS device disappeared or detached",
                )
            })?;
        for capability in [ClientCapability::UniversalPlanes, ClientCapability::Atomic] {
            let _ = drm_device.set_client_capability(capability, true);
        }
        let ids = backend.randr_id_alloc.ids_for(&output_key);
        {
            let entry = backend.randr_id_alloc.entry_mut(&output_key);
            entry.connected = true;
            entry.config = super::ConnectorConfig::Enabled {
                mode_w: backend.platform.outputs[0].width,
                mode_h: backend.platform.outputs[0].height,
                vrefresh: backend.platform.outputs[0].output.picked.vrefresh,
                x: 0,
                y: 0,
            };
            entry.modes = backend.platform.outputs[0].output.modes.clone();
            entry.edid = backend.platform.outputs[0].output.edid.clone();
            entry.mm_width = backend.platform.outputs[0].output.mm_width;
            entry.mm_height = backend.platform.outputs[0].output.mm_height;
            entry.connector_type = backend.platform.outputs[0].output.connector_type.clone();
        }
        backend.output_key_by_id.insert(ids.output_id, output_key);
        backend.initialize_provider_output_sources()?;
        c0_3aii_replace_owner_executor(backend, behaviour);
        Ok((fixture, device_key, ids.output_id, connector, target_mode))
    }

    fn c0_3bi_live_disabled_modeset_backend(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
    ) -> Result<
        (
            OwnerLiveFixture,
            DrmDeviceKey,
            u32,
            String,
            yserver_core::backend::ModeSpec,
        ),
        std::io::Error,
    > {
        use super::ConnectorConfig;
        use ::drm::{ClientCapability, Device as _};

        let mut backend = super::KmsBackend::for_tests_with_vk_live_scene_real_drm()?;
        let device_key = backend
            .platform
            .vk
            .as_ref()
            .and_then(|vk| vk.selected_drm_identity)
            .and_then(|identity| identity.primary)
            .ok_or_else(|| std::io::Error::other("live modeset fixture has no DRM identity"))?;
        backend.platform.devices[0].key = device_key;
        backend.platform.outputs[0].key.device_key = device_key;
        backend.platform.outputs[0].scanout_route.kms_device_key = device_key;
        let scanout_route = backend.platform.outputs[0].scanout_route;
        match backend.platform.scanout_pools[0]
            .as_mut()
            .expect("live-scene fixture retains its scanout pool")
        {
            crate::kms::vk::scanout::OutputScanout::Shared(pool) => {
                pool.route = scanout_route;
            }
            crate::kms::vk::scanout::OutputScanout::Copied(pool) => {
                pool.route = scanout_route;
                pool.destinations.route = scanout_route;
            }
        }
        let drm_device = backend.platform.devices[0]
            .device
            .clone_rc()
            .expect("attached test DRM device");
        for capability in [ClientCapability::UniversalPlanes, ClientCapability::Atomic] {
            let _ = drm_device.set_client_capability(capability, true);
        }
        // Keep the synthetic output as the old lit topology while making its
        // reserved object tuple disjoint from the real connector selected below.
        backend.platform.outputs[0].output.encoder = ::drm::control::from_u32(0xefff_ff01).unwrap();
        backend.platform.outputs[0].output.crtc = ::drm::control::from_u32(0xefff_ff02).unwrap();
        backend.platform.outputs[0].output.plane = ::drm::control::from_u32(0xefff_ff03).unwrap();
        backend
            .scene
            .rebuild_outputs(&backend.platform)
            .map_err(|error| {
                std::io::Error::other(format!("rebuild disabled fixture scene: {error:?}"))
            })?;

        let mut fixture = finish_owner_live_fixture(backend, false)?;
        let drm_device = fixture.backend.platform.devices[0]
            .device
            .clone_rc()
            .expect("attached fixture DRM device");
        let reserved_routes = fixture
            .backend
            .platform
            .outputs
            .iter()
            .filter(|layout| layout.key.device_key == device_key)
            .map(|layout| {
                (
                    layout.output.encoder,
                    layout.output.crtc,
                    layout.output.plane,
                )
            })
            .collect::<Vec<_>>();
        let output = crate::drm::modeset::probe_connector_snapshots(&drm_device)?
            .into_iter()
            .filter(|candidate| !candidate.modes.is_empty())
            .find_map(|candidate| {
                crate::drm::modeset::discover_output_for_connector(
                    &drm_device,
                    &candidate.connector_name,
                    &reserved_routes,
                )
                .ok()
            })
            .ok_or_else(|| {
                std::io::Error::other(
                    "live disabled-output fixture needs a connected connector with an unreserved route",
                )
            })?;
        let connector = output.connector_name.clone();
        let output_key = OutputKey::new(device_key, connector.clone());
        let mode = yserver_core::backend::ModeSpec {
            width: output.picked.width,
            height: output.picked.height,
            vrefresh: output.picked.vrefresh,
        };
        let ids = fixture.backend.randr_id_alloc.ids_for(&output_key);
        {
            let entry = fixture.backend.randr_id_alloc.entry_mut(&output_key);
            entry.connected = true;
            entry.config = ConnectorConfig::Off;
            entry.modes = output.modes;
            entry.edid = output.edid;
            entry.mm_width = output.mm_width;
            entry.mm_height = output.mm_height;
            entry.connector_type = output.connector_type;
        }
        fixture
            .backend
            .output_key_by_id
            .insert(ids.output_id, output_key);
        c0_3aii_replace_owner_executor(&mut fixture.backend, behaviour);
        Ok((fixture, device_key, ids.output_id, connector, mode))
    }

    fn c0_3bi_begin_client_modeset(
        backend: &mut super::KmsBackend,
        output_id: u32,
        connector: &str,
        mode: Option<yserver_core::backend::ModeSpec>,
    ) -> yserver_core::backend::CrtcConfigToken {
        c0_3bi_begin_client_modeset_at(backend, output_id, connector, mode, 0, 0)
    }

    fn c0_3bi_begin_client_modeset_at(
        backend: &mut super::KmsBackend,
        output_id: u32,
        connector: &str,
        mode: Option<yserver_core::backend::ModeSpec>,
        x: i32,
        y: i32,
    ) -> yserver_core::backend::CrtcConfigToken {
        let result = Backend::begin_crtc_config(backend, output_id, connector, mode, x, y)
            .expect("Owner client modeset begin");
        let CrtcConfigApply::Pending(token) = result else {
            panic!("non-idempotent Owner request must occupy the asynchronous slot")
        };
        token
    }

    fn c0_3bi_current_mode(
        backend: &super::KmsBackend,
        output_idx: usize,
    ) -> yserver_core::backend::ModeSpec {
        let output = &backend.platform.outputs[output_idx];
        yserver_core::backend::ModeSpec {
            width: output.width,
            height: output.height,
            vrefresh: output.output.picked.vrefresh,
        }
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum C0RetiredProofKind {
        GpuFence,
        KmsRelease,
        ResourceProof,
        OwnerBuffer,
        QuarantinedOwnerBuffer,
    }

    struct C0ExpectedRetiredBundle {
        instance: crate::kms::backend::OutputInstanceId,
        proofs: Vec<C0RetiredProofKind>,
    }

    #[derive(Default)]
    struct C0EndStateExpectation {
        installed_outputs: Vec<OutputKey>,
        retained_bundles: Vec<C0ExpectedRetiredBundle>,
        quarantined_allocations: Vec<crate::kms::render::resources::AllocationKey>,
        other_live_allocations: Vec<crate::kms::render::resources::AllocationKey>,
    }

    fn c0_3bi_expected_end_state(
        installed_outputs: impl IntoIterator<Item = OutputKey>,
    ) -> C0EndStateExpectation {
        C0EndStateExpectation {
            installed_outputs: installed_outputs.into_iter().collect(),
            ..C0EndStateExpectation::default()
        }
    }

    fn c0_3bi_end_state_errors(
        backend: &super::KmsBackend,
        expected: &C0EndStateExpectation,
    ) -> Vec<String> {
        use crate::kms::{
            render::resources::{AllocationKey, ObligationKind},
            vk::scanout::{BoPhase, OutputScanout},
        };
        use std::collections::BTreeSet;

        let allocations = backend
            .resource_service()
            .map(|service| service.allocation_end_state_for_tests())
            .unwrap_or_default();
        let allocation_by_key = allocations
            .iter()
            .map(|allocation| (allocation.key, allocation))
            .collect::<std::collections::HashMap<_, _>>();
        let mut expected_keys = BTreeSet::<AllocationKey>::new();
        let mut errors = Vec::new();
        let expected_outputs = expected
            .installed_outputs
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>();
        let actual_outputs = backend
            .platform
            .outputs
            .iter()
            .map(|output| output.key.clone())
            .collect::<BTreeSet<_>>();
        for output in actual_outputs.difference(&expected_outputs) {
            errors.push(format!("unexpected installed output {output:?}"));
        }
        for output in expected_outputs.difference(&actual_outputs) {
            errors.push(format!("expected installed output {output:?} is absent"));
        }
        for output_key in &expected.installed_outputs {
            let Some(output_idx) = backend
                .platform
                .outputs
                .iter()
                .position(|output| output.key == *output_key)
            else {
                continue;
            };
            let Some(scanout) = backend
                .platform
                .scanout_pools
                .get(output_idx)
                .and_then(Option::as_ref)
            else {
                // Protocol-only lifecycle fixtures intentionally model the
                // KMS output inventory without allocating scanout pools.
                continue;
            };
            match scanout {
                OutputScanout::Shared(pool) => {
                    expected_keys.extend(pool.bos.iter().filter_map(|bo| bo.managed_key()));
                }
                OutputScanout::Copied(pool) => {
                    expected_keys.extend(
                        pool.destinations
                            .bos
                            .iter()
                            .filter_map(|bo| bo.managed_key()),
                    );
                    expected_keys.extend(
                        pool.sources
                            .iter()
                            .filter_map(|source| source.managed_key()),
                    );
                }
            }
        }
        let retired = backend.scene.retired_output_end_states_for_tests();
        let expected_retired = expected
            .retained_bundles
            .iter()
            .map(|bundle| bundle.instance)
            .collect::<BTreeSet<_>>();
        for bundle in &retired {
            if !expected_retired.contains(&bundle.instance) {
                errors.push(format!(
                    "unexpected retired-output bundle {:?} ({}) with allocations {:?}",
                    bundle.instance, bundle.key.connector_name, bundle.allocation_keys
                ));
                continue;
            }
            expected_keys.extend(bundle.allocation_keys.iter().copied());
            let expectation = expected
                .retained_bundles
                .iter()
                .find(|item| item.instance == bundle.instance)
                .expect("retired instance was checked against the expected set");
            let mut actual_proofs = Vec::new();
            if bundle.gpu_fence_proofs > 0 {
                actual_proofs.push(C0RetiredProofKind::GpuFence);
            }
            let mut resource_proof = false;
            let mut kms_release = false;
            for key in &bundle.allocation_keys {
                if let Some(allocation) = allocation_by_key.get(key) {
                    kms_release |= allocation
                        .pending_obligations
                        .contains(&ObligationKind::KmsRelease);
                    resource_proof |= allocation.pending_obligations.iter().any(|obligation| {
                        matches!(
                            obligation,
                            ObligationKind::Gpu
                                | ObligationKind::Read
                                | ObligationKind::ForeignReturn
                        )
                    });
                }
            }
            if kms_release {
                actual_proofs.push(C0RetiredProofKind::KmsRelease);
            }
            if resource_proof {
                actual_proofs.push(C0RetiredProofKind::ResourceProof);
            }
            if bundle.owner_buffers.iter().any(|(_, state)| {
                matches!(
                    state,
                    crate::kms::render::owner_buffer::OwnerBufferState::Submitted
                        | crate::kms::render::owner_buffer::OwnerBufferState::Accepted
                        | crate::kms::render::owner_buffer::OwnerBufferState::Current
                        | crate::kms::render::owner_buffer::OwnerBufferState::Releasing
                )
            }) {
                actual_proofs.push(C0RetiredProofKind::OwnerBuffer);
            }
            if bundle.owner_buffers.iter().any(|(_, state)| {
                *state == crate::kms::render::owner_buffer::OwnerBufferState::Quarantined
            }) {
                actual_proofs.push(C0RetiredProofKind::QuarantinedOwnerBuffer);
            }
            actual_proofs.sort_by_key(|proof| format!("{proof:?}"));
            let mut named_proofs = expectation.proofs.clone();
            named_proofs.sort_by_key(|proof| format!("{proof:?}"));
            if actual_proofs != named_proofs {
                errors.push(format!(
                    "retired-output bundle {:?} has proofs {:?}, test names {:?}",
                    bundle.instance, actual_proofs, named_proofs
                ));
            }
            for (bo_idx, phase) in bundle.phases.iter().enumerate() {
                let key = bundle.allocation_keys.get(bo_idx).copied();
                let has_kms_proof =
                    key.and_then(|key| allocation_by_key.get(&key))
                        .is_some_and(|allocation| {
                            allocation
                                .pending_obligations
                                .contains(&ObligationKind::KmsRelease)
                        });
                let has_scene_proof = backend
                    .scene
                    .bo_has_pending_proof_for_tests(bundle.instance, bo_idx);
                match phase {
                    BoPhase::OnScreen if !has_kms_proof => errors.push(format!(
                        "retired pool {:?} BO {bo_idx} is OnScreen without a pending KMS-release proof",
                        bundle.instance
                    )),
                    BoPhase::Retiring if !has_scene_proof && !resource_proof => errors.push(format!(
                        "retired pool {:?} BO {bo_idx} is Retiring without a pending proof",
                        bundle.instance
                    )),
                    BoPhase::Owner
                        if !bundle
                            .owner_buffers
                            .iter()
                            .any(|(owner_idx, _)| *owner_idx == bo_idx) =>
                    {
                        errors.push(format!(
                            "retired pool {:?} BO {bo_idx} is Owner without an owner buffer",
                            bundle.instance
                        ));
                    }
                    _ => {}
                }
            }
        }
        for expected_bundle in &expected.retained_bundles {
            if !retired
                .iter()
                .any(|bundle| bundle.instance == expected_bundle.instance)
            {
                errors.push(format!(
                    "named retired-output bundle {:?} is absent",
                    expected_bundle.instance
                ));
            }
        }

        expected_keys.extend(expected.quarantined_allocations.iter().copied());
        expected_keys.extend(expected.other_live_allocations.iter().copied());
        let actual_keys = allocations
            .iter()
            .map(|allocation| allocation.key)
            .collect::<BTreeSet<_>>();
        for key in actual_keys.difference(&expected_keys) {
            errors.push(format!(
                "resource service holds unexpected allocation {key:?}"
            ));
        }
        for key in expected_keys.difference(&actual_keys) {
            errors.push(format!(
                "expected live allocation {key:?} is absent from the resource service"
            ));
        }
        for key in &expected.quarantined_allocations {
            if allocation_by_key
                .get(key)
                .is_none_or(|allocation| !allocation.frozen)
            {
                errors.push(format!(
                    "named quarantined allocation {key:?} is not frozen in the resource service"
                ));
            }
        }

        let current_crtcs = backend
            .platform
            .outputs
            .iter()
            .map(CrtcKey::for_output)
            .collect::<HashSet<_>>();
        for resources in &backend.commit_consumer.current_resources {
            for member in &resources.crtcs {
                if !current_crtcs.contains(&member.crtc) {
                    errors.push(format!(
                        "current-resource lease for absent CRTC {:?} has no live holder",
                        member.crtc
                    ));
                }
            }
        }
        for (output_idx, scanout) in backend.platform.scanout_pools.iter().enumerate() {
            let Some(scanout) = scanout.as_ref() else {
                continue;
            };
            let Some(instance) = backend.scene.output_instance_id_for_tests(output_idx) else {
                errors.push(format!(
                    "installed output {output_idx} has no scene instance"
                ));
                continue;
            };
            let owner_buffers = backend.scene.owner_buffer_identities_for_tests(output_idx);
            for (bo_idx, bo) in scanout.display_pool().bos.iter().enumerate() {
                let key = bo.managed_key();
                let has_owner_buffer = owner_buffers
                    .iter()
                    .any(|owner| owner.bo_idx == bo_idx && Some(owner.managed_key) == key);
                let has_scene_proof = backend
                    .scene
                    .bo_has_pending_proof_for_tests(instance, bo_idx);
                let has_resource_proof = key
                    .and_then(|key| allocation_by_key.get(&key))
                    .is_some_and(|allocation| !allocation.pending_obligations.is_empty());
                match bo.state.phase {
                    BoPhase::Owner if !has_owner_buffer => errors.push(format!(
                        "installed pool {instance:?} BO {bo_idx} is Owner without an owner buffer"
                    )),
                    BoPhase::Retiring if !has_scene_proof && !has_resource_proof => errors.push(format!(
                        "installed pool {instance:?} BO {bo_idx} is Retiring without a pending proof"
                    )),
                    BoPhase::Pending if !has_scene_proof && !has_resource_proof => errors.push(format!(
                        "installed pool {instance:?} BO {bo_idx} is Pending without a pending proof"
                    )),
                    _ => {}
                }
            }
        }
        errors
    }

    fn c0_3bi_assert_end_state(
        backend: &super::KmsBackend,
        test_name: &str,
        expected: &C0EndStateExpectation,
    ) {
        let errors = c0_3bi_end_state_errors(backend, expected);
        assert!(
            errors.is_empty(),
            "{test_name} end-state check failed:\n{}\nretired bundle details: {:?}",
            errors.join("\n"),
            backend.scene.retired_output_end_states_for_tests()
        );
    }

    fn c0_3bi_assert_one_urgent_withdrawal_delivered(
        backend: &super::KmsBackend,
        state: &ServerState,
        trace_start: usize,
        output_id: u32,
        crtc_id: u32,
        label: &str,
    ) {
        use yserver_core::core_loop::run::CoreEntryDelivery;

        let urgent_withdrawals = backend.core_entry_deliveries_for_tests[trace_start..]
            .iter()
            .filter_map(|delivery| match delivery {
                CoreEntryDelivery::UrgentWithdrawal {
                    output_ids,
                    crtc_ids,
                } => Some((output_ids.clone(), crtc_ids.clone())),
                CoreEntryDelivery::TopologyEpisodeBegin(_)
                | CoreEntryDelivery::TopologyEpisodeEnd { .. } => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            urgent_withdrawals,
            vec![(vec![output_id], vec![crtc_id])],
            "{label}: exactly one delivered urgent withdrawal names this output and CRTC"
        );

        let resources = state.randr.screen_resources_current();
        assert!(
            !resources.outputs.contains(&output_id),
            "{label}: the withdrawn output is absent from the published projection"
        );
        assert!(
            !resources.crtcs.contains(&crtc_id),
            "{label}: the withdrawn CRTC is absent from the published projection"
        );
    }

    fn c0_3bi_assert_single_unpublished_topology_episode_delivered(
        backend: &super::KmsBackend,
        trace_start: usize,
        label: &str,
    ) {
        use yserver_core::core_loop::run::CoreEntryDelivery;

        let deliveries = &backend.core_entry_deliveries_for_tests[trace_start..];
        let topology_events = deliveries
            .iter()
            .filter(|delivery| {
                matches!(
                    delivery,
                    CoreEntryDelivery::TopologyEpisodeBegin(_)
                        | CoreEntryDelivery::TopologyEpisodeEnd { .. }
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            topology_events.len(),
            2,
            "{label}: exactly one begin and one end are delivered"
        );
        match (topology_events[0], topology_events[1]) {
            (
                CoreEntryDelivery::TopologyEpisodeBegin(begin_id),
                CoreEntryDelivery::TopologyEpisodeEnd {
                    episode_id: end_id,
                    published: false,
                },
            ) => assert_eq!(
                begin_id, end_id,
                "{label}: the unpublished end matches the one begun episode"
            ),
            other => panic!("{label}: expected ordered Begin, End(None), got {other:?}"),
        }
    }

    fn c0_3bi_assert_one_published_topology_episode_delivered(
        backend: &super::KmsBackend,
        trace_start: usize,
        label: &str,
    ) {
        use yserver_core::core_loop::run::CoreEntryDelivery;

        let topology_events = backend.core_entry_deliveries_for_tests[trace_start..]
            .iter()
            .filter_map(|delivery| match delivery {
                CoreEntryDelivery::TopologyEpisodeBegin(id) => Some((Some(*id), None)),
                CoreEntryDelivery::TopologyEpisodeEnd {
                    episode_id,
                    published,
                } => Some((None, Some((*episode_id, *published)))),
                CoreEntryDelivery::UrgentWithdrawal { .. } => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            topology_events.len(),
            2,
            "{label}: exactly one topology episode is delivered"
        );
        match (topology_events[0], topology_events[1]) {
            ((Some(begin_id), None), (None, Some((end_id, true)))) => assert_eq!(
                begin_id, end_id,
                "{label}: the published end matches the one begun episode"
            ),
            other => panic!("{label}: expected ordered Begin, End(Some), got {other:?}"),
        }
    }

    fn c0_3bi_assert_one_unpublished_topology_end_delivered(
        backend: &super::KmsBackend,
        trace_start: usize,
        expected_episode_id: Option<u64>,
        label: &str,
    ) {
        use yserver_core::core_loop::run::CoreEntryDelivery;

        let ends = backend.core_entry_deliveries_for_tests[trace_start..]
            .iter()
            .filter_map(|delivery| match delivery {
                CoreEntryDelivery::TopologyEpisodeEnd {
                    episode_id,
                    published: false,
                } => Some(*episode_id),
                CoreEntryDelivery::UrgentWithdrawal { .. }
                | CoreEntryDelivery::TopologyEpisodeBegin(_)
                | CoreEntryDelivery::TopologyEpisodeEnd {
                    published: true, ..
                } => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            ends.len(),
            1,
            "{label}: exactly one unpublished end is delivered"
        );
        if let Some(expected_episode_id) = expected_episode_id {
            assert_eq!(
                ends[0], expected_episode_id,
                "{label}: the unpublished end names the superseded episode"
            );
        }
    }

    fn c0_3bi_finish_announced_crtc_configs(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
    ) -> Result<(), String> {
        for token in Backend::drain_ready_crtc_configs(backend) {
            if !backend
                .core_driver_announced_crtc_configs_for_tests
                .insert(token)
            {
                return Err(format!(
                    "core-entry driver observed CRTC token {token:?} more than once"
                ));
            }
            if backend.ready_forced_reprobe_results.contains_key(&token) {
                let result = Backend::finish_forced_reprobe(backend, token, state)
                    .map_err(|error| error.to_string());
                backend
                    .core_driver_finished_forced_reprobes_for_tests
                    .push_back((token, result));
                continue;
            }
            let result = Backend::finish_crtc_config(backend, token);
            backend
                .core_driver_finished_crtc_configs_for_tests
                .push_back((token, result));
        }
        Ok(())
    }

    fn c0_3bi_take_crtc_config_result(
        backend: &mut super::KmsBackend,
        token: yserver_core::backend::CrtcConfigToken,
    ) -> std::io::Result<bool> {
        if let Some(index) = backend
            .core_driver_finished_crtc_configs_for_tests
            .iter()
            .position(|(announced, _)| *announced == token)
        {
            return backend
                .core_driver_finished_crtc_configs_for_tests
                .remove(index)
                .expect("located completed CRTC result")
                .1;
        }
        assert!(
            !backend
                .core_driver_announced_crtc_configs_for_tests
                .contains(&token),
            "core-entry driver announced {token:?}, but its finished result was already consumed or lost"
        );
        Backend::finish_crtc_config(backend, token)
    }

    fn c0_3bi_has_crtc_config_result(
        backend: &super::KmsBackend,
        token: yserver_core::backend::CrtcConfigToken,
    ) -> bool {
        backend
            .core_driver_finished_crtc_configs_for_tests
            .iter()
            .any(|(finished, _)| *finished == token)
    }

    fn c0_3bi_wait_client_modeset_live(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        token: yserver_core::backend::CrtcConfigToken,
        label: &str,
    ) -> crate::kms::owner::identity::CommitId {
        let tag = backend
            .lifecycle_drivers
            .get(&device)
            .and_then(|driver| driver.client_modeset.as_ref())
            .filter(|slot| slot.token == token)
            .map(|slot| slot.tag)
            .unwrap_or_else(|| panic!("{label}: no client-modeset slot for {token:?}"));
        let observed_commit = std::rc::Rc::new(std::cell::RefCell::new(None));
        let observed_commit_for_wait = std::rc::Rc::clone(&observed_commit);
        c0_3bi_core_driver_until(
            backend,
            label,
            std::time::Duration::from_secs(3),
            &|backend| {
                let Some(commit) = backend
                    .lifecycle_drivers
                    .get(&device)
                    .and_then(|driver| driver.client_modeset_commit_for_tests(tag))
                else {
                    return false;
                };
                let is_live = backend
                    .device_owner_for_tests(0)
                    .live_record()
                    .is_some_and(|record| record.commit_id() == commit);
                if is_live {
                    *observed_commit_for_wait.borrow_mut() = Some(commit);
                }
                is_live
            },
            None,
        )
        .unwrap_or_else(|error| {
            let driver = backend.lifecycle_drivers.get(&device);
            let tracked_commit = driver.and_then(|driver| driver.client_modeset_commit_for_tests(tag));
            let slot = driver.and_then(|driver| {
                driver.client_modeset.as_ref().map(|slot| {
                    (slot.token, slot.tag, slot.phase, slot.prepared.is_some())
                })
            });
            let stats = driver.map(|driver| driver.client_modeset_test_stats());
            let live = backend.device_owner_for_tests(0).live_record().map(|record| {
                (
                    record.commit_id(),
                    record.state(),
                    record.milestones(),
                    record.closure().kernel_event().to_vec(),
                )
            });
            panic!(
                "{error}; tag={tag:?}; tracked modeset commit={tracked_commit:?}; slot={slot:?}; test-only/live sends={:?}; live Owner record={live:?}",
                stats.map(|stats| (stats.0.len(), stats.1.len()) )
            )
        });
        observed_commit
            .borrow()
            .unwrap_or_else(|| panic!("{label}: driver saw no live commit for {tag:?}"))
    }

    /// Drive KMS progress through the same `Backend` entries used by the core
    /// loop. Test-injected Owner batches are treated as an already-readable
    /// owner-completion fd; all other readiness comes from `poll_fds()`.
    fn c0_3bi_core_driver_until(
        backend: &mut super::KmsBackend,
        label: &str,
        timeout: std::time::Duration,
        done: &dyn Fn(&super::KmsBackend) -> bool,
        hardware_complete: Option<&Rc<RefCell<HashSet<crate::kms::owner::identity::CommitId>>>>,
    ) -> Result<(), String> {
        let mut state = ServerState::new();
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            label,
            timeout,
            done,
            hardware_complete,
        )
    }

