    #[test]
    fn c0_3bi_lit_crtc_still_waits_for_its_clock() {
        use crate::kms::{
            executor::test_support::StubBehaviour,
            owner::clock::{ClockSource, ProbeState},
        };

        let (mut backend, device) = lifecycle_dpms_backend(StubBehaviour::AcceptCallsWith(303));
        let hardware_crtc = u32::from(CrtcKey::for_output(&backend.platform.outputs[0]).crtc);
        let key = c0_3bi_install_unprobed_clock_epoch(&mut backend, device);
        assert_eq!(
            backend
                .platform
                .owner_ref(device)
                .unwrap()
                .clock(key)
                .unwrap()
                .probe,
            ProbeState::NotStarted
        );
        assert!(
            !backend
                .platform
                .owner_ref(device)
                .unwrap()
                .has_clock_probe_in_flight()
        );

        let (validation_before, live_before, ..) =
            backend.lifecycle_drivers[&device].topology_test_stats();
        Backend::set_dpms_power(&mut backend, 3).expect("DPMS off request");
        let tag = lifecycle_test_tag(&backend, device);
        let (validation_waiting, live_waiting, ..) =
            backend.lifecycle_drivers[&device].topology_test_stats();
        assert_eq!(validation_waiting, validation_before);
        assert_eq!(live_waiting, live_before);

        backend.activate_admission_clock_probes(device);
        assert!(matches!(
            backend
                .platform
                .owner_ref(device)
                .unwrap()
                .clock(key)
                .unwrap()
                .probe,
            ProbeState::InFlight(_)
        ));
        let (validation_waiting, live_waiting, ..) =
            backend.lifecycle_drivers[&device].topology_test_stats();
        assert_eq!(validation_waiting, validation_before);
        assert_eq!(live_waiting, live_before);

        for _ in 0..4 {
            let (_, live_sends, ..) = backend.lifecycle_drivers[&device].topology_test_stats();
            if live_sends.iter().filter(|sent| **sent == tag).count() == 1 {
                break;
            }
            c0_3bi_drive_executor_ready(
                &mut backend,
                "c0_3bi_lit_crtc_still_waits_for_its_clock executor reply",
            );
        }

        let (validation_sends, live_sends, ..) =
            backend.lifecycle_drivers[&device].topology_test_stats();
        assert_eq!(
            validation_sends.iter().filter(|sent| **sent == tag).count(),
            1
        );
        assert_eq!(live_sends.iter().filter(|sent| **sent == tag).count(), 1);
        assert!(backend.device_owner_for_tests(0).live_record().is_some());
        let current_key = backend
            .platform
            .owner_ref(device)
            .unwrap()
            .clock_key_for_hardware_crtc(hardware_crtc)
            .unwrap();
        let clock = backend
            .platform
            .owner_ref(device)
            .unwrap()
            .clock(current_key)
            .unwrap();
        assert_eq!(clock.source, ClockSource::KernelSequence);
        assert_eq!(clock.probe, ProbeState::Succeeded);

        c0_3bi_assert_end_state(
            &backend,
            "c0_3bi_lit_crtc_still_waits_for_its_clock",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
    fn c0_3bi_no_probe_to_an_inactive_crtc() {
        use crate::kms::{
            executor::{ObservedOutcome, test_support::StubBehaviour},
            owner::clock::{ClockSource, ProbeState},
        };

        let (mut backend, device) = lifecycle_dpms_backend(StubBehaviour::NeverReply);
        c0_3aii_apply_dpms_transition(&mut backend, device, 3);
        let _ = backend.drained_host_call_events_for_tests();
        let key = c0_3bi_install_fresh_clock_epoch(&mut backend, device);
        let clock = backend
            .platform
            .owner_ref(device)
            .unwrap()
            .clock(key)
            .unwrap();
        assert_eq!(clock.source, ClockSource::Unresolved);
        assert_eq!(clock.probe, ProbeState::NotStarted);
        assert!(
            !backend
                .platform
                .owner_ref(device)
                .unwrap()
                .has_clock_probe_in_flight()
        );
        assert!(backend.drained_host_call_events_for_tests().is_empty());

        let commit = c0_3bi_begin_dpms_transition(&mut backend, device, 0);
        assert_eq!(
            backend
                .platform
                .owner_ref(device)
                .unwrap()
                .clock(key)
                .unwrap()
                .probe,
            ProbeState::NotStarted,
            "the unresolved epoch remains unprobed until DPMS-on completes"
        );
        assert_eq!(
            backend
                .device_owner_for_tests(0)
                .live_record()
                .map(|record| record.commit_id()),
            Some(commit)
        );
        c0_3bi_complete_dpms_transition(&mut backend, device, StubBehaviour::AcceptProbeWith(304));
        assert_eq!(
            backend.owner_dpms_installed_active.get(&device),
            Some(&true)
        );
        assert!(matches!(
            backend
                .platform
                .owner_ref(device)
                .unwrap()
                .clock(key)
                .unwrap()
                .probe,
            ProbeState::InFlight(_)
        ));

        c0_3bi_core_driver_until(
            &mut backend,
            "c0_3bi_no_probe_to_an_inactive_crtc probe reply",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .host_call_events_for_tests
                    .lock()
                    .unwrap()
                    .iter()
                    .any(|event| {
                        matches!(event.kind, ObservedOutcome::ProbeAccepted { sequence: 304 })
                    })
            },
            None,
        )
        .expect("core driver receives the newly lit epoch probe reply");
        let observations = backend.drained_host_call_events_for_tests();
        assert_eq!(
            observations
                .iter()
                .filter(|observation| matches!(
                    observation.kind,
                    ObservedOutcome::ProbeAccepted { sequence: 304 }
                ))
                .count(),
            1,
            "DPMS-on completion sends exactly one probe for the newly lit epoch"
        );
        let clock = backend
            .platform
            .owner_ref(device)
            .unwrap()
            .clock(key)
            .unwrap();
        assert_eq!(clock.source, ClockSource::KernelSequence);
        assert_eq!(clock.probe, ProbeState::Succeeded);

        c0_3bi_assert_end_state(
            &backend,
            "c0_3bi_no_probe_to_an_inactive_crtc",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
    fn c0_3bi_value_dead_reads_routed() {
        use crate::kms::executor::test_support::StubBehaviour;

        // Direct teardown keeps the Owner device lit according to its
        // acknowledged state even when the Legacy server-wide cache is stale.
        let (mut direct, device) = lifecycle_dpms_backend(StubBehaviour::NeverReply);
        direct.owner_dpms_installed_active.insert(device, true);
        direct.kms_outputs_active = false;
        direct.platform.dpms_output_calls_for_tests = Some(Vec::new());
        direct.scanout_m2.test_force_active = true;
        direct.scanout_m2.unflip_shadow_ready = true;
        assert!(
            direct
                .teardown_direct_before_topology_requery("C.0 installed-power test")
                .expect("test DPMS recorder avoids a hardware modeset")
        );

        // Owner power participates in topology freshness. Flipping only the
        // stale Legacy cache must not invalidate an Owner qualification.
        let (mut signature, signature_device) = lifecycle_dpms_backend(StubBehaviour::NeverReply);
        signature
            .owner_dpms_installed_active
            .insert(signature_device, true);
        signature.kms_outputs_active = false;
        let owner_signature = signature.crtc_config_topology_signature();
        signature.kms_outputs_active = true;
        assert_eq!(
            signature.crtc_config_topology_signature(),
            owner_signature,
            "Owner freshness ignores the Legacy cache"
        );
        signature
            .owner_dpms_installed_active
            .insert(signature_device, false);
        assert_ne!(
            signature.crtc_config_topology_signature(),
            owner_signature,
            "Owner freshness follows installed device power"
        );

        // The asynchronous qualifier's captured recovery state is also
        // device-local. Its executor only records the job; it never probes KMS.
        let (mut pending, pending_device, output_id, connector) =
            c0_3bi_client_modeset_backend(StubBehaviour::NeverReply);
        pending
            .owner_dpms_installed_active
            .insert(pending_device, true);
        pending.kms_outputs_active = false;
        let state = Rc::new(RefCell::new(TestCrtcConfigProbeState::default()));
        pending.set_crtc_config_probe_executor(Box::new(TestCrtcConfigProbeExecutor::new(
            Rc::clone(&state),
            None,
        )));
        let output_key = pending.output_key_by_id[&output_id].clone();
        let prepared_output = clone_test_drm_output(&pending.platform.outputs[0].output);
        let route = pending.platform.outputs[0].scanout_route;
        let token = pending
            .enqueue_prepared_crtc_config_probe(
                output_id,
                output_key,
                connector,
                c0_3bi_changed_mode(),
                0,
                0,
                prepared_output,
                route,
            )
            .expect("the test probe executor accepts the copied job");
        assert!(pending.pending_crtc_config_probes[&token].was_active);
        assert_eq!(state.borrow().enqueued, vec![token]);

        // Applying a disable to one of two Owner outputs preserves the lit
        // survivor from installed power, not the stale global cache. Both
        // all-off and relight calls are recorded, never sent to DRM.
        let (mut apply, apply_device, first_id, first_connector) =
            c0_3bi_client_modeset_backend_with_output_count(StubBehaviour::NeverReply, 2);
        apply.owner_dpms_installed_active.insert(apply_device, true);
        apply.kms_outputs_active = false;
        apply.platform.dpms_output_calls_for_tests = Some(Vec::new());
        for output in &apply.platform.outputs {
            let ids = apply.randr_id_alloc.ids_for(&output.key);
            apply
                .output_key_by_id
                .insert(ids.output_id, output.key.clone());
        }
        assert!(
            apply
                .apply_crtc_config(first_id, &first_connector, None, 0, 0)
                .expect("the test DPMS recorder prevents hardware writes")
        );
        assert_eq!(apply.platform.outputs.len(), 1);
        assert!(apply.kms_outputs_active);
        let calls = apply
            .platform
            .dpms_output_calls_for_tests
            .as_ref()
            .expect("recorder remains installed");
        assert_eq!(calls.len(), 2);
        assert!(!calls[0].0, "legacy topology quiesce still goes all-off");
        assert!(calls[1].0, "the installed-power Owner survivor is relit");
        assert_eq!(calls[1].1, vec![apply.platform.outputs[0].key.clone()]);
        c0_3bi_assert_end_state(
            &direct,
            "c0_3bi_value_dead_reads_routed direct teardown",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
        c0_3bi_assert_end_state(
            &signature,
            "c0_3bi_value_dead_reads_routed signature freshness",
            &c0_3bi_expected_end_state([OutputKey::new(signature_device, "test")]),
        );
        Backend::cancel_crtc_config(&mut pending, token);
        c0_3bi_assert_end_state(
            &pending,
            "c0_3bi_value_dead_reads_routed pending qualification",
            &c0_3bi_expected_end_state([OutputKey::new(pending_device, "test")]),
        );
        c0_3bi_assert_end_state(
            &apply,
            "c0_3bi_value_dead_reads_routed Legacy disable",
            &c0_3bi_expected_end_state([OutputKey::new(apply_device, "test2")]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3bi_begin_on_owner_is_pending_vulkan() {
        use crate::kms::executor::test_support::{ScriptedReply, StubBehaviour};

        let (OwnerLiveFixture { mut backend, .. }, device, output_id, connector, mode) =
            c0_3bi_live_modeset_backend(
                StubBehaviour::Scripted(ScriptedReply::Accepted { mask: 0, fds: 0 }),
                false,
            )
            .expect("environmental skip: no live Vulkan modeset fixture");
        let result =
            Backend::begin_crtc_config(&mut backend, output_id, &connector, Some(mode), 0, 0)
                .expect("Owner begin succeeds asynchronously");
        let CrtcConfigApply::Pending(token) = result else {
            panic!("a non-idempotent Owner modeset must return Pending")
        };

        c0_3bi_drive_executor_ready(
            &mut backend,
            "c0_3bi_begin_on_owner_is_pending_vulkan executor reply",
        );
        let commit = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("TEST_ONLY acceptance dispatches the real transaction")
            .commit_id();
        c0_conv_cii_accept_direct_owner_commit(&mut backend, device, commit);
        let completion = backend.complete_owner_for_tests(0);
        assert!(c0_3bi_drive_owner_batch(
            &mut backend,
            device,
            completion,
            "c0_3bi_begin_on_owner_is_pending_vulkan owner event"
        ));

        assert!(
            backend
                .core_driver_announced_crtc_configs_for_tests
                .contains(&token),
            "the core-entry driver drained the CRTC-ready notification"
        );
        assert_eq!(
            backend
                .core_driver_finished_crtc_configs_for_tests
                .iter()
                .filter(|(announced, _)| *announced == token)
                .count(),
            1,
            "the core-entry driver finishes the announced token once"
        );
        assert!(c0_3bi_take_crtc_config_result(&mut backend, token).expect("promoted modeset"));
        assert!(
            !backend
                .core_driver_finished_crtc_configs_for_tests
                .iter()
                .any(|(announced, _)| *announced == token),
            "the single finished result was consumed"
        );
        assert_eq!(backend.platform.outputs[0].width, mode.width);
        assert_eq!(backend.platform.outputs[0].height, mode.height);
        assert_eq!(
            backend
                .randr_id_alloc
                .entry(&backend.output_key_by_id[&output_id])
                .unwrap()
                .config,
            super::ConnectorConfig::Enabled {
                mode_w: mode.width,
                mode_h: mode.height,
                vrefresh: mode.vrefresh,
                x: 0,
                y: 0,
            }
        );

        c0_3bi_assert_end_state(
            &backend,
            "c0_3bi_begin_on_owner_is_pending_vulkan",
            &c0_3bi_expected_end_state([OutputKey::new(device, connector.clone())]),
        );
    }

    #[test]
    fn c0_3bi_idempotent_request_dispatches_nothing() {
        use crate::kms::executor::test_support::StubBehaviour;

        let (mut backend, device, output_id, connector) =
            c0_3bi_client_modeset_backend(StubBehaviour::NeverReply);
        let output = &backend.platform.outputs[0];
        let mode = ModeSpec {
            width: output.width,
            height: output.height,
            vrefresh: output.output.picked.vrefresh,
        };
        let (x, y) = (output.x, output.y);
        let output_key = backend.output_key_by_id[&output_id].clone();
        backend.randr_id_alloc.entry_mut(&output_key).config = super::ConnectorConfig::Off;

        for _ in 0..2 {
            assert_eq!(
                Backend::begin_crtc_config(&mut backend, output_id, &connector, Some(mode), x, y,)
                    .expect("idempotent Owner reassert"),
                CrtcConfigApply::Applied(false)
            );
        }
        let (validation, live) = backend.lifecycle_drivers[&device].client_modeset_test_stats();
        assert!(validation.is_empty());
        assert!(live.is_empty());
        assert_eq!(
            backend.randr_id_alloc.entry(&output_key).unwrap().config,
            super::ConnectorConfig::Enabled {
                mode_w: mode.width,
                mode_h: mode.height,
                vrefresh: mode.vrefresh,
                x,
                y,
            },
            "idempotency keeps the registry synchronized with the installed layout"
        );

        c0_3bi_assert_end_state(
            &backend,
            "c0_3bi_idempotent_request_dispatches_nothing",
            &c0_3bi_expected_end_state([output_key.clone()]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3bi_cancel_before_and_after_dispatch_vulkan() {
        use crate::kms::executor::test_support::{ScriptedReply, StubBehaviour};

        let (
            OwnerLiveFixture {
                mut backend,
                cleanup_calls,
                ..
            },
            device,
            output_id,
            connector,
            mode,
        ) = c0_3bi_live_modeset_backend(
            StubBehaviour::Scripted(ScriptedReply::Accepted { mask: 0, fds: 0 }),
            false,
        )
        .expect("environmental skip: no live Vulkan modeset fixture");
        let token = c0_3bi_begin_client_modeset(&mut backend, output_id, &connector, Some(mode));
        let (keys, framebuffers) = c0_3bi_pending_prepared_pool_allocations(&backend, device);
        assert!(
            backend.lifecycle_drivers[&device]
                .client_modeset_test_stats()
                .1
                .is_empty(),
            "the live modeset has not crossed dispatch"
        );
        Backend::cancel_crtc_config(&mut backend, token);
        assert!(
            backend.lifecycle_drivers[&device].client_modeset.is_none(),
            "pre-dispatch cancellation releases the Owner slot"
        );
        c0_3bi_assert_prepared_pool_released(
            &backend,
            device,
            &keys,
            &framebuffers,
            &cleanup_calls,
        );
        assert!(Backend::drain_ready_crtc_configs(&mut backend).is_empty());

        let (OwnerLiveFixture { mut backend, .. }, device, output_id, connector, mode) =
            c0_3bi_live_modeset_backend(
                StubBehaviour::Scripted(ScriptedReply::Accepted { mask: 0, fds: 0 }),
                false,
            )
            .expect("environmental skip: no live Vulkan modeset fixture");
        let token = c0_3bi_begin_client_modeset(&mut backend, output_id, &connector, Some(mode));
        let commit = c0_3bi_dispatch_client_modeset(&mut backend, device);
        assert!(Backend::crtc_config_install_capable(&backend, token));
        Backend::cancel_crtc_config(&mut backend, token);
        assert!(
            Backend::crtc_config_install_capable(&backend, token),
            "dropping the token does not make a dispatched transaction cancellable"
        );

        c0_conv_cii_accept_direct_owner_commit(&mut backend, device, commit);
        let completion = backend.complete_owner_for_tests(0);
        c0_3aii_replace_owner_executor(&mut backend, StubBehaviour::AcceptProbeWith(305));
        assert!(c0_3bi_drive_owner_batch(
            &mut backend,
            device,
            completion,
            "c0_3bi_cancel_before_and_after_dispatch_vulkan owner event"
        ));
        assert!(backend.lifecycle_drivers[&device].client_modeset.is_none());
        assert_eq!(backend.platform.outputs[0].width, mode.width);
        assert_eq!(backend.platform.outputs[0].height, mode.height);
        assert!(!Backend::crtc_config_install_capable(&backend, token));
        assert!(Backend::drain_ready_crtc_configs(&mut backend).is_empty());
        assert!(!backend.ready_client_modeset_results.contains_key(&token));

        c0_3bi_assert_end_state(
            &backend,
            "c0_3bi_cancel_before_and_after_dispatch_vulkan",
            &c0_3bi_expected_end_state([OutputKey::new(device, connector.clone())]),
        );
    }

    #[test]
    fn c0_3bi_legacy_path_unchanged() {
        let mut backend = KmsBackend::for_tests();
        push_test_output(&mut backend, 2);
        // Record the all-off/relight sequence so the test cannot issue a DRM
        // write. This fixture has no Owner transport gate.
        backend.kms_outputs_active = true;
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let output_key = backend.platform.outputs[0].key.clone();
        let ids = backend.randr_id_alloc.ids_for(&output_key);
        backend
            .output_key_by_id
            .insert(ids.output_id, output_key.clone());

        assert_eq!(
            Backend::begin_crtc_config(
                &mut backend,
                ids.output_id,
                &output_key.connector_name,
                None,
                0,
                0,
            )
            .expect("Legacy disable remains synchronous"),
            CrtcConfigApply::Applied(true)
        );
        assert!(backend.lifecycle_drivers.is_empty());
        let calls = backend
            .platform
            .dpms_output_calls_for_tests
            .as_ref()
            .expect("Legacy DPMS recorder");
        assert_eq!(calls.len(), 2);
        assert!(
            !calls[0].0,
            "Legacy CRTC mutation first turns all outputs off"
        );
        assert!(calls[1].0, "Legacy CRTC mutation relights the survivor");
        assert_eq!(calls[1].1, vec![backend.platform.outputs[0].key.clone()]);
        let surviving_output = calls[1]
            .1
            .first()
            .cloned()
            .expect("the scenario asserts one surviving installed output");

        c0_3bi_assert_end_state(
            &backend,
            "c0_3bi_legacy_path_unchanged",
            &c0_3bi_expected_end_state([surviving_output]),
        );
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct C0_3biModesetState {
        changed: bool,
        registry: Option<(super::ConnectorConfig, bool, bool, bool)>,
        outputs: Vec<(OutputKey, u16, u16, u32, i32, i32)>,
        framebuffer: (u16, u16),
    }

    fn c0_3bi_modeset_state(
        backend: &super::KmsBackend,
        output_key: &OutputKey,
        changed: bool,
    ) -> C0_3biModesetState {
        let registry = backend.randr_id_alloc.entry(output_key).map(|entry| {
            (
                entry.config,
                entry.crtc_associated,
                entry.client_configured,
                entry.connected,
            )
        });
        let outputs = backend
            .platform
            .outputs
            .iter()
            .map(|output| {
                (
                    output.key.clone(),
                    output.width,
                    output.height,
                    output.output.picked.vrefresh,
                    output.x,
                    output.y,
                )
            })
            .collect();
        C0_3biModesetState {
            changed,
            registry,
            outputs,
            framebuffer: (backend.platform.fb_w, backend.platform.fb_h),
        }
    }

    fn c0_3bi_legacy_script_step(
        backend: &mut super::KmsBackend,
        output_id: u32,
        connector: &str,
        mode: Option<ModeSpec>,
    ) -> bool {
        let CrtcConfigApply::Applied(changed) =
            Backend::begin_crtc_config(backend, output_id, connector, mode, 0, 0)
                .expect("Legacy synchronous CRTC configuration")
        else {
            panic!("same-device Legacy configuration must remain synchronous")
        };
        assert!(Backend::drain_ready_crtc_configs(backend).is_empty());
        changed
    }

    fn c0_3bi_owner_script_step(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        output_id: u32,
        connector: &str,
        mode: Option<ModeSpec>,
        sequence: u64,
    ) -> bool {
        use crate::kms::executor::test_support::StubBehaviour;

        // The stub's /dev/null out-fences are placeholders; completion is
        // supplied below as a synthetic HardwareComplete/DRM event pair.
        backend.platform.owner_completion_detached = true;
        let owner_output_count = backend
            .platform
            .outputs
            .iter()
            .filter(|output| output.key.device_key == device)
            .count();
        c0_3bi_complete_owner_followups(
            backend,
            device,
            owner_output_count.saturating_add(8),
            "settle prior Owner work before replacing the script executor",
        );
        assert!(
            backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.live_record())
                .is_none(),
            "script executor replacement must not strand a live Owner request"
        );
        // The stub answers validation, live commit, and any probe through the
        // executor channel; the core-entry completion helper supplies only the
        // kernel's fence and DRM-event effects.
        c0_3aii_replace_owner_executor(backend, StubBehaviour::AcceptKernelCalls(sequence));
        let result = Backend::begin_crtc_config(backend, output_id, connector, mode, 0, 0)
            .expect("Owner CRTC configuration begin");
        let CrtcConfigApply::Pending(token) = result else {
            assert_eq!(
                result,
                CrtcConfigApply::Applied(false),
                "only an idempotent Owner request returns synchronously"
            );
            assert!(Backend::drain_ready_crtc_configs(backend).is_empty());
            return false;
        };

        let commit = c0_3bi_wait_client_modeset_live(
            backend,
            device,
            token,
            "scripted client modeset live dispatch",
        );
        c0_3bi_wait_owner_commit_accepted(
            backend,
            device,
            commit,
            "accept scripted client modeset",
        );
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device,
            commit,
            "scripted client modeset owner completion",
        );
        let owner_output_count = backend
            .platform
            .outputs
            .iter()
            .filter(|output| output.key.device_key == device)
            .count();
        c0_3bi_complete_owner_followups(
            backend,
            device,
            owner_output_count.saturating_add(8),
            "scripted client modeset follow-up completion",
        );
        let changed = c0_3bi_take_crtc_config_result(backend, token)
            .expect("terminal Owner client modeset result");
        if mode.is_some() {
            c0_3bi_core_driver_until(
                backend,
                "scripted promoted-output clock probe",
                std::time::Duration::from_secs(3),
                &|backend| {
                    backend
                        .host_call_events_for_tests
                        .lock()
                        .unwrap()
                        .iter()
                        .any(|event| {
                            matches!(
                                event.kind,
                                crate::kms::executor::ObservedOutcome::ProbeAccepted {
                                    sequence: actual
                                } if actual == sequence
                            )
                        })
                },
                None,
            )
            .unwrap_or_else(|error| panic!("{error}"));
            let observations = backend.drained_host_call_events_for_tests();
            assert!(
                observations.iter().any(|event| matches!(
                    event.kind,
                    crate::kms::executor::ObservedOutcome::ProbeAccepted { sequence: actual }
                        if actual == sequence
                )),
                "lighting promotion must probe its new clock epoch"
            );
        }
        changed
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3bi_modeset_differential_backend_state_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;

        // Run the Legacy production entry first, with only its final DRM
        // commit and all-off/relight calls recorded. The fixture uses real
        // Vulkan allocations but never takes DRM master or submits a modeset.
        let (OwnerLiveFixture { mut backend, .. }, device, output_id, connector, _fixture_mode) =
            c0_3bi_live_modeset_backend(StubBehaviour::NeverReply, false)
                .expect("environmental skip: no live Vulkan modeset fixture");
        let output_key = backend.output_key_by_id[&output_id].clone();
        let initial_mode = {
            let output = &backend.platform.outputs[0];
            ModeSpec {
                width: output.width,
                height: output.height,
                vrefresh: output.output.picked.vrefresh,
            }
        };
        let modes = backend.platform.outputs[0]
            .output
            .modes
            .iter()
            .map(|mode| ModeSpec {
                width: mode.width,
                height: mode.height,
                vrefresh: mode.vrefresh,
            })
            .collect::<Vec<_>>();
        let mode_pair = modes
            .iter()
            .copied()
            .filter(|mode| mode.width != initial_mode.width || mode.height != initial_mode.height)
            .find_map(|mode_change| {
                modes
                    .iter()
                    .copied()
                    .find(|mode| {
                        mode.width == mode_change.width
                            && mode.height == mode_change.height
                            && mode.vrefresh != mode_change.vrefresh
                    })
                    .map(|refresh_only| (mode_change, refresh_only))
            });
        let (mode_change, refresh_only) = mode_pair.unwrap_or_else(|| {
            panic!(
                "differential fixture requires a distinct-resolution mode plus a second refresh at that resolution; advertised modes: {modes:?}"
            )
        });

        let incarnation = backend
            .platform
            .owner_ref(device)
            .expect("live fixture Owner identity")
            .incarnation();
        backend.platform.install_transport_gate(
            crate::kms::render::resources::TransportGate::new_legacy(
                device,
                incarnation,
                Box::new(backend.direct_ownership_handle()),
            ),
        );
        backend.admission_conductors.remove(&device);
        backend.lifecycle_drivers.remove(&device);
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());
        backend.platform.modeset_calls_for_tests = Some(Vec::new());

        assert!(c0_3bi_legacy_script_step(
            &mut backend,
            output_id,
            &connector,
            None,
        ));
        let mut legacy_steps = Vec::new();
        for (mode, label) in [
            (Some(initial_mode), "enable"),
            (Some(mode_change), "mode change"),
            (Some(refresh_only), "refresh-only change"),
            (Some(refresh_only), "idempotent repeat"),
            (None, "disable"),
            (Some(initial_mode), "re-enable"),
        ] {
            let changed = c0_3bi_legacy_script_step(&mut backend, output_id, &connector, mode);
            assert_eq!(changed, label != "idempotent repeat", "Legacy {label}");
            legacy_steps.push(c0_3bi_modeset_state(&backend, &output_key, changed));
        }
        assert!(
            backend
                .platform
                .modeset_calls_for_tests
                .as_ref()
                .is_some_and(|calls| calls.len() >= 4),
            "Legacy enables and mode changes still use the synchronous modeset writer"
        );
        drop(backend);

        // The Owner uses the same advertised modes and requests. Its live
        // commit is accepted by the stubbed executor, so no hardware modeset
        // can occur in this differential test.
        let (
            OwnerLiveFixture { mut backend, .. },
            device,
            output_id,
            owner_connector,
            _fixture_mode,
        ) = c0_3bi_live_modeset_backend(StubBehaviour::NeverReply, false)
            .expect("environmental skip: no live Vulkan modeset fixture");
        assert_eq!(owner_connector, connector);
        let owner_key = backend.output_key_by_id[&output_id].clone();
        let disable =
            c0_3bi_owner_script_step(&mut backend, device, output_id, &owner_connector, None, 401);
        assert!(disable);
        let mut owner_steps = Vec::new();
        for (mode, label, sequence) in [
            (Some(initial_mode), "enable", 402),
            (Some(mode_change), "mode change", 403),
            (Some(refresh_only), "refresh-only change", 404),
            (Some(refresh_only), "idempotent repeat", 405),
            (None, "disable", 406),
            (Some(initial_mode), "re-enable", 407),
        ] {
            let changed = c0_3bi_owner_script_step(
                &mut backend,
                device,
                output_id,
                &owner_connector,
                mode,
                sequence,
            );
            assert_eq!(changed, label != "idempotent repeat", "Owner {label}");
            owner_steps.push(c0_3bi_modeset_state(&backend, &owner_key, changed));
        }
        assert_eq!(owner_steps, legacy_steps);

        c0_3bi_assert_end_state(
            &backend,
            "c0_3bi_modeset_differential_backend_state_vulkan",
            &c0_3bi_expected_end_state([owner_key.clone()]),
        );
    }

    fn c0_3aii_compose_from_scene(backend: &mut super::KmsBackend, output_idx: usize) {
        backend.scene.mark_scene_structure_damage_rect(
            output_idx,
            ash::vk::Rect2D {
                offset: ash::vk::Offset2D::default(),
                extent: ash::vk::Extent2D {
                    width: 19,
                    height: 23,
                },
            },
        );
        backend.tick_maybe_composite_for_tests_without_render_completion_drain();
        backend.platform.wait_idle_bounded();
        backend.drain_scanout_render_completions_for_tests();
    }

    fn c0_3aii_owner_current_framebuffer(
        backend: &mut super::KmsBackend,
        output_idx: usize,
    ) -> Option<::drm::control::framebuffer::Handle> {
        backend
            .scene
            .owner_current_framebuffer(
                output_idx,
                None,
                backend.resource_service.as_mut().expect("resource service"),
            )
            .expect("read current Owner framebuffer")
    }

    fn c0_3aii_current_composed_allocation(
        backend: &super::KmsBackend,
    ) -> crate::kms::render::resources::AllocationKey {
        backend
            .commit_consumer
            .current_resources
            .iter()
            .find(|resources| resources.direct_role.is_none())
            .and_then(|resources| resources.allocations.first())
            .expect("current composed Owner allocation")
            .key()
    }

    fn c0_3aii_current_direct_allocation(
        backend: &super::KmsBackend,
    ) -> crate::kms::render::resources::AllocationKey {
        backend
            .commit_consumer
            .current_resources
            .iter()
            .find(|resources| {
                resources.direct_role.as_ref().is_some_and(|role| {
                    role.role() == crate::kms::render::resources::DirectRole::Current
                })
            })
            .and_then(|resources| resources.allocations.first())
            .expect("current direct Owner allocation")
            .key()
    }

    fn c0_3aii_accept_and_complete_live_record(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
    ) {
        let commit = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("Owner live record")
            .commit_id();
        c0_conv_cii_accept_direct_owner_commit(backend, device, commit);
        let completion = backend.complete_owner_for_tests(0);
        c0_3aii_replace_owner_executor(
            backend,
            crate::kms::executor::test_support::StubBehaviour::NeverReply,
        );
        assert!(c0_3bi_drive_owner_batch(
            backend,
            device,
            completion,
            "complete Owner live record"
        ));
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3aii_off_waits_for_the_accepted_predecessor_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;

        let mut fixture = owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let backend = &mut fixture.backend;
        let device = backend.platform.primary_device().expect("Owner device").key;
        let output_idx = 0;
        backend.scene.mark_scene_structure_dirty();
        backend.tick_maybe_composite_for_tests_without_render_completion_drain();
        backend.platform.wait_idle_bounded();
        backend.drain_scanout_render_completions_for_tests();
        let predecessor = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("production composed offer dispatches")
            .commit_id();
        c0_conv_cii_accept_direct_owner_commit(backend, device, predecessor);
        assert!(
            backend
                .device_owner_for_tests(0)
                .live_record()
                .expect("accepted composed predecessor")
                .milestones()
                .accepted
        );

        let admission_trace_before = backend.admission_trace_for_tests(device);
        Backend::set_dpms_power(backend, 3).expect("queue DPMS off behind predecessor");
        assert_eq!(
            backend
                .device_owner_for_tests(0)
                .live_record()
                .expect("predecessor remains current")
                .commit_id(),
            predecessor,
            "DPMS must not replace an accepted composed Owner record"
        );
        assert!(
            backend
                .lifecycle_drivers
                .get(&device)
                .expect("Owner lifecycle driver")
                .pending_topology_validation_commits_for_tests()
                .is_empty(),
            "off cannot run TEST_ONLY before predecessor terminalization"
        );
        assert_eq!(
            backend.admission_trace_for_tests(device),
            admission_trace_before,
            "the lifecycle closure must not enter admission while the predecessor is accepted"
        );

        c0_3aii_prepare_lifecycle_clock(backend, device);
        c0_3aii_replace_owner_executor(
            backend,
            StubBehaviour::Scripted(
                crate::kms::executor::test_support::ScriptedReply::Accepted { mask: 0, fds: 0 },
            ),
        );
        let predecessor_completion = backend.complete_owner_for_tests(0);
        assert!(backend.route_owner_event_batch(
            device,
            predecessor_completion,
            std::time::Instant::now(),
        ));
        wait_executor_readable_for_tests(backend, std::time::Duration::from_secs(5));
        Backend::on_executor_readable(backend, &mut ServerState::new());
        let off = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("off topology dispatch follows predecessor retirement")
            .commit_id();
        assert_ne!(off, predecessor);
        c0_3aii_accept_and_complete_live_record(backend, device);
        assert!(!backend.owner_outputs_powered_on(device));
        assert!(
            backend
                .scene
                .owner_current_framebuffer(
                    output_idx,
                    None,
                    backend.resource_service.as_mut().expect("resource service")
                )
                .expect("retained current buffer")
                .is_some()
        );
        c0_3bi_assert_end_state(
            backend,
            "c0_3aii_off_waits_for_the_accepted_predecessor_vulkan",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3aii_composed_waits_while_off_vulkan() {
        use crate::kms::owner::admission::{IntentKey, Readiness, WaitReason};

        let mut fixture = owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let backend = &mut fixture.backend;
        let device = backend.platform.primary_device().expect("Owner device").key;
        c0_conv_ciii_establish_composed_return(backend, device);
        c0_3aii_apply_dpms_transition(backend, device, 3);

        c0_3aii_compose_from_scene(backend, 0);
        assert!(
            backend.device_owner_for_tests(0).live_record().is_none(),
            "a composed offer must not dispatch while its CRTC is off"
        );
        let (&crtc, &generation) = backend
            .admission_conductors
            .get(&device)
            .expect("Owner conductor")
            .composed
            .iter()
            .next()
            .expect("offscreen scene compose must offer a generation");
        assert_eq!(
            backend
                .admission_snapshot(device, false)
                .expect("off Owner snapshot")
                .readiness(IntentKey::Composed { crtc, generation }),
            Some(Readiness::Waiting(WaitReason::OutputPoweredOff))
        );
        c0_3aii_apply_dpms_transition(backend, device, 0);
        let full = backend
            .scene
            .scene_structure_damage_for_tests(0)
            .expect("scene structure damage after on");
        assert!(
            full.iter().any(|rect| {
                rect.offset == ash::vk::Offset2D::default()
                    && rect.extent.width == u32::from(backend.platform.outputs[0].width)
                    && rect.extent.height == u32::from(backend.platform.outputs[0].height)
            }),
            "applied on marks the Owner scene for a full frame"
        );

        c0_3aii_compose_from_scene(backend, 0);
        let composed = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("ordinary composed admission reopens after on");
        assert!(composed.closure().expected_completion().contains(&crtc));
        c0_3aii_accept_and_complete_live_record(backend, device);
        c0_3bi_assert_end_state(
            backend,
            "c0_3aii_composed_waits_while_off_vulkan",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3aii_owner_ignores_kms_outputs_active_vulkan() {
        use crate::kms::{
            owner::admission::{IntentKey, Readiness, WaitReason},
            render::cursor::{ActiveCursorAnim, AnimCursorRecord, AnimFrame, CursorRecord},
        };
        use std::time::{Duration, Instant};

        let mut fixture = owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let backend = &mut fixture.backend;
        let device = backend.platform.primary_device().expect("Owner device").key;
        backend
            .scene
            .test_set_cursor_mode(crate::kms::render::scene::CursorPlaneMode::Hw);

        // With Owner power on, the Legacy cache is deliberately wrong. The
        // production composition path must still establish the composed
        // return required by admission.
        backend.kms_outputs_active = false;
        backend.scene.scene_structure_dirty = true;
        let owner_scene_wakeup = Backend::next_wakeup(backend);
        let scene_wakeup_checked = Instant::now();
        assert!(
            owner_scene_wakeup.is_some_and(|deadline| deadline <= scene_wakeup_checked),
            "Owner-on scene wakeup remains immediate with the Legacy cache false \
             (wants_compose={} output_ready={} retry={:?} wake={owner_scene_wakeup:?})",
            backend.scene_wants_compose(),
            backend.scene.has_output_ready_for_submit(),
            backend.scene.earliest_retry_deadline(),
        );
        c0_conv_ciii_establish_composed_return(backend, device);

        let anim_handle = 0xC0D2_6001;
        let first = CursorRecord::new(1, 1, 0, 0, vec![0x11, 0, 0, 0xff], 1);
        let second = CursorRecord::new(1, 1, 0, 0, vec![0x22, 0, 0, 0xff], 2);
        backend
            .cursor_records
            .insert(anim_handle, std::sync::Arc::clone(&first));
        backend.anim_cursor_records.insert(
            anim_handle,
            AnimCursorRecord {
                frames: vec![
                    AnimFrame {
                        source: anim_handle,
                        record: first,
                        pixmap: None,
                        delay: Duration::from_secs(60),
                    },
                    AnimFrame {
                        source: anim_handle,
                        record: second,
                        pixmap: None,
                        delay: Duration::from_secs(60),
                    },
                ],
            },
        );
        backend.active_cursor_anim = Some(ActiveCursorAnim {
            handle: anim_handle,
            frame: 0,
            next_frame: Instant::now() - Duration::from_millis(1),
        });

        backend.tick_cursor_animation();
        assert_eq!(
            backend.active_cursor_anim.as_ref().unwrap().frame,
            1,
            "Owner-on cursor tick follows installed power with the Legacy cache false"
        );
        let cursor_deadline = Instant::now() + Duration::from_secs(60);
        backend.active_cursor_anim.as_mut().unwrap().next_frame = cursor_deadline;
        assert_eq!(
            backend.cursor_anim_deadline(),
            Some(cursor_deadline),
            "Owner-on cursor deadline follows installed power with the Legacy cache false"
        );
        assert_eq!(
            Backend::next_wakeup(backend),
            Some(cursor_deadline),
            "next_wakeup keeps the Owner cursor timer despite the Legacy cache false"
        );

        let candidate = c0_direct_eligibility_candidate(backend, 0xC0D2, 0xC0D3, 0xC0D4, 0);
        assert!(
            c0_direct_pure_eligibility(backend, &candidate),
            "the pure direct predicate reads the candidate Owner device's installed power"
        );
        assert!(
            backend.direct_present_eligibility(candidate).eligible,
            "Owner-on direct eligibility ignores the Legacy cache false"
        );
        assert!(
            !backend.present_scanout_blackout(candidate.crtc_id),
            "Owner-on blackout follows installed power with the Legacy cache false"
        );

        let probe_rejects_before = backend.scanout_m0.m1_probe_reject;
        let m1_open_before = backend.scanout_m0.m1_gate_open;
        let output_rejects_before = backend.scanout_m0.m1_gate_reject_outputs;
        backend.observe_scanout_m0(candidate);
        assert_eq!(
            backend.scanout_m0.m1_probe_reject,
            probe_rejects_before + 1,
            "the Owner-on M1 probe reaches its topology check despite the Legacy cache false"
        );
        assert_eq!(
            backend.scanout_m0.m1_gate_open,
            m1_open_before + 1,
            "the Owner-on M0 observation reports its candidate output powered"
        );
        assert_eq!(
            backend.scanout_m0.m1_gate_reject_outputs, output_rejects_before,
            "the Owner-on M0 observation does not reject the output from the Legacy cache"
        );

        c0_3aii_apply_dpms_transition(backend, device, 3);
        assert!(!backend.owner_outputs_powered_on(device));
        backend.kms_outputs_active = true;
        let source_id = backend
            .store
            .lookup(candidate.src_host_xid)
            .expect("M1 test source");
        backend.scanout_m1.remove(source_id);

        assert!(
            !c0_direct_pure_eligibility(backend, &candidate),
            "the pure direct predicate refuses an Owner-off candidate despite the Legacy cache true"
        );
        assert!(
            !backend.direct_present_eligibility(candidate).eligible,
            "Owner-off direct eligibility follows installed power with the Legacy cache true"
        );
        assert!(
            backend.present_scanout_blackout(candidate.crtc_id),
            "Owner-off blackout follows installed power with the Legacy cache true"
        );

        let probe_rejects_before_off = backend.scanout_m0.m1_probe_reject;
        let m1_open_before_off = backend.scanout_m0.m1_gate_open;
        let output_rejects_before_off = backend.scanout_m0.m1_gate_reject_outputs;
        backend.observe_scanout_m0(candidate);
        assert_eq!(
            backend.scanout_m0.m1_probe_reject, probe_rejects_before_off,
            "the Owner-off M1 probe is closed before its topology check despite the Legacy cache true"
        );
        assert_eq!(
            backend.scanout_m0.m1_gate_open, m1_open_before_off,
            "the Owner-off M0 observation never reports an open power gate"
        );
        assert_eq!(
            backend.scanout_m0.m1_gate_reject_outputs,
            output_rejects_before_off + 1,
            "the Owner-off M0 observation records its per-output power refusal"
        );

        let cursor_frame_off = backend.active_cursor_anim.as_ref().unwrap().frame;
        backend.active_cursor_anim.as_mut().unwrap().next_frame =
            Instant::now() - Duration::from_millis(1);
        backend.tick_cursor_animation();
        assert_eq!(
            backend.active_cursor_anim.as_ref().unwrap().frame,
            cursor_frame_off,
            "Owner-off cursor tick stays parked despite the Legacy cache true"
        );
        assert_eq!(
            backend.cursor_anim_deadline(),
            None,
            "Owner-off cursor deadline is suppressed despite the Legacy cache true"
        );

        c0_3aii_compose_from_scene(backend, 0);
        assert!(
            backend.device_owner_for_tests(0).live_record().is_none(),
            "off-screen composition ticks, but no commit is submitted to the dark Owner CRTC"
        );
        let (&crtc, &generation) = backend
            .admission_conductors
            .get(&device)
            .expect("Owner conductor")
            .composed
            .iter()
            .next()
            .expect("composition runs while Owner output is off");
        assert_eq!(
            backend
                .admission_snapshot(device, false)
                .expect("Owner readiness snapshot")
                .readiness(IntentKey::Composed { crtc, generation }),
            Some(Readiness::Waiting(WaitReason::OutputPoweredOff)),
            "off-screen generation waits for Owner power reconciliation"
        );
        let before_wakeup = Instant::now();
        assert!(
            Backend::next_wakeup(backend).is_none_or(|deadline| deadline > before_wakeup),
            "an OutputPoweredOff generation never gives next_wakeup an immediate scene deadline"
        );
        c0_3bi_assert_end_state(
            backend,
            "c0_3aii_owner_ignores_kms_outputs_active_vulkan",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    #[test]
