    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_composed_readiness_waits_for_clock_probe_vulkan() {
        use crate::kms::owner::{
            admission::{IntentKey, Readiness, WaitReason},
            clock::{ClockSource, ProbeOutcome, ProbeState},
        };

        let mut fixture = owner_live_fixture().expect("environmental skip: no live Vulkan ICD");
        let backend = &mut fixture.backend;
        let device = backend.platform.outputs[0].key.device_key;
        let crtc = u32::from(backend.platform.outputs[0].output.crtc);
        let clock_key = backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.clock_key_for_hardware_crtc(crtc))
            .expect("the live Owner output has an installed clock epoch");

        // Compose and offer a real backend-owned generation while lifecycle
        // admission is held, so the test can put the clock epoch into the
        // failed-probe state before asking the admission snapshot.
        backend
            .admission_conductors
            .get_mut(&device)
            .expect("Owner conductor")
            .lifecycle_admission_closed = true;
        let mut state = ServerState::new();
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "resolve the startup Owner clock before preparing the composed generation",
            std::time::Duration::from_secs(5),
            &|backend| {
                backend
                    .platform
                    .owner_ref(device)
                    .and_then(|owner| owner.clock(clock_key))
                    .is_some_and(|clock| matches!(clock.probe, ProbeState::Succeeded))
            },
            None,
        )
        .expect("the test starts from a resolved Owner clock epoch");
        backend.scene.mark_scene_structure_dirty();
        c0_3bi_core_driver_until_mode(
            backend,
            &mut state,
            "prepare composed generation behind the Owner startup gate",
            std::time::Duration::from_secs(5),
            &|backend| {
                let Some((_, generation, waiting)) = backend.scene.owner_prepared_for_tests(0)
                else {
                    return false;
                };
                !waiting
                    && backend
                        .scene
                        .owner_state_for_generation_for_tests(0, generation)
                        == Some(crate::kms::render::owner_buffer::OwnerBufferState::Desired)
                    && backend.scene.owner_composed_ready(0, generation)
                    && backend
                        .admission_conductors
                        .get(&device)
                        .is_some_and(|conductor| conductor.composed.get(&crtc) == Some(&generation))
            },
            None,
            false,
            true,
        )
        .expect("the composed Owner generation is offered while admission is closed");
        let queued_generation = backend
            .admission_conductors
            .get(&device)
            .and_then(|conductor| conductor.composed.get(&crtc))
            .copied()
            .expect("queued composed generation");
        let scene_ready_before_probe_failure =
            backend.scene.owner_composed_ready(0, queued_generation);
        let clock_state = {
            let clock = backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.clock(clock_key))
                .expect("installed Owner clock");
            (
                clock.source,
                clock.probe,
                clock.probe_outcome,
                clock.reference,
                clock.queue_failed,
            )
        };
        {
            let clock = backend
                .platform
                .owner_for(device)
                .expect("Owner")
                .clock_mut(clock_key)
                .expect("installed Owner clock");
            clock.source = ClockSource::Unresolved;
            clock.probe = ProbeState::Failed;
            clock.probe_outcome = Some(ProbeOutcome::Rejected {
                errno: libc::EINVAL,
            });
            clock.reference = None;
            clock.queue_failed = false;
        }

        let snapshot = backend
            .admission_snapshot(device, false)
            .expect("active Owner readiness snapshot");
        assert_eq!(
            snapshot.readiness(IntentKey::Composed {
                crtc,
                generation: backend
                    .admission_conductors
                    .get(&device)
                    .and_then(|conductor| conductor.composed.get(&crtc))
                    .copied()
                    .expect("queued composed generation"),
            }),
            Some(Readiness::Waiting(WaitReason::SourceWaits)),
            "a composed generation cannot be ready until its Owner clock probe succeeds"
        );
        assert!(
            backend
                .admission_conductors
                .get(&device)
                .is_some_and(|conductor| conductor.composed.contains_key(&crtc)),
            "the scene damage has produced and retained the composed generation"
        );

        backend
            .admission_conductors
            .get_mut(&device)
            .expect("Owner conductor")
            .lifecycle_admission_closed = false;
        let blocked_outcome = backend.admission_wake(device, false);
        let scene_ready_after_blocked_wake =
            backend.scene.owner_composed_ready(0, queued_generation);
        assert_eq!(
            blocked_outcome,
            crate::kms::render::admission::AdmissionOutcome::NothingAdmissible,
            "the queued generation stays in the conductor until its clock probe succeeds"
        );
        assert!(
            backend
                .admission_trace_for_tests(device)
                .iter()
                .all(|step| !matches!(
                    step,
                    crate::kms::render::admission::AdmissionTraceStep::Decided
                )),
            "a clock-blocked composed generation does not reach an admission decision"
        );
        assert!(
            backend
                .platform
                .owner_ref(device)
                .is_some_and(|owner| owner.live_record().is_none()),
            "an unresolved Owner clock cannot reach begin/send"
        );

        {
            let clock = backend
                .platform
                .owner_for(device)
                .expect("Owner")
                .clock_mut(clock_key)
                .expect("installed Owner clock");
            (
                clock.source,
                clock.probe,
                clock.probe_outcome,
                clock.reference,
                clock.queue_failed,
            ) = clock_state;
        }
        let dispatch_trace_start = backend.admission_trace_for_tests(device).len();
        let outcome = backend.admission_wake(device, false);
        let composed_generation = backend
            .admission_conductors
            .get(&device)
            .and_then(|conductor| conductor.composed.get(&crtc))
            .copied();
        let scene_ready = composed_generation
            .is_some_and(|generation| backend.scene.owner_composed_ready(0, generation));
        let readiness_after_retry = composed_generation.and_then(|generation| {
            backend
                .admission_snapshot(device, false)
                .and_then(|snapshot| snapshot.readiness(IntentKey::Composed { crtc, generation }))
        });
        if !matches!(
            &outcome,
            crate::kms::render::admission::AdmissionOutcome::Dispatched(_)
        ) {
            c0_3bi_core_driver_until_with_state(
                backend,
                &mut state,
                "observe render readiness and dispatch the retained composed generation",
                std::time::Duration::from_secs(5),
                &|backend| {
                    backend
                        .admission_trace_for_tests(device)
                        .iter()
                        .skip(dispatch_trace_start)
                        .any(|step| {
                            matches!(
                                step,
                                crate::kms::render::admission::AdmissionTraceStep::Dispatched(_)
                            )
                        })
                        && backend
                            .platform
                            .owner_ref(device)
                            .and_then(|owner| owner.live_record())
                            .is_some()
                },
                None,
            )
            .unwrap_or_else(|error| {
                panic!(
                    "{error}; initial_outcome={outcome:?}; clock={:?}; scene_ready={scene_ready}; \
                     readiness_after_retry={readiness_after_retry:?}; conductor={:?}; live={:?}; \
                     core_entries={:?}",
                    backend
                        .platform
                        .owner_ref(device)
                        .and_then(|owner| owner.clock(clock_key))
                        .map(|clock| (
                            clock.source,
                            clock.probe,
                            clock.reference,
                            clock.queue_failed
                        )),
                    backend.admission_conductors.get(&device).map(|conductor| (
                        conductor.composed.clone(),
                        conductor.last_readiness_for_tests.clone(),
                        conductor.last_decision_for_tests.clone(),
                    )),
                    backend
                        .platform
                        .owner_ref(device)
                        .and_then(|owner| owner.live_record())
                        .map(|record| (record.commit_id(), record.state(), record.milestones())),
                    backend.core_entry_trace_for_tests.borrow(),
                )
            });
        }
        let dispatched_after_probe = backend
            .admission_trace_for_tests(device)
            .iter()
            .skip(dispatch_trace_start)
            .any(|step| {
                matches!(
                    step,
                    crate::kms::render::admission::AdmissionTraceStep::Dispatched(_)
                )
            });
        assert!(
            dispatched_after_probe,
            "a successful Owner clock probe dispatches the retained generation; \
             outcome={outcome:?}; clock={:?}; scene_ready={scene_ready}; \
             scene_ready_before_probe_failure={scene_ready_before_probe_failure}; \
             scene_ready_after_blocked_wake={scene_ready_after_blocked_wake}; \
             readiness_after_retry={readiness_after_retry:?}; conductor={:?}; live={:?}",
            backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.clock(clock_key))
                .map(|clock| (
                    clock.source,
                    clock.probe,
                    clock.reference,
                    clock.queue_failed
                )),
            backend.admission_conductors.get(&device).map(|conductor| (
                conductor.composed.clone(),
                conductor.last_readiness_for_tests.clone(),
                conductor.last_decision_for_tests.clone(),
            )),
            backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.live_record())
                .map(|record| (record.commit_id(), record.state(), record.milestones()))
        );
    }

    /// Keep the unrelated Owner's accepted repaint from reaching its watchdog
    /// while the other device is intentionally stalled for CompletionUnknown.
    fn c0_3cii_wait_for_partial_unknown_while_settling_peer(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        stalled_device: DrmDeviceKey,
        stalled_commit: crate::kms::owner::identity::CommitId,
        peer_device: DrmDeviceKey,
        episode_id: u64,
        delivery_start: usize,
        stalled_ids: crate::kms::render::backend::ConnectorIds,
        label: &str,
    ) -> Result<(), String> {
        use std::time::Instant;

        let deadline = Instant::now() + std::time::Duration::from_secs(5);
        let target_reached = |backend: &super::KmsBackend| {
            backend.acquire_episode.is_none()
                && backend.hotplug_episode.is_none()
                && backend
                    .lifecycle_coordinator
                    .device(&stalled_device)
                    .is_some_and(|arbiter| {
                        arbiter.state()
                            == crate::kms::owner::lifecycle::DeviceLifecycleState::ExecutorStalled
                    })
                && backend
                    .platform
                    .owner_ref(stalled_device)
                    .and_then(|owner| owner.live_record())
                    .is_some_and(|record| record.commit_id() == stalled_commit)
                && backend.core_entry_deliveries_for_tests[delivery_start..]
                    .iter()
                    .any(|delivery| {
                        matches!(
                            delivery,
                            yserver_core::core_loop::run::CoreEntryDelivery::TopologyEpisodeBegin(
                                delivered_episode
                            ) if *delivered_episode == episode_id
                        )
                    })
                && backend.core_entry_deliveries_for_tests[delivery_start..]
                    .iter()
                    .any(|delivery| {
                        matches!(
                            delivery,
                            yserver_core::core_loop::run::CoreEntryDelivery::UrgentWithdrawal {
                                output_ids,
                                crtc_ids,
                            } if output_ids == &[stalled_ids.output_id]
                                && crtc_ids == &[stalled_ids.crtc_id]
                        )
                    })
                && backend.core_entry_deliveries_for_tests[delivery_start..]
                    .iter()
                    .any(|delivery| {
                        matches!(
                            delivery,
                            yserver_core::core_loop::run::CoreEntryDelivery::TopologyEpisodeEnd {
                                episode_id: delivered_episode,
                                published: true,
                            } if *delivered_episode == episode_id
                        )
                    })
        };
        let peer_fast_update = |backend: &super::KmsBackend| {
            backend
                .platform
                .owner_ref(peer_device)
                .and_then(|owner| owner.live_record())
                .filter(|record| {
                    record.completion_context().class
                        == crate::kms::owner::completion::CompletionClass::FastUpdate
                })
                .map(|record| (record.commit_id(), record.milestones().accepted))
        };
        let mut target_quiet_since = None;

        loop {
            let now = Instant::now();
            if now >= deadline {
                return Err(format!(
                    "{label}: core-entry driver timed out; stalled_state={:?}; \
                     peer_live={:?}; deliveries={:?}",
                    backend
                        .lifecycle_coordinator
                        .device(&stalled_device)
                        .map(|arbiter| arbiter.state()),
                    backend
                        .platform
                        .owner_ref(peer_device)
                        .and_then(|owner| owner.live_record())
                        .map(|record| (
                            record.commit_id(),
                            record.state(),
                            record.milestones(),
                            record.completion_context().class
                        )),
                    &backend.core_entry_deliveries_for_tests[delivery_start..]
                ));
            }

            let target_is_reached = target_reached(backend);
            if let Some((commit, accepted)) = peer_fast_update(backend) {
                if accepted {
                    c0_3bi_complete_owner_commit_through_core_driver_with_state(
                        backend,
                        state,
                        peer_device,
                        commit,
                        &format!("{label}: finish peer composed frame"),
                    );
                    target_quiet_since = None;
                    continue;
                }
            } else if let Some(record) = backend
                .platform
                .owner_ref(peer_device)
                .and_then(|owner| owner.live_record())
            {
                return Err(format!(
                    "{label}: unexpected peer Owner record: commit={:?}, state={:?}, class={:?}",
                    record.commit_id(),
                    record.state(),
                    record.completion_context().class
                ));
            }

            if target_is_reached {
                let quiet_since = target_quiet_since.get_or_insert(now);
                if now.duration_since(*quiet_since) >= std::time::Duration::from_millis(100) {
                    return Ok(());
                }
            }

            let slice = std::time::Duration::from_millis(50).min(deadline - now);
            let done = |backend: &super::KmsBackend| {
                peer_fast_update(backend).is_some()
                    || (!target_is_reached && target_reached(backend))
            };
            match c0_3bi_core_driver_until_with_state(backend, state, label, slice, &done, None) {
                Ok(()) => {}
                Err(error) if error.contains("core-entry driver timed out") => {}
                Err(error) => return Err(error),
            }
        }
    }

    /// Retire an unplugged Owner pool while completing any accepted repaint
    /// that the scene driver submitted in the same topology turn.
    fn c0_3cii_wait_for_owner_retirement(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        expected: &C0EndStateExpectation,
        label: &str,
    ) -> Result<(), String> {
        use std::time::Instant;

        let deadline = Instant::now() + std::time::Duration::from_secs(5);
        let end_state_reached =
            |backend: &super::KmsBackend| c0_3bi_end_state_errors(backend, expected).is_empty();
        let mut quiet_since = None;

        loop {
            let now = Instant::now();
            if now >= deadline {
                return Err(format!(
                    "{label}: core-entry driver timed out; end_state_errors={:?}; \
                     retired={:?}; owner_live={:?}; scene_wants_compose={}; \
                     ready_render_count={}; owner_events={:?}; offers={:?}",
                    c0_3bi_end_state_errors(backend, expected),
                    backend.scene.retired_output_end_states_for_tests(),
                    backend
                        .platform
                        .owner_ref(device)
                        .and_then(|owner| owner.live_record())
                        .map(|record| (
                            record.commit_id(),
                            record.state(),
                            record.milestones(),
                            record.completion_context().class
                        )),
                    backend.scene_wants_compose(),
                    backend
                        .platform
                        .ready_scanout_render_completions_for_tests
                        .len(),
                    backend.core_driver_owner_events_for_tests,
                    backend.core_driver_composed_offers_for_tests
                ));
            }

            let live_record = backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.live_record());
            if let Some(record) = live_record {
                if record.completion_context().class
                    != crate::kms::owner::completion::CompletionClass::FastUpdate
                {
                    return Err(format!(
                        "{label}: unexpected Owner record while retiring unplugged output: \
                         commit={:?}, state={:?}, class={:?}",
                        record.commit_id(),
                        record.state(),
                        record.completion_context().class
                    ));
                }
                if record.milestones().accepted {
                    let commit = record.commit_id();
                    c0_3bi_complete_owner_commit_through_core_driver_with_state(
                        backend,
                        state,
                        device,
                        commit,
                        &format!("{label}: complete incidental Owner repaint"),
                    );
                    quiet_since = None;
                    continue;
                }
            }

            let reached = end_state_reached(backend) && live_record.is_none();
            if reached {
                let quiet_from = quiet_since.get_or_insert(now);
                if now.duration_since(*quiet_from) >= std::time::Duration::from_millis(100) {
                    return Ok(());
                }
            }

            let slice = std::time::Duration::from_millis(50).min(deadline - now);
            let done = |backend: &super::KmsBackend| {
                backend
                    .platform
                    .owner_ref(device)
                    .and_then(|owner| owner.live_record())
                    .is_some_and(|record| {
                        record.completion_context().class
                            == crate::kms::owner::completion::CompletionClass::FastUpdate
                            && record.milestones().accepted
                    })
                    || (!reached && end_state_reached(backend))
            };
            match c0_3bi_core_driver_until_with_state(backend, state, label, slice, &done, None) {
                Ok(()) => {}
                Err(error) if error.contains("core-entry driver timed out") => {}
                Err(error) => return Err(error),
            }
        }
    }

    fn c0_3cii_grant_hotplug(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        answer: Result<Vec<ConnectorSnapshot>, io::Error>,
        label: &str,
    ) -> usize {
        let sent_before = backend.lifecycle_drivers[&device]
            .topology_test_stats()
            .1
            .len();
        c0_3cii_arm_hotplug_probe(backend, state, device, answer, label);
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            &format!("{label}: await core topology grant"),
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .acquire_episode
                    .as_ref()
                    .is_some_and(|episode| episode.granted)
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: core did not grant hotplug turn: {error}"));
        sent_before
    }

    fn c0_3cii_complete_hotplug_commit(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        sent_before: usize,
        label: &str,
    ) -> crate::kms::owner::identity::CommitId {
        let commit = c0_3cii_wait_hotplug_commit(backend, state, device, sent_before, label);
        c0_3bi_complete_owner_commit_through_core_driver_with_state(
            backend,
            state,
            device,
            commit,
            &format!("{label}: apply topology through core entries"),
        );
        c0_3cii_finish_hotplug_episode(backend, state, device, label);
        commit
    }

    fn c0_3cii_finish_hotplug_episode(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        label: &str,
    ) {
        for turn in 0..8 {
            if backend.acquire_episode.is_none() {
                return;
            }
            if let Some(commit) = backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.live_record())
                .map(|record| record.commit_id())
            {
                c0_3bi_complete_owner_commit_through_core_driver_with_state(
                    backend,
                    state,
                    device,
                    commit,
                    &format!("{label}: complete follow-up topology commit {turn}"),
                );
                continue;
            }
            c0_3bi_core_driver_until_with_state(
                backend,
                state,
                &format!("{label}: await terminal topology participant {turn}"),
                std::time::Duration::from_secs(5),
                &|backend| {
                    backend.acquire_episode.is_none()
                        || backend
                            .platform
                            .owner_ref(device)
                            .and_then(|owner| owner.live_record())
                            .is_some()
                },
                None,
            )
            .unwrap_or_else(|error| {
                panic!("{label}: topology participant did not advance: {error}")
            });
        }
        panic!("{label}: topology episode exceeded eight serialized commits");
    }

    fn c0_3cii_wait_hotplug_commit(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        sent_before: usize,
        label: &str,
    ) -> crate::kms::owner::identity::CommitId {
        if let Some(commit) = backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.live_record())
            .filter(|record| {
                record.completion_context().class
                    == crate::kms::owner::completion::CompletionClass::FastUpdate
            })
            .map(|record| record.commit_id())
        {
            c0_3bi_complete_owner_commit_through_core_driver_with_state(
                backend,
                state,
                device,
                commit,
                &format!("{label}: finish prior composed frame"),
            );
        }
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            &format!("{label}: dispatch hotplug topology commit"),
            std::time::Duration::from_secs(5),
            &|backend| {
                backend.lifecycle_drivers[&device].topology_test_stats().1.len() > sent_before
                    && backend
                        .platform
                        .owner_ref(device)
                        .and_then(|owner| owner.live_record())
                        .is_some()
            },
            None,
        )
        .unwrap_or_else(|error| panic!(
            "{label}: topology dispatch failed: {error}; sent_before={sent_before}; owner_devices={:?}; gate={:?}; arbiter={:?}; topology_rep={:?}; dpms={:?}; stats={:?}; transition={:?}; live={:?}; episode={:?}; hotplug={:?}",
            backend.lifecycle_owner_incarnation_devices(),
            backend.platform.transport_gate(&device).map(|gate| gate.state()),
            backend.lifecycle_coordinator.device(&device).map(|arbiter| (arbiter.state(), arbiter.desired().seat_target())),
            backend.lifecycle_coordinator.device(&device).and_then(|arbiter| arbiter.desired().representative(crate::kms::owner::lifecycle::DesiredField::Topology)),
            backend.lifecycle_coordinator.device(&device).map(|arbiter| arbiter.desired().protocol_dpms_level()),
            backend.lifecycle_drivers[&device].topology_test_stats(),
            backend.lifecycle_coordinator.device(&device).and_then(|arbiter| arbiter.transition()),
            backend.platform.owner_ref(device).and_then(|owner| owner.live_record()).map(|record| (record.commit_id(), record.state(), record.completion_context().class)),
            backend.acquire_episode.as_ref().map(|episode| (episode.id, episode.granted, episode.remaining.clone())),
            backend.hotplug_episode.as_ref().map(|episode| episode.participants.get(&device).map(|participant| (participant.classification, participant.terminal))),
        ));
        let record = backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.live_record())
            .expect("hotplug transaction is live");
        record.commit_id()
    }

    fn c0_3cii_snapshot_from_layout(
        backend: &super::KmsBackend,
        key: &OutputKey,
    ) -> ConnectorSnapshot {
        let layout = backend
            .platform
            .outputs
            .iter()
            .find(|layout| &layout.key == key)
            .expect("installed output snapshot");
        ConnectorSnapshot {
            key: key.clone(),
            modes: layout.output.modes.clone(),
            mm_width: layout.output.mm_width,
            mm_height: layout.output.mm_height,
            edid: layout.output.edid.clone(),
            connector_type: layout.output.connector_type.clone(),
        }
    }

    fn c0_3cii_legacy_fixture_from_owner_snapshot(
        owner_allocator: &super::RandrIdAllocator,
        snapshot: &ConnectorSnapshot,
        picked: &crate::platform::drm::Mode,
        position: (i32, i32),
    ) -> (super::KmsBackend, DrmDeviceKey, OutputKey, ServerState) {
        let mut backend = super::KmsBackend::for_tests();
        let device = backend.platform.devices[0].key;
        let key = OutputKey::new(device, snapshot.key.connector_name.clone());
        let layout = backend
            .platform
            .outputs
            .first_mut()
            .expect("headless Legacy fixture starts with one output");
        layout.key = key.clone();
        layout.output.connector_name.clone_from(&key.connector_name);
        layout.output.picked.clone_from(picked);
        layout.output.modes.clone_from(&snapshot.modes);
        layout.output.mm_width = snapshot.mm_width;
        layout.output.mm_height = snapshot.mm_height;
        layout.output.edid.clone_from(&snapshot.edid);
        layout
            .output
            .connector_type
            .clone_from(&snapshot.connector_type);
        layout.x = position.0;
        layout.y = position.1;
        layout.width = picked.width;
        layout.height = picked.height;
        backend.platform.fb_w = u16::try_from(position.0.max(0))
            .unwrap_or(u16::MAX)
            .saturating_add(picked.width);
        backend.platform.fb_h = u16::try_from(position.1.max(0))
            .unwrap_or(u16::MAX)
            .saturating_add(picked.height);
        // The live Owner fixture already allocated RandR XIDs for its
        // boot-time synthetic inventory before discovering the real output.
        // Mirror that inventory plus this Owner device's connector entries
        // into the Legacy fixture, remapping only fixture-local DRM keys, so
        // the wire comparison holds every output/CRTC/mode XID constant.
        backend.randr_id_alloc = super::RandrIdAllocator {
            next: owner_allocator.next,
            providers: owner_allocator
                .providers
                .iter()
                .map(|(endpoint, id)| {
                    let endpoint = match endpoint {
                        super::RandrProviderEndpoint::Kms(owner_device)
                            if *owner_device == snapshot.key.device_key =>
                        {
                            super::RandrProviderEndpoint::Kms(device)
                        }
                        endpoint => *endpoint,
                    };
                    (endpoint, *id)
                })
                .collect(),
            connectors: owner_allocator
                .connectors
                .iter()
                .filter(|(key, _)| {
                    key.device_key == snapshot.key.device_key || key.connector_name == "test"
                })
                .map(|(key, entry)| {
                    (
                        OutputKey::new(device, key.connector_name.clone()),
                        entry.clone(),
                    )
                })
                .collect(),
            modes: owner_allocator.modes.clone(),
            withdrawn_devices: owner_allocator
                .withdrawn_devices
                .iter()
                .map(|_| device)
                .collect(),
        };
        // The legacy fixture records the all-off step instead of issuing a
        // DRM modeset. Connector additions in this differential have no
        // remembered active route, so they also need no enable ioctl.
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());
        let state = c0_3ci_core_state(&mut backend);
        (backend, device, key, state)
    }

    fn c0_3cii_remap_snapshot(snapshot: &ConnectorSnapshot, key: OutputKey) -> ConnectorSnapshot {
        let mut snapshot = snapshot.clone();
        snapshot.key = key;
        snapshot
    }

    fn c0_3cii_set_publication_clock(state: &mut ServerState, tick_ms: u64) {
        // The Owner samples lastConfigTime when its terminal publication
        // reaches the core; Legacy samples it inside the synchronous rescan.
        // Give each paired operation the same broad clock tick, while the
        // differential normalizes only that protocol field if scheduling
        // crosses a millisecond boundary.
        state.start_instant = std::time::Instant::now()
            .checked_sub(std::time::Duration::from_millis(tick_ms))
            .expect("fixture timestamp epoch is representable");
    }

    fn c0_3cii_normalize_event_config_timestamps(bytes: &[u8]) -> Vec<u8> {
        assert_eq!(bytes.len() % 32, 0, "RANDR events are 32-byte records");
        let mut normalized = bytes.to_vec();
        for event in normalized.chunks_exact_mut(32) {
            match event[0] {
                89 => event[8..12].fill(0), // RRScreenChangeNotify.config_timestamp
                90 if event[1] == yserver_protocol::x11::randr::NOTIFY_OUTPUT_CHANGE => {
                    event[8..12].fill(0); // RROutputChangeNotify.config_timestamp
                }
                90 if event[1] == yserver_protocol::x11::randr::NOTIFY_CRTC_CHANGE => {}
                event_type => panic!("unexpected RANDR notification event type {event_type}"),
            }
        }
        normalized
    }

    fn c0_3cii_normalize_resources_config_timestamp(bytes: &[u8]) -> Vec<u8> {
        assert!(bytes.len() >= 16, "GetScreenResourcesCurrent fixed reply");
        let mut normalized = bytes.to_vec();
        // Keep lastSetTime byte-exact; only lastConfigTime can legitimately
        // differ because the two independent fixtures publish at different
        // core-loop instants.
        normalized[12..16].fill(0);
        normalized
    }

    fn c0_3cii_randr_request_bytes(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        peer: &mut std::os::unix::net::UnixStream,
        client: u32,
        sequence: u16,
        minor: u8,
        body: &[u8],
        label: &str,
    ) -> Vec<u8> {
        use yserver_core::core_loop::process_request::{RequestOutcome, process_request};
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        let outcome = process_request(
            state,
            backend,
            ClientId(client),
            SequenceNumber(sequence),
            RequestHeader {
                opcode: 128,
                data: minor,
                length_units: u32::try_from(body.len() / 4 + 1)
                    .expect("fixture RANDR request length fits"),
            },
            body,
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: dispatch RANDR request: {error}"));
        assert!(
            matches!(outcome, RequestOutcome::Handled),
            "{label}: published-state RandR request completes synchronously: {outcome:?}"
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            label,
            std::time::Duration::from_millis(100),
            &|_| true,
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: flush core reply: {error}"));
        kbd_map_drain(peer)
    }

    fn c0_3cii_published_randr_replies(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        peer: &mut std::os::unix::net::UnixStream,
        client: u32,
        label: &str,
    ) -> (Vec<u8>, Vec<u8>, Vec<u8>) {
        use yserver_protocol::x11::randr as rr;

        let output = state
            .randr
            .outputs
            .first()
            .expect("differential keeps the original output resource");
        let output_id = output.output_id;
        let crtc_id = output.crtc_id;
        let config_timestamp = state.randr.config_timestamp;
        // Task 5 owns forced RR_GET_SCREEN_RESOURCES reprobe parity. Task 3
        // compares its identical reply payload through the current-state
        // request so this differential observes only the publication under
        // test and does not add a later task's probe path.
        let resources = c0_3cii_randr_request_bytes(
            backend,
            state,
            peer,
            client,
            1,
            rr::RR_GET_SCREEN_RESOURCES_CURRENT,
            &yserver_core::resources::ROOT_WINDOW.0.to_le_bytes(),
            &format!("{label}: GetScreenResourcesCurrent"),
        );
        let mut output_body = Vec::with_capacity(8);
        output_body.extend_from_slice(&output_id.to_le_bytes());
        output_body.extend_from_slice(&config_timestamp.to_le_bytes());
        let output_info = c0_3cii_randr_request_bytes(
            backend,
            state,
            peer,
            client,
            2,
            rr::RR_GET_OUTPUT_INFO,
            &output_body,
            &format!("{label}: GetOutputInfo"),
        );
        let mut crtc_body = Vec::with_capacity(8);
        crtc_body.extend_from_slice(&crtc_id.to_le_bytes());
        crtc_body.extend_from_slice(&config_timestamp.to_le_bytes());
        let crtc_info = c0_3cii_randr_request_bytes(
            backend,
            state,
            peer,
            client,
            3,
            rr::RR_GET_CRTC_INFO,
            &crtc_body,
            &format!("{label}: GetCrtcInfo"),
        );
        (resources, output_info, crtc_info)
    }

    fn c0_3cii_client_output_modes(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        peer: &mut std::os::unix::net::UnixStream,
        client: u32,
        output_id: u32,
        sequence: u16,
        label: &str,
    ) -> Vec<(u16, u16, u32)> {
        use yserver_protocol::x11::randr as rr;

        let resources = c0_3cii_randr_request_bytes(
            backend,
            state,
            peer,
            client,
            sequence,
            rr::RR_GET_SCREEN_RESOURCES_CURRENT,
            &yserver_core::resources::ROOT_WINDOW.0.to_le_bytes(),
            &format!("{label}: GetScreenResourcesCurrent"),
        );
        assert_eq!(resources[0], 1, "{label}: resources reply");
        let resources_crtcs = usize::from(u16::from_le_bytes([resources[16], resources[17]]));
        let resources_outputs = usize::from(u16::from_le_bytes([resources[18], resources[19]]));
        let resources_modes = usize::from(u16::from_le_bytes([resources[20], resources[21]]));
        let resources_mode_start = 32 + (resources_crtcs + resources_outputs) * 4;
        let resources_mode_ids = (0..resources_modes)
            .map(|index| {
                let offset = resources_mode_start + index * 32;
                u32::from_le_bytes(
                    resources[offset..offset + 4]
                        .try_into()
                        .expect("four-byte mode XID"),
                )
            })
            .collect::<Vec<_>>();

        let mut output_body = Vec::with_capacity(8);
        output_body.extend_from_slice(&output_id.to_le_bytes());
        output_body.extend_from_slice(&state.randr.config_timestamp.to_le_bytes());
        let output_info = c0_3cii_randr_request_bytes(
            backend,
            state,
            peer,
            client,
            sequence.wrapping_add(1),
            rr::RR_GET_OUTPUT_INFO,
            &output_body,
            &format!("{label}: GetOutputInfo"),
        );
        assert_eq!(output_info[0], 1, "{label}: output info reply");
        let output_crtcs = usize::from(u16::from_le_bytes([output_info[26], output_info[27]]));
        let output_modes = usize::from(u16::from_le_bytes([output_info[28], output_info[29]]));
        let output_mode_start = 36 + output_crtcs * 4;
        let output_mode_ids = (0..output_modes)
            .map(|index| {
                let offset = output_mode_start + index * 4;
                u32::from_le_bytes(
                    output_info[offset..offset + 4]
                        .try_into()
                        .expect("four-byte output mode XID"),
                )
            })
            .collect::<Vec<_>>();

        output_mode_ids
            .iter()
            .map(|mode_id| {
                assert!(
                    resources_mode_ids.contains(mode_id),
                    "{label}: GetOutputInfo mode {mode_id} appears in GetScreenResourcesCurrent"
                );
                let mode = state
                    .randr
                    .mode_table
                    .iter()
                    .find(|mode| mode.mode_id == *mode_id)
                    .unwrap_or_else(|| panic!("{label}: published mode table contains {mode_id}"));
                (mode.width, mode.height, mode.vrefresh)
            })
            .collect()
    }

    fn c0_3cii_assert_matching_randr_replies(
        owner: &(Vec<u8>, Vec<u8>, Vec<u8>),
        legacy: &(Vec<u8>, Vec<u8>, Vec<u8>),
        label: &str,
    ) {
        assert_eq!(
            c0_3cii_normalize_resources_config_timestamp(&owner.0),
            c0_3cii_normalize_resources_config_timestamp(&legacy.0),
            "{label}: GetScreenResourcesCurrent bytes (only lastConfigTime is normalized)"
        );
        assert_eq!(owner.1, legacy.1, "{label}: GetOutputInfo bytes");
        assert_eq!(owner.2, legacy.2, "{label}: GetCrtcInfo bytes");
    }

    fn c0_3cii_assert_matching_backend_projection(
        owner: &super::KmsBackend,
        legacy: &super::KmsBackend,
        label: &str,
    ) {
        let layout_projection = |backend: &super::KmsBackend| {
            let mut outputs = backend
                .platform
                .outputs
                .iter()
                .map(|layout| {
                    (
                        layout.key.connector_name.clone(),
                        layout.x,
                        layout.y,
                        layout.width,
                        layout.height,
                        layout.output.picked.width,
                        layout.output.picked.height,
                        layout.output.picked.vrefresh,
                    )
                })
                .collect::<Vec<_>>();
            outputs.sort_unstable();
            outputs
        };
        let registry_projection = |backend: &super::KmsBackend| {
            let mut entries = backend
                .randr_id_alloc
                .entries()
                .map(|(key, entry)| {
                    (
                        key.connector_name.clone(),
                        entry.ids,
                        entry.connected,
                        entry.config,
                        entry.crtc_associated,
                        entry.client_configured,
                        entry.last_enabled,
                        entry
                            .modes
                            .iter()
                            .map(|mode| (mode.width, mode.height, mode.vrefresh, mode.preferred))
                            .collect::<Vec<_>>(),
                        entry.edid.clone(),
                        entry.mm_width,
                        entry.mm_height,
                        entry.connector_type.clone(),
                    )
                })
                .collect::<Vec<_>>();
            entries.sort_unstable_by(|a, b| a.0.cmp(&b.0));
            entries
        };
        assert_eq!(
            layout_projection(owner),
            layout_projection(legacy),
            "{label}: installed outputs and layout"
        );
        assert_eq!(
            (owner.platform.fb_w, owner.platform.fb_h),
            (legacy.platform.fb_w, legacy.platform.fb_h),
            "{label}: framebuffer extent"
        );
        assert_eq!(
            registry_projection(owner),
            registry_projection(legacy),
            "{label}: connector registry (fixture device keys are intentionally normalized)"
        );
        let mut owner_provider_ids = owner
            .randr_id_alloc
            .providers
            .values()
            .copied()
            .collect::<Vec<_>>();
        let mut legacy_provider_ids = legacy
            .randr_id_alloc
            .providers
            .values()
            .copied()
            .collect::<Vec<_>>();
        owner_provider_ids.sort_unstable();
        legacy_provider_ids.sort_unstable();
        assert_eq!(
            owner_provider_ids, legacy_provider_ids,
            "{label}: provider XID allocation (fixture-local DRM keys normalized)"
        );
        assert_eq!(
            owner.randr_id_alloc.modes, legacy.randr_id_alloc.modes,
            "{label}: mode identity to XID allocation"
        );
        assert_eq!(
            owner.randr_id_alloc.next, legacy.randr_id_alloc.next,
            "{label}: next RandR XID allocation"
        );
    }

    fn c0_3cii_run_legacy_hotplug(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        watched_key: &OutputKey,
        snapshots: Vec<ConnectorSnapshot>,
        label: &str,
    ) {
        let mut snapshots = snapshots;
        // The live Owner fixture carries one boot-time synthetic connector
        // outside the Owner device's hotplug episode. Keep that unrelated
        // inventory stable in the Legacy fixture's global rescan so this
        // differential changes only the connector under test.
        for (key, entry) in backend.randr_id_alloc.entries() {
            if key.device_key == device
                && key != watched_key
                && entry.connected
                && !snapshots.iter().any(|snapshot| snapshot.key == *key)
            {
                snapshots.push(ConnectorSnapshot {
                    key: key.clone(),
                    modes: entry.modes.clone(),
                    mm_width: entry.mm_width,
                    mm_height: entry.mm_height,
                    edid: entry.edid.clone(),
                    connector_type: entry.connector_type.clone(),
                });
            }
        }
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        backend
            .platform
            .queue_connector_probe_for_tests(device, Ok(snapshots));
        super::KmsBackend::record_display_hotplug_edge(backend);
        backend.hotplug_rescan_deadline =
            Some(std::time::Instant::now() - std::time::Duration::from_millis(1));
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            label,
            std::time::Duration::from_secs(3),
            &|backend| backend.hotplug_rescan_deadline.is_none(),
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: Legacy rescan: {error}"));
    }

    fn c0_3cii_run_owner_hotplug(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        snapshots: Vec<ConnectorSnapshot>,
        label: &str,
    ) {
        let delivery_start = backend.core_entry_deliveries_for_tests.len();
        let sends_before = backend.lifecycle_drivers[&device]
            .topology_test_stats()
            .1
            .len();
        c0_3cii_arm_hotplug_probe(backend, state, device, Ok(snapshots), label);
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            &format!("{label}: grant the topology episode"),
            std::time::Duration::from_secs(3),
            &|backend| {
                let deliveries = &backend.core_entry_deliveries_for_tests[delivery_start..];
                deliveries.iter().any(|delivery| {
                    matches!(
                        delivery,
                        yserver_core::core_loop::run::CoreEntryDelivery::TopologyEpisodeBegin(_)
                    )
                })
                    && (backend
                        .acquire_episode
                        .as_ref()
                        .is_some_and(|episode| episode.granted)
                        || deliveries.iter().any(|delivery| {
                            matches!(
                            delivery,
                            yserver_core::core_loop::run::CoreEntryDelivery::TopologyEpisodeEnd {
                                ..
                            }
                        )
                        }))
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: grant topology episode: {error}"));

        if backend.acquire_episode.is_some() {
            let commit = c0_3cii_wait_hotplug_commit(
                backend,
                state,
                device,
                sends_before,
                &format!("{label}: dispatch topology transaction"),
            );
            c0_3bi_complete_owner_commit_through_core_driver_with_state(
                backend,
                state,
                device,
                commit,
                &format!("{label}: complete topology transaction"),
            );
            c0_3cii_finish_hotplug_episode(backend, state, device, label);
        }
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            &format!("{label}: deliver EpisodeEnd publication"),
            std::time::Duration::from_secs(3),
            &|backend| {
                backend.acquire_episode.is_none()
                    && backend.core_entry_deliveries_for_tests[delivery_start..]
                        .iter()
                        .any(|delivery| {
                            matches!(
                                delivery,
                                yserver_core::core_loop::run::CoreEntryDelivery::TopologyEpisodeEnd {
                                    ..
                                }
                            )
                        })
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: publish topology episode: {error}"));
        c0_3cii_settle_owner_fixture(backend, state, device, &format!("{label}: settle Owner"));
        assert!(
            backend.core_entry_deliveries_for_tests[delivery_start..]
                .iter()
                .all(|delivery| !matches!(
                    delivery,
                    yserver_core::core_loop::run::CoreEntryDelivery::UrgentWithdrawal { .. }
                )),
            "{label}: a successful hotplug publication must not withdraw the Owner device"
        );
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .map(|arbiter| arbiter.state()),
            Some(crate::kms::owner::lifecycle::DeviceLifecycleState::Ready),
            "{label}: the successful hotplug leaves the Owner lifecycle ready"
        );
    }

    fn c0_3cii_assert_hotplug_publication_differential(
        test_name: &str,
        compare_replies_and_backend: bool,
    ) {
        use crate::kms::executor::test_support::StubBehaviour;
        use yserver_protocol::x11::randr as rr;

        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        assert_eq!(
            outputs.len(),
            1,
            "the Owner fixture starts with one lit output"
        );
        let backend = &mut fixture.backend;
        // This differential drives hotplug through the scripted prober and
        // the core-entry edge path. Ignore unrelated host udev edges from
        // the live DRM fixture while those scripted episodes are open.
        backend.platform.hotplug_monitor = None;
        let mut owner_state = c0_3ci_core_state(backend);
        c0_3cii_settle_owner_fixture(
            backend,
            &mut owner_state,
            device,
            "publication parity setup",
        );
        let owner_key = outputs[0].clone();
        let owner_layout = backend
            .platform
            .outputs
            .iter()
            .find(|layout| layout.key == owner_key)
            .expect("Owner output layout");
        let initial_snapshot = c0_3cii_snapshot_from_layout(backend, &owner_key);
        let initial_mode = owner_layout.output.picked.clone();
        let initial_position = (owner_layout.x, owner_layout.y);

        let (mut legacy, legacy_device, legacy_key, mut legacy_state) =
            c0_3cii_legacy_fixture_from_owner_snapshot(
                &backend.randr_id_alloc,
                &initial_snapshot,
                &initial_mode,
                initial_position,
            );
        let output_projection = |state: &ServerState| {
            state
                .randr
                .outputs
                .iter()
                .map(|output| {
                    (
                        (
                            output.name.clone(),
                            output.output_id,
                            output.crtc_id,
                            output.mode_id,
                            output.connected,
                            output.x,
                            output.y,
                            output.width,
                            output.height,
                            output.vrefresh,
                            output.timing,
                        ),
                        (
                            output.mm_width,
                            output.mm_height,
                            output.mode_ids.clone(),
                            output.num_preferred,
                            output.rotation,
                        ),
                    )
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(
            output_projection(&owner_state),
            output_projection(&legacy_state),
            "the two fixtures start from the same connector snapshot and RandR IDs"
        );

        let mut owner_query = c0_3aii_install_dpms_core_client(&mut owner_state, 74);
        let mut legacy_query = c0_3aii_install_dpms_core_client(&mut legacy_state, 74);
        let mut owner_all_events = c0_3aii_install_dpms_core_client(&mut owner_state, 72);
        let mut legacy_all_events = c0_3aii_install_dpms_core_client(&mut legacy_state, 72);
        let mut owner_output_events = c0_3aii_install_dpms_core_client(&mut owner_state, 73);
        let mut legacy_output_events = c0_3aii_install_dpms_core_client(&mut legacy_state, 73);
        let all_masks = rr::NOTIFY_MASK_SCREEN_CHANGE
            | rr::NOTIFY_MASK_CRTC_CHANGE
            | rr::NOTIFY_MASK_OUTPUT_CHANGE;
        owner_state
            .randr_select_masks
            .insert((72, yserver_core::resources::ROOT_WINDOW), all_masks);
        legacy_state
            .randr_select_masks
            .insert((72, yserver_core::resources::ROOT_WINDOW), all_masks);
        owner_state.randr_select_masks.insert(
            (73, yserver_core::resources::ROOT_WINDOW),
            rr::NOTIFY_MASK_OUTPUT_CHANGE,
        );
        legacy_state.randr_select_masks.insert(
            (73, yserver_core::resources::ROOT_WINDOW),
            rr::NOTIFY_MASK_OUTPUT_CHANGE,
        );
        for state in [&mut owner_state, &mut legacy_state] {
            state.randr.timestamp = 1_234;
            state.randr.config_timestamp = 500;
        }
        c0_3cii_set_publication_clock(&mut owner_state, 8_000);
        c0_3cii_set_publication_clock(&mut legacy_state, 8_000);

        let compare_notifications = |owner_all: &[u8],
                                     legacy_all: &[u8],
                                     owner_output: &[u8],
                                     legacy_output: &[u8],
                                     expected_all_events: usize,
                                     expected_output_events: usize,
                                     label: &str| {
            assert_eq!(
                owner_all.len(),
                expected_all_events * 32,
                "{label}: Owner all-mask event count; events={owner_all:?}"
            );
            assert_eq!(
                legacy_all.len(),
                expected_all_events * 32,
                "{label}: Legacy all-mask event count"
            );
            assert_eq!(
                owner_output.len(),
                expected_output_events * 32,
                "{label}: Owner output-mask event count"
            );
            assert_eq!(
                legacy_output.len(),
                expected_output_events * 32,
                "{label}: Legacy output-mask event count"
            );
            assert_eq!(
                c0_3cii_normalize_event_config_timestamps(owner_all),
                c0_3cii_normalize_event_config_timestamps(legacy_all),
                "{label}: exact event contents and order, normalizing only lastConfigTime"
            );
            assert_eq!(
                c0_3cii_normalize_event_config_timestamps(owner_output),
                c0_3cii_normalize_event_config_timestamps(legacy_output),
                "{label}: exact output-selected event bytes"
            );
            if expected_all_events > 0 {
                assert_eq!(
                    owner_all[0], 89,
                    "{label}: RRScreenChangeNotify comes first"
                );
                assert_eq!(
                    legacy_all[0], 89,
                    "{label}: Legacy screen notification comes first"
                );
            }
            for (events, expected, side) in [
                (owner_all, expected_all_events, "Owner"),
                (legacy_all, expected_all_events, "Legacy"),
            ] {
                for (index, event) in events.chunks_exact(32).enumerate() {
                    if event[0] == 90 {
                        assert_eq!(
                            event[1],
                            if expected == 3 && index == 1 {
                                rr::NOTIFY_CRTC_CHANGE
                            } else {
                                rr::NOTIFY_OUTPUT_CHANGE
                            },
                            "{label}: {side} notification order at event {index}"
                        );
                    }
                }
            }
            if expected_output_events == 1 {
                assert_eq!(
                    owner_output[0], 90,
                    "{label}: output mask receives RRNotify"
                );
                assert_eq!(owner_output[1], rr::NOTIFY_OUTPUT_CHANGE);
            }
        };

        let assert_timestamps = |owner_state: &ServerState,
                                 legacy_state: &ServerState,
                                 previous_config: u32,
                                 config_changed: bool,
                                 label: &str| {
            assert_eq!(
                owner_state.randr.timestamp, 1_234,
                "{label}: Owner lastSetTime preserved"
            );
            assert_eq!(
                legacy_state.randr.timestamp, 1_234,
                "{label}: Legacy lastSetTime preserved"
            );
            if config_changed {
                assert_ne!(
                    owner_state.randr.config_timestamp, previous_config,
                    "{label}: Owner lastConfigTime advances"
                );
                assert_ne!(
                    legacy_state.randr.config_timestamp, previous_config,
                    "{label}: Legacy lastConfigTime advances"
                );
            } else {
                assert_eq!(
                    owner_state.randr.config_timestamp, previous_config,
                    "{label}: metadata-only Owner change preserves lastConfigTime"
                );
                assert_eq!(
                    legacy_state.randr.config_timestamp, previous_config,
                    "{label}: metadata-only Legacy change preserves lastConfigTime"
                );
            }
        };

        // Monitor dimensions are Output metadata, not the available mode
        // configuration. Both paths emit OutputChangeNotify but preserve
        // lastConfigTime for this change.
        let config_before_metadata = owner_state.randr.config_timestamp;
        let mut metadata = initial_snapshot.clone();
        metadata.mm_width = metadata.mm_width.saturating_add(1);
        c0_3cii_run_owner_hotplug(
            backend,
            &mut owner_state,
            device,
            vec![metadata.clone()],
            "Owner metadata-only hotplug",
        );
        c0_3cii_run_legacy_hotplug(
            &mut legacy,
            &mut legacy_state,
            legacy_device,
            &legacy_key,
            vec![c0_3cii_remap_snapshot(&metadata, legacy_key.clone())],
            "Legacy metadata-only hotplug",
        );
        assert_timestamps(
            &owner_state,
            &legacy_state,
            config_before_metadata,
            false,
            "metadata-only hotplug",
        );
        compare_notifications(
            &kbd_map_drain(&mut owner_all_events),
            &kbd_map_drain(&mut legacy_all_events),
            &kbd_map_drain(&mut owner_output_events),
            &kbd_map_drain(&mut legacy_output_events),
            2,
            1,
            "metadata-only hotplug",
        );
        if compare_replies_and_backend {
            let owner_replies = c0_3cii_published_randr_replies(
                backend,
                &mut owner_state,
                &mut owner_query,
                74,
                "Owner metadata-only published resources",
            );
            let legacy_replies = c0_3cii_published_randr_replies(
                &mut legacy,
                &mut legacy_state,
                &mut legacy_query,
                74,
                "Legacy metadata-only published resources",
            );
            c0_3cii_assert_matching_randr_replies(
                &owner_replies,
                &legacy_replies,
                "metadata-only hotplug",
            );
            c0_3cii_assert_matching_backend_projection(backend, &legacy, "metadata-only hotplug");
        }

        // The physical unplug is the stateful publication under review: the
        // Owner sends its KMS disable through the executor fixture, while the
        // Legacy fixture records its synchronous all-off step instead of
        // issuing a DRM modeset.
        let config_before_unplug = owner_state.randr.config_timestamp;
        c0_3cii_set_publication_clock(&mut owner_state, 16_000);
        c0_3cii_set_publication_clock(&mut legacy_state, 16_000);
        c0_3cii_run_owner_hotplug(
            backend,
            &mut owner_state,
            device,
            Vec::new(),
            "Owner connector unplug",
        );
        c0_3cii_run_legacy_hotplug(
            &mut legacy,
            &mut legacy_state,
            legacy_device,
            &legacy_key,
            Vec::new(),
            "Legacy connector unplug",
        );
        assert_timestamps(
            &owner_state,
            &legacy_state,
            config_before_unplug,
            true,
            "connector unplug",
        );
        let owner_unplug_events = kbd_map_drain(&mut owner_all_events);
        let legacy_unplug_events = kbd_map_drain(&mut legacy_all_events);
        let owner_unplug_output = kbd_map_drain(&mut owner_output_events);
        let legacy_unplug_output = kbd_map_drain(&mut legacy_output_events);
        compare_notifications(
            &owner_unplug_events,
            &legacy_unplug_events,
            &owner_unplug_output,
            &legacy_unplug_output,
            3,
            1,
            "connector unplug",
        );
        assert_eq!(
            &owner_unplug_events[36..40],
            &1_234_u32.to_le_bytes(),
            "RRNotify CrtcChange carries preserved lastSetTime"
        );
        if compare_replies_and_backend {
            let owner_replies = c0_3cii_published_randr_replies(
                backend,
                &mut owner_state,
                &mut owner_query,
                74,
                "Owner unplug published resources",
            );
            let legacy_replies = c0_3cii_published_randr_replies(
                &mut legacy,
                &mut legacy_state,
                &mut legacy_query,
                74,
                "Legacy unplug published resources",
            );
            c0_3cii_assert_matching_randr_replies(
                &owner_replies,
                &legacy_replies,
                "connector unplug",
            );
            c0_3cii_assert_matching_backend_projection(backend, &legacy, "connector unplug");
        }

        // Return the connector with a new mode list that no longer contains
        // the remembered active mode. This exercises the same published
        // replug state on both paths without asking the Legacy fixture to
        // issue a modeset; Task 2 separately proves compatible-route relight.
        let config_before_replug = owner_state.randr.config_timestamp;
        let mut replug = initial_snapshot.clone();
        let mut replacement_mode = replug
            .modes
            .first()
            .expect("the connector advertises a baseline mode")
            .clone();
        replacement_mode.width = replacement_mode
            .width
            .checked_add(8)
            .expect("fixture mode width has room for a replacement mode");
        replacement_mode.name.push_str("-replacement");
        replug.modes = vec![replacement_mode];
        c0_3cii_set_publication_clock(&mut owner_state, 24_000);
        c0_3cii_set_publication_clock(&mut legacy_state, 24_000);
        c0_3cii_run_owner_hotplug(
            backend,
            &mut owner_state,
            device,
            vec![replug.clone()],
            "Owner incompatible-mode replug",
        );
        c0_3cii_run_legacy_hotplug(
            &mut legacy,
            &mut legacy_state,
            legacy_device,
            &legacy_key,
            vec![c0_3cii_remap_snapshot(&replug, legacy_key.clone())],
            "Legacy incompatible-mode replug",
        );
        assert_timestamps(
            &owner_state,
            &legacy_state,
            config_before_replug,
            true,
            "connector replug",
        );
        let owner_replug_events = kbd_map_drain(&mut owner_all_events);
        let legacy_replug_events = kbd_map_drain(&mut legacy_all_events);
        let owner_replug_output = kbd_map_drain(&mut owner_output_events);
        let legacy_replug_output = kbd_map_drain(&mut legacy_output_events);
        compare_notifications(
            &owner_replug_events,
            &legacy_replug_events,
            &owner_replug_output,
            &legacy_replug_output,
            2,
            1,
            "connector replug",
        );
        if compare_replies_and_backend {
            let owner_replies = c0_3cii_published_randr_replies(
                backend,
                &mut owner_state,
                &mut owner_query,
                74,
                "Owner replug published resources",
            );
            let legacy_replies = c0_3cii_published_randr_replies(
                &mut legacy,
                &mut legacy_state,
                &mut legacy_query,
                74,
                "Legacy replug published resources",
            );
            c0_3cii_assert_matching_randr_replies(
                &owner_replies,
                &legacy_replies,
                "connector replug",
            );
            c0_3cii_assert_matching_backend_projection(backend, &legacy, "connector replug");
        }

        let expected = c0_3bi_expected_end_state(Vec::<OutputKey>::new());
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut owner_state,
            "drain the unplugged Owner pool retirement",
            std::time::Duration::from_secs(5),
            &|backend| c0_3bi_end_state_errors(backend, &expected).is_empty(),
            None,
        )
        .unwrap_or_else(|error| {
            panic!("{test_name}: retired Owner output did not settle: {error}")
        });
        c0_3bi_assert_end_state(backend, &format!("{test_name} Owner"), &expected);
        c0_3bi_assert_end_state(&legacy, &format!("{test_name} Legacy"), &expected);
    }

    #[test]
    #[cfg(target_os = "linux")]
    fn c0_3cii_legacy_only_rescan_unchanged() {
        use std::{
            os::fd::OwnedFd,
            sync::{Arc, Mutex},
            thread::ThreadId,
        };

        struct RecordingLegacyProber {
            snapshots: Vec<ConnectorSnapshot>,
            calls: Mutex<Vec<ThreadId>>,
        }

        impl crate::kms::render::platform::ConnectorProber for RecordingLegacyProber {
            fn probe_snapshot(
                &self,
                _key: DrmDeviceKey,
                _fd: OwnedFd,
            ) -> io::Result<Vec<ConnectorSnapshot>> {
                self.calls
                    .lock()
                    .expect("record Legacy probe call")
                    .push(std::thread::current().id());
                Ok(self.snapshots.clone())
            }

            fn probe_connectors(
                &self,
                _key: DrmDeviceKey,
                _fd: OwnedFd,
            ) -> io::Result<Vec<crate::platform::drm::ConnectorProbe>> {
                Ok(Vec::new())
            }
        }

        let mut backend = super::KmsBackend::for_tests();
        assert!(backend.lifecycle_owner_incarnation_devices().is_empty());
        let outputs = backend
            .platform
            .outputs
            .iter()
            .map(|output| output.key.clone())
            .collect::<Vec<_>>();
        let snapshots = outputs
            .iter()
            .map(|key| c0_3cii_snapshot_from_layout(&backend, key))
            .collect();
        let prober = Arc::new(RecordingLegacyProber {
            snapshots,
            calls: Mutex::new(Vec::new()),
        });
        backend.platform.connector_prober = prober.clone();
        let core_thread = std::thread::current().id();
        let mut state = c0_3ci_core_state(&mut backend);
        super::KmsBackend::record_display_hotplug_edge(&mut backend);
        backend.hotplug_rescan_deadline =
            Some(std::time::Instant::now() - std::time::Duration::from_millis(1));
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "run unchanged Legacy-only hotplug rescan",
            std::time::Duration::from_secs(1),
            &|backend| {
                !backend.platform.outputs.is_empty() && !prober.calls.lock().unwrap().is_empty()
            },
            None,
        )
        .expect("Legacy-only debounced edge completes its synchronous rescan");
        assert_eq!(
            prober.calls.lock().unwrap().as_slice(),
            &[core_thread],
            "Legacy synchronous rescan probes through ConnectorProber on the core thread"
        );
        assert!(backend.probe_episode.is_none());
        assert!(backend.probe_workers.workers.is_empty());
        assert!(backend.acquire_episode.is_none());
        c0_3bi_assert_end_state(
            &backend,
            "c0_3cii_legacy_only_rescan_unchanged",
            &c0_3bi_expected_end_state(outputs),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    #[cfg(target_os = "linux")]
    fn c0_3cii_edge_during_open_episode_rearms_vulkan() {
        use crate::kms::render::platform::ProbeBarrier;

        let (mut fixture, device_a, device_b, outputs_a, outputs_b, mut state) =
            c0_3cii_live_two_owner_fixture();
        let backend = &mut fixture.backend;
        assert_eq!(outputs_a.len(), 1);
        assert_eq!(outputs_b.len(), 1);
        c0_3cii_settle_owner_fixtures(
            backend,
            &mut state,
            &[device_a, device_b],
            "deferred-edge Owner fixture readiness",
        );
        let first_a = Vec::new();
        let first_b = vec![c0_3cii_snapshot_from_layout(backend, &outputs_b[0])];
        let second_a = first_a.clone();
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let barrier = ProbeBarrier::new();
        backend.platform.queue_blocked_connector_probe_for_tests(
            device_a,
            Ok(first_a),
            barrier.clone(),
        );
        backend
            .platform
            .queue_connector_probe_for_tests(device_b, Ok(first_b));
        backend
            .platform
            .queue_connector_probe_for_tests(device_a, Ok(second_a));
        backend
            .platform
            .queue_connector_probe_for_tests(device_b, Ok(Vec::new()));

        super::KmsBackend::record_display_hotplug_edge(backend);
        backend.hotplug_rescan_deadline =
            Some(std::time::Instant::now() - std::time::Duration::from_millis(1));
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "start the first blocked two-Owner edge episode",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend
                    .probe_episode
                    .as_ref()
                    .is_some_and(|episode| episode.cause == super::ProbeEpisodeCause::Hotplug)
                    && barrier.wait_started(std::time::Duration::ZERO)
            },
            None,
        )
        .expect("first edge starts one combined probe episode");
        assert!(barrier.wait_started(std::time::Duration::from_secs(1)));
        let first_epoch = backend.probe_episode.as_ref().unwrap().epoch;
        super::KmsBackend::record_display_hotplug_edge(backend);
        backend.hotplug_rescan_deadline =
            Some(std::time::Instant::now() - std::time::Duration::from_millis(1));
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "defer a second edge during the open probe episode",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend.probe_episode.as_ref().is_some_and(|episode| {
                    episode.epoch == first_epoch
                        && episode.remaining == [device_a].into_iter().collect()
                        && episode.results.contains_key(&device_b)
                }) && backend.probe_workers.workers.len() == 1
                    && backend.probe_workers.workers.contains_key(&device_a)
                    && backend.hotplug_rescan_deferred
            },
            None,
        )
        .expect("second edge is deferred after B answers while A remains blocked");
        assert_eq!(backend.probe_episode.as_ref().unwrap().epoch, first_epoch);
        assert_eq!(backend.probe_workers.workers.len(), 1);
        assert!(backend.hotplug_rescan_deferred);

        let first_sends = [device_a, device_b]
            .into_iter()
            .map(|device| {
                (
                    device,
                    backend.lifecycle_drivers[&device]
                        .topology_test_stats()
                        .1
                        .len(),
                )
            })
            .collect::<HashMap<_, _>>();
        barrier.release();
        c0_3cii_finish_probe_workers(backend, &mut state, "join first edge probe workers");
        c0_3cii_wait_hotplug_grant(backend, &mut state, "grant first edge topology turn");
        let first_commit = c0_3cii_wait_hotplug_commit(
            backend,
            &mut state,
            device_a,
            first_sends[&device_a],
            "dispatch first edge topology transaction",
        );
        c0_3bi_complete_owner_commit_through_core_driver_with_state(
            backend,
            &mut state,
            device_a,
            first_commit,
            "apply first edge transaction through core entries",
        );
        c0_3cii_finish_hotplug_episode(
            backend,
            &mut state,
            device_a,
            "finish first edge topology turn",
        );
        assert!(backend.acquire_episode.is_none());
        assert_eq!(backend.platform.outputs.len(), 1);
        assert_eq!(backend.platform.outputs[0].key, outputs_b[0]);

        let next_epoch_floor = backend.next_probe_epoch;
        assert!(backend.hotplug_rescan_deadline.is_some());
        backend.hotplug_rescan_deadline =
            Some(std::time::Instant::now() - std::time::Duration::from_millis(1));
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "start one probe for the newest edge after EpisodeEnd",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend.next_probe_epoch == next_epoch_floor + 1
                    && (backend.probe_episode.is_some()
                        || backend.acquire_episode.as_ref().is_some_and(|episode| {
                            episode.cause == super::TopologyEpisodeCause::Hotplug
                        }))
            },
            None,
        )
        .expect("the deferred edge starts one new probe episode after EpisodeEnd");
        if backend.probe_episode.is_some() {
            c0_3cii_finish_probe_workers(backend, &mut state, "join newest edge probe workers");
        }
        c0_3cii_wait_hotplug_grant(backend, &mut state, "grant newest edge topology turn");
        assert_eq!(
            backend
                .hotplug_episode
                .as_ref()
                .unwrap()
                .participants
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            [device_b],
            "the second probe sees B's newer disconnect while A remains absent"
        );
        let second_commit = c0_3cii_wait_hotplug_commit(
            backend,
            &mut state,
            device_b,
            first_sends[&device_b],
            "dispatch newest edge topology transaction",
        );
        c0_3bi_complete_owner_commit_through_core_driver_with_state(
            backend,
            &mut state,
            device_b,
            second_commit,
            "apply newest edge transaction through core entries",
        );
        c0_3cii_finish_hotplug_episode(
            backend,
            &mut state,
            device_b,
            "finish newest edge topology turn",
        );
        c0_3bi_complete_owner_followups(
            backend,
            device_b,
            8,
            "complete ordinary repaint work after the newest unplug",
        );
        let expected = c0_3bi_expected_end_state(Vec::<OutputKey>::new());
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "drain both edge episodes' pool obligations",
            std::time::Duration::from_secs(5),
            &|backend| c0_3bi_end_state_errors(backend, &expected).is_empty(),
            None,
        )
        .unwrap_or_else(|error| {
            panic!(
                "{error}; outputs={:?}; end_errors={:?}; retired={:?}; owners={:?}; episodes={:?}",
                backend
                    .platform
                    .outputs
                    .iter()
                    .map(|output| output.key.clone())
                    .collect::<Vec<_>>(),
                c0_3bi_end_state_errors(backend, &expected),
                backend.scene.retired_output_end_states_for_tests(),
                [device_a, device_b].map(|device| (
                    device,
                    backend
                        .platform
                        .owner_ref(device)
                        .and_then(|owner| owner.live_record())
                        .map(|record| (
                            record.commit_id(),
                            record.state(),
                            record.completion_context().class
                        ))
                )),
                backend
                    .acquire_episode
                    .as_ref()
                    .map(|episode| (episode.id, episode.remaining.clone())),
            )
        });
        assert_eq!(backend.next_probe_epoch, next_epoch_floor + 1);
        assert_eq!(backend.platform.outputs.len(), 0);
        c0_3bi_assert_end_state(
            backend,
            "c0_3cii_edge_during_open_episode_rearms_vulkan",
            &expected,
        );
    }

