    #[test]
    fn c0_3cii_probe_worker_shares_the_master_file() {
        use std::os::fd::{AsFd, AsRawFd};

        let mut backend = super::KmsBackend::for_tests();
        let device = DrmDeviceKey {
            major: 0x7fff_ff02,
            minor: 61,
        };
        push_test_device(&mut backend, device);
        install_admission_owner_gate(&mut backend, device);
        backend.vt_skip_master_ioctls_for_tests = true;
        backend.vt_state = crate::vt::state::VtState::Suspended;
        let barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device,
            Ok(Vec::new()),
            barrier.clone(),
        );

        let mut state = ServerState::new();
        backend.rebuild_randr_state(&mut state, None, false);
        let expected = c0_3bi_expected_end_state(
            backend
                .platform
                .outputs
                .iter()
                .map(|output| output.key.clone()),
        );
        c0_3cii_start_blocked_acquire(
            &mut backend,
            &mut state,
            device,
            &barrier,
            "probe-worker shared-file acquire",
        );

        let source_fd = backend
            .platform
            .device_for_key(device)
            .expect("synthetic Owner device")
            .device
            .attached()
            .expect("attached test DRM device")
            .as_fd()
            .as_raw_fd();
        let observation = backend
            .platform
            .connector_probe_observations_for_tests()
            .into_iter()
            .rev()
            .find(|observation| observation.key == device)
            .expect("worker probe observation");
        let worker_fd = observation.fd;
        assert!(
            !observation
                .fd_closed
                .load(std::sync::atomic::Ordering::Acquire)
        );
        // F_SETFL is attached to the open file description. Seeing this bit
        // through the worker fd proves it is F_DUPFD_CLOEXEC of the same file,
        // rather than a fresh open of the DRM node.
        // SAFETY: fcntl borrows both live descriptors and changes only flags.
        let original = unsafe { libc::fcntl(source_fd, libc::F_GETFL) };
        assert!(original >= 0);
        assert_eq!(
            unsafe { libc::fcntl(source_fd, libc::F_SETFL, original | libc::O_NONBLOCK) },
            0
        );
        let worker_flags = unsafe { libc::fcntl(worker_fd, libc::F_GETFL) };
        assert_eq!(worker_flags & libc::O_NONBLOCK, libc::O_NONBLOCK);
        assert_eq!(
            unsafe { libc::fcntl(worker_fd, libc::F_GETFD) } & libc::FD_CLOEXEC,
            libc::FD_CLOEXEC,
            "the duplicated probe descriptor is close-on-exec"
        );
        assert_eq!(
            unsafe { libc::fcntl(source_fd, libc::F_SETFL, original) },
            0,
            "restore the fixture file status flags"
        );

        barrier.release();
        c0_3cii_finish_probe_workers(&mut backend, &mut state, "join shared-file worker");
        assert!(
            observation
                .fd_closed
                .load(std::sync::atomic::Ordering::Acquire)
        );
        c0_3bi_assert_end_state(
            &backend,
            "c0_3cii_probe_worker_shares_the_master_file",
            &expected,
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_acquire_probe_is_off_the_core_thread_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;
        use std::io::Read;
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber};

        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        let mut state = c0_3ci_core_state(backend);
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device,
            "worker acquire known release",
        );
        let snapshot = c0_3ci_test_probe_results(backend)
            .remove(&device)
            .expect("Owner probe result")
            .expect("healthy Owner snapshot");
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device,
            Ok(snapshot),
            barrier.clone(),
        );
        // Bound the test if a future regression probes synchronously from
        // the core entry: that path cannot reach the assertions below while
        // this real worker is held at the barrier.
        let barrier_timeout = barrier.clone();
        let _barrier_timeout_thread = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(1_500));
            barrier_timeout.release();
        });
        backend.vt_skip_master_ioctls_for_tests = true;
        let mut peer = c0_3aii_install_dpms_core_client(&mut state, 72);

        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device,
            &barrier,
            "blocked Owner acquire probe",
        );
        assert_eq!(backend.vt_state, crate::vt::state::VtState::Resuming);
        assert!(
            !backend.vt_call_trace_for_tests.contains(&"resume_input"),
            "input remains paused until the worker answers"
        );

        let published_output_count = state.randr.outputs.len() as u16;
        let outcome = yserver_core::core_loop::process_request::process_request(
            &mut state,
            backend,
            ClientId(72),
            SequenceNumber(1),
            RequestHeader {
                opcode: 128,
                data: yserver_protocol::x11::randr::RR_GET_SCREEN_RESOURCES_CURRENT,
                length_units: 2,
            },
            &yserver_core::resources::ROOT_WINDOW.0.to_le_bytes(),
            None,
        )
        .expect("published-state GetScreenResourcesCurrent while the probe is blocked");
        assert!(matches!(
            outcome,
            yserver_core::core_loop::process_request::RequestOutcome::Handled
        ));
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "flush query while acquire probe is blocked",
            std::time::Duration::from_millis(100),
            &|_| true,
            None,
        )
        .expect("the core driver services RandR queries during the blocked probe");
        let mut reply_header = [0; 32];
        peer.read_exact(&mut reply_header)
            .expect("client receives the published RandR resource reply");
        assert_eq!(reply_header[0], 1);
        assert_eq!(
            u16::from_le_bytes(reply_header[18..20].try_into().unwrap()),
            published_output_count,
            "query reports the published output set before the worker resolves"
        );
        let extra_units = u32::from_le_bytes(reply_header[4..8].try_into().unwrap());
        let extra_bytes = usize::try_from(extra_units).unwrap() * 4;
        let mut reply_body = vec![0; extra_bytes];
        peer.read_exact(&mut reply_body)
            .expect("client receives the complete resource reply");
        assert_eq!(backend.vt_state, crate::vt::state::VtState::Resuming);

        barrier.release();
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "resolve blocked acquire probe",
            std::time::Duration::from_secs(3),
            &|backend| backend.probe_episode.is_none(),
            None,
        )
        .expect("worker result resolves through poll_deferred_input");
        assert_eq!(backend.vt_state, crate::vt::state::VtState::Active);
        assert_eq!(
            backend.vt_call_trace_for_tests.last(),
            Some(&"resume_input"),
            "input resumes only after the healthy worker result"
        );
        c0_3bi_assert_end_state(
            backend,
            "c0_3cii_acquire_probe_is_off_the_core_thread_vulkan",
            &c0_3ci_expected_end_state_with_acquire_preparation(backend, outputs),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_release_during_acquire_probe_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;

        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        backend.vt_skip_master_ioctls_for_tests = true;
        backend.platform.owner_completion_detached = true;
        let mut state = c0_3ci_core_state(backend);
        let published_before_release = state
            .randr
            .outputs
            .iter()
            .map(|output| (output.output_id, output.connected, output.mode_id))
            .collect::<Vec<_>>();
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device,
            "release-before-acquire-probe fixture",
        );
        let snapshot = c0_3ci_test_probe_results(backend)
            .remove(&device)
            .expect("Owner probe result")
            .expect("healthy Owner snapshot");
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device,
            Ok(snapshot),
            barrier.clone(),
        );
        let acquire_descriptions_before = backend.lifecycle_drivers[&device]
            .acquire_topology_descriptions_for_tests()
            .len();
        let delivery_start = backend.core_entry_deliveries_for_tests.len();
        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device,
            &barrier,
            "release supersedes blocked acquire probe",
        );

        // The executor models helper IPC and the test fixture skips real VT
        // and DRM master ioctls; it does not send a kernel reinstall commit.
        backend.core_driver_vt_releases_for_tests += 1;
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "release while acquire probe is outstanding",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend.vt_state == crate::vt::state::VtState::Suspended
                    && backend.owner_vt_release.is_none()
            },
            None,
        )
        .expect("release supersedes the unfinished acquire through core entries");
        assert!(backend.probe_episode.is_none());
        assert!(backend.acquire_episode.is_none());
        c0_3bi_assert_one_unpublished_topology_end_delivered(
            backend,
            delivery_start,
            None,
            "release supersedes blocked acquire probe",
        );
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .acquire_topology_descriptions_for_tests()
                .len(),
            acquire_descriptions_before,
            "release prevents the acquire reinstall from reaching the executor"
        );
        assert_eq!(
            state
                .randr
                .outputs
                .iter()
                .map(|output| (output.output_id, output.connected, output.mode_id))
                .collect::<Vec<_>>(),
            published_before_release,
            "the release end does not publish an incomplete acquire probe"
        );

        let observations_before_late_answer = backend
            .platform
            .connector_probe_observations_for_tests()
            .len();
        barrier.release();
        c0_3cii_finish_probe_workers(backend, &mut state, "discard released acquire answer");
        assert_eq!(backend.vt_state, crate::vt::state::VtState::Suspended);
        assert_eq!(
            backend
                .platform
                .connector_probe_observations_for_tests()
                .len(),
            observations_before_late_answer,
            "no worker is spawned while the seat is released"
        );
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .acquire_topology_descriptions_for_tests()
                .len(),
            acquire_descriptions_before,
            "the late answer cannot dispatch an acquire reinstall"
        );
        assert_eq!(
            state
                .randr
                .outputs
                .iter()
                .map(|output| (output.output_id, output.connected, output.mode_id))
                .collect::<Vec<_>>(),
            published_before_release,
            "the invalidated late answer cannot change client RandR state"
        );
        c0_3bi_assert_end_state(
            backend,
            "c0_3cii_release_during_acquire_probe_vulkan",
            &c0_3bi_expected_end_state(outputs),
        );
    }

    #[test]
    fn c0_3cii_probe_answer_joins_worker_in_consuming_iteration() {
        let mut backend = KmsBackend::for_tests();
        let device = DrmDeviceKey {
            major: 0x7fff_ff03,
            minor: 73,
        };
        push_test_device(&mut backend, device);
        let incarnation = backend
            .probe_incarnation(device)
            .expect("test Owner incarnation");
        let deferred_device = DrmDeviceKey {
            major: device.major,
            minor: device.minor + 1,
        };
        let epoch = 73;
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(30);
        backend.probe_episode = Some(super::ProbeEpisode {
            cause: super::ProbeEpisodeCause::Acquire,
            epoch,
            deadline,
            participants: [
                (device, Some(incarnation)),
                (deferred_device, Some(IncarnationId::first())),
            ]
            .into_iter()
            .collect(),
            remaining: [device, deferred_device].into_iter().collect(),
            owner_devices: HashSet::from([device]),
            legacy_devices: HashSet::new(),
            results: Default::default(),
            connector_results: Default::default(),
            forced_reprobe_token: None,
        });

        // Hold the worker just after its answer is visible. This makes the
        // send/exit race deterministic: the iteration consuming the answer
        // must join it rather than leave it for a later core wakeup.
        let (result_sent_tx, result_sent_rx) = std::sync::mpsc::channel();
        let (controller_ready_tx, controller_ready_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let result_sender = backend.probe_result_sender.clone();
        let join = std::thread::Builder::new()
            .name("c0-3cii-probe-answer-fixture".into())
            .spawn(move || {
                result_sender
                    .send(super::ProbeWorkerResult {
                        device,
                        incarnation: Some(incarnation),
                        epoch,
                        transition: None,
                        result: Ok(super::ProbeWorkerAnswer::Snapshot(Vec::new())),
                    })
                    .expect("fixture result receiver remains open");
                result_sent_tx.send(()).expect("signal sent result");
                controller_ready_tx
                    .send(())
                    .expect("signal release controller");
                release_rx
                    .recv()
                    .expect("test releases worker after result consumption");
            })
            .expect("spawn controlled probe worker");
        backend.probe_workers.workers.insert(
            device,
            super::ProbeWorker {
                incarnation: Some(incarnation),
                epoch,
                transition: None,
                join,
                lease: None,
                stuck: false,
            },
        );
        let release_controller = std::thread::spawn(move || {
            controller_ready_rx
                .recv()
                .expect("worker publishes its answer before waiting");
            std::thread::sleep(std::time::Duration::from_millis(500));
            let _ = release_tx.send(());
        });
        result_sent_rx
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("worker result is queued before the core iteration");

        let output_keys = backend
            .platform
            .outputs
            .iter()
            .map(|output| output.key.clone())
            .collect::<Vec<_>>();
        let expected_end_state = c0_3bi_expected_end_state(output_keys);
        let mut state = ServerState::new();
        let poll_entries_before = backend
            .core_entry_trace_for_tests
            .borrow()
            .iter()
            .filter(|entry| **entry == "poll_deferred_input")
            .count();
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "consume the worker answer and join it in one core-entry iteration",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend
                    .probe_episode
                    .as_ref()
                    .is_some_and(|episode| episode.results.contains_key(&device))
                    && !backend.probe_workers.workers.contains_key(&device)
            },
            None,
        )
        .expect("the core-entry driver consumes the result and joins its worker");
        release_controller
            .join()
            .expect("release controller completes");

        assert!(
            backend
                .probe_episode
                .as_ref()
                .expect("second participant keeps episode open")
                .results
                .get(&device)
                .expect("same core iteration consumed the answer")
                .as_ref()
                .is_ok_and(Vec::is_empty),
            "the consumed fixture answer is the expected empty snapshot"
        );
        assert!(
            backend.probe_workers.workers.is_empty(),
            "the answer's worker is joined in the iteration that consumes it"
        );
        assert_eq!(
            backend
                .core_entry_trace_for_tests
                .borrow()
                .iter()
                .filter(|entry| **entry == "poll_deferred_input")
                .count(),
            poll_entries_before + 1,
            "one core-driver iteration consumed the queued answer"
        );
        backend.probe_episode = None;
        c0_3bi_assert_end_state(
            &backend,
            "c0_3cii_probe_answer_joins_worker_in_consuming_iteration",
            &expected_end_state,
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_worker_answer_alone_reaches_clients_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;
        use yserver_core::core_loop::{Message, channel};
        use yserver_protocol::x11::randr as rr;

        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        backend.vt_skip_master_ioctls_for_tests = true;
        let mut state = c0_3ci_core_state(backend);
        let mut listener = c0_3aii_install_dpms_core_client(&mut state, 74);
        state.randr_select_masks.insert(
            (74, yserver_core::resources::ROOT_WINDOW),
            rr::NOTIFY_MASK_OUTPUT_CHANGE | rr::NOTIFY_MASK_CRTC_CHANGE,
        );
        let retired_instance = backend
            .scene
            .output_instance_id_for_tests(0)
            .expect("pre-acquire output scene instance");
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device,
            "worker-answer acquire known release",
        );
        let (_poll, sender, receiver) = channel().expect("core wake channel");
        Backend::set_input_sender(backend, sender);
        let mut snapshot = c0_3ci_test_probe_results(backend)
            .remove(&device)
            .expect("Owner probe result")
            .expect("baseline Owner snapshot");
        let mut added_connector = snapshot[0].clone();
        added_connector.key = OutputKey::new(device, "worker-only-added-connector");
        snapshot.push(added_connector);
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device,
            Ok(snapshot),
            barrier.clone(),
        );
        let delivery_start = backend.core_entry_deliveries_for_tests.len();
        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device,
            &barrier,
            "worker-only publication acquire",
        );

        barrier.release();
        let mut worker_wake_seen = false;
        for _ in 0..100 {
            if receiver
                .try_recv_all_tagged()
                .into_iter()
                .any(|(_, message)| matches!(message, Message::CrtcConfigReady))
            {
                worker_wake_seen = true;
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        assert!(worker_wake_seen, "worker answer wakes the core once");

        // No client request, udev edge, or unrelated fd is driven here. The
        // worker wake is the only event that lets the existing core-entry
        // driver consume the result and resolve the acquire publication.
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "consume lone probe result and continue acquire",
            std::time::Duration::from_secs(3),
            &|backend| backend.probe_episode.is_none(),
            None,
        )
        .expect("the answer is consumed from poll_deferred_input");
        let self_wake_seen = receiver
            .try_recv_all_tagged()
            .into_iter()
            .any(|(_, message)| matches!(message, Message::CrtcConfigReady));
        assert!(
            self_wake_seen,
            "result consumption sends CrtcConfigReady after enqueueing its continuation/publication"
        );
        assert!(
            backend.vt_call_trace_for_tests.contains(&"resume_input"),
            "the healthy acquire continuation completed without another stimulus"
        );
        let reinstall = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device,
            "accept reinstall after the worker-only topology change",
        );
        c0_3bi_complete_owner_commit_through_core_driver_with_state(
            backend,
            &mut state,
            device,
            reinstall,
            "apply reinstall after the worker-only topology change",
        );
        let expected = c0_3ci_expected_end_state_with_acquire_preparation(backend, outputs);
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "retire the pre-acquire scene instance and release its allocations",
            std::time::Duration::from_secs(5),
            &|backend| {
                !backend
                    .scene
                    .retired_output_has_instance_for_tests(retired_instance)
                    && c0_3bi_end_state_errors(backend, &expected).is_empty()
            },
            None,
        )
        .expect(
            "the prior scene instance and its resources drain before the final end-state check",
        );
        let added_id = backend
            .randr_id_alloc
            .ids_for(&OutputKey::new(device, "worker-only-added-connector"))
            .output_id;
        assert!(
            state
                .randr
                .outputs
                .iter()
                .any(|output| { output.output_id == added_id && output.connected })
        );
        assert!(
            !kbd_map_drain(&mut listener).is_empty(),
            "the requester-less acquire publication reaches the subscribed client"
        );
        c0_3bi_assert_one_published_topology_episode_delivered(
            backend,
            delivery_start,
            "worker-only topology acquire",
        );
        c0_3bi_assert_end_state(
            backend,
            "c0_3cii_worker_answer_alone_reaches_clients_vulkan",
            &expected,
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_hotplug_while_released_waits_for_acquire_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;
        use yserver_protocol::x11::randr as rr;

        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), true);
        let backend = &mut fixture.backend;
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        backend.vt_skip_master_ioctls_for_tests = true;
        let mut state = c0_3ci_core_state(backend);
        let mut listener = c0_3aii_install_dpms_core_client(&mut state, 76);
        state.randr_select_masks.insert(
            (76, yserver_core::resources::ROOT_WINDOW),
            rr::NOTIFY_MASK_OUTPUT_CHANGE | rr::NOTIFY_MASK_CRTC_CHANGE,
        );
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device,
            "released-seat hotplug acquire fixture",
        );
        let probe_count_while_released = backend
            .platform
            .connector_probe_observations_for_tests()
            .len();
        // Model the already-recorded udev edge. Task 2 owns changing the udev
        // route; in Task 1 this deferred edge must not start a worker while
        // the seat is away, and the next acquire's probe covers it.
        backend.hotplug_rescan_deferred = true;
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "keep released-seat edge deferred",
            std::time::Duration::from_millis(100),
            &|backend| backend.vt_state == crate::vt::state::VtState::Suspended,
            None,
        )
        .expect("deferred hotplug does not start a worker while released");
        assert_eq!(
            backend
                .platform
                .connector_probe_observations_for_tests()
                .len(),
            probe_count_while_released
        );

        let preserved = outputs[0].clone();
        let snapshot = backend
            .platform
            .outputs
            .iter()
            .find(|layout| layout.key == preserved)
            .map(|layout| ConnectorSnapshot {
                key: layout.key.clone(),
                modes: layout.output.modes.clone(),
                mm_width: layout.output.mm_width,
                mm_height: layout.output.mm_height,
                edid: layout.output.edid.clone(),
                connector_type: layout.output.connector_type.clone(),
            })
            .expect("the synthetic second output starts installed");
        backend
            .platform
            .script_connector_probe_for_tests(device, Ok(vec![snapshot]));
        let delivery_start = backend.core_entry_deliveries_for_tests.len();
        c0_3ci_acquire_with_scripted_layout_through_core_driver(
            backend,
            &mut state,
            "acquire covers the released-seat hotplug",
        );
        assert_eq!(
            backend.platform.outputs.len(),
            1,
            "the acquire probe removes the vanished connector from the installed set"
        );
        assert_eq!(backend.platform.outputs[0].key, preserved);
        let reinstall = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device,
            "accept reinstall after released-seat hotplug",
        );
        c0_3bi_complete_owner_commit_through_core_driver_with_state(
            backend,
            &mut state,
            device,
            reinstall,
            "apply reinstall after released-seat hotplug",
        );
        let removed_id = backend.randr_id_alloc.ids_for(&outputs[1]).output_id;
        let removed = state
            .randr
            .outputs
            .iter()
            .find(|output| output.output_id == removed_id)
            .expect("disconnected output remains queryable after acquire");
        assert!(!removed.connected, "acquire publishes the deferred unplug");
        assert!(
            state
                .randr
                .outputs
                .iter()
                .any(|output| { output.name == preserved.connector_name && output.connected })
        );
        assert!(
            !kbd_map_drain(&mut listener).is_empty(),
            "the acquired topology publication reaches the subscribed client once"
        );
        assert_eq!(
            backend
                .platform
                .connector_probe_observations_for_tests()
                .len(),
            probe_count_while_released + 1,
            "the acquire worker is the first probe spawned for this edge"
        );
        c0_3bi_assert_one_published_topology_episode_delivered(
            backend,
            delivery_start,
            "released-seat hotplug acquire",
        );
        let expected = c0_3bi_expected_end_state([preserved]);
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "drain released-seat acquire retirement resources",
            std::time::Duration::from_secs(5),
            &|backend| c0_3bi_end_state_errors(backend, &expected).is_empty(),
            None,
        )
        .unwrap_or_else(|error| {
            panic!(
                "{error}; end_state_errors={:?}; retired={:?}",
                c0_3bi_end_state_errors(backend, &expected),
                backend.scene.retired_output_end_states_for_tests(),
            )
        });
        c0_3bi_assert_end_state(
            backend,
            "c0_3cii_hotplug_while_released_waits_for_acquire_vulkan",
            &expected,
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_mixed_acquire_legacy_failure_on_receipt_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;
        use yserver_core::core_loop::{Message, channel};

        let (mut fixture, owner, owner_outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        backend.vt_skip_master_ioctls_for_tests = true;
        let mut state = c0_3ci_core_state(backend);
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            owner,
            "mixed Legacy failure acquire fixture",
        );
        let (legacy, legacy_output) = c0_3ci_add_legacy_output(backend, 119, 0x3b1_920);
        let barrier = crate::kms::render::platform::ProbeBarrier::new();
        let owner_snapshot = c0_3ci_test_probe_results(backend)
            .remove(&owner)
            .expect("Owner probe result")
            .expect("healthy Owner snapshot");
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        backend.platform.script_blocked_connector_probe_for_tests(
            owner,
            Ok(owner_snapshot),
            barrier.clone(),
        );
        backend
            .platform
            .script_connector_probe_for_tests(legacy, Err(io::Error::from_raw_os_error(libc::EIO)));
        let (_poll, sender, receiver) = channel().expect("core shutdown channel");
        Backend::set_input_sender(backend, sender);
        let started = std::time::Instant::now();

        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            owner,
            &barrier,
            "mixed acquire blocked Owner and failed Legacy probe",
        );
        let messages = std::cell::RefCell::new(Vec::new());
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "consume Legacy EIO while the Owner probe worker stays blocked",
            std::time::Duration::from_secs(1),
            &|_| {
                messages.borrow_mut().extend(receiver.try_recv_all_tagged());
                messages
                    .borrow()
                    .iter()
                    .any(|(_, message)| matches!(message, Message::Shutdown))
            },
            None,
        )
        .expect("Legacy EIO reaches the shutdown channel while Owner remains blocked");
        messages.borrow_mut().extend(receiver.try_recv_all_tagged());
        assert!(
            messages
                .borrow()
                .iter()
                .any(|(_, message)| matches!(message, Message::Shutdown)),
            "the Legacy EIO requests server exit while the Owner worker is still blocked"
        );
        assert!(
            started.elapsed() < super::PROBE_EPISODE_DEADLINE,
            "Legacy failure is consumed on receipt, before the Owner deadline"
        );
        assert!(backend.probe_episode.is_none());
        assert!(barrier.wait_started(std::time::Duration::ZERO));

        barrier.release();
        c0_3cii_finish_probe_workers(backend, &mut state, "join mixed acquire probe workers");
        c0_3bi_assert_end_state(
            backend,
            "c0_3cii_mixed_acquire_legacy_failure_on_receipt_vulkan",
            &c0_3bi_expected_end_state(owner_outputs.into_iter().chain([legacy_output])),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_acquire_probe_no_reply_withdraws_owner_device_vulkan() {
        use yserver_core::core_loop::{Message, channel};

        let (mut fixture, device_a, device_b, outputs_a, outputs_b, mut state) =
            c0_3cii_released_two_owner_fixture();
        let backend = &mut fixture.backend;
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let probes = c0_3ci_test_probe_results(backend);
        let snapshot_a = probes[&device_a]
            .as_ref()
            .expect("healthy A snapshot")
            .clone();
        let snapshot_b = probes[&device_b]
            .as_ref()
            .expect("scripted late B answer")
            .clone();
        let barrier_b = crate::kms::render::platform::ProbeBarrier::new();
        backend
            .platform
            .script_connector_probe_for_tests(device_a, Ok(snapshot_a));
        backend.platform.script_blocked_connector_probe_for_tests(
            device_b,
            Ok(snapshot_b),
            barrier_b.clone(),
        );
        let (_poll, sender, receiver) = channel().expect("core wake channel");
        Backend::set_input_sender(backend, sender);
        let delivery_start = backend.core_entry_deliveries_for_tests.len();

        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device_b,
            &barrier_b,
            "B has no acquire probe answer",
        );
        let deadline = backend
            .probe_episode
            .as_ref()
            .expect("probe episode open while B is blocked")
            .deadline;
        assert!(
            Backend::next_wakeup(backend).is_some_and(|wakeup| wakeup <= deadline),
            "the absolute probe deadline participates in next_wakeup"
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "expire unanswered B probe",
            std::time::Duration::from_secs(3),
            &|backend| backend.probe_episode.is_none(),
            None,
        )
        .expect("the probe episode resolves at its armed deadline");
        assert_eq!(
            backend
                .platform
                .transport_gate(&device_b)
                .map(|gate| gate.state()),
            Some(crate::kms::render::resources::TransportState::Closed),
            "B is closed and withdrawn at the probe deadline"
        );
        let expected_kms_outputs = outputs_a
            .iter()
            .chain(&outputs_b)
            .cloned()
            .collect::<std::collections::HashSet<_>>();
        assert_eq!(backend.platform.outputs.len(), expected_kms_outputs.len());
        assert!(
            backend
                .platform
                .outputs
                .iter()
                .all(|output| { expected_kms_outputs.contains(&output.key) })
        );
        let withdrawn_ids = backend.randr_id_alloc.ids_for(&outputs_b[0]);
        let withdrawn_output_id = withdrawn_ids.output_id;
        let (projected_outputs, _) = backend.randr_outputs_and_modes();
        assert!(
            projected_outputs
                .iter()
                .all(|output| output.output_id != withdrawn_output_id),
            "B's output is withdrawn from the live RandR projection while its KMS layout is retained"
        );
        assert!(
            state
                .randr
                .outputs
                .iter()
                .all(|output| output.output_id != withdrawn_output_id)
        );
        c0_3bi_assert_one_urgent_withdrawal_delivered(
            backend,
            &state,
            delivery_start,
            withdrawn_ids.output_id,
            withdrawn_ids.crtc_id,
            "unanswered acquire probe B",
        );
        assert!(
            receiver
                .try_recv_all_tagged()
                .into_iter()
                .all(|(_, message)| !matches!(message, Message::Shutdown))
        );

        let reinstall = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device_a,
            "healthy A continues after B times out",
        );
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device_a,
            reinstall,
            "apply healthy A reinstall after B times out",
        );
        barrier_b.release();
        c0_3cii_finish_probe_workers(backend, &mut state, "discard B's late acquire answer");
        c0_3bi_assert_one_urgent_withdrawal_delivered(
            backend,
            &state,
            delivery_start,
            withdrawn_ids.output_id,
            withdrawn_ids.crtc_id,
            "late unanswered acquire probe B",
        );
        assert_eq!(
            backend
                .platform
                .transport_gate(&device_b)
                .map(|gate| gate.state()),
            Some(crate::kms::render::resources::TransportState::Closed)
        );
        let expected = c0_3ci_expected_end_state_with_acquire_preparation(
            backend,
            outputs_a.into_iter().chain(outputs_b),
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "drain no-reply acquire retirement proofs",
            std::time::Duration::from_secs(5),
            &|backend| c0_3bi_end_state_errors(backend, &expected).is_empty(),
            None,
        )
        .unwrap_or_else(|error| {
            panic!(
                "no-reply acquire retirement proofs drain: {error}; end_state_errors={:?}; \
                 retired={:?}",
                c0_3bi_end_state_errors(backend, &expected),
                backend.scene.retired_output_end_states_for_tests()
            )
        });
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_acquire_probe_no_reply_withdraws_owner_device_vulkan",
            &expected,
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_stuck_acquire_worker_closes_and_is_reaped_vulkan() {
        let (mut fixture, device_a, device_b, outputs_a, _outputs_b, mut state) =
            c0_3cii_released_two_owner_fixture();
        let backend = &mut fixture.backend;
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let output_a_index = backend
            .platform
            .outputs
            .iter()
            .position(|output| output.key.device_key == device_a)
            .expect("Owner A installed output");
        let output_b_index = backend
            .platform
            .outputs
            .iter()
            .position(|output| output.key.device_key == device_b)
            .expect("Owner B installed output");
        assert_eq!(
            backend
                .scene
                .output_is_excluded_from_composition_for_tests(output_b_index),
            Some(false),
            "B's live scene output starts eligible for composition"
        );
        let probes = c0_3ci_test_probe_results(backend);
        let snapshot_a = probes[&device_a]
            .as_ref()
            .expect("healthy A snapshot")
            .clone();
        let snapshot_b = probes[&device_b]
            .as_ref()
            .expect("healthy B snapshot")
            .clone();
        let barrier_b = crate::kms::render::platform::ProbeBarrier::new();
        backend
            .platform
            .script_connector_probe_for_tests(device_a, Ok(snapshot_a));
        backend.platform.script_blocked_connector_probe_for_tests(
            device_b,
            Ok(snapshot_b),
            barrier_b.clone(),
        );
        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device_b,
            &barrier_b,
            "stuck B acquire worker",
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "close B at the probe deadline",
            std::time::Duration::from_secs(3),
            &|backend| backend.probe_episode.is_none(),
            None,
        )
        .expect("stuck worker fails its participant at the absolute deadline");
        assert!(
            backend
                .probe_workers
                .workers
                .get(&device_b)
                .is_some_and(|worker| worker.stuck)
        );
        let observations_b = backend
            .platform
            .connector_probe_observations_for_tests()
            .into_iter()
            .filter(|observation| observation.key == device_b)
            .collect::<Vec<_>>();
        assert_eq!(observations_b.len(), 1);
        let worker_fd_closed = std::sync::Arc::clone(&observations_b[0].fd_closed);
        assert_eq!(
            backend
                .platform
                .transport_gate(&device_b)
                .map(|gate| gate.state()),
            Some(crate::kms::render::resources::TransportState::Closed)
        );
        assert_eq!(
            backend
                .scene
                .output_is_excluded_from_composition_for_tests(output_b_index),
            Some(true),
            "failed acquire closes B's transport and excludes its retained output from composition"
        );

        let reinstall_a = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device_a,
            "A reinstalls while B's worker remains stuck",
        );
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device_a,
            reinstall_a,
            "apply A reinstall while B is stuck",
        );
        let instance_after_first_acquire = backend
            .scene
            .output_instance_id_for_tests(output_a_index)
            .expect("A scene instance after first acquire");

        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device_a,
            "release before retrying acquire with stuck B",
        );
        let second_snapshot = c0_3ci_test_probe_results(backend)
            .remove(&device_a)
            .expect("second A answer")
            .expect("healthy second A snapshot");
        let second_a_barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device_a,
            Ok(second_snapshot),
            second_a_barrier.clone(),
        );
        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device_a,
            &second_a_barrier,
            "second acquire skips closed B",
        );
        let second_episode = backend
            .probe_episode
            .as_ref()
            .expect("A's second probe remains blocked");
        assert_eq!(
            second_episode
                .participants
                .keys()
                .copied()
                .collect::<Vec<_>>(),
            [device_a],
            "the closed B incarnation is absent from the second probe episode"
        );
        second_a_barrier.release();
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "resolve A's second acquire probe",
            std::time::Duration::from_secs(3),
            &|backend| backend.probe_episode.is_none(),
            None,
        )
        .expect("A's second acquire probe resolves while B stays closed");
        let observations = backend.platform.connector_probe_observations_for_tests();
        assert_eq!(
            observations
                .iter()
                .filter(|observation| observation.key == device_b)
                .count(),
            1,
            "the next acquire does not spawn another worker for closed B"
        );
        let reinstall_a_again = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device_a,
            "A reinstalls on the second acquire",
        );
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device_a,
            reinstall_a_again,
            "apply A's second acquire reinstall",
        );

        barrier_b.release();
        c0_3cii_finish_probe_workers(backend, &mut state, "join returned stuck B worker");
        assert!(backend.probe_workers.workers.is_empty());
        // The worker's OwnedFd is dropped as its prober returns; the ledger
        // keeps only the JoinHandle until poll_deferred_input joins it.
        assert!(worker_fd_closed.load(std::sync::atomic::Ordering::Acquire));
        assert_eq!(
            backend
                .platform
                .transport_gate(&device_b)
                .map(|gate| gate.state()),
            Some(crate::kms::render::resources::TransportState::Closed),
            "the late answer changes nothing after the worker is reaped"
        );
        let expected = c0_3ci_expected_end_state_with_acquire_preparation(
            backend,
            outputs_a.into_iter().chain(_outputs_b),
        );
        let retirement_drained = |backend: &super::KmsBackend| {
            !backend
                .scene
                .retired_output_has_instance_for_tests(instance_after_first_acquire)
                && c0_3bi_end_state_errors(backend, &expected).is_empty()
        };
        c0_3cii_drive_owner_work_until(
            backend,
            &mut state,
            &[device_a, device_b],
            "retire A's displaced scene instance after the second acquire",
            std::time::Duration::from_secs(5),
            &retirement_drained,
        )
        .unwrap_or_else(|error| {
            panic!(
                "{error}; A diagnostics: {}; end_state_errors={:?}; retired={:?}",
                c0_3cii_owner_route_diagnostics_for_tests(backend, device_a),
                c0_3bi_end_state_errors(backend, &expected),
                backend.scene.retired_output_end_states_for_tests(),
            )
        });
        c0_3bi_assert_end_state(
            backend,
            "c0_3cii_stuck_acquire_worker_closes_and_is_reaped_vulkan",
            &expected,
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_stale_probe_discarded_vulkan() {
        let (mut fixture, device_a, device_b, outputs_a, _outputs_b, mut state) =
            c0_3cii_released_two_owner_fixture();
        let backend = &mut fixture.backend;
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let probes = c0_3ci_test_probe_results(backend);
        let snapshot_a = probes[&device_a]
            .as_ref()
            .expect("first A snapshot")
            .clone();
        let snapshot_b = probes[&device_b]
            .as_ref()
            .expect("first B snapshot")
            .clone();
        let first_a_barrier = crate::kms::render::platform::ProbeBarrier::new();
        let old_worker_barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device_a,
            Ok(snapshot_a.clone()),
            first_a_barrier.clone(),
        );
        backend.platform.script_blocked_connector_probe_for_tests(
            device_b,
            Ok(snapshot_b),
            old_worker_barrier.clone(),
        );
        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device_b,
            &old_worker_barrier,
            "first acquire with a late B worker",
        );
        let old_epoch = backend
            .probe_episode
            .as_ref()
            .expect("first probe episode")
            .epoch;
        // Keep the first episode open on B, but make A's successful answer
        // deterministic before release. Otherwise load can leave A's quick
        // worker in the ledger when the next acquire begins, so its stale
        // EIO masks the second episode's intended blocked A probe.
        first_a_barrier.release();
        let first_probe_deadline = backend
            .probe_episode
            .as_ref()
            .expect("first probe episode remains open for B")
            .deadline
            .saturating_duration_since(std::time::Instant::now());
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "consume the first-epoch A answer while B remains blocked",
            first_probe_deadline,
            &|backend| {
                backend.probe_episode.as_ref().is_some_and(|episode| {
                    episode.epoch == old_epoch
                        && episode.results.get(&device_a).is_some_and(Result::is_ok)
                        && !backend.probe_workers.workers.contains_key(&device_a)
                })
            },
            None,
        )
        .expect("A's first-epoch answer is joined before the next acquire");
        assert!(backend.probe_workers.workers.contains_key(&device_b));
        assert!(
            backend
                .probe_episode
                .as_ref()
                .unwrap()
                .remaining
                .contains(&device_b)
        );

        backend.core_driver_vt_releases_for_tests += 1;
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "release supersedes first probe episode",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend.vt_state == crate::vt::state::VtState::Suspended
                    && backend.owner_vt_release.is_none()
            },
            None,
        )
        .expect("release invalidates the first probe epoch");
        assert!(backend.probe_episode.is_none());

        let second_a_barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device_a,
            Ok(snapshot_a.clone()),
            second_a_barrier.clone(),
        );
        c0_3cii_start_blocked_acquire(
            backend,
            &mut state,
            device_a,
            &second_a_barrier,
            "second acquire while old B worker is still held",
        );
        let second_epoch = backend
            .probe_episode
            .as_ref()
            .expect("second probe episode remains open for A")
            .epoch;
        assert_ne!(old_epoch, second_epoch);
        assert!(
            backend
                .probe_episode
                .as_ref()
                .unwrap()
                .remaining
                .contains(&device_a)
        );
        let current_incarnation = backend.probe_episode.as_ref().unwrap().participants[&device_a]
            .expect("Owner probe participant has an incarnation");
        let stale_incarnation = crate::kms::owner::identity::IncarnationId::from_raw(
            current_incarnation.get().saturating_sub(1),
        );
        assert_ne!(stale_incarnation, current_incarnation);

        // The first worker cannot be duplicated while its fd is outstanding,
        // so B's second-episode participant has already failed with EBUSY.
        // This tagged channel item models an answer from an older B incarnation
        // racing an otherwise pending result on A. It tests the result-envelope
        // guard, not an executor or kernel side effect.
        backend
            .probe_result_sender
            .send(super::ProbeWorkerResult {
                device: device_a,
                incarnation: Some(stale_incarnation),
                epoch: second_epoch,
                transition: None,
                result: Ok(super::ProbeWorkerAnswer::Snapshot(snapshot_a)),
            })
            .expect("enqueue stale-incarnation probe answer");
        backend.wake_crtc_config_ready();
        let trace_len_before_stale_result = backend.core_entry_trace_for_tests.borrow().len();
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "discard stale-incarnation result",
            std::time::Duration::from_millis(100),
            &|backend| {
                backend.core_entry_trace_for_tests.borrow().len() > trace_len_before_stale_result
            },
            None,
        )
        .expect("the core driver consumes the tagged stale result");
        assert!(
            backend.probe_episode.as_ref().is_some_and(|episode| {
                episode.remaining.contains(&device_a) && !episode.results.contains_key(&device_a)
            }),
            "wrong-incarnation answer cannot resolve the second episode"
        );

        old_worker_barrier.release();
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "join first-epoch B worker while second episode is open",
            std::time::Duration::from_secs(2),
            &|backend| !backend.probe_workers.workers.contains_key(&device_b),
            None,
        )
        .expect("the old B worker is joined without changing the second episode");
        let episode = backend
            .probe_episode
            .as_ref()
            .expect("A still holds the second probe episode open");
        assert!(episode.remaining.contains(&device_a));
        assert_eq!(
            episode.results[&device_b]
                .as_ref()
                .unwrap_err()
                .raw_os_error(),
            Some(libc::EBUSY),
            "old epoch answer cannot replace B's second-episode stuck-worker failure"
        );

        second_a_barrier.release();
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "resolve second probe episode",
            std::time::Duration::from_secs(3),
            &|backend| backend.probe_episode.is_none(),
            None,
        )
        .expect("fresh A answer resolves the current episode");
        let reinstall = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device_a,
            "accept A after stale probe answers",
        );
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device_a,
            reinstall,
            "apply A after stale probe answers",
        );
        assert!(backend.probe_workers.workers.is_empty());
        let expected = c0_3ci_expected_end_state_with_acquire_preparation(
            backend,
            outputs_a.into_iter().chain(_outputs_b),
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "drain the displaced scene instance after stale probe discard",
            std::time::Duration::from_secs(5),
            &|backend| c0_3bi_end_state_errors(backend, &expected).is_empty(),
            None,
        )
        .unwrap_or_else(|error| {
            panic!(
                "c0_3cii_stale_probe_discarded_vulkan: displaced scene instance did not drain: {error}; end_errors={:?}; retired={:?}",
                c0_3bi_end_state_errors(backend, &expected),
                backend.scene.retired_output_end_states_for_tests()
            )
        });
        c0_3bi_assert_end_state(backend, "c0_3cii_stale_probe_discarded_vulkan", &expected);
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_acquire_enodev_on_receipt_vulkan() {
        use yserver_core::core_loop::{Message, channel};

        fn run_case(errno: i32, case: &str) {
            let (mut fixture, device_a, device_b, outputs_a, outputs_b, mut state) =
                c0_3cii_released_two_owner_fixture();
            let backend = &mut fixture.backend;
            backend
                .platform
                .install_scripted_connector_prober_for_tests();
            let output_a_index = backend
                .platform
                .outputs
                .iter()
                .position(|output| output.key.device_key == device_a)
                .expect("Owner A installed output");
            let retired_instance_a = backend
                .scene
                .output_instance_id_for_tests(output_a_index)
                .expect("pre-acquire Owner A scene instance");
            let probes = c0_3ci_test_probe_results(backend);
            let snapshot_a = probes[&device_a]
                .as_ref()
                .expect("blocked A snapshot")
                .clone();
            let barrier_a = crate::kms::render::platform::ProbeBarrier::new();
            backend.platform.script_blocked_connector_probe_for_tests(
                device_a,
                Ok(snapshot_a),
                barrier_a.clone(),
            );
            backend.platform.script_connector_probe_for_tests(
                device_b,
                Err(io::Error::from_raw_os_error(errno)),
            );
            let (_poll, sender, receiver) = channel().expect("core wake channel");
            Backend::set_input_sender(backend, sender);

            let delivery_start = backend.core_entry_deliveries_for_tests.len();
            c0_3cii_start_blocked_acquire(backend, &mut state, device_a, &barrier_a, case);
            c0_3bi_core_driver_until_with_state(
                backend,
                &mut state,
                case,
                std::time::Duration::from_secs(1),
                &|backend| {
                    backend
                        .platform
                        .transport_gate(&device_b)
                        .is_some_and(|gate| {
                            gate.state() == crate::kms::render::resources::TransportState::Closed
                        })
                },
                None,
            )
            .unwrap_or_else(|error| {
                panic!("{case}: B failure is consumed while A is blocked: {error}")
            });

            assert!(backend.probe_episode.as_ref().is_some_and(|episode| {
                episode.remaining.contains(&device_a) && !episode.remaining.contains(&device_b)
            }));
            let b_is_removed =
                backend
                    .lifecycle_coordinator
                    .device(&device_b)
                    .is_some_and(|arbiter| {
                        arbiter.state()
                            == crate::kms::owner::lifecycle::DeviceLifecycleState::Removed
                    });
            if errno == libc::ENODEV {
                assert!(b_is_removed, "{case}: ENODEV is DeviceRemoved at receipt");
                assert!(
                    !backend
                        .probe_episode
                        .as_ref()
                        .unwrap()
                        .results
                        .contains_key(&device_b),
                    "{case}: a removed participant has no failed probe result"
                );
            } else {
                assert!(!b_is_removed, "{case}: EIO is not DeviceRemoved");
                assert_eq!(
                    backend.probe_episode.as_ref().unwrap().results[&device_b]
                        .as_ref()
                        .unwrap_err()
                        .raw_os_error(),
                    Some(errno),
                    "{case}: the ordinary probe failure preserves its errno"
                );
            }
            let ids = backend.randr_id_alloc.ids_for(&outputs_b[0]);
            c0_3bi_assert_one_urgent_withdrawal_delivered(
                backend,
                &state,
                delivery_start,
                ids.output_id,
                ids.crtc_id,
                &format!("{case}: B's withdrawal before A answers"),
            );
            assert!(
                receiver
                    .try_recv_all_tagged()
                    .into_iter()
                    .any(|(_, message)| matches!(message, Message::CrtcConfigReady))
            );

            barrier_a.release();
            c0_3bi_core_driver_until_with_state(
                backend,
                &mut state,
                case,
                std::time::Duration::from_secs(3),
                &|backend| backend.probe_episode.is_none(),
                None,
            )
            .unwrap_or_else(|error| panic!("{case}: A's healthy answer resolves: {error}"));
            let reinstall = c0_3ci_wait_owner_acquire_accepted(backend, &mut state, device_a, case);
            c0_3bi_complete_owner_commit_through_core_driver_with_state(
                backend, &mut state, device_a, reinstall, case,
            );
            let expected = if errno == libc::ENODEV {
                c0_3cii_removed_end_state(
                    backend,
                    outputs_a.iter().chain(&outputs_b).cloned(),
                    device_b,
                )
            } else {
                c0_3ci_expected_end_state_with_acquire_preparation(
                    backend,
                    outputs_a.iter().chain(&outputs_b).cloned(),
                )
            };
            c0_3bi_core_driver_until_with_state(
                backend,
                &mut state,
                case,
                std::time::Duration::from_secs(5),
                &|backend| {
                    !backend
                        .scene
                        .retired_output_has_instance_for_tests(retired_instance_a)
                        && c0_3bi_end_state_errors(backend, &expected).is_empty()
                },
                None,
            )
            .unwrap_or_else(|error| {
                panic!(
                    "{case}: retired A output and resource service drain: {error}; \
                     end_state_errors={:?}; retired={:?}",
                    c0_3bi_end_state_errors(backend, &expected),
                    backend.scene.retired_output_end_states_for_tests(),
                )
            });
            c0_3bi_assert_end_state(backend, case, &expected);
        }

        run_case(libc::ENODEV, "ENODEV withdraws B before A answers");
        run_case(libc::EIO, "EIO withdraws B before A answers");
    }

    #[test]
    #[ignore = "hardware probe only; do not run in the implementation pass"]
    #[cfg(target_os = "linux")]
    fn c0_hw_3cii_probe_worker_on_card1_drm() {
        use std::{
            fs,
            os::{
                fd::{AsFd, AsRawFd, OwnedFd},
                unix::fs::{FileTypeExt, MetadataExt},
            },
            sync::{Arc, Mutex},
            time::Instant,
        };

        struct RecordingProductionProber {
            answer: Mutex<Option<Vec<ConnectorSnapshot>>>,
            worker_thread: Mutex<Option<std::thread::ThreadId>>,
            worker_probe_duration: Mutex<Option<std::time::Duration>>,
            master_fd: std::os::fd::RawFd,
            worker_saw_master_file_status_flag: Mutex<Option<bool>>,
            master_file_status_flag_restored: Mutex<Option<bool>>,
        }

        impl crate::kms::render::platform::ConnectorProber for RecordingProductionProber {
            fn probe_snapshot(
                &self,
                key: DrmDeviceKey,
                fd: OwnedFd,
            ) -> io::Result<Vec<ConnectorSnapshot>> {
                *self.worker_thread.lock().expect("record worker thread") =
                    Some(std::thread::current().id());

                // F_SETFL status flags belong to the open file description.
                // Device::open set O_NONBLOCK on the master. Clear and then
                // set it through the master only after the worker fd exists,
                // observe it through that fd, then restore the original flags.
                // A fresh blocking open of card1 would not inherit this marker.
                // SAFETY: fcntl borrows both live descriptors; the master fd
                // remains owned by the test while the worker runs.
                let master_flags = unsafe { libc::fcntl(self.master_fd, libc::F_GETFL) };
                let (marker_visible, restored) =
                    if master_flags >= 0 && master_flags & libc::O_NONBLOCK != 0 {
                        let clear_result = unsafe {
                            libc::fcntl(
                                self.master_fd,
                                libc::F_SETFL,
                                master_flags & !libc::O_NONBLOCK,
                            )
                        };
                        let set_result = if clear_result == 0 {
                            unsafe { libc::fcntl(self.master_fd, libc::F_SETFL, master_flags) }
                        } else {
                            -1
                        };
                        let worker_flags = if set_result == 0 {
                            unsafe { libc::fcntl(fd.as_raw_fd(), libc::F_GETFL) }
                        } else {
                            -1
                        };
                        let restore_result =
                            unsafe { libc::fcntl(self.master_fd, libc::F_SETFL, master_flags) };
                        (
                            clear_result == 0
                                && set_result == 0
                                && worker_flags >= 0
                                && worker_flags & libc::O_NONBLOCK != 0,
                            restore_result == 0,
                        )
                    } else {
                        (false, false)
                    };
                *self
                    .worker_saw_master_file_status_flag
                    .lock()
                    .expect("record master file-status observation") = Some(marker_visible);
                *self
                    .master_file_status_flag_restored
                    .lock()
                    .expect("record master file-status restoration") = Some(restored);

                let probe_started = Instant::now();
                let probe_result =
                    crate::kms::render::platform::DrmConnectorProber.probe_snapshot(key, fd);
                *self
                    .worker_probe_duration
                    .lock()
                    .expect("record worker probe duration") = Some(probe_started.elapsed());
                let answer = probe_result?;
                *self.answer.lock().expect("record worker answer") = Some(answer.clone());
                Ok(answer)
            }

            fn probe_connectors(
                &self,
                key: DrmDeviceKey,
                fd: OwnedFd,
            ) -> io::Result<Vec<crate::platform::drm::ConnectorProbe>> {
                crate::kms::render::platform::DrmConnectorProber.probe_connectors(key, fd)
            }
        }

        let card1 = "/dev/dri/card1";
        // Device::open is the production Owner path: it acquires DRM master,
        // enables the KMS client capabilities and marks the master's OFD
        // nonblocking. The worker must dup this fd so the kernel performs the
        // forced connector probe rather than demoting it to its cached probe.
        let source = std::rc::Rc::new(
            crate::drm::Device::open(card1)
                .unwrap_or_else(|error| panic!("open card1 as DRM Owner: {error}")),
        );
        let key = crate::platform::drm::primary_device_key_from_fd(source.as_fd())
            .unwrap_or_else(|error| panic!("identify card1 Owner fd: {error}"));
        let card1_identity = fs::metadata(card1).expect("stat card1 device node");
        let count_card1_fds = || {
            fs::read_dir("/proc/self/fd")
                .expect("read this process's fd directory")
                .filter_map(Result::ok)
                .filter_map(|entry| fs::metadata(entry.path()).ok())
                .filter(|metadata| {
                    metadata.file_type().is_char_device()
                        && metadata.dev() == card1_identity.dev()
                        && metadata.ino() == card1_identity.ino()
                        && metadata.rdev() == card1_identity.rdev()
                })
                .count()
        };

        // The full live-KMS fixture requires a connected mode and performs an
        // initial modeset. Reuse the headless state fixture, replacing its
        // sole device with card1 so no `/dev/null` Legacy device can
        // participate in this acquire episode.
        let mut backend = super::KmsBackend::for_tests();
        assert_eq!(backend.platform.devices.len(), 1);
        // A successful Owner continuation may dispatch a topology reinstall.
        // This fixture helper accepts the executor protocol request but never
        // issues a DRM commit, so the test cannot modeset card1.
        let executor = crate::kms::executor::test_support::spawn_stub_helper(
            crate::kms::executor::test_support::StubBehaviour::AcceptKernelCalls(1_000),
        )
        .expect("spawn card1 acquire fixture executor");
        let (incarnation, lifecycle) = executor.owner_identity();
        backend.platform.devices[0].key = key;
        backend.platform.devices[0].device = std::rc::Rc::clone(&source).into();
        backend.platform.devices[0].executor = Some(executor);
        backend.platform.devices[0].owner = Some(
            crate::kms::owner::device::DeviceCommitOwner::new(incarnation, lifecycle, 1),
        );
        backend.platform.outputs[0].key.device_key = key;
        backend.platform.outputs[0].scanout_route.kms_device_key = key;
        backend
            .platform
            .rebuild_output_instance_ids_for_tests()
            .expect("rekey the synthetic output instance to card1");
        backend.platform.reap_executors_on_drop_for_tests();
        install_admission_owner_gate(&mut backend, key);
        backend.install_admission_conductor_with_backend_composed_for_tests(
            key,
            AdmissionSourceFixture::new_source().0,
        );
        backend
            .lifecycle_register_owner_device(key)
            .expect("register card1 Owner lifecycle");
        let prober = Arc::new(RecordingProductionProber {
            answer: Mutex::new(None),
            worker_thread: Mutex::new(None),
            worker_probe_duration: Mutex::new(None),
            master_fd: source.as_fd().as_raw_fd(),
            worker_saw_master_file_status_flag: Mutex::new(None),
            master_file_status_flag_restored: Mutex::new(None),
        });
        backend.platform.connector_prober = prober.clone();
        // Device::open already holds DRM master. Avoid a second SET_MASTER in
        // the simulated VT-acquire entry while retaining the real master fd.
        backend.vt_skip_master_ioctls_for_tests = true;
        backend.vt_state = crate::vt::state::VtState::Suspended;
        let input_control = Arc::new(
            crate::input_thread::InputThreadControl::new().expect("input control eventfd"),
        );
        input_control.pause();
        backend.set_input_thread_control(Arc::clone(&input_control));
        let mut state = ServerState::new();
        backend.rebuild_randr_state(&mut state, None, false);
        let initial_output_keys = backend
            .platform
            .outputs
            .iter()
            .map(|output| output.key.clone())
            .collect::<Vec<_>>();

        let card1_fds_before_probe = count_card1_fds();
        let started = Instant::now();
        backend.core_driver_vt_acquires_for_tests += 1;
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "card1 production probe worker starts",
            std::time::Duration::from_secs(1),
            &|backend| {
                backend.probe_episode.is_some() && backend.probe_workers.workers.contains_key(&key)
            },
            None,
        )
        .expect("the card1 worker starts within the acquire episode");
        let episode = backend
            .probe_episode
            .as_ref()
            .expect("card1 worker belongs to an open acquire episode");
        assert_eq!(
            episode.participants.keys().copied().collect::<Vec<_>>(),
            [key],
            "card1 is the acquire episode's only participant"
        );
        assert_eq!(
            episode.owner_devices,
            HashSet::from([key]),
            "card1 participates through the Owner route"
        );
        assert!(
            episode.legacy_devices.is_empty(),
            "the acquire episode has no Legacy or /dev/null participant"
        );
        let episode_epoch = episode.epoch;
        let episode_incarnation =
            episode.participants[&key].expect("card1 Owner probe participant has an incarnation");
        let worker = backend
            .probe_workers
            .workers
            .get(&key)
            .expect("card1 worker remains in the ledger");
        assert_eq!(worker.epoch, episode_epoch);
        assert_eq!(worker.incarnation, Some(episode_incarnation));

        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "card1 production probe answer and acquire continuation",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend.probe_episode.is_none()
                    && backend.probe_workers.workers.is_empty()
                    && backend.vt_state == crate::vt::state::VtState::Active
                    && backend.vt_call_trace_for_tests.contains(&"resume_input")
            },
            None,
        )
        .expect("the card1 probe answer resolves the episode and resumes the seat");
        let elapsed = started.elapsed();
        let worker_probe_duration = prober
            .worker_probe_duration
            .lock()
            .expect("worker probe duration lock")
            .expect("production probe duration recorded around DrmConnectorProber");
        assert!(
            worker_probe_duration < super::PROBE_EPISODE_DEADLINE,
            "WORKER PROBE took {worker_probe_duration:?}, above the {:?} episode deadline",
            super::PROBE_EPISODE_DEADLINE
        );
        assert!(
            elapsed < super::PROBE_EPISODE_DEADLINE,
            "the acquire episode resolved from its worker answer in {elapsed:?}, before its deadline"
        );

        assert_eq!(backend.vt_state, crate::vt::state::VtState::Active);
        assert!(backend.vt_call_trace_for_tests.contains(&"resume_input"));
        assert_eq!(
            input_control.drain(),
            vec![crate::input_thread::InputThreadCommand::Resume],
            "the successful acquire continuation resumes the input thread"
        );
        assert_eq!(
            backend
                .platform
                .transport_gate(&key)
                .map(|gate| gate.state()),
            Some(crate::kms::render::resources::TransportState::Owner),
            "card1's successful answer keeps its Owner transport open"
        );
        assert!(
            backend
                .lifecycle_coordinator
                .device(&key)
                .is_some_and(|arbiter| {
                    arbiter.desired().device_presence() == Some(true)
                        && arbiter.desired().seat_target()
                            == Some(crate::kms::owner::lifecycle::SeatTarget::Owned)
                }),
            "card1's answer is consumed by the current episode and reaches the Owner continuation"
        );

        assert!(
            backend.probe_workers.workers.is_empty(),
            "the completed probe worker was joined and removed from the ledger"
        );
        let card1_fds_after_join = count_card1_fds();
        assert_eq!(
            card1_fds_after_join, card1_fds_before_probe,
            "joining the worker closes its duplicate of the card1 master fd"
        );

        let worker_snapshot = prober
            .answer
            .lock()
            .expect("worker answer lock")
            .clone()
            .expect("production worker answered successfully");
        assert!(
            worker_snapshot
                .iter()
                .all(|snapshot| snapshot.key.device_key == key)
        );
        let expected_end_state =
            c0_3bi_expected_end_state(initial_output_keys.into_iter().filter(|output| {
                output.device_key != key
                    || worker_snapshot
                        .iter()
                        .any(|snapshot| &snapshot.key == output && !snapshot.modes.is_empty())
            }));
        let synchronous_snapshot = crate::platform::drm::probe_connector_snapshots(&source)
            .unwrap_or_else(|error| panic!("synchronous card1 comparison probe: {error}"))
            .iter()
            .map(|probe| ConnectorSnapshot::from_probe(key, probe))
            .collect::<Vec<_>>();
        assert_eq!(worker_snapshot.len(), synchronous_snapshot.len());
        for (worker, synchronous) in worker_snapshot.iter().zip(&synchronous_snapshot) {
            assert_eq!(worker.key, synchronous.key);
            assert_eq!(worker.modes, synchronous.modes);
            assert_eq!(worker.mm_width, synchronous.mm_width);
            assert_eq!(worker.mm_height, synchronous.mm_height);
            assert_eq!(worker.edid, synchronous.edid);
            assert_eq!(worker.connector_type, synchronous.connector_type);
        }
        let worker_thread = prober
            .worker_thread
            .lock()
            .expect("worker thread lock")
            .expect("production worker thread recorded");
        assert_ne!(worker_thread, std::thread::current().id());
        assert!(
            prober
                .worker_saw_master_file_status_flag
                .lock()
                .expect("master file-status observation lock")
                .expect("worker master file-status observation recorded"),
            "the worker fd sees O_NONBLOCK set through the master fd after the worker fd exists"
        );
        assert!(
            prober
                .master_file_status_flag_restored
                .lock()
                .expect("master file-status restoration lock")
                .expect("master file-status restoration recorded"),
            "the master's original file-status flags are restored"
        );
        eprintln!(
            "card1 WORKER PROBE duration: {worker_probe_duration:?}; acquire episode completion: {elapsed:?}"
        );
        c0_3bi_assert_end_state(
            &backend,
            "c0_hw_3cii_probe_worker_on_card1_drm",
            &expected_end_state,
        );
    }

    #[test]
    fn c0_3cii_legacy_only_acquire_unchanged() {
        let mut backend = super::KmsBackend::for_tests();
        backend.vt_skip_master_ioctls_for_tests = true;
        backend.vt_resume_succeeds_for_tests = true;
        backend.vt_state = crate::vt::state::VtState::Suspended;
        let outputs = backend
            .platform
            .outputs
            .iter()
            .map(|output| output.key.clone())
            .collect::<Vec<_>>();
        let mut state = ServerState::new();
        backend.rebuild_randr_state(&mut state, None, false);

        backend.core_driver_vt_acquires_for_tests += 1;
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "Legacy-only synchronous acquire",
            std::time::Duration::from_secs(1),
            &|backend| {
                backend.core_driver_vt_acquires_for_tests == 0
                    && backend.vt_state == crate::vt::state::VtState::Active
            },
            None,
        )
        .expect("Legacy-only acquire uses its established synchronous route");
        assert!(backend.probe_episode.is_none());
        assert!(backend.probe_workers.workers.is_empty());
        assert!(
            backend
                .core_entry_trace_for_tests
                .borrow()
                .contains(&"vt_acquire")
        );
        c0_3bi_assert_end_state(
            &backend,
            "c0_3cii_legacy_only_acquire_unchanged",
            &c0_3bi_expected_end_state(outputs),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_acquire_releases_displaced_composed_work_vulkan() {
        use crate::kms::{
            executor::test_support::StubBehaviour,
            render::{owner_buffer::OwnerBufferState, platform::ScanoutRenderCompletionStage},
            vk::scanout::BoPhase,
        };

        // A completed render with an admission offer becomes Displaced when
        // VT acquire retires its old output instance.
        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        let previous_completion_deadline = backend
            .platform
            .owner_ref(device)
            .expect("Owner device")
            .completion_deadline_override;
        c0_3bi_set_owner_completion_deadline_for_tests(
            backend,
            device,
            Some(std::time::Duration::from_secs(30)),
        );
        c0_3bi_settle_owner_frame_work_through_core_driver(
            backend,
            device,
            "settle Owner fixture before preparing displaced acquire work",
            std::time::Duration::from_secs(3),
        )
        .expect("initial Owner frame work settles before the acquire subject is prepared");
        let output_key = outputs[0].clone();
        let instance = backend
            .scene
            .output_instance_id_for_tests(0)
            .expect("the live Owner output instance");
        let crtc = u32::from(backend.platform.outputs[0].output.crtc);
        let previous_generation = backend
            .scene
            .owner_buffer_identities_for_tests(0)
            .into_iter()
            .filter(|identity| identity.output_key == output_key && identity.crtc == crtc)
            .map(|identity| identity.generation)
            .max()
            .unwrap_or(0);
        backend
            .admission_conductors
            .get_mut(&device)
            .expect("active admission conductor")
            .lifecycle_admission_closed = true;
        backend
            .platform
            .hold_next_scanout_render_completion_for_tests(
                instance,
                ScanoutRenderCompletionStage::Render,
            );
        backend.scene.mark_scene_structure_dirty();
        backend.tick_maybe_composite_for_tests_without_render_completion_drain();
        let (bo_idx, generation, waiting) = backend
            .scene
            .owner_prepared_for_tests(0)
            .expect("the dirty Owner scene starts an exact render generation");
        assert!(waiting, "the exact render is still pending");
        assert!(generation > previous_generation);
        let (target_identity, target_state) = backend
            .scene
            .owner_buffer_for_generation_anywhere_for_tests(&output_key, bo_idx, generation)
            .expect("the prepared Rendering generation has a complete identity");
        assert_eq!(target_state, OwnerBufferState::Rendering);
        let render_fence = backend
            .scene
            .hold_owner_render_fence_for_tests(0, generation)
            .expect("hold the exact render ticket before the next core poll");
        backend.platform.wait_idle_bounded();
        let completion = backend
            .platform
            .held_scanout_render_completion_for_tests(
                instance,
                ScanoutRenderCompletionStage::Render,
            )
            .expect("the held exact render notification is ready");
        backend
            .platform
            .release_scanout_render_completion_for_tests(completion)
            .expect("make the held exact render notification visible to the core driver");
        c0_3bi_core_driver_until_before_iteration_tail(
            backend,
            "observe the held Desired generation before a successor compose",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .scene
                    .owner_buffer_for_generation_anywhere_for_tests(&output_key, bo_idx, generation)
                    .is_some_and(|(identity, state)| {
                        identity == target_identity && state == OwnerBufferState::Desired
                    })
            },
        )
        .expect("the core entry observes render completion for the held generation");
        assert_eq!(
            backend
                .scene
                .owner_buffer_for_generation_anywhere_for_tests(&output_key, bo_idx, generation)
                .map(|(_, state)| state),
            Some(OwnerBufferState::Desired)
        );
        let allocations =
            c0_3bi_scanout_allocation_keys(backend, device, &output_key.connector_name);
        assert_eq!(
            backend
                .scene
                .owner_state_for_generation_for_tests(0, generation),
            Some(OwnerBufferState::Desired)
        );
        let mut state = c0_3ci_core_state(backend);
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device,
            "release with a displaced composed frame",
        );
        assert_eq!(
            backend
                .scene
                .owner_state_for_generation_for_tests(0, generation),
            Some(OwnerBufferState::Desired),
            "VT release leaves the held unsubmitted generation queued until acquire retires its output"
        );
        c0_3ci_acquire_with_scripted_layout_through_core_driver(
            backend,
            &mut state,
            "acquire with a displaced composed frame",
        );
        let reinstall = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device,
            "accept acquire with a displaced composed frame",
        );
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device,
            reinstall,
            "complete acquire with a displaced composed frame",
        );

        c0_3cii_drive_owner_work_until(
            backend,
            &mut state,
            &[device],
            "retain displaced frame while its render fence is withheld",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend
                    .scene
                    .retired_output_end_states_for_tests()
                    .iter()
                    .any(|bundle| {
                        bundle.instance == instance
                            && bundle.gpu_fence_proofs == 1
                            && bundle
                                .owner_buffers
                                .contains(&(bo_idx, OwnerBufferState::Displaced))
                            && backend
                                .scene
                                .owner_buffer_for_generation_anywhere_for_tests(
                                    &output_key,
                                    bo_idx,
                                    generation,
                                )
                                .is_some_and(|(identity, state)| {
                                    identity == target_identity
                                        && state == OwnerBufferState::Displaced
                                })
                    })
            },
        )
        .expect("the held Desired generation remains in the retired bundle");
        let retired = backend
            .scene
            .retired_output_end_states_for_tests()
            .into_iter()
            .find(|bundle| bundle.instance == instance)
            .expect("the old instance has a retired bundle");
        assert_eq!(
            retired.owner_buffers,
            vec![(bo_idx, OwnerBufferState::Displaced)]
        );
        assert_eq!(retired.phases[bo_idx], BoPhase::Owner);
        assert_eq!(retired.gpu_fence_proofs, 1);
        c0_3bi_assert_no_retired_instance_offer(backend, device, crtc, instance, generation);
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_acquire_releases_displaced_composed_work_vulkan while withheld",
            &C0EndStateExpectation {
                installed_outputs: outputs.clone(),
                retained_bundles: vec![C0ExpectedRetiredBundle {
                    instance,
                    proofs: vec![
                        C0RetiredProofKind::GpuFence,
                        C0RetiredProofKind::ResourceProof,
                    ],
                }],
                ..C0EndStateExpectation::default()
            },
        );

        render_fence.release_polling_for_tests();
        c0_3bi_core_driver_until(
            backend,
            "free displaced composed work after its render fence",
            std::time::Duration::from_secs(4),
            &|backend| {
                !backend
                    .scene
                    .retired_output_has_instance_for_tests(instance)
            },
            None,
        )
        .expect("the retired bundle drains after the render fence signals");
        assert!(allocations.iter().all(|key| {
            backend
                .resource_service()
                .is_none_or(|service| !service.contains(key))
        }));
        c0_3bi_settle_owner_frame_work_through_core_driver(
            backend,
            device,
            "settle successor work after displaced composed work is released",
            std::time::Duration::from_secs(3),
        )
        .expect("successor work settles through core entries after acquire");
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_acquire_releases_displaced_composed_work_vulkan after signal",
            &c0_3bi_expected_end_state(outputs),
        );
        c0_3bi_set_owner_completion_deadline_for_tests(
            backend,
            device,
            previous_completion_deadline,
        );

        // A Rendering buffer can reach VT release before its render
        // completion is serviced. The inactive-seat completion entry drops
        // that notification; retired-bundle service must still consume its
        // GPU batch when the fence later proves the work is finished.
        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        let previous_completion_deadline = backend
            .platform
            .owner_ref(device)
            .expect("Owner device")
            .completion_deadline_override;
        c0_3bi_set_owner_completion_deadline_for_tests(
            backend,
            device,
            Some(std::time::Duration::from_secs(30)),
        );
        c0_3bi_settle_owner_frame_work_through_core_driver(
            backend,
            device,
            "settle Owner fixture before preparing Rendering retirement",
            std::time::Duration::from_secs(3),
        )
        .expect("initial Owner frame work settles before the Rendering subject is prepared");
        let output_key = outputs[0].clone();
        let instance = backend
            .scene
            .output_instance_id_for_tests(0)
            .expect("old output instance");
        backend
            .admission_conductors
            .get_mut(&device)
            .expect("active admission conductor")
            .lifecycle_admission_closed = true;
        backend
            .platform
            .hold_next_scanout_render_completion_for_tests(
                instance,
                ScanoutRenderCompletionStage::Render,
            );
        backend.scene.mark_scene_structure_dirty();
        backend.tick_maybe_composite_for_tests_without_render_completion_drain();
        let (bo_idx, generation, waiting) = backend
            .scene
            .owner_prepared_for_tests(0)
            .expect("the live Owner fixture composed a frame");
        assert!(waiting, "the render is still pending");
        assert_eq!(
            backend
                .scene
                .owner_state_for_generation_for_tests(0, generation),
            Some(OwnerBufferState::Rendering)
        );
        let allocations =
            c0_3bi_scanout_allocation_keys(backend, device, &output_key.connector_name);
        let (target_identity, target_state) = backend
            .scene
            .owner_buffer_for_generation_anywhere_for_tests(&output_key, bo_idx, generation)
            .expect("the prepared Rendering generation has a complete identity");
        assert_eq!(target_state, OwnerBufferState::Rendering);
        let render_fence = backend
            .scene
            .hold_owner_render_fence_for_tests(0, generation)
            .expect("the Rendering generation retains its render fence");
        backend.platform.wait_idle_bounded();
        let completion = backend
            .platform
            .held_scanout_render_completion_for_tests(
                instance,
                ScanoutRenderCompletionStage::Render,
            )
            .expect("the render completion remains held before VT release");

        let mut state = c0_3ci_core_state(backend);
        Backend::on_vt_release(backend, &mut state);
        backend
            .platform
            .release_scanout_render_completion_for_tests(completion)
            .expect("make the completed render notification visible");
        backend.drain_scanout_render_completions_for_tests();
        assert_eq!(
            backend
                .platform
                .pending_scanout_render_completion_count_for_tests(),
            0,
            "the inactive-seat drain consumed the notification before promotion"
        );
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device,
            "finish release after the render notification was dropped",
        );
        c0_3ci_acquire_with_scripted_layout_through_core_driver(
            backend,
            &mut state,
            "acquire after the render notification was dropped",
        );
        let reinstall = c0_3ci_wait_owner_acquire_accepted(
            backend,
            &mut state,
            device,
            "accept acquire after the render notification was dropped",
        );
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device,
            reinstall,
            "complete acquire after the render notification was dropped",
        );

        c0_3cii_drive_owner_work_until(
            backend,
            &mut state,
            &[device],
            "retain Rendering work as Displaced behind its render fence",
            std::time::Duration::from_secs(2),
            &|backend| {
                backend
                    .scene
                    .retired_output_end_states_for_tests()
                    .iter()
                    .any(|bundle| {
                        bundle.instance == instance
                            && bundle.gpu_fence_proofs == 1
                            && bundle
                                .owner_buffers
                                .contains(&(bo_idx, OwnerBufferState::Displaced))
                            && backend
                                .scene
                                .owner_buffer_for_generation_anywhere_for_tests(
                                    &output_key,
                                    bo_idx,
                                    generation,
                                )
                                .is_some_and(|(identity, state)| {
                                    identity == target_identity
                                        && state == OwnerBufferState::Displaced
                                })
                    })
            },
        )
        .expect("the held Rendering generation remains in the retired bundle");
        let retired = backend
            .scene
            .retired_output_end_states_for_tests()
            .into_iter()
            .find(|bundle| bundle.instance == instance)
            .expect("the old Rendering instance remains retired");
        assert_eq!(
            retired.owner_buffers,
            vec![(bo_idx, OwnerBufferState::Displaced)]
        );
        assert_eq!(retired.phases[bo_idx], BoPhase::Owner);
        assert_eq!(retired.gpu_fence_proofs, 1);
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_acquire_releases_displaced_composed_work_vulkan Rendering withheld",
            &C0EndStateExpectation {
                installed_outputs: outputs.clone(),
                retained_bundles: vec![C0ExpectedRetiredBundle {
                    instance,
                    proofs: vec![
                        C0RetiredProofKind::GpuFence,
                        C0RetiredProofKind::ResourceProof,
                    ],
                }],
                ..C0EndStateExpectation::default()
            },
        );

        render_fence.release_polling_for_tests();
        c0_3bi_core_driver_until(
            backend,
            "release dropped Rendering work after its render fence",
            std::time::Duration::from_secs(4),
            &|backend| {
                !backend
                    .scene
                    .retired_output_has_instance_for_tests(instance)
            },
            None,
        )
        .expect("the retired bundle registers and discharges the completed render batch");
        assert!(allocations.iter().all(|key| {
            backend
                .resource_service()
                .is_none_or(|service| !service.contains(key))
        }));
        c0_3bi_settle_owner_frame_work_through_core_driver(
            backend,
            device,
            "settle successor work after Rendering retirement",
            std::time::Duration::from_secs(3),
        )
        .expect("successor work settles through core entries after Rendering retirement");
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_acquire_releases_displaced_composed_work_vulkan Rendering after signal",
            &c0_3bi_expected_end_state(outputs),
        );
        c0_3bi_set_owner_completion_deadline_for_tests(
            backend,
            device,
            previous_completion_deadline,
        );
    }

    fn c0_3ci_live_release_fixture(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
        two_outputs: bool,
    ) -> (
        OwnerLiveFixture,
        DrmDeviceKey,
        Vec<OutputKey>,
        yserver_core::backend::ModeSpec,
    ) {
        let (fixture, device, _, _, target_mode) =
            c0_3bi_live_modeset_backend(behaviour, two_outputs)
                .expect("environmental skip: live Vulkan release fixture");
        c0_3ci_finish_live_release_fixture(fixture, device, target_mode, two_outputs)
    }

    fn c0_3ci_live_release_fixture_with_completed_front(
        behaviour: crate::kms::executor::test_support::StubBehaviour,
    ) -> (
        OwnerLiveFixture,
        DrmDeviceKey,
        Vec<OutputKey>,
        yserver_core::backend::ModeSpec,
    ) {
        let (fixture, device, _, _, target_mode) =
            c0_3bi_live_modeset_backend_with_completed_composed_front(behaviour)
                .expect("environmental skip: live Vulkan release fixture with composed front");
        c0_3ci_finish_live_release_fixture(fixture, device, target_mode, false)
    }

    fn c0_3ci_finish_live_release_fixture(
        mut fixture: OwnerLiveFixture,
        device: DrmDeviceKey,
        target_mode: yserver_core::backend::ModeSpec,
        two_outputs: bool,
    ) -> (
        OwnerLiveFixture,
        DrmDeviceKey,
        Vec<OutputKey>,
        yserver_core::backend::ModeSpec,
    ) {
        if two_outputs {
            // The second output is synthetic but shares the real device's
            // property schema. The executor stub does not issue a real
            // atomic request, so mirror the device-wide property IDs.
            let (real_crtc, synthetic_crtc, plane_fb_id, plane_crtc_id, out_fence) = {
                let outputs = &fixture.backend.platform.outputs;
                (
                    outputs[0].output.crtc,
                    u32::from(outputs[1].output.crtc),
                    outputs[0].output.plane_fb_id_prop,
                    outputs[0].output.plane_crtc_id_prop,
                    outputs[0].output.crtc_out_fence_ptr_prop,
                )
            };
            let drm_device = fixture.backend.platform.devices[0]
                .device
                .clone_rc()
                .expect("attached fixture DRM device");
            let active_property = fixture.backend.platform.devices[0]
                .active_property_cache
                .get_or_discover(drm_device.as_ref(), real_crtc)
                .expect("discover ACTIVE on the real fixture CRTC");
            fixture.backend.platform.outputs[1].output.plane_fb_id_prop = plane_fb_id;
            fixture.backend.platform.outputs[1]
                .output
                .plane_crtc_id_prop = plane_crtc_id;
            fixture.backend.platform.outputs[1]
                .output
                .crtc_out_fence_ptr_prop = out_fence;
            fixture.backend.platform.devices[0]
                .active_property_cache
                .insert_for_tests(synthetic_crtc, active_property);
        }
        fixture.backend.vt_skip_master_ioctls_for_tests = true;
        fixture.backend.platform.owner_completion_detached = true;
        fixture
            .backend
            .lifecycle_register_owner_device(device)
            .expect("register the already-installed Owner outputs as lifecycle-ready");
        let outputs = fixture
            .backend
            .platform
            .outputs
            .iter()
            .filter(|output| output.key.device_key == device)
            .map(|output| output.key.clone())
            .collect::<Vec<_>>();
        let completion_crtcs = fixture
            .backend
            .platform
            .outputs
            .iter()
            .filter(|output| output.key.device_key == device)
            .map(CrtcKey::for_output)
            .collect::<Vec<_>>();
        for crtc in completion_crtcs {
            fixture.backend.platform.record_completion_clock(
                crtc,
                yserver_core::backend::PresentClockSample {
                    msc: 1_000,
                    ust: 1_000_000,
                    source: yserver_core::backend::PresentClockSource::IdleSequence,
                },
            );
        }
        (fixture, device, outputs, target_mode)
    }

    fn c0_3ci_core_state(backend: &mut super::KmsBackend) -> ServerState {
        let mut state = ServerState::new();
        backend.rebuild_randr_state(&mut state, None, false);
        let _requester = c0_3aii_install_dpms_core_client(&mut state, 71);
        state
    }

    fn c0_3ci_acquire_with_scripted_layout_through_core_driver(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        label: &str,
    ) {
        // The live fixture starts with DrmConnectorProber. Acquire tests that
        // model synthetic connector discovery opt into the script here and
        // queue the exact current layout; any test-specific `set` answer
        // remains first in line and keeps its original assertion path.
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        for (device, result) in c0_3ci_test_probe_results(backend) {
            let Ok(snapshot) = result else {
                continue;
            };
            backend
                .platform
                .queue_connector_probe_for_tests(device, Ok(snapshot));
        }
        let owner_devices = backend.lifecycle_owner_incarnation_devices();
        let descriptions_before = backend
            .lifecycle_drivers
            .iter()
            .map(|(device, driver)| {
                (
                    *device,
                    driver.acquire_topology_descriptions_for_tests().len(),
                )
            })
            .collect::<std::collections::BTreeMap<_, _>>();
        // The executor stub accepts helper IPC only; it does not issue the
        // kernel DRM atomic reinstall or VT master ioctl. The fixture skips
        // master ioctls and drives the backend entry through the core driver.
        backend.core_driver_vt_acquires_for_tests += 1;
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            label,
            std::time::Duration::from_secs(2),
            &|backend| {
                backend.core_driver_vt_acquires_for_tests == 0
                    && backend.probe_episode.is_none()
                    && owner_devices.iter().all(|device| {
                        let closed = backend.platform.transport_gate(device).is_some_and(|gate| {
                            gate.state() == crate::kms::render::resources::TransportState::Closed
                        });
                        if closed {
                            return true;
                        }
                        let has_new_description =
                            backend.lifecycle_drivers.get(device).is_some_and(|driver| {
                                driver.acquire_topology_descriptions_for_tests().len()
                                    > descriptions_before.get(device).copied().unwrap_or(0)
                            });
                        let has_live_record = backend
                            .platform
                            .owner_ref(*device)
                            .and_then(|owner| owner.live_record())
                            .is_some();
                        let transition_pending = backend
                            .lifecycle_coordinator
                            .device(device)
                            .and_then(|arbiter| arbiter.transition())
                            .is_some_and(|transition| {
                                transition.kind
                                    == crate::kms::owner::lifecycle::LifecycleKind::VTAcquire
                            });
                        !transition_pending || has_new_description || has_live_record
                    })
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: {error}"));
        assert!(
            backend
                .core_entry_trace_for_tests
                .borrow()
                .contains(&"vt_acquire"),
            "the acquire ran through a Backend core entry"
        );
    }

    fn c0_3cii_start_blocked_acquire(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        barrier: &crate::kms::render::platform::ProbeBarrier,
        label: &str,
    ) {
        backend.core_driver_vt_acquires_for_tests += 1;
        let acquire_worker_started = |backend: &super::KmsBackend| {
            backend.vt_state == crate::vt::state::VtState::Resuming
                && backend.probe_workers.workers.contains_key(&device)
                && backend
                    .core_entry_trace_for_tests
                    .borrow()
                    .contains(&"vt_acquire")
        };
        let driven = c0_3bi_core_driver_until_mode(
            backend,
            state,
            label,
            std::time::Duration::from_secs(1),
            &acquire_worker_started,
            None,
            false,
            true,
        );
        if let Err(error) = driven {
            // The VT callback can run as the final Backend entry before the
            // bounded driver notices its deadline. Accept that timeout only
            // when the exact acquire entry and blocked worker are observable.
            assert!(acquire_worker_started(backend), "{label}: {error}");
        }
        assert!(
            barrier.wait_started(std::time::Duration::from_secs(1)),
            "{label}: the scripted prober owns a real worker thread blocked on its barrier"
        );
        assert!(
            backend
                .platform
                .connector_probe_observations_for_tests()
                .iter()
                .any(|observation| observation.key == device),
            "{label}: the worker entered the scripted prober before the barrier"
        );
        assert!(
            backend
                .core_entry_trace_for_tests
                .borrow()
                .contains(&"vt_acquire"),
            "{label}: acquire enters through the core driver"
        );
    }

    fn c0_3cii_finish_probe_workers(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        label: &str,
    ) {
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            label,
            std::time::Duration::from_secs(3),
            &|backend| backend.probe_workers.workers.is_empty(),
            None,
        )
        .unwrap_or_else(|error| panic!("{label}: {error}"));
    }

    fn c0_3cii_released_two_owner_fixture() -> (
        OwnerLiveFixture,
        DrmDeviceKey,
        DrmDeviceKey,
        Vec<OutputKey>,
        Vec<OutputKey>,
        ServerState,
    ) {
        let (mut fixture, device_a, device_b, outputs_a, outputs_b, mut state) =
            c0_3cii_live_two_owner_fixture();
        let backend = &mut fixture.backend;
        backend.vt_skip_master_ioctls_for_tests = true;
        backend.platform.owner_completion_detached = true;
        // AcceptKernelCalls models the executor protocol only; it does not
        // submit kernel atomic commits, page flips, VT ioctls, or DRM master.
        c0_3ci_release_owners_to_suspended(
            backend,
            &mut state,
            &[device_a, device_b],
            "two-Owner probe fixture release",
        );
        (fixture, device_a, device_b, outputs_a, outputs_b, state)
    }

    #[cfg(target_os = "linux")]
    fn c0_3cii_udev_record(
        action: crate::kms::hotplug::DrmHotplugAction,
        device: DrmDeviceKey,
        card_node: bool,
        connector_subdevice: bool,
        hotplug: bool,
    ) -> crate::kms::hotplug::DrmHotplugRecord {
        crate::kms::hotplug::DrmHotplugRecord {
            action,
            dev_t: Some(device),
            devnode: Some(std::path::PathBuf::from(format!(
                "/dev/dri/{}{}",
                if card_node { "card" } else { "renderD" },
                device.minor
            ))),
            subsystem: Some("drm".to_owned()),
            is_card_node: card_node,
            is_render_node: !card_node && !connector_subdevice,
            is_connector_subdevice: connector_subdevice,
            hotplug,
        }
    }

    #[cfg(target_os = "linux")]
    fn c0_3cii_script_udev_records(
        backend: &mut super::KmsBackend,
        records: Vec<crate::kms::hotplug::DrmHotplugRecord>,
    ) {
        backend.platform.hotplug_monitor = Some(
            crate::kms::hotplug::DrmHotplugMonitor::from_records(records),
        );
        backend
            .core_driver_readiness_script_for_tests
            .push_back((yserver_core::backend::BackendFdKind::DrmHotplug, -1));
    }

    fn c0_3cii_removed_end_state(
        backend: &super::KmsBackend,
        live_layout: impl IntoIterator<Item = OutputKey>,
        removed_device: DrmDeviceKey,
    ) -> C0EndStateExpectation {
        let mut expected = c0_3bi_expected_end_state(live_layout);
        expected.quarantined_allocations = backend
            .resource_service()
            .map(|service| {
                service
                    .allocation_end_state_for_tests()
                    .into_iter()
                    .filter(|allocation| {
                        allocation.key.device == removed_device && allocation.frozen
                    })
                    .map(|allocation| allocation.key)
                    .collect()
            })
            .unwrap_or_default();
        expected
    }

    fn c0_3cii_install_core_shutdown_channel(
        backend: &mut super::KmsBackend,
    ) -> yserver_core::core_loop::CoreReceiver {
        let (_poll, sender, receiver) =
            yserver_core::core_loop::channel().expect("core shutdown channel");
        Backend::set_input_sender(backend, sender);
        receiver
    }

