    #[cfg(target_os = "linux")]
    fn c0_3cii_real_monitor_change_record(
        records: &[crate::kms::hotplug::DrmHotplugRecord],
        device: DrmDeviceKey,
    ) -> Option<&crate::kms::hotplug::DrmHotplugRecord> {
        records.iter().find(|record| {
            record.action == crate::kms::hotplug::DrmHotplugAction::Change
                && record.dev_t == Some(device)
                && record.hotplug
        })
    }

    #[test]
    #[cfg(target_os = "linux")]
    fn c0_3cii_real_monitor_match_requires_card_dev_t() {
        let selected = DrmDeviceKey {
            major: 226,
            minor: 1,
        };
        let other = DrmDeviceKey {
            major: 226,
            minor: 2,
        };
        let unrelated = c0_3cii_udev_record(
            crate::kms::hotplug::DrmHotplugAction::Change,
            other,
            true,
            false,
            true,
        );
        let card = c0_3cii_udev_record(
            crate::kms::hotplug::DrmHotplugAction::Change,
            selected,
            true,
            false,
            true,
        );
        assert!(
            c0_3cii_real_monitor_change_record(std::slice::from_ref(&unrelated), selected)
                .is_none()
        );
        assert_eq!(
            c0_3cii_real_monitor_change_record(&[unrelated, card.clone()], selected),
            Some(&card)
        );
    }

    #[cfg(target_os = "linux")]
    fn c0_3cii_real_monitor_delivers_typed_events(
        backend: &super::KmsBackend,
        device: DrmDeviceKey,
        record_start: usize,
        label: &str,
    ) {
        let records = &backend.drm_hotplug_records_for_tests[record_start..];
        let typed = c0_3cii_real_monitor_change_record(records, device)
            .unwrap_or_else(|| {
                panic!(
                    "{label}: real udev monitor must deliver change with card dev_t {device} and HOTPLUG=1; records={records:?}"
                )
            });
        let classified = crate::kms::hotplug::classify_drm_hotplug_records(
            [typed.clone()],
            &backend.open_drm_cards_for_hotplug_classifier(),
            &backend.selected_renderer_drm_nodes(),
        );
        assert!(
            classified.iter().any(|event| event.disposition
                == crate::kms::hotplug::DrmHotplugDisposition::ConnectorEdge),
            "{label}: the typed monitor record is classified as a connector edge"
        );
        assert!(
            classified.iter().all(|event| event.disposition
                != crate::kms::hotplug::DrmHotplugDisposition::DeviceRemoved),
            "{label}: a connector edge is not DeviceRemoved"
        );
    }

    #[test]
    #[ignore = "hardware proof only; the implementer must never run this real-modeset test"]
    #[cfg(target_os = "linux")]
    fn c0_hw_3c_hotplug_on_card1_drm() {
        use std::{
            cell::RefCell,
            collections::HashSet,
            os::fd::{AsFd, AsRawFd, OwnedFd},
            path::PathBuf,
            rc::Rc,
            sync::{Arc, Mutex},
            time::{Duration, Instant},
        };

        use crate::kms::render::resources::{DrmCleanupRegistry, ResourceService};
        use yserver_core::backend::Backend;
        use yserver_protocol::x11::randr as rr;

        struct TimedProductionProber {
            durations: Arc<Mutex<Vec<Duration>>>,
        }

        impl crate::kms::render::platform::ConnectorProber for TimedProductionProber {
            fn probe_snapshot(
                &self,
                device: DrmDeviceKey,
                fd: OwnedFd,
            ) -> io::Result<Vec<ConnectorSnapshot>> {
                let started = Instant::now();
                let result =
                    crate::kms::render::platform::DrmConnectorProber.probe_snapshot(device, fd);
                self.durations
                    .lock()
                    .expect("record production connector probe duration")
                    .push(started.elapsed());
                result
            }

            fn probe_connectors(
                &self,
                device: DrmDeviceKey,
                fd: OwnedFd,
            ) -> io::Result<Vec<crate::platform::drm::ConnectorProbe>> {
                crate::kms::render::platform::DrmConnectorProber.probe_connectors(device, fd)
            }
        }

        let card1 = PathBuf::from("/dev/dri/card1");
        if let Err(error) = std::fs::metadata(&card1) {
            eprintln!("environmental skip: /dev/dri/card1 is unavailable: {error}");
            return;
        }
        let preflight = super::KmsBackend::for_tests_with_vk_live_scene_real_drm()
            .unwrap_or_else(|error| panic!("card1 hotplug preflight failed: {error}"));
        let primary = preflight
            .platform
            .vk
            .as_ref()
            .and_then(|vk| vk.selected_drm_identity)
            .and_then(|identity| identity.primary)
            .expect("Vulkan reports the primary DRM identity");
        let primary_path = super::card_path_for_key(primary)
            .unwrap_or_else(|error| panic!("cannot map primary DRM identity: {error}"));
        assert_eq!(
            primary_path, card1,
            "the real hotplug test must select card1 before opening an Owner"
        );
        drop(preflight);

        let mut base = super::KmsBackend::for_tests_with_vk_live_scene_real_drm()
            .unwrap_or_else(|error| panic!("card1 Vulkan base fixture failed: {error}"));
        // Set the diagnostic root colour before the live-KMS fixture rebuilds
        // root storage at the HDMI-2 extent.
        base.core.bg_pixel = Some(0x0010_50E0);
        let mut fixture =
            super::KmsBackend::for_tests_with_live_kms_from_backend(base, Some("HDMI-2"))
                .unwrap_or_else(|error| panic!("card1 HDMI-2 live fixture failed: {error}"));
        let backend = &mut fixture.backend;
        backend.resource_cleanup_on_drop_for_tests = true;
        let device = backend
            .platform
            .primary_device()
            .expect("live KMS fixture has card1")
            .key;
        let device_rc = backend
            .platform
            .device_for_key(device)
            .expect("card1 device is retained")
            .device
            .clone_rc()
            .expect("attached test DRM device");
        assert_eq!(
            super::card_path_for_key(device).expect("map card1 device identity"),
            card1
        );
        let executor = crate::kms::executor::KmsIoExecutor::spawn(
            device_rc.as_fd(),
            crate::kms::owner::identity::IncarnationId::first(),
        )
        .unwrap_or_else(|error| panic!("spawn card1 Owner executor: {error}"));
        let (incarnation, lifecycle) = executor.owner_identity();
        backend.platform.devices[0].executor = Some(executor);
        backend.platform.devices[0].owner = Some(
            crate::kms::owner::device::DeviceCommitOwner::new(incarnation, lifecycle, 1),
        );
        let mut registry = DrmCleanupRegistry::new(Rc::clone(&device_rc), device, incarnation);
        let mut service = ResourceService::new(device, incarnation);
        for output_idx in 0..backend.platform.scanout_pools.len() {
            let bo_count = backend.platform.scanout_pools[output_idx]
                .as_ref()
                .map_or(0, |scanout| scanout.display_pool().bos.len());
            for bo_idx in 0..bo_count {
                backend
                    .platform
                    .register_managed_scanout_bo(&mut service, &mut registry, output_idx, bo_idx)
                    .unwrap_or_else(|error| {
                        panic!("adopt card1 output {output_idx} BO {bo_idx}: {error:?}")
                    });
            }
        }
        backend.install_resource_service_with_registry(service, registry);
        install_admission_owner_gate(backend, device);
        backend.install_admission_conductor_with_backend_composed_for_tests(
            device,
            AdmissionSourceFixture::new_source().0,
        );

        let output_idx = backend
            .platform
            .outputs
            .iter()
            .position(|output| output.key.device_key == device)
            .expect("live card1 HDMI-2 output");
        let output_key = backend.platform.outputs[output_idx].key.clone();
        assert_eq!(output_key.connector_name, "HDMI-2");
        let output_id = backend.randr_id_alloc.ids_for(&output_key).output_id;
        backend
            .output_key_by_id
            .insert(output_id, output_key.clone());
        let config = {
            let output = &backend.platform.outputs[output_idx];
            super::ConnectorConfig::Enabled {
                mode_w: output.width,
                mode_h: output.height,
                vrefresh: output.output.picked.vrefresh,
                x: output.x,
                y: output.y,
            }
        };
        {
            let output = &backend.platform.outputs[output_idx];
            let entry = backend.randr_id_alloc.entry_mut(&output_key);
            entry.connected = true;
            entry.config = config;
            entry.modes = output.output.modes.clone();
            entry.edid = output.output.edid.clone();
            entry.mm_width = output.output.mm_width;
            entry.mm_height = output.output.mm_height;
            entry.connector_type = output.output.connector_type.clone();
        }
        let drm_fd = backend
            .platform
            .device_for_key(device)
            .expect("card1 Owner device")
            .device
            .attached()
            .expect("attached test DRM device")
            .as_fd()
            .as_raw_fd();
        let hardware_complete = Rc::new(RefCell::new(HashSet::new()));
        let hardware_crtc =
            u32::from(CrtcKey::for_output(&backend.platform.outputs[output_idx]).crtc);
        let clock_key = backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.clock_key_for_hardware_crtc(hardware_crtc))
            .expect("HDMI-2 CRTC has a production clock record");
        c0_hw_3b_drive_until(
            backend,
            device,
            drm_fd,
            "initial HDMI-2 clock probe",
            Duration::from_secs(20),
            &|backend| {
                backend
                    .platform
                    .owner_ref(device)
                    .and_then(|owner| owner.clock(clock_key))
                    .is_some_and(|clock| {
                        clock.probe == crate::kms::owner::clock::ProbeState::Succeeded
                    })
            },
            &hardware_complete,
        )
        .unwrap_or_else(|error| panic!("initial HDMI-2 clock probe failed: {error}"));
        // Keep the live fixture's diagnostic root colour vivid so a person
        // watching the monitor can distinguish yserver's frame from the
        // black console. The fixture initialized the root storage in this
        // colour before the Owner clock probe.
        backend.core.bg_pixel = Some(0x0010_50E0);
        c0_3cii_dump_kernel_planes(backend, device, "before the initial composed commit");
        c0_3cii_hotplug_initial_composed_commit(
            backend,
            device,
            drm_fd,
            &output_key,
            "compose the initial HDMI-2 frame before hotplug cycles",
            &hardware_complete,
        )
        .unwrap_or_else(|error| {
            let diagnostics =
                c0_3cii_hotplug_diagnostics_for_tests(backend, device, output_idx, hardware_crtc);
            panic!("initial HDMI-2 composition failed: {error}; {diagnostics}");
        });
        c0_3cii_dump_kernel_planes(backend, device, "after the initial composed commit");
        c0_3cii_report_pool_bos(backend, output_idx, "after initial composed commit");

        // Keep startup composition on the same known-ready Owner path as 3b.
        // Hotplug observation and RANDR publication are needed only for the
        // unplug/replug cycles below; attaching them before the baseline frame
        // lets startup topology work race that first ordinary admission.
        backend
            .platform
            .use_production_connector_prober_for_live_drm_fixture();
        assert!(
            !backend.platform.connector_prober_is_scripted_for_tests(),
            "the hardware route uses DrmConnectorProber on the duplicated master fd"
        );
        backend.platform.hotplug_monitor = Some(
            crate::kms::hotplug::DrmHotplugMonitor::new()
                .expect("open the production udev monitor")
                .expect("udev monitor available on this host"),
        );
        assert!(
            Backend::poll_fds(backend)
                .iter()
                .any(|(_, kind)| *kind == yserver_core::backend::BackendFdKind::DrmHotplug),
            "the production udev monitor is registered in the core poll set"
        );

        {
            let entry = backend.randr_id_alloc.entry_mut(&output_key);
            entry.last_enabled = Some(config);
            entry.crtc_associated = true;
        }
        let mut state = c0_3ci_core_state(backend);
        let mut listener = c0_3aii_install_dpms_core_client(&mut state, 74);
        state.randr_select_masks.insert(
            (74, yserver_core::resources::ROOT_WINDOW),
            rr::NOTIFY_MASK_OUTPUT_CHANGE | rr::NOTIFY_MASK_CRTC_CHANGE,
        );

        let durations = Arc::new(Mutex::new(Vec::new()));
        backend.platform.connector_prober = Arc::new(TimedProductionProber {
            durations: Arc::clone(&durations),
        });
        let mut expected_live = backend
            .platform
            .outputs
            .iter()
            .map(|output| output.key.clone())
            .collect::<Vec<_>>();
        assert!(expected_live.contains(&output_key));
        for cycle in 1..=4 {
            eprintln!("UNPLUG HDMI-2 now (cycle {cycle}/4)");
            let probe_index = durations.lock().expect("read probe durations").len();
            let typed_event_start = backend.drm_hotplug_records_for_tests.len();
            let old_instance = backend
                .platform
                .outputs
                .iter()
                .position(|output| output.key == output_key)
                .and_then(|index| backend.platform.output_instance_ids.get(index).copied())
                .expect("HDMI-2 output instance before unplug");
            let sends_before = backend.lifecycle_drivers[&device]
                .topology_test_stats()
                .1
                .len();
            c0_3bi_core_driver_until_with_state(
                backend,
                &mut state,
                "real HDMI-2 unplug through udev, probe and Owner transaction",
                Duration::from_secs(60),
                &|backend| {
                    backend.acquire_episode.is_none()
                        && !backend
                            .platform
                            .outputs
                            .iter()
                            .any(|output| output.key == output_key)
                        && backend.lifecycle_drivers[&device]
                            .topology_test_stats()
                            .1
                            .len()
                            > sends_before
                        && !backend
                            .scene
                            .retired_output_has_instance_for_tests(old_instance)
                },
                Some(&hardware_complete),
            )
            .unwrap_or_else(|error| panic!("cycle {cycle}: unplug route timed out: {error}"));
            c0_3cii_real_monitor_delivers_typed_events(
                backend,
                device,
                typed_event_start,
                &format!("cycle {cycle} unplug"),
            );
            let unplug_duration = durations
                .lock()
                .expect("read production probe duration")
                .get(probe_index)
                .copied()
                .expect("unplug probe duration was recorded");
            eprintln!("cycle {cycle}: unplug DrmConnectorProber duration {unplug_duration:?}");
            assert!(state.randr.outputs.iter().any(|output| {
                output.output_id == output_id && !output.connected && output.mode_id == 0
            }));
            assert_eq!(
                backend
                    .lifecycle_coordinator
                    .device(&device)
                    .map(|arbiter| arbiter.state()),
                Some(crate::kms::owner::lifecycle::DeviceLifecycleState::Ready),
                "cycle {cycle}: the unplug participant reached Applied"
            );
            assert!(
                backend
                    .lifecycle_coordinator
                    .device(&device)
                    .and_then(|arbiter| arbiter
                        .desired()
                        .representative(crate::kms::owner::lifecycle::DesiredField::Topology,))
                    .is_some_and(|representative| matches!(
                        representative.disposition,
                        Some(crate::kms::owner::lifecycle::Disposition::Applied(_))
                    )),
                "cycle {cycle}: the hotplug lifecycle representative resolved Applied"
            );
            assert!(
                !kbd_map_drain(&mut listener).is_empty(),
                "cycle {cycle}: the unplug publication reached the RandR client"
            );
            expected_live.retain(|key| key != &output_key);
            c0_3bi_assert_end_state(
                backend,
                "c0_hw_3c_hotplug_on_card1_drm unplug",
                &c0_3bi_expected_end_state(expected_live.clone()),
            );

            eprintln!("REPLUG HDMI-2 now (cycle {cycle}/4)");
            let probe_index = durations.lock().expect("read probe durations").len();
            let typed_event_start = backend.drm_hotplug_records_for_tests.len();
            let sends_before = backend.lifecycle_drivers[&device]
                .topology_test_stats()
                .1
                .len();
            c0_3bi_core_driver_until_with_state(
                backend,
                &mut state,
                "real HDMI-2 replug through udev, probe and relight transaction",
                Duration::from_secs(60),
                &|backend| {
                    backend.acquire_episode.is_none()
                        && backend
                            .platform
                            .outputs
                            .iter()
                            .any(|output| output.key == output_key)
                        && backend.lifecycle_drivers[&device]
                            .topology_test_stats()
                            .1
                            .len()
                            > sends_before
                },
                Some(&hardware_complete),
            )
            .unwrap_or_else(|error| panic!("cycle {cycle}: replug route timed out: {error}"));
            c0_3cii_real_monitor_delivers_typed_events(
                backend,
                device,
                typed_event_start,
                &format!("cycle {cycle} replug"),
            );
            let relight_duration = durations
                .lock()
                .expect("read production probe duration")
                .get(probe_index)
                .copied()
                .expect("replug probe duration was recorded");
            eprintln!("cycle {cycle}: replug DrmConnectorProber duration {relight_duration:?}");
            assert!(state.randr.outputs.iter().any(|output| {
                output.output_id == output_id && output.connected && output.mode_id != 0
            }));
            let new_instance = backend
                .platform
                .outputs
                .iter()
                .position(|output| output.key == output_key)
                .and_then(|index| backend.platform.output_instance_ids.get(index).copied())
                .expect("relit HDMI-2 output instance");
            assert_ne!(
                new_instance, old_instance,
                "cycle {cycle}: relight owns a fresh pool"
            );
            assert_eq!(
                backend
                    .lifecycle_coordinator
                    .device(&device)
                    .map(|arbiter| arbiter.state()),
                Some(crate::kms::owner::lifecycle::DeviceLifecycleState::Ready),
                "cycle {cycle}: the relight participant reached Applied"
            );
            assert!(
                backend
                    .lifecycle_coordinator
                    .device(&device)
                    .and_then(|arbiter| arbiter
                        .desired()
                        .representative(crate::kms::owner::lifecycle::DesiredField::Topology,))
                    .is_some_and(|representative| matches!(
                        representative.disposition,
                        Some(crate::kms::owner::lifecycle::Disposition::Applied(_))
                    )),
                "cycle {cycle}: the hotplug lifecycle representative resolved Applied"
            );
            assert!(
                !kbd_map_drain(&mut listener).is_empty(),
                "cycle {cycle}: the relight publication reached the RandR client"
            );
            expected_live.push(output_key.clone());
            c0_3bi_assert_end_state(
                backend,
                "c0_hw_3c_hotplug_on_card1_drm replug",
                &c0_3bi_expected_end_state(expected_live.clone()),
            );
            c0_hw_3b_compose_and_complete_through_core_driver(
                backend,
                device,
                drm_fd,
                &output_key,
                &format!("cycle {cycle}: composed frame after HDMI-2 relight"),
                &hardware_complete,
            )
            .unwrap_or_else(|error| panic!("cycle {cycle}: relit HDMI-2 frame failed: {error}"));
            if cycle == 1 {
                let relit_output_idx = backend
                    .platform
                    .outputs
                    .iter()
                    .position(|output| output.key == output_key)
                    .expect("relit HDMI-2 output");
                c0_3cii_dump_kernel_planes(
                    backend,
                    device,
                    "after the first relight composed commit",
                );
                c0_3cii_report_pool_bos(
                    backend,
                    relit_output_idx,
                    "after first relight composed commit",
                );
            }
        }
    }

    fn c0_3cii_hotplug_diagnostics_for_tests(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        output_idx: usize,
        crtc: u32,
    ) -> String {
        let trace = backend.admission_trace_for_tests(device);
        let trace_tail = trace
            .iter()
            .skip(trace.len().saturating_sub(12))
            .cloned()
            .collect::<Vec<_>>();
        let composed = backend
            .admission_conductors
            .get(&device)
            .map(|conductor| conductor.composed.clone());
        let composed_generation = composed
            .as_ref()
            .and_then(|generations| generations.get(&crtc))
            .copied();
        let composed_readiness = composed_generation
            .and_then(|generation| backend.composed_readiness_for_tests(device, crtc, generation));
        let arbiter = backend.lifecycle_coordinator.device(&device);
        let arbiter_state = arbiter.map(|arbiter| arbiter.state());
        let arbiter_admission_open = arbiter.map(|arbiter| arbiter.admission_open());
        let transition = arbiter.and_then(|arbiter| {
            arbiter
                .transition()
                .map(|transition| (transition.kind, transition.phase))
        });
        let conductor_state = backend.admission_conductors.get(&device).map(|conductor| {
            (
                conductor.lifecycle_admission_closed,
                conductor.recovery_stopped,
                conductor.composed.clone(),
                conductor.last_readiness_for_tests.clone(),
                conductor.last_decision_for_tests.clone(),
            )
        });
        let transport_gate_state = backend
            .platform
            .transport_gate(&device)
            .map(|gate| gate.state());
        let owner_state = backend.platform.owner_ref(device).map(|owner| {
            let clock_context = owner.clock_context();
            let clock_key = owner.clock_key_for_hardware_crtc(crtc);
            let clock = clock_key.and_then(|key| owner.clock(key));
            let live_record = owner
                .live_record()
                .map(|record| (record.commit_id(), *record.milestones()));
            let clock_state = clock.map(|clock| {
                (
                    clock.source,
                    clock.probe,
                    clock.probe_outcome,
                    clock.lifecycle_epoch,
                    clock.topology_generation,
                    clock.reference,
                    clock.queue_failed,
                )
            });
            (
                clock_context,
                clock_key,
                clock_state,
                live_record,
                owner.is_poisoned(),
            )
        });
        let scene_prepared = backend.scene.owner_prepared_for_tests(output_idx);
        let newest_generation = scene_prepared.map(|(_, generation, _)| generation);
        let owner_composed_ready = newest_generation
            .map(|generation| backend.scene.owner_composed_ready(output_idx, generation));
        let damage_state = backend.scene.damage_state_for_tests(output_idx);
        let damage_signature = backend.scene.scanout_damage_signature_for_tests(output_idx);
        let scanout_bos = backend
            .platform
            .scanout_pools
            .get(output_idx)
            .and_then(Option::as_ref)
            .map(|scanout| {
                scanout
                    .display_pool()
                    .bos
                    .iter()
                    .enumerate()
                    .map(|(bo_idx, bo)| {
                        (
                            bo_idx,
                            format!("{:?}", bo.state),
                            backend.platform.owner_bo_phase(output_idx, bo_idx),
                            backend.scene.owner_state_for_tests(output_idx, bo_idx),
                            bo.managed_key(),
                        )
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let scanout_bos_with_service = scanout_bos
            .iter()
            .map(|(bo_idx, state, phase, owner_state, managed_key)| {
                let service_holds = managed_key.is_some_and(|key| {
                    backend
                        .resource_service
                        .as_ref()
                        .is_some_and(|service| service.contains(&key))
                });
                (
                    *bo_idx,
                    state.clone(),
                    *phase,
                    *owner_state,
                    *managed_key,
                    service_holds,
                )
            })
            .collect::<Vec<_>>();
        let adopted_bos_held = scanout_bos_with_service
            .iter()
            .filter(|(_, _, _, _, _, held)| *held)
            .count();
        let resource_service_holds_adopted_bos = (
            adopted_bos_held,
            scanout_bos_with_service.len(),
            backend.resource_service.is_some(),
        );
        let executor_counts = backend
            .platform
            .devices
            .iter()
            .find(|entry| entry.key == device)
            .and_then(|entry| entry.executor.as_ref())
            .map(|executor| executor.request_counts_for_tests());
        let offers_len = backend.core_driver_composed_offers_for_tests.len();
        let last_offers = backend
            .core_driver_composed_offers_for_tests
            .iter()
            .skip(offers_len.saturating_sub(12))
            .cloned()
            .collect::<Vec<_>>();

        format!(
            "vt_state={:?}; arbiter_state={:?}; transition={:?}; arbiter_admission_open={:?}; \
             lifecycle_admission_closed={:?}; recovery_stopped={:?}; transport_gate_state={:?}; \
             composed={:?}; admission_trace_tail={:?}; last_decision_by_tier={:?}; \
             last_readiness_by_tier={:?}; composed_readiness={:?}; live_record={:?}; \
             clock_context_and_hdmi_crtc_clock={:?}; \
             owner_dpms_installed_active={:?}; poisoned={:?}; scene_composed_generation_exists={}; \
             scene_newest_generation={:?}; damage_pending={:?}; damage_signature={:?}; \
             scanout_bos={:?}; owner_composed_ready={:?}; executor_sent_requests={:?}; \
             validation_sends={:?}; live_sends={:?}; replies={:?}; \
             core_driver_composed_offers_len={}; last_offers={:?}; \
             resource_service_holds_adopted_bos={:?} (bo_idx,state,phase,owner_state,key,held)={:?}",
            backend.vt_state,
            arbiter_state,
            transition,
            arbiter_admission_open,
            conductor_state.as_ref().map(|(closed, _, _, _, _)| *closed),
            conductor_state
                .as_ref()
                .map(|(_, recovery_stopped, _, _, _)| *recovery_stopped),
            transport_gate_state,
            conductor_state
                .as_ref()
                .map(|(_, _, composed, _, _)| composed),
            trace_tail,
            conductor_state
                .as_ref()
                .and_then(|(_, _, _, _, decision)| decision.as_ref()),
            conductor_state
                .as_ref()
                .map(|(_, _, _, readiness, _)| readiness),
            composed_readiness,
            owner_state
                .as_ref()
                .and_then(|(_, _, _, live_record, _)| *live_record),
            owner_state.map(|(clock_context, clock_key, clock, _, _)| {
                (clock_context, clock_key, clock)
            }),
            backend.owner_dpms_installed_active.get(&device).copied(),
            backend
                .platform
                .owner_ref(device)
                .map(|owner| owner.is_poisoned()),
            scene_prepared.is_some(),
            newest_generation,
            damage_state.map(|(owes_repaint, staged)| {
                (
                    owes_repaint,
                    staged,
                    damage_signature.as_ref().map(|(pending, _, _)| *pending),
                )
            }),
            damage_signature,
            scanout_bos_with_service
                .iter()
                .map(|(bo_idx, state, phase, owner_state, key, _)| {
                    (*bo_idx, state.as_str(), phase, owner_state, key)
                })
                .collect::<Vec<_>>(),
            owner_composed_ready,
            executor_counts.map(|counts| counts.0),
            executor_counts.map(|counts| counts.1),
            executor_counts.map(|counts| counts.2),
            executor_counts.map(|counts| counts.3),
            offers_len,
            last_offers,
            resource_service_holds_adopted_bos,
            scanout_bos_with_service,
        )
    }

    /// What the kernel reports it is scanning out: every plane's CRTC and
    /// framebuffer, and every CRTC's mode. A person watching the monitor sees
    /// the screen; this prints the kernel's side of the same moment.
    fn c0_3cii_dump_kernel_planes(backend: &super::KmsBackend, device: DrmDeviceKey, label: &str) {
        use ::drm::control::Device as _;

        let Some(kms) = backend
            .platform
            .devices
            .iter()
            .find(|entry| entry.key == device)
        else {
            eprintln!("kernel planes {label}: device {device} is absent");
            return;
        };
        let drm = kms.device.attached().expect("attached test DRM device");
        let planes = drm
            .plane_handles()
            .map(|handles| {
                handles
                    .iter()
                    .filter_map(|handle| drm.get_plane(*handle).ok().map(|plane| (*handle, plane)))
                    .map(|(handle, plane)| {
                        format!(
                            "plane {}: crtc={:?} fb={:?}",
                            u32::from(handle),
                            plane.crtc().map(u32::from),
                            plane.framebuffer().map(u32::from)
                        )
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let crtcs = drm
            .resource_handles()
            .map(|resources| {
                resources
                    .crtcs()
                    .iter()
                    .filter_map(|handle| drm.get_crtc(*handle).ok().map(|crtc| (*handle, crtc)))
                    .map(|(handle, crtc)| {
                        format!(
                            "crtc {}: mode={:?} fb={:?}",
                            u32::from(handle),
                            crtc.mode().map(|mode| (mode.size(), mode.vrefresh())),
                            crtc.framebuffer().map(u32::from)
                        )
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        eprintln!("kernel planes {label}: {planes:?}; {crtcs:?}");
    }

    /// Read one particular managed Shared scanout BO, bypassing legacy
    /// `BoPhase` selection. The caller's `Read` lease stays alive through the
    /// synchronous staging copy, so this reports the allocation that owns the
    /// image rather than whichever BO a screenshot helper happens to choose.
    fn c0_3cii_read_pool_bo(
        backend: &mut super::KmsBackend,
        output_idx: usize,
        bo_idx: usize,
    ) -> Result<(Option<u32>, Vec<u8>, u32, u32), String> {
        use crate::kms::render::resources::UseKind;

        let (key, width, height, initialized) = {
            let scanout = backend
                .platform
                .scanout_pools
                .get(output_idx)
                .and_then(Option::as_ref)
                .ok_or_else(|| format!("output {output_idx} has no pool"))?;
            let crate::kms::vk::scanout::OutputScanout::Shared(pool) = scanout else {
                return Err(format!("output {output_idx} does not use Shared scanout"));
            };
            let bo = pool
                .bos
                .get(bo_idx)
                .ok_or_else(|| format!("output {output_idx} has no BO {bo_idx}"))?;
            let key = bo
                .managed_key()
                .ok_or_else(|| format!("output {output_idx} BO {bo_idx} is not managed"))?;
            let legacy_written = backend
                .platform
                .bo_generations
                .get(output_idx)
                .and_then(|entries| entries.get(bo_idx))
                .is_some_and(|entry| entry.last_present_generation.is_some());
            let owner_written = backend
                .scene
                .owner_generation_for_tests(output_idx, bo_idx)
                .is_some();
            (
                key,
                pool.width,
                pool.height,
                legacy_written || owner_written,
            )
        };
        let byte_len = usize::try_from(width)
            .ok()
            .and_then(|width| {
                usize::try_from(height)
                    .ok()
                    .and_then(|height| width.checked_mul(height))
            })
            .and_then(|pixels| pixels.checked_mul(4))
            .ok_or_else(|| format!("output {output_idx} BO {bo_idx} byte size overflow"))?;

        let (read_lease, image, framebuffer) = {
            let service = backend
                .resource_service
                .as_mut()
                .ok_or_else(|| "Owner fixture has no resource service".to_string())?;
            let lease = service
                .reserve(key, UseKind::Read)
                .map_err(|error| format!("reserve output {output_idx} BO {bo_idx}: {error:?}"))?;
            let (image, framebuffer) = service
                .with_scanout_read(&lease, |allocation| {
                    (
                        allocation.shared().image,
                        allocation
                            .file_owned()
                            .and_then(|file_owned| file_owned.fb_handle())
                            .map(u32::from),
                    )
                })
                .map_err(|error| format!("resolve output {output_idx} BO {bo_idx}: {error:?}"))?;
            (lease, image, framebuffer)
        };

        let vk = backend
            .platform
            .vk
            .as_ref()
            .cloned()
            .ok_or_else(|| "Owner fixture has no Vulkan context".to_string())?;
        let command_pool = backend
            .platform
            .ops_command_pool_handle()
            .ok_or_else(|| "Owner fixture has no readback command pool".to_string())?;
        let (staging_buffer, staging_mapped) =
            super::ensure_scanout_readback(&mut backend.platform, &vk, byte_len)
                .map_err(|error| format!("allocate BO readback staging: {error}"))?;
        let old_layout = if initialized {
            ash::vk::ImageLayout::GENERAL
        } else {
            ash::vk::ImageLayout::UNDEFINED
        };
        let op = super::ensure_scanout_readback_op(&mut backend.platform, &vk, command_pool)
            .map_err(|error| format!("allocate BO readback command: {error}"))?;
        let copy_result = op.run(|vk, command_buffer| {
            let (src_stage, src_access) = if old_layout == ash::vk::ImageLayout::UNDEFINED {
                (
                    ash::vk::PipelineStageFlags2::NONE,
                    ash::vk::AccessFlags2::NONE,
                )
            } else {
                (
                    ash::vk::PipelineStageFlags2::ALL_COMMANDS,
                    ash::vk::AccessFlags2::MEMORY_WRITE,
                )
            };
            let before = [ash::vk::ImageMemoryBarrier2::default()
                .src_stage_mask(src_stage)
                .src_access_mask(src_access)
                .dst_stage_mask(ash::vk::PipelineStageFlags2::COPY)
                .dst_access_mask(ash::vk::AccessFlags2::TRANSFER_READ)
                .old_layout(old_layout)
                .new_layout(ash::vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
                .image(image)
                .subresource_range(
                    ash::vk::ImageSubresourceRange::default()
                        .aspect_mask(ash::vk::ImageAspectFlags::COLOR)
                        .level_count(1)
                        .layer_count(1),
                )];
            let before_dep = ash::vk::DependencyInfo::default().image_memory_barriers(&before);
            unsafe { vk.device.cmd_pipeline_barrier2(command_buffer, &before_dep) };
            let region = [ash::vk::BufferImageCopy::default()
                .buffer_offset(0)
                .buffer_row_length(0)
                .buffer_image_height(0)
                .image_subresource(
                    ash::vk::ImageSubresourceLayers::default()
                        .aspect_mask(ash::vk::ImageAspectFlags::COLOR)
                        .layer_count(1),
                )
                .image_offset(ash::vk::Offset3D::default())
                .image_extent(ash::vk::Extent3D {
                    width,
                    height,
                    depth: 1,
                })];
            unsafe {
                vk.device.cmd_copy_image_to_buffer(
                    command_buffer,
                    image,
                    ash::vk::ImageLayout::TRANSFER_SRC_OPTIMAL,
                    staging_buffer,
                    &region,
                )
            };
            let after = [ash::vk::ImageMemoryBarrier2::default()
                .src_stage_mask(ash::vk::PipelineStageFlags2::COPY)
                .src_access_mask(ash::vk::AccessFlags2::TRANSFER_READ)
                .dst_stage_mask(ash::vk::PipelineStageFlags2::ALL_COMMANDS)
                .dst_access_mask(ash::vk::AccessFlags2::MEMORY_WRITE)
                .old_layout(ash::vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
                .new_layout(ash::vk::ImageLayout::GENERAL)
                .image(image)
                .subresource_range(
                    ash::vk::ImageSubresourceRange::default()
                        .aspect_mask(ash::vk::ImageAspectFlags::COLOR)
                        .level_count(1)
                        .layer_count(1),
                )];
            let after_dep = ash::vk::DependencyInfo::default().image_memory_barriers(&after);
            unsafe { vk.device.cmd_pipeline_barrier2(command_buffer, &after_dep) };
            Ok(())
        });
        drop(read_lease);
        if let Err(error) = copy_result {
            return Err(format!("copy output {output_idx} BO {bo_idx}: {error:?}"));
        }
        if let Some(readback) = backend.platform.scanout_readback.as_ref() {
            readback
                .invalidate_for_read()
                .map_err(|error| format!("invalidate BO readback: {error:?}"))?;
        }
        let bytes =
            unsafe { std::slice::from_raw_parts(staging_mapped.as_ptr(), byte_len).to_vec() };
        Ok((framebuffer, bytes, width, height))
    }

    fn c0_3cii_sample_rgb(bytes: &[u8], width: u32, height: u32, x: u32, y: u32) -> Option<u32> {
        if x >= width || y >= height {
            return None;
        }
        let offset = usize::try_from(y)
            .ok()?
            .checked_mul(usize::try_from(width).ok()?)?
            .checked_add(usize::try_from(x).ok()?)?
            .checked_mul(4)?;
        let pixel = bytes.get(offset..offset.checked_add(4)?)?;
        Some((u32::from(pixel[2]) << 16) | (u32::from(pixel[1]) << 8) | u32::from(pixel[0]))
    }

    /// Print identity and representative pixels for every scanout BO. The
    /// samples come from the named managed allocation, not from phase-based
    /// screenshot selection.
    fn c0_3cii_report_pool_bos(backend: &mut super::KmsBackend, output_idx: usize, label: &str) {
        let bo_count = backend
            .platform
            .scanout_pools
            .get(output_idx)
            .and_then(Option::as_ref)
            .map(|pool| pool.display_pool().bos.len())
            .unwrap_or(0);
        for bo_idx in 0..bo_count {
            let (phase, owner_state, owner_generation, legacy_generation) = {
                let bo = &backend.platform.scanout_pools[output_idx]
                    .as_ref()
                    .expect("report output pool")
                    .display_pool()
                    .bos[bo_idx];
                (
                    bo.state.phase,
                    backend.scene.owner_state_for_tests(output_idx, bo_idx),
                    backend.scene.owner_generation_for_tests(output_idx, bo_idx),
                    backend
                        .platform
                        .bo_generations
                        .get(output_idx)
                        .and_then(|entries| entries.get(bo_idx))
                        .and_then(|entry| entry.last_present_generation),
                )
            };
            match c0_3cii_read_pool_bo(backend, output_idx, bo_idx) {
                Ok((framebuffer, bytes, width, height)) => {
                    let samples = [
                        ("top-left", 0, 0),
                        ("top-right", width.saturating_sub(1), 0),
                        ("bottom-left", 0, height.saturating_sub(1)),
                        (
                            "bottom-right",
                            width.saturating_sub(1),
                            height.saturating_sub(1),
                        ),
                        ("centre", width / 2, height / 2),
                        ("inside-800x600", 400, 300),
                        ("outside-800x600", 900, 700),
                    ]
                    .into_iter()
                    .map(|(name, x, y)| {
                        let value = c0_3cii_sample_rgb(&bytes, width, height, x, y).map_or_else(
                            || "out-of-bounds".to_string(),
                            |rgb| format!("#{rgb:06X}"),
                        );
                        format!("{name}=({x},{y}) {value}")
                    })
                    .collect::<Vec<_>>();
                    eprintln!(
                        "pool BO {label}: output={output_idx} bo={bo_idx} fb={framebuffer:?} \
                         legacy_phase={phase:?} owner_state={owner_state:?} \
                         owner_generation={owner_generation:?} \
                         legacy_last_present_generation={legacy_generation:?} \
                         extent={width}x{height} samples=[{}]",
                        samples.join(", ")
                    );
                }
                Err(error) => eprintln!(
                    "pool BO {label}: output={output_idx} bo={bo_idx} \
                     legacy_phase={phase:?} owner_state={owner_state:?} \
                     owner_generation={owner_generation:?} \
                     legacy_last_present_generation={legacy_generation:?} \
                     readback_error={error}"
                ),
            }
        }
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3cii_live_kms_fixture_first_owner_frame_and_readback_vulkan() {
        use crate::kms::vk::scanout::BoPhase;

        const ROOT_BLUE: u32 = 0x0010_50E0;
        let mut fixture =
            owner_live_fixture().expect("environmental skip: no live Vulkan ICD available");
        let backend = &mut fixture.backend;
        assert!(backend.platform.output_uses_owner_route(0));

        // Mirror the live-KMS handoff without a master, connector probe or
        // modeset: drain the synthetic root fill, install a larger framebuffer
        // extent, then run the same engine/scene/root reconstruction used by
        // the live fixture. The fresh root must be painted in the current
        // background before the first Owner scene samples it.
        assert!(
            backend.engine.frame_builder_is_open(),
            "the fixture's initial root fill is still in its open frame"
        );
        backend
            .engine
            .shutdown(&mut backend.store, &mut backend.platform);
        backend.core.bg_pixel = Some(ROOT_BLUE);
        backend.platform.fb_w = 1920;
        backend.platform.fb_h = 1080;
        backend
            .reinitialize_live_kms_fixture_render_state()
            .expect("reinitialize root for the live framebuffer extent");
        assert_eq!(
            backend
                .root_storage_extent()
                .map(|extent| (extent.width, extent.height)),
            Some((1920, 1080))
        );

        let device = backend.platform.outputs[0].key.device_key;
        backend.scene.mark_scene_structure_dirty();
        backend.tick_maybe_composite_for_tests_without_render_completion_drain();
        backend.platform.wait_idle_bounded();
        backend.drain_scanout_render_completions_for_tests();
        let (prepared_bo, generation, waiting) = backend
            .scene
            .owner_prepared_for_tests(0)
            .expect("the first Owner composition has a prepared BO");
        assert!(!waiting, "the first Owner render completed");
        let commit = backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.live_record())
            .map(|record| record.commit_id())
            .expect("the first composed generation reached Owner admission");
        backend.route_owner_event_batch(
            device,
            vec![crate::kms::owner::device::OwnerEvent::Accepted { commit }],
            std::time::Instant::now(),
        );
        backend.route_owner_event_batch(
            device,
            vec![crate::kms::owner::device::OwnerEvent::HardwareComplete { commit }],
            std::time::Instant::now(),
        );
        let device_index = backend
            .platform
            .devices
            .iter()
            .position(|entry| entry.key == device)
            .expect("Owner device index");
        let completion_events = backend.complete_owner_for_tests(device_index);
        backend.route_owner_event_batch(device, completion_events, std::time::Instant::now());
        assert_eq!(backend.scene.owner_current_bo_idx(0), Some(prepared_bo));
        assert_eq!(
            backend.scene.owner_generation_for_tests(0, prepared_bo),
            Some(generation)
        );

        let (framebuffer, bytes, width, height) =
            c0_3cii_read_pool_bo(backend, 0, prepared_bo).expect("read the current Owner BO");
        assert!(framebuffer.is_some(), "the current Owner BO has a DRM FB");
        for (label, x, y) in [
            ("top-left", 0, 0),
            ("centre", width / 2, height / 2),
            ("inside-800x600", 400, 300),
            ("bottom-right", width - 1, height - 1),
        ] {
            assert_eq!(
                c0_3cii_sample_rgb(&bytes, width, height, x, y),
                Some(ROOT_BLUE),
                "the first Owner BO must contain the initialized root at {label}"
            );
        }

        // Model a retained legacy OnScreen phase on a sibling BO. Before
        // Owner-aware selection, both root GetImage and dumps picked this
        // stale phase ahead of the buffer confirmed current by Owner.
        let pool_len = backend.platform.scanout_pools[0]
            .as_ref()
            .expect("Owner pool")
            .display_pool()
            .bos
            .len();
        let stale_bo = (0..pool_len)
            .find(|bo_idx| *bo_idx != prepared_bo)
            .expect("pool has a sibling BO");
        let previous_phase = {
            let pool = backend.platform.scanout_pools[0]
                .as_mut()
                .expect("Owner pool")
                .display_pool_mut();
            let bo = &mut pool.bos[stale_bo];
            let previous = bo.state.phase;
            bo.state.phase = BoPhase::OnScreen;
            previous
        };
        let requested = r(0, 0, 8, 8);
        for selection in [
            super::ScanoutReadSelection::OnScreenOnly,
            super::ScanoutReadSelection::PermissiveDump,
        ] {
            let route = super::select_scanout_read_route(backend, requested, selection)
                .expect("an Owner-current BO resolves the requested root rect");
            assert_eq!(
                route,
                super::ScanoutReadRoute::Pool {
                    pool_idx: 0,
                    bo_idx: prepared_bo,
                    local: requested,
                },
                "{selection:?} must select the Owner-current framebuffer"
            );
        }
        let root_read = super::read_scanout_region(
            backend,
            requested,
            super::ScanoutReadSelection::OnScreenOnly,
        )
        .expect("root GetImage reads the Owner-current BO");
        assert_eq!(root_read.len(), 8 * 8 * 4);
        assert!(
            root_read
                .chunks_exact(4)
                .all(|pixel| pixel[0] == 0xE0 && pixel[1] == 0x50 && pixel[2] == 0x10),
            "root GetImage bytes come from the painted Owner-current BO"
        );
        backend.platform.scanout_pools[0]
            .as_mut()
            .expect("Owner pool")
            .display_pool_mut()
            .bos[stale_bo]
            .state
            .phase = previous_phase;
    }

    fn c0_3cii_hotplug_initial_composed_commit(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        _drm_fd: std::os::fd::RawFd,
        output_key: &OutputKey,
        label: &str,
        hardware_complete: &std::rc::Rc<
            std::cell::RefCell<std::collections::HashSet<crate::kms::owner::identity::CommitId>>,
        >,
    ) -> Result<crate::kms::owner::identity::CommitId, String> {
        use crate::kms::render::admission::AdmissionTraceStep;

        let output_idx = backend
            .platform
            .outputs
            .iter()
            .position(|output| &output.key == output_key)
            .ok_or_else(|| format!("{label}: output {output_key:?} is absent"))?;
        let output = &backend.platform.outputs[output_idx];
        let crtc = output.output.crtc;
        let crtc_key = crate::kms::render::platform::CrtcKey::new(device, crtc);
        let primary_plane = u32::from(output.output.plane);
        let output_instance = *backend
            .platform
            .output_instance_ids
            .get(output_idx)
            .ok_or_else(|| format!("{label}: output {output_key:?} has no instance identity"))?;
        let damage_before = backend
            .scene
            .damage_history_latest_generation_for_tests(output_idx);
        let offers_before = backend.core_driver_composed_offers_for_tests.len();
        let dispatched_before = backend
            .admission_trace_for_tests(device)
            .into_iter()
            .filter_map(|step| match step {
                AdmissionTraceStep::Dispatched(commit) => Some(commit),
                _ => None,
            })
            .collect::<std::collections::HashSet<_>>();
        let current_before = backend
            .commit_consumer
            .current_resources
            .iter()
            .filter_map(|resources| resources.commit_id)
            .collect::<std::collections::HashSet<_>>();

        backend.scene.mark_scene_structure_dirty();
        eprintln!(
            "{label}: initial-frame baseline: {}",
            c0_3cii_hotplug_diagnostics_for_tests(backend, device, output_idx, u32::from(crtc))
        );
        // Stop as soon as the target commit is current: one more iteration
        // can dispatch the next frame, and a commit with a successor in
        // flight is no longer in current_resources.
        c0_3bi_core_driver_until_mode(
            backend,
            &mut ServerState::new(),
            label,
            std::time::Duration::from_secs(20),
            &|backend| {
                let target_generation_was_offered = backend
                    .core_driver_composed_offers_for_tests
                    .iter()
                    .skip(offers_before)
                    .any(|(offer_device, offer_crtc, _, offer_instance)| {
                        *offer_device == device
                            && *offer_crtc == u32::from(crtc)
                            && *offer_instance == output_instance
                    });
                let dispatched = backend
                    .admission_trace_for_tests(device)
                    .into_iter()
                    .filter_map(|step| match step {
                        AdmissionTraceStep::Dispatched(commit) => Some(commit),
                        _ => None,
                    })
                    .collect::<std::collections::HashSet<_>>();
                let completed = hardware_complete.borrow();
                let target_commit_is_current = backend
                    .commit_consumer
                    .current_resources
                    .iter()
                    .filter(|resources| resources.direct_role.is_none())
                    .filter(|resources| {
                        resources.crtcs.iter().any(|member| member.crtc == crtc_key)
                    })
                    .filter_map(|resources| resources.commit_id)
                    .any(|commit_key| {
                        commit_key.device == device
                            && !current_before.contains(&commit_key)
                            && !dispatched_before.contains(&commit_key.commit)
                            && dispatched.contains(&commit_key.commit)
                            // The driver's set is the real HardwareComplete
                            // evidence (out-fence observed through the core
                            // entries). `hardware_completed_commits` is only
                            // populated while a commit is still retiring, so
                            // it is empty once the commit is current.
                            && completed.contains(&commit_key.commit)
                    });

                target_generation_was_offered
                    && target_commit_is_current
                    && backend
                        .scene
                        .damage_history_latest_generation_for_tests(output_idx)
                        > damage_before
                    && backend
                        .platform
                        .owner_ref(device)
                        .is_some_and(|owner| owner.live_record().is_none())
            },
            Some(hardware_complete),
            false,
            true,
        )?;

        let commit_key = backend
            .commit_consumer
            .current_resources
            .iter()
            .filter(|resources| resources.direct_role.is_none())
            .filter(|resources| resources.crtcs.iter().any(|member| member.crtc == crtc_key))
            .filter_map(|resources| resources.commit_id)
            .find(|commit_key| {
                commit_key.device == device
                    && !current_before.contains(commit_key)
                    && !dispatched_before.contains(&commit_key.commit)
                    && backend
                        .admission_trace_for_tests(device)
                        .contains(&AdmissionTraceStep::Dispatched(commit_key.commit))
                    && hardware_complete.borrow().contains(&commit_key.commit)
            })
            .ok_or_else(|| {
                format!(
                    "{label}: no fresh composed commit reached HardwareComplete; current={:?}; current_before={current_before:?}; dispatched_before={dispatched_before:?}; trace={:?}; hardware_complete={:?}; live={:?}",
                    backend
                        .commit_consumer
                        .current_resources
                        .iter()
                        .map(|resources| (
                            resources.commit_id,
                            resources.direct_role.is_some(),
                            resources.crtcs.iter().map(|member| member.crtc).collect::<Vec<_>>()
                        ))
                        .collect::<Vec<_>>(),
                    backend.admission_trace_for_tests(device),
                    hardware_complete.borrow(),
                    backend
                        .platform
                        .owner_ref(device)
                        .and_then(|owner| owner.live_record().map(|record| record.commit_id())),
                )
            })?;

        let current_framebuffer = c0_3aii_owner_current_framebuffer(backend, output_idx)
            .ok_or_else(|| format!("{label}: output has no retained composed framebuffer"))?;
        let dispatched_framebuffers = {
            let (consumer, service) = (
                &backend.commit_consumer,
                backend.resource_service.as_mut().expect("resource service"),
            );
            let resources = consumer
                .current_resources
                .iter()
                .find(|resources| resources.commit_id == Some(commit_key))
                .ok_or_else(|| {
                    format!(
                        "{label}: completed commit {:?} is not current",
                        commit_key.commit
                    )
                })?;
            let mut framebuffers = Vec::new();
            for allocation in &resources.allocations {
                let framebuffer = service
                    .with_scanout_read(allocation, |scanout| {
                        scanout.file_owned().and_then(|backing| backing.fb_handle())
                    })
                    .map_err(|error| {
                        format!(
                            "{label}: read commit {:?} scanout framebuffer: {error:?}",
                            commit_key.commit
                        )
                    })?;
                if let Some(framebuffer) = framebuffer {
                    framebuffers.push(framebuffer);
                }
            }
            framebuffers
        };
        if !dispatched_framebuffers.contains(&current_framebuffer) {
            return Err(format!(
                "{label}: dispatched commit {:?} primary plane {} FBs {:?} do not include current output FB {:?}",
                commit_key.commit, primary_plane, dispatched_framebuffers, current_framebuffer
            ));
        }

        Ok(commit_key.commit)
    }

    fn c0_3ci_expected_end_state_with_acquire_preparation(
        backend: &super::KmsBackend,
        outputs: impl IntoIterator<Item = OutputKey>,
    ) -> C0EndStateExpectation {
        let mut expected = c0_3bi_expected_end_state(outputs);
        expected.other_live_allocations = backend
            .lifecycle_drivers
            .values()
            .flat_map(|driver| driver.prepared_acquire_allocation_keys_for_tests())
            .collect();
        expected
    }

    fn c0_3ci_object_property_membership_error(
        device: &crate::drm::Device,
        description: &crate::kms::owner::build::CommitDescription,
    ) -> Result<(), String> {
        use crate::kms::owner::closure::ObjectKind;
        use ::drm::control::Device as _;

        for object in &description.objects {
            let discovered_property_ids = match object.kind {
                ObjectKind::Connector => {
                    let handle = ::drm::control::from_u32::<::drm::control::connector::Handle>(
                        object.object,
                    )
                    .ok_or_else(|| format!("connector object id is zero: {object:?}"))?;
                    device
                        .get_properties(handle)
                        .and_then(|properties| properties.as_hashmap(device))
                        .map_err(|error| {
                            format!(
                                "connector object {} was not discovered: {error}",
                                object.object
                            )
                        })?
                }
                ObjectKind::Crtc => {
                    let handle =
                        ::drm::control::from_u32::<::drm::control::crtc::Handle>(object.object)
                            .ok_or_else(|| format!("CRTC object id is zero: {object:?}"))?;
                    device
                        .get_properties(handle)
                        .and_then(|properties| properties.as_hashmap(device))
                        .map_err(|error| {
                            format!("CRTC object {} was not discovered: {error}", object.object)
                        })?
                }
                ObjectKind::Plane => {
                    let handle =
                        ::drm::control::from_u32::<::drm::control::plane::Handle>(object.object)
                            .ok_or_else(|| format!("plane object id is zero: {object:?}"))?;
                    device
                        .get_properties(handle)
                        .and_then(|properties| properties.as_hashmap(device))
                        .map_err(|error| {
                            format!("plane object {} was not discovered: {error}", object.object)
                        })?
                }
            }
            .values()
            .map(|property| u32::from(property.handle()))
            .collect::<HashSet<_>>();
            for (property, _) in &object.props {
                if !discovered_property_ids.contains(property) {
                    return Err(format!(
                        "object {} ({:?}) carries property id {property}, absent from its discovered property cache",
                        object.object, object.kind
                    ));
                }
            }
            if object.kind == ObjectKind::Crtc
                && !discovered_property_ids.contains(&description.property_ids.out_fence_ptr)
            {
                return Err(format!(
                    "CRTC object {} will carry OUT_FENCE_PTR property id {}, absent from its discovered property cache",
                    object.object, description.property_ids.out_fence_ptr
                ));
            }
        }
        Ok(())
    }

    fn c0_3ci_test_probe_results(
        backend: &super::KmsBackend,
    ) -> std::collections::BTreeMap<DrmDeviceKey, Result<Vec<ConnectorSnapshot>, io::ErrorKind>>
    {
        backend
            .platform
            .devices
            .iter()
            .map(|device| {
                let snapshot = backend
                    .platform
                    .outputs
                    .iter()
                    .filter(|layout| layout.key.device_key == device.key)
                    .map(|layout| ConnectorSnapshot {
                        key: layout.key.clone(),
                        modes: layout.output.modes.clone(),
                        mm_width: layout.output.mm_width,
                        mm_height: layout.output.mm_height,
                        edid: layout.output.edid.clone(),
                        connector_type: layout.output.connector_type.clone(),
                    })
                    .collect();
                (device.key, Ok(snapshot))
            })
            .collect()
    }

    fn c0_3ci_script_probe_results_for_tests(
        backend: &mut super::KmsBackend,
        results: std::collections::BTreeMap<
            DrmDeviceKey,
            Result<Vec<ConnectorSnapshot>, io::ErrorKind>,
        >,
    ) {
        // This helper is used only by synthetic acquire tests over a live
        // allocation fixture, so make the test-only prober opt-in explicit.
        // The actual live fixture itself retains DrmConnectorProber.
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        for (device, result) in results {
            backend.platform.script_connector_probe_for_tests(
                device,
                result.map_err(|kind| io::Error::new(kind, "scripted connector probe")),
            );
        }
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_acquire_description_uses_discovered_object_properties_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;

        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        assert!(backend.acquire_uses_live_kms_discovery_for_tests);

        // This fixture has real DRM connector/CRTC/plane handles and live
        // Vulkan scanout allocations, but its helper is an IPC stub. Preparing
        // the description exercises the acquire builder without a modeset or
        // DRM-master operation.
        let prepared = backend
            .lifecycle_prepare_acquire_topology(device)
            .expect("prepare the acquire reinstall on the live-KMS Owner fixture");
        let description = prepared.description.clone();
        let rediscovered_object_ids = prepared
            .outputs
            .iter()
            .flat_map(|prepared| {
                let output = prepared
                    .prepared_set
                    .output
                    .as_ref()
                    .expect("acquire output was rediscovered");
                [
                    (
                        crate::kms::owner::closure::ObjectKind::Connector,
                        u32::from(output.connector),
                    ),
                    (
                        crate::kms::owner::closure::ObjectKind::Crtc,
                        u32::from(output.crtc),
                    ),
                    (
                        crate::kms::owner::closure::ObjectKind::Plane,
                        u32::from(output.plane),
                    ),
                ]
            })
            .collect::<Vec<_>>();
        let drm_device = backend
            .platform
            .device_for_key(device)
            .expect("live fixture device")
            .device
            .clone_rc()
            .expect("attached test DRM device");
        let object_ids = description
            .objects
            .iter()
            .map(|object| (object.kind, object.object))
            .collect::<Vec<_>>();
        let property_pairs = description
            .objects
            .iter()
            .flat_map(|object| {
                object
                    .props
                    .iter()
                    .map(move |(property, _)| (object.kind, object.object, *property))
            })
            .collect::<Vec<_>>();
        backend.lifecycle_release_acquire_topology(prepared);

        c0_3ci_object_property_membership_error(&drm_device, &description).unwrap_or_else(|error| {
            panic!(
                "acquire reinstall must use this incarnation's object/property cache; objects={object_ids:?}; properties={property_pairs:?}; error={error}"
            )
        });
        assert_eq!(description.objects.len(), 3);
        assert_eq!(
            object_ids, rediscovered_object_ids,
            "serialized object IDs come from this acquire's connector/CRTC/plane discovery"
        );
        assert_eq!(
            object_ids.iter().map(|(kind, _)| *kind).collect::<Vec<_>>(),
            [
                crate::kms::owner::closure::ObjectKind::Connector,
                crate::kms::owner::closure::ObjectKind::Crtc,
                crate::kms::owner::closure::ObjectKind::Plane,
            ],
            "acquire and 3b's client modeset builder serialize one connector, CRTC, and primary plane"
        );

        // Mutation guard: put back the two old test-only IDs that belonged to
        // other objects on this device. The connector lacks property 23, and
        // this CRTC lacks property 21 (which is its plane's CRTC_ID).
        for (kind, old_property_id, property_index) in [
            (crate::kms::owner::closure::ObjectKind::Connector, 23, 0),
            (crate::kms::owner::closure::ObjectKind::Crtc, 21, 1),
        ] {
            let mut mutated = description.clone();
            let object = mutated
                .objects
                .iter_mut()
                .find(|object| object.kind == kind)
                .expect("object emitted by acquire description");
            object.props[property_index].0 = old_property_id;
            assert!(
                c0_3ci_object_property_membership_error(&drm_device, &mutated).is_err(),
                "the guard rejects old test-only property id {old_property_id} on {kind:?}"
            );
        }
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_acquire_description_uses_discovered_object_properties_vulkan",
            &c0_3bi_expected_end_state(outputs),
        );
    }

    fn c0_3ci_wait_owner_acquire_accepted(
        backend: &mut super::KmsBackend,
        state: &mut ServerState,
        device: DrmDeviceKey,
        label: &str,
    ) -> crate::kms::owner::identity::CommitId {
        c0_3bi_core_driver_until_with_state(
            backend,
            state,
            label,
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .platform
                    .owner_ref(device)
                    .and_then(|owner| owner.live_record())
                    .is_some_and(|record| record.milestones().accepted)
            },
            None,
        )
        .unwrap_or_else(|error| {
            let arbiter = backend.lifecycle_coordinator.device(&device).map(|arbiter| {
                (
                    arbiter.state(),
                    arbiter.transition(),
                    arbiter.desired().device_presence(),
                    arbiter.desired().representative(
                        crate::kms::owner::lifecycle::DesiredField::Seat,
                    ),
                )
            });
            let record = backend
                .platform
                .owner_ref(device)
                .and_then(|owner| owner.live_record())
                .map(|record| (record.commit_id(), record.state(), record.milestones()));
            let stats = backend.lifecycle_drivers.get(&device).map(|driver| {
                (
                    driver.topology_test_stats(),
                    driver.pending_topology_descriptions_for_tests(),
                    driver.acquire_topology_descriptions_for_tests(),
                )
            });
            let host_calls = backend.host_call_events_for_tests.lock().unwrap().clone();
            let owner_poisoned = backend.platform.owner_ref(device).map(|owner| owner.is_poisoned());
            panic!("{label}: {error}; arbiter={arbiter:?}; owner={record:?}; poisoned={owner_poisoned:?}; driver={stats:?}; host_calls={host_calls:?}");
        });
        backend
            .platform
            .owner_ref(device)
            .and_then(|owner| owner.live_record())
            .expect("accepted VTAcquire reinstall remains live")
            .commit_id()
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_requests_while_released_match_legacy_vulkan() {
        use std::{os::unix::net::UnixStream, time::Duration};

        use crate::kms::executor::test_support::StubBehaviour;
        use yserver_core::core_loop::process_request::{RequestOutcome, process_request};
        use yserver_protocol::x11::{
            ClientId, RequestHeader, SequenceNumber, dpms,
            randr::{self as rr},
        };

        fn set_crtc_disable(
            backend: &mut super::KmsBackend,
            state: &mut ServerState,
            peer: &mut UnixStream,
            client: u32,
            output_id: u32,
        ) -> Vec<u8> {
            let output = state
                .randr
                .outputs
                .iter()
                .find(|output| output.output_id == output_id)
                .expect("requested RANDR output");
            let mut body = Vec::with_capacity(24);
            body.extend_from_slice(&output.crtc_id.to_le_bytes());
            body.extend_from_slice(&1234_u32.to_le_bytes());
            body.extend_from_slice(&state.randr.config_timestamp.to_le_bytes());
            body.extend_from_slice(&0_i16.to_le_bytes());
            body.extend_from_slice(&0_i16.to_le_bytes());
            body.extend_from_slice(&0_u32.to_le_bytes());
            body.extend_from_slice(&0_u16.to_le_bytes());
            body.extend_from_slice(&[0; 2]);
            let outcome = process_request(
                state,
                backend,
                ClientId(client),
                SequenceNumber(1),
                RequestHeader {
                    opcode: 128,
                    data: rr::RR_SET_CRTC_CONFIG,
                    length_units: 7,
                },
                &body,
                None,
            )
            .expect("core SetCrtcConfig dispatch");
            assert!(
                matches!(outcome, RequestOutcome::Handled),
                "released SetCrtcConfig must answer synchronously: {outcome:?}"
            );
            kbd_map_drain(peer)
        }

        fn dpms_wire(
            backend: &mut super::KmsBackend,
            state: &mut ServerState,
            requester: &mut UnixStream,
            listener: &mut UnixStream,
        ) -> (Vec<u8>, Vec<u8>) {
            fn issue(
                backend: &mut super::KmsBackend,
                state: &mut ServerState,
                client: u32,
                sequence: u16,
                minor: u8,
                body: &[u8],
            ) {
                let outcome = process_request(
                    state,
                    backend,
                    ClientId(client),
                    SequenceNumber(sequence),
                    RequestHeader {
                        opcode: 134,
                        data: minor,
                        length_units: if body.is_empty() { 1 } else { 2 },
                    },
                    body,
                    None,
                )
                .expect("core DPMS request dispatch");
                assert!(
                    matches!(outcome, RequestOutcome::Handled),
                    "DPMS request completes synchronously: {outcome:?}"
                );
            }

            issue(
                backend,
                state,
                82,
                1,
                dpms::SELECT_INPUT,
                &dpms::DPMS_INFO_NOTIFY_MASK.to_le_bytes(),
            );
            issue(
                backend,
                state,
                81,
                2,
                dpms::FORCE_LEVEL,
                &[dpms::DPMS_MODE_OFF as u8, 0, 0, 0],
            );
            issue(backend, state, 81, 3, dpms::INFO, &[]);
            (kbd_map_drain(requester), kbd_map_drain(listener))
        }

        // AcceptKernelCalls exercises the Owner helper protocol only; it does
        // not issue the kernel ACTIVE=0 atomic commit or VT_RELDISP/drmDropMaster.
        let (mut fixture, device, outputs, _target_mode) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        let mut owner_state = c0_3ci_core_state(backend);
        owner_state.dpms.kms_capable = true;
        owner_state.dpms.enabled = true;
        owner_state.start_instant = std::time::Instant::now()
            .checked_add(Duration::from_secs(60))
            .expect("stable protocol clock");
        owner_state.randr.timestamp = 1234;
        let mut owner_requester = c0_3aii_install_dpms_core_client(&mut owner_state, 81);
        let mut owner_listener = c0_3aii_install_dpms_core_client(&mut owner_state, 82);
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut owner_state,
            device,
            "Task 3 Owner release before protocol requests",
        );
        assert_eq!(backend.vt_state, crate::vt::state::VtState::Suspended);
        let (released_output_id, released_output_name) = owner_state
            .randr
            .outputs
            .iter()
            .find(|output| backend.output_key_for_id(output.output_id) == Some(&outputs[0]))
            .map(|output| (output.output_id, output.name.clone()))
            .expect("live Owner RANDR output");
        let released_key = backend
            .output_key_for_id(released_output_id)
            .expect("Owner output key");
        let released_error = backend
            .begin_owner_crtc_config(
                released_output_id,
                &released_output_name,
                None,
                0,
                0,
                released_key.clone(),
            )
            .expect_err("released Owner seat refuses SetCrtcConfig");
        assert_eq!(
            c0_3bi_client_modeset_failure(&released_error),
            Some(crate::kms::render::admission::ClientModesetFailure::SeatReleased),
            "the Legacy-identical Failed reply is specifically caused by SeatReleased: {released_error:?}"
        );
        let owner_topology_sends = backend.lifecycle_drivers[&device]
            .topology_test_stats()
            .1
            .len();
        let owner_client_sends = backend.lifecycle_drivers[&device]
            .client_modeset_test_stats()
            .1
            .len();

        let mut legacy = super::KmsBackend::for_tests();
        legacy.vt_state = crate::vt::state::VtState::Suspended;
        legacy.kms_outputs_active = false;
        let mut legacy_state = c0_3ci_core_state(&mut legacy);
        legacy_state.dpms.kms_capable = true;
        legacy_state.dpms.enabled = true;
        legacy_state.start_instant = std::time::Instant::now()
            .checked_add(Duration::from_secs(60))
            .expect("stable protocol clock");
        legacy_state.randr.timestamp = 1234;
        let mut legacy_requester = c0_3aii_install_dpms_core_client(&mut legacy_state, 81);
        let mut legacy_listener = c0_3aii_install_dpms_core_client(&mut legacy_state, 82);

        let owner_crtc_reply = set_crtc_disable(
            backend,
            &mut owner_state,
            &mut owner_requester,
            81,
            released_output_id,
        );
        let legacy_output_id = legacy_state
            .randr
            .outputs
            .first()
            .expect("one Legacy RANDR output")
            .output_id;
        let legacy_crtc_reply = set_crtc_disable(
            &mut legacy,
            &mut legacy_state,
            &mut legacy_requester,
            81,
            legacy_output_id,
        );
        assert_eq!(
            owner_crtc_reply, legacy_crtc_reply,
            "SetCrtcConfig reply bytes"
        );
        assert_eq!(owner_crtc_reply.len(), 32);
        assert_eq!(owner_crtc_reply[1], 3, "RRSetCrtcConfig reports Failed");
        assert_eq!(
            u32::from_le_bytes(owner_crtc_reply[8..12].try_into().unwrap()),
            1234,
            "failed reply preserves lastSetTime"
        );

        let owner_dpms = dpms_wire(
            backend,
            &mut owner_state,
            &mut owner_requester,
            &mut owner_listener,
        );
        let legacy_dpms = dpms_wire(
            &mut legacy,
            &mut legacy_state,
            &mut legacy_requester,
            &mut legacy_listener,
        );
        assert_eq!(owner_dpms, legacy_dpms, "DPMSInfo and notification bytes");
        assert_eq!(owner_dpms.0.len(), 32, "one DPMSInfo reply");
        assert_eq!(
            u16::from_le_bytes(owner_dpms.0[8..10].try_into().unwrap()),
            dpms::DPMS_MODE_OFF,
            "DPMSForceLevel updates the protocol level while released"
        );
        assert_eq!(owner_dpms.1.len(), 32, "one DPMSInfoNotify event");

        c0_3bi_core_driver_until_with_state(
            backend,
            &mut owner_state,
            "Task 3 released requests do not dispatch Owner KMS work",
            Duration::from_millis(20),
            &|_| true,
            None,
        )
        .expect("core entries drain any released-seat lifecycle work");
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .topology_test_stats()
                .1
                .len(),
            owner_topology_sends,
            "released requests send no lifecycle KMS calls"
        );
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .client_modeset_test_stats()
                .1
                .len(),
            owner_client_sends,
            "released SetCrtcConfig sends no client modeset"
        );

        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_requests_while_released_match_legacy_vulkan Owner",
            &c0_3bi_expected_end_state(outputs.clone()),
        );
        c0_3bi_assert_end_state(
            &legacy,
            "c0_3ci_requests_while_released_match_legacy_vulkan Legacy",
            &c0_3bi_expected_end_state(
                legacy
                    .platform
                    .outputs
                    .iter()
                    .map(|output| output.key.clone()),
            ),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_dpms_while_released_is_deferred_vulkan() {
        use std::time::Duration;

        use crate::kms::{
            executor::test_support::StubBehaviour,
            owner::lifecycle::{DesiredField, Disposition, Prerequisite},
        };
        use yserver_core::core_loop::process_request::{RequestOutcome, process_request};
        use yserver_protocol::x11::{ClientId, RequestHeader, SequenceNumber, dpms};

        // The accepting stub does not issue the kernel ACTIVE=0 atomic commit
        // or perform VT_RELDISP/drmDropMaster; it only replies to helper IPC.
        let (mut fixture, device, outputs, _target_mode) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        let mut state = c0_3ci_core_state(backend);
        state.dpms.kms_capable = true;
        state.dpms.enabled = true;
        let _requester = c0_3aii_install_dpms_core_client(&mut state, 81);
        c0_3ci_release_owner_to_suspended(
            backend,
            &mut state,
            device,
            "Task 3 DPMS release before deferred level updates",
        );

        let sends_before = backend.lifecycle_drivers[&device]
            .topology_test_stats()
            .1
            .len();
        for (sequence, level) in [(1, dpms::DPMS_MODE_STANDBY), (2, dpms::DPMS_MODE_OFF)] {
            let outcome = process_request(
                &mut state,
                backend,
                ClientId(81),
                SequenceNumber(sequence),
                RequestHeader {
                    opcode: 134,
                    data: dpms::FORCE_LEVEL,
                    length_units: 2,
                },
                &[level as u8, 0, 0, 0],
                None,
            )
            .expect("core DPMSForceLevel dispatch");
            assert!(matches!(outcome, RequestOutcome::Handled));
        }

        let arbiter = backend
            .lifecycle_coordinator
            .device(&device)
            .expect("Owner lifecycle arbiter");
        let desired = arbiter.desired();
        assert_eq!(state.dpms.power_level, dpms::DPMS_MODE_OFF as u8);
        assert_eq!(
            backend.lifecycle_coordinator.protocol_dpms_level(),
            dpms::DPMS_MODE_OFF as u8,
            "coordinator keeps the protocol level even while its transport is closed; gate={:?}",
            backend
                .platform
                .transport_gate(&device)
                .map(|gate| gate.state())
        );
        let representative = desired
            .representative(DesiredField::Dpms)
            .expect("deferred DPMS representative");
        assert_eq!(
            u16::from(desired.protocol_dpms_level()),
            dpms::DPMS_MODE_OFF
        );
        assert_eq!(
            representative.disposition,
            Some(Disposition::Deferred(Prerequisite::SeatReleased))
        );
        let projection = desired
            .dpms_targets()
            .get(&outputs[0])
            .expect("Owner output's DPMS projection");
        assert_eq!(u16::from(projection.level), dpms::DPMS_MODE_OFF);
        assert_eq!(projection.representative, Some(representative.event_id));
        assert!(backend.device_owner_for_tests(0).live_record().is_none());

        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "Task 3 newest released DPMS level remains deferred",
            Duration::from_millis(20),
            &|_| true,
            None,
        )
        .expect("core entries drain any released-seat lifecycle work");
        assert_eq!(
            backend.lifecycle_drivers[&device]
                .topology_test_stats()
                .1
                .len(),
            sends_before,
            "deferred DPMS levels send no executor call"
        );

        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_dpms_while_released_is_deferred_vulkan",
            &c0_3bi_expected_end_state(outputs),
        );
    }

    #[test]
    #[cfg(target_os = "linux")]
    fn c0_3ci_hotplug_edge_is_recorded_until_owner_seat_returns() {
        use std::time::Duration;

        use crate::kms::executor::test_support::StubBehaviour;

        // NeverReply is idle in this scenario: the injected edge is retained
        // as state, and no connector probe or kernel KMS side effect occurs.
        let (mut backend, device) = lifecycle_dpms_backend(StubBehaviour::NeverReply);
        backend.vt_state = crate::vt::state::VtState::Suspended;
        super::KmsBackend::record_display_hotplug_edge(&mut backend);
        assert!(backend.hotplug_rescan_deferred);
        assert!(backend.hotplug_rescan_deadline.is_none());

        let mut state = ServerState::new();
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "released Owner hotplug edge remains recorded",
            Duration::from_millis(20),
            &|_| true,
            None,
        )
        .expect("core entry leaves released hotplug edge pending");
        assert!(backend.hotplug_rescan_deferred);
        assert!(backend.hotplug_rescan_deadline.is_none());

        backend.vt_state = crate::vt::state::VtState::Active;
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "returned Owner hotplug edge arms its debounce",
            Duration::from_millis(20),
            &|backend| backend.hotplug_rescan_deferred,
            None,
        )
        .expect("core entry arms the deferred hotplug rescan after acquire");
        assert!(!backend.hotplug_rescan_deferred);
        assert!(backend.hotplug_rescan_deadline.is_some());

        c0_3bi_assert_end_state(
            &backend,
            "c0_3ci_hotplug_edge_is_recorded_until_owner_seat_returns",
            &c0_3bi_expected_end_state([OutputKey::new(device, "test")]),
        );
    }

    fn c0_3ci_expected_end_state_with_pending_client_modeset(
        backend: &super::KmsBackend,
        outputs: impl IntoIterator<Item = OutputKey>,
    ) -> C0EndStateExpectation {
        let mut expected = c0_3bi_expected_end_state(outputs);
        expected.other_live_allocations = backend
            .lifecycle_drivers
            .values()
            .filter_map(|driver| driver.client_modeset.as_ref())
            .filter_map(|slot| slot.prepared.as_ref())
            .flat_map(|prepared| prepared.prepared_set.allocation_keys.iter().copied())
            .collect();
        expected
    }

    fn c0_3ci_add_legacy_output(
        backend: &mut super::KmsBackend,
        device_number: u32,
        crtc: u32,
    ) -> (DrmDeviceKey, OutputKey) {
        let device = test_device_key(device_number);
        push_test_device(backend, device);
        push_test_output(backend, crtc);
        let output = &mut backend.platform.outputs[1];
        let key = OutputKey::new(device, output.key.connector_name.clone());
        output.key = key.clone();
        output.scanout_route.kms_device_key = device;
        backend.platform.output_instance_ids[1] = backend
            .platform
            .allocate_output_instance_id(&key)
            .expect("Legacy fixture output instance");
        let ids = backend.randr_id_alloc.ids_for(&key);
        backend.output_key_by_id.insert(ids.output_id, key.clone());
        let output = &backend.platform.outputs[1];
        let entry = backend.randr_id_alloc.entry_mut(&key);
        entry.connected = true;
        entry.config = super::ConnectorConfig::Enabled {
            mode_w: output.width,
            mode_h: output.height,
            vrefresh: output.output.picked.vrefresh,
            x: output.x,
            y: output.y,
        };
        entry.modes = output.output.modes.clone();
        entry.edid = output.output.edid.clone();
        entry.mm_width = output.output.mm_width;
        entry.mm_height = output.output.mm_height;
        entry.connector_type = output.output.connector_type.clone();
        backend
            .scene
            .rebuild_outputs(&backend.platform)
            .expect("Legacy fixture output joins the scene inventory");
        (device, key)
    }

    fn c0_3ci_install_legacy_probe_snapshot(
        backend: &mut super::KmsBackend,
        device: DrmDeviceKey,
        output: &OutputKey,
    ) {
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let layout = backend
            .platform
            .outputs
            .iter()
            .find(|layout| &layout.key == output)
            .expect("Legacy probe output remains installed");
        let snapshot = ConnectorSnapshot {
            key: output.clone(),
            modes: layout.output.modes.clone(),
            mm_width: layout.output.mm_width,
            mm_height: layout.output.mm_height,
            edid: layout.output.edid.clone(),
            connector_type: layout.output.connector_type.clone(),
        };
        backend
            .platform
            .script_connector_probe_for_tests(device, Ok(vec![snapshot]));
        assert_eq!(output.device_key, device);
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_prompt_obligations_never_wait_vulkan() {
        use crate::{
            kms::{executor::test_support::StubBehaviour, owner::lifecycle::SeatTarget},
            vt::state::VtState,
        };
        use yserver_core::{
            core_loop::{DeviceInfo, HostInputEvent, InputOrigin, message::LibinputConfigSnapshot},
            host_x11::HostKeyEvent,
            xinput::{InputCapabilities, InputSourceId},
        };

        let (mut fixture, device, outputs, target_mode) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptValidationThenNeverReply, false);
        let backend = &mut fixture.backend;
        let mut state = c0_3ci_core_state(backend);
        let mut peer = c0_3aii_install_dpms_core_client(&mut state, 72);
        let output_id = backend.randr_id_alloc.ids_for(&outputs[0]).output_id;
        backend
            .output_key_by_id
            .insert(output_id, outputs[0].clone());
        let token = c0_3bi_begin_client_modeset(
            backend,
            output_id,
            &outputs[0].connector_name,
            Some(target_mode),
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "dispatch client modeset before VT release",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .lifecycle_drivers
                    .get(&device)
                    .and_then(|driver| driver.client_modeset.as_ref())
                    .is_some_and(|slot| {
                        slot.token == token
                            && slot.phase
                                == crate::kms::render::admission::ClientModesetPhase::Dispatched
                    })
            },
            None,
        )
        .expect("client modeset is dispatched and its executor stops replying");
        let client_commit = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("dispatched client commit")
            .commit_id();
        let source = InputSourceId(0xC031);
        Backend::on_host_input(
            backend,
            &mut state,
            HostInputEvent::DeviceAdded(DeviceInfo {
                source_id: source,
                enabled: true,
                resume_key: None,
                capabilities: InputCapabilities {
                    keyboard: true,
                    pointer: true,
                    touch: false,
                },
                name: "C.0 VT held-input fixture".into(),
                device_node: "/dev/input/event193".into(),
                sysname: "event193".into(),
                vendor_id: 1,
                product_id: 2,
                is_touchpad: false,
                config: LibinputConfigSnapshot::default(),
            }),
        );
        Backend::on_host_input(
            backend,
            &mut state,
            HostInputEvent::Key(HostKeyEvent {
                origin: InputOrigin::Physical(source),
                keycode: 38,
                pressed: true,
                time: 0,
                root_x: 0,
                root_y: 0,
                event_x: 0,
                event_y: 0,
                state: 0,
            }),
        );
        Backend::on_host_input(
            backend,
            &mut state,
            HostInputEvent::PointerButton {
                origin: InputOrigin::Physical(source),
                button: 0x110,
                pressed: true,
                time: 0,
            },
        );
        assert!(
            state.xi_devices.source(source).is_some(),
            "fixture source registered"
        );
        assert!(backend.core.down_keys.contains(&38), "fixture key is held");
        assert_ne!(backend.core.button_mask, 0, "fixture button is held");
        backend.set_input_thread_control(std::sync::Arc::new(
            crate::input_thread::InputThreadControl::new().expect("input control eventfd"),
        ));
        state.dpms.power_level = 3;
        let previous_activity = state.dpms.last_activity;

        // The executor stub cannot issue a DRM atomic ioctl, signal a kernel
        // out-fence, or perform the VT hand-off. It only accepts validation
        // through its protocol and then withholds the live-call reply.
        // The production release path: the core pauses input, then finishes.
        let _pause_barrier_queued = Backend::begin_vt_release(backend);
        Backend::finish_vt_release(
            backend,
            &mut state,
            &yserver_core::core_loop::input_inventory::InputInventory::new(),
        );

        assert_eq!(backend.vt_state, VtState::Suspending);
        assert_eq!(
            backend.lifecycle_coordinator.seat_target(),
            Some(SeatTarget::Released)
        );
        assert!(backend.core.down_keys.is_empty(), "held key was released");
        assert_eq!(backend.core.button_mask, 0, "held button was released");
        assert_eq!(state.dpms.power_level, 0, "protocol DPMS resets to On");
        assert!(state.dpms.last_activity > previous_activity);
        assert_eq!(
            &backend.vt_call_trace_for_tests[..2],
            ["pause_input", "held_releases"]
        );
        assert!(backend.admission_conductors[&device].lifecycle_admission_closed);
        assert!(Backend::present_scanout_blackout(
            backend,
            u32::from(backend.platform.outputs[0].output.crtc)
        ));
        assert!(
            backend
                .device_owner_for_tests(0)
                .live_record()
                .is_some_and(|record| record.commit_id() == client_commit)
        );
        assert!(
            kbd_map_drain(&mut peer).is_empty(),
            "no executor reply was observed"
        );
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_prompt_obligations_never_wait_vulkan",
            &c0_3ci_expected_end_state_with_pending_client_modeset(backend, outputs),
        );
    }

    #[test]
    fn c0_3ci_legacy_only_release_unchanged() {
        use crate::vt::state::VtState;

        let mut backend = KmsBackend::for_tests();
        let output = backend.platform.outputs[0].key.clone();
        backend.platform.dpms_output_calls_for_tests = Some(Vec::new());
        backend.platform.dpms_output_scopes_for_tests = Some(Vec::new());
        let mut state = ServerState::new();

        Backend::on_vt_release(&mut backend, &mut state);

        assert_eq!(
            backend.platform.dpms_output_calls_for_tests,
            Some(vec![(false, vec![output.clone()])])
        );
        assert_eq!(
            backend.platform.dpms_output_scopes_for_tests,
            Some(vec![None])
        );
        assert!(backend.owner_vt_release.is_none());
        assert!(
            !backend
                .vt_call_trace_for_tests
                .contains(&"legacy_set_seat_target"),
            "Legacy-only release keeps the established call sequence"
        );
        assert_eq!(backend.vt_state, VtState::Suspended);
        c0_3bi_assert_end_state(
            &backend,
            "c0_3ci_legacy_only_release_unchanged",
            &c0_3bi_expected_end_state([output]),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_release_commit_is_active_off_vulkan() {
        use crate::kms::{
            executor::{
                ObservedOutcome, protocol::HostCallCorrelation, test_support::StubBehaviour,
            },
            owner::closure::ObjectKind,
        };

        let (mut fixture, device, outputs, _) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), true);
        let backend = &mut fixture.backend;
        let mut state = c0_3ci_core_state(backend);
        // AcceptKernelCalls accepts protocol requests only. This Vulkan
        // fixture does not execute DRM atomic ioctls, signal out-fences, or
        // perform the VT master hand-off.
        Backend::on_vt_release(backend, &mut state);
        let description = backend.lifecycle_drivers[&device]
            .pending_topology_descriptions_for_tests()
            .into_iter()
            .next()
            .unwrap_or_else(|| panic!("ACTIVE=0 TEST_ONLY description is queued",));
        let expected_crtcs = backend
            .platform
            .outputs
            .iter()
            .filter(|output| output.key.device_key == device)
            .map(|output| u32::from(output.output.crtc))
            .collect::<Vec<_>>();
        assert_eq!(description.objects.len(), 2);
        assert_eq!(description.crtc_state.len(), 2);
        for (object, crtc) in description.objects.iter().zip(&expected_crtcs) {
            assert_eq!(object.kind, ObjectKind::Crtc);
            assert_eq!(object.object, *crtc);
            assert_eq!(object.props, vec![(description.property_ids.active, 0)]);
        }
        assert!(description.objects.iter().all(|object| {
            object.kind != ObjectKind::Plane
                && object
                    .props
                    .iter()
                    .all(|(property, _)| *property != description.property_ids.out_fence_ptr)
        }));

        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "executor accepts release lifecycle commit",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .device_owner_for_tests(0)
                    .live_record()
                    .is_some_and(|record| record.milestones().accepted)
            },
            None,
        )
        .expect("release commit reaches the executor through core entries");
        let record = backend.device_owner_for_tests(0).live_record().unwrap();
        assert_eq!(record.closure().expected_completion(), expected_crtcs);
        let commit = record.commit_id();
        let accepted_fence_count = backend
            .drained_host_call_events_for_tests()
            .into_iter()
            .find_map(
                |observation| match (observation.correlation, observation.kind) {
                    (
                        HostCallCorrelation::Atomic {
                            commit: observed, ..
                        },
                        ObservedOutcome::Accepted { fence_count, .. },
                    ) if observed == commit => Some(fence_count),
                    _ => None,
                },
            )
            .expect("executor accepted the release commit");
        assert_eq!(
            accepted_fence_count, 2,
            "one required out-fence per lit CRTC"
        );
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_release_commit_is_active_off_vulkan",
            &c0_3bi_expected_end_state(outputs),
        );
    }

    #[test]
    #[ignore = "needs live Vulkan ICD"]
    fn c0_3ci_release_commit_waits_behind_dispatched_modeset_vulkan() {
        use crate::kms::executor::test_support::StubBehaviour;

        let (mut fixture, device, outputs, target_mode) =
            c0_3ci_live_release_fixture(StubBehaviour::AcceptKernelCalls(1_000), false);
        let backend = &mut fixture.backend;
        let previous_completion_deadline = backend
            .platform
            .owner_ref(device)
            .expect("Owner device")
            .completion_deadline_override;
        c0_3bi_set_owner_completion_deadline_for_tests(
            backend,
            device,
            Some(std::time::Duration::from_secs(30)),
        );
        c0_3bi_settle_owner_frame_work_through_core_driver(
            backend,
            device,
            "settle Owner frame work before client modeset and VT release",
            std::time::Duration::from_secs(3),
        )
        .expect("initial Owner frame work settles through core entries");
        let initial_current_resources = backend
            .commit_consumer
            .current_resources
            .iter()
            .filter(|resources| {
                resources
                    .crtcs
                    .iter()
                    .any(|member| member.crtc.device_key == device)
            })
            .collect::<Vec<_>>();
        assert_eq!(
            initial_current_resources.len(),
            1,
            "the settled Owner fixture has one current framebuffer lease"
        );
        assert_eq!(initial_current_resources[0].allocations.len(), 1);
        let initial_current_commit = initial_current_resources[0].commit_id;
        let initial_current_allocation = initial_current_resources[0].allocations[0].key();
        let retired_instance = backend
            .scene
            .output_instance_id_for_tests(0)
            .expect("initial output instance before client modeset");
        let mut state = c0_3ci_core_state(backend);
        let output_id = backend.randr_id_alloc.ids_for(&outputs[0]).output_id;
        backend
            .output_key_by_id
            .insert(output_id, outputs[0].clone());
        let token = c0_3bi_begin_client_modeset(
            backend,
            output_id,
            &outputs[0].connector_name,
            Some(target_mode),
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "dispatch the client modeset",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .lifecycle_drivers
                    .get(&device)
                    .and_then(|driver| driver.client_modeset.as_ref())
                    .is_some_and(|slot| {
                        slot.token == token
                            && slot.phase
                                == crate::kms::render::admission::ClientModesetPhase::Dispatched
                    })
            },
            None,
        )
        .expect("client modeset occupies the Owner slot");
        let client_commit = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("client commit")
            .commit_id();
        Backend::on_vt_release(backend, &mut state);
        assert_eq!(
            backend
                .device_owner_for_tests(0)
                .live_record()
                .map(|record| record.commit_id()),
            Some(client_commit),
            "VT release does not preempt the dispatched client commit"
        );

        // The executor stub accepts requests but cannot emit a real DRM
        // page-flip event or signal an out-fence; the existing core-entry
        // completion seam injects those kernel effects after 50 ms.
        std::thread::sleep(std::time::Duration::from_millis(50));
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device,
            client_commit,
            "client modeset completes before release commit",
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "finish client token and dispatch queued VT release",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .device_owner_for_tests(0)
                    .live_record()
                    .is_some_and(|record| {
                        record.commit_id() != client_commit && record.milestones().accepted
                    })
            },
            None,
        )
        .expect("VT release commit is sent only after client completion");
        assert!(c0_3bi_has_crtc_config_result(backend, token));
        let _ = c0_3bi_take_crtc_config_result(backend, token)
            .expect("client modeset token completes before VT hand-off");
        let release_commit = backend
            .device_owner_for_tests(0)
            .live_record()
            .expect("release commit")
            .commit_id();
        c0_3bi_complete_owner_commit_through_core_driver(
            backend,
            device,
            release_commit,
            "release commit completes after client modeset",
        );
        assert_eq!(
            &backend.vt_call_trace_for_tests[backend.vt_call_trace_for_tests.len() - 2..],
            ["drop_master", "vt_reldisp"]
        );
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "drain the retired output after client modeset and VT release",
            std::time::Duration::from_secs(3),
            &|backend| {
                !backend
                    .scene
                    .retired_output_has_instance_for_tests(retired_instance)
            },
            None,
        )
        .expect("the initial output instance drains through core entries after release");
        let current_release_resources = backend
            .commit_consumer
            .current_resources
            .iter()
            .filter(|resources| {
                resources
                    .crtcs
                    .iter()
                    .any(|member| member.crtc.device_key == device)
            })
            .collect::<Vec<_>>();
        assert_eq!(
            current_release_resources.len(),
            1,
            "VT release retains the one current framebuffer lease from the settled Owner fixture"
        );
        assert_eq!(
            current_release_resources[0].commit_id,
            initial_current_commit
        );
        assert_eq!(current_release_resources[0].crtcs.len(), 1);
        assert!(
            current_release_resources[0]
                .crtcs
                .iter()
                .all(|member| member.crtc.device_key == device)
        );
        assert_eq!(
            current_release_resources[0].allocations.len(),
            1,
            "the retained current CRTC has one framebuffer allocation"
        );
        assert_eq!(
            current_release_resources[0].allocations[0].key(),
            initial_current_allocation,
            "client modeset and VT release leave the exact fixture framebuffer current"
        );
        let mut expected = c0_3bi_expected_end_state(outputs.clone());
        expected.other_live_allocations = vec![initial_current_allocation];
        c0_3bi_core_driver_until_with_state(
            backend,
            &mut state,
            "settle release and modeset resources through core entries",
            std::time::Duration::from_secs(3),
            &|backend| {
                backend
                    .platform
                    .owner_ref(device)
                    .and_then(|owner| owner.live_record())
                    .is_none()
                    && c0_3bi_end_state_errors(backend, &expected).is_empty()
            },
            None,
        )
        .expect("release and modeset resources settle through core entries");
        c0_3bi_assert_end_state(
            backend,
            "c0_3ci_release_commit_waits_behind_dispatched_modeset_vulkan",
            &expected,
        );
        c0_3bi_set_owner_completion_deadline_for_tests(
            backend,
            device,
            previous_completion_deadline,
        );
    }

