    fn c0_3di_assert_old_file_native_objects_gone(
        backend: &super::KmsBackend,
        device: DrmDeviceKey,
        incarnation: IncarnationId,
        test_name: &str,
    ) {
        let mut pool_gbm_devices = 0;
        let mut pool_gbm_bos = 0;
        for (output, scanout) in backend
            .platform
            .outputs
            .iter()
            .zip(&backend.platform.scanout_pools)
        {
            if output.key.device_key == device
                && let Some(scanout) = scanout.as_ref()
            {
                let (devices, bos) = scanout.file_family_gbm_object_counts_for_tests();
                pool_gbm_devices += devices;
                pool_gbm_bos += bos;
            }
        }
        assert_eq!(
            pool_gbm_devices, 0,
            "{test_name}: the old incarnation's scanout pools retain no GBM device"
        );
        assert_eq!(
            pool_gbm_bos, 0,
            "{test_name}: the old incarnation's scanout pools retain no GBM BO"
        );
        let old_service = backend
            .resource_service
            .as_ref()
            .filter(|service| service.device() == device && service.incarnation() == incarnation)
            .expect("old incarnation resource service remains available for quarantine");
        let old_registry = backend
            .drm_cleanup_registry
            .as_ref()
            .filter(|registry| {
                registry.device_key() == device && registry.incarnation() == incarnation
            })
            .expect("old incarnation cleanup registry remains in quarantine");
        assert_eq!(
            old_registry.retained_native_file_object_count_for_tests(),
            0,
            "{test_name}: the old incarnation retains no native GBM device"
        );
        assert_eq!(
            old_service.file_owned_gbm_bo_count_for_tests(),
            0,
            "{test_name}: family closure destroyed every managed old-incarnation GBM BO"
        );
    }

    fn c0_3di_file_description_fds_for_tests(
        fd: std::os::fd::RawFd,
    ) -> std::io::Result<Vec<std::os::fd::RawFd>> {
        #[cfg(target_os = "linux")]
        {
            let pid = unsafe { libc::getpid() };
            let mut matching = Vec::new();
            for entry in std::fs::read_dir("/proc/self/fd")? {
                let entry = entry?;
                let Some(candidate) = entry
                    .file_name()
                    .to_str()
                    .and_then(|name| name.parse::<std::os::fd::RawFd>().ok())
                else {
                    continue;
                };
                if candidate == fd {
                    matching.push(candidate);
                    continue;
                }
                // SAFETY: KCMP_FILE only compares the two open descriptors;
                // both process ids are this process and `candidate` came
                // from its live /proc/self/fd directory.
                let result = unsafe { libc::syscall(libc::SYS_kcmp, pid, pid, 0, fd, candidate) };
                if result == 0 {
                    matching.push(candidate);
                } else if result < 0 {
                    let error = std::io::Error::last_os_error();
                    if error.raw_os_error() != Some(libc::EBADF) {
                        return Err(error);
                    }
                }
            }
            Ok(matching)
        }
        #[cfg(not(target_os = "linux"))]
        {
            let _ = fd;
            Err(std::io::Error::new(
                std::io::ErrorKind::Unsupported,
                "proc fd description comparison requires Linux kcmp",
            ))
        }
    }

    fn c0_3di_card_fd_numbers_for_tests(
        card_path: &std::path::Path,
    ) -> std::io::Result<Vec<std::os::fd::RawFd>> {
        #[cfg(target_os = "linux")]
        {
            let mut matching = Vec::new();
            for entry in std::fs::read_dir("/proc/self/fd")? {
                let entry = entry?;
                let Some(candidate) = entry
                    .file_name()
                    .to_str()
                    .and_then(|name| name.parse::<std::os::fd::RawFd>().ok())
                else {
                    continue;
                };
                match std::fs::read_link(entry.path()) {
                    Ok(target) if target == card_path => matching.push(candidate),
                    Ok(_) => {}
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
                    Err(error) => return Err(error),
                }
            }
            Ok(matching)
        }
        #[cfg(not(target_os = "linux"))]
        {
            let _ = card_path;
            Err(std::io::Error::new(
                std::io::ErrorKind::Unsupported,
                "proc fd inspection requires Linux",
            ))
        }
    }

    fn c0_3di_assert_end_state(backend: &super::KmsBackend, test_name: &str) {
        let installed = backend
            .platform
            .outputs
            .iter()
            .map(|output| output.key.clone())
            .collect::<Vec<_>>();
        c0_3bi_assert_end_state(backend, test_name, &c0_3bi_expected_end_state(installed));
        for quarantine in &backend.quarantined_normal_recoveries {
            let incarnation = quarantine
                .device
                .owner
                .as_ref()
                .map(|owner| owner.incarnation());
            assert!(
                incarnation == Some(quarantine.transition.incarnation)
                    || incarnation == Some(quarantine.transition.incarnation.next()),
                "{test_name}: quarantined device identity remains tied to its transition"
            );
            if let Some(service) = &quarantine.resource_service {
                assert_eq!(Some(service.incarnation()), incarnation);
            }
            if let Some(registry) = &quarantine.cleanup_registry {
                assert_eq!(Some(registry.incarnation()), incarnation);
            }
        }
        if let Some((device, incarnation)) = backend
            .drm_cleanup_registry
            .as_ref()
            .filter(|registry| registry.is_family_closed())
            .map(|registry| (registry.device_key(), registry.incarnation()))
        {
            c0_3di_assert_old_file_native_objects_gone(backend, device, incarnation, test_name);
        }
    }

    fn c0_3di_assert_reopened_end_state(
        backend: &super::KmsBackend,
        device: DrmDeviceKey,
        old_incarnation: IncarnationId,
        new_incarnation: IncarnationId,
        test_name: &str,
    ) {
        use crate::kms::owner::lifecycle::DeviceLifecycleState;

        let owner = backend
            .platform
            .owner_ref(device)
            .expect("the reopened device retains an Owner");
        assert_eq!(owner.incarnation(), new_incarnation, "{test_name}");
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .map(|arbiter| arbiter.state()),
            Some(DeviceLifecycleState::RecoveryFailed),
            "{test_name}: Task 3 ends with the default non-qualified attempt outcome"
        );
        assert!(
            !backend.pending_normal_recoveries.contains_key(&device),
            "{test_name}: no recovery attempt remains pending"
        );
        assert!(
            backend.resource_service.as_ref().is_some_and(|service| {
                service.device() == device
                    && service.incarnation() == new_incarnation
                    && service.allocation_end_state_for_tests().is_empty()
            }),
            "{test_name}: Task 3 installs a fresh empty resource service; pool creation is Task 4"
        );
        assert!(
            backend
                .drm_cleanup_registry
                .as_ref()
                .is_some_and(|registry| {
                    registry.device_key() == device && registry.incarnation() == new_incarnation
                })
        );

        let old_quarantine = backend
            .quarantined_normal_recoveries
            .iter()
            .find(|quarantine| quarantine.transition.incarnation == old_incarnation)
            .expect("the old incarnation remains in the transition quarantine");
        assert_eq!(
            old_quarantine
                .device
                .owner
                .as_ref()
                .map(|owner| owner.incarnation()),
            Some(old_incarnation)
        );
        assert!(old_quarantine.device.device.attached().is_none());
        assert_eq!(
            old_quarantine
                .device
                .incarnation_fd_set
                .borrow()
                .remaining_leases(),
            0,
            "{test_name}: no old-incarnation fd leases remain"
        );
        let old_registry = old_quarantine
            .cleanup_registry
            .as_ref()
            .expect("the old cleanup registry remains quarantined");
        assert_eq!(old_registry.incarnation(), old_incarnation);
        assert!(old_registry.is_family_closed());
        assert_eq!(
            old_registry.retained_native_file_object_count_for_tests(),
            0
        );
        assert_eq!(
            old_quarantine
                .resource_service
                .as_ref()
                .expect("the old resource service remains quarantined")
                .incarnation(),
            old_incarnation
        );
        let old_allocations = old_quarantine
            .resource_service
            .as_ref()
            .expect("the old resource service remains quarantined")
            .allocation_end_state_for_tests();
        assert!(
            old_allocations
                .iter()
                .all(|allocation| allocation.key.device == device
                    && allocation.key.incarnation == old_incarnation)
        );
        assert_eq!(
            old_quarantine
                .resource_service
                .as_ref()
                .expect("the old resource service remains quarantined")
                .file_owned_gbm_bo_count_for_tests(),
            0,
            "{test_name}: family closure released every old-incarnation GBM BO"
        );
        assert!(backend.platform.outputs.iter().any(|output| {
            output.key.device_key == device && output.key.connector_name == "HDMI-2"
        }));
    }

    fn c0_3di_urgent_withdrawal_count(backend: &super::KmsBackend, start: usize) -> usize {
        backend.core_entry_deliveries_for_tests[start..]
            .iter()
            .filter(|delivery| {
                matches!(
                    delivery,
                    yserver_core::core_loop::run::CoreEntryDelivery::UrgentWithdrawal { .. }
                )
            })
            .count()
    }

    type C0RecoveryFailureFixture = (
        super::KmsBackend,
        ServerState,
        DrmDeviceKey,
        IncarnationId,
        OutputKey,
        u32,
        u32,
        Rc<Cell<usize>>,
        Rc<RefCell<Vec<crate::kms::owner::lifecycle::RecoveryId>>>,
        usize,
    );

    fn c0_3di_failed_recovery_fixture(
        result: super::NormalRecoveryAttemptResult,
    ) -> C0RecoveryFailureFixture {
        use crate::kms::executor::test_support::StubBehaviour;
        use yserver_core::backend::Backend;

        let attempts = Rc::new(Cell::new(0));
        let recovery_ids = Rc::new(RefCell::new(Vec::new()));
        let attempts_for_runtime = Rc::clone(&attempts);
        let ids_for_runtime = Rc::clone(&recovery_ids);
        let runtime = Box::new(move |_, recovery_id, _| {
            attempts_for_runtime.set(attempts_for_runtime.get() + 1);
            ids_for_runtime.borrow_mut().push(recovery_id);
            result
        });
        let (mut backend, device, incarnation) =
            c0_3di_barrier_backend_with_attempt(StubBehaviour::NeverReply, runtime);
        let (output_key, output_id, crtc_id) = c0_3di_add_owner_output(&mut backend, device, 0x3d1);
        let mut state = ServerState::new();
        backend.rebuild_randr_state(&mut state, None, false);
        let (_poll, sender, _receiver) =
            yserver_core::core_loop::channel().expect("core wake channel");
        Backend::set_input_sender(&mut backend, sender);
        let delivery_start = backend.core_entry_deliveries_for_tests.len();
        c0_3di_drive_completion_loss_to_poison(
            &mut backend,
            &mut state,
            device,
            std::time::Duration::from_secs(8),
        );
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "finish the one NormalRecovery attempt",
            std::time::Duration::from_secs(8),
            &|backend| {
                backend
                    .lifecycle_coordinator
                    .device(&device)
                    .is_some_and(|arbiter| {
                        arbiter.state()
                            == crate::kms::owner::lifecycle::DeviceLifecycleState::RecoveryFailed
                    })
                    && c0_3di_urgent_withdrawal_count(backend, delivery_start) == 1
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));
        assert_eq!(attempts.get(), 1, "the incident is attempted once");
        assert_eq!(recovery_ids.borrow().len(), 1);
        assert!(backend.barrier_ready(incarnation));
        let registry = backend
            .drm_cleanup_registry
            .as_ref()
            .expect("old family registry");
        assert!(
            registry.is_family_closed(),
            "the old family remains quarantined closed"
        );
        assert_eq!(registry.incarnation(), incarnation);
        assert!(
            backend
                .resource_service
                .as_ref()
                .is_some_and(|service| service.incarnation() == incarnation)
        );
        (
            backend,
            state,
            device,
            incarnation,
            output_key,
            output_id,
            crtc_id,
            attempts,
            recovery_ids,
            delivery_start,
        )
    }

    #[test]
    fn c0_3di_poison_requests_termination_and_retires_the_family_vulkan() {
        use std::os::fd::{AsFd, AsRawFd};
        use yserver_core::backend::Backend;

        let (mut backend, device, incarnation) =
            c0_3di_barrier_backend(crate::kms::executor::test_support::StubBehaviour::NeverReply);
        let generation_before_detach = backend.platform.poll_source_generation();
        let raw_fd = backend.platform.devices[0]
            .device
            .attached()
            .expect("attached test DRM device")
            .as_fd()
            .as_raw_fd();
        let extra_device_ref = backend.platform.devices[0]
            .device
            .clone_rc()
            .expect("hold a device reference through control detach");
        let mut state = ServerState::new();
        c0_3di_drive_completion_loss_to_poison(
            &mut backend,
            &mut state,
            device,
            std::time::Duration::from_secs(8),
        );
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "reap helper and detach the control device",
            std::time::Duration::from_secs(5),
            &|backend| {
                backend.platform.helper_is_reaped(device)
                    && backend.platform.control_device_detached(device)
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));

        assert!(
            backend.platform.poll_source_generation() > generation_before_detach,
            "poison detach must advance the poll-source generation"
        );

        assert!(!backend.barrier_ready(incarnation));
        assert!(
            Backend::poll_fds(&backend)
                .iter()
                .all(|(fd, _)| *fd != raw_fd),
            "the detached device fd leaves poll_fds before the final owner closes it"
        );
        assert!(
            !backend
                .drm_cleanup_registry
                .as_ref()
                .unwrap()
                .is_family_closed(),
            "closing the control alias alone is not the family-closure proof"
        );
        drop(extra_device_ref);
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "close the final old-family reference and mint its proof",
            std::time::Duration::from_secs(5),
            &|backend| backend.barrier_ready(incarnation),
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));

        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .unwrap()
                .state(),
            crate::kms::owner::lifecycle::DeviceLifecycleState::RecoveryFailed
        );
        assert!(backend.platform.helper_is_reaped(device));
        assert_eq!(
            backend
                .platform
                .incarnation_fd_set(device)
                .unwrap()
                .borrow()
                .remaining_leases(),
            0
        );
        assert!(
            backend
                .drm_cleanup_registry
                .as_ref()
                .unwrap()
                .is_family_closed()
        );
        assert!(backend.barrier_ready(incarnation));
        assert!(
            !backend.pending_poisoned_barriers.contains(&device),
            "the completed barrier is not polled or minted again after the attempt"
        );
        let detached_caps = backend
            .platform
            .discover_completion_caps(device)
            .expect_err("detached devices refuse completion-capability discovery");
        assert_eq!(detached_caps.kind(), std::io::ErrorKind::NotConnected);
        c0_3di_assert_end_state(
            &backend,
            "c0_3di_poison_requests_termination_and_retires_the_family_vulkan",
        );
    }

    #[test]
    fn c0_3di_stuck_probe_worker_blocks_the_barrier_vulkan() {
        use std::{
            os::fd::{AsFd, AsRawFd},
            time::Duration,
        };

        let (mut backend, device, incarnation) =
            c0_3di_barrier_backend(crate::kms::executor::test_support::StubBehaviour::NeverReply);
        let mut state = ServerState::new();
        backend
            .platform
            .install_scripted_connector_prober_for_tests();
        let probe_barrier = crate::kms::render::platform::ProbeBarrier::new();
        backend.platform.script_blocked_connector_probe_for_tests(
            device,
            Ok(Vec::new()),
            probe_barrier.clone(),
        );
        let (_poll, sender, _receiver) =
            yserver_core::core_loop::channel().expect("core wake channel");
        yserver_core::backend::Backend::set_input_sender(&mut backend, sender);
        super::KmsBackend::record_display_hotplug_edge(&mut backend);
        backend.hotplug_rescan_deadline =
            Some(std::time::Instant::now() - Duration::from_millis(1));
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "start the blocked probe through the hotplug core entry",
            Duration::from_secs(3),
            &|backend| {
                backend.probe_workers.workers.contains_key(&device)
                    && probe_barrier.wait_started(Duration::ZERO)
            },
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));
        assert_eq!(
            backend
                .platform
                .incarnation_fd_set(device)
                .unwrap()
                .borrow()
                .remaining_leases(),
            2,
            "the real helper and blocked probe worker each hold an incarnation lease"
        );
        c0_3di_drive_completion_loss_to_poison(
            &mut backend,
            &mut state,
            device,
            Duration::from_secs(8),
        );
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "reap helper while the probe worker is held",
            Duration::from_secs(3),
            &|backend| backend.platform.helper_is_reaped(device),
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));
        assert!(backend.platform.helper_is_reaped(device));
        assert!(!backend.platform.control_device_detached(device));
        let drm_fd = backend.platform.devices[0]
            .device
            .attached()
            .expect("attached test DRM device")
            .as_fd()
            .as_raw_fd();
        assert!(
            yserver_core::backend::Backend::poll_fds(&backend)
                .iter()
                .all(|(fd, _)| *fd != drm_fd),
            "the event reader is detached while the device handle remains attached"
        );
        assert!(
            backend.probe_workers.workers.contains_key(&device),
            "the blocked probe worker remains live after helper reap"
        );
        assert!(!backend.barrier_ready(incarnation));
        assert!(
            !backend
                .drm_cleanup_registry
                .as_ref()
                .unwrap()
                .is_family_closed()
        );
        assert!(
            backend.scene_wants_compose(),
            "the fixture retains scene work while the test Owner is poisoned"
        );
        // The shared fixture's scene output is a synthetic Legacy output,
        // unrelated to the poisoned Owner key. Disable only that Legacy
        // fallback around the wakeup query so this assertion measures the
        // barrier's deadline, not legitimate scene work.
        let kms_outputs_active = backend.kms_outputs_active;
        backend.kms_outputs_active = false;
        let wakeup = yserver_core::backend::Backend::next_wakeup(&backend);
        let queried_at = std::time::Instant::now();
        backend.kms_outputs_active = kms_outputs_active;
        assert!(
            wakeup.is_none_or(|wakeup| wakeup > queried_at + Duration::from_millis(1)),
            "a stuck probe worker must not make the core poll the barrier every millisecond; wakeup={wakeup:?}"
        );

        probe_barrier.release();
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "join the probe and close the old fd family",
            Duration::from_secs(3),
            &|backend| backend.barrier_ready(incarnation),
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));
        assert!(!backend.probe_workers.workers.contains_key(&device));
        assert_eq!(
            backend
                .platform
                .incarnation_fd_set(device)
                .unwrap()
                .borrow()
                .remaining_leases(),
            0,
            "joining the probe worker releases its incarnation lease"
        );
        assert!(
            backend
                .drm_cleanup_registry
                .as_ref()
                .unwrap()
                .is_family_closed()
        );
        c0_3di_assert_end_state(
            &backend,
            "c0_3di_stuck_probe_worker_blocks_the_barrier_vulkan",
        );
    }

    #[test]
    fn c0_3di_unreaped_helper_blocks_the_barrier_vulkan() {
        use std::{
            os::fd::{AsFd, AsRawFd},
            time::Duration,
        };
        use yserver_core::backend::Backend;

        struct ResumeHelperOnDrop(libc::pid_t);

        impl Drop for ResumeHelperOnDrop {
            fn drop(&mut self) {
                // SAFETY: The PID is the helper child owned by this test
                // fixture. Resuming it lets any pending SIGTERM finish.
                unsafe {
                    libc::kill(self.0, libc::SIGCONT);
                }
            }
        }

        let (mut backend, device, incarnation) =
            c0_3di_barrier_backend(crate::kms::executor::test_support::StubBehaviour::NeverReply);
        let helper_pid = backend.platform.devices[0]
            .executor
            .as_ref()
            .expect("helper process")
            .child_pid();
        // SAFETY: SIGSTOP pauses this fixture's helper child so the core
        // driver's termination request cannot also reap it in the same turn.
        assert_eq!(unsafe { libc::kill(helper_pid, libc::SIGSTOP) }, 0);
        let _resume_on_drop = ResumeHelperOnDrop(helper_pid);
        let mut state = ServerState::new();
        c0_3di_drive_completion_loss_to_poison(
            &mut backend,
            &mut state,
            device,
            Duration::from_secs(8),
        );
        assert!(
            backend.platform.devices[0]
                .executor
                .as_ref()
                .unwrap()
                .termination_requested_for_tests()
        );
        assert!(backend.platform.devices[0].helper_lease.is_some());
        assert!(!backend.barrier_ready(incarnation));
        assert!(
            !backend
                .drm_cleanup_registry
                .as_ref()
                .unwrap()
                .is_family_closed(),
            "a termination request does not mint the family closure"
        );
        assert!(!backend.platform.control_device_detached(device));
        let drm_fd = backend.platform.devices[0]
            .device
            .attached()
            .expect("attached test DRM device")
            .as_fd()
            .as_raw_fd();
        assert!(
            yserver_core::backend::Backend::poll_fds(&backend)
                .iter()
                .all(|(fd, _)| *fd != drm_fd),
            "the event reader is detached while the helper lease keeps the device open"
        );
        assert!(
            Backend::poll_fds(&backend).iter().any(|(_, kind)| matches!(
                kind,
                yserver_core::backend::BackendFdKind::ExecutorControl
            )),
            "the helper control socket remains registered to wake the core on hangup"
        );
        // The shared fixture's scene output is a synthetic Legacy output,
        // unrelated to the poisoned Owner key. Isolate the helper barrier
        // deadline from legitimate Legacy scene work.
        let kms_outputs_active = backend.kms_outputs_active;
        backend.kms_outputs_active = false;
        let wakeup = Backend::next_wakeup(&backend);
        let queried_at = std::time::Instant::now();
        backend.kms_outputs_active = kms_outputs_active;
        assert!(
            wakeup.is_none_or(|wakeup| wakeup > queried_at + Duration::from_millis(1)),
            "an unreaped helper must not make the core poll the barrier every millisecond; wakeup={wakeup:?}"
        );

        // SAFETY: SIGCONT resumes only the fixture's helper child; the
        // pending SIGTERM then lets the core driver observe the real reap.
        assert_eq!(unsafe { libc::kill(helper_pid, libc::SIGCONT) }, 0);
        c0_3bi_core_driver_until_with_state(
            &mut backend,
            &mut state,
            "reap helper and close the old fd family",
            Duration::from_secs(3),
            &|backend| backend.barrier_ready(incarnation),
            None,
        )
        .unwrap_or_else(|error| panic!("{error}"));
        assert!(
            backend
                .drm_cleanup_registry
                .as_ref()
                .unwrap()
                .is_family_closed()
        );
        c0_3di_assert_end_state(&backend, "c0_3di_unreaped_helper_blocks_the_barrier_vulkan");
    }

    #[test]
    fn c0_3di_rec1_one_attempt_per_incident_vulkan() {
        use yserver_core::backend::Backend;

        let (
            mut backend,
            mut state,
            device,
            incarnation,
            output_key,
            output_id,
            crtc_id,
            attempts,
            recovery_ids,
            delivery_start,
        ) = c0_3di_failed_recovery_fixture(super::NormalRecoveryAttemptResult::CompletionUnknown);
        let recovery_id = recovery_ids.borrow()[0];
        assert_eq!(
            backend
                .lifecycle_coordinator
                .device(&device)
                .and_then(|arbiter| arbiter.recovery())
                .map(|incident| incident.id()),
            Some(recovery_id),
            "completion unknown fails the incident that was started"
        );
        c0_3bi_assert_one_urgent_withdrawal_delivered(
            &backend,
            &state,
            delivery_start,
            output_id,
            crtc_id,
            "unknown completion during NormalRecovery",
        );

        assert!(backend.lifecycle_set_dpms_power(3).expect("DPMS off"));
        assert!(backend.lifecycle_set_dpms_power(0).expect("DPMS on"));
        assert!(
            backend
                .lifecycle_set_dpms_power(2)
                .expect("second DPMS off")
        );
        assert!(backend.lifecycle_set_dpms_power(0).expect("second DPMS on"));
        assert!(
            Backend::begin_crtc_config(
                &mut backend,
                output_id,
                &output_key.connector_name,
                None,
                0,
                0,
            )
            .is_err(),
            "a client modeset is refused against the failed, withdrawn device"
        );

        let next_wakeups_before = backend
            .core_entry_trace_for_tests
            .borrow()
            .iter()
            .filter(|entry| **entry == "next_wakeup")
            .count();
        for _ in 0..12 {
            backend
                .core_driver_owner_events_for_tests
                .push_back((device, Vec::new()));
            c0_3bi_core_driver_until_with_state(
                &mut backend,
                &mut state,
                "drive post-failure next_wakeup without a retry",
                std::time::Duration::from_secs(1),
                &|backend| backend.core_driver_owner_events_for_tests.is_empty(),
                None,
            )
            .unwrap_or_else(|error| panic!("{error}"));
        }
        let next_wakeups_after = backend
            .core_entry_trace_for_tests
            .borrow()
            .iter()
            .filter(|entry| **entry == "next_wakeup")
            .count();
        assert!(next_wakeups_after >= next_wakeups_before + 12);
        assert_eq!(
            attempts.get(),
            1,
            "DPMS, client work and wakeups do not retry"
        );
        assert_eq!(recovery_ids.borrow().as_slice(), [recovery_id]);
        let arbiter = backend
            .lifecycle_coordinator
            .device(&device)
            .expect("Owner arbiter remains registered");
        assert_eq!(
            arbiter.state(),
            crate::kms::owner::lifecycle::DeviceLifecycleState::RecoveryFailed
        );
        assert_eq!(
            arbiter.recovery().map(|incident| incident.id()),
            Some(recovery_id)
        );
        assert!(!arbiter.admission_open());
        assert!(backend.barrier_ready(incarnation));
        c0_3di_assert_end_state(&backend, "c0_3di_rec1_one_attempt_per_incident_vulkan");
    }

